            * { box-sizing: border-box; }
            body {
                margin: 0;
                font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
                background: radial-gradient(circle at top, #152034, var(--bg));
                color: var(--ink);
                min-height: 100vh;
            }
            header {
                padding: 20px 24px;
                border-bottom: 1px solid rgba(255,255,255,0.08);
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 16px;
            }
            .header-title {
                display: inline-flex;
                align-items: center;
                gap: 12px;
                flex-wrap: wrap;
            }
            .header-history {
                display: inline-flex;
                align-items: center;
                gap: 6px;
            }
            .header-icon-btn {
                width: 32px;
                height: 32px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                background: var(--panel);
                border: 1px solid rgba(255,255,255,0.2);
                color: var(--ink);
                cursor: pointer;
                font-size: 16px;
                font-weight: 700;
                border-radius: 0;
            }
            .tab-nav {
                display: flex;
                gap: 8px;
                padding: 0 24px;
                background: var(--panel);
                border-bottom: 1px solid rgba(255,255,255,0.08);
            }
            .tab-nav button {
                padding: 12px 20px;
                background: transparent;
                border: none;
                color: var(--muted);
                cursor: pointer;
                font-weight: 600;
                border-bottom: 3px solid transparent;
                transition: all 0.2s;
            }
            .tab-nav button:hover {
                color: var(--ink);
                background: rgba(255,255,255,0.05);
            }
            .tab-nav button.active {
                color: var(--accent);
                border-bottom-color: var(--accent);
            }
            #mode-edit-text.active {
                background: var(--accent) !important;
                color: #0b2d20 !important;
                border-color: rgba(16, 185, 129, 0.8) !important;
            }
            .tab-content {
                display: none;
            }
            .tab-content.active {
                display: block;
            }
            .pdf-editor-layout {
                min-height: calc(100vh - var(--pdf-sticky-top, 178px));
            }
            #pdf-mode-bar,
            #selection-toolbar {
                top: var(--pdf-sticky-top, 178px);
            }
            @media (min-width: 1024px) {
                #sidebar {
                    top: var(--pdf-sticky-top, 178px);
                    height: calc(100vh - var(--pdf-sticky-top, 178px));
                }
            }
            #guided-invoice {
                overflow-y: auto;
                background: #f3f4f6;
            }
            #pdf-editor {
                position: relative;
            }
            header a {
                color: var(--muted);
                text-decoration: none;
            }
            .top-actions {
                display: inline-flex;
                align-items: center;
                gap: 12px;
            }
            #theme-toggle {
                background: var(--panel);
                border: 1px solid rgba(255,255,255,0.1);
                color: var(--ink);
                padding: 8px 12px;
                border-radius: 6px;
                cursor: pointer;
                font-size: 18px;
                transition: all 0.2s;
            }
            #theme-toggle:hover {
                background: var(--accent-dark);
                border-color: var(--accent);
            }
            .floating-zoom-bar {
                position: fixed;
                left: 50%;
                bottom: 18px;
                transform: translateX(-50%);
                display: inline-flex;
                align-items: center;
                gap: 10px;
                padding: 8px 12px;
                background: rgba(32, 36, 45, 0.95);
                border: 1px solid rgba(255,255,255,0.12);
                border-radius: 10px;
                color: #e5e7eb;
                z-index: 9999;
                box-shadow: 0 12px 30px rgba(0,0,0,0.35);
                font-size: 14px;
            }
            .floating-zoom-bar .divider {
                width: 1px;
                height: 20px;
                background: rgba(255,255,255,0.2);
            }
            .floating-zoom-bar button {
                border: none;
                background: rgba(255,255,255,0.08);
                color: #f3f4f6;
                width: 28px;
                height: 28px;
                border-radius: 6px;
                cursor: pointer;
                font-size: 16px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
            }
            .floating-zoom-bar button:hover {
                background: rgba(255,255,255,0.16);
            }
            .floating-zoom-bar input[type="number"] {
                width: 54px;
                background: rgba(255,255,255,0.1);
                border: 1px solid rgba(255,255,255,0.2);
                color: #f3f4f6;
                padding: 4px 6px;
                border-radius: 6px;
                text-align: center;
                font-size: 14px;
            }
            .floating-zoom-bar .zoom-label {
                min-width: 48px;
                text-align: center;
                font-weight: 600;
            }
            .mode-btn {
                border: 1px solid rgba(255,255,255,0.2);
                background: transparent;
                color: var(--ink);
                padding: 8px 14px;
                border-radius: 999px;
                cursor: pointer;
                font-weight: 600;
            }
            .mode-btn.active {
                background: var(--accent);
                color: #0b2d20;
                border-color: transparent;
            }
            .layout {
                display: grid;
                grid-template-columns: 320px 1fr;
                min-height: calc(100vh - 114px);
            }
            #extracted-text .layout {
                display: flex;
                height: calc(100vh - 100px);
                overflow: hidden;
            }
            #extracted-text .viewer-wrap {
                margin-left: 0;
                flex: 1;
                display: flex;
                flex-direction: column;
                height: 100%;
                overflow: hidden;
            }
            #extracted-text .viewer-wrap .viewer {
                flex: 1;
                overflow-y: auto;
            }
            .extracted-text-view {
                background: white;
                height: calc(100vh - 114px);
                overflow: auto;
                padding: 40px;
            }
            
            /* AI Chat Sidebar */
            .ai-chat-sidebar {
                width: 400px;
                background: #1f2937;
                border-right: 1px solid #374151;
                display: flex;
                flex-direction: column;
                height: 100%;
            }
            .ai-chat-header {
                padding: 16px 20px;
                border-bottom: 1px solid #374151;
                font-weight: 600;
                color: white;
                font-size: 16px;
            }
            .ai-chat-messages {
                flex: 1;
                overflow-y: auto;
                padding: 20px;
                display: flex;
                flex-direction: column;
                gap: 16px;
            }
            .ai-chat-message {
                display: flex;
                flex-direction: column;
                gap: 8px;
                animation: slideIn 0.3s ease-out;
            }
            @keyframes slideIn {
                from {
                    opacity: 0;
                    transform: translateY(10px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
            .ai-chat-message.user {
                align-items: flex-end;
            }
            .ai-chat-message.bot {
                align-items: flex-start;
            }
            .ai-message-bubble {
                max-width: 85%;
                padding: 12px 16px;
                border-radius: 12px;
                word-wrap: break-word;
                line-height: 1.5;
            }
            .ai-chat-message.user .ai-message-bubble {
                background: #3b82f6;
                color: white;
                border-bottom-right-radius: 4px;
            }
            .ai-chat-message.bot .ai-message-bubble {
                background: #dbeafe;
                color: #1e40af;
                border-bottom-left-radius: 4px;
            }
            .ai-message-copy {
                display: flex;
                align-items: center;
                gap: 6px;
                font-size: 13px;
                color: #9ca3af;
                cursor: pointer;
                padding: 4px 8px;
                border-radius: 4px;
                transition: all 0.2s;
            }
            .ai-message-copy:hover {
                color: #6b7280;
                background: #374151;
            }
            .ai-chat-input-area {
                padding: 16px 20px;
                border-top: 1px solid #374151;
            }
            .ai-chat-input-wrapper {
                display: flex;
                gap: 12px;
                align-items: flex-end;
            }
            .ai-chat-input-container {
                flex: 1;
                display: flex;
                flex-direction: column;
                gap: 8px;
            }
            .ai-chat-textarea {
                width: 100%;
                background: #374151;
                border: 1px solid #4b5563;
                border-radius: 8px;
                padding: 12px;
                color: white;
                resize: none;
                font-size: 14px;
                min-height: 44px;
                max-height: 120px;
                outline: none;
                transition: border-color 0.2s;
            }
            .ai-chat-textarea:focus {
                border-color: #3b82f6;
            }
            .ai-chat-textarea::placeholder {
                color: #9ca3af;
            }
            .ai-attach-btn {
                display: flex;
                align-items: center;
                gap: 6px;
                padding: 8px 12px;
                background: transparent;
                border: none;
                color: #9ca3af;
                cursor: pointer;
                border-radius: 6px;
                font-size: 14px;
                transition: all 0.2s;
            }
            .ai-attach-btn:hover {
                color: #d1d5db;
                background: #374151;
            }
            .ai-send-btn {
                width: 40px;
                height: 40px;
                background: #1e293b;
                border: none;
                border-radius: 8px;
                display: flex;
                align-items: center;
                justify-content: center;
                cursor: pointer;
                transition: all 0.2s;
                flex-shrink: 0;
            }
            .ai-send-btn:hover {
                background: #334155;
            }
            .ai-send-btn:active {
                transform: scale(0.95);
            }
            .ai-send-btn svg {
                width: 20px;
                height: 20px;
                color: white;
            }
            
            /* Request History Panel */
            .ai-request-history-panel {
                border-top: 1px solid rgba(255,255,255,0.1);
                background: rgba(0,0,0,0.2);
            }
            .history-header {
                padding: 12px 16px;
                display: flex;
                justify-content: space-between;
                align-items: center;
                cursor: pointer;
                transition: background 0.2s;
                font-weight: 600;
                font-size: 14px;
                color: #e5e7eb;
            }
            .history-header:hover {
                background: rgba(255,255,255,0.05);
            }
            .history-toggle {
                background: none;
                border: none;
                padding: 4px;
                cursor: pointer;
                color: #9ca3af;
                display: flex;
                align-items: center;
                justify-content: center;
                transition: transform 0.2s;
            }
            .history-toggle.open {
                transform: rotate(180deg);
            }
            .history-content {
                max-height: 300px;
                overflow-y: auto;
            }
            .history-list {
                padding: 8px;
            }
            .history-item {
                background: rgba(255,255,255,0.05);
                border: 1px solid rgba(255,255,255,0.1);
                border-radius: 6px;
                padding: 12px;
                margin-bottom: 8px;
                font-size: 12px;
            }
            .history-item-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 8px;
            }
            .history-item-cost {
                font-weight: 700;
                color: #60a5fa;
                font-size: 14px;
            }
            .history-item-date {
                color: #9ca3af;
                font-size: 11px;
            }
            .history-item-prompt {
                color: #d1d5db;
                margin-bottom: 8px;
                line-height: 1.4;
            }
            .history-item-stats {
                display: flex;
                gap: 12px;
                padding-top: 8px;
                border-top: 1px solid rgba(255,255,255,0.1);
                color: #9ca3af;
            }
            .history-item-stat {
                display: flex;
                align-items: center;
                gap: 4px;
            }
            
            /* Light theme support for chat */
            body.light-theme .ai-chat-sidebar {
                background: #f9fafb;
                border-right: 1px solid #e5e7eb;
            }
            body.light-theme .ai-chat-header {
                color: #111827;
                border-bottom: 1px solid #e5e7eb;
            }
            body.light-theme .ai-chat-message.bot .ai-message-bubble {
                background: #dbeafe;
                color: #1e40af;
            }
            body.light-theme .ai-chat-textarea {
                background: white;
                border: 1px solid #d1d5db;
                color: #111827;
            }
            body.light-theme .ai-chat-textarea:focus {
                border-color: #3b82f6;
            }
            body.light-theme .ai-chat-input-area {
                border-top: 1px solid #e5e7eb;
            }
            body.light-theme .ai-send-btn {
                background: #1e293b;
            }
            body.light-theme .ai-send-btn:hover {
                background: #334155;
            }
            body.light-theme .ai-message-copy:hover {
                background: #f3f4f6;
            }
            .extraction-page {
                position: relative;
                background: white;
                min-height: 1000px;
                padding: 60px 80px;
                margin-bottom: 40px;
                border: 1px solid #e0e0e0;
                box-shadow: 0 2px 8px rgba(0,0,0,0.1);
            }
            .extraction-page-header {
                text-align: center;
                padding: 15px;
                background: #f5f5f5;
                color: #666;
                font-size: 13px;
                font-weight: 600;
                margin: -60px -80px 40px;
            }
            .text-span {
                position: absolute;
                white-space: pre;
                cursor: text;
                padding: 2px;
                border: 1px dashed transparent;
                transition: all 0.15s;
                color: #000000;
            }
            .text-span:hover {
                background: rgba(66, 133, 244, 0.15);
                border-color: rgba(66, 133, 244, 0.4);
            }
            .text-span.editing {
                background: white;
                border: 2px solid #4285f4;
                outline: none;
                z-index: 100;
            }
            .text-span.modified {
                background: rgba(76, 175, 80, 0.2);
                border-color: #4caf50;
            }
            .extracted-loading {
                text-align: center;
                padding: 100px;
                font-size: 18px;
                color: var(--muted);
            }
            .sidebar {
                background: var(--panel);
                padding: 20px;
                border-right: 1px solid rgba(255,255,255,0.08);
                height: calc(100vh - 114px);
                overflow-y: auto;
            }
            .sidebar h2 {
                margin: 0 0 12px;
                font-size: 18px;
                display: flex;
                align-items: center;
                justify-content: space-between;
            }
            .sidebar h2 .gear-icon {
                cursor: pointer;
                font-size: 18px;
                color: var(--muted);
                transition: color 0.2s, transform 0.2s;
            }
            .sidebar h2 .gear-icon:hover {
                color: var(--accent);
                transform: rotate(30deg);
            }
            .sidebar label {
                display: block;
                margin-top: 16px;
                color: var(--muted);
                font-size: 13px;
            }
            .sidebar input, .sidebar textarea, .sidebar select {
                width: 100%;
                margin-top: 6px;
                background: #0c1220;
                border: 1px solid rgba(255,255,255,0.12);
                color: var(--ink);
                padding: 10px;
                border-radius: 10px;
            }
            .sidebar button {
                width: 100%;
                margin-top: 16px;
                border: none;
                padding: 12px;
                border-radius: 999px;
                font-weight: 700;
                cursor: pointer;
            }
            .primary {
                background: var(--accent);
                color: #0b2d20;
            }
            .ghost {
                background: transparent;
                color: var(--muted);
                border: 1px solid rgba(255,255,255,0.2);
            }
            .status {
                margin-top: 12px;
                font-size: 13px;
                color: var(--muted);
            }
            .status.ok { color: var(--accent); }
            .status.err { color: var(--danger); }
            .page-list {
                display: grid;
                gap: 18px;
                margin-top: 12px;
                padding-bottom: 12px;
            }
            .page-thumb {
                display: grid;
                justify-items: center;
                gap: 8px;
                padding: 10px 8px 12px;
                background: rgba(255,255,255,0.04);
                border-radius: 12px;
                border: 1px solid rgba(255,255,255,0.06);
                cursor: pointer;
                transition: transform 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
            }
            .page-thumb canvas {
                width: 160px;
                height: auto;
                border-radius: 6px;
                background: #fff;
                box-shadow: 0 8px 18px rgba(0,0,0,0.35);
            }
            .page-thumb span {
                font-size: 12px;
                color: var(--muted);
            }
            .page-thumb.active {
                border-color: var(--accent);
                box-shadow: 0 0 0 2px rgba(77, 208, 168, 0.2);
                transform: translateY(-2px);
            }
            .viewer-wrap {
                display: flex;
                flex-direction: column;
                min-height: calc(100vh - 64px);
            }
            .sticky-tools {
                position: sticky;
                top: 0;
                z-index: 120000;
                background: linear-gradient(180deg, rgba(7,11,18,0.98), rgba(7,11,18,0.92));
                border-bottom: 1px solid rgba(255,255,255,0.08);
                backdrop-filter: blur(6px);
                isolation: isolate;
            }
            .sticky-tools .mode-bar,
            .sticky-tools .toolbar {
                margin: 0;
                border-radius: 0;
                position: relative;
                z-index: 120001;
            }
            .toolbar {
                display: flex;
                flex-wrap: wrap;
                gap: 12px;
                align-items: center;
                padding: 14px 20px;
                border-bottom: 1px solid rgba(255,255,255,0.08);
                background: rgba(16, 24, 36, 0.9);
            }
            .toolbar .label {
                color: var(--muted);
                font-size: 13px;
            }
            .toolbar-controls {
                display: flex;
                flex-wrap: wrap;
                gap: 10px;
                align-items: center;
            }
            .toolbar select,
            .toolbar input[type="number"] {
                background: #0c1220;
                border: 1px solid rgba(255,255,255,0.12);
                color: var(--ink);
                border-radius: 8px;
                padding: 6px 8px;
            }
            .toolbar button {
                border: none;
                padding: 8px 12px;
                border-radius: 0;
                cursor: pointer;
                font-weight: 700;
            }
            .toolbar button.icon-btn {
                width: 32px;
                height: 32px;
                padding: 0;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 18px;
                font-weight: normal;
            }
            .toolbar .pill {
                background: rgba(110,231,183,0.16);
                color: var(--ink);
                border: 1px solid rgba(110,231,183,0.4);
            }
            .toolbar .pill-active {
                background: var(--accent);
                color: #0b2d20;
                border-color: var(--accent);
            }
            .toolbar .danger {
                background: #ff6b6b;
                color: white;
            }
            .toolbar .disabled {
                opacity: 0.5;
                pointer-events: none;
            }
            .selection-toolbar {
                display: flex;
                align-items: center;
                gap: 6px;
                flex-wrap: wrap;
                width: 100%;
                position: relative;
                z-index: 120002 !important;
            }
            .selection-toolbar .toolbar-label {
                font-size: 12px;
                font-weight: 500;
                color: #94a3b8;
                white-space: nowrap;
                margin-right: 4px;
                letter-spacing: 0.01em;
            }
            .selection-toolbar .toolbar-controls {
                display: flex;
                align-items: center;
                gap: 4px;
                flex-wrap: wrap;
            }
            .selection-toolbar .toolbar-controls.disabled {
                opacity: 0.35;
                pointer-events: none;
            }
            .selection-toolbar .tb-divider {
                width: 1px;
                height: 24px;
                background: rgba(255, 255, 255, 0.1);
                margin: 0 4px;
            }
            .selection-toolbar .tb-group {
                display: inline-flex;
                align-items: center;
                gap: 3px;
            }
            .selection-toolbar select,
            .selection-toolbar input[type="number"] {
                background: rgba(255, 255, 255, 0.07);
                border: 1px solid rgba(255, 255, 255, 0.12);
                color: #e2e8f0;
                border-radius: 6px;
                padding: 5px 8px;
                font-size: 12px;
                min-width: 56px;
                outline: none;
                transition: border-color 0.15s, background 0.15s;
            }
            .selection-toolbar select:hover,
            .selection-toolbar input[type="number"]:hover {
                background: rgba(255, 255, 255, 0.1);
                border-color: rgba(255, 255, 255, 0.2);
            }
            .selection-toolbar select:focus,
            .selection-toolbar input[type="number"]:focus {
                border-color: #3b82f6;
                background: rgba(255, 255, 255, 0.1);
            }
            .selection-toolbar select option {
                background: #1e293b;
                color: #e2e8f0;
            }
            .selection-toolbar .icon-btn {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                width: 32px;
                height: 32px;
                background: rgba(255, 255, 255, 0.05);
                color: #cbd5e1;
                border: 1px solid rgba(255, 255, 255, 0.1);
                border-radius: 6px;
                font-size: 13px;
                cursor: pointer;
                transition: all 0.15s;
            }
            .selection-toolbar .icon-btn:hover {
                background: rgba(255, 255, 255, 0.12);
                color: #f1f5f9;
                border-color: rgba(255, 255, 255, 0.2);
            }
            .selection-toolbar .icon-btn.active,
            .selection-toolbar .icon-btn[aria-pressed="true"] {
                background: linear-gradient(180deg, #2563eb 0%, #1d4ed8 100%);
                color: #ffffff;
                border-color: rgba(191, 219, 254, 0.95);
                box-shadow: 0 0 0 1px rgba(147, 197, 253, 0.38), inset 0 -1px 0 rgba(15, 23, 42, 0.28);
                transform: translateY(-1px);
            }
            .selection-toolbar .icon-btn:disabled {
                opacity: 0.3;
                cursor: default;
            }
            .selection-toolbar .color-btn {
                display: inline-flex;
                align-items: center;
                gap: 4px;
                cursor: pointer;
            }
            .selection-toolbar .color-swatch {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                width: 28px;
                height: 28px;
                border-radius: 6px;
                border: 1px solid rgba(255, 255, 255, 0.12);
                overflow: hidden;
                position: relative;
                cursor: pointer;
            }
            .selection-toolbar .color-swatch input[type="color"] {
                position: absolute;
                width: 200%;
                height: 200%;
                top: -50%;
                left: -50%;
                border: none;
                background: none;
                cursor: pointer;
            }
            .selection-toolbar .danger-btn {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                height: 32px;
                padding: 0 12px;
                background: rgba(239, 68, 68, 0.1);
                color: #f87171;
                border: 1px solid rgba(239, 68, 68, 0.2);
                border-radius: 6px;
                font-size: 12px;
                font-weight: 600;
                cursor: pointer;
                transition: all 0.15s;
            }
            .selection-toolbar .danger-btn:hover {
                background: rgba(239, 68, 68, 0.2);
                border-color: rgba(239, 68, 68, 0.4);
            }
            .selection-toolbar .danger-btn:disabled {
                opacity: 0.3;
                cursor: default;
            }
            .mode-bar {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 10px 20px;
                border-bottom: 1px solid rgba(255,255,255,0.08);
                background: rgba(12, 20, 32, 0.95);
                flex-wrap: wrap;
            }
            .mode-bar .mode-spacer {
                flex: 1 1 auto;
            }
            .mode-bar .divider {
                width: 1px;
                height: 24px;
                background: rgba(255,255,255,0.12);
            }
            .mode-bar button {
                border: none;
                padding: 8px 14px;
                border-radius: 0;
                cursor: pointer;
                background: #1a2636;
                color: var(--ink);
                font-weight: 600;
                display: inline-flex;
                align-items: center;
                gap: 8px;
            }
            .mode-bar button.primary {
                background: var(--accent);
                color: #0b2d20;
            }
            .mode-bar button.ghost {
                background: transparent;
                color: var(--muted);
                border: 1px solid rgba(255,255,255,0.2);
            }
            .mode-bar button.active {
                background: var(--accent);
                color: #0b2d20;
            }
            .mode-bar.overlay-active {
                border-bottom: 1px solid rgba(16, 185, 129, 0.45);
                box-shadow: inset 0 -2px 0 rgba(16, 185, 129, 0.35);
            }
            .mode-overlay-chip {
                border: 1px solid rgba(255, 255, 255, 0.16);
                transition: all 0.2s ease;
            }
            .mode-overlay-chip.overlay-active {
                background: linear-gradient(135deg, rgba(16, 185, 129, 0.28), rgba(6, 95, 70, 0.35)) !important;
                border-color: rgba(16, 185, 129, 0.8) !important;
                box-shadow: 0 0 0 1px rgba(16, 185, 129, 0.45), 0 0 18px rgba(16, 185, 129, 0.28);
            }
            .overlay-state-indicator {
                display: none;
                margin-top: 10px;
                padding: 10px 12px;
                border-radius: 10px;
                font-size: 13px;
                font-weight: 600;
                color: #d1fae5;
                background: linear-gradient(135deg, rgba(16, 185, 129, 0.16), rgba(6, 78, 59, 0.38));
                border: 1px solid rgba(16, 185, 129, 0.45);
            }
            .overlay-state-indicator.active {
                display: block;
            }
            .overlay-tool-disabled {
                opacity: 0.35 !important;
                filter: grayscale(0.65);
                cursor: not-allowed !important;
                pointer-events: none !important;
            }
            .overlay-tool-disabled * {
                pointer-events: none !important;
            }
            .mode-bar .icon {
                font-weight: 800;
                font-size: 16px;
            }
            .toggle-switch {
                display: inline-flex;
                align-items: center;
                gap: 10px;
                padding: 6px 10px;
                border: 1px solid rgba(255,255,255,0.2);
                background: #1a2636;
                color: var(--ink);
                font-weight: 600;
                border-radius: 0;
                cursor: pointer;
                user-select: none;
            }
            .toggle-switch input {
                display: none;
            }
            .toggle-switch .slider {
                position: relative;
                width: 36px;
                height: 18px;
                background: rgba(255,255,255,0.2);
                border: 1px solid rgba(255,255,255,0.3);
                border-radius: 0;
                transition: all 0.2s;
                flex-shrink: 0;
            }
            .toggle-switch .slider::after {
                content: '';
                position: absolute;
                top: 1px;
                left: 1px;
                width: 14px;
                height: 14px;
                background: #ffffff;
                transition: all 0.2s;
                border-radius: 0;
            }
            .toggle-switch input:checked + .slider {
                background: var(--accent);
                border-color: var(--accent);
            }
            .toggle-switch input:checked + .slider::after {
                left: 19px;
                background: #0b2d20;
            }
            .viewer {
                padding: 24px;
                overflow: visible;
                flex: 1;
            }
            #ai-viewer {
                overflow: visible;
            }
            .viewer-footer {
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 16px;
                padding: 16px 24px 28px;
                color: var(--muted);
            }
            .viewer-footer button {
                border: 1px solid rgba(255,255,255,0.2);
                background: transparent;
                color: var(--ink);
                padding: 8px 16px;
                border-radius: 0;
                cursor: pointer;
                font-weight: 600;
            }
            .viewer-footer button[disabled] {
                opacity: 0.6;
                cursor: not-allowed;
            }
            /* Edit text mode info banner */
            .edit-text-banner {
                display: flex;
                align-items: center;
                gap: 6px;
                flex-wrap: nowrap;
                position: sticky;
                top: 0;
                z-index: 120;
                background: rgba(17, 24, 39, 0.97);
                border-bottom: 1px solid rgba(255,255,255,0.08);
                padding: 6px 12px;
                min-height: 56px;
                color: #e5e7eb;
                font-size: 13px;
                backdrop-filter: blur(12px);
                overflow-x: auto;
                overflow-y: hidden;
                box-shadow: 0 10px 24px rgba(0,0,0,0.22);
            }
            body.light-theme .edit-text-banner {
