                padding: 4px 8px;
                font-family: inherit;
                box-sizing: border-box;
                white-space: pre-wrap;
                overflow-wrap: break-word;
                word-break: break-word;
                user-select: text;
                cursor: text;
            }
            .text-box-creator.promoted-inline-editor .tbc-input {
                min-height: 100%;
                height: 100%;
                padding: 0;
                background: transparent;
                box-sizing: border-box;
            }
            .text-box-creator.inline-annotation-editor .tbc-input {
                min-height: 100%;
                height: 100%;
                background: transparent;
                box-sizing: border-box;
            }
            .text-box-creator .tbc-native-input {
                position: absolute;
                inset: 0;
                width: 100%;
                height: 100%;
                border: none;
                padding: 0;
                margin: 0;
                resize: none;
                opacity: 0;
                background: transparent;
                color: transparent;
                pointer-events: none;
                touch-action: none;
                font: inherit;
                line-height: inherit;
                white-space: pre-wrap;
                overflow: hidden;
                overflow-wrap: break-word;
                word-break: break-word;
            }
            .text-box-creator .tbc-input:empty::before {
                content: attr(data-placeholder);
                color: #9ca3af;
                pointer-events: none;
            }
            .text-box-creator .tbc-menu {
                position: absolute;
