            .acroform-preview-field.acroform-preview-btn.is-choice .acroform-preview-check {
                border-radius: 999px;
            }
            .acroform-preview-control {
                position: absolute;
                inset: 0;
                width: 100%;
                height: 100%;
                box-sizing: border-box;
                border: none;
                outline: none;
                background: transparent;
                color: inherit;
                font: inherit;
                line-height: 1.05;
                padding: 1px 4px;
                margin: 0;
                resize: none;
                appearance: none;
                -webkit-appearance: none;
                border-radius: inherit;
