            function getPromotedAnnotationMetaKey(annotationLike) {
                if (!annotationLike || typeof annotationLike !== 'object') {
                    return '';
                }

                const annotationId = String(annotationLike.id || '').trim();
                if (annotationId !== '') {
                    return `id:${annotationId}`;
                }

                const sourceKey = String(annotationLike.promotedSourceKey || '').trim();
                if (sourceKey !== '') {
                    return `source:${sourceKey}`;
                }

                return '';
            }

            function sanitizePromotedAnnotationSourceMeta(meta) {
                if (!meta || typeof meta !== 'object') {
                    return null;
                }

                const sourceLineBBoxes = Array.isArray(meta.sourceLineBBoxes)
                    ? meta.sourceLineBBoxes
                        .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        .map((bbox) => bbox.map((value) => Number(value) || 0))
                    : [];

                const sourceTextLines = Array.isArray(meta.sourceTextLines)
                    ? meta.sourceTextLines
                        .map((line) => sanitizePromotedExtractionLine(line))
                        .filter((line, index, lines) => !(line && index > 0 && lines[index - 1] === line))
                    : [];

                const sourceSpans = Array.isArray(meta.sourceSpans)
                    ? meta.sourceSpans
                        .filter((span) => span && Array.isArray(span.bbox) && span.bbox.length >= 4)
                        .map((span) => ({
                            text: sanitizePromotedExtractionLine(span.text ?? ''),
                            rawText: String(span.rawText ?? span.text ?? '').replace(/\u00A0/g, ' '),
                            font: String(span.font ?? span.embedded_font_name ?? span.embedded_font_family ?? '').trim(),
                            embedded_font_name: String(span.embedded_font_name ?? '').trim(),
                            embedded_font_family: String(span.embedded_font_family ?? '').trim(),
                            fontSize: Number(span.fontSize ?? span.font_size) || 0,
                            fontWeight: String(span.fontWeight ?? span.font_weight ?? '400'),
                            fontStyle: String(span.fontStyle ?? (span.italic ? 'italic' : null) ?? 'normal'),
                            underline: Boolean(span.underline),
                            hasDrawnUnderline: Boolean(span.hasDrawnUnderline),
                            suppressDrawnUnderline: Boolean(span.suppressDrawnUnderline),
                            color: String(span.color ?? '').trim(),
                            origin: Array.isArray(span.origin) && span.origin.length >= 2
                                ? [Number(span.origin[0]) || 0, Number(span.origin[1]) || 0]
                                : null,
                            direction: Array.isArray(span.direction) && span.direction.length >= 2
                                ? [Number(span.direction[0]) || 0, Number(span.direction[1]) || 0]
                                : null,
                            writing_mode: Number(span.writing_mode ?? span.writingMode ?? 0) || 0,
                            rotation: Number(span.rotation ?? span.rotation_degrees ?? 0) || 0,
                            bbox: span.bbox.map((value) => Number(value) || 0),
                        }))
                        .reduce((deduped, span) => {
                            const duplicateIndex = deduped.findIndex((kept) => {
                                return promotedSourceSpansLookDuplicate(kept, span);
                            });

                            if (duplicateIndex === -1) {
                                deduped.push(span);
                                return deduped;
                            }

                            const kept = deduped[duplicateIndex];
                            const mergedText = normalizePromotedDuplicateText(kept.text, span.text);
                            if (mergedText) {
                                kept.text = mergedText;
                            }
                            if (!kept.rawText && span.rawText) {
                                kept.rawText = span.rawText;
                            }
                            if (!kept.font && span.font) {
                                kept.font = span.font;
                            }
                            if (!(kept.fontSize > 0) && span.fontSize > 0) {
                                kept.fontSize = span.fontSize;
                            }
                            return deduped;
                        }, [])
                    : [];

                return {
                    sourceBlockLeft: Number(meta.sourceBlockLeft) || 0,
                    sourceBlockTop: Number(meta.sourceBlockTop) || 0,
                    sourceBlockWidth: Number(meta.sourceBlockWidth) || 0,
                    sourceBlockHeight: Number(meta.sourceBlockHeight) || 0,
                    sourcePageHeight: Number(meta.sourcePageHeight) || 0,
                    sourceTextLines,
                    sourceLineBBoxes,
                    sourceSpans,
                };
            }

            function setPromotedAnnotationSourceMeta(annotationLike, meta) {
                const key = getPromotedAnnotationMetaKey(annotationLike);
                if (!key) {
                    return null;
                }

                const sanitized = sanitizePromotedAnnotationSourceMeta(meta);
                if (!sanitized) {
                    promotedAnnotationSourceMeta.delete(key);
                    return null;
                }

                promotedAnnotationSourceMeta.set(key, sanitized);
                return sanitized;
            }

            function getPromotedAnnotationSourceMeta(annotationLike) {
                const key = getPromotedAnnotationMetaKey(annotationLike);
                if (!key) {
                    return null;
                }

                return promotedAnnotationSourceMeta.get(key) || null;
            }

            function clearPromotedAnnotationSourceMeta(annotationLike) {
                const key = getPromotedAnnotationMetaKey(annotationLike);
                if (!key) {
                    return;
                }

                promotedAnnotationSourceMeta.delete(key);
            }

            function extractLegacyPromotedAnnotationSourceMeta(annotationData) {
                if (!annotationData || typeof annotationData !== 'object') {
                    return null;
                }

                const hasLegacySourceFields = (
                    annotationData.sourceBlockLeft !== undefined
                    || annotationData.sourceBlockTop !== undefined
                    || Array.isArray(annotationData.sourceTextLines)
                    || Array.isArray(annotationData.sourceLineBBoxes)
                    || Array.isArray(annotationData.sourceSpans)
                );

                if (!hasLegacySourceFields) {
                    return null;
                }

                return sanitizePromotedAnnotationSourceMeta({
                    sourceBlockLeft: annotationData.sourceBlockLeft,
                    sourceBlockTop: annotationData.sourceBlockTop,
                    sourceBlockWidth: annotationData.sourceBlockWidth,
                    sourceBlockHeight: annotationData.sourceBlockHeight,
                    sourcePageHeight: annotationData.sourcePageHeight,
                    sourceTextLines: annotationData.sourceTextLines,
                    sourceLineBBoxes: annotationData.sourceLineBBoxes,
                    sourceSpans: annotationData.sourceSpans,
                });
            }

            function clampTextFontSizePx(value, min = editTextBannerMinFontSize, max = editTextBannerMaxFontSize) {
                const numericValue = Number(value);
                if (!Number.isFinite(numericValue)) {
                    return min;
                }
                return Math.max(min, Math.min(max, Math.round(numericValue)));
            }

            function bannerSliderValueToFontSizePx(value) {
                const sliderValue = Math.max(
                    editTextBannerSliderMin,
                    Math.min(editTextBannerSliderMax, Number(value) || editTextBannerSliderMid)
                );
                if (sliderValue <= editTextBannerSliderMid) {
                    const ratio = (sliderValue - editTextBannerSliderMin)
                        / Math.max(1, editTextBannerSliderMid - editTextBannerSliderMin);
                    return clampTextFontSizePx(
                        editTextBannerMinFontSize
                        + ((editTextBannerMidFontSize - editTextBannerMinFontSize) * ratio)
                    );
                }
                const ratio = (sliderValue - editTextBannerSliderMid)
                    / Math.max(1, editTextBannerSliderMax - editTextBannerSliderMid);
                return clampTextFontSizePx(
                    editTextBannerMidFontSize
                    + ((editTextBannerMaxFontSize - editTextBannerMidFontSize) * ratio)
                );
            }

            function fontSizePxToBannerSliderValue(value) {
                const sizePx = clampTextFontSizePx(value);
                if (sizePx <= editTextBannerMidFontSize) {
                    const ratio = (sizePx - editTextBannerMinFontSize)
                        / Math.max(1, editTextBannerMidFontSize - editTextBannerMinFontSize);
                    return Math.round(
                        editTextBannerSliderMin
                        + ((editTextBannerSliderMid - editTextBannerSliderMin) * ratio)
                    );
                }
                const ratio = (sizePx - editTextBannerMidFontSize)
                    / Math.max(1, editTextBannerMaxFontSize - editTextBannerMidFontSize);
                return Math.round(
                    editTextBannerSliderMid
                    + ((editTextBannerSliderMax - editTextBannerSliderMid) * ratio)
                );
            }

            function setEditTextBannerFontSize(sizePx) {
                const size = document.getElementById('etb-size');
                if (!size) {
                    return;
                }
                size.value = String(fontSizePxToBannerSliderValue(sizePx));
            }

            function getAnnotationTextPreview(annotation, maxLength = 28) {
                const normalizedText = String(annotation?.text || '')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (!normalizedText) {
                    return '';
                }
                if (normalizedText.length <= maxLength) {
                    return normalizedText;
                }
                return `${normalizedText.slice(0, maxLength).trimEnd()}...`;
            }

            // Annotations Panel Management
            // SVG icons for each annotation type
            const LAYER_ICONS = {
                text: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 7 4 4 20 4 20 7"/><line x1="9" y1="20" x2="15" y2="20"/><line x1="12" y1="4" x2="12" y2="20"/></svg>`,
                shape: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/></svg>`,
                image: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>`,
                signature: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/></svg>`,
                table: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="3" y1="15" x2="21" y2="15"/><line x1="9" y1="3" x2="9" y2="21"/><line x1="15" y1="3" x2="15" y2="21"/></svg>`,
                field: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="6" width="20" height="12" rx="2"/><line x1="6" y1="12" x2="18" y2="12"/></svg>`,
                eraser: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 20H7L3 16l10-10 7 7-2.5 2.5"/><path d="M6.0001 17.9999L10 14"/></svg>`,
                draw: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 17c3-3 6 0 9-3s3-6 6-6"/></svg>`,
            };
            const EDIT_ICON_SVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>`;
            const DELETE_ICON_SVG = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>`;

            function updateAnnotationsList() {
                const annotationsList = document.getElementById('annotations-list');
                if (!annotationsList) return;

                const searchInput = document.getElementById('annotations-search');
                const searchQuery = (searchInput ? searchInput.value : '').toLowerCase().trim();

                annotationsList.innerHTML = '';

                annotations.forEach((annotation, index) => {
                    let iconKey = 'text';
                    let title = 'Annotation';
                    if (annotation.type === 'text' || !annotation.type) {
                        iconKey = 'text';
                        title = getAnnotationTextPreview(annotation)
                            || `New Text ${annotations.filter((a, i) => (a.type === 'text' || !a.type) && i <= index).length}`;
                    } else if (annotation.type === 'field') {
                        iconKey = 'field';
                        title = getFieldAnnotationPreview(annotation)
                            || `${getFieldAnnotationLabel(annotation)} ${annotations.filter((a, i) => a.type === 'field' && i <= index).length}`;
                    } else if (annotation.type === 'signature') {
                        iconKey = 'signature';
                        title = `Authorized Signature ${annotations.filter((a, i) => a.type === 'signature' && i <= index).length}`;
                    } else if (annotation.type === 'shape') {
                        iconKey = 'shape';
                        title = `New ${annotation.shapeType ? annotation.shapeType.charAt(0).toUpperCase() + annotation.shapeType.slice(1) : 'Shape'} ${annotations.filter((a, i) => a.type === 'shape' && i <= index).length}`;
                    } else if (annotation.type === 'table') {
                        iconKey = 'table';
                        title = `Table ${annotation.rows || ''}×${annotation.cols || ''} ${annotations.filter((a, i) => a.type === 'table' && i <= index).length}`;
                    } else if (annotation.type === 'image') {
                        iconKey = 'image';
                        title = `Brand Logo ${annotations.filter((a, i) => a.type === 'image' && i <= index).length}`;
                    } else if (annotation.type === 'eraser') {
                        iconKey = 'eraser';
                        title = `Eraser ${annotations.filter((a, i) => a.type === 'eraser' && i <= index).length}`;
                    }

                    // Filter by search query (search against display name)
                    const searchTitle = annotation.customName || title;
                    if (searchQuery && !searchTitle.toLowerCase().includes(searchQuery)) return;

                    const item = document.createElement('div');
                    item.className = 'annotation-item';
                    item.draggable = true;
                    item.dataset.index = index;
                    if (selectedAnnotation === annotation) item.classList.add('selected');

                    item.innerHTML = `
                        <div class="annotation-item-icon type-${iconKey}">${LAYER_ICONS[iconKey] || LAYER_ICONS.text}</div>
                        <div class="annotation-item-content">
                            <div class="annotation-item-title"></div>
                            <div class="annotation-item-meta">Page ${annotation.pageIndex + 1}</div>
                        </div>
                        <div class="annotation-item-actions">
                            <button class="annotation-item-action edit" title="Edit" data-index="${index}">${EDIT_ICON_SVG}</button>
                            <button class="annotation-item-action delete" title="Delete" data-index="${index}">${DELETE_ICON_SVG}</button>
                        </div>
                    `;
                    const displayTitle = annotation.customName || title;
                    const titleElement = item.querySelector('.annotation-item-title');
                    if (titleElement) {
                        titleElement.textContent = displayTitle;
                        titleElement.title = 'Double-click to rename';
                    }

                    // Inline rename on double-click
                    titleElement?.addEventListener('dblclick', (e) => {
                        e.stopPropagation();
                        const current = titleElement.textContent;
                        const input = document.createElement('input');
                        input.type = 'text';
                        input.className = 'annotation-item-rename-input';
                        input.value = current;
                        titleElement.replaceWith(input);
                        input.focus();
                        input.select();

                        const commit = () => {
                            const newName = input.value.trim();
                            if (newName && newName !== (annotation.customName || title)) {
                                annotation.customName = newName;
                                persistAnnotations();
                                saveAnnotationToDatabase(annotation);
                            }
                            updateAnnotationsList();
                        };
                        const cancel = () => updateAnnotationsList();

                        input.addEventListener('blur', commit);
                        input.addEventListener('keydown', (ev) => {
                            if (ev.key === 'Enter') { ev.preventDefault(); input.blur(); }
                            if (ev.key === 'Escape') { input.removeEventListener('blur', commit); cancel(); }
                        });
                    });

                    // Edit button
                    item.querySelector('.edit').addEventListener('click', (e) => {
                        e.stopPropagation();
                        // Scroll to annotation on page and select it
                        const page = document.querySelector(`[data-page-index="${annotation.pageIndex}"]`);
                        if (page) {
                            page.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }
                        if (!setSelection(annotation)) {
                            ensureAnnotationInteractionsEnabled(annotation, {
                                message: 'Turn on Edit Text to select existing text, shapes, and signatures.',
                            });
                        }
                    });
                    
                    // Click on list item to select
                    item.addEventListener('click', (e) => {
                        if (e.target.closest('.annotation-item-actions')) return;
                        const page = document.querySelector(`[data-page-index="${annotation.pageIndex}"]`);
                        if (page) {
                            page.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }
                        if (!setSelection(annotation)) {
                            ensureAnnotationInteractionsEnabled(annotation, {
                                message: 'Turn on Edit Text to select existing text, shapes, and signatures.',
                            });
                        }
                    });
                    
                    // Delete button
                    item.querySelector('.delete').addEventListener('click', (e) => {
                        e.stopPropagation();
                        if (!ensureAnnotationInteractionsEnabled(annotation, {
                            message: 'Turn on Edit Text to delete existing text, shapes, and signatures.',
                        })) {
                            return;
                        }
                        const ann = annotations[index];
                        deleteAnnotationFromDatabase(ann);
                        annotations.splice(index, 1);
                        persistAnnotations();
                        rerenderPdf();
                        updateAnnotationsList();
                    });
                    
                    // Drag & drop for reordering
                    item.addEventListener('dragstart', (e) => {
                        item.classList.add('dragging');
                        e.dataTransfer.effectAllowed = 'move';
                        e.dataTransfer.setData('text/plain', index);
                    });
                    
                    item.addEventListener('dragend', () => {
                        item.classList.remove('dragging');
                    });
                    
                    item.addEventListener('dragover', (e) => {
                        e.preventDefault();
                        e.dataTransfer.dropEffect = 'move';
                    });
                    
                    item.addEventListener('drop', (e) => {
                        e.preventDefault();
                        const fromIndex = parseInt(e.dataTransfer.getData('text/plain'));
                        const toIndex = parseInt(item.dataset.index);
                        
                        if (fromIndex !== toIndex) {
                            const [moved] = annotations.splice(fromIndex, 1);
                            annotations.splice(toIndex, 0, moved);
                            persistAnnotations();
                            rerenderPdf();
                            updateAnnotationsList();
                        }
                    });
                    
                    annotationsList.appendChild(item);
                });
            }

            // Toggle annotations panel
            document.getElementById('annotations-toggle')?.addEventListener('click', () => {
                const panel = document.getElementById('annotations-panel');
                panel.classList.toggle('collapsed');
            });

            // Keep the layers panel flush below the mode-bar
            function syncLayersPanelTop() {
                const modeBar = document.getElementById('pdf-mode-bar');
                if (!modeBar) return;
                const bottom = modeBar.getBoundingClientRect().bottom;
                document.documentElement.style.setProperty('--layers-panel-top', `${bottom}px`);
            }
            syncLayersPanelTop();
            window.addEventListener('resize', syncLayersPanelTop);
            // Re-sync after any scroll (mode-bar is sticky so its bottom can change)
            window.addEventListener('scroll', syncLayersPanelTop, { passive: true });

            // Search filter
            document.getElementById('annotations-search')?.addEventListener('input', () => {
                updateAnnotationsList();
            });

            // Remove all annotations
            document.getElementById('remove-all-annotations')?.addEventListener('click', () => {
                if (annotations.length === 0) return;
                if (confirm(`Remove all ${annotations.length} annotations?`)) {
                    clearAllAnnotationRecords();
                    persistAnnotations();
                    rerenderPdf();
                    updateAnnotationsList();
                }
            });

            const fontMap = {
                Helvetica: { css: '"AnnotHelvetica", "Arimo", Arial, sans-serif', pdf: PDFLib.StandardFonts.Helvetica },
                Arial: { css: '"AnnotHelvetica", "Arimo", Arial, sans-serif', pdf: PDFLib.StandardFonts.Helvetica },
                Verdana: { css: '"Verdana", Geneva, Arial, sans-serif', pdf: PDFLib.StandardFonts.Helvetica },
                TrebuchetMS: { css: '"Trebuchet MS", Verdana, Geneva, Arial, sans-serif', pdf: PDFLib.StandardFonts.Helvetica },
                TimesRoman: { css: '"TimesRoman", "Tinos", "Times New Roman", Times, serif', pdf: PDFLib.StandardFonts.TimesRoman },
                Georgia: { css: '"Georgia", "Liberation Serif", serif', pdf: PDFLib.StandardFonts.TimesRoman },
                Palatino: { css: '"AnnotPalatino", "Liberation Serif", "Times New Roman", serif', pdf: PDFLib.StandardFonts.TimesRoman },
                Garamond: { css: '"AnnotGaramond", "EB Garamond", Baskerville, serif', pdf: PDFLib.StandardFonts.TimesRoman },
                Courier: { css: '"Courier", "Cousine", "Courier New", monospace', pdf: PDFLib.StandardFonts.Courier },
            };
            const pdfFontVariants = {
                Helvetica: {
                    normal: PDFLib.StandardFonts.Helvetica,
                    bold: PDFLib.StandardFonts.HelveticaBold,
                    italic: PDFLib.StandardFonts.HelveticaOblique,
                    boldItalic: PDFLib.StandardFonts.HelveticaBoldOblique,
                },
                Arial: {
                    normal: PDFLib.StandardFonts.Helvetica,
                    bold: PDFLib.StandardFonts.HelveticaBold,
                    italic: PDFLib.StandardFonts.HelveticaOblique,
                    boldItalic: PDFLib.StandardFonts.HelveticaBoldOblique,
                },
                Verdana: {
                    normal: PDFLib.StandardFonts.Helvetica,
                    bold: PDFLib.StandardFonts.HelveticaBold,
                    italic: PDFLib.StandardFonts.HelveticaOblique,
                    boldItalic: PDFLib.StandardFonts.HelveticaBoldOblique,
                },
                TrebuchetMS: {
                    normal: PDFLib.StandardFonts.Helvetica,
                    bold: PDFLib.StandardFonts.HelveticaBold,
                    italic: PDFLib.StandardFonts.HelveticaOblique,
                    boldItalic: PDFLib.StandardFonts.HelveticaBoldOblique,
                },
                TimesRoman: {
                    normal: PDFLib.StandardFonts.TimesRoman,
                    bold: PDFLib.StandardFonts.TimesRomanBold,
                    italic: PDFLib.StandardFonts.TimesRomanItalic,
                    boldItalic: PDFLib.StandardFonts.TimesRomanBoldItalic,
                },
                Georgia: {
                    normal: PDFLib.StandardFonts.TimesRoman,
                    bold: PDFLib.StandardFonts.TimesRomanBold,
                    italic: PDFLib.StandardFonts.TimesRomanItalic,
                    boldItalic: PDFLib.StandardFonts.TimesRomanBoldItalic,
                },
                Palatino: {
                    normal: PDFLib.StandardFonts.TimesRoman,
                    bold: PDFLib.StandardFonts.TimesRomanBold,
                    italic: PDFLib.StandardFonts.TimesRomanItalic,
                    boldItalic: PDFLib.StandardFonts.TimesRomanBoldItalic,
                },
                Garamond: {
                    normal: PDFLib.StandardFonts.TimesRoman,
                    bold: PDFLib.StandardFonts.TimesRomanBold,
                    italic: PDFLib.StandardFonts.TimesRomanItalic,
                    boldItalic: PDFLib.StandardFonts.TimesRomanBoldItalic,
                },
                Courier: {
                    normal: PDFLib.StandardFonts.Courier,
                    bold: PDFLib.StandardFonts.CourierBold,
                    italic: PDFLib.StandardFonts.CourierOblique,
                    boldItalic: PDFLib.StandardFonts.CourierBoldOblique,
                },
            };

            let insertMode = null;
            let toolMode = 'select'; // Start in select mode, user clicks Edit Text to edit
            let signatureDataUrl = null;
            let signatureImageAsset = null;
            let signatureTargetField = null;
            let shapeType = 'circle';
            let shapeStroke = '#000000';
            let shapeStrokeWidth = 2;
            let shapeStrokeTransparentState = false;
            let shapeFill = '#ffffff';
            let shapeFillTransparentState = false;
            let shapeOpacityValue = 1;
            let tableRows = 3;
            let tableCols = 3;
            let tableStroke = '#000000';
            let tableStrokeWidth = 1;
            let tableFill = '#ffffff';
            let tableFillTransparent = true;
            let tableOuterBorder = true;
            let drawToolType = 'brush';
            let drawStrokeColor = '#111827';
            let drawOpacity = 1;
            let drawBrushSize = 12;
            let fieldType = 'text';
            const gridlinesSettingsStorageKey = 'pdf-editor-gridlines-settings-v1';

            function normalizeShapeOpacity(value) {
                const numericValue = Number(value);
                if (!Number.isFinite(numericValue)) {
                    return 1;
                }
                const normalized = numericValue > 1 ? (numericValue / 100) : numericValue;
                return Math.max(0, Math.min(1, normalized));
            }

            function shapeHasVisibleStroke(shapeLike) {
                if (!shapeLike || shapeLike.strokeTransparent) {
                    return false;
                }
                const strokeWidth = Number(shapeLike.strokeWidth) || 0;
                const strokeColor = String(shapeLike.strokeColor || '').trim().toLowerCase();
                return strokeWidth > 0 && strokeColor !== '' && strokeColor !== 'transparent';
            }

            function syncShapeAnnotationOutlineState(label, shapeLike, { preview = false } = {}) {
                if (!label) {
                    return;
                }
                const needsOutline = !!shapeLike && String(shapeLike.type || 'shape') === 'shape' && !shapeHasVisibleStroke(shapeLike);
                label.classList.toggle('shape-fill-only-outline', needsOutline);
                label.classList.toggle('shape-draw-preview', needsOutline && preview);
            }

            function createShapeSvgElement(tagName) {
                return document.createElementNS('http://www.w3.org/2000/svg', tagName);
            }

            function mapShapeCoordinate(value, inset) {
                const safeInset = Math.max(0, Math.min(45, Number(inset) || 0));
                const clampedValue = Math.max(0, Math.min(100, Number(value) || 0));
                return Number((safeInset + ((100 - (safeInset * 2)) * (clampedValue / 100))).toFixed(3));
            }

            function clampShapeUnitInterval(value, fallback) {
                const numericValue = Number(value);
                if (!Number.isFinite(numericValue)) {
                    return fallback;
                }
                return Math.max(0, Math.min(1, numericValue));
            }

            function isLineShapeType(shapeTypeValue) {
                return String(shapeTypeValue || '') === 'line';
            }

            function ensureLineShapeGeometry(shapeLike) {
                const geometry = {
                    lineStartX: clampShapeUnitInterval(shapeLike?.lineStartX, 0),
                    lineStartY: clampShapeUnitInterval(shapeLike?.lineStartY, 1),
                    lineEndX: clampShapeUnitInterval(shapeLike?.lineEndX, 1),
                    lineEndY: clampShapeUnitInterval(shapeLike?.lineEndY, 0),
                };

                if (shapeLike && isLineShapeType(shapeLike.shapeType)) {
                    shapeLike.lineStartX = geometry.lineStartX;
                    shapeLike.lineStartY = geometry.lineStartY;
                    shapeLike.lineEndX = geometry.lineEndX;
                    shapeLike.lineEndY = geometry.lineEndY;
                }

                return geometry;
            }

            function computeLineBoxGeometry(startX, startY, endX, endY) {
                const safeStartX = Number(startX) || 0;
                const safeStartY = Number(startY) || 0;
                const safeEndX = Number(endX) || 0;
                const safeEndY = Number(endY) || 0;
                const left = Math.min(safeStartX, safeEndX);
                const top = Math.min(safeStartY, safeEndY);
                const width = Math.max(1, Math.abs(safeEndX - safeStartX));
                const height = Math.max(1, Math.abs(safeEndY - safeStartY));

                return {
                    left,
                    top,
                    width,
                    height,
                    lineStartX: clampShapeUnitInterval((safeStartX - left) / width, 0),
                    lineStartY: clampShapeUnitInterval((safeStartY - top) / height, 0),
                    lineEndX: clampShapeUnitInterval((safeEndX - left) / width, 1),
                    lineEndY: clampShapeUnitInterval((safeEndY - top) / height, 1),
                };
            }

            function snapLineEndpoint(startX, startY, endX, endY) {
                const dx = (Number(endX) || 0) - (Number(startX) || 0);
                const dy = (Number(endY) || 0) - (Number(startY) || 0);
                const distance = Math.hypot(dx, dy);
                if (distance < 1) {
                    return {
                        x: Number(endX) || 0,
                        y: Number(endY) || 0,
                    };
                }

                const angle = Math.atan2(dy, dx);
                const snapStep = Math.PI / 4;
                const snapThreshold = (8 * Math.PI) / 180;
                const snappedAngle = Math.round(angle / snapStep) * snapStep;
                let angleDelta = angle - snappedAngle;
                while (angleDelta > Math.PI) angleDelta -= Math.PI * 2;
                while (angleDelta < -Math.PI) angleDelta += Math.PI * 2;

                if (Math.abs(angleDelta) > snapThreshold) {
                    return {
                        x: Number(endX) || 0,
                        y: Number(endY) || 0,
                    };
                }

                return {
                    x: (Number(startX) || 0) + (Math.cos(snappedAngle) * distance),
                    y: (Number(startY) || 0) + (Math.sin(snappedAngle) * distance),
                };
            }

            function syncLineShapeSvgGeometry(svg, shapeLike) {
                if (!svg || !isLineShapeType(shapeLike?.shapeType)) {
                    return;
                }
                const line = svg.querySelector('line');
                if (!line) {
                    return;
                }
                const geometry = ensureLineShapeGeometry(shapeLike);
                line.setAttribute('x1', String(Number((geometry.lineStartX * 100).toFixed(3))));
                line.setAttribute('y1', String(Number((geometry.lineStartY * 100).toFixed(3))));
                line.setAttribute('x2', String(Number((geometry.lineEndX * 100).toFixed(3))));
                line.setAttribute('y2', String(Number((geometry.lineEndY * 100).toFixed(3))));
            }

            function buildShapeSvg(shapeLike) {
                const svg = createShapeSvgElement('svg');
                const strokeWidth = Math.max(0, Number(shapeLike?.strokeWidth) || 0);
                const visibleStroke = shapeHasVisibleStroke(shapeLike);
                const inset = visibleStroke ? Math.min(45, strokeWidth / 2) : 0;
                const opacity = normalizeShapeOpacity(shapeLike?.opacity);
                const strokeColor = visibleStroke ? String(shapeLike.strokeColor || '#000000') : 'transparent';
                const fillColor = shapeLike?.fillTransparent ? 'transparent' : String(shapeLike?.fillColor || '#000000');
                const preserveStrokeWidth = ['line', 'x', 'checkmark', 'arrow'].includes(String(shapeLike?.shapeType || ''));
                const innerSize = Math.max(0, 100 - (inset * 2));
                const minEdge = inset;
                const maxEdge = 100 - inset;

                svg.setAttribute('width', '100%');
                svg.setAttribute('height', '100%');
                svg.setAttribute('viewBox', `${-inset} ${-inset} ${100 + (inset * 2)} ${100 + (inset * 2)}`);
                svg.setAttribute('preserveAspectRatio', 'none');
                svg.style.display = 'block';
                svg.style.overflow = 'visible';

                const setBaseShapeStyle = (element) => {
                    element.setAttribute('fill', fillColor);
                    element.setAttribute('stroke', strokeColor);
                    if (strokeWidth > 0) {
                        element.setAttribute('stroke-width', String(strokeWidth));
                    }
                    if (preserveStrokeWidth) {
                        element.setAttribute('vector-effect', 'non-scaling-stroke');
                    }
                    element.setAttribute('opacity', String(opacity));
                    return element;
                };

                if (shapeLike?.shapeType === 'circle' || shapeLike?.shapeType === 'ellipse') {
                    const ellipse = setBaseShapeStyle(createShapeSvgElement('ellipse'));
                    ellipse.setAttribute('cx', '50');
                    ellipse.setAttribute('cy', '50');
                    ellipse.setAttribute('rx', String(Math.max(0, 50 - inset)));
                    ellipse.setAttribute('ry', String(Math.max(0, 50 - inset)));
                    svg.appendChild(ellipse);
                    return svg;
                }

                if (shapeLike?.shapeType === 'triangle') {
                    const triangle = setBaseShapeStyle(createShapeSvgElement('polygon'));
                    triangle.setAttribute('points', `50 ${minEdge}, ${maxEdge} ${maxEdge}, ${minEdge} ${maxEdge}`);
                    triangle.setAttribute('stroke-linejoin', 'round');
                    svg.appendChild(triangle);
                    return svg;
                }

                if (shapeLike?.shapeType === 'x') {
                    const group = createShapeSvgElement('g');
                    [
                        [minEdge, minEdge, maxEdge, maxEdge],
                        [maxEdge, minEdge, minEdge, maxEdge],
                    ].forEach(([x1, y1, x2, y2]) => {
                        const line = setBaseShapeStyle(createShapeSvgElement('line'));
                        line.setAttribute('fill', 'none');
                        line.setAttribute('x1', String(x1));
                        line.setAttribute('y1', String(y1));
                        line.setAttribute('x2', String(x2));
                        line.setAttribute('y2', String(y2));
                        line.setAttribute('stroke-linecap', 'round');
                        group.appendChild(line);
                    });
                    svg.appendChild(group);
                    return svg;
                }

                if (shapeLike?.shapeType === 'line') {
                    const line = setBaseShapeStyle(createShapeSvgElement('line'));
                    line.setAttribute('fill', 'none');
                    line.setAttribute('stroke-linecap', 'round');
                    svg.appendChild(line);
                    syncLineShapeSvgGeometry(svg, shapeLike);
                    return svg;
                }

                if (shapeLike?.shapeType === 'checkmark') {
                    const polyline = setBaseShapeStyle(createShapeSvgElement('polyline'));
                    polyline.setAttribute('fill', 'none');
                    polyline.setAttribute('points', [
                        `${mapShapeCoordinate(15, inset)} ${mapShapeCoordinate(50, inset)}`,
                        `${mapShapeCoordinate(40, inset)} ${mapShapeCoordinate(75, inset)}`,
                        `${mapShapeCoordinate(85, inset)} ${mapShapeCoordinate(15, inset)}`,
                    ].join(', '));
                    polyline.setAttribute('stroke-linecap', 'round');
                    polyline.setAttribute('stroke-linejoin', 'round');
                    svg.appendChild(polyline);
                    return svg;
                }

                if (shapeLike?.shapeType === 'star') {
                    const star = setBaseShapeStyle(createShapeSvgElement('polygon'));
                    star.setAttribute('points', [
                        '50,5', '61,38', '95,38', '68,58', '79,91',
                        '50,71', '21,91', '32,58', '5,38', '39,38',
                    ].map((point) => {
                        const [x, y] = point.split(',').map(Number);
                        return `${mapShapeCoordinate(x, inset)} ${mapShapeCoordinate(y, inset)}`;
                    }).join(', '));
                    star.setAttribute('stroke-linejoin', 'round');
                    svg.appendChild(star);
                    return svg;
                }

                if (shapeLike?.shapeType === 'polygon') {
                    const polygon = setBaseShapeStyle(createShapeSvgElement('polygon'));
                    polygon.setAttribute('points', [
                        '50,5', '90,27', '90,73', '50,95', '10,73', '10,27',
                    ].map((point) => {
                        const [x, y] = point.split(',').map(Number);
                        return `${mapShapeCoordinate(x, inset)} ${mapShapeCoordinate(y, inset)}`;
                    }).join(', '));
                    polygon.setAttribute('stroke-linejoin', 'round');
                    svg.appendChild(polygon);
                    return svg;
                }

                if (shapeLike?.shapeType === 'arrow') {
                    const group = createShapeSvgElement('g');
                    const line = setBaseShapeStyle(createShapeSvgElement('line'));
                    line.setAttribute('fill', 'none');
                    line.setAttribute('x1', String(minEdge));
                    line.setAttribute('y1', '50');
                    line.setAttribute('x2', String(mapShapeCoordinate(82, inset)));
                    line.setAttribute('y2', '50');
                    line.setAttribute('stroke-linecap', 'round');
                    const arrowHead = setBaseShapeStyle(createShapeSvgElement('polyline'));
                    arrowHead.setAttribute('fill', 'none');
                    arrowHead.setAttribute('points', [
                        `${mapShapeCoordinate(64, inset)} ${mapShapeCoordinate(32, inset)}`,
                        `${maxEdge} 50`,
                        `${mapShapeCoordinate(64, inset)} ${mapShapeCoordinate(68, inset)}`,
                    ].join(', '));
                    arrowHead.setAttribute('stroke-linecap', 'round');
                    arrowHead.setAttribute('stroke-linejoin', 'round');
                    group.appendChild(line);
                    group.appendChild(arrowHead);
                    svg.appendChild(group);
                    return svg;
                }

                const rect = setBaseShapeStyle(createShapeSvgElement('rect'));
                rect.setAttribute('x', String(minEdge));
                rect.setAttribute('y', String(minEdge));
                rect.setAttribute('width', String(innerSize));
                rect.setAttribute('height', String(innerSize));
                svg.appendChild(rect);
                return svg;
            }

            function getCurrentShapeStyleConfig() {
                const strokeTransparent = Boolean(shapeStrokeTransparentInput?.checked ?? shapeStrokeTransparentState);
                const fillTransparent = Boolean(shapeFillTransparentInput?.checked ?? shapeFillTransparentState);
                const strokeColorValue = String(shapeStrokeColorInput?.value || shapeStrokeHexInput?.value || shapeStroke || '#000000').trim() || '#000000';
                const fillColorValue = String(shapeFillColorInput?.value || shapeFillHexInput?.value || shapeFill || '#ffffff').trim() || '#ffffff';
                const strokeWidth = Math.max(0, parseFloat(shapeStrokeWidthInput?.value) || shapeStrokeWidth || 0);
                const opacityPercent = parseFloat(shapeOpacityInput?.value);
                const opacity = Number.isFinite(opacityPercent)
                    ? Math.max(0, Math.min(1, opacityPercent / 100))
                    : normalizeShapeOpacity(shapeOpacityValue);

                shapeStroke = strokeColorValue;
                shapeFill = fillColorValue;
                shapeStrokeTransparentState = strokeTransparent;
                shapeFillTransparentState = fillTransparent;
                shapeStrokeWidth = strokeWidth;
                shapeOpacityValue = opacity;

                return {
                    strokeTransparent,
                    fillTransparent,
                    strokeColor: strokeTransparent ? 'transparent' : strokeColorValue,
                    fillColor: fillTransparent ? 'transparent' : fillColorValue,
                    strokeWidth,
                    opacity,
                };
            }

            function loadGridlinesSettings() {
                try {
                    const raw = localStorage.getItem(gridlinesSettingsStorageKey);
                    if (!raw) {
                        return null;
                    }
                    const parsed = JSON.parse(raw);
                    if (!parsed || typeof parsed !== 'object') {
                        return null;
                    }
                    return parsed;
                } catch (error) {
                    console.warn('Failed to load gridlines settings:', error);
                    return null;
                }
            }

            function persistGridlinesSettings() {
                try {
                    localStorage.setItem(gridlinesSettingsStorageKey, JSON.stringify({
                        enabled: !!gridlinesEnabled,
                        spacing: gridlinesSpacing,
                        color: gridlinesColor,
                        opacity: gridlinesOpacity,
                    }));
                } catch (error) {
                    console.warn('Failed to persist gridlines settings:', error);
                }
            }

            const storedGridlinesSettings = loadGridlinesSettings();
            let gridlinesEnabled = !!storedGridlinesSettings?.enabled;

            function isImageBackedAnnotationType(type) {
                const normalized = String(type || '').toLowerCase();
                return normalized === 'signature' || normalized === 'image';
            }

            function getAnnotationImageDataUrl(annotation) {
                const directValue = String(annotation?.dataUrl || annotation?.src || '').trim();
                if (directValue) {
                    return directValue;
                }

                const assetPath = String(annotation?.assetPath || annotation?.imagePath || '').trim();
                if (!assetPath) {
                    return '';
                }

                if (/^https?:\/\//i.test(assetPath)) {
                    return assetPath;
                }

                const normalizedPath = assetPath.replace(/^\/+/, '').replace(/^storage\//, '');
                const documentAssetMatch = normalizedPath.match(/^annotation-assets\/documents\/(\d+)\/([^/]+)$/i);
                if (documentAssetMatch) {
                    const [, documentId, fileName] = documentAssetMatch;
                    return new URL(`/documents/${encodeURIComponent(documentId)}/annotation-assets/${encodeURIComponent(fileName)}`, window.location.origin).toString();
                }

                return new URL(`/${normalizedPath}`, window.location.origin).toString();
            }

            function getAnnotationTypeLabel(annotationOrType) {
                const normalized = typeof annotationOrType === 'string'
                    ? String(annotationOrType).toLowerCase()
                    : String(annotationOrType?.type || 'text').toLowerCase();
                if (normalized === 'signature') return 'Signature';
                if (normalized === 'image') return 'Image';
                if (normalized === 'shape') return 'Shape';
                if (normalized === 'table') return 'Table';
                if (normalized === 'eraser') return 'Eraser';
                if (normalized === 'field') return 'Field';
                return 'Text';
            }

            function isFieldAnnotation(annotationOrType) {
                const normalized = typeof annotationOrType === 'string'
                    ? String(annotationOrType || '').toLowerCase()
                    : String(annotationOrType?.type || '').toLowerCase();
                return normalized === 'field';
            }

            function normalizeFieldKind(value) {
                const normalized = String(value || '').toLowerCase().trim();
                if (normalized === 'date') {
                    return 'date';
                }
                if (normalized === 'checkbox') {
                    return 'checkbox';
                }
                if (normalized === 'signature') {
                    return 'signature';
                }
                if (normalized === 'select') {
                    return 'select';
                }
                if (normalized === 'list') {
                    return 'list';
                }
                return 'text';
            }

            function isOptionFieldKind(value) {
                const normalized = normalizeFieldKind(value);
                return normalized === 'select' || normalized === 'list';
            }

            function isTextEntryFieldKind(value) {
                const normalized = normalizeFieldKind(value);
                return normalized === 'text' || normalized === 'date';
            }

            function formatDateFieldValue(value, { finalize = false } = {}) {
                const rawValue = String(value ?? '').trim();
                if (!rawValue) {
                    return '';
                }

                if (/[^\d]/.test(rawValue)) {
                    const parts = rawValue
                        .split(/[^0-9]+/)
                        .map((part) => part.trim())
                        .filter((part) => part.length > 0)
                        .slice(0, 3);
                    if (parts.length) {
                        const month = finalize ? parts[0].slice(0, 2).padStart(2, '0') : parts[0].slice(0, 2);
                        const day = parts.length > 1
                            ? (finalize ? parts[1].slice(0, 2).padStart(2, '0') : parts[1].slice(0, 2))
                            : '';
                        const year = parts.length > 2 ? parts[2].slice(0, 4) : '';
                        return [month, day, year].filter((part) => part.length > 0).join('/');
                    }
                }

                const digits = rawValue.replace(/\D+/g, '').slice(0, 8);
                if (!digits) {
                    return '';
                }
                const month = digits.slice(0, 2);
                const day = digits.slice(2, 4);
                const year = digits.slice(4, 8);
                return [month, day, year].filter((part) => part.length > 0).join('/');
            }

            function dateFieldValueToPickerValue(value) {
                const normalized = formatDateFieldValue(value, { finalize: true });
                const match = normalized.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
                if (!match) {
                    return '';
                }
                const [, month, day, year] = match;
                return `${year}-${month}-${day}`;
            }

            function pickerValueToDateFieldValue(value) {
                const normalized = String(value || '').trim();
                const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
                if (!match) {
                    return formatDateFieldValue(normalized, { finalize: true });
                }
                const [, year, month, day] = match;
                return `${month}/${day}/${year}`;
            }

            function getDefaultOptionFieldOptions(fieldKind) {
                return normalizeFieldKind(fieldKind) === 'list'
                    ? ['Option 1', 'Option 2', 'Option 3']
                    : ['Option 1', 'Option 2'];
            }

            function normalizeSelectFieldOptions(options, fallbackOptions = ['Option 1']) {
                const source = Array.isArray(options) ? options : [];
                const normalized = source
                    .map((option) => String(option ?? '').trim())
                    .filter((option) => option.length > 0)
                    .slice(0, 50);
                if (normalized.length) {
                    return normalized;
                }
                return fallbackOptions
                    .map((option) => String(option ?? '').trim())
                    .filter((option) => option.length > 0);
            }

            function getSelectFieldOptions(annotation, fallbackOptions = ['Option 1']) {
                return normalizeSelectFieldOptions(annotation?.fieldOptions, fallbackOptions);
            }

            function getSelectFieldValue(annotation, fallbackOptions = ['Option 1']) {
                const options = getSelectFieldOptions(annotation, fallbackOptions);
                const currentValue = String(annotation?.fieldValue || '').trim();
                if (currentValue && options.includes(currentValue)) {
                    return currentValue;
                }
                return options[0] || '';
            }

            function getFieldAnnotationLabel(annotation) {
                if (!isFieldAnnotation(annotation)) {
                    return '';
                }
                const fieldKind = normalizeFieldKind(annotation.fieldKind);
                if (fieldKind === 'date') {
                    return 'Date Field';
                }
                if (fieldKind === 'checkbox') {
                    return 'Checkbox';
                }
                if (fieldKind === 'signature') {
                    return 'Signature Field';
                }
                if (fieldKind === 'select') {
                    return 'Select Field';
                }
                if (fieldKind === 'list') {
                    return 'List Field';
                }
                return 'Text Field';
            }

            function getFieldAnnotationPreview(annotation) {
                if (!isFieldAnnotation(annotation)) {
                    return '';
                }
                const fieldKind = normalizeFieldKind(annotation.fieldKind);
                if (fieldKind === 'date') {
                    const preview = String(annotation.fieldValue || '').trim()
                        ? formatDateFieldValue(annotation.fieldValue || '', { finalize: true })
                        : String(annotation.placeholder || 'MM/DD/YYYY').trim();
                    return preview.length > 28 ? `${preview.slice(0, 28).trimEnd()}...` : preview;
                }
                if (fieldKind === 'checkbox') {
                    return annotation.checked ? 'Checkbox checked' : 'Checkbox';
                }
                if (fieldKind === 'signature') {
                    return annotation.signedDataUrl || annotation.signedAssetPath
                        ? 'Signed signature field'
                        : 'Signature field';
                }
                if (isOptionFieldKind(fieldKind)) {
                    const preview = getSelectFieldValue(annotation, getDefaultOptionFieldOptions(fieldKind)) || (fieldKind === 'list' ? 'List field' : 'Select field');
                    return preview.length > 28 ? `${preview.slice(0, 28).trimEnd()}...` : preview;
                }
                const preview = String(annotation.fieldValue || annotation.placeholder || 'Text Field').trim();
                return preview.length > 28 ? `${preview.slice(0, 28).trimEnd()}...` : preview;
            }

            function getFieldSignatureImageUrl(annotation) {
                if (!annotation || normalizeFieldKind(annotation.fieldKind) !== 'signature') {
                    return '';
                }
                return getAnnotationImageDataUrl({
                    dataUrl: annotation.signedDataUrl || '',
                    src: annotation.signedDataUrl || '',
                    assetPath: annotation.signedAssetPath || annotation.imagePath || '',
                    imagePath: annotation.signedAssetPath || annotation.imagePath || '',
                    mimeType: annotation.signedMimeType || 'image/png',
                });
            }

            function isTextAnnotationType(annotationOrType) {
                const normalized = typeof annotationOrType === 'string'
                    ? String(annotationOrType || '').toLowerCase()
                    : String(annotationOrType?.type || 'text').toLowerCase();
                return normalized === '' || normalized === 'text';
            }

            function isAutoDetectedDrawnCheckboxAnnotation(annotation) {
                return Boolean(
                    annotation
                    && typeof annotation === 'object'
                    && String(annotation.type || '').toLowerCase() === 'field'
                    && normalizeFieldKind(annotation.fieldKind) === 'checkbox'
                    && annotation.autoDetectedDrawnCheckbox === true
                );
            }

            function isDraggableOverlayAnnotation(annotation) {
                if (isAutoDetectedDrawnCheckboxAnnotation(annotation)) {
                    return false;
                }
                const normalized = String(annotation?.type || '').toLowerCase();
                return normalized === 'shape'
                    || normalized === 'eraser'
                    || normalized === 'table'
                    || normalized === 'field'
                    || isImageBackedAnnotationType(annotation?.type);
            }

            function hasShapeStyleAnnotationControls(annotationOrType) {
                if (typeof annotationOrType === 'object' && isAutoDetectedDrawnCheckboxAnnotation(annotationOrType)) {
                    return false;
                }
                const normalized = typeof annotationOrType === 'string'
                    ? String(annotationOrType || '').toLowerCase()
                    : String(annotationOrType?.type || '').toLowerCase();
                return normalized === 'shape'
                    || normalized === 'table'
                    || normalized === 'image'
                    || normalized === 'signature'
                    || normalized === 'field';
            }

            function getActiveFieldToolKind() {
                return toolMode === 'field' ? normalizeFieldKind(fieldType) : null;
            }

            function shouldStartOverlayShapeDraw(event, overlay) {
                if (!event || !overlay) {
                    return false;
                }

                const target = event.target;
                if (target === overlay) {
                    return true;
                }

                if (!(target instanceof Element) || !overlay.contains(target)) {
                    return false;
                }

                return !target.closest('.annotation, .overlay-field, .text-box-creator');
            }

            let gridlinesSpacing = Number.isFinite(Number(storedGridlinesSettings?.spacing))
                ? Math.min(200, Math.max(20, parseInt(storedGridlinesSettings.spacing, 10)))
                : 50;
            let gridlinesColor = /^#[0-9a-f]{6}$/i.test(String(storedGridlinesSettings?.color || ''))
                ? String(storedGridlinesSettings.color)
                : '#3b82f6';
            let gridlinesOpacity = Number.isFinite(Number(storedGridlinesSettings?.opacity))
                ? Math.min(0.5, Math.max(0.05, Number(storedGridlinesSettings.opacity)))
                : 0.15;
            let pdfDoc = null;
            let pdfjsDocument = null;
            let totalPages = 0;
            let renderedPages = 0;
            let renderInProgress = false;
            let viewerRenderQueue = Promise.resolve();
            let latestViewerRenderRequestId = 0;
            let activeViewerRenderRequestId = 0;
            const initialPageBatch = 6;
            const pageBatchSize = 4;
            
            // Overlay editor state
            let overlayEditorActive = false;
            let overlayExtractionData = null;
            let overlayEmbeddedFonts = null;  // Embedded font data from PDF extraction
            let overlayPdfDoc = null;  // Track overlay PDF for cleanup
            let promotedExtractionBootstrapPromise = null;
            let promotedExtractionHydrated = false;
            const deletedPromotedSourceKeys = new Set();
            const deletedSavedTextAnnotationIds = new Set();
            const deletedSavedNonTextAnnotationIds = new Set();
            // Tracks every annotation ID that has ever existed in this session (created or loaded).
            // If a known ID is absent from `annotations` at save time, the user deleted it.
            const knownAnnotationIds = new Set();
            let overlayEditedFields = new Map();
            let overlayPersistedEdits = new Map();
            let overlayLoadToken = 0;
            let overlayResizingField = null;
            let overlayResizeStart = { x: 0, y: 0, width: 0, height: 0, left: 0, top: 0 };
            let overlayResizePosition = '';
            let overlayInteractionActive = false; // true during resize/drag to block doFontReRender
            const overlayLoadedFonts = new Set();
            const overlayEditsStoragePrefix = `pdf-overlay-edits-${documentId}`;
            const overlayEditsStorageKey = `${overlayEditsStoragePrefix}-${overlayDocumentRevision}`;
            initializeEditorActivityTracking();
            let overlayRendered = false;
            let overlayUndoStack = [];
            let overlayRedoStack = [];
            let inlineEditRequestSequence = 0;
            const overlayUndoLimit = 50;
            const overlayUndoBtn = document.getElementById('overlay-undo');
            const overlayRedoBtn = document.getElementById('overlay-redo');
            const textMeasureCtx = document.createElement('canvas').getContext('2d');
            const documentLoadingScreen = document.getElementById('document-loading-screen');
            const documentLoadingMessage = document.getElementById('document-loading-message');
            const documentLoadingProgress = document.getElementById('document-loading-progress');
            const documentLoadingPercent = document.getElementById('document-loading-percent');
            const overlayLoadingModal = document.getElementById('overlay-loading-modal');
            const overlayLoadingMessage = document.getElementById('overlay-loading-message');
            const overlayLoadingProgress = document.getElementById('overlay-loading-progress');
            const overlayLoadingPercent = document.getElementById('overlay-loading-percent');
            let initialDocumentLoadPending = true;
            let documentLoadingHideTimer = null;
            const acroFormFieldDefaults = new Map();
            const acroFormFieldChanges = new Map();
            const deletedAnnotationPageIndices = new Set();
            const dirtyAnnotationPageIndices = new Set();

            function queueViewerRender(renderCallback) {
                const requestId = ++latestViewerRenderRequestId;
                const scheduledRender = viewerRenderQueue
                    .catch(() => {})
                    .then(async () => {
                        if (requestId !== latestViewerRenderRequestId) {
                            return;
                        }
                        activeViewerRenderRequestId = requestId;
                        try {
                            return await renderCallback(requestId);
                        } finally {
                            if (activeViewerRenderRequestId === requestId) {
                                activeViewerRenderRequestId = 0;
                            }
                        }
                    });
                viewerRenderQueue = scheduledRender.catch(() => {});
                return scheduledRender;
            }

            function isCurrentViewerRenderRequest(requestId) {
                return requestId === latestViewerRenderRequestId;
            }

            function getAcroFormEditorStateStorageKeys() {
                const keys = [];
                const currentSessionId = getStoredPdfSessionId({
                    includeUrl: true,
                    includeLegacyGlobal: loadedSavedPdfMode,
                });
                if (currentSessionId) {
                    keys.push(`pdf-acroform-editor-state-${documentId}-${currentSessionId}`);
                }
                keys.push(`pdf-acroform-editor-state-${documentId}-${overlayDocumentRevision}`);
                return Array.from(new Set(keys.filter(Boolean)));
            }

            function getAcroFormFieldStateKey(annotation) {
                const fieldName = String(annotation?.fieldName || '').trim();
                return fieldName || String(annotation?.id || '').trim();
            }

            function isTextAnnotation(annotation) {
                return String(annotation?.type || '').toLowerCase() === 'text';
            }

            function getAnnotationPageIndex(annotation) {
                const pageIndex = Number(annotation?.pageIndex);
                return Number.isInteger(pageIndex) && pageIndex >= 0 ? pageIndex : null;
            }

            function markAnnotationPageDirty(annotation) {
                if (!annotation || isFieldAnnotation(annotation)) {
                    return;
                }
                const pageIndex = getAnnotationPageIndex(annotation);
                if (pageIndex !== null) {
                    dirtyAnnotationPageIndices.add(pageIndex);
                }
            }

            function clearTextAnnotationRedrawTracking() {
                dirtyAnnotationPageIndices.clear();
                deletedAnnotationPageIndices.clear();
            }

            function getAcroFormFieldDescriptor(annotation) {
                return `${annotation?.fieldName || ''} ${annotation?.alternativeText || ''}`
                    .toLowerCase()
                    .replace(/[^a-z0-9]+/g, ' ')
                    .trim();
            }

            function isEinCombField(annotation) {
                const descriptor = getAcroFormFieldDescriptor(annotation);
                return descriptor.includes('eincomb')
                    || descriptor.includes(' employer identification number ')
                    || descriptor.startsWith('employer identification number ')
                    || descriptor.endsWith(' employer identification number')
                    || descriptor === 'employer identification number ein';
            }

            function normalizeAcroFormFieldValue(annotation, rawValue) {
                const fieldType = String(annotation?.fieldType || '').toUpperCase();
                if (fieldType === 'BTN') {
                    if (annotation?.radioButton) {
                        return String(rawValue || '').trim();
                    }
                    return !(rawValue === false
                        || rawValue == null
                        || rawValue === ''
                        || rawValue === 'Off'
                        || rawValue === 'false'
                        || rawValue === '0');
                }
                if (fieldType === 'CH') {
                    if (annotation?.multiSelect) {
                        const values = Array.isArray(rawValue) ? rawValue : (rawValue == null || rawValue === '' ? [] : [rawValue]);
                        return values.map((value) => String(value ?? ''));
                    }
                    if (Array.isArray(rawValue)) {
                        return String(rawValue[0] ?? '');
                    }
                    return String(rawValue ?? '');
                }
                if (Array.isArray(rawValue)) {
                    return rawValue.map((value) => String(value ?? '')).join('\n');
                }
                let normalizedValue = String(rawValue ?? '');
                if (fieldType === 'TX' && isEinCombField(annotation)) {
                    normalizedValue = normalizedValue.replace(/\D+/g, '');
                    const combLength = inferAcroFormCombLength(annotation);
                    if (combLength > 0) {
                        normalizedValue = normalizedValue.slice(0, combLength);
                    }
                }
                return normalizedValue;
            }

            function normalizeAcroFormFieldRect(rectLike) {
                if (!Array.isArray(rectLike) || rectLike.length < 4) {
                    return null;
                }
                const rect = rectLike
                    .slice(0, 4)
                    .map((value) => Number(value));
                return rect.every((value) => Number.isFinite(value)) ? rect : null;
            }

            function normalizeAcroFormFieldTextColor(colorLike) {
                if (typeof colorLike === 'string') {
                    const value = colorLike.trim();
                    if (!value) {
                        return null;
                    }
                    if (/^#[0-9a-f]{6}$/i.test(value)) {
                        return value.toLowerCase();
                    }
                    if (/^[0-9a-f]{6}$/i.test(value)) {
                        return `#${value.toLowerCase()}`;
                    }
                    return null;
                }

                if (Array.isArray(colorLike) && colorLike.length > 0) {
                    const values = colorLike.slice(0, 3).map((value) => Number(value));
                    if (!values.every((value) => Number.isFinite(value))) {
                        return null;
                    }
                    const rgb = values.map((value) => {
                        if (value <= 1) {
                            return Math.max(0, Math.min(255, Math.round(value * 255)));
                        }
                        return Math.max(0, Math.min(255, Math.round(value)));
                    });
                    while (rgb.length < 3) {
                        rgb.push(rgb[0]);
                    }
                    return `#${rgb.map((value) => value.toString(16).padStart(2, '0')).join('')}`;
                }

                return null;
            }

            function mergeAcroFormFieldStateEntryWithAnnotation(entry, annotation) {
                if (!entry || !annotation) {
                    return entry;
                }

                const key = getAcroFormFieldStateKey(annotation);
                const pageIndex = getAnnotationPageIndex(annotation);
                const rect = normalizeAcroFormFieldRect(annotation?.rect);
                const textColor = normalizeAcroFormFieldTextColor(
                    entry?.textColor
                    ?? annotation?.textColor
                    ?? annotation?.fontColor
                    ?? annotation?.color
                    ?? annotation?.defaultAppearanceData?.fontColor
                );

                return {
                    ...entry,
                    key: String(entry?.key || key || '').trim(),
                    fieldName: String(entry?.fieldName || annotation?.fieldName || key || '').trim(),
                    pageIndex: Number.isInteger(Number(entry?.pageIndex)) ? Number(entry.pageIndex) : (pageIndex !== null ? pageIndex : null),
                    fieldType: String(entry?.fieldType || annotation?.fieldType || '').toUpperCase(),
                    checkBox: Boolean(entry?.checkBox ?? annotation?.checkBox),
                    radioButton: Boolean(entry?.radioButton ?? annotation?.radioButton),
                    combo: Boolean(entry?.combo ?? annotation?.combo),
                    multiLine: Boolean(entry?.multiLine ?? annotation?.multiLine),
                    multiSelect: Boolean(entry?.multiSelect ?? annotation?.multiSelect),
                    exportValue: String(entry?.exportValue || annotation?.exportValue || '').trim(),
                    rect: normalizeAcroFormFieldRect(entry?.rect) || rect,
                    textColor,
                };
            }

            function createAcroFormFieldStateEntry(annotation, rawValue) {
                const key = getAcroFormFieldStateKey(annotation);
                const pageIndex = getAnnotationPageIndex(annotation);
                return {
                    key,
                    fieldName: String(annotation?.fieldName || key || '').trim(),
                    pageIndex: pageIndex !== null ? pageIndex : null,
                    fieldType: String(annotation?.fieldType || '').toUpperCase(),
                    checkBox: Boolean(annotation?.checkBox),
                    radioButton: Boolean(annotation?.radioButton),
                    combo: Boolean(annotation?.combo),
                    multiLine: Boolean(annotation?.multiLine),
                    multiSelect: Boolean(annotation?.multiSelect),
                    exportValue: String(annotation?.exportValue || '').trim(),
                    rect: normalizeAcroFormFieldRect(annotation?.rect),
                    textColor: normalizeAcroFormFieldTextColor(
                        annotation?.textColor
                        ?? annotation?.fontColor
                        ?? annotation?.color
                        ?? annotation?.defaultAppearanceData?.fontColor
                    ),
                    value: normalizeAcroFormFieldValue(annotation, rawValue),
                };
            }

            function areAcroFormFieldValuesEqual(left, right) {
                if (Array.isArray(left) || Array.isArray(right)) {
                    const leftValues = Array.isArray(left) ? left : [left];
                    const rightValues = Array.isArray(right) ? right : [right];
                    if (leftValues.length !== rightValues.length) {
                        return false;
                    }
                    return leftValues.every((value, index) => String(value ?? '') === String(rightValues[index] ?? ''));
                }
                if (typeof left === 'boolean' || typeof right === 'boolean') {
                    return Boolean(left) === Boolean(right);
                }
                return String(left ?? '') === String(right ?? '');
            }

            function persistAcroFormEditorState() {
                try {
                    if (acroFormFieldChanges.size === 0) {
                        getAcroFormEditorStateStorageKeys().forEach((storageKey) => {
                            sessionStorage.removeItem(storageKey);
                        });
                        return;
                    }
                    const serialized = JSON.stringify(Array.from(acroFormFieldChanges.values()));
                    getAcroFormEditorStateStorageKeys().forEach((storageKey) => {
                        sessionStorage.setItem(storageKey, serialized);
                    });
                } catch (error) {
                    console.warn('Failed to persist AcroForm editor state', error);
                }
            }

            function applyAcroFormEditorStateEntries(entries, { persist = false } = {}) {
                acroFormFieldChanges.clear();
                (Array.isArray(entries) ? entries : []).forEach((entry) => {
                    const key = String(entry?.key || entry?.fieldName || '').trim();
                    if (!key) {
                        return;
                    }
                    acroFormFieldChanges.set(key, {
                        key,
                        fieldName: String(entry?.fieldName || key).trim(),
                        pageIndex: Number.isInteger(Number(entry?.pageIndex)) ? Number(entry.pageIndex) : null,
                        fieldType: String(entry?.fieldType || '').toUpperCase(),
                        checkBox: Boolean(entry?.checkBox),
                        radioButton: Boolean(entry?.radioButton),
                        combo: Boolean(entry?.combo),
                        multiLine: Boolean(entry?.multiLine),
                        multiSelect: Boolean(entry?.multiSelect),
                        exportValue: String(entry?.exportValue || '').trim(),
                        rect: normalizeAcroFormFieldRect(entry?.rect),
                        textColor: normalizeAcroFormFieldTextColor(entry?.textColor),
                        value: entry?.value,
                    });
                });
                if (persist) {
                    persistAcroFormEditorState();
                }
            }

            function getAcroFormEntriesForSave() {
                return Array.from(acroFormFieldChanges.values()).sort((left, right) => (
                    String(left?.key || '').localeCompare(String(right?.key || ''))
                ));
            }

            function loadAcroFormEditorState() {
                try {
                    let raw = '';
                    for (const storageKey of getAcroFormEditorStateStorageKeys()) {
                        const candidate = sessionStorage.getItem(storageKey);
                        if (candidate) {
                            raw = candidate;
                            break;
                        }
                    }
                    if (!raw) {
                        return;
                    }
                    const parsed = JSON.parse(raw);
                    if (!Array.isArray(parsed)) {
                        return;
                    }
                    applyAcroFormEditorStateEntries(parsed, { persist: false });
                } catch (error) {
                    console.warn('Failed to restore AcroForm editor state', error);
                }
            }

            function clearAcroFormEditorState({ preserveDefaults = false } = {}) {
                acroFormFieldChanges.clear();
                if (!preserveDefaults) {
                    acroFormFieldDefaults.clear();
                }
                try {
                    getAcroFormEditorStateStorageKeys().forEach((storageKey) => {
                        sessionStorage.removeItem(storageKey);
                    });
                } catch (error) {
                    console.warn('Failed to clear AcroForm editor state', error);
                }
            }

            function ensureAcroFormFieldDefaultState(annotation) {
                const key = getAcroFormFieldStateKey(annotation);
                if (!key) {
                    return null;
                }
                const nextDefault = createAcroFormFieldStateEntry(annotation, annotation?.fieldValue);
                acroFormFieldDefaults.set(key, nextDefault);
                const existingChange = acroFormFieldChanges.get(key);
                if (existingChange && areAcroFormFieldValuesEqual(existingChange.value, nextDefault.value)) {
                    acroFormFieldChanges.delete(key);
                    persistAcroFormEditorState();
                }
                return nextDefault;
            }

            function getAcroFormFieldCurrentState(annotation) {
                const key = getAcroFormFieldStateKey(annotation);
                if (!key) {
                    return createAcroFormFieldStateEntry(annotation, annotation?.fieldValue);
                }
                const defaultEntry = ensureAcroFormFieldDefaultState(annotation) || createAcroFormFieldStateEntry(annotation, annotation?.fieldValue);
                const existingEntry = acroFormFieldChanges.get(key);
                if (!existingEntry) {
                    return defaultEntry;
                }
                const mergedEntry = mergeAcroFormFieldStateEntryWithAnnotation(existingEntry, annotation);
                const existingRect = normalizeAcroFormFieldRect(existingEntry?.rect);
                const mergedRect = normalizeAcroFormFieldRect(mergedEntry?.rect);
                const shouldRefreshEntry = (
                    !existingRect && Boolean(mergedRect)
                ) || (
                    !Number.isInteger(Number(existingEntry?.pageIndex))
                    && Number.isInteger(Number(mergedEntry?.pageIndex))
                );
                if (shouldRefreshEntry) {
                    acroFormFieldChanges.set(key, mergedEntry);
                    persistAcroFormEditorState();
                }
                return mergedEntry;
            }

            function updateAcroFormFieldCurrentValue(annotation, rawValue) {
                const key = getAcroFormFieldStateKey(annotation);
                if (!key) {
                    return;
                }
                const defaultEntry = ensureAcroFormFieldDefaultState(annotation) || createAcroFormFieldStateEntry(annotation, annotation?.fieldValue);
                const nextEntry = createAcroFormFieldStateEntry(annotation, rawValue);
                if (areAcroFormFieldValuesEqual(defaultEntry.value, nextEntry.value)) {
                    acroFormFieldChanges.delete(key);
                } else {
                    acroFormFieldChanges.set(key, nextEntry);
                }
                persistAcroFormEditorState();
            }

            function getAcroFormCombCharacters(value, maxLen) {
                const normalizedValue = String(value ?? '').replace(/[\r\n]+/g, '');
                const limit = Number.isFinite(Number(maxLen)) ? Math.max(0, Number(maxLen)) : 0;
                const characters = Array.from(normalizedValue);
                return limit > 0 ? characters.slice(0, limit) : characters;
            }

            function inferAcroFormCombLength(annotation) {
                const explicitMaxLen = Number(annotation?.maxLen);
                if (Number.isFinite(explicitMaxLen) && explicitMaxLen > 1) {
                    return explicitMaxLen;
                }

                const descriptor = `${annotation?.fieldName || ''} ${annotation?.alternativeText || ''}`
                    .toLowerCase()
                    .replace(/[^a-z0-9]+/g, ' ')
                    .trim();

                if (!descriptor) {
                    return 0;
                }

                if (descriptor.includes('social security') || descriptor.includes('ssn')) {
                    return 9;
                }
                if (descriptor.includes('zip code')) {
                    return 5;
                }
                if (descriptor.includes('date of birth')
                    || descriptor.includes('exp date')
                    || descriptor.includes('mmddyyyy')
                    || descriptor.includes('mm dd yyyy')
                    || descriptor.includes('mm/dd/yyyy')) {
                    return 8;
                }

                return 0;
            }

            function syncAcroFormCombPreview(preview, control, maxLen, placeholderText = '') {
                if (!(preview instanceof HTMLElement)) {
                    return;
                }

                const combDisplay = preview.querySelector('.acroform-preview-comb-display');
                if (!(combDisplay instanceof HTMLElement)) {
                    return;
                }

                const cells = Array.from(combDisplay.querySelectorAll('.acroform-preview-comb-cell'));
                const characters = getAcroFormCombCharacters(control?.value ?? '', maxLen);
                const placeholderCharacters = getAcroFormCombCharacters(placeholderText, maxLen);
                cells.forEach((cell, index) => {
                    const activeCharacter = characters[index] ?? '';
                    const placeholderCharacter = placeholderCharacters[index] ?? '';
                    const usePlaceholder = !activeCharacter && Boolean(placeholderCharacter);
                    cell.textContent = activeCharacter || placeholderCharacter || '';
                    cell.classList.toggle('is-filled', Boolean(activeCharacter));
                    cell.classList.toggle('is-placeholder', usePlaceholder);
                    const isActive = preview.classList.contains('is-focused')
                        && control instanceof HTMLInputElement
                        && typeof control.selectionStart === 'number'
                        && control.selectionStart === control.selectionEnd
                        && index === Math.min(control.selectionStart, Math.max(cells.length - 1, 0));
                    cell.classList.toggle('is-active', isActive);
                });
            }

            function moveAcroFormControlCaretToEnd(control) {
                if (
                    !(control instanceof HTMLInputElement || control instanceof HTMLTextAreaElement)
                    || typeof control.setSelectionRange !== 'function'
                ) {
                    return;
                }
                const valueLength = String(control.value || '').length;
                control.setSelectionRange(valueLength, valueLength);
            }

            function queueAcroFormControlCaretToEnd(control, afterMove = null) {
                if (!(control instanceof HTMLInputElement || control instanceof HTMLTextAreaElement)) {
                    return;
                }
                const run = () => {
                    moveAcroFormControlCaretToEnd(control);
                    if (typeof afterMove === 'function') {
                        afterMove();
                    }
                };
                requestAnimationFrame(() => {
                    run();
                    requestAnimationFrame(run);
                });
            }

            function hasAcroFormEditorChanges() {
                return acroFormFieldChanges.size > 0;
            }

            function getAcroFormChangedPageIndices() {
                const pageIndices = new Set();
                for (const entry of acroFormFieldChanges.values()) {
                    const pageIndex = Number(entry?.pageIndex);
                    if (Number.isInteger(pageIndex) && pageIndex >= 0) {
                        pageIndices.add(pageIndex);
                    }
                }
                return Array.from(pageIndices).sort((left, right) => left - right);
            }

            async function loadAcroFormEditorStateFromDatabase({ force = false } = {}) {
                const sessionId = getStoredPdfSessionId({
                    includeUrl: true,
                    includeLegacyGlobal: loadedSavedPdfMode,
                });
                if (!sessionId) {
                    return 0;
                }
                if (!force && !loadedSavedPdfMode && acroFormFieldChanges.size > 0) {
                    return acroFormFieldChanges.size;
                }

                const requestUrl = new URL(savedAcroFormStateUrl, window.location.origin);
                requestUrl.searchParams.set('session_id', sessionId);

                const response = await fetch(requestUrl.toString(), {
                    credentials: 'same-origin',
                    headers: {
                        Accept: 'application/json',
                    },
                });

                const payload = await response.json().catch(() => ({}));
                if (!response.ok || !payload?.success || !Array.isArray(payload.entries)) {
                    return 0;
                }

                if (payload?.session_id && String(payload.session_id).trim() !== '') {
                    setStoredPdfSessionId(payload.session_id);
                }

                applyAcroFormEditorStateEntries(payload.entries, { persist: true });
                return payload.entries.length;
            }

            loadAcroFormEditorState();

            if (loadedSavedPdfMode) {
                try {
                    sessionStorage.removeItem(overlayEditsStorageKey);
                    // Also clear shape annotations from sessionStorage so they don't
                    // duplicate with shapes loaded from DB in loadedSavedPdfMode.
                    sessionStorage.removeItem(annotationsStorageKey);
                } catch (storageError) {
                    console.warn('Failed to clear cached editor state for loaded saved PDF mode', storageError);
                }
            }

            function sanitizeOverlayStorageText(value) {
                if (value == null) return '';
                return String(value)
                    .replace(/\u00A0/g, ' ')
                    .replace(/\uFFFD/g, '')
                    .replace(/[\u200B\u200C\u200D\u2060\uFEFF]/g, '')
                    .replace(/[\uE000-\uF8FF]/g, '')
                    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
            }

            function normalizeOverlayStorageText(value) {
                return sanitizeOverlayStorageText(value).replace(/\s+/g, ' ').trim();
            }

            async function ensureOverlayExtractionDataLoaded() {
                if (Array.isArray(overlayExtractionData) && overlayExtractionData.length > 0) {
                    return overlayExtractionData;
                }

                const extractionResponse = await fetch(`${fitzExtractionDataUrl}?v=${Date.now()}`, {
                    credentials: 'same-origin',
                    headers: { Accept: 'application/json' },
                });
                const extractionData = await extractionResponse.json().catch(() => ({}));
                if (!extractionResponse.ok || !extractionData?.success || !Array.isArray(extractionData.extraction_data)) {
                    return [];
                }

                overlayExtractionData = resolveOverlayExtractionPages(extractionData);
                if (extractionData.embedded_fonts && typeof extractionData.embedded_fonts === 'object') {
                    overlayEmbeddedFonts = extractionData.embedded_fonts;
                    loadEmbeddedFontFaces(overlayEmbeddedFonts);
                }
                preloadExtractionFontFamilies(overlayExtractionData);
                populateFontDropdown();
                return overlayExtractionData;
            }

            function normalizePromotedDebugSearchText(value, { stripPunctuation = false } = {}) {
                let normalized = String(value ?? '')
                    .toLowerCase()
                    .replace(/\u00A0/g, ' ')
                    .replace(/[\u200B\u200C\u200D\u2060\uFEFF]/g, '')
                    .replace(/[‘’]/g, '\'')
                    .replace(/[“”]/g, '"')
                    .replace(/[–—]/g, '-')
                    .replace(/\s+/g, ' ')
                    .trim();

                if (stripPunctuation) {
                    normalized = normalized
                        .replace(/[^a-z0-9]+/g, ' ')
                        .replace(/\s+/g, ' ')
                        .trim();
                }

                return normalized;
            }

            function normalizePromotedDebugQuery(value) {
                return normalizePromotedDebugSearchText(value);
            }

            function promotedDebugValueMatchesQuery(value, normalizedQuery) {
                if (!normalizedQuery) {
                    return false;
                }

                const normalizedValue = normalizePromotedDebugSearchText(value);
                if (normalizedValue.includes(normalizedQuery)) {
                    return true;
                }

                const strippedQuery = normalizePromotedDebugSearchText(normalizedQuery, { stripPunctuation: true });
                if (!strippedQuery) {
                    return false;
                }

                const strippedValue = normalizePromotedDebugSearchText(value, { stripPunctuation: true });
                return strippedValue.includes(strippedQuery);
            }

            function serializePromotedDebugSpan(span) {
                if (!span || typeof span !== 'object') {
                    return null;
                }

                return {
                    text: String(span.text || ''),
                    rawText: String(span.rawText || span.text || ''),
                    font: String(span.font || ''),
                    fontSize: Number(span.fontSize ?? span.font_size) || 0,
                    fontWeight: String(span.fontWeight || span.font_weight || ''),
                    fontStyle: String(span.fontStyle || ''),
                    underline: Boolean(span.underline),
                    color: String(span.color || ''),
                    bbox: Array.isArray(span.bbox) ? span.bbox.map((value) => Number(value) || 0) : null,
                    origin: Array.isArray(span.origin) ? span.origin.map((value) => Number(value) || 0) : null,
                    direction: Array.isArray(span.direction) ? span.direction.map((value) => Number(value) || 0) : null,
                    writingMode: Number(span.writing_mode ?? span.writingMode) || 0,
                    rotation: Number(span.rotation) || 0,
                };
            }

            function serializePromotedDebugLineEntry(entry) {
                if (!entry || typeof entry !== 'object') {
                    return null;
                }

                return {
                    index: Number(entry.index) || 0,
                    text: String(entry.text || ''),
                    bbox: Array.isArray(entry.bbox) ? entry.bbox.map((value) => Number(value) || 0) : null,
                    spans: Array.isArray(entry.spans)
                        ? entry.spans.map((span) => serializePromotedDebugSpan(span)).filter(Boolean)
                        : [],
                };
            }

            function buildPromotedDebugLineReuseDiagnostics(lineEntries) {
                if (!Array.isArray(lineEntries)) {
                    return [];
                }

                const normalizeComparableLineText = (value) => String(value ?? '')
                    .replace(/\u00A0/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();

                return lineEntries.map((entry) => {
                    const geometryConsistent = promotedLineEntryHasConsistentSourceSpanGeometry(entry);
                    const currentLineText = sanitizePromotedExtractionLine(entry?.originalText || entry?.text || '');
                    const rebuiltLineText = Array.isArray(entry?.spans) && entry.spans.length > 0
                        ? buildPromotedLineTextFromSpans(entry)
                        : sanitizePromotedExtractionLine(entry?.text || '');
                    const normalizedCurrentLineText = normalizeComparableLineText(currentLineText);
                    const normalizedRebuiltLineText = normalizeComparableLineText(rebuiltLineText);
                    const canReuseExactSourceSpans = Boolean(
                        Array.isArray(entry?.spans)
                        && entry.spans.length > 0
                        && geometryConsistent
                        && (
                            normalizedCurrentLineText === ''
                            || normalizedCurrentLineText === normalizedRebuiltLineText
                        )
                    );

                    let reuseFailureReason = null;
                    if (Array.isArray(entry?.spans) && entry.spans.length > 0 && !canReuseExactSourceSpans) {
                        reuseFailureReason = geometryConsistent ? 'text_mismatch' : 'geometry';
                    }

                    return {
                        index: Number(entry?.index) || 0,
                        text: String(entry?.text || ''),
                        originalText: String(entry?.originalText || entry?.text || ''),
                        bbox: Array.isArray(entry?.bbox) ? entry.bbox.map((value) => Number(value) || 0) : null,
                        spanCount: Array.isArray(entry?.spans) ? entry.spans.length : 0,
                        geometryConsistent,
                        canReuseExactSourceSpans,
                        reuseFailureReason,
                        rebuiltLineText,
                        currentLineText,
                        normalizedRebuiltLineText,
                        normalizedCurrentLineText,
                    };
                });
            }

            function buildPromotedDebugLineEntriesFromSourceMeta(sourceMeta) {
                const sourceLineBBoxes = Array.isArray(sourceMeta?.sourceLineBBoxes)
                    ? sourceMeta.sourceLineBBoxes
                        .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        .map((bbox) => bbox.map((value) => Number(value) || 0))
                    : [];
                const sourceTextLines = Array.isArray(sourceMeta?.sourceTextLines)
                    ? sourceMeta.sourceTextLines.map((line) => String(line ?? ''))
                    : [];
                const sourceSpans = Array.isArray(sourceMeta?.sourceSpans)
                    ? sourceMeta.sourceSpans
                        .filter((span) => span && Array.isArray(span.bbox) && span.bbox.length >= 4)
                        .map((span) => ({
                            ...span,
                            bbox: span.bbox.map((value) => Number(value) || 0),
                        }))
                    : [];

                if (!sourceLineBBoxes.length || sourceLineBBoxes.length !== sourceTextLines.length) {
                    return [];
                }

                const lineEntries = sourceLineBBoxes.map((bbox, index) => ({
                    index,
                    bbox,
                    text: sourceTextLines[index] ?? '',
                    originalText: sourceTextLines[index] ?? '',
                    spans: [],
                }));

                assignPromotedSpansToLineEntries(lineEntries, sourceSpans);

                return lineEntries;
            }

            function serializePromotedDebugExtractedSource(source) {
                if (!source || typeof source !== 'object') {
                    return null;
                }

                return {
                    blockText: String(source.blockText || ''),
                    textLines: Array.isArray(source.textLines)
                        ? source.textLines.map((line) => String(line ?? ''))
                        : [],
                    sourceLineBBoxes: Array.isArray(source.sourceLineBBoxes)
                        ? source.sourceLineBBoxes.map((bbox) => (
                            Array.isArray(bbox) ? bbox.map((value) => Number(value) || 0) : null
                        )).filter(Boolean)
                        : [],
                    lineEntries: Array.isArray(source.lineEntries)
                        ? source.lineEntries.map((entry) => serializePromotedDebugLineEntry(entry)).filter(Boolean)
                        : [],
                    lineReuseDiagnostics: Array.isArray(source.lineEntries)
                        ? buildPromotedDebugLineReuseDiagnostics(source.lineEntries)
                        : [],
                    sourceSpans: Array.isArray(source.sourceSpans)
                        ? source.sourceSpans.map((span) => serializePromotedDebugSpan(span)).filter(Boolean)
                        : [],
                };
            }

            function serializePromotedDebugAnnotation(annotation) {
                const sourceMeta = typeof getPromotedAnnotationSourceMeta === 'function'
                    ? (getPromotedAnnotationSourceMeta(annotation) || {})
                    : {};

                return {
                    id: String(annotation?.id || ''),
                    key: String(annotation?.promotedSourceKey || ''),
                    text: String(annotation?.text || ''),
                    sourceTextLines: Array.isArray(sourceMeta?.sourceTextLines)
                        ? sourceMeta.sourceTextLines.map((line) => String(line ?? ''))
                        : [],
                    sourceLineBBoxes: Array.isArray(sourceMeta?.sourceLineBBoxes)
                        ? sourceMeta.sourceLineBBoxes.map((bbox) => (
                            Array.isArray(bbox) ? bbox.map((value) => Number(value) || 0) : null
                        )).filter(Boolean)
                        : [],
                    pageIndex: Number(annotation?.pageIndex) || 0,
                    pdfX: Number(annotation?.pdfX) || 0,
                    pdfY: Number(annotation?.pdfY) || 0,
                    pdfWidth: Number(annotation?.pdfWidth) || 0,
                    pdfHeight: Number(annotation?.pdfHeight) || 0,
                };
            }

            function serializeRuntimeDebugAnnotation(annotation) {
                const sourceMeta = typeof getPromotedAnnotationSourceMeta === 'function'
                    ? (getPromotedAnnotationSourceMeta(annotation) || {})
                    : {};
                const sourceLineEntries = buildPromotedDebugLineEntriesFromSourceMeta(sourceMeta);

                return {
                    id: String(annotation?.id || ''),
                    type: String(annotation?.type || 'text'),
                    key: String(annotation?.promotedSourceKey || ''),
                    text: String(annotation?.text || ''),
                    originalText: String(annotation?.originalText || ''),
                    pageIndex: Number(annotation?.pageIndex) || 0,
                    pdfX: Number(annotation?.pdfX) || 0,
                    pdfY: Number(annotation?.pdfY) || 0,
                    pdfWidth: Number(annotation?.pdfWidth) || 0,
                    pdfHeight: Number(annotation?.pdfHeight) || 0,
                    promotedFromExtraction: Boolean(annotation?.promotedFromExtraction),
                    promotedDirty: Boolean(annotation?.promotedDirty),
                    promotedSourcePage: Number(annotation?.promotedSourcePage) || 0,
                    promotedSourceBlockNum: Number(annotation?.promotedSourceBlockNum) || 0,
                    savedTextOverlay: Boolean(annotation?.savedTextOverlay),
                    savedDatabaseAnnotation: Boolean(annotation?.savedDatabaseAnnotation),
                    sourceTextLines: Array.isArray(sourceMeta?.sourceTextLines)
                        ? sourceMeta.sourceTextLines.map((line) => String(line ?? ''))
                        : [],
                    sourceLineBBoxes: Array.isArray(sourceMeta?.sourceLineBBoxes)
                        ? sourceMeta.sourceLineBBoxes.map((bbox) => (
                            Array.isArray(bbox) ? bbox.map((value) => Number(value) || 0) : null
                        )).filter(Boolean)
                        : [],
                    sourceSpans: Array.isArray(sourceMeta?.sourceSpans)
                        ? sourceMeta.sourceSpans.map((span) => serializePromotedDebugSpan(span)).filter(Boolean)
                        : [],
                    lineReuseDiagnostics: buildPromotedDebugLineReuseDiagnostics(sourceLineEntries),
                };
            }

            function collectPromotedDebugAnnotationMatchReasons(annotation, normalizedQuery) {
                const reasons = [];
                if (promotedDebugValueMatchesQuery(annotation?.id, normalizedQuery)) {
                    reasons.push('annotation.id');
                }
                if (promotedDebugValueMatchesQuery(annotation?.promotedSourceKey, normalizedQuery)) {
                    reasons.push('annotation.promotedSourceKey');
                }
                if (promotedDebugValueMatchesQuery(annotation?.text, normalizedQuery)) {
                    reasons.push('annotation.text');
                }
                return reasons;
            }

            function collectRuntimeDebugAnnotationMatchReasons(annotation, normalizedQuery) {
                const reasons = [];
                if (promotedDebugValueMatchesQuery(annotation?.id, normalizedQuery)) {
                    reasons.push('annotation.id');
                }
                if (promotedDebugValueMatchesQuery(annotation?.promotedSourceKey, normalizedQuery)) {
                    reasons.push('annotation.promotedSourceKey');
                }
                if (promotedDebugValueMatchesQuery(annotation?.text, normalizedQuery)) {
                    reasons.push('annotation.text');
                }
                if (promotedDebugValueMatchesQuery(annotation?.originalText, normalizedQuery)) {
                    reasons.push('annotation.originalText');
                }
                const sourceMeta = typeof getPromotedAnnotationSourceMeta === 'function'
                    ? getPromotedAnnotationSourceMeta(annotation)
                    : null;
                const joinedSourceTextLines = Array.isArray(sourceMeta?.sourceTextLines)
                    ? sourceMeta.sourceTextLines.map((line) => String(line ?? '')).join(' ')
                    : '';
                if ((sourceMeta?.sourceTextLines || []).some((line) => promotedDebugValueMatchesQuery(line, normalizedQuery))) {
                    reasons.push('annotation.sourceTextLines');
                }
                if (promotedDebugValueMatchesQuery(joinedSourceTextLines, normalizedQuery)) {
                    reasons.push('annotation.joinedSourceTextLines');
                }
                return reasons;
            }

            function collectPromotedDebugBlockMatchReasons(block, rawSource, trimmedSource, normalizedQuery, pageData) {
                const reasons = [];
                const blockSourceKey = `block-${Number(pageData?.page_number) || 0}-${Number(block?.block_num) || 0}`;

                if (promotedDebugValueMatchesQuery(blockSourceKey, normalizedQuery)) {
                    reasons.push('block.sourceKey');
                }
                if (promotedDebugValueMatchesQuery(block?.text, normalizedQuery)) {
                    reasons.push('block.text');
                }
                if ((rawSource?.textLines || []).some((line) => promotedDebugValueMatchesQuery(line, normalizedQuery))) {
                    reasons.push('raw.textLines');
                }
                if (promotedDebugValueMatchesQuery((rawSource?.textLines || []).join(' '), normalizedQuery)) {
                    reasons.push('raw.joinedTextLines');
                }
                if ((trimmedSource?.textLines || []).some((line) => promotedDebugValueMatchesQuery(line, normalizedQuery))) {
                    reasons.push('trimmed.textLines');
                }
                if (promotedDebugValueMatchesQuery((trimmedSource?.textLines || []).join(' '), normalizedQuery)) {
                    reasons.push('trimmed.joinedTextLines');
                }

                return Array.from(new Set(reasons));
            }

            function collectRuntimeAnnotationMatches(query, { limit = 50 } = {}) {
                const normalizedQuery = normalizePromotedDebugQuery(query);
                if (!normalizedQuery) {
                    throw new Error('A match string is required.');
                }

                const matches = [];
                let truncated = false;

                annotations.some((annotation) => {
                    const matchReasons = collectRuntimeDebugAnnotationMatchReasons(annotation, normalizedQuery);
                    if (!matchReasons.length) {
                        return false;
                    }

                    matches.push({
                        ...serializeRuntimeDebugAnnotation(annotation),
                        matchReasons,
                    });

                    if (matches.length >= Math.max(1, Number(limit) || 50)) {
                        truncated = true;
                        return true;
                    }

                    return false;
                });

                return {
                    totalMatches: matches.length,
                    truncated,
                    matches,
                };
            }

            function collectFitzExtractionMatchesAgainstPages(extractionPages, query, { limit = 50 } = {}) {
                const normalizedQuery = normalizePromotedDebugQuery(query);
                if (!normalizedQuery) {
                    throw new Error('A match string is required.');
                }

                const matches = [];
                let truncated = false;

                (Array.isArray(extractionPages) ? extractionPages : []).some((pageData) => {
                    const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];

                    return pageBlocks.some((block) => {
                        const rawSource = buildPromotedLineEntriesFromExtractionBlock(block, []);
                        const trimmedSource = trimPromotedLeadingBulletLeadInFromSourceBlock(block, pageData, rawSource);
                        const builtAnnotations = buildTextAnnotationsFromExtractionBlock(block, pageData, [], rawSource);
                        const built = builtAnnotations.map((annotation) => serializePromotedDebugAnnotation(annotation));
                        const matchingBuilt = builtAnnotations.reduce((carry, annotation) => {
                            const matchReasons = collectPromotedDebugAnnotationMatchReasons(annotation, normalizedQuery);
                            if (matchReasons.length > 0) {
                                carry.push({
                                    ...serializePromotedDebugAnnotation(annotation),
                                    matchReasons,
                                });
                            }
                            return carry;
                        }, []);
                        const blockMatchReasons = collectPromotedDebugBlockMatchReasons(
                            block,
                            rawSource,
                            trimmedSource,
                            normalizedQuery,
                            pageData
                        );

                        if (!matchingBuilt.length && !blockMatchReasons.length) {
                            return false;
                        }

                        matches.push({
                            pageNumber: Number(pageData?.page_number) || 0,
                            blockNum: Number(block?.block_num) || 0,
                            blockSourceKey: `block-${Number(pageData?.page_number) || 0}-${Number(block?.block_num) || 0}`,
                            matchReasons: blockMatchReasons,
                            blockText: String(block?.text || ''),
                            rawTextLines: Array.isArray(rawSource?.textLines)
                                ? rawSource.textLines.map((line) => String(line ?? ''))
                                : [],
                            trimmedTextLines: Array.isArray(trimmedSource?.textLines)
                                ? trimmedSource.textLines.map((line) => String(line ?? ''))
                                : [],
                            raw: serializePromotedDebugExtractedSource(rawSource),
                            trimmed: serializePromotedDebugExtractedSource(trimmedSource),
                            built,
                            matchingBuilt: matchingBuilt.length ? matchingBuilt : built,
                        });

                        if (matches.length >= Math.max(1, Number(limit) || 50)) {
                            truncated = true;
                            return true;
                        }

                        return false;
                    });
                });

                return {
                    totalMatches: matches.length,
                    truncated,
                    matches,
                };
            }

            window.pdfPromotedAnnotationDebugApi = {
                async getContext() {
                    const extractionPages = await ensureOverlayExtractionDataLoaded();

                    return {
                        documentId,
                        totalPages: Array.isArray(extractionPages) ? extractionPages.length : 0,
                    };
                },

                async inspectPromotedAnnotationMatches(query, options = {}) {
                    await bootstrapPromotedTextAnnotations({ force: false });
                    const extractionPages = await ensureOverlayExtractionDataLoaded();
                    const annotationResult = collectRuntimeAnnotationMatches(query, options);
                    const fitzResult = collectFitzExtractionMatchesAgainstPages(extractionPages, query, options);

                    return {
                        documentId,
                        query: String(query ?? ''),
                        normalizedQuery: normalizePromotedDebugQuery(query),
                        totalPages: Array.isArray(extractionPages) ? extractionPages.length : 0,
                        annotationMatchesCount: annotationResult.totalMatches,
                        fitzMatchesCount: fitzResult.totalMatches,
                        totalMatches: annotationResult.totalMatches + fitzResult.totalMatches,
                        truncated: Boolean(annotationResult.truncated || fitzResult.truncated),
                        annotationMatches: annotationResult.matches,
                        fitzMatches: fitzResult.matches,
                    };
                },
            };

            async function prepareEditablePdfSource({ forceRefresh = true } = {}) {
                const refreshParam = forceRefresh ? '1' : '0';
                const prepareResponse = await fetch(
                    `${prepareOverlayUrl}?force_refresh=${refreshParam}&v=${Date.now()}`,
                    {
                        method: 'POST',
                        credentials: 'same-origin',
                        headers: {
                            'X-CSRF-TOKEN': csrfToken,
                            'X-Requested-With': 'XMLHttpRequest',
                            'Accept': 'application/json',
                        },
                    }
                );

                if (!prepareResponse.ok) {
                    const errorText = await prepareResponse.text().catch(() => '');
                    throw new Error(
                        `Failed to prepare editable PDF source (${prepareResponse.status}): ${errorText.slice(0, 300)}`
                    );
                }

                return prepareResponse.json().catch(() => ({}));
            }

            async function syncBasePdfForPromotedEditTextMode() {
                if (loadedSavedPdfMode || overlayEditorActive || isImageDocument) {
                    return false;
                }

                const shouldUseCleanBase = annotations.some((annotation) => {
                    if (!annotation || !isTextAnnotationType(annotation)) {
                        return false;
                    }
                    return Boolean(annotation.promotedFromExtraction || annotation.savedTextOverlay);
                });
                const nextBasePdfUrl = shouldUseCleanBase ? cleanPdfUrl : pdfUrl;

                if (basePdfUrl === nextBasePdfUrl) {
                    return false;
                }

                if (shouldUseCleanBase) {
                    await prepareEditablePdfSource({ forceRefresh: true });
                }

                basePdfUrl = nextBasePdfUrl;
                pdfVersion = Date.now();
                await rerenderPdf();
                return true;
            }

            async function materializeSavedPdfSession(loadUrl, sessionId, fallbackEditUrl = '') {
                const normalizedSessionId = String(sessionId || '').trim();
                if (!normalizedSessionId) {
                    throw new Error('Saved PDF session is missing.');
                }

                const response = await fetch(loadUrl, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-CSRF-TOKEN': csrfToken,
                        'Accept': 'application/json',
                    },
                    body: JSON.stringify({
                        session_id: normalizedSessionId,
                    }),
                });

                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result?.success) {
                    throw new Error(result.message || `Failed to load saved PDF (${response.status})`);
                }

                const resolvedSessionId = String(result.session_id || normalizedSessionId).trim();
                if (resolvedSessionId) {
                    setStoredPdfSessionId(resolvedSessionId);
                }

                try {
                    sessionStorage.removeItem(overlayEditsStorageKey);
                    sessionStorage.removeItem(annotationsStorageKey);
                } catch (storageError) {
                    console.warn('Failed to clear session storage after loading saved PDF', storageError);
                }

                const destination = new URL(result.edit_url || fallbackEditUrl || window.location.pathname, window.location.origin);
                destination.searchParams.delete('loadedSavedPdf');
                if (resolvedSessionId) {
                    destination.searchParams.set('savedSession', resolvedSessionId);
                }
                destination.searchParams.set('savedSessionMaterialized', '1');

                window.location.replace(destination.toString());
                return true;
            }

            function overlayBboxesRoughlyMatch(a, b, tolerance = 6) {
                if (!Array.isArray(a) || !Array.isArray(b) || a.length < 4 || b.length < 4) {
                    return false;
                }
                return a.every((value, index) => Math.abs((Number(value) || 0) - (Number(b[index]) || 0)) <= tolerance);
            }

            function clearStaleOverlayEditStorage() {
                try {
                    const staleKeys = [];
                    for (let i = 0; i < sessionStorage.length; i++) {
                        const key = sessionStorage.key(i);
                        if (key && key.startsWith(overlayEditsStoragePrefix) && key !== overlayEditsStorageKey) {
                            staleKeys.push(key);
                        }
                    }
                    staleKeys.forEach((key) => sessionStorage.removeItem(key));
                } catch (err) {
                    console.warn('Failed to clear stale overlay edit storage', err);
                }
            }

            function buildOverlayExtractionEditIndex() {
                const extractionPages = Array.isArray(overlayExtractionData) ? overlayExtractionData : [];
                const index = new Map();

                extractionPages.forEach((page) => {
                    if (!page || !page.page_number) return;

                    const pageNumber = Number(page.page_number) || 0;
                    const pageBlocks = Array.isArray(page.blocks) ? page.blocks : [];
                    const pageWords = Array.isArray(page.words) ? page.words : [];

                    pageBlocks.forEach((block) => {
                        if (!block || block.block_num === undefined || block.block_num === null) return;
                        const blockText = Array.isArray(block.text_lines) && block.text_lines.length
                            ? block.text_lines.map((line) => sanitizeOverlayStorageText(line)).join('\n')
                            : sanitizeOverlayStorageText(block.text || '');
                        index.set(`block-${pageNumber}-${block.block_num}`, {
                            page_number: pageNumber,
                            text: blockText,
                            bbox: [
                                Number(block.left) || 0,
                                Number(block.top) || 0,
                                (Number(block.left) || 0) + (Number(block.width) || 0),
                                (Number(block.top) || 0) + (Number(block.height) || 0),
                            ],
                        });
                    });

                    pageWords.forEach((word, wordIndex) => {
                        if (!word) return;
                        index.set(`${pageNumber}-${wordIndex}`, {
                            page_number: pageNumber,
                            text: sanitizeOverlayStorageText(word.text || ''),
                            bbox: [
                                Number(word.left) || 0,
                                Number(word.top) || 0,
                                (Number(word.left) || 0) + (Number(word.width) || 0),
                                (Number(word.top) || 0) + (Number(word.height) || 0),
                            ],
                        });
                    });
                });

                return index;
            }

            function pruneOverlayEditsAgainstExtraction() {
                if (!(overlayEditedFields instanceof Map) || overlayEditedFields.size === 0) {
                    return;
                }

                const extractionIndex = buildOverlayExtractionEditIndex();
                if (extractionIndex.size === 0) {
                    return;
                }

                let removedCount = 0;
                Array.from(overlayEditedFields.entries()).forEach(([key, edit]) => {
                    const source = extractionIndex.get(String(key));
                    if (!source) {
                        overlayEditedFields.delete(key);
                        removedCount++;
                        return;
                    }

                    const samePage = !edit?.page_number || Number(edit.page_number) === Number(source.page_number);
                    const editOriginalText = normalizeOverlayStorageText(edit?.original_text || '');
                    const sourceText = normalizeOverlayStorageText(source.text || '');
                    const textMismatch = editOriginalText && sourceText && editOriginalText !== sourceText;
                    const bboxMismatch = Array.isArray(edit?.original_bbox)
                        && !overlayBboxesRoughlyMatch(edit.original_bbox, source.bbox);

                    if (!samePage || textMismatch || bboxMismatch) {
                        overlayEditedFields.delete(key);
                        removedCount++;
                    }
                });

                if (removedCount > 0) {
                    persistOverlayEdits();
                    updateOverlaySaveButton();
                    console.info(`[Overlay Debug] Dropped ${removedCount} stale overlay edit(s) for document revision ${overlayDocumentRevision}.`);
                }
            }

            /**
             * Get system font fallback stack for a given font family name.
             * Used as fallback after embedded PDF fonts for characters not in the subset.
             */
            const _getSystemFallback = (family) => {
                const lower = family.toLowerCase();
                const fallbacks = {
                    'arimo': '"Arimo", Arial, Helvetica, sans-serif',
                    'tinos': '"Tinos", "Times New Roman", Times, serif',
                    'cousine': '"Cousine", "Courier New", Courier, monospace',
                    'gelasio': '"Gelasio", Georgia, serif',
                    'georgia': '"Georgia", "Liberation Serif", serif',
                    'verdana': 'Verdana, Geneva, Arial, sans-serif',
                    'roboto': '"Roboto", Arial, Helvetica, sans-serif',
                    'nimbussans': 'Helvetica, Arial, sans-serif',
                    'tahoma': 'Tahoma, Arial, Verdana, sans-serif',
                    'tahomaunicode': 'Tahoma, Arial, Verdana, sans-serif',
                    'timesnewroman': 'Times New Roman, Times, serif',
                    'timesnewromanunicode': 'Times New Roman, Times, serif',
                    'times': 'Times New Roman, Times, serif',
                    'arial': 'Arial, Helvetica, sans-serif',
                    'helvetica': 'Helvetica, Arial, sans-serif',
                    'courier': '"Cousine", "Courier New", Courier, monospace',
                    'calibri': 'Calibri, sans-serif',
                };
                for (const [key, val] of Object.entries(fallbacks)) {
                    if (lower === key || lower.startsWith(key)) {
                        return val;
                    }
                }
                if (lower.includes('serif') && !lower.includes('sans')) return 'serif';
                if (lower.includes('mono')) return 'monospace';
                return 'Arial, sans-serif';
            };

            const normalizePdfEditableFontFamily = (fontName) => {
                if (!fontName) return '';
                let cleaned = String(fontName).replace(/['"]/g, '').trim();

                if (cleaned.includes('+')) {
                    const parts = cleaned.split('+', 2);
                    if (parts[0].length === 6) {
                        cleaned = parts[1];
                    }
                }

                if (/^[A-Za-z]{6}[A-Z]/.test(cleaned) && cleaned.length > 7) {
                    const withoutPrefix = cleaned.substring(6);
                    if (/^[A-Z][a-z]/.test(withoutPrefix)) {
                        cleaned = withoutPrefix;
                    }
                }

                const basePart = cleaned.split(/[-_,]/)[0] || cleaned;
                const weightSuffixes = [
                    'Thin', 'Hairline', 'ExtraLight', 'UltraLight', 'Light',
                    'Regular', 'Medium', 'SemiBold', 'DemiBold', 'Bold',
                    'ExtraBold', 'UltraBold', 'Black', 'Heavy',
                ];
                let family = basePart;
                for (const suffix of weightSuffixes) {
                    if (family.endsWith(suffix) && family.length > suffix.length) {
                        family = family.substring(0, family.length - suffix.length);
                        break;
                    }
                }

                return family.replace(/[,\s]+$/g, '').trim();
            };

            /**
             * Infer CSS font-stretch value from a PDF font name.
             * Detects abbreviated condensed/expanded suffixes like "Cn", "BlkCn", "Cond".
             */
            function extractFontStretchFromPdfFontName(fontName) {
                if (!fontName) return 'normal';
                const lower = String(fontName).toLowerCase();
                if (/condensed|narrow/.test(lower)) return 'condensed';
                if (/expanded|extended/.test(lower)) return 'expanded';
                const parts = lower.split(/[-_,+]/);
                for (const part of parts) {
                    if (part === 'cond' || part === 'cn' || part === 'cd'
                        || part.endsWith('cn') || part.endsWith('cd') || part.endsWith('cond')) {
                        return 'condensed';
                    }
                    if (part === 'ext' || part === 'expanded' || part === 'extended' || part === 'wide') {
                        return 'expanded';
                    }
                }
                return 'normal';
            }

            const normalizePdfExactFontName = (fontName) => {
                if (!fontName) return '';
                let cleaned = String(fontName).replace(/['"]/g, '').trim();

                if (/^PDF_/i.test(cleaned)) {
                    cleaned = cleaned.substring(4);
                }

                if (cleaned.includes('+')) {
                    const parts = cleaned.split('+', 2);
                    if (parts[0].length === 6) {
                        cleaned = parts[1];
                    }
                }

                if (/^[A-Za-z]{6}[A-Z]/.test(cleaned) && cleaned.length > 7) {
                    const withoutPrefix = cleaned.substring(6);
                    if (/^[A-Z][a-z]/.test(withoutPrefix)) {
                        cleaned = withoutPrefix;
                    }
                }

                return cleaned.replace(/[,\s]+$/g, '').trim();
            };

            function sanitizeOverlayText(value) {
                if (value == null) return '';
                return String(value)
                    .replace(/\u00A0/g, ' ')
                    .replace(/\uFFFD/g, '')
                    .replace(/[\u200B\u200C\u200D\u2060\uFEFF]/g, '')
                    .replace(/[\uE000-\uF8FF]/g, '')
                    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
            }

            function isFilledCircleSymbolSourceSpan(sourceSpan) {
                const normalizedFont = normalizePdfEditableFontFamily(sourceSpan?.font || '');
                const normalizedText = String(sourceSpan?.text || sourceSpan?.rawText || '').trim();
                return normalizedFont.toLowerCase() === 'europeanpistd'
                    && (normalizedText === '•' || normalizedText === '●');
            }

            function shouldRenderFilledCircleSymbolAsShape(sourceSpan, siblingSpans = []) {
                if (!isFilledCircleSymbolSourceSpan(sourceSpan)) {
                    return false;
                }

                const hasInlineTextNeighbors = (Array.isArray(siblingSpans) ? siblingSpans : []).some((candidate) => {
                    if (!candidate || candidate === sourceSpan) {
                        return false;
                    }
                    const candidateText = sanitizeOverlayText(String(
                        candidate?.text
                        ?? candidate?.render_text
                        ?? candidate?.rawText
                        ?? ''
                    ));
                    if (!candidateText) {
                        return false;
                    }
                    return !isFilledCircleSymbolSourceSpan(candidate);
                });

                return !hasInlineTextNeighbors;
            }

            function isAdobePiRightTriangleSourceSpan(sourceSpan) {
                const normalizedFont = normalizePdfEditableFontFamily(
                    sourceSpan?.embedded_font_name || sourceSpan?.font || ''
                );
                const normalizedText = String(sourceSpan?.text || sourceSpan?.rawText || '').trim();
                const spanBBox = Array.isArray(sourceSpan?.bbox) && sourceSpan.bbox.length >= 4
                    ? sourceSpan.bbox
                    : null;
                if (!spanBBox) {
                    return false;
                }
                const spanWidth = Math.max(0, (Number(spanBBox[2]) || 0) - (Number(spanBBox[0]) || 0));
                const spanHeight = Math.max(0, (Number(spanBBox[3]) || 0) - (Number(spanBBox[1]) || 0));
                const aspectRatio = spanWidth > 0 ? (spanHeight / spanWidth) : 0;
                return normalizedFont.toLowerCase() === 'adobepistd'
                    && normalizedText === '▲'
                    && aspectRatio >= 2.2;
            }

            function applyAdobePiRightTriangleSpanStyles(
                element,
                sourceSpan,
                {
                    scale = 1,
                    scaleX = scale,
                    scaleY = scale,
                    absolute = false,
                    lineLeft = 0,
                    lineTop = 0,
                    fallbackColor = '#000000',
                } = {}
            ) {
                const spanBBox = Array.isArray(sourceSpan?.bbox) && sourceSpan.bbox.length >= 4
                    ? sourceSpan.bbox
                    : null;
                if (!(element instanceof HTMLElement) || !spanBBox) {
                    return false;
                }

                const spanLeft = Number(spanBBox[0]) || 0;
                const spanTop = Number(spanBBox[1]) || 0;
                const spanRight = Number(spanBBox[2]) || spanLeft;
                const spanBottom = Number(spanBBox[3]) || spanTop;
                const spanWidth = Math.max(1, spanRight - spanLeft);
                const spanHeight = Math.max(1, spanBottom - spanTop);
                const color = getExactSourceSpanCssColor(sourceSpan, fallbackColor);

                element.textContent = '';
                element.style.whiteSpace = 'normal';
                element.style.padding = '0';
                element.style.margin = '0';
                element.style.width = `${spanWidth * scaleX}px`;
                element.style.height = `${spanHeight * scaleY}px`;
                element.style.minWidth = `${spanWidth * scaleX}px`;
                element.style.minHeight = `${spanHeight * scaleY}px`;
                element.style.lineHeight = '0';
                element.style.backgroundColor = color;
                element.style.color = 'transparent';
                element.style.fontSize = '0';
                element.style.textDecoration = 'none';
                element.style.boxSizing = 'border-box';
                element.style.clipPath = 'polygon(0 0, 100% 50%, 0 100%)';
                element.style.webkitClipPath = 'polygon(0 0, 100% 50%, 0 100%)';

