                        .map((index) => {
                            const text = sanitizePromotedExtractionLine(rawTextLines[index]);
                            const bbox = Array.isArray(block.line_bboxes[index]) && block.line_bboxes[index].length >= 4
                                ? block.line_bboxes[index].map((value) => Number(value) || 0)
