                    textLines: resolvedTextLines,
                    sourceLineBBoxes,
                    sourceSpans,
                    lineEntries,
                    excludedLineEntries,
                    transferredMarkerEntries: Array.isArray(transferredMarkerEntries) ? transferredMarkerEntries : [],
