                        return buildPromotedComparableLineEntriesForBlock(candidateBlock).some((entry) => {
                            const entryText = String(entry?.text || '').replace(/\u00A0/g, ' ').trim().toLowerCase();
                            if (!entryText || !rowMatch(bbox, entry?.bbox || [])) {
