            }

            function buildPromotedInlineRightLabelSpanSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length !== 1) {
