                    .filter((span) => Array.isArray(span?.bbox) && span.bbox.length >= 4)
                    .slice()
                    .sort((leftSpan, rightSpan) => (Number(leftSpan?.bbox?.[0]) || 0) - (Number(rightSpan?.bbox?.[0]) || 0));
                if (!lineBBox || sortedSpans.length < 3) {
