                    return [
                        Math.min(...validSpans.map((span) => Number(span.bbox[0]) || 0)),
                        Math.min(...validSpans.map((span) => Number(span.bbox[1]) || 0)),
                        Math.max(...validSpans.map((span) => Number(span.bbox[2]) || 0)),
                        Math.max(...validSpans.map((span) => Number(span.bbox[3]) || 0)),
