                    const endBox = endSpan?.bbox;
                    const endLeft = Number(endBox?.[0]) || 0;
                    const endRight = Number(endBox?.[2]) || endLeft;
                    if (endLeft < lineLeft + (lineWidth * 0.58) || (lineRight - endRight) > Math.max(80, lineWidth * 0.18)) {
