                    leaderAfterSpans.push(span);
                }
                const leaderSpans = leaderBeforeSpans.length ? leaderBeforeSpans : leaderAfterSpans;
                if (!leaderSpans.length) {
                    return [];
                }

                const leftSpanEndIndex = leaderBeforeSpans.length ? (labelStartIndex - leaderBeforeSpans.length) : labelStartIndex;
                const leftSpans = sortedSpans.slice(0, leftSpanEndIndex).filter((span) => !looksLikeLeaderSpan(span));
                const trailingTextSpans = sortedSpans
                    .slice(labelEndIndex + leaderAfterSpans.length + 1)
                    .filter((span) => /[A-Za-z0-9]/.test(normalizeSpanText(span)));
                if (!leftSpans.length || trailingTextSpans.length) {
                    return [];
                }

                const leftText = sanitizePromotedExtractionLine(leftSpans.map((span) => normalizeSpanText(span)).join(' '));
                if (!leftText || !/[A-Za-z]/.test(leftText)) {
                    return [];
                }

                const leftBBox = unionBBox(leftSpans);
                const labelBBox = unionBBox(labelSpans);
                if (!leftBBox || !labelBBox) {
                    return [];
                }
                const gap = (Number(labelBBox[0]) || 0) - (Number(leftBBox[2]) || 0);
                if (gap < 36) {
                    return [];
                }

                const splitAnnotations = [
                    buildSpanClusterAnnotation(leftSpans, `inline-right-label-left-${Number(lineEntry?.index) || 0}`, () => leftText),
                    buildSpanClusterAnnotation(labelSpans, `inline-right-label-label-${Number(lineEntry?.index) || 0}`, () => labelText),
                    buildSpanClusterAnnotation(leaderSpans, `inline-right-label-leader-${Number(lineEntry?.index) || 0}`),
                ].filter(Boolean);

                return splitAnnotations.length >= 2 ? splitAnnotations : [];
            }

            function findPromotedSiblingMarkerLineForTextEntry(textEntry, sourceBlock, pageBlocks) {
                const textBox = Array.isArray(textEntry?.bbox) ? textEntry.bbox : [0, 0, 0, 0];
                const textLeft = Number(textBox[0]) || 0;
                let bestMatch = null;

                (Array.isArray(pageBlocks) ? pageBlocks : []).forEach((candidateBlock) => {
                    if (!candidateBlock || candidateBlock === sourceBlock) {
                        return;
                    }

                    buildPromotedComparableLineEntriesForBlock(candidateBlock).forEach((candidateEntry) => {
                        if (!promotedLineEntryLooksLikeStandaloneBullet(candidateEntry)) {
                            return;
                        }
                        if (!promotedEntriesShareVisualRow(textEntry, candidateEntry)) {
                            return;
                        }

                        const candidateBox = Array.isArray(candidateEntry?.bbox) ? candidateEntry.bbox : [0, 0, 0, 0];
                        const candidateRight = Number(candidateBox[2]) || 0;
                        const gap = textLeft - candidateRight;
                        if (gap < 6 || gap > 80) {
                            return;
                        }

                        if (!bestMatch || gap < bestMatch.gap) {
                            bestMatch = { entry: candidateEntry, gap };
                        }
                    });
                });

                return bestMatch;
            }

            function findPromotedSiblingCompactLabelLineForTextEntry(textEntry, sourceBlock, pageBlocks) {
                const textBox = Array.isArray(textEntry?.bbox) ? textEntry.bbox : [0, 0, 0, 0];
                const textLeft = Number(textBox[0]) || 0;
                const textRight = Number(textBox[2]) || textLeft;
                let bestMatch = null;

                (Array.isArray(pageBlocks) ? pageBlocks : []).forEach((candidateBlock) => {
                    if (!candidateBlock || candidateBlock === sourceBlock) {
                        return;
                    }

                    buildPromotedComparableLineEntriesForBlock(candidateBlock).forEach((candidateEntry) => {
                        if (!promotedLineEntryLooksLikeCompactLabel(candidateEntry)) {
                            return;
                        }
                        if (!promotedEntriesShareVisualRow(textEntry, candidateEntry)) {
                            return;
                        }

                        const candidateBox = Array.isArray(candidateEntry?.bbox) ? candidateEntry.bbox : [0, 0, 0, 0];
                        const candidateLeft = Number(candidateBox[0]) || 0;
                        const candidateRight = Number(candidateBox[2]) || candidateLeft;
                        const gapToRight = candidateLeft - textRight;
                        const gapToLeft = textLeft - candidateRight;
                        const gap = gapToRight >= 0 ? gapToRight : gapToLeft;
                        const side = gapToRight >= 0 ? 'right' : 'left';
                        if (gap < 6 || gap > 80) {
                            return;
                        }

                        if (!bestMatch || gap < bestMatch.gap) {
                            bestMatch = {
                                entry: candidateEntry,
                                gap,
                                side,
                            };
                        }
                    });
                });

                return bestMatch;
            }

            function findPromotedSiblingTextLineForRightAlignedLabelEntry(labelEntry, sourceBlock, pageBlocks) {
                if (!promotedLineEntryLooksLikeRightAlignedFormLabel(labelEntry)) {
                    return null;
                }

                const labelBox = Array.isArray(labelEntry?.bbox) ? labelEntry.bbox : [0, 0, 0, 0];
                const labelLeft = Number(labelBox[0]) || 0;
                let bestMatch = null;

                (Array.isArray(pageBlocks) ? pageBlocks : []).forEach((candidateBlock) => {
                    if (!candidateBlock || candidateBlock === sourceBlock) {
                        return;
                    }

                    buildPromotedComparableLineEntriesForBlock(candidateBlock).forEach((candidateEntry) => {
                        const candidateText = String(candidateEntry?.text || '').trim();
                        if (
                            !candidateText
                            || promotedLineEntryLooksLikeLeaderOnly(candidateEntry)
                            || promotedLineEntryLooksLikeRightAlignedFormLabel(candidateEntry)
                        ) {
                            return;
                        }
                        if (!promotedEntriesShareVisualRow(candidateEntry, labelEntry)) {
                            return;
                        }

                        const candidateBox = Array.isArray(candidateEntry?.bbox) ? candidateEntry.bbox : [0, 0, 0, 0];
                        const candidateRight = Number(candidateBox[2]) || 0;
                        const gap = labelLeft - candidateRight;
                        if (gap < 24 || gap > 220) {
                            return;
                        }

                        if (!bestMatch || gap < bestMatch.gap) {
                            bestMatch = {
                                block: candidateBlock,
                                entry: candidateEntry,
                                gap,
                            };
                        }
                    });
                });

                return bestMatch;
            }

            function buildPromotedSyntheticLeaderAnnotationForRightAlignedLabelBlock(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length !== 1) {
                    return null;
                }

                const labelEntry = lineEntries[0];
                if (!promotedLineEntryLooksLikeRightAlignedFormLabel(labelEntry)) {
                    return null;
                }

                const siblingMatch = findPromotedSiblingTextLineForRightAlignedLabelEntry(labelEntry, block, pageData?.blocks || []);
                if (!siblingMatch?.entry) {
                    return null;
                }

                const textBox = Array.isArray(siblingMatch.entry?.bbox) ? siblingMatch.entry.bbox : [0, 0, 0, 0];
                const labelBox = Array.isArray(labelEntry?.bbox) ? labelEntry.bbox : [0, 0, 0, 0];
                const textRight = Number(textBox[2]) || 0;
                const labelLeft = Number(labelBox[0]) || textRight;
                const gap = labelLeft - textRight;
                if (gap < 80) {
                    return null;
                }

                const lineTop = Math.min(Number(textBox[1]) || 0, Number(labelBox[1]) || 0);
                const lineHeight = Math.max(
                    1,
                    Number(textBox[3]) - Number(textBox[1]) || 0,
                    Number(labelBox[3]) - Number(labelBox[1]) || 0
                );
                const leaderTop = lineTop + (lineHeight * 0.705);
                const leaderHeight = Math.max(0.888, lineHeight * 0.111);
                const leaderLeft = textRight + 10;
                const leaderRight = labelLeft - 10;
                if ((leaderRight - leaderLeft) < 80) {
                    return null;
                }

                const leaderDotCount = Math.max(12, Math.min(32, Math.round((leaderRight - leaderLeft) / 12)));
                const leaderText = Array.from({ length: leaderDotCount }, () => '.').join(' ');
                const leaderBBox = [leaderLeft, leaderTop, leaderRight, leaderTop + leaderHeight];
                const leaderSpan = buildSyntheticPromotedSpanFromBlockLine(block, leaderText, leaderBBox);
                if (!leaderSpan) {
                    return null;
                }

                return buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: [leaderText],
                    sourceLineBBoxes: [leaderBBox],
                    sourceSpans: [leaderSpan],
                    sourceKeySuffix: `leader-for-${normalizePromotedRightAlignedFormLabelText(labelEntry?.text || '').replace(/[^a-z0-9_-]+/gi, '_') || 'label'}`,
                });
            }

            function buildPromotedSiblingCompactLabelAlignedLineSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const nonEmptyEntries = lineEntries.filter((entry) => String(entry?.text || '').trim() !== '');
                if (nonEmptyEntries.length < 2) {
                    return [];
                }

                const labelMatches = nonEmptyEntries.map((entry) => findPromotedSiblingCompactLabelLineForTextEntry(entry, block, pageData?.blocks || []));
                if (!labelMatches.every(Boolean)) {
                    return [];
                }

                const preferredSide = labelMatches[0]?.side || '';
                if (!preferredSide || !labelMatches.every((match) => match?.side === preferredSide)) {
                    return [];
                }

                const labelLefts = labelMatches.map((match) => Number(match?.entry?.bbox?.[0]) || 0);
                const labelRights = labelMatches.map((match) => Number(match?.entry?.bbox?.[2]) || 0);
                if ((Math.max(...labelLefts) - Math.min(...labelLefts)) > 18 || (Math.max(...labelRights) - Math.min(...labelRights)) > 18) {
                    return [];
                }

                return nonEmptyEntries.map((entry) => buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: [entry.text],
                    sourceLineBBoxes: [entry.bbox],
                    sourceSpans: Array.isArray(entry?.spans) ? entry.spans : [],
                    sourceKeySuffix: `label-aligned-line-${Number(entry?.index) || 0}`,
                })).filter(Boolean);
            }

            function buildPromotedMarkerAlignedLineSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const nonEmptyEntries = lineEntries.filter((entry) => String(entry?.text || '').trim() !== '');
                if (nonEmptyEntries.length < 2) {
                    return [];
                }

                const markerMatches = nonEmptyEntries.map((entry) => findPromotedSiblingMarkerLineForTextEntry(entry, block, pageData?.blocks || []));
                if (!markerMatches.every(Boolean)) {
                    return [];
                }

                return nonEmptyEntries.map((entry) => buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: [entry.text],
                    sourceLineBBoxes: [entry.bbox],
                    sourceSpans: Array.isArray(entry?.spans) ? entry.spans : [],
                    sourceKeySuffix: `marker-aligned-line-${Number(entry?.index) || 0}`,
                })).filter(Boolean);
            }

            function buildPromotedRightLabelLeaderLineSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const nonEmptyEntries = lineEntries.filter((entry) => String(entry?.text || '').trim() !== '');
                if (nonEmptyEntries.length < 2) {
                    return [];
                }

                const hasBulletRow = nonEmptyEntries.some((entry) => /^(?:•|●|◦|▪|■|○)\s+\S/.test(String(entry?.text || '').trim()));
                const hasRightLabel = nonEmptyEntries.some((entry) => promotedLineEntryLooksLikeRightAlignedFormLabel(entry));
                const hasLeaderOnlyLine = nonEmptyEntries.some((entry) => promotedLineEntryLooksLikeLeaderOnly(entry));
                if (!hasBulletRow || !hasRightLabel || !hasLeaderOnlyLine) {
                    return [];
                }

                const splitAnnotations = [];
                let currentTextCluster = [];
                const flushTextCluster = () => {
                    if (!currentTextCluster.length) {
                        return;
                    }
                    const clusterStartIndex = Number(currentTextCluster[0]?.index) || 0;
                    const clusterEndIndex = Number(currentTextCluster[currentTextCluster.length - 1]?.index) || clusterStartIndex;
                    const clusterExtractedSource = {
                        blockText: currentTextCluster.map((entry) => entry.text).join('\n'),
                        textLines: currentTextCluster.map((entry) => entry.text),
                        sourceLineBBoxes: currentTextCluster.map((entry) => entry.bbox),
                        sourceSpans: currentTextCluster.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                        lineEntries: currentTextCluster.map((entry, entryIndex) => ({
                            index: entryIndex,
                            text: entry.text,
                            bbox: entry.bbox,
                            spans: Array.isArray(entry?.spans) ? entry.spans : [],
                        })),
                        excludedLineEntries: [],
                        transferredMarkerEntries: [],
                        sourceKeySuffix: `label-leader-text-lines-${clusterStartIndex}-${clusterEndIndex}`,
                    };
                    splitAnnotations.push(...buildTextAnnotationsFromExtractionBlock(block, pageData, [], clusterExtractedSource));
                    currentTextCluster = [];
                };

                nonEmptyEntries.forEach((entry) => {
                    if (promotedLineEntryLooksLikeRightAlignedFormLabel(entry) || promotedLineEntryLooksLikeLeaderOnly(entry)) {
                        flushTextCluster();
                        const annotation = buildPromotedTextAnnotationFromSource(block, pageData, {
                            textLines: [entry.text],
                            sourceLineBBoxes: [entry.bbox],
                            sourceSpans: Array.isArray(entry?.spans) ? entry.spans : [],
                            sourceKeySuffix: promotedLineEntryLooksLikeRightAlignedFormLabel(entry)
                                ? `label-line-${Number(entry?.index) || 0}`
                                : `leader-line-${Number(entry?.index) || 0}`,
                        });
                        if (annotation) {
                            splitAnnotations.push(annotation);
                        }
                        return;
                    }
                    currentTextCluster.push(entry);
                });
                flushTextCluster();

                return splitAnnotations.length > 1 ? splitAnnotations : [];
            }

            function buildPromotedInlineBulletRowSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const nonEmptyEntries = lineEntries.filter((entry) => String(entry?.text || '').trim() !== '');
                if (nonEmptyEntries.length < 2) {
                    return [];
                }

                const bulletRowStartIndexes = lineEntries
                    .map((entry) => {
                        const text = String(entry?.text || '').replace(/\u00A0/g, ' ').trim();
                        if (!text || promotedLineEntryLooksLikeLeaderOnly(entry) || promotedLineEntryLooksLikeRightAlignedFormLabel(entry)) {
                            return -1;
                        }
                        return /^(?:\(?\d+[A-Za-z]?\)?[.)]?\s+)?(?:•|●|◦|▪|■|○)\s+\S/.test(text)
                            ? (Number(entry?.index) || 0)
                            : -1;
                    })
                    .filter((index) => index >= 0);
                if (bulletRowStartIndexes.length < 2) {
                    return [];
                }

                const clusters = [];
                const firstStartIndex = bulletRowStartIndexes[0];
                if (firstStartIndex > 0) {
                    const leadingCluster = lineEntries
                        .slice(0, firstStartIndex)
                        .filter((entry) => String(entry?.text || '').trim() !== '');
                    if (leadingCluster.length > 0) {
                        clusters.push(leadingCluster);
                    }
                }

                bulletRowStartIndexes.forEach((startIndex, index) => {
                    const nextStartIndex = index + 1 < bulletRowStartIndexes.length ? bulletRowStartIndexes[index + 1] : lineEntries.length;
                    const cluster = lineEntries
                        .slice(startIndex, nextStartIndex)
                        .filter((entry) => String(entry?.text || '').trim() !== '');
                    if (cluster.length > 0) {
                        clusters.push(cluster);
                    }
                });
                if (clusters.length < 2) {
                    return [];
                }

                const expectedIndexes = nonEmptyEntries.map((entry) => Number(entry?.index) || 0);
                const actualIndexes = clusters.flatMap((cluster) => cluster.map((entry) => Number(entry?.index) || 0));
                if (
                    actualIndexes.length !== expectedIndexes.length
                    || actualIndexes.some((value, index) => value !== expectedIndexes[index])
                ) {
                    return [];
                }

                return clusters.map((cluster, clusterIndex) => {
                    const clusterStartIndex = Number(cluster[0]?.index) || 0;
                    const clusterEndIndex = Number(cluster[cluster.length - 1]?.index) || 0;
                    return buildPromotedTextAnnotationFromSource(block, pageData, {
                        textLines: cluster.map((entry) => entry.text),
                        sourceLineBBoxes: cluster.map((entry) => entry.bbox),
                        sourceSpans: cluster.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                        sourceKeySuffix: `inline-bullet-lines-${clusterIndex}-${clusterStartIndex}-${clusterEndIndex}`,
                    });
                }).filter(Boolean);
            }

            function buildPromotedNumberedItemSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const isNumberedStart = (entry) => {
                    const text = String(entry?.text || '').replace(/\u00A0/g, ' ').trim();
                    if (!text) {
                        return false;
                    }
                    return /^\(?\d+[A-Za-z]?(?:\.[A-Za-z])?(?:,\s*\d+[A-Za-z]?(?:\.[A-Za-z])?)*[.)]?\s/.test(text);
                };

                const startIndexes = lineEntries
                    .map((entry, index) => ({ entry, index }))
                    .filter(({ entry }) => isNumberedStart(entry))
                    .map(({ index }) => index);
                if (startIndexes.length < 2) {
                    return [];
                }

                const clusters = startIndexes.map((startIndex, index) => {
                    const nextStartIndex = index + 1 < startIndexes.length ? startIndexes[index + 1] : lineEntries.length;
                    return lineEntries
                        .slice(startIndex, nextStartIndex)
                        .filter((entry) => String(entry?.text || '').trim() !== '');
                }).filter((cluster) => cluster.length > 0);
                if (clusters.length < 2) {
                    return [];
                }

                return clusters.map((cluster, clusterIndex) => buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: cluster.map((entry) => entry.text),
                    sourceLineBBoxes: cluster.map((entry) => entry.bbox),
                    sourceSpans: cluster.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                    sourceKeySuffix: `numbered-lines-${clusterIndex}-${Number(cluster[0]?.index) || 0}-${Number(cluster[cluster.length - 1]?.index) || 0}`,
                })).filter(Boolean);
            }

            function buildPromotedLeadingHeadingSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 2) {
                    return [];
                }

                const headingCluster = [lineEntries[0]];
                const bodyCluster = lineEntries.slice(1);
                if (!promotedClusterLooksLikeSectionHeading(headingCluster) || !promotedClusterLooksLikeBodyCopy(bodyCluster)) {
                    return [];
                }

                const splitTrailingLabelEntries = (entries) => {
                    if (!Array.isArray(entries) || entries.length < 4) {
                        return null;
                    }
                    const labelEntry = entries[entries.length - 1];
                    const labelText = String(labelEntry?.text || '').replace(/\u00A0/g, ' ').trim();
                    if (!labelText || !/:$/.test(labelText) || labelText.length > 72) {
                        return null;
                    }
                    const labelWords = labelText.split(/\s+/).filter(Boolean);
                    if (labelWords.length > 12) {
                        return null;
                    }
                    const previousEntries = entries.slice(0, -1);
                    const labelBox = Array.isArray(labelEntry?.bbox) ? labelEntry.bbox : [0, 0, 0, 0];
                    const labelWidth = Math.max(0, (Number(labelBox[2]) || 0) - (Number(labelBox[0]) || 0));
                    const maxPreviousWidth = Math.max(...previousEntries.map((entry) => {
                        const bbox = Array.isArray(entry?.bbox) ? entry.bbox : [0, 0, 0, 0];
                        return Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0));
                    }));
                    if (labelWidth <= 0 || maxPreviousWidth <= 0 || labelWidth > (maxPreviousWidth * 0.8)) {
                        return null;
                    }
                    return {
                        bodyEntries: previousEntries,
                        trailingLabelEntries: [labelEntry],
                    };
                };

                const trailingLabelSplit = splitTrailingLabelEntries(bodyCluster);
                const renderClusterAnnotation = (entries, suffix) => buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: entries.map((entry) => entry.text),
                    sourceLineBBoxes: entries.map((entry) => entry.bbox),
                    sourceSpans: entries.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                    sourceKeySuffix: suffix,
                });

                const headingAnnotation = renderClusterAnnotation(
                    headingCluster,
                    `heading-lines-${Number(headingCluster[0]?.index) || 0}`
                );
                if (!trailingLabelSplit) {
                    const bodyAnnotation = renderClusterAnnotation(
                        bodyCluster,
                        `body-lines-${Number(bodyCluster[0]?.index) || 1}-${Number(bodyCluster[bodyCluster.length - 1]?.index) || bodyCluster.length}`
                    );
                    return [headingAnnotation, bodyAnnotation].filter(Boolean);
                }

                const bodyAnnotation = renderClusterAnnotation(
                    trailingLabelSplit.bodyEntries,
                    `body-lines-${Number(trailingLabelSplit.bodyEntries[0]?.index) || 1}-${Number(trailingLabelSplit.bodyEntries[trailingLabelSplit.bodyEntries.length - 1]?.index) || bodyCluster.length}`
                );
                const trailingLabelAnnotation = renderClusterAnnotation(
                    trailingLabelSplit.trailingLabelEntries,
                    `label-lines-${Number(trailingLabelSplit.trailingLabelEntries[0]?.index) || bodyCluster.length}`
                );

                return [headingAnnotation, bodyAnnotation, trailingLabelAnnotation].filter(Boolean);
            }

            function buildPromotedEmbeddedHeadingSplitAnnotations(block, pageData, extractedSource) {
                const lineEntries = Array.isArray(extractedSource?.lineEntries) ? extractedSource.lineEntries : [];
                if (lineEntries.length < 3) {
                    return [];
                }

                const lineLooksLikeEmbeddedHeadingLead = (entry) => {
                    if (promotedClusterLooksLikeSectionHeading([entry])) {
                        return true;
                    }
                    const normalized = String(entry?.text || '').replace(/\u00A0/g, ' ').trim();
                    if (!normalized || normalized.length > 18) {
                        return /^[A-Z][A-Z ]{2,18}\s*:\s+/.test(normalized);
                    }
                    return /[A-Z]/.test(normalized) && normalized === normalized.toUpperCase();
                };
                const lineLooksLikeDetachedPunctuation = (entry) => {
                    const normalized = String(entry?.text || '').replace(/\u00A0/g, ' ').trim();
                    return /^[:;,.!?-]+$/.test(normalized);
                };

                const headingIndex = lineEntries.findIndex((entry, index) => {
                    if (index <= 0 || index >= lineEntries.length - 1) {
                        return false;
                    }
                    return lineLooksLikeEmbeddedHeadingLead(entry);
                });
                if (headingIndex <= 0 || headingIndex >= lineEntries.length - 1) {
                    return [];
                }

                const beforeCluster = lineEntries.slice(0, headingIndex);
                let headingEndIndex = headingIndex;
                while (headingEndIndex + 1 < lineEntries.length && lineLooksLikeDetachedPunctuation(lineEntries[headingEndIndex + 1])) {
                    headingEndIndex += 1;
                }
                const bodyOnlyCluster = lineEntries.slice(headingEndIndex + 1);
                const afterCluster = lineEntries.slice(headingIndex);
                if (!bodyOnlyCluster.length || !promotedClusterLooksLikeBodyCopy(beforeCluster) || !promotedClusterLooksLikeBodyCopy(bodyOnlyCluster)) {
                    return [];
                }

                const beforeAnnotation = buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: beforeCluster.map((entry) => entry.text),
                    sourceLineBBoxes: beforeCluster.map((entry) => entry.bbox),
                    sourceSpans: beforeCluster.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                    sourceKeySuffix: `body-prefix-lines-${Number(beforeCluster[0]?.index) || 0}-${Number(beforeCluster[beforeCluster.length - 1]?.index) || 0}`,
                });
                const afterAnnotation = buildPromotedTextAnnotationFromSource(block, pageData, {
                    textLines: afterCluster.map((entry) => entry.text),
                    sourceLineBBoxes: afterCluster.map((entry) => entry.bbox),
                    sourceSpans: afterCluster.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                    sourceKeySuffix: `body-suffix-lines-${Number(afterCluster[0]?.index) || headingIndex}-${Number(afterCluster[afterCluster.length - 1]?.index) || lineEntries.length}`,
                });

                return [beforeAnnotation, afterAnnotation].filter(Boolean);
            }

            function promotedLineEntryLooksLikeLeaderOnly(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized) {
                    return false;
                }

                const compact = normalized.replace(/\s+/g, '');
                if (compact.length < 4) {
                    return false;
                }

                return /^[._\-]+$/.test(compact);
            }

            function promotedLineEntryLooksLikeCompactLabel(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized) {
                    return false;
                }

                const compact = normalized.replace(/\s+/g, '');
                if (!compact || compact.length > 4) {
                    return false;
                }

                return /^[0-9]+[A-Za-z]?$/.test(compact) || /^[A-Za-z]$/.test(compact);
            }

            function promotedLineEntryStartsFormRow(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized) {
                    return false;
                }

                return (
                    /^\d+[A-Za-z]?\s+[A-Z(]/.test(normalized)
                    || /^\d+\s+[A-Za-z]$/.test(normalized)
                    || /^[A-Za-z]\s+[A-Z(0-9]/.test(normalized)
                    || /^[A-Za-z]$/.test(normalized)
                );
            }

            function promotedLineEntryLooksLikeStandaloneSidebarWord(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized || /\s/.test(normalized) || normalized.length > 12) {
                    return false;
                }

                return /^[A-Za-z]+$/.test(normalized);
            }

            function normalizePromotedRightAlignedFormLabelText(value) {
                return String(value || '')
                    .replace(/\u00A0/g, ' ')
                    .replace(/^[.\s]+/, '')
                    .replace(/\s+/g, ' ')
                    .trim();
            }

            function promotedLineEntryLooksLikeRightAlignedFormLabel(entry) {
                const normalized = normalizePromotedRightAlignedFormLabelText(entry?.text || '');
                if (!normalized || normalized.length > 18) {
                    return false;
                }

                return /^(?:[A-Za-z0-9/-]+(?:\s+or\s+[A-Za-z0-9/-]+)?)$/.test(normalized);
            }

            function promotedLineEntryLooksLikeStackedScalarValue(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .replace(/[−–—]/g, '-')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (!normalized || normalized.length > 24) {
                    return false;
                }

                return (
                    /^\$?\d[\d,]*(?:\.\d{1,2})?$/.test(normalized)
                    || /^\$?\d[\d,]*(?:\.\d{1,2})?\s*-\s*\$?\d[\d,]*(?:\.\d{1,2})?$/.test(normalized)
                    || /^(over|under)\s+\$?\d[\d,]*(?:\.\d{1,2})?$/i.test(normalized)
                );
            }

            function promotedLineEntryLooksLikeStandaloneColumnCell(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized || normalized.length > 48 || promotedLineEntryLooksLikeLeaderOnly(entry)) {
                    return false;
                }

                if (promotedLineEntryLooksLikeStackedScalarValue(entry)) {
                    return true;
                }

                const bbox = Array.isArray(entry?.bbox) ? entry.bbox : [0, 0, 0, 0];
                const width = Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0));
                const words = normalized.split(/\s+/).filter(Boolean);
                const hasLetters = /[A-Za-z]/.test(normalized);
                const uppercaseLike = hasLetters && normalized === normalized.toUpperCase();

                return (
                    (uppercaseLike && words.length <= 4 && width <= 240)
                    || (words.length <= 3 && width <= 180 && !/[,:;?!]/.test(normalized))
                );
            }

            function promotedLineEntriesLookLikeColumnLayout(lineEntries) {
                if (!Array.isArray(lineEntries) || lineEntries.length < 2) {
                    return false;
                }

                const sortedEntries = lineEntries
                    .filter((entry) => Array.isArray(entry?.bbox) && entry.bbox.length >= 4)
                    .slice()
                    .sort((leftEntry, rightEntry) => (Number(leftEntry?.bbox?.[0]) || 0) - (Number(rightEntry?.bbox?.[0]) || 0));
                if (sortedEntries.length < 2 || !sortedEntries.every((entry) => promotedLineEntryLooksLikeStandaloneColumnCell(entry))) {
                    return false;
                }

                const firstBox = sortedEntries[0].bbox;
                const firstTop = Number(firstBox[1]) || 0;
                const firstBottom = Number(firstBox[3]) || firstTop;
                const firstHeight = Math.max(1, firstBottom - firstTop);
                let hasMeaningfulGap = false;

                for (let index = 0; index < sortedEntries.length; index += 1) {
                    const currentBox = sortedEntries[index].bbox;
                    const currentTop = Number(currentBox[1]) || 0;
                    const currentBottom = Number(currentBox[3]) || currentTop;
                    const currentHeight = Math.max(1, currentBottom - currentTop);
                    const overlap = Math.max(0, Math.min(firstBottom, currentBottom) - Math.max(firstTop, currentTop));
                    const overlapRatio = overlap / Math.max(1, Math.min(firstHeight, currentHeight));
                    if (overlapRatio < 0.65) {
                        return false;
                    }

                    if (index > 0) {
                        const previousBox = sortedEntries[index - 1].bbox;
                        const previousRight = Number(previousBox[2]) || 0;
                        const currentLeft = Number(currentBox[0]) || 0;
                        if ((currentLeft - previousRight) >= 12) {
                            hasMeaningfulGap = true;
                        }
                    }
                }

                return hasMeaningfulGap;
            }

            function promotedLineEntryLooksLikeNarrowMarker(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized || /\s/.test(normalized)) {
                    return false;
                }

                const bbox = Array.isArray(entry?.bbox) ? entry.bbox : [0, 0, 0, 0];
                const width = Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0));
                const height = Math.max(0, (Number(bbox[3]) || 0) - (Number(bbox[1]) || 0));
                if (width > 96 || height > 24) {
                    return false;
                }

                return (
                    promotedLineEntryLooksLikeCompactLabel(entry)
                    || promotedLineEntryLooksLikeStandaloneSidebarWord(entry)
                    || /^[A-Za-z0-9/-]+$/.test(normalized)
                );
            }

            function promotedLineEntryLooksLikeStandaloneBullet(entry) {
                const normalized = String(entry?.text || '')
                    .replace(/\u00A0/g, ' ')
                    .trim();
                if (!normalized) {
                    return false;
                }

                return /^(?:•|●|◦|▪|■|○)$/.test(normalized);
            }

            function buildPromotedComparableLineEntriesForBlock(block) {
                if (!block || typeof block !== 'object') {
                    return [];
                }

                const rawTextLines = Array.isArray(block?.text_lines) ? block.text_lines : [];
                const rawLineBBoxes = Array.isArray(block?.line_bboxes) ? block.line_bboxes : [];
                if (!rawTextLines.length || rawLineBBoxes.length !== rawTextLines.length) {
                    return [];
                }

                return rawTextLines.map((line, index) => {
                    const text = sanitizePromotedExtractionLine(line);
                    const bbox = Array.isArray(rawLineBBoxes[index]) && rawLineBBoxes[index].length >= 4
                        ? rawLineBBoxes[index].map((value) => Number(value) || 0)
                        : null;
                    if (!bbox) {
                        return null;
                    }
                    return {
                        index,
                        text,
                        bbox,
                    };
                }).filter(Boolean);
            }

            function getPromotedMeaningfulBlockLines(block) {
                return Array.isArray(block?.text_lines)
                    ? block.text_lines
                        .map((line) => sanitizePromotedExtractionLine(line))
                        .filter((line) => line.length > 0)
                    : [];
            }

            function promotedBlockLooksLikeDecorativeCalloutSymbol(block) {
                const lines = getPromotedMeaningfulBlockLines(block);
                if (lines.length !== 1) {
                    return false;
                }

                const text = String(lines[0] || '').replace(/\s+/g, '');
                if (!/^(?:!|¡|‼|▲|△|▼|▽|◆|◇|■|□|●|○|◦|▪|▶|►)$/.test(text)) {
                    return false;
                }

                const width = Math.max(0, Number(block?.width) || 0);
                const height = Math.max(0, Number(block?.height) || 0);
                return width > 0
                    && height > 0
                    && width <= 42
                    && height <= 60;
            }

            function promotedBlockLooksLikeCompactCalloutCaption(block) {
                const lines = getPromotedMeaningfulBlockLines(block);
                if (lines.length !== 1) {
                    return false;
                }

                const text = String(lines[0] || '').trim();
                if (!/^[A-Z][A-Z0-9/& -]{2,14}$/.test(text)) {
                    return false;
                }

                const width = Math.max(0, Number(block?.width) || 0);
                const height = Math.max(0, Number(block?.height) || 0);
                return width > 0
                    && height > 0
                    && width <= 80
                    && height <= 20;
            }

            function blockBelongsToDecorativeCalloutIconCluster(block, pageBlocks) {
                if (!block || typeof block !== 'object') {
                    return false;
                }

                const blockIsSymbol = promotedBlockLooksLikeDecorativeCalloutSymbol(block);
                const blockIsCaption = promotedBlockLooksLikeCompactCalloutCaption(block);
                if (!blockIsSymbol && !blockIsCaption) {
                    return false;
                }

                const blockLeft = Number(block?.left) || 0;
                const blockTop = Number(block?.top) || 0;
                const blockWidth = Math.max(0, Number(block?.width) || 0);
                const blockHeight = Math.max(0, Number(block?.height) || 0);
                const blockRight = blockLeft + blockWidth;
                const blockBottom = blockTop + blockHeight;
                const blockCenterX = blockLeft + (blockWidth / 2);

                let sawSymbol = blockIsSymbol;
                let sawCaption = blockIsCaption;

                (Array.isArray(pageBlocks) ? pageBlocks : []).forEach((otherBlock) => {
                    if (!otherBlock || otherBlock === block) {
                        return;
                    }

                    const otherIsSymbol = promotedBlockLooksLikeDecorativeCalloutSymbol(otherBlock);
                    const otherIsCaption = promotedBlockLooksLikeCompactCalloutCaption(otherBlock);
                    if (!otherIsSymbol && !otherIsCaption) {
                        return;
                    }

                    const otherLeft = Number(otherBlock?.left) || 0;
                    const otherTop = Number(otherBlock?.top) || 0;
                    const otherWidth = Math.max(0, Number(otherBlock?.width) || 0);
                    const otherHeight = Math.max(0, Number(otherBlock?.height) || 0);
                    const otherRight = otherLeft + otherWidth;
                    const otherBottom = otherTop + otherHeight;
                    const otherCenterX = otherLeft + (otherWidth / 2);

                    const horizontalOverlap = Math.max(0, Math.min(blockRight, otherRight) - Math.max(blockLeft, otherLeft));
                    const minWidth = Math.max(1, Math.min(blockWidth, otherWidth));
                    const overlapRatio = horizontalOverlap / minWidth;
                    const sameNarrowColumn = overlapRatio >= 0.55
                        || Math.abs(blockCenterX - otherCenterX) <= 12;
                    if (!sameNarrowColumn) {
                        return;
                    }

                    const verticalGap = Math.max(
                        0,
                        Math.max(otherTop - blockBottom, blockTop - otherBottom)
                    );
                    if (verticalGap > 12) {
                        return;
                    }

                    sawSymbol = sawSymbol || otherIsSymbol;
                    sawCaption = sawCaption || otherIsCaption;
                });

                return sawSymbol && sawCaption;
            }

            function promotedEntriesShareVisualRow(leftEntry, rightEntry) {
                const leftBox = Array.isArray(leftEntry?.bbox) ? leftEntry.bbox : [0, 0, 0, 0];
                const rightBox = Array.isArray(rightEntry?.bbox) ? rightEntry.bbox : [0, 0, 0, 0];
                const leftTop = Number(leftBox[1]) || 0;
                const leftBottom = Number(leftBox[3]) || leftTop;
                const rightTop = Number(rightBox[1]) || 0;
                const rightBottom = Number(rightBox[3]) || rightTop;
                const leftHeight = Math.max(1, leftBottom - leftTop);
                const rightHeight = Math.max(1, rightBottom - rightTop);
                const overlap = Math.max(0, Math.min(leftBottom, rightBottom) - Math.max(leftTop, rightTop));
                const overlapRatio = overlap / Math.max(1, Math.min(leftHeight, rightHeight));
                return overlapRatio >= 0.45
                    || Math.abs(leftTop - rightTop) <= Math.max(2, Math.min(6, Math.min(leftHeight, rightHeight) * 0.45));
            }

            function findPromotedSiblingTextLineForMarkerEntry(markerEntry, sourceBlock, pageBlocks) {
                if (!promotedLineEntryLooksLikeStandaloneBullet(markerEntry)) {
                    return null;
                }

                const markerBox = Array.isArray(markerEntry?.bbox) ? markerEntry.bbox : [0, 0, 0, 0];
                const markerLeft = Number(markerBox[0]) || 0;
                const markerRight = Number(markerBox[2]) || markerLeft;
                let bestMatch = null;

                (Array.isArray(pageBlocks) ? pageBlocks : []).forEach((candidateBlock) => {
                    if (!candidateBlock || candidateBlock === sourceBlock) {
                        return;
                    }

                    buildPromotedComparableLineEntriesForBlock(candidateBlock).forEach((candidateEntry) => {
                        const candidateText = String(candidateEntry?.text || '').trim();
                        if (!candidateText || promotedLineEntryLooksLikeStandaloneBullet(candidateEntry)) {
                            return;
                        }
                        if (!promotedEntriesShareVisualRow(markerEntry, candidateEntry)) {
                            return;
                        }

                        const candidateBox = Array.isArray(candidateEntry?.bbox) ? candidateEntry.bbox : [0, 0, 0, 0];
                        const candidateLeft = Number(candidateBox[0]) || 0;
                        const candidateRight = Number(candidateBox[2]) || candidateLeft;
                        const horizontalGap = candidateLeft - markerRight;
                        if (horizontalGap < 8 || horizontalGap > 80) {
                            return;
                        }
                        if (candidateRight <= markerRight) {
                            return;
                        }

                        if (!bestMatch || horizontalGap < bestMatch.horizontalGap) {
                            bestMatch = {
                                block: candidateBlock,
                                entry: candidateEntry,
                                horizontalGap,
                            };
                        }
                    });
                });

                return bestMatch;
            }

            function trimPromotedLeadingBulletLeadInFromSourceBlock(block, pageData, extractedSource) {
                if (!block || !extractedSource || !Array.isArray(extractedSource.lineEntries) || extractedSource.lineEntries.length < 2) {
                    return extractedSource;
                }

                const sourceLineBBoxes = Array.isArray(extractedSource.sourceLineBBoxes)
                    ? extractedSource.sourceLineBBoxes
                    : [];
                const sourceTextLines = Array.isArray(extractedSource.textLines)
                    ? extractedSource.textLines
                    : [];
                if (!sourceLineBBoxes.length || sourceLineBBoxes.length !== sourceTextLines.length) {
                    return extractedSource;
                }

                const lineEntries = extractedSource.lineEntries;
                let firstContentIndex = -1;
                const dropIndexes = new Set();
                let sawLeadingBullet = false;

                for (let index = 0; index < lineEntries.length; index += 1) {
                    const normalizedText = String(lineEntries[index]?.text || '').trim();
                    if (normalizedText === '') {
                        if (sawLeadingBullet) {
                            dropIndexes.add(index);
                        }
                        continue;
                    }
                    if (promotedLineEntryLooksLikeStandaloneBullet(lineEntries[index])) {
                        sawLeadingBullet = true;
                        dropIndexes.add(index);
                        continue;
                    }
                    firstContentIndex = index;
                    break;
                }

                if (!sawLeadingBullet || firstContentIndex <= 0) {
                    return extractedSource;
                }

                const markerEntries = lineEntries.filter((entry, index) => dropIndexes.has(index) && promotedLineEntryLooksLikeStandaloneBullet(entry));
                if (!markerEntries.length) {
                    return extractedSource;
                }

                const siblingMatches = markerEntries
                    .map((entry) => findPromotedSiblingTextLineForMarkerEntry(entry, block, pageData?.blocks || []))
                    .filter(Boolean);
                if (siblingMatches.length !== markerEntries.length) {
                    return extractedSource;
                }

                const leadingContentEntry = lineEntries[firstContentIndex];
                const lastMarkerEntry = markerEntries[markerEntries.length - 1];
                const markerBottom = Number(lastMarkerEntry?.bbox?.[3]) || 0;
                const contentTop = Number(leadingContentEntry?.bbox?.[1]) || markerBottom;
                const verticalGap = contentTop - markerBottom;
                if (verticalGap < Math.max(6, ((Number(lastMarkerEntry?.bbox?.[3]) || 0) - (Number(lastMarkerEntry?.bbox?.[1]) || 0)) * 0.9)) {
                    return extractedSource;
                }

                const keptIndexes = sourceTextLines
                    .map((_line, index) => index)
                    .filter((index) => !dropIndexes.has(index));
                if (!keptIndexes.length) {
                    return extractedSource;
                }

                const keptLineEntries = keptIndexes.map((index, nextIndex) => {
                    const entry = lineEntries[index];
                    return {
                        ...entry,
                        index: nextIndex,
                    };
                });

                return {
                    blockText: keptLineEntries.map((entry) => sanitizePromotedExtractionLine(entry?.text || '')).filter(Boolean).join('\n'),
                    textLines: keptIndexes.map((index) => sourceTextLines[index]),
                    sourceLineBBoxes: keptIndexes.map((index) => sourceLineBBoxes[index]),
                    sourceSpans: keptLineEntries.flatMap((entry) => Array.isArray(entry?.spans) ? entry.spans : []),
                    lineEntries: keptLineEntries,
                    excludedLineEntries: markerEntries.map((entry) => ({
                        ...entry,
                        spans: Array.isArray(entry?.spans) ? entry.spans : [],
                    })),
                };
            }

            function detectPromotedTrailingBulletMarkerLineEntries(block) {
                const lineEntries = buildPromotedComparableLineEntriesForBlock(block);
                if (!lineEntries.length) {
                    return [];
                }

                const trailing = [];
                for (let index = lineEntries.length - 1; index >= 0; index -= 1) {
                    const entry = lineEntries[index];
                    const normalizedText = String(entry?.text || '').trim();
                    if (normalizedText === '') {
                        continue;
                    }
                    if (!promotedLineEntryLooksLikeStandaloneBullet(entry)) {
                        break;
                    }
                    trailing.unshift(entry);
                }

                if (!trailing.length || trailing.length === lineEntries.length) {
                    return [];
                }

                return trailing;
            }

            function buildPromotedTrailingBulletTransferMap(pageBlocks) {
                const blocks = Array.isArray(pageBlocks) ? pageBlocks.filter((block) => block && typeof block === 'object') : [];
                const transfersByTargetBlock = new Map();
                const excludedLineIndexesBySourceBlock = new Map();

                blocks.forEach((sourceBlock) => {
                    const sourceBlockNum = Number(sourceBlock?.block_num);
                    if (!Number.isFinite(sourceBlockNum)) {
                        return;
                    }

                    const trailingMarkerEntries = detectPromotedTrailingBulletMarkerLineEntries(sourceBlock);
                    if (!trailingMarkerEntries.length) {
                        return;
                    }

                    const tentativeTransfers = [];
                    let sharedTargetBlockNum = null;

                    trailingMarkerEntries.forEach((markerEntry) => {
                        const markerBox = Array.isArray(markerEntry?.bbox) ? markerEntry.bbox : [0, 0, 0, 0];
                        const markerRight = Number(markerBox[2]) || 0;
                        let bestMatch = null;

                        blocks.forEach((candidateBlock) => {
                            const candidateBlockNum = Number(candidateBlock?.block_num);
                            if (!Number.isFinite(candidateBlockNum) || candidateBlockNum === sourceBlockNum) {
                                return;
                            }

                            buildPromotedComparableLineEntriesForBlock(candidateBlock).forEach((candidateEntry) => {
                                const candidateText = String(candidateEntry?.text || '').trim();
                                if (!candidateText || promotedLineEntryLooksLikeStandaloneBullet(candidateEntry)) {
                                    return;
                                }
                                if (!promotedEntriesShareVisualRow(markerEntry, candidateEntry)) {
                                    return;
                                }

                                const candidateBox = Array.isArray(candidateEntry?.bbox) ? candidateEntry.bbox : [0, 0, 0, 0];
                                const candidateLeft = Number(candidateBox[0]) || 0;
                                const gap = candidateLeft - markerRight;
                                if (gap < 6 || gap > 80) {
                                    return;
                                }

                                if (!bestMatch || gap < bestMatch.gap) {
                                    bestMatch = {
                                        targetBlock: candidateBlock,
                                        targetBlockNum: candidateBlockNum,
                                        targetLineIndex: Number(candidateEntry?.index) || 0,
                                        gap,
                                    };
                                }
                            });
                        });

                        if (!bestMatch) {
                            tentativeTransfers.length = 0;
                            sharedTargetBlockNum = null;
                            return;
                        }

                        if (sharedTargetBlockNum === null) {
                            sharedTargetBlockNum = bestMatch.targetBlockNum;
                        } else if (sharedTargetBlockNum !== bestMatch.targetBlockNum) {
                            tentativeTransfers.length = 0;
                            sharedTargetBlockNum = null;
                            return;
                        }

                        tentativeTransfers.push({
                            sourceBlockNum,
                            sourceLineIndex: Number(markerEntry?.index) || 0,
                            targetBlockNum: bestMatch.targetBlockNum,
                            targetLineIndex: bestMatch.targetLineIndex,
                            markerSpan: buildSyntheticPromotedSpanFromBlockLine(sourceBlock, markerEntry?.text || '', markerEntry?.bbox || []),
                        });
                    });

                    if (!tentativeTransfers.length || sharedTargetBlockNum === null) {
                        return;
                    }

                    if (!transfersByTargetBlock.has(sharedTargetBlockNum)) {
                        transfersByTargetBlock.set(sharedTargetBlockNum, []);
                    }
                    tentativeTransfers.forEach((transfer) => {
                        transfersByTargetBlock.get(sharedTargetBlockNum).push(transfer);
                        if (!excludedLineIndexesBySourceBlock.has(sourceBlockNum)) {
                            excludedLineIndexesBySourceBlock.set(sourceBlockNum, new Set());
                        }
                        excludedLineIndexesBySourceBlock.get(sourceBlockNum).add(transfer.sourceLineIndex);
                    });
                });

                transfersByTargetBlock.forEach((transfers) => {
                    transfers.sort((leftTransfer, rightTransfer) => (
                        (Number(leftTransfer?.targetLineIndex) || 0) - (Number(rightTransfer?.targetLineIndex) || 0)
                    ));
                });

                return {
                    transfersByTargetBlock,
                    excludedLineIndexesBySourceBlock,
                };
            }

            function mergePromotedExcludedLineIndexes(...sets) {
                const merged = new Set();
                sets.forEach((value) => {
                    if (value instanceof Set) {
                        value.forEach((entry) => merged.add(Number(entry)));
                        return;
                    }
                    if (Array.isArray(value)) {
                        value.forEach((entry) => merged.add(Number(entry)));
                    }
                });
                return merged.size > 0 ? merged : null;
            }

            function promotedLineEntryDominantFontWeight(entry) {
                const spanWeights = (Array.isArray(entry?.spans) ? entry.spans : [])
                    .map((span) => Number(span?.fontWeight ?? span?.font_weight) || 0)
                    .filter((weight) => weight > 0);
                if (spanWeights.length) {
                    return Math.max(...spanWeights);
                }
                return 0;
            }

            function promotedClusterLooksLikeSectionHeading(cluster) {
                if (!Array.isArray(cluster) || cluster.length === 0) {
                    return false;
                }

                const clusterText = cluster
                    .map((entry) => String(entry?.text || '').replace(/\u00A0/g, ' ').trim())
                    .filter(Boolean)
                    .join(' ')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (!clusterText || clusterText.length > 48) {
                    return false;
                }

                const lineCount = cluster.length;
                if (lineCount > 2) {
                    return false;
                }

                const maxWidth = Math.max(...cluster.map((entry) => {
                    const bbox = Array.isArray(entry?.bbox) ? entry.bbox : [0, 0, 0, 0];
                    return Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0));
                }));
                if (maxWidth > 220) {
                    return false;
                }

                return cluster.every((entry) => promotedLineEntryDominantFontWeight(entry) >= 600);
            }

            function promotedClusterLooksLikeBodyCopy(cluster) {
                if (!Array.isArray(cluster) || cluster.length === 0) {
                    return false;
                }

                const clusterText = cluster
                    .map((entry) => String(entry?.text || '').replace(/\u00A0/g, ' ').trim())
                    .filter(Boolean)
                    .join(' ')
                    .replace(/\s+/g, ' ')
                    .trim();
                if (!clusterText || clusterText.length < 20) {
                    return false;
                }

                const maxWidth = Math.max(...cluster.map((entry) => {
                    const bbox = Array.isArray(entry?.bbox) ? entry.bbox : [0, 0, 0, 0];
                    return Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0));
                }));
                if (maxWidth < 120) {
                    return false;
                }

                return cluster.some((entry) => promotedLineEntryDominantFontWeight(entry) <= 500);
            }

            function shouldForcePromotedSemanticClusterSplit(lineEntries, clusters) {
                if (!Array.isArray(lineEntries) || lineEntries.length < 2) {
                    return false;
                }
                if (!Array.isArray(clusters) || clusters.length < 2) {
                    return false;
                }

                for (let index = 1; index < clusters.length; index += 1) {
                    const previousCluster = clusters[index - 1];
                    const nextCluster = clusters[index];
                    if (!promotedClusterLooksLikeSectionHeading(previousCluster)) {
                        continue;
                    }
                    if (!promotedClusterLooksLikeBodyCopy(nextCluster)) {
                        continue;
                    }
                    return true;
                }

                return false;
            }

            function shouldForcePromotedGapClusterSplit(lineEntries, clusters) {
                if (!Array.isArray(lineEntries) || lineEntries.length < 2) {
                    return false;
                }
                if (!Array.isArray(clusters) || clusters.length < 2) {
                    return false;
                }

                for (let index = 1; index < clusters.length; index += 1) {
                    const previousCluster = Array.isArray(clusters[index - 1]) ? clusters[index - 1] : [];
                    const nextCluster = Array.isArray(clusters[index]) ? clusters[index] : [];
                    if (!previousCluster.length || !nextCluster.length) {
                        continue;
                    }

                    const previousLastEntry = previousCluster[previousCluster.length - 1];
                    const nextFirstEntry = nextCluster[0];
                    const previousBox = Array.isArray(previousLastEntry?.bbox) ? previousLastEntry.bbox : [0, 0, 0, 0];
                    const nextBox = Array.isArray(nextFirstEntry?.bbox) ? nextFirstEntry.bbox : [0, 0, 0, 0];
                    const previousTop = Number(previousBox[1]) || 0;
                    const previousBottom = Number(previousBox[3]) || previousTop;
                    const nextTop = Number(nextBox[1]) || 0;
                    const nextBottom = Number(nextBox[3]) || nextTop;
                    const previousHeight = Math.max(1, previousBottom - previousTop);
                    const nextHeight = Math.max(1, nextBottom - nextTop);
                    const verticalGap = nextTop - previousBottom;
                    const leftDelta = Math.abs((Number(nextBox[0]) || 0) - (Number(previousBox[0]) || 0));
                    const gapThreshold = Math.max(10, Math.min(28, Math.max(previousHeight, nextHeight) * 0.8));

                    if (verticalGap > gapThreshold && leftDelta <= Math.max(18, Math.min(previousHeight, nextHeight) * 1.2)) {
                        return true;
                    }
                }

                return false;
            }

            function shouldForcePromotedFormRowSplit(lineEntries, clusters) {
                if (!Array.isArray(lineEntries) || lineEntries.length < 2) {
                    return false;
                }
                if (!Array.isArray(clusters) || clusters.length <= 1) {
                    return false;
                }

                const hasLeaderOnlyLine = lineEntries.some((entry) => promotedLineEntryLooksLikeLeaderOnly(entry));
                const allCompactLabels = lineEntries.every((entry) => promotedLineEntryLooksLikeCompactLabel(entry));
                const compactLabelCount = lineEntries.filter((entry) => promotedLineEntryLooksLikeCompactLabel(entry)).length;
                const narrowMarkerCount = lineEntries.filter((entry) => promotedLineEntryLooksLikeNarrowMarker(entry)).length;
                const stackedScalarValueCount = lineEntries.filter((entry) => promotedLineEntryLooksLikeStackedScalarValue(entry)).length;
                const nonCompactCount = lineEntries.filter((entry) => (
                    !promotedLineEntryLooksLikeCompactLabel(entry) && !promotedLineEntryLooksLikeLeaderOnly(entry)
                )).length;
                const formRowStartCount = lineEntries.filter((entry) => promotedLineEntryStartsFormRow(entry)).length;
                const sidebarWordCount = lineEntries.filter((entry) => promotedLineEntryLooksLikeStandaloneSidebarWord(entry)).length;
                const columnLayout = promotedLineEntriesLookLikeColumnLayout(lineEntries);
                if (columnLayout) {
                    return true;
                }
                if (!hasLeaderOnlyLine && !allCompactLabels) {
                    if (
                        !(compactLabelCount >= 2 && nonCompactCount >= 1)
                        && !(narrowMarkerCount >= 2 && nonCompactCount >= 1)
                        && !(lineEntries.length >= 4 && stackedScalarValueCount >= Math.max(4, lineEntries.length - 1))
                        && !(formRowStartCount >= 2)
                        && !(sidebarWordCount >= 2 && formRowStartCount >= 1)
                    ) {
                        return false;
                    }
                }

                return clusters.every((cluster) => (
                    Array.isArray(cluster)
                    && cluster.length > 0
                    && (
                        allCompactLabels
                            ? cluster.every((entry) => promotedLineEntryLooksLikeCompactLabel(entry))
                            : (
                                cluster.some((entry) => !promotedLineEntryLooksLikeLeaderOnly(entry))
                                || cluster.every((entry) => promotedLineEntryLooksLikeLeaderOnly(entry))
                            )
                    )
                ));
            }

            function clusterPromotedExtractionLineEntries(lineEntries) {
                if (!Array.isArray(lineEntries) || lineEntries.length === 0) {
                    return [];
                }

                const normalizeLineText = (entry) => String(entry?.text || '').trim();
                const sortedEntries = lineEntries
                    .slice()
                    .filter((entry) => normalizeLineText(entry) !== '')
                    .sort(comparePromotedLineEntryVisualPosition);
                if (!sortedEntries.length) {
                    return [];
                }
                const clusters = [];
                let currentCluster = [sortedEntries[0]];

                const isNumberedLine = (entry) => /^\(?\d+\)?[.)]/.test(normalizeLineText(entry));
                const isFooterLine = (entry) => /^The form of this addendum/i.test(normalizeLineText(entry));
                const shouldSplitCluster = (previousEntry, nextEntry) => {
                    const prevBox = Array.isArray(previousEntry?.bbox) ? previousEntry.bbox : [0, 0, 0, 0];
                    const nextBox = Array.isArray(nextEntry?.bbox) ? nextEntry.bbox : [0, 0, 0, 0];
                    const prevTop = Number(prevBox[1]) || 0;
                    const prevBottom = Number(prevBox[3]) || prevTop;
                    const nextTop = Number(nextBox[1]) || 0;
                    const nextBottom = Number(nextBox[3]) || nextTop;
                    const prevHeight = Math.max(1, prevBottom - prevTop);
                    const nextHeight = Math.max(1, nextBottom - nextTop);
                    const verticalGap = nextTop - prevBottom;
                    const overlapHeight = Math.max(0, Math.min(prevBottom, nextBottom) - Math.max(prevTop, nextTop));
                    const overlapRatio = overlapHeight / Math.max(1, Math.min(prevHeight, nextHeight));
                    const prevLeft = Number(prevBox[0]) || 0;
                    const nextLeft = Number(nextBox[0]) || 0;
                    const columnShift = Math.abs(nextLeft - prevLeft);

                    if (
                        (
                            (promotedLineEntryLooksLikeLeaderOnly(previousEntry) && promotedLineEntryLooksLikeNarrowMarker(nextEntry))
                            || (promotedLineEntryLooksLikeNarrowMarker(previousEntry) && promotedLineEntryLooksLikeLeaderOnly(nextEntry))
                        )
                        && columnShift >= 24
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeStackedScalarValue(previousEntry)
                        && promotedLineEntryLooksLikeStackedScalarValue(nextEntry)
                    ) {
                        return true;
                    }
                    const previousRight = Number(prevBox[2]) || prevLeft;
                    const horizontalGap = nextLeft - previousRight;
                    if (
                        overlapRatio >= 0.65
                        && horizontalGap >= 12
                        && promotedLineEntryLooksLikeStandaloneColumnCell(previousEntry)
                        && promotedLineEntryLooksLikeStandaloneColumnCell(nextEntry)
                    ) {
                        return true;
                    }

                    if (overlapRatio >= 0.2) {
                        return false;
                    }

                    if (promotedLineEntryLooksLikeLeaderOnly(previousEntry) && !promotedLineEntryLooksLikeLeaderOnly(nextEntry)) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeCompactLabel(previousEntry)
                        && promotedLineEntryLooksLikeCompactLabel(nextEntry)
                        && Math.max(prevBox[2] - prevBox[0], nextBox[2] - nextBox[0]) <= 24
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeCompactLabel(previousEntry)
                        && !promotedLineEntryLooksLikeCompactLabel(nextEntry)
                        && (nextTop - prevTop) >= Math.max(6, prevHeight * 0.8)
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeRightAlignedFormLabel(nextEntry)
                        && !promotedLineEntryLooksLikeRightAlignedFormLabel(previousEntry)
                        && (nextLeft - previousRight) >= 120
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryStartsFormRow(nextEntry)
                        && !promotedLineEntryLooksLikeLeaderOnly(previousEntry)
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeStandaloneSidebarWord(nextEntry)
                        && promotedLineEntryLooksLikeStandaloneSidebarWord(previousEntry)
                    ) {
                        return true;
                    }
                    if (
                        promotedLineEntryLooksLikeStandaloneSidebarWord(nextEntry)
                        && !promotedLineEntryLooksLikeStandaloneSidebarWord(previousEntry)
                    ) {
                        return true;
                    }
                    if (isNumberedLine(nextEntry) && !isNumberedLine(previousEntry) && overlapRatio < 0.3) {
                        return true;
                    }
                    if (isFooterLine(nextEntry) && !isFooterLine(previousEntry)) {
                        return true;
                    }

                    const splitGapThreshold = Math.max(4.5, Math.min(14, Math.max(prevHeight, nextHeight) * 0.6));
                    if (verticalGap > splitGapThreshold) {
                        return true;
                    }

                    const dramaticIndentSplitThreshold = Math.max(24, Math.min(prevHeight, nextHeight) * 1.2);
                    if (
                        /[:)]\s*$/.test(normalizeLineText(previousEntry))
                        && (nextLeft - prevLeft) > Math.max(14, Math.min(prevHeight, nextHeight) * 0.75)
                    ) {
                        return true;
                    }

                    if (nextLeft - prevLeft > dramaticIndentSplitThreshold) {
                        return true;
                    }

                    const normalizedNext = normalizeLineText(nextEntry).replace(/[, ]+/g, '');
                    const normalizedPrev = normalizeLineText(previousEntry);
                    const amountOnly = /^[0-9]+$/.test(normalizedNext);
                    if (amountOnly && /(less than|\$|amount|value)/i.test(normalizedPrev)) {
                        return false;
                    }

                    return false;
                };

                for (let index = 1; index < sortedEntries.length; index += 1) {
                    const nextEntry = sortedEntries[index];
                    const previousEntry = currentCluster[currentCluster.length - 1];
                    if (shouldSplitCluster(previousEntry, nextEntry)) {
                        clusters.push(currentCluster);
                        currentCluster = [nextEntry];
                        continue;
                    }
                    currentCluster.push(nextEntry);
                }

                if (currentCluster.length) {
                    clusters.push(currentCluster);
                }

                return clusters.filter((cluster) => Array.isArray(cluster) && cluster.length > 0);
            }

            function buildPromotedTextAnnotationFromSource(block, pageData, {
                textLines = [],
                sourceLineBBoxes = [],
                sourceSpans = [],
                sourceKeySuffix = '',
                explicitId = '',
                explicitSourceKey = '',
            } = {}) {
                const normalizedLines = Array.isArray(textLines)
                    ? textLines.map((line) => sanitizePromotedExtractionLine(line)).filter((line) => line !== '')
                    : [];
                const blockText = normalizedLines.length
                    ? normalizedLines.join('\n')
                    : sanitizePromotedExtractionText(block?.text || '');

                if (!blockText) {
                    return null;
                }

                const normalizedLineBBoxes = Array.isArray(sourceLineBBoxes)
                    ? sourceLineBBoxes
                        .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        .map((bbox) => bbox.map((value) => Number(value) || 0))
                    : [];
                const bboxSource = normalizedLineBBoxes.length
                    ? normalizedLineBBoxes
                    : [[
                        Number(block?.left) || 0,
                        Number(block?.top) || 0,
                        (Number(block?.left) || 0) + (Number(block?.width) || 0),
                        (Number(block?.top) || 0) + (Number(block?.height) || 0),
                    ]];
                const allLinesAreLeaderOnly = normalizedLines.length > 0
                    && normalizedLines.every((line) => /^[.\s]+$/.test(String(line || '').trim()));
                const annotationBBoxSource = (() => {
                    if (!allLinesAreLeaderOnly || bboxSource.length !== 1) {
                        return bboxSource;
                    }

                    const rawBBox = bboxSource[0];
                    const rawTop = Number(rawBBox?.[1]) || 0;
                    const rawBottom = Number(rawBBox?.[3]) || rawTop;
                    const rawHeight = Math.max(0.25, rawBottom - rawTop);
                    const relevantSpans = (Array.isArray(sourceSpans) ? sourceSpans : []).filter((span) => span);
                    const avgAscender = relevantSpans.length > 0
                        ? relevantSpans.reduce((sum, span) => sum + (Number(span?.ascender) || 0.8), 0) / relevantSpans.length
                        : 0.8;
                    const avgDescender = relevantSpans.length > 0
                        ? relevantSpans.reduce((sum, span) => sum + (Number(span?.descender) || -0.2), 0) / relevantSpans.length
                        : -0.2;
                    const avgFontSize = relevantSpans.length > 0
                        ? relevantSpans.reduce((sum, span) => sum + (Number(span?.fontSize ?? span?.font_size) || Number(block?.font_size) || 12), 0) / relevantSpans.length
                        : (Number(block?.font_size) || 12);
                    const desiredHeight = Math.max(rawHeight, avgFontSize * Math.max(0.6, avgAscender - avgDescender), 6);
                    if (desiredHeight <= rawHeight + 0.25) {
                        return bboxSource;
                    }

                    return [[
                        Number(rawBBox?.[0]) || 0,
                        rawBottom - desiredHeight,
                        Number(rawBBox?.[2]) || Number(rawBBox?.[0]) || 0,
                        rawBottom,
                    ]];
                })();

                const left = Math.min(...annotationBBoxSource.map((bbox) => Number(bbox?.[0]) || 0));
                const top = Math.min(...annotationBBoxSource.map((bbox) => Number(bbox?.[1]) || 0));
                const right = Math.max(...annotationBBoxSource.map((bbox) => Number(bbox?.[2]) || left));
                const bottom = Math.max(...annotationBBoxSource.map((bbox) => Number(bbox?.[3]) || top));
                const width = right - left;
                const height = bottom - top;
                const pageHeight = Number(pageData?.height) || 0;
                if (width <= 1 || height <= 1 || pageHeight <= 0) {
                    return null;
                }

                const lineCount = Math.max(
                    1,
                    normalizedLines.length || blockText.split('\n').length
                );
                const fontWeight = block?.font_weight
                    ? String(block.font_weight)
                    : (block?.bold ? '700' : '400');
                const extractedLineHeight = normalizedLineBBoxes.length
                    ? normalizedLineBBoxes.reduce((sum, bbox) => (
                        sum + Math.max(1, (Number(bbox?.[3]) || 0) - (Number(bbox?.[1]) || 0))
                    ), 0) / normalizedLineBBoxes.length
                    : (Number(block?.avg_line_height) || Number(block?.line_height) || (height / lineCount));
                const rootSourceKey = `block-${pageData.page_number}-${block.block_num}`;
                const promotedSourceKey = explicitSourceKey || (sourceKeySuffix ? `${rootSourceKey}-${sourceKeySuffix}` : rootSourceKey);

                const annotation = {
                    id: explicitId || `promoted_${pageData.page_number}_${block.block_num}${sourceKeySuffix ? `_${sourceKeySuffix.replace(/[^a-z0-9_-]+/gi, '_')}` : ''}`,
                    type: 'text',
                    text: blockText,
                    originalText: blockText,
                    pageIndex: Math.max(0, (Number(pageData?.page_number) || 1) - 1),
                    pdfX: left,
                    pdfY: pageHeight - (top + height),
                    pdfWidth: width,
                    pdfHeight: height,
                    keepBounds: true,
                    fontSize: Math.max(6, Number(block?.font_size) || 12),
                    fontFamily: normalizePdfEditableFontFamily(block?.font || 'Helvetica') || normalizeBuiltinAnnotationFontFamily(block?.font || 'Helvetica'),
                    fontSourceName: String(block?.font || '').trim(),
                    lineHeight: extractedLineHeight > 0 ? extractedLineHeight : null,
                    textColor: normalizePromotedAnnotationColor(block),
                    backgroundColor: 'transparent',
                    fontWeight,
                    fontStyle: block?.italic ? 'italic' : 'normal',
                    underline: Boolean(block?.underline),
                    textAlign: 'left',
                    opacity: 1,
                    rotation: 0,
                    promotedFromExtraction: true,
                    promotedDirty: false,
                    promotedSourceKey,
                    promotedSourceBlockNum: Number(block?.block_num) || 0,
                    promotedSourcePage: Number(pageData?.page_number) || 1,
                };

                setPromotedAnnotationSourceMeta(annotation, {
                    sourceBlockLeft: left,
                    sourceBlockTop: top,
                    sourceBlockWidth: width,
                    sourceBlockHeight: height,
                    sourcePageHeight: pageHeight,
                    sourceTextLines: normalizedLines.length
                        ? [...normalizedLines]
                        : blockText.split('\n').map((line) => sanitizePromotedExtractionLine(line)),
                    sourceLineBBoxes: normalizedLineBBoxes,
                    sourceSpans,
                });

                normalizeTextAnnotation(annotation);
                return annotation;
            }

            function normalizeExtractionRect(rectLike) {
                if (!Array.isArray(rectLike) || rectLike.length < 4) {
                    return null;
                }
                const rect = rectLike.slice(0, 4).map((value) => Number(value));
                return rect.every((value) => Number.isFinite(value)) ? rect : null;
            }

            function getExtractionBlockRect(block) {
                const directRect = normalizeExtractionRect(block?.bbox);
                if (directRect) {
                    return directRect;
                }

                const left = Number(block?.left);
                const top = Number(block?.top);
                const width = Number(block?.width);
                const height = Number(block?.height);
                if (![left, top, width, height].every(Number.isFinite)) {
                    return null;
                }

                return [left, top, left + Math.max(0, width), top + Math.max(0, height)];
            }

            function extractionRectOverlapSmaller(rectA, rectB) {
                const a = normalizeExtractionRect(rectA);
                const b = normalizeExtractionRect(rectB);
                if (!a || !b) {
                    return 0;
                }

                const interW = Math.max(0, Math.min(a[2], b[2]) - Math.max(a[0], b[0]));
                const interH = Math.max(0, Math.min(a[3], b[3]) - Math.max(a[1], b[1]));
                const inter = interW * interH;
                if (inter <= 0) {
                    return 0;
                }

                const areaA = Math.max(0, a[2] - a[0]) * Math.max(0, a[3] - a[1]);
                const areaB = Math.max(0, b[2] - b[0]) * Math.max(0, b[3] - b[1]);
                const smaller = Math.min(areaA, areaB);
                return smaller > 0 ? (inter / smaller) : 0;
            }

            function mergeBoundingBoxExtractionPages(rawPages, groupedPages) {
                const safeRawPages = Array.isArray(rawPages) ? rawPages : [];
                const safeGroupedPages = Array.isArray(groupedPages) ? groupedPages : [];
                if (!boundingBoxEditMode || safeGroupedPages.length === 0) {
                    return safeRawPages;
                }

                const rawByPage = new Map(
                    safeRawPages
                        .filter((page) => page && Number.isFinite(Number(page.page_number)))
                        .map((page) => [Number(page.page_number), page])
                );
                const groupedByPage = new Map(
                    safeGroupedPages
                        .filter((page) => page && Number.isFinite(Number(page.page_number)))
                        .map((page) => [Number(page.page_number), page])
                );
                const pageNumbers = Array.from(new Set([
                    ...rawByPage.keys(),
                    ...groupedByPage.keys(),
                ])).sort((left, right) => left - right);

                return pageNumbers.map((pageNumber) => {
                    const rawPage = rawByPage.get(pageNumber) || {};
                    const groupedPage = groupedByPage.get(pageNumber) || {};
                    const groupedBlocks = Array.isArray(groupedPage.blocks) ? groupedPage.blocks.slice() : [];
                    const rawBlocks = Array.isArray(rawPage.blocks) ? rawPage.blocks : [];
                    const mergedBlocks = groupedBlocks.slice();

                    rawBlocks.forEach((rawBlock) => {
                        const rawRect = getExtractionBlockRect(rawBlock);
                        if (!rawRect) {
                            return;
                        }

                        const rawText = sanitizeOverlayText(rawBlock?.text || '').replace(/\s+/g, ' ').trim();
                        const coveredByGroupedBlock = groupedBlocks.some((groupedBlock) => {
                            const groupedRect = getExtractionBlockRect(groupedBlock);
                            if (!groupedRect) {
                                return false;
                            }

                            if (pdfRectContainsRect(groupedRect, rawRect, 0.75)) {
                                return true;
                            }

                            if (extractionRectOverlapSmaller(rawRect, groupedRect) >= 0.72) {
                                return true;
                            }

                            const groupedText = sanitizeOverlayText(groupedBlock?.text || '').replace(/\s+/g, ' ').trim();
                            return !!rawText
                                && !!groupedText
                                && (rawText === groupedText || rawText.includes(groupedText) || groupedText.includes(rawText))
                                && pdfRectsIntersect(rawRect, groupedRect, 0.75);
                        });

                        if (!coveredByGroupedBlock) {
                            mergedBlocks.push(rawBlock);
                        }
                    });

                    mergedBlocks.sort((leftBlock, rightBlock) => {
                        const leftTop = Number(leftBlock?.top) || 0;
                        const rightTop = Number(rightBlock?.top) || 0;
                        if (leftTop !== rightTop) {
                            return leftTop - rightTop;
                        }
                        const leftValue = Number(leftBlock?.left) || 0;
                        const rightValue = Number(rightBlock?.left) || 0;
                        if (leftValue !== rightValue) {
                            return leftValue - rightValue;
                        }
                        return (Number(leftBlock?.block_num) || 0) - (Number(rightBlock?.block_num) || 0);
                    });

                    return {
                        ...rawPage,
                        ...groupedPage,
                        page_number: pageNumber,
                        width: Math.max(Number(rawPage?.width) || 0, Number(groupedPage?.width) || 0),
                        height: Math.max(Number(rawPage?.height) || 0, Number(groupedPage?.height) || 0),
                        blocks: mergedBlocks,
                        words: Array.isArray(rawPage.words) ? rawPage.words : (Array.isArray(groupedPage.words) ? groupedPage.words : []),
                    };
                }).filter((page) => {
                    const hasBlocks = Array.isArray(page?.blocks) && page.blocks.length > 0;
                    const hasWords = Array.isArray(page?.words) && page.words.length > 0;
                    return hasBlocks || hasWords;
                });
            }

            function tagBoundingBoxLiteralPages(pages) {
                const safePages = Array.isArray(pages) ? pages : [];
                return safePages.map((page) => ({
                    ...page,
                    _overlayLiteralBlocks: true,
                }));
            }

            function resolveOverlayExtractionPages(extractionPayload) {
                const rawExtractionData = Array.isArray(extractionPayload?.extraction_data)
                    ? extractionPayload.extraction_data
                    : [];
                return rawExtractionData;
            }

            function pdfRectsIntersect(rectA, rectB, padding = 0) {
                const leftA = Number(rectA?.[0]) - padding;
                const topA = Number(rectA?.[1]) - padding;
                const rightA = Number(rectA?.[2]) + padding;
                const bottomA = Number(rectA?.[3]) + padding;
                const leftB = Number(rectB?.[0]) - padding;
                const topB = Number(rectB?.[1]) - padding;
                const rightB = Number(rectB?.[2]) + padding;
                const bottomB = Number(rectB?.[3]) + padding;
                if (![leftA, topA, rightA, bottomA, leftB, topB, rightB, bottomB].every(Number.isFinite)) {
                    return false;
                }
                return !(rightA <= leftB || rightB <= leftA || bottomA <= topB || bottomB <= topA);
            }

            function pdfRectContainsRect(outerRect, innerRect, padding = 0) {
                const outerLeft = Number(outerRect?.[0]) - padding;
                const outerTop = Number(outerRect?.[1]) - padding;
                const outerRight = Number(outerRect?.[2]) + padding;
                const outerBottom = Number(outerRect?.[3]) + padding;
                const innerLeft = Number(innerRect?.[0]);
                const innerTop = Number(innerRect?.[1]);
                const innerRight = Number(innerRect?.[2]);
                const innerBottom = Number(innerRect?.[3]);
                if (![outerLeft, outerTop, outerRight, outerBottom, innerLeft, innerTop, innerRight, innerBottom].every(Number.isFinite)) {
                    return false;
                }
                return innerLeft >= outerLeft
                    && innerTop >= outerTop
                    && innerRight <= outerRight
                    && innerBottom <= outerBottom;
            }

            function annotationPdfRectOnPage(annotation, pageHeight) {
                const pdfX = Number(annotation?.pdfX);
                const pdfY = Number(annotation?.pdfY);
                const pdfWidth = Number(annotation?.pdfWidth);
                const pdfHeight = Number(annotation?.pdfHeight);
                const resolvedPageHeight = Number(pageHeight);
                if (![pdfX, pdfY, pdfWidth, pdfHeight, resolvedPageHeight].every(Number.isFinite)) {
                    return null;
                }
                return [
                    pdfX,
                    resolvedPageHeight - (pdfY + pdfHeight),
                    pdfX + pdfWidth,
                    resolvedPageHeight - pdfY,
                ];
            }

            function buildDrawnCheckboxCandidates(pageData, pageIndex) {
                const pageHeight = Number(pageData?.height) || 0;
                if (!(pageHeight > 0)) {
                    return [];
                }

                const drawnBoxRects = Array.isArray(pageData?.drawn_box_rects)
                    ? pageData.drawn_box_rects.map((rect) => normalizeExtractionRect(rect)).filter(Boolean)
                    : [];
                const widgetRects = Array.isArray(pageData?.widget_rects)
                    ? pageData.widget_rects.map((rect) => normalizeExtractionRect(rect)).filter(Boolean)
                    : [];
                const pageWords = Array.isArray(pageData?.words) ? pageData.words : [];
                const decorativeRectIndexes = new Set();
                const rectHasNearbyLabelText = (rect) => {
                    const [x0, y0, x1, y1] = rect;
                    const width = x1 - x0;
                    const height = y1 - y0;
                    const verticalBandPadding = Math.max(8, height * 0.75);
                    const minLeft = x0 - Math.max(40, width * 2.5);
                    const maxRight = x1 + Math.max(120, width * 8);

                    return pageWords.some((word) => {
                        const text = String(word?.text || '').replace(/\u00A0/g, ' ').trim();
                        if (!text || !/[A-Za-z0-9]/.test(text)) {
                            return false;
                        }

                        const wordLeft = Number(word?.left) || 0;
                        const wordTop = Number(word?.top) || 0;
                        const wordWidth = Number(word?.width) || 0;
                        const wordHeight = Number(word?.height) || 0;
                        const wordRight = wordLeft + wordWidth;
                        const wordBottom = wordTop + wordHeight;
                        if (!(wordWidth > 0 && wordHeight > 0)) {
                            return false;
                        }
                        if (wordRight <= minLeft || wordLeft >= maxRight) {
                            return false;
                        }
                        if (wordRight <= x0 || wordLeft >= x1) {
                            const verticalOverlap = Math.max(
                                0,
                                Math.min(y1 + verticalBandPadding, wordBottom) - Math.max(y0 - verticalBandPadding, wordTop)
                            );
                            if (verticalOverlap <= 0) {
                                return false;
                            }
                            const minHeight = Math.max(1, Math.min((y1 - y0) + (verticalBandPadding * 2), wordHeight));
                            return (verticalOverlap / minHeight) >= 0.35;
                        }
                        return false;
                    });
                };

                drawnBoxRects.forEach((parentRect, parentIndex) => {
                    const parentWidth = Number(parentRect?.[2]) - Number(parentRect?.[0]);
                    const parentHeight = Number(parentRect?.[3]) - Number(parentRect?.[1]);
                    const parentArea = parentWidth * parentHeight;
                    if (!(parentWidth > 0 && parentHeight > 0 && parentArea > 0)) {
                        return;
                    }

                    const childIndexes = [];
                    drawnBoxRects.forEach((childRect, childIndex) => {
                        if (childIndex === parentIndex) {
                            return;
                        }
                        const childWidth = Number(childRect?.[2]) - Number(childRect?.[0]);
                        const childHeight = Number(childRect?.[3]) - Number(childRect?.[1]);
                        const childArea = childWidth * childHeight;
                        if (!(childWidth > 0 && childHeight > 0 && childArea > 0)) {
                            return;
                        }
                        if (childArea >= parentArea * 0.45) {
                            return;
                        }
                        if (!pdfRectContainsRect(parentRect, childRect, 0.75)) {
                            return;
                        }
                        childIndexes.push(childIndex);
                    });

                    if (childIndexes.length >= 2) {
                        decorativeRectIndexes.add(parentIndex);
                        childIndexes.forEach((childIndex) => decorativeRectIndexes.add(childIndex));
                    }
                });

                return drawnBoxRects.flatMap((rect, rectIndex) => {
                    if (decorativeRectIndexes.has(rectIndex)) {
                        return [];
                    }

                    const [x0, y0, x1, y1] = rect;
                    const width = x1 - x0;
                    const height = y1 - y0;
                    if (!(width >= 5 && height >= 5)) {
                        return [];
                    }
                    const aspectRatio = width / Math.max(1, height);
                    if (aspectRatio < 0.7 || aspectRatio > 1.3) {
                        return [];
                    }
                    if (width > 24 || height > 24) {
                        return [];
                    }
                    if (widgetRects.some((widgetRect) => pdfRectsIntersect(rect, widgetRect, 0.5))) {
                        return [];
                    }
                    if (!rectHasNearbyLabelText(rect)) {
                        return [];
                    }

                    return [{
                        rect,
                        rectIndex,
                        pageHeight,
                        annotationId: `detected_checkbox_${Number(pageData?.page_number) || (pageIndex + 1)}_${rectIndex}`,
                    }];
                });
            }

            function isSavedAutoDetectedCheckboxValid(annotation, extractionPages) {
                if (!annotation?.autoDetectedDrawnCheckbox) {
                    return true;
                }

                const pageIndex = Number(annotation?.pageIndex);
                if (!Number.isInteger(pageIndex) || pageIndex < 0) {
                    return false;
                }

                const pageEntries = Array.isArray(extractionPages) ? extractionPages : [];
                const pageData = pageEntries[pageIndex];
                if (!pageData) {
                    return false;
                }

                const annotationId = String(annotation?.id || '').trim();
                if (!annotationId) {
                    return false;
                }

                return buildDrawnCheckboxCandidates(pageData, pageIndex).some((candidate) => candidate.annotationId === annotationId);
            }

            function buildAutoDetectedDrawnCheckboxAnnotations(extractionPages) {
                const pageEntries = Array.isArray(extractionPages) ? extractionPages : [];
                let createdCount = 0;

                pageEntries.forEach((pageData, pageIndex) => {
                    buildDrawnCheckboxCandidates(pageData, pageIndex).forEach(({ rect, annotationId, pageHeight }) => {
                        const [x0, y0, x1, y1] = rect;
                        const width = x1 - x0;
                        const height = y1 - y0;
                        const existingAnnotation = annotations.find((annotation) => String(annotation?.id || '') === annotationId);
                        if (existingAnnotation) {
                            return;
                        }

                        const overlapsExistingField = annotations.some((annotation) => {
                            if (!annotation || annotation.type !== 'field' || annotation.pageIndex !== pageIndex) {
                                return false;
                            }
                            const annotationRect = annotationPdfRectOnPage(annotation, pageHeight);
                            return annotationRect ? pdfRectsIntersect(rect, annotationRect, 0.5) : false;
                        });
                        if (overlapsExistingField) {
                            return;
                        }

                        const annotation = {
                            id: annotationId,
                            type: 'field',
                            fieldKind: 'checkbox',
                            fieldName: annotationId,
                            checked: false,
                            pageIndex,
                            pdfX: x0,
                            pdfY: pageHeight - y1,
                            pdfWidth: width,
                            pdfHeight: height,
                            fontSize: 12,
                            textColor: '#111827',
                            backgroundColor: '#e0e7ff',
                            borderColor: 'transparent',
                            accentColor: '#111827',
                            borderWidth: 0,
                            opacity: 1,
                            checkboxMarkSymbol: '✕',
                            autoDetectedDrawnCheckbox: true,
                            keepBounds: true,
                        };

                        normalizeFieldAnnotation(annotation);
                        annotations.push(annotation);
                        createdCount += 1;
                        });
                });

                return createdCount;
            }

            function buildTextAnnotationsFromExtractionBlock(block, pageData, absorbedInlineBlocks = [], prebuiltExtractedSource = null) {
                if (blockBelongsToDecorativeCalloutIconCluster(block, pageData?.blocks || [])) {
                    return [];
                }

                const rawExtractedSource = prebuiltExtractedSource || buildPromotedLineEntriesFromExtractionBlock(block, absorbedInlineBlocks);
                const extractedSource = trimPromotedLeadingBulletLeadInFromSourceBlock(block, pageData, rawExtractedSource);
                if (!extractedSource) {
                    return [];
                }
                const {
                    lineEntries = [],
                    sourceLineBBoxes = [],
                    sourceSpans = [],
                } = extractedSource;
                const detachedMarkerAnnotations = buildPromotedDetachedMarkerAnnotations(block, pageData, extractedSource);
                const syntheticLeaderAnnotation = buildPromotedSyntheticLeaderAnnotationForRightAlignedLabelBlock(block, pageData, extractedSource);

                const compactFormLabelSplitAnnotations = buildPromotedCompactFormLabelSplitAnnotations(block, pageData, extractedSource);
                if (compactFormLabelSplitAnnotations.length > 0) {
                    return (syntheticLeaderAnnotation
                        ? [syntheticLeaderAnnotation, ...compactFormLabelSplitAnnotations]
                        : compactFormLabelSplitAnnotations
                    ).concat(detachedMarkerAnnotations);
                }

                const inlineRightLabelSpanSplitAnnotations = buildPromotedInlineRightLabelSpanSplitAnnotations(block, pageData, extractedSource);
                if (inlineRightLabelSpanSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(inlineRightLabelSpanSplitAnnotations);
                }

                const bulletListSplitAnnotations = buildPromotedBulletListSplitAnnotations(block, pageData, extractedSource);
                if (bulletListSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(bulletListSplitAnnotations);
                }

                const markerAlignedLineSplitAnnotations = buildPromotedMarkerAlignedLineSplitAnnotations(block, pageData, extractedSource);
                if (markerAlignedLineSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(markerAlignedLineSplitAnnotations);
                }

                const rightLabelLeaderLineSplitAnnotations = buildPromotedRightLabelLeaderLineSplitAnnotations(block, pageData, extractedSource);
                if (rightLabelLeaderLineSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(rightLabelLeaderLineSplitAnnotations);
                }

                const inlineBulletRowSplitAnnotations = buildPromotedInlineBulletRowSplitAnnotations(block, pageData, extractedSource);
                if (inlineBulletRowSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(inlineBulletRowSplitAnnotations);
                }

                const compactLabelAlignedLineSplitAnnotations = buildPromotedSiblingCompactLabelAlignedLineSplitAnnotations(block, pageData, extractedSource);
                if (compactLabelAlignedLineSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(compactLabelAlignedLineSplitAnnotations);
                }

                const numberedItemSplitAnnotations = buildPromotedNumberedItemSplitAnnotations(block, pageData, extractedSource);
                if (numberedItemSplitAnnotations.length > 1) {
                    return detachedMarkerAnnotations.concat(numberedItemSplitAnnotations);
                }

                const shouldPreferRowSplitOverColumnSplit = lineEntries.some((entry) => (
                    promotedLineEntryLooksLikeLeaderOnly(entry)
                    || promotedLineEntryLooksLikeRightAlignedFormLabel(entry)
                ));
                if (!shouldPreferRowSplitOverColumnSplit) {
                    const columnSplitAnnotations = buildPromotedColumnSplitAnnotationsFromSourceBlock(block, pageData, extractedSource);
                    if (columnSplitAnnotations.length > 1) {
                        return detachedMarkerAnnotations.concat(columnSplitAnnotations);
                    }
                }

                const embeddedHeadingSplitAnnotations = buildPromotedEmbeddedHeadingSplitAnnotations(block, pageData, extractedSource);
                if (embeddedHeadingSplitAnnotations.length > 1) {
                    return embeddedHeadingSplitAnnotations.concat(detachedMarkerAnnotations);
                }

                const leadingHeadingSplitAnnotations = buildPromotedLeadingHeadingSplitAnnotations(block, pageData, extractedSource);
                if (leadingHeadingSplitAnnotations.length > 1) {
                    return leadingHeadingSplitAnnotations.concat(detachedMarkerAnnotations);
                }

                const baseAnnotation = buildPromotedTextAnnotationFromSource(block, pageData, extractedSource);
                if (!baseAnnotation) {
                    return syntheticLeaderAnnotation
                        ? [syntheticLeaderAnnotation, ...detachedMarkerAnnotations]
                        : detachedMarkerAnnotations;
                }

                if (!lineEntries.length || sourceLineBBoxes.length < 2) {
                    return syntheticLeaderAnnotation
                        ? [syntheticLeaderAnnotation, baseAnnotation, ...detachedMarkerAnnotations]
                        : [baseAnnotation, ...detachedMarkerAnnotations];
                }

                const clusters = clusterPromotedExtractionLineEntries(lineEntries);
                const forceFormRowSplit = shouldForcePromotedFormRowSplit(lineEntries, clusters);
                const forceSemanticClusterSplit = shouldForcePromotedSemanticClusterSplit(lineEntries, clusters);
                const forceGapClusterSplit = shouldForcePromotedGapClusterSplit(lineEntries, clusters);
                if ((!lineGroupingEditorMode && !forceFormRowSplit && !forceSemanticClusterSplit && !forceGapClusterSplit) || clusters.length <= 1) {
                    return syntheticLeaderAnnotation
                        ? [syntheticLeaderAnnotation, baseAnnotation, ...detachedMarkerAnnotations]
                        : [baseAnnotation, ...detachedMarkerAnnotations];
                }

                const splitAnnotations = clusters.map((cluster) => {
                    const clusterStartIndex = Number(cluster[0]?.index) || 0;
                    const clusterEndIndex = Number(cluster[cluster.length - 1]?.index) || clusterStartIndex;
                    const clusterLineBBoxes = cluster.map((entry) => entry.bbox);
                    const clusterSpans = cluster.flatMap((entry) => Array.isArray(entry.spans) ? entry.spans : []);
                    return buildPromotedTextAnnotationFromSource(block, pageData, {
                        textLines: cluster.map((entry) => entry.text),
                        sourceLineBBoxes: clusterLineBBoxes,
                        sourceSpans: clusterSpans.length ? clusterSpans : sourceSpans,
                        sourceKeySuffix: `lines-${clusterStartIndex}-${clusterEndIndex}`,
                    });
                }).filter(Boolean);

                if (splitAnnotations.length) {
                    return (syntheticLeaderAnnotation
                        ? [syntheticLeaderAnnotation, ...splitAnnotations]
                        : splitAnnotations
                    ).concat(detachedMarkerAnnotations);
                }

                return syntheticLeaderAnnotation
                    ? [syntheticLeaderAnnotation, baseAnnotation, ...detachedMarkerAnnotations]
                    : [baseAnnotation, ...detachedMarkerAnnotations];
            }

            function promotedAnnotationSourceLineBBoxes(annotation) {
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                return Array.isArray(sourceMeta?.sourceLineBBoxes)
                    ? sourceMeta.sourceLineBBoxes
                        .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        .map((bbox) => bbox.map((value) => Number(value) || 0))
                    : [];
            }

            function promotedAnnotationSourceTextLines(annotation) {
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                const sourceTextLines = Array.isArray(sourceMeta?.sourceTextLines)
                    ? sourceMeta.sourceTextLines.map((line) => String(line ?? ''))
                    : String(annotation?.text || '').split('\n');
                return sourceTextLines
                    .map((line) => sanitizePromotedExtractionLine(line))
                    .filter((line) => line !== '');
            }

            function promotedAnnotationDominantFontWeight(annotation) {
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                const spanWeights = (Array.isArray(sourceMeta?.sourceSpans) ? sourceMeta.sourceSpans : [])
                    .map((span) => Number(span?.fontWeight ?? span?.font_weight) || 0)
                    .filter((weight) => weight > 0);
                if (spanWeights.length) {
                    return Math.max(...spanWeights);
                }
                return Number(annotation?.fontWeight) || 0;
            }

            function promotedAnnotationLooksLikeHeadingLabel(annotation) {
                if (!annotation?.promotedFromExtraction) {
                    return false;
                }

                const text = String(annotation?.text || '').replace(/\u00A0/g, ' ').replace(/\s+/g, ' ').trim();
                if (!text || text.length > 48) {
                    return false;
                }

                const lineBoxes = promotedAnnotationSourceLineBBoxes(annotation);
                if (lineBoxes.length > 2) {
                    return false;
                }

                const maxWidth = lineBoxes.length
                    ? Math.max(...lineBoxes.map((bbox) => Math.max(0, (Number(bbox[2]) || 0) - (Number(bbox[0]) || 0))))
                    : (Number(annotation?.pdfWidth) || 0);
                if (maxWidth > 220) {
                    return false;
                }

                return promotedAnnotationDominantFontWeight(annotation) >= 600;
            }

            function promotedAnnotationShouldUseTransparentMask(annotation) {
                if (!annotation) {
                    return false;
                }
                if (annotation.promotedCompactFieldLabel) {
                    return true;
                }
                if (!annotation.promotedFromExtraction) {
                    return false;
                }
                const sourceLines = promotedAnnotationSourceTextLines(annotation);
                if (sourceLines.length !== 1) {
                    return false;
                }
                const text = String(sourceLines[0] || '').replace(/\u00A0/g, ' ').trim();
                if (!text || text.length > 48) {
                    return false;
                }
                if (/^\d+[A-Za-z]?$/.test(text)) {
                    return true;
                }
                return /^[A-Z][A-Z0-9\s'()\/-]{1,40}$/.test(text);
            }

            function shouldMergeAdjacentPromotedContinuationAnnotations(previousAnnotation, nextAnnotation) {
                if (!previousAnnotation?.promotedFromExtraction || !nextAnnotation?.promotedFromExtraction) {
                    return false;
                }
                if (previousAnnotation.promotedDirty || nextAnnotation.promotedDirty || previousAnnotation.promotedReflowEnabled || nextAnnotation.promotedReflowEnabled) {
                    return false;
                }
                if ((Number(previousAnnotation.pageIndex) || 0) !== (Number(nextAnnotation.pageIndex) || 0)) {
                    return false;
                }
                if (promotedAnnotationLooksLikeHeadingLabel(previousAnnotation) || promotedAnnotationLooksLikeHeadingLabel(nextAnnotation)) {
                    return false;
                }

                const previousBoxes = promotedAnnotationSourceLineBBoxes(previousAnnotation);
                const nextBoxes = promotedAnnotationSourceLineBBoxes(nextAnnotation);
                if (!previousBoxes.length || !nextBoxes.length) {
                    return false;
                }

                const previousLastBox = previousBoxes[previousBoxes.length - 1];
                const nextFirstBox = nextBoxes[0];
                const verticalGap = (Number(nextFirstBox[1]) || 0) - (Number(previousLastBox[3]) || 0);
                const leftDelta = Math.abs((Number(nextFirstBox[0]) || 0) - (Number(previousLastBox[0]) || 0));
                if (verticalGap < -1 || verticalGap > 4.5 || leftDelta > 4) {
                    return false;
                }

                const previousLines = promotedAnnotationSourceTextLines(previousAnnotation);
                const nextLines = promotedAnnotationSourceTextLines(nextAnnotation);
                const previousLastLine = String(previousLines[previousLines.length - 1] || '').trim();
                const nextFirstLine = String(nextLines[0] || '').trim();
                if (!previousLastLine || !nextFirstLine) {
                    return false;
                }

                if (/[A-Za-z]-$/.test(previousLastLine)) {
                    return true;
                }

                return previousLastLine.length >= 16
                    && !/[.!?:;]$/.test(previousLastLine)
                    && /^[a-z]/.test(nextFirstLine);
            }

            function mergePromotedContinuationAnnotationPair(previousAnnotation, nextAnnotation) {
                const previousMeta = getPromotedAnnotationSourceMeta(previousAnnotation) || {};
                const nextMeta = getPromotedAnnotationSourceMeta(nextAnnotation) || {};
                const combinedLineBBoxes = [
                    ...promotedAnnotationSourceLineBBoxes(previousAnnotation),
                    ...promotedAnnotationSourceLineBBoxes(nextAnnotation),
                ];
                const combinedTextLines = [
                    ...promotedAnnotationSourceTextLines(previousAnnotation),
                    ...promotedAnnotationSourceTextLines(nextAnnotation),
                ];
                const combinedSourceSpans = [
                    ...(Array.isArray(previousMeta?.sourceSpans) ? previousMeta.sourceSpans : []),
                    ...(Array.isArray(nextMeta?.sourceSpans) ? nextMeta.sourceSpans : []),
                ].sort((leftSpan, rightSpan) => {
                    const leftBox = Array.isArray(leftSpan?.bbox) ? leftSpan.bbox : [0, 0, 0, 0];
                    const rightBox = Array.isArray(rightSpan?.bbox) ? rightSpan.bbox : [0, 0, 0, 0];
                    const topDelta = (Number(leftBox[1]) || 0) - (Number(rightBox[1]) || 0);
                    if (Math.abs(topDelta) > 1) {
                        return topDelta;
                    }
                    return (Number(leftBox[0]) || 0) - (Number(rightBox[0]) || 0);
                });
                const pageHeight = Number(previousMeta?.sourcePageHeight ?? nextMeta?.sourcePageHeight) || Number(previousAnnotation?.sourcePageHeight) || 0;
                const left = Math.min(...combinedLineBBoxes.map((bbox) => Number(bbox?.[0]) || 0));
                const top = Math.min(...combinedLineBBoxes.map((bbox) => Number(bbox?.[1]) || 0));
                const right = Math.max(...combinedLineBBoxes.map((bbox) => Number(bbox?.[2]) || left));
                const bottom = Math.max(...combinedLineBBoxes.map((bbox) => Number(bbox?.[3]) || top));
                const combinedSourceKey = [
                    String(previousAnnotation?.promotedSourceKey || '').trim(),
                    String(nextAnnotation?.promotedSourceKey || '').trim(),
                ].filter(Boolean).join('__merge__');

                const mergedAnnotation = {
                    ...previousAnnotation,
                    id: `${String(previousAnnotation?.id || 'promoted')}_merge_${String(nextAnnotation?.id || 'promoted')}`,
                    text: combinedTextLines.join('\n'),
                    originalText: combinedTextLines.join('\n'),
                    pdfX: left,
                    pdfY: pageHeight > 0 ? (pageHeight - bottom) : (Number(previousAnnotation?.pdfY) || 0),
                    pdfWidth: Math.max(1, right - left),
                    pdfHeight: Math.max(1, bottom - top),
                    keepBounds: true,
                    promotedDirty: false,
                    promotedSourceKey: combinedSourceKey || String(previousAnnotation?.promotedSourceKey || ''),
                };

                setPromotedAnnotationSourceMeta(mergedAnnotation, {
                    sourceBlockLeft: left,
                    sourceBlockTop: top,
                    sourceBlockWidth: Math.max(1, right - left),
                    sourceBlockHeight: Math.max(1, bottom - top),
                    sourcePageHeight: pageHeight,
                    sourceTextLines: combinedTextLines,
                    sourceLineBBoxes: combinedLineBBoxes,
                    sourceSpans: combinedSourceSpans,
                });
                normalizeTextAnnotation(mergedAnnotation);
                return mergedAnnotation;
            }

            function mergeAdjacentPromotedContinuationAnnotations(annotationList) {
                const merged = [];

                (Array.isArray(annotationList) ? annotationList : []).forEach((annotation) => {
                    if (!annotation) {
                        return;
                    }
                    const previousAnnotation = merged[merged.length - 1] || null;
                    if (previousAnnotation && shouldMergeAdjacentPromotedContinuationAnnotations(previousAnnotation, annotation)) {
                        merged[merged.length - 1] = mergePromotedContinuationAnnotationPair(previousAnnotation, annotation);
                        return;
                    }
                    merged.push(annotation);
                });

                return merged;
            }

            function buildAbsorbedInlinePromotedBlockMap(pageBlocks) {
                const blocks = Array.isArray(pageBlocks) ? pageBlocks.filter((block) => block && typeof block === 'object') : [];
                const absorbedByParent = new Map();
                const absorbedChildBlockNums = new Set();

                const normalizeComparable = (value) => String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
                const getBlockRect = (block) => {
                    const left = Number(block?.left) || 0;
                    const top = Number(block?.top) || 0;
                    const width = Number(block?.width) || 0;
                    const height = Number(block?.height) || 0;
                    return {
                        left,
                        top,
                        right: left + width,
                        bottom: top + height,
                        width,
                        height,
                    };
                };
                const rectContains = (outer, inner, tolerance = 2) => (
                    inner.left >= (outer.left - tolerance)
                    && inner.right <= (outer.right + tolerance)
                    && inner.top >= (outer.top - tolerance)
                    && inner.bottom <= (outer.bottom + tolerance)
                );

                blocks.forEach((childBlock) => {
                    const childText = sanitizePromotedExtractionText(childBlock?.text || '');
                    const childLines = Array.isArray(childBlock?.text_lines) ? childBlock.text_lines.filter(Boolean) : [];
                    if (!childText || childLines.length > 1) {
                        return;
                    }
                    const childRect = getBlockRect(childBlock);
                    if (childRect.width <= 0 || childRect.height <= 0 || childRect.width > 120 || childRect.height > 24) {
                        return;
                    }

                    let bestParent = null;
                    let bestScore = -1;
                    const normalizedChildText = normalizeComparable(childText);

                    blocks.forEach((parentBlock) => {
                        if (parentBlock === childBlock) {
                            return;
                        }
                        const parentText = sanitizePromotedExtractionText(parentBlock?.text || '');
                        if (!parentText) {
                            return;
                        }
                        const normalizedParentText = normalizeComparable(parentText);
                        const parentHasUnderlinePlaceholder = /_{3,}/.test(String(parentBlock?.text || ''))
                            || (Array.isArray(parentBlock?.text_lines) && parentBlock.text_lines.some((line) => /_{3,}/.test(String(line || ''))))
                            || (Array.isArray(parentBlock?.spans) && parentBlock.spans.some((span) => /_{3,}/.test(String(span?.text || ''))));
                        const childLooksLikeFilledValue = /^[0-9][0-9,./$%-]*$/.test(String(childText || '').trim());
                        if (!normalizedParentText.includes(normalizedChildText) && !(parentHasUnderlinePlaceholder && childLooksLikeFilledValue)) {
                            return;
                        }

                        const parentRect = getBlockRect(parentBlock);
                        if (parentRect.width <= childRect.width || parentRect.height <= childRect.height) {
                            return;
                        }
                        if (!rectContains(parentRect, childRect)) {
                            return;
                        }

                        const parentLineBoxes = Array.isArray(parentBlock?.line_bboxes)
                            ? parentBlock.line_bboxes.filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                            : [];
                        const childMidY = childRect.top + (childRect.height / 2);
                        const lineMatch = parentLineBoxes.some((bbox) => {
                            const top = Number(bbox?.[1]) || 0;
                            const bottom = Number(bbox?.[3]) || top;
                            return childMidY >= (top - 2) && childMidY <= (bottom + 2);
                        });
                        if (!lineMatch) {
                            return;
                        }

                        const score = ((parentRect.width * parentRect.height) - (childRect.width * childRect.height)) * -1;
                        if (bestParent === null || score > bestScore) {
                            bestParent = parentBlock;
                            bestScore = score;
                        }
                    });

                    if (!bestParent) {
                        return;
                    }

                    const parentKey = Number(bestParent?.block_num);
                    if (!Number.isFinite(parentKey)) {
                        return;
                    }
                    if (!absorbedByParent.has(parentKey)) {
                        absorbedByParent.set(parentKey, []);
                    }
                    absorbedByParent.get(parentKey).push(childBlock);
                    absorbedChildBlockNums.add(Number(childBlock?.block_num));
                });

                return {
                    absorbedByParent,
                    absorbedChildBlockNums,
                };
            }

            function buildTextAnnotationFromSavedState(annotationData) {
                if (!annotationData || typeof annotationData !== 'object') {
                    return null;
                }

                const promotedSourcePageNumber = Number(annotationData.promotedSourcePage);
                const savedPageIndex = Number(annotationData.pageIndex);
                const normalizedPageIndex = annotationData.promotedFromExtraction && promotedSourcePageNumber > 0
                    ? Math.max(0, promotedSourcePageNumber - 1)
                    : (Number.isFinite(savedPageIndex) ? savedPageIndex : 0);

                const normalized = {
                    ...annotationData,
                    pageIndex: normalizedPageIndex,
                    pdfX: Number(annotationData.pdfX) || 0,
                    pdfY: Number(annotationData.pdfY) || 0,
                    fontSize: Number(annotationData.fontSize) || 12,
                    opacity: Number(annotationData.opacity ?? 1),
                };
                const savedTextSnapshot = sanitizePromotedExtractionText(annotationData.text || '');
                const savedOriginalTextSnapshot = sanitizePromotedExtractionText(annotationData.originalText || annotationData.text || '');
                const savedHasMaterialEdits = Boolean(annotationData.promotedDirty)
                    || (
                        savedTextSnapshot !== ''
                        && savedTextSnapshot !== savedOriginalTextSnapshot
                    );
                const legacySourceMeta = extractLegacyPromotedAnnotationSourceMeta(annotationData);
                if (annotationData.requestedFontSize !== undefined && annotationData.requestedFontSize !== null) {
                    normalized.requestedFontSize = Number(annotationData.requestedFontSize) || null;
                }

                if (!normalized.promotedFromExtraction) {
                    normalized.savedTextOverlay = true;
                } else {
                    delete normalized.savedTextOverlay;
                }
                normalized.savedDatabaseAnnotation = true;

                if (annotationData.pdfWidth !== undefined && annotationData.pdfWidth !== null) {
                    normalized.pdfWidth = Number(annotationData.pdfWidth) || 0;
                }
                if (annotationData.pdfHeight !== undefined && annotationData.pdfHeight !== null) {
                    normalized.pdfHeight = Number(annotationData.pdfHeight) || 0;
                }
                if (annotationData.lineHeight !== undefined && annotationData.lineHeight !== null) {
                    normalized.lineHeight = Number(annotationData.lineHeight) || null;
                }
                if (normalized.promotedFromExtraction) {
                    normalized.text = sanitizePromotedExtractionText(normalized.text || '');
                    normalized.originalText = sanitizePromotedExtractionText(normalized.originalText || normalized.text || '');
                }
                if (shouldEnablePromotedAnnotationReflow(normalized)) {
                    normalized.promotedReflowEnabled = true;
                }

                if (legacySourceMeta) {
                    setPromotedAnnotationSourceMeta(normalized, legacySourceMeta);
                    delete normalized.sourceBlockLeft;
                    delete normalized.sourceBlockTop;
                    delete normalized.sourceBlockWidth;
                    delete normalized.sourceBlockHeight;
                    delete normalized.sourcePageHeight;
                    delete normalized.sourceTextLines;
                    delete normalized.sourceLineBBoxes;
                    delete normalized.sourceSpans;
                }

                let promotedSourceMeta = legacySourceMeta || getPromotedAnnotationSourceMeta(normalized);
                repairSavedPromotedAnnotationCorruption(normalized, promotedSourceMeta);
                if (normalized.promotedFromExtraction && savedHasMaterialEdits) {
                    normalized.text = savedTextSnapshot || normalized.text;
                    normalized.originalText = savedOriginalTextSnapshot || normalized.originalText || normalized.text;
                    normalized.promotedDirty = true;
                    promotedSourceMeta = trimDirtyPromotedSourceMetaToCurrentLines(normalized, promotedSourceMeta) || promotedSourceMeta;
                }
                if (normalized.promotedFromExtraction) {
                    const lineBoxes = Array.isArray(promotedSourceMeta?.sourceLineBBoxes)
                        ? promotedSourceMeta.sourceLineBBoxes
                            .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                            .map((bbox) => bbox.map((value) => Number(value) || 0))
                        : [];
                    const inferredWidth = Number(promotedSourceMeta?.sourceBlockWidth) > 0
                        ? Number(promotedSourceMeta.sourceBlockWidth)
                        : (lineBoxes.length
                            ? Math.max(...lineBoxes.map((bbox) => Number(bbox[2]) || 0)) - Math.min(...lineBoxes.map((bbox) => Number(bbox[0]) || 0))
                            : 0);
                    const inferredHeight = Number(promotedSourceMeta?.sourceBlockHeight) > 0
                        ? Number(promotedSourceMeta.sourceBlockHeight)
                        : (lineBoxes.length
                            ? Math.max(...lineBoxes.map((bbox) => Number(bbox[3]) || 0)) - Math.min(...lineBoxes.map((bbox) => Number(bbox[1]) || 0))
                            : 0);
                    if (!(Number(normalized.pdfWidth) > 0) && inferredWidth > 0) {
                        normalized.pdfWidth = inferredWidth;
                    }
                    if (!(Number(normalized.pdfHeight) > 0) && inferredHeight > 0) {
                        normalized.pdfHeight = inferredHeight;
                    }
                }

                normalizeTextAnnotation(normalized);
                if (canPreservePromotedAnnotationSourceLineLayout(normalized, normalized.text, {
                    richTextHtml: normalized.richTextHtml || '',
                })) {
                    delete normalized.promotedReflowEnabled;
                }
                if (shouldResetPromotedAnnotationReflow(normalized)) {
                    delete normalized.promotedReflowEnabled;
                }
                return normalized;
            }

            function buildSavedNonTextAnnotationFromState(annotationData) {
                if (!annotationData || typeof annotationData !== 'object') {
                    return null;
                }
                if (annotationData.type === 'text' || !annotationData.type) {
                    return null;
                }

                const normalized = {
                    ...annotationData,
                    pageIndex: Number(annotationData.pageIndex) || 0,
                    pdfX: Number(annotationData.pdfX) || 0,
                    pdfY: Number(annotationData.pdfY) || 0,
                    opacity: Number(annotationData.opacity ?? 1),
                    rotation: Number(annotationData.rotation) || 0,
                    savedDatabaseAnnotation: true,
                };

                if (annotationData.pdfWidth !== undefined && annotationData.pdfWidth !== null) {
                    normalized.pdfWidth = Number(annotationData.pdfWidth) || 0;
                }
                if (annotationData.pdfHeight !== undefined && annotationData.pdfHeight !== null) {
                    normalized.pdfHeight = Number(annotationData.pdfHeight) || 0;
                }
                if (annotationData.fontSize !== undefined && annotationData.fontSize !== null) {
                    normalized.fontSize = Number(annotationData.fontSize) || 12;
                }
                if (annotationData.strokeWidth !== undefined && annotationData.strokeWidth !== null) {
                    normalized.strokeWidth = Number(annotationData.strokeWidth) || 0;
                }
                if (annotationData.lineHeight !== undefined && annotationData.lineHeight !== null) {
                    normalized.lineHeight = Number(annotationData.lineHeight) || null;
                }

                return normalized;
            }

            function clearPromotedExtractionAnnotations() {
                for (let index = annotations.length - 1; index >= 0; index -= 1) {
                    if (annotations[index]?.promotedFromExtraction) {
                        annotations.splice(index, 1);
                    }
                }
            }

            function clearSavedTextOverlayAnnotations() {
                for (let index = annotations.length - 1; index >= 0; index -= 1) {
                    if (annotations[index]?.savedTextOverlay && annotations[index]?.savedDatabaseAnnotation) {
                        annotations.splice(index, 1);
                    }
                }
            }

            function clearSavedNonTextDatabaseAnnotations() {
                for (let index = annotations.length - 1; index >= 0; index -= 1) {
                    const annotation = annotations[index];
                    if (annotation?.savedDatabaseAnnotation && annotation?.type && annotation.type !== 'text') {
                        annotations.splice(index, 1);
                    }
                }
            }

            function hydrateSavedTextAnnotations(savedAnnotations) {
                const hydrated = [];
                const seenIds = new Set();

                (Array.isArray(savedAnnotations) ? savedAnnotations : []).forEach((annotationData) => {
                    const annotation = buildTextAnnotationFromSavedState(annotationData);
                    if (!annotation || deletedSavedTextAnnotationIds.has(String(annotation.id || ''))) {
                        return;
                    }
                    const annotationId = String(annotation.id || '');
                    if (annotationId && seenIds.has(annotationId)) {
                        return;
                    }
                    if (annotationId) {
                        seenIds.add(annotationId);
                    }
                    hydrated.push(annotation);
                });

                clearSavedTextOverlayAnnotations();
                hydrated.forEach((annotation) => { registerAnnotationId(annotation); annotations.push(annotation); });
                return hydrated.length;
            }

            function estimateSavedTextAnnotationBounds(annotation) {
                const fontSize = Math.max(1, Number(annotation?.fontSize) || 12);
                const fontFamily = resolveAnnotationCssFontFamily(annotation?.fontFamily || 'Helvetica', {
                    preferExact: Boolean(annotation?.promotedFromExtraction),
                    exactFontName: annotation?.fontSourceName || '',
                });
                const lineHeight = Math.max(1, Number(annotation?.lineHeight) || (fontSize * 1.2));
                const lines = String(annotation?.text || '').split('\n');
                const widestLine = lines.reduce((maxWidth, line) => (
                    Math.max(maxWidth, measureAnnotationTextWidth(line, fontSize, fontFamily, annotation?.fontWeight, annotation?.fontStyle))
                ), 0);

                return {
                    width: widestLine,
                    height: lineHeight * Math.max(1, lines.length),
                };
            }

            function getSavedAnnotationRect(annotation) {
                if (!annotation) {
                    return null;
                }
                const left = Number(annotation.pdfX) || 0;
                let width = Number(annotation.pdfWidth) || 0;
                let height = Number(annotation.pdfHeight) || 0;
                if ((width <= 0 || height <= 0) && annotation.savedTextOverlay) {
                    const estimatedBounds = estimateSavedTextAnnotationBounds(annotation);
                    width = width > 0 ? width : estimatedBounds.width;
                    height = height > 0 ? height : estimatedBounds.height;
                }
                if (width <= 0 || height <= 0) {
                    return null;
                }
                const rawY = Number(annotation.pdfY) || 0;
                const hasBounds = Number(annotation.pdfWidth) > 0 && Number(annotation.pdfHeight) > 0;
                const bottom = hasBounds ? rawY : (rawY - height);
                const top = hasBounds ? (rawY + height) : rawY;
                return {
                    left,
                    bottom,
                    right: left + width,
                    top,
                    width,
                    height,
                };
            }

            function hydrateSavedNonTextAnnotations(savedAnnotations, extractionPages = []) {
                const hydrated = [];
                const seenIds = new Set();

                (Array.isArray(savedAnnotations) ? savedAnnotations : []).forEach((annotationData) => {
                    if (!isSavedAutoDetectedCheckboxValid(annotationData, extractionPages)) {
                        return;
                    }
                    const annotation = buildSavedNonTextAnnotationFromState(annotationData);
                    if (!annotation) {
                        return;
                    }
                    const annotationId = String(annotation.id || '');
                    if (annotationId && seenIds.has(annotationId)) {
                        return;
                    }
                    if (annotationId) {
                        seenIds.add(annotationId);
                    }
                    hydrated.push(annotation);
                });

                clearSavedNonTextDatabaseAnnotations();
                hydrated.forEach((annotation) => { registerAnnotationId(annotation); annotations.push(annotation); });
                return hydrated.length;
            }

            function collectExistingDirtyBoundingBoxPromotedAnnotations() {
                const existingBySourceKey = new Map();

                annotations.forEach((annotation) => {
                    if (!annotation?.promotedFromExtraction || !annotation?.promotedSourceKey) {
                        return;
                    }
                    if (!annotation.promotedDirty && !annotation.promotedReflowEnabled) {
                        return;
                    }

                    existingBySourceKey.set(String(annotation.promotedSourceKey), annotation);
                });

                return existingBySourceKey;
            }

            function hydrateBoundingBoxEditPromotedAnnotations(savedAnnotations, extractionPages = []) {
                const hydrated = [];
                const seenIds = new Set();
                const seenSourceKeys = new Set();
                const existingDirtyBySourceKey = collectExistingDirtyBoundingBoxPromotedAnnotations();
                const normalizedPages = Array.isArray(extractionPages) ? extractionPages : [];

                const pushAnnotation = (annotation) => {
                    if (!annotation?.promotedFromExtraction) {
                        return;
                    }

                    const sourceKey = String(annotation.promotedSourceKey || '').trim();
                    if (!sourceKey || deletedPromotedSourceKeys.has(sourceKey) || seenSourceKeys.has(sourceKey)) {
                        return;
                    }

                    const annotationId = String(annotation.id || '').trim();
                    if (annotationId && seenIds.has(annotationId)) {
                        return;
                    }

                    seenSourceKeys.add(sourceKey);
                    if (annotationId) {
                        seenIds.add(annotationId);
                    }
                    hydrated.push(annotation);
                };

                const normalizedSavedAnnotations = Array.isArray(savedAnnotations) ? savedAnnotations : [];
                if (normalizedSavedAnnotations.length > 0) {
                    normalizedSavedAnnotations.forEach((annotationData) => {
                        const savedAnnotation = buildTextAnnotationFromSavedState(annotationData);
                        if (!savedAnnotation?.promotedFromExtraction || !savedAnnotation?.promotedSourceKey) {
                            return;
                        }

                        const sourceKey = String(savedAnnotation.promotedSourceKey || '').trim();
                        const dirtyAnnotation = existingDirtyBySourceKey.get(sourceKey);
                        pushAnnotation(dirtyAnnotation || savedAnnotation);
                    });
                } else {
                    normalizedPages.forEach((pageData) => {
                        const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];
                        pageBlocks.forEach((block) => {
                            const pageNumber = Number(pageData?.page_number) || 1;
                            const blockNumber = Number(block?.block_num) || 0;
                            const sourceKey = `block-${pageNumber}-${blockNumber}`;
                            if (deletedPromotedSourceKeys.has(sourceKey)) {
                                return;
                            }

                            const dirtyAnnotation = existingDirtyBySourceKey.get(sourceKey);
                            if (dirtyAnnotation) {
                                pushAnnotation(dirtyAnnotation);
                                return;
                            }

                            const annotation = buildPromotedTextAnnotationFromSource(block, pageData, {
                                textLines: Array.isArray(block?.text_lines) ? block.text_lines : [],
                                sourceLineBBoxes: Array.isArray(block?.line_bboxes) ? block.line_bboxes : [],
                                sourceSpans: Array.isArray(block?.spans)
                                    ? block.spans
                                        .filter((span) => span && Array.isArray(span.bbox) && span.bbox.length >= 4)
                                        .map((span) => ({
                                            ...span,
                                            bbox: span.bbox.map((value) => Number(value) || 0),
                                        }))
                                    : [],
                                explicitSourceKey: sourceKey,
                            });

                            pushAnnotation(annotation);
                        });
                    });
                }

                existingDirtyBySourceKey.forEach((annotation, sourceKey) => {
                    if (!seenSourceKeys.has(String(sourceKey)) && !deletedPromotedSourceKeys.has(String(sourceKey))) {
                        pushAnnotation(annotation);
                    }
                });

                clearPromotedExtractionAnnotations();
                hydrated.forEach((annotation) => {
                    registerAnnotationId(annotation);
                    annotations.push(annotation);
                });
                promotedExtractionHydrated = hydrated.length > 0;

                return hydrated.length;
            }

            async function bootstrapBoundingBoxEditAnnotationLayer({ force = false } = {}) {
                if (!boundingBoxEditMode || isImageDocument) {
                    return 0;
                }

                if (
                    !force
                    && annotations.some((annotation) => annotation?.promotedFromExtraction)
                    && annotations.some((annotation) => annotation?.savedDatabaseAnnotation)
                ) {
                    return annotations.filter((annotation) => annotation?.promotedFromExtraction).length;
                }

                const {
                    standaloneSavedAnnotations,
                    promotedSavedAnnotations,
                    otherSavedAnnotations,
                } = await loadSavedTextAnnotationsFromDatabase();
                const extractionPages = Array.isArray(overlayExtractionData) ? overlayExtractionData : [];

                basePdfUrl = cleanPdfUrl;
                pdfVersion = Date.now();

                const standaloneSavedAnnotationCount = hydrateSavedTextAnnotations(standaloneSavedAnnotations);
                const promotedAnnotationCount = hydrateBoundingBoxEditPromotedAnnotations(promotedSavedAnnotations, extractionPages);
                const otherSavedAnnotationCount = hydrateSavedNonTextAnnotations(otherSavedAnnotations, extractionPages);
                const autoDetectedCheckboxCount = buildAutoDetectedDrawnCheckboxAnnotations(extractionPages);

                return standaloneSavedAnnotationCount + promotedAnnotationCount + otherSavedAnnotationCount + autoDetectedCheckboxCount;
            }

            async function loadSavedTextAnnotationsFromDatabase() {
                const sessionId = getStoredPdfSessionId({
                    includeUrl: true,
                    includeLegacyGlobal: loadedSavedPdfMode,
                });
                const savedAnnotationsUrl = new URL(`{{ route('documents.getSavedAnnotations', $document) }}`, window.location.origin);
                if (sessionId) {
                    savedAnnotationsUrl.searchParams.set('session_id', sessionId);
                }

                const response = await fetch(savedAnnotationsUrl.toString(), {
                    credentials: 'same-origin',
                    headers: {
                        Accept: 'application/json',
                    },
                });

                const payload = await response.json().catch(() => ({}));
                if (!response.ok || !payload?.success || !Array.isArray(payload.annotations)) {
                    return {
                        standaloneSavedAnnotations: [],
                        promotedSavedAnnotations: [],
                        otherSavedAnnotations: [],
                    };
                }

                if (payload?.session_id && String(payload.session_id).trim() !== '') {
                    setStoredPdfSessionId(payload.session_id);
                }

                if (Array.isArray(payload?.deleted_promoted_source_keys)) {
                    payload.deleted_promoted_source_keys.forEach((sourceKey) => {
                        const normalizedSourceKey = String(sourceKey || '').trim();
                        if (normalizedSourceKey) {
                            deletedPromotedSourceKeys.add(normalizedSourceKey);
                        }
                    });
                }

                const savedTextAnnotations = payload.annotations.filter((annotation) => (
                    annotation
                    && (annotation.type === 'text' || !annotation.type)
                    && annotation.db_state !== 'deleted'
                ));

                const standaloneSavedAnnotations = [];
                const promotedSavedAnnotations = [];
                const otherSavedAnnotations = [];

                savedTextAnnotations.forEach((annotation) => {
                    if (!annotation || typeof annotation !== 'object') {
                        return;
                    }
                    if (annotation.promotedFromExtraction && annotation.promotedSourceKey) {
                        const annotationId = String(annotation.id || '');
                        const sourceKey = String(annotation.promotedSourceKey || '');
                        if (
                            annotationId && deletedSavedTextAnnotationIds.has(annotationId)
                            || sourceKey && deletedPromotedSourceKeys.has(sourceKey)
                        ) {
                            return;
                        }
                        promotedSavedAnnotations.push(annotation);
                        return;
                    }
                    standaloneSavedAnnotations.push(annotation);
                });

                payload.annotations.forEach((annotation) => {
                    if (!annotation || typeof annotation !== 'object') {
                        return;
                    }
                    if ((annotation.type === 'text' || !annotation.type) || annotation.db_state === 'deleted') {
                        return;
                    }
                    otherSavedAnnotations.push(annotation);
                });

                return {
                    standaloneSavedAnnotations,
                    promotedSavedAnnotations,
                    otherSavedAnnotations,
                };
            }

            function collectStandaloneTextAnnotationsForPromotedSuppression(savedStandaloneAnnotations = []) {
                const collected = [];
                const seenKeys = new Set();
                const pushAnnotation = (annotation) => {
                    if (!annotation || annotation.promotedFromExtraction) {
                        return;
                    }
                    if (annotation.type && annotation.type !== 'text') {
                        return;
                    }

                    const key = [
                        Number(annotation.pageIndex) || 0,
                        (Number(annotation.pdfX) || 0).toFixed(2),
                        (Number(annotation.pdfY) || 0).toFixed(2),
                        (Number(annotation.pdfWidth) || 0).toFixed(2),
                        (Number(annotation.pdfHeight) || 0).toFixed(2),
                        String(annotation.text || '').replace(/\s+/g, ' ').trim(),
                    ].join('|');
                    if (seenKeys.has(key)) {
                        return;
                    }
                    seenKeys.add(key);
                    collected.push(annotation);
                };

                (Array.isArray(savedStandaloneAnnotations) ? savedStandaloneAnnotations : [])
                    .map((annotation) => buildTextAnnotationFromSavedState(annotation))
                    .filter(Boolean)
                    .forEach(pushAnnotation);

                annotations.forEach(pushAnnotation);

                return collected;
            }

            function hydratePromotedAnnotationsFromExtraction(extractionPages, {
                savedPromotedAnnotations = [],
                savedStandaloneAnnotations = [],
            } = {}) {
                const promotedAnnotations = [];
                const seenKeys = new Set();
                const matchedSavedPromotedAnnotationIds = new Set();
                const standaloneTextAnnotationsForSuppression = collectStandaloneTextAnnotationsForPromotedSuppression(savedStandaloneAnnotations);
                const hydratedSavedPromotedAnnotations = (Array.isArray(savedPromotedAnnotations) ? savedPromotedAnnotations : [])
                    .map((annotation) => buildTextAnnotationFromSavedState(annotation))
                    .filter((annotation) => annotation?.promotedFromExtraction);
                const hydratedSavedPromotedBySourceKey = new Map(
                    hydratedSavedPromotedAnnotations
                        .filter((annotation) => annotation?.promotedSourceKey)
                        .map((annotation) => [String(annotation.promotedSourceKey), annotation])
                );
                const existingDirtyPromotedByKey = new Map(
                    annotations
                        .filter((annotation) => annotation?.promotedFromExtraction && annotation?.promotedDirty && annotation?.promotedSourceKey)
                        .map((annotation) => [annotation.promotedSourceKey, annotation])
                );
                const savedPromotedAnnotationHasMaterialEdits = (annotation) => {
                    if (!annotation?.promotedFromExtraction) {
                        return false;
                    }
                    if (annotation.promotedDirty || annotation.promotedReflowEnabled) {
                        return true;
                    }
                    return sanitizePromotedExtractionText(annotation.text || '') !== sanitizePromotedExtractionText(annotation.originalText || '');
                };
                const normalizePromotedComparableText = (value) => String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
                const estimateStandaloneTextBounds = (annotation) => {
                    const fontSize = Math.max(1, Number(annotation?.fontSize) || 12);
                    const fontFamily = resolveAnnotationCssFontFamily(annotation?.fontFamily || 'Helvetica', {
                        preferExact: Boolean(annotation?.promotedFromExtraction),
                        exactFontName: annotation?.fontSourceName || '',
                    });
                    const lineHeight = Math.max(1, Number(annotation?.lineHeight) || (fontSize * 1.2));
                    const lines = String(annotation?.text || '').split('\n');
                    const widestLine = lines.reduce((maxWidth, line) => (
                        Math.max(maxWidth, measureAnnotationTextWidth(line, fontSize, fontFamily, annotation?.fontWeight, annotation?.fontStyle))
                    ), 0);

                    return {
                        width: widestLine,
                        height: lineHeight * Math.max(1, lines.length),
                    };
                };
                const getAnnotationRect = (annotation) => {
                    if (!annotation) {
                        return null;
                    }
                    const left = Number(annotation.pdfX) || 0;
                    let width = Number(annotation.pdfWidth) || 0;
                    let height = Number(annotation.pdfHeight) || 0;
                    if ((width <= 0 || height <= 0) && annotation.savedTextOverlay) {
                        const estimatedBounds = estimateStandaloneTextBounds(annotation);
                        width = width > 0 ? width : estimatedBounds.width;
                        height = height > 0 ? height : estimatedBounds.height;
                    }
                    if (width <= 0 || height <= 0) {
                        return null;
                    }
                    const rawY = Number(annotation.pdfY) || 0;
                    const hasBounds = Number(annotation.pdfWidth) > 0 && Number(annotation.pdfHeight) > 0;
                    const bottom = hasBounds ? rawY : (rawY - height);
                    const top = hasBounds ? (rawY + height) : rawY;
                    return {
                        left,
                        bottom,
                        right: left + width,
                        top,
                        width,
                        height,
                    };
                };
                const rectIntersectionArea = (rectA, rectB) => {
                    if (!rectA || !rectB) {
                        return 0;
                    }
                    const overlapWidth = Math.max(0, Math.min(rectA.right, rectB.right) - Math.max(rectA.left, rectB.left));
                    const overlapHeight = Math.max(0, Math.min(rectA.top, rectB.top) - Math.max(rectA.bottom, rectB.bottom));
                    return overlapWidth * overlapHeight;
                };
                const rectOverlapRatio = (rectA, rectB) => {
                    const intersectionArea = rectIntersectionArea(rectA, rectB);
                    if (intersectionArea <= 0) {
                        return 0;
                    }
                    const minArea = Math.max(1, Math.min(rectA.width * rectA.height, rectB.width * rectB.height));
                    return intersectionArea / minArea;
                };
                const isPromotedAnnotationCompatibleWithExtractionBlock = (savedAnnotation, extractedAnnotation, sourceKey = '') => {
                    if (!savedAnnotation || !extractedAnnotation) {
                        return false;
                    }
                    const normalizedSourceKey = String(sourceKey || '').trim();
                    const savedSourceKey = String(savedAnnotation.promotedSourceKey || '').trim();
                    if (
                        normalizedSourceKey
                        && savedSourceKey
                        && savedSourceKey === normalizedSourceKey
                    ) {
                        return true;
                    }
                    if ((Number(savedAnnotation.pageIndex) || 0) !== (Number(extractedAnnotation.pageIndex) || 0)) {
                        return false;
                    }

                    const savedRect = getAnnotationRect(savedAnnotation);
                    const extractedRect = getAnnotationRect(extractedAnnotation);
                    if (!savedRect || !extractedRect) {
                        return false;
                    }

                    const overlapRatio = rectOverlapRatio(savedRect, extractedRect);
                    const savedCenterX = (savedRect.left + savedRect.right) / 2;
                    const savedCenterY = (savedRect.bottom + savedRect.top) / 2;
                    const extractedCenterX = (extractedRect.left + extractedRect.right) / 2;
                    const extractedCenterY = (extractedRect.bottom + extractedRect.top) / 2;
                    const centerDelta = Math.hypot(savedCenterX - extractedCenterX, savedCenterY - extractedCenterY);
                    const geometryCompatible = (
                        overlapRatio >= 0.55
                        || (
                            centerDelta <= 14
                            && Math.abs(savedRect.width - extractedRect.width) <= 18
                            && Math.abs(savedRect.height - extractedRect.height) <= 18
                        )
                    );
                    if (!geometryCompatible) {
                        return false;
                    }

                    const savedOriginalText = normalizePromotedComparableText(savedAnnotation.originalText || '');
                    const savedCurrentText = normalizePromotedComparableText(savedAnnotation.text || '');
                    const extractedText = normalizePromotedComparableText(extractedAnnotation.text || '');

                    return (
                        (savedOriginalText && savedOriginalText === extractedText)
                        || (savedCurrentText && savedCurrentText === extractedText)
                    );
                };
                const overlapsSavedStandaloneAnnotation = (annotation) => {
                    if (!annotation) {
                        return false;
                    }
                    const annotationRect = getSavedAnnotationRect(annotation);
                    if (!annotationRect) {
                        return false;
                    }

                    return standaloneTextAnnotationsForSuppression.some((savedAnnotation) => {
                        if ((Number(savedAnnotation.pageIndex) || 0) !== (Number(annotation.pageIndex) || 0)) {
                            return false;
                        }
                        const savedRect = getSavedAnnotationRect(savedAnnotation);
                        if (!savedRect) {
                            return false;
                        }

                        return annotationRect.right > savedRect.left
                            && annotationRect.left < savedRect.right
                            && annotationRect.top > savedRect.bottom
                            && annotationRect.bottom < savedRect.top;
                    });
                };

                (Array.isArray(extractionPages) ? extractionPages : []).forEach((pageData) => {
                    const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];
                    const {
                        absorbedByParent,
                        absorbedChildBlockNums,
                    } = buildAbsorbedInlinePromotedBlockMap(pageBlocks);
                    const {
                        transfersByTargetBlock,
                        excludedLineIndexesBySourceBlock,
                    } = buildPromotedTrailingBulletTransferMap(pageBlocks);
                    pageBlocks.forEach((block) => {
                        const blockNum = Number(block?.block_num);
                        if (absorbedChildBlockNums.has(blockNum)) {
                            return;
                        }

                        const rootSourceKey = `block-${pageData.page_number}-${block.block_num}`;
                        if (deletedPromotedSourceKeys.has(rootSourceKey)) {
                            return;
                        }
                        const absorbedInlineBlocks = absorbedByParent.get(blockNum) || [];
                        const extractedSource = buildPromotedLineEntriesFromExtractionBlock(block, absorbedInlineBlocks, {
                            excludedLineIndexes: mergePromotedExcludedLineIndexes(
                                excludedLineIndexesBySourceBlock.get(blockNum)
                            ),
                            transferredMarkerEntries: transfersByTargetBlock.get(blockNum) || [],
                        });
                        if (!extractedSource) {
                            return;
                        }
                        const legacyWholeBlockMatch = existingDirtyPromotedByKey.get(rootSourceKey)
                            || hydratedSavedPromotedBySourceKey.get(rootSourceKey)
                            || null;
                        const shouldHonorLegacyWholeBlockMatch = savedPromotedAnnotationHasMaterialEdits(legacyWholeBlockMatch);
                        const builtAnnotations = buildTextAnnotationsFromExtractionBlock(block, pageData, absorbedInlineBlocks, extractedSource);
                        const candidateAnnotations = shouldHonorLegacyWholeBlockMatch
                            ? [buildPromotedTextAnnotationFromSource(block, pageData, extractedSource)]
                            : builtAnnotations;

                        candidateAnnotations.forEach((builtAnnotation) => {
                            if (!builtAnnotation) {
                                return;
                            }

                            const sourceKey = String(builtAnnotation.promotedSourceKey || rootSourceKey);
                            if (deletedPromotedSourceKeys.has(sourceKey)) {
                                return;
                            }
                            if (
                                !existingDirtyPromotedByKey.has(sourceKey)
                                && !hydratedSavedPromotedBySourceKey.has(sourceKey)
                                && overlapsSavedStandaloneAnnotation(builtAnnotation)
                            ) {
                                return;
                            }

                            let savedPromotedMatch = null;
                            const exactSavedPromotedMatch = hydratedSavedPromotedBySourceKey.get(sourceKey);
                            if (
                                savedPromotedAnnotationHasMaterialEdits(exactSavedPromotedMatch)
                                && isPromotedAnnotationCompatibleWithExtractionBlock(exactSavedPromotedMatch, builtAnnotation, sourceKey)
                            ) {
                                savedPromotedMatch = exactSavedPromotedMatch;
                            }
                            if (!savedPromotedMatch) {
                                savedPromotedMatch = hydratedSavedPromotedAnnotations.find((candidate) => {
                                    if (!savedPromotedAnnotationHasMaterialEdits(candidate)) {
                                        return false;
                                    }
                                    const candidateId = String(candidate?.id || '');
                                    if (candidateId && matchedSavedPromotedAnnotationIds.has(candidateId)) {
                                        return false;
                                    }
                                    return isPromotedAnnotationCompatibleWithExtractionBlock(candidate, builtAnnotation);
                                }) || null;
                            }
                            const annotation = existingDirtyPromotedByKey.get(sourceKey)
                                || savedPromotedMatch
                                || builtAnnotation;
                            if (!annotation) {
                                return;
                            }
                            if (annotation?.promotedFromExtraction && String(annotation.promotedSourceKey || '') === String(sourceKey) && builtAnnotation) {
                                const extractedSourceMeta = getPromotedAnnotationSourceMeta(builtAnnotation);
                                if (extractedSourceMeta) {
                                    const savedSourceMeta = getPromotedAnnotationSourceMeta(annotation);
                                    setPromotedAnnotationSourceMeta(annotation, {
                                        ...extractedSourceMeta,
                                        ...(savedSourceMeta || {}),
                                        sourceTextLines: Array.isArray(extractedSourceMeta?.sourceTextLines) && extractedSourceMeta.sourceTextLines.length
                                            ? extractedSourceMeta.sourceTextLines
                                            : (savedSourceMeta?.sourceTextLines || []),
                                        sourceLineBBoxes: Array.isArray(extractedSourceMeta?.sourceLineBBoxes) && extractedSourceMeta.sourceLineBBoxes.length
                                            ? extractedSourceMeta.sourceLineBBoxes
                                            : (savedSourceMeta?.sourceLineBBoxes || []),
                                        sourceSpans: Array.isArray(extractedSourceMeta?.sourceSpans) && extractedSourceMeta.sourceSpans.length
                                            ? extractedSourceMeta.sourceSpans
                                            : (savedSourceMeta?.sourceSpans || []),
                                        sourceBlockWidth: Number(savedSourceMeta?.sourceBlockWidth) > 0
                                            ? Number(savedSourceMeta.sourceBlockWidth)
                                            : extractedSourceMeta.sourceBlockWidth,
                                        sourceBlockHeight: Number(savedSourceMeta?.sourceBlockHeight) > 0
                                            ? Number(savedSourceMeta.sourceBlockHeight)
                                            : extractedSourceMeta.sourceBlockHeight,
                                        sourcePageHeight: Number(savedSourceMeta?.sourcePageHeight) > 0
                                            ? Number(savedSourceMeta.sourcePageHeight)
                                            : extractedSourceMeta.sourcePageHeight,
                                    });
                                }
                            }
                            if (shouldResetPromotedAnnotationReflow(annotation)) {
                                delete annotation.promotedReflowEnabled;
                            }
                            if (savedPromotedMatch?.id) {
                                matchedSavedPromotedAnnotationIds.add(String(savedPromotedMatch.id));
                            }

                            const dedupeKey = [
                                Number(annotation.pageIndex) || 0,
                                annotation.promotedSourceKey || annotation.promotedSourceBlockNum,
                                (Number(annotation.pdfX) || 0).toFixed(2),
                                (Number(annotation.pdfY) || 0).toFixed(2),
                                (Number(annotation.pdfWidth) || 0).toFixed(2),
                                (Number(annotation.pdfHeight) || 0).toFixed(2),
                                String(annotation.text || '').replace(/\s+/g, ' ').trim(),
                            ].join('|');
                            if (seenKeys.has(dedupeKey)) {
                                return;
                            }
                            seenKeys.add(dedupeKey);
                            promotedAnnotations.push(annotation);
                        });
                    });
                });

                existingDirtyPromotedByKey.forEach((annotation, key) => {
                    if (!promotedAnnotations.includes(annotation) && !deletedPromotedSourceKeys.has(String(key))) {
                        promotedAnnotations.push(annotation);
                    }
                });

                const mergedPromotedAnnotations = mergeAdjacentPromotedContinuationAnnotations(promotedAnnotations);
                clearPromotedExtractionAnnotations();
                mergedPromotedAnnotations.forEach((annotation) => annotations.push(annotation));
                promotedExtractionHydrated = mergedPromotedAnnotations.length > 0;
                return mergedPromotedAnnotations.length;
            }

            function hydrateSavedPromotedAnnotations(savedAnnotations, {
                extractionPages = [],
                savedStandaloneAnnotations = [],
            } = {}) {
                const hydrated = [];
                const seenIds = new Set();
                const savedPromotedAnnotationHasMaterialEdits = (annotation) => {
                    if (!annotation?.promotedFromExtraction) {
                        return false;
                    }
                    if (annotation.promotedDirty || annotation.promotedReflowEnabled) {
                        return true;
                    }
                    return sanitizePromotedExtractionText(annotation.text || '') !== sanitizePromotedExtractionText(annotation.originalText || '');
                };
                const unregisterHydratedAnnotation = (annotation) => {
                    if (!annotation) {
                        return;
                    }
                    const index = hydrated.indexOf(annotation);
                    if (index !== -1) {
                        hydrated.splice(index, 1);
                    }
                    const annotationId = String(annotation.id || '');
                    if (annotationId) {
                        seenIds.delete(annotationId);
                    }
                    const sourceKey = String(annotation.promotedSourceKey || '');
                    if (sourceKey) {
                        promotedBySourceKey.delete(sourceKey);
                    }
                };

                (Array.isArray(savedAnnotations) ? savedAnnotations : []).forEach((annotationData) => {
                    const annotation = buildTextAnnotationFromSavedState(annotationData);
                    if (!annotation || !annotation.promotedFromExtraction) {
                        return;
                    }
                    const annotationId = String(annotation.id || '');
                    if (annotationId && seenIds.has(annotationId)) {
                        return;
                    }
                    if (annotationId) {
                        seenIds.add(annotationId);
                    }
                    hydrated.push(annotation);
                });

                const promotedBySourceKey = new Map(
                    hydrated
                        .filter((annotation) => annotation?.promotedSourceKey)
                        .map((annotation) => [String(annotation.promotedSourceKey), annotation])
                );
                const standaloneTextAnnotationsForSuppression = collectStandaloneTextAnnotationsForPromotedSuppression(savedStandaloneAnnotations);
                const overlapsSavedStandaloneAnnotation = (annotation) => {
                    if (!annotation) {
                        return false;
                    }
                    const annotationRect = getSavedAnnotationRect(annotation);
                    if (!annotationRect) {
                        return false;
                    }

                    return standaloneTextAnnotationsForSuppression.some((savedAnnotation) => {
                        if ((Number(savedAnnotation.pageIndex) || 0) !== (Number(annotation.pageIndex) || 0)) {
                            return false;
                        }
                        const savedRect = getSavedAnnotationRect(savedAnnotation);
                        if (!savedRect) {
                            return false;
                        }

                        return annotationRect.right > savedRect.left
                            && annotationRect.left < savedRect.right
                            && annotationRect.top > savedRect.bottom
                            && annotationRect.bottom < savedRect.top;
                    });
                };
                const mergeExtractedSourceMetaIntoAnnotation = (annotation, builtAnnotation) => {
                    if (!annotation?.promotedFromExtraction || !builtAnnotation) {
                        return;
                    }
                    const extractedSourceMeta = getPromotedAnnotationSourceMeta(builtAnnotation);
                    if (!extractedSourceMeta) {
                        return;
                    }
                    const savedSourceMeta = getPromotedAnnotationSourceMeta(annotation);
                    setPromotedAnnotationSourceMeta(annotation, {
                        ...(savedSourceMeta || {}),
                        ...extractedSourceMeta,
                        sourceTextLines: Array.isArray(extractedSourceMeta?.sourceTextLines) && extractedSourceMeta.sourceTextLines.length
                            ? extractedSourceMeta.sourceTextLines
                            : (savedSourceMeta?.sourceTextLines || []),
                        sourceLineBBoxes: Array.isArray(extractedSourceMeta?.sourceLineBBoxes) && extractedSourceMeta.sourceLineBBoxes.length
                            ? extractedSourceMeta.sourceLineBBoxes
                            : (savedSourceMeta?.sourceLineBBoxes || []),
                        sourceSpans: Array.isArray(extractedSourceMeta?.sourceSpans) && extractedSourceMeta.sourceSpans.length
                            ? extractedSourceMeta.sourceSpans
                            : (savedSourceMeta?.sourceSpans || []),
                        sourceBlockWidth: Number(extractedSourceMeta?.sourceBlockWidth) > 0
                            ? Number(extractedSourceMeta.sourceBlockWidth)
                            : Number(savedSourceMeta?.sourceBlockWidth) || 0,
                        sourceBlockHeight: Number(extractedSourceMeta?.sourceBlockHeight) > 0
                            ? Number(extractedSourceMeta.sourceBlockHeight)
                            : Number(savedSourceMeta?.sourceBlockHeight) || 0,
                        sourcePageHeight: Number(extractedSourceMeta?.sourcePageHeight) > 0
                            ? Number(extractedSourceMeta.sourcePageHeight)
                            : Number(savedSourceMeta?.sourcePageHeight) || 0,
                    });
                };

                (Array.isArray(extractionPages) ? extractionPages : []).forEach((pageData) => {
                    const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];
                    const {
                        absorbedByParent,
                        absorbedChildBlockNums,
                    } = buildAbsorbedInlinePromotedBlockMap(pageBlocks);
                    const {
                        transfersByTargetBlock,
                        excludedLineIndexesBySourceBlock,
                    } = buildPromotedTrailingBulletTransferMap(pageBlocks);
                    pageBlocks.forEach((block) => {
                        const blockNum = Number(block?.block_num);
                        if (absorbedChildBlockNums.has(blockNum)) {
                            return;
                        }

                        const rootSourceKey = `block-${pageData.page_number}-${block.block_num}`;
                        if (deletedPromotedSourceKeys.has(rootSourceKey)) {
                            return;
                        }
                        const absorbedInlineBlocks = absorbedByParent.get(blockNum) || [];
                        const extractedSource = buildPromotedLineEntriesFromExtractionBlock(block, absorbedInlineBlocks, {
                            excludedLineIndexes: mergePromotedExcludedLineIndexes(
                                excludedLineIndexesBySourceBlock.get(blockNum)
                            ),
                            transferredMarkerEntries: transfersByTargetBlock.get(blockNum) || [],
                        });
                        if (!extractedSource) {
                            return;
                        }

                        const savedWholeBlockMatch = promotedBySourceKey.get(rootSourceKey) || null;
                        const shouldHonorLegacyWholeBlockMatch = savedPromotedAnnotationHasMaterialEdits(savedWholeBlockMatch);
                        if (savedWholeBlockMatch && !shouldHonorLegacyWholeBlockMatch) {
                            unregisterHydratedAnnotation(savedWholeBlockMatch);
                        }
                        const builtAnnotations = buildTextAnnotationsFromExtractionBlock(block, pageData, absorbedInlineBlocks, extractedSource);
                        const candidateAnnotations = shouldHonorLegacyWholeBlockMatch
                            ? [buildPromotedTextAnnotationFromSource(block, pageData, extractedSource)]
                            : builtAnnotations;

                        candidateAnnotations.forEach((builtAnnotation) => {
                            if (!builtAnnotation) {
                                return;
                            }
                            const sourceKey = String(builtAnnotation.promotedSourceKey || rootSourceKey);
                            if (deletedPromotedSourceKeys.has(sourceKey)) {
                                return;
                            }

                            const savedAnnotation = promotedBySourceKey.get(sourceKey);
                            if (savedAnnotation) {
                                mergeExtractedSourceMetaIntoAnnotation(savedAnnotation, builtAnnotation);
                                return;
                            }

                            if (overlapsSavedStandaloneAnnotation(builtAnnotation)) {
                                return;
                            }

                            const annotationId = String(builtAnnotation.id || '');
                            if (annotationId && seenIds.has(annotationId)) {
                                return;
                            }
                            if (annotationId) {
                                seenIds.add(annotationId);
                            }
                            registerAnnotationId(builtAnnotation);
                            hydrated.push(builtAnnotation);
                            if (sourceKey) {
                                promotedBySourceKey.set(sourceKey, builtAnnotation);
                            }
                        });
                    });
                });

                const mergedHydrated = mergeAdjacentPromotedContinuationAnnotations(hydrated);
                clearPromotedExtractionAnnotations();
                mergedHydrated.forEach((annotation) => {
                    registerAnnotationId(annotation);
                    annotations.push(annotation);
                });
                promotedExtractionHydrated = mergedHydrated.length > 0;
                return mergedHydrated.length;
            }

            function countPromotedExtractionBlocks(extractionPages) {
                return (Array.isArray(extractionPages) ? extractionPages : []).reduce((count, pageData) => (
                    count + (() => {
                        const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];
                        const {
                            absorbedByParent,
                            absorbedChildBlockNums,
                        } = buildAbsorbedInlinePromotedBlockMap(pageBlocks);
                        const {
                            transfersByTargetBlock,
                            excludedLineIndexesBySourceBlock,
                        } = buildPromotedTrailingBulletTransferMap(pageBlocks);
                        return pageBlocks.reduce((pageCount, block) => {
                            const blockNum = Number(block?.block_num);
                            if (absorbedChildBlockNums.has(blockNum)) {
                                return pageCount;
                            }
                            const absorbedInlineBlocks = absorbedByParent.get(blockNum) || [];
                            const extractedSource = buildPromotedLineEntriesFromExtractionBlock(block, absorbedInlineBlocks, {
                                excludedLineIndexes: mergePromotedExcludedLineIndexes(
                                    excludedLineIndexesBySourceBlock.get(blockNum)
                                ),
                                transferredMarkerEntries: transfersByTargetBlock.get(blockNum) || [],
                            });
                            return pageCount + buildTextAnnotationsFromExtractionBlock(block, pageData, absorbedInlineBlocks, extractedSource).length;
                        }, 0);
                    })()
                ), 0);
            }

            function shouldPreferSavedPromotedSnapshot(savedPromotedAnnotations, extractionPages) {
                const savedCount = Array.isArray(savedPromotedAnnotations) ? savedPromotedAnnotations.length : 0;
                // Saved sessions are authoritative for promoted text. If a promoted
                // snapshot exists for the active session, reload it directly instead
                // of rebuilding from extraction and reconciling the two states.
                return savedCount > 0;
            }

            async function bootstrapPromotedTextAnnotations({ force = false } = {}) {
                if (!promotedTextAnnotationsEnabled || isImageDocument) {
                    return 0;
                }
                if (loadedSavedPdfMode) {
                    await prepareEditablePdfSource({ forceRefresh: true });
                    const {
                        standaloneSavedAnnotations,
                        promotedSavedAnnotations,
                        otherSavedAnnotations,
                    } = await loadSavedTextAnnotationsFromDatabase();
                    const extractionPages = await ensureOverlayExtractionDataLoaded();
                    const extractionBlocksAvailable = countPromotedExtractionBlocks(extractionPages) > 0;
                    const hasSavedPromotedAnnotations = Array.isArray(promotedSavedAnnotations) && promotedSavedAnnotations.length > 0;
                    basePdfUrl = shouldUseOriginalBaseForSavedAnnotationLayer(
                        standaloneSavedAnnotations,
                        promotedSavedAnnotations,
                        otherSavedAnnotations,
                        extractionPages
                    ) ? originalPdfUrl : cleanPdfUrl;
                    pdfVersion = Date.now();
                    const standaloneSavedAnnotationCount = hydrateSavedTextAnnotations(standaloneSavedAnnotations);
                    const promotedAnnotationCount = hasSavedPromotedAnnotations
                        ? hydrateSavedPromotedAnnotations(promotedSavedAnnotations, {
                            extractionPages,
                            savedStandaloneAnnotations: standaloneSavedAnnotations,
                        })
                        : (extractionBlocksAvailable
                            ? hydratePromotedAnnotationsFromExtraction(extractionPages, {
                                savedStandaloneAnnotations: standaloneSavedAnnotations,
                            })
                            : 0);
                    const otherSavedAnnotationCount = hydrateSavedNonTextAnnotations(otherSavedAnnotations, extractionPages);
                    const autoDetectedCheckboxCount = buildAutoDetectedDrawnCheckboxAnnotations(extractionPages);

                    return standaloneSavedAnnotationCount + promotedAnnotationCount + otherSavedAnnotationCount + autoDetectedCheckboxCount;
                }
                if (!force && promotedExtractionHydrated) {
                    return annotations.filter((annotation) => annotation?.promotedFromExtraction).length;
                }
                if (!force && annotations.some((annotation) => !annotation?.promotedFromExtraction && !annotation?.savedTextOverlay)) {
                    return 0;
                }
                if (promotedExtractionBootstrapPromise && !force) {
                    return promotedExtractionBootstrapPromise;
                }

                promotedExtractionBootstrapPromise = (async () => {
                    await prepareEditablePdfSource({ forceRefresh: true });

                    const extractionResponse = await fetch(`${fitzExtractionDataUrl}?v=${Date.now()}`, {
                        credentials: 'same-origin',
                        headers: { Accept: 'application/json' },
                    });
                    const extractionData = await extractionResponse.json().catch(() => ({}));
                    if (!extractionResponse.ok || !extractionData?.success || !Array.isArray(extractionData.extraction_data)) {
                        throw new Error(extractionData?.message || `Failed to load extracted text data (${extractionResponse.status})`);
                    }

                    overlayExtractionData = resolveOverlayExtractionPages(extractionData);
                    if (extractionData.embedded_fonts && typeof extractionData.embedded_fonts === 'object') {
                        overlayEmbeddedFonts = extractionData.embedded_fonts;
                        loadEmbeddedFontFaces(overlayEmbeddedFonts);
                    }
                    preloadExtractionFontFamilies(overlayExtractionData);
                    populateFontDropdown();

                    const {
                        standaloneSavedAnnotations,
                        promotedSavedAnnotations,
                        otherSavedAnnotations,
                    } = await loadSavedTextAnnotationsFromDatabase();
                    basePdfUrl = shouldUseOriginalBaseForSavedAnnotationLayer(
                        standaloneSavedAnnotations,
                        promotedSavedAnnotations,
                        otherSavedAnnotations,
                        overlayExtractionData
                    ) ? originalPdfUrl : cleanPdfUrl;
                    pdfVersion = Date.now();
                    const standaloneSavedAnnotationCount = hydrateSavedTextAnnotations(standaloneSavedAnnotations);
                    const promotedAnnotationCount = shouldPreferSavedPromotedSnapshot(promotedSavedAnnotations, overlayExtractionData)
                        ? hydrateSavedPromotedAnnotations(promotedSavedAnnotations, {
                            extractionPages: overlayExtractionData,
                            savedStandaloneAnnotations: standaloneSavedAnnotations,
                        })
                        : hydratePromotedAnnotationsFromExtraction(overlayExtractionData, {
                            savedPromotedAnnotations: promotedSavedAnnotations,
                            savedStandaloneAnnotations: standaloneSavedAnnotations,
                        });
                    const otherSavedAnnotationCount = hydrateSavedNonTextAnnotations(otherSavedAnnotations, overlayExtractionData);
                    const autoDetectedCheckboxCount = buildAutoDetectedDrawnCheckboxAnnotations(overlayExtractionData);

                    return standaloneSavedAnnotationCount + promotedAnnotationCount + otherSavedAnnotationCount + autoDetectedCheckboxCount;
                })();

                try {
                    return await promotedExtractionBootstrapPromise;
                } finally {
                    promotedExtractionBootstrapPromise = null;
                }
            }

            async function loadPdf() {
                try {
                    setStatus(isImageDocument ? 'Loading image...' : 'Loading PDF...', '');
                    loadAnnotationsFromStorage();
                    await loadAcroFormEditorStateFromDatabase({ force: loadedSavedPdfMode });
                    if (!isImageDocument && promotedTextAnnotationsEnabled) {
                        await bootstrapPromotedTextAnnotations();
                    }
                    await restoreUnhydratedStoredLocalAnnotations({
                        rehydratePromoted: !isImageDocument && promotedTextAnnotationsEnabled,
                    });
                    await rerenderPdf();
                    if (!isImageDocument && promotedTextAnnotationsEnabled) {
                        schedulePromotedAnnotationFontRefit();
                    }
                    setStatus(isImageDocument ? 'Image loaded successfully.' : 'PDF loaded successfully.', 'ok');
                } catch (err) {
                    setStatus('Failed to load: ' + err.message, 'err');
                }
            }

            async function loadOriginalPdfBytes() {
                if (originalPdfBytes) {
                    return;
                }
                const response = await fetch(pdfUrlWithVersion());
                originalPdfBytes = await response.arrayBuffer();
            }

            function setStatus(message, type) {
                status.textContent = message;
                status.className = 'status' + (type ? ' ' + type : '');
            }

            const setSaveSpinner = (visible, message) => {
                if (!saveSpinner) {
                    return;
                }
                if (saveSpinnerText && message) {
                    saveSpinnerText.textContent = message;
                }
                saveSpinner.classList.toggle('active', Boolean(visible));
                saveSpinner.setAttribute('aria-hidden', visible ? 'false' : 'true');
            };

            const reloadEditorAfterSave = (message = 'Saved! Reloading...') => {
                setSaveSpinner(true, message);
                setStatus(message, 'ok');
                if (viewer) {
                    viewer.style.visibility = 'hidden';
                }
                window.setTimeout(() => {
                    window.location.reload();
                }, 500);
            };

            let selectedAnnotationMenuPlacementFrame = null;

            function getStickyUiBottomEdge() {
                let safeTop = 0;
                [
                    document.getElementById('pdf-mode-bar'),
                    document.getElementById('selection-toolbar'),
                    document.getElementById('edit-text-banner'),
                ].forEach((element) => {
                    if (!element) {
                        return;
                    }
                    const rect = element.getBoundingClientRect();
                    if (rect.height <= 0 || rect.bottom <= 0) {
                        return;
                    }
                    safeTop = Math.max(safeTop, rect.bottom);
                });
                return Math.max(0, safeTop);
            }

            function updateSelectedAnnotationMenuPlacement() {
                if (!selectedAnnotation?.element) {
                    return;
                }

                const label = selectedAnnotation.element;
                const menu = label.querySelector('.annotation-tbc-menu, .shape-action-bar');
                if (!menu) {
                    return;
                }

                label.classList.remove('annotation-menu-below');
                if (label.classList.contains('line-annotation')) {
                    return;
                }

                const labelRect = label.getBoundingClientRect();
                const menuRect = menu.getBoundingClientRect();
                const activeConfigPanel = menu.querySelector('.field-select-config-popover.active');
                const configPanelHeight = activeConfigPanel
                    ? Math.max(activeConfigPanel.getBoundingClientRect().height || 0, activeConfigPanel.offsetHeight || 0) + 8
                    : 0;
                const menuHeight = Math.max(menuRect.height || 0, menu.offsetHeight || 0) + configPanelHeight;
                if (menuHeight <= 0) {
                    return;
                }

                const safeTop = getStickyUiBottomEdge();
                const viewportBottom = window.innerHeight || document.documentElement.clientHeight || 0;
                const menuGap = 18;
                const requiredSpace = menuHeight + menuGap;
                const spaceAbove = Math.max(0, labelRect.top - safeTop);
                const spaceBelow = Math.max(0, viewportBottom - labelRect.bottom);
                const shouldFlipBelow = spaceAbove < requiredSpace && (spaceBelow >= requiredSpace || spaceBelow > spaceAbove);

                label.classList.toggle('annotation-menu-below', shouldFlipBelow);
            }

            function queueSelectedAnnotationMenuPlacement() {
                if (selectedAnnotationMenuPlacementFrame !== null) {
                    return;
                }
                selectedAnnotationMenuPlacementFrame = requestAnimationFrame(() => {
                    selectedAnnotationMenuPlacementFrame = null;
                    updateSelectedAnnotationMenuPlacement();
                });
            }

            function annotationInteractionsRequireEditTextMode(annotation) {
                const normalizedType = String(annotation?.type || 'text').toLowerCase();
                return normalizedType === 'text'
                    || normalizedType === 'shape'
                    || normalizedType === 'signature'
                    || normalizedType === 'table';
            }

            function ensureAnnotationInteractionsEnabled(annotation, {
                notify = true,
                message = 'Turn on Edit Text to select or modify existing text, shapes, and signatures.',
            } = {}) {
                if (!annotationInteractionsRequireEditTextMode(annotation) || toolMode === 'edit-text') {
                    return true;
                }
                if (notify && message) {
                    setStatus(message, 'warn');
                }
                return false;
            }

            function clearLockedAnnotationSelectionIfNeeded() {
                if (!selectedAnnotation || ensureAnnotationInteractionsEnabled(selectedAnnotation, { notify: false })) {
                    return false;
                }
                setSelection(null, { bypassInteractionGuard: true });
                return true;
            }

            function setSelection(annotation, options = {}) {
                const bypassInteractionGuard = options.bypassInteractionGuard === true;
                if (annotation && !bypassInteractionGuard && !ensureAnnotationInteractionsEnabled(annotation, { notify: false })) {
                    return false;
                }
                if (selectedAnnotation && selectedAnnotation.element) {
                    selectedAnnotation.closeFieldConfigPanel?.();
                    if (selectedAnnotation.type === 'field' && selectedAnnotation.element.classList.contains('field-editing')) {
                        const previousFieldInput = selectedAnnotation.fieldInput || selectedAnnotation.element.querySelector('.field-annotation-input');
                        if (previousFieldInput) {
                            const previousFieldKind = normalizeFieldKind(selectedAnnotation.fieldKind);
                            const nextFieldValue = previousFieldKind === 'date'
                                ? formatDateFieldValue(previousFieldInput.value || '', { finalize: true })
                                : String(previousFieldInput.value || '');
                            previousFieldInput.value = nextFieldValue;
                            selectedAnnotation.fieldValue = nextFieldValue;
                            previousFieldInput.readOnly = true;
                            previousFieldInput.tabIndex = -1;
                            selectedAnnotation.element.classList.remove('field-editing');
                            persistAnnotations();
                            saveAnnotationToDatabase(selectedAnnotation);
                        }
                    }
                    selectedAnnotation.element.classList.remove('selected');
                    selectedAnnotation.element.classList.remove('annotation-menu-below');
                    // Hide resize handles and action bar from previously selected shape-like annotation
                    const prevHandles = selectedAnnotation.element.querySelectorAll('.shape-resize-handle');
                    prevHandles.forEach(h => h.style.display = 'none');
                    const prevRotateHandle = selectedAnnotation.element.querySelector('.rotate-handle');
                    if (prevRotateHandle) {
                        prevRotateHandle.style.display = 'none';
                    }
                    const prevActionBar = selectedAnnotation.element.querySelector('.shape-action-bar');
                    if (prevActionBar) {
                        prevActionBar.style.display = 'none';
                    }
                }
                selectedAnnotation = annotation;
                if (annotation) {
                    clearOverlaySelection();
                }
                if (selectedAnnotation && selectedAnnotation.element) {
                    selectedAnnotation.element.classList.add('selected');
                    // Show resize handles and action bar for selected shape-like annotation
                    if (hasShapeStyleAnnotationControls(selectedAnnotation)) {
                        const handles = selectedAnnotation.element.querySelectorAll('.shape-resize-handle');
                        handles.forEach(h => h.style.display = 'block');
                        const rotateHandle = selectedAnnotation.element.querySelector('.rotate-handle');
                        if (rotateHandle) {
                            rotateHandle.style.display = 'flex';
                        }
                        const actionBar = selectedAnnotation.element.querySelector('.shape-action-bar');
                        if (actionBar) {
                            actionBar.style.display = 'flex';
                        }
                    }
                }
                updateSelectionBar();
                updateEditTextBanner();
                queueSelectedAnnotationMenuPlacement();
                return true;
            }

            function suppressNextOverlayBackgroundClick(overlay) {
                if (!overlay) {
                    return;
                }
                overlay.dataset.suppressNextBackgroundClick = '1';
            }

            function consumeSuppressedOverlayBackgroundClick(overlay, event) {
                if (!overlay || overlay.dataset.suppressNextBackgroundClick !== '1') {
                    return false;
                }
                delete overlay.dataset.suppressNextBackgroundClick;
                if (event) {
                    event.preventDefault();
                    event.stopPropagation();
                }
                return true;
            }

            function updateTextLayerVisibility() {
                const inEditTextMode = toolMode === 'edit-text';
                // When the original (non-clean) PDF is rendered alongside promoted-extraction
                // annotation overlays, the text layer would duplicate the canvas-baked text and
                // cause a ghost overlay effect. Suppress it in that case.
                const suppressTextLayer = inEditTextMode
                    && basePdfUrl !== cleanPdfUrl
                    && annotations.some((a) => a.promotedFromExtraction);
                // Keep extracted text hidden in Add Text mode; only show it in Edit Text mode.
                viewer.classList.toggle('text-editing', inEditTextMode && !suppressTextLayer);
                viewer.classList.toggle('edit-text-mode', inEditTextMode);
            }

            function populateSelectionBarFromOverlayFields(fields) {
                const liveFields = Array.isArray(fields)
                    ? fields.filter((field) => field && document.body.contains(field))
                    : [];
                if (!liveFields.length) {
                    return;
                }

                const referenceField = liveFields.includes(selectedOverlayField)
                    ? selectedOverlayField
                    : liveFields[liveFields.length - 1];
                const textEl = getOverlayTextElement(referenceField);
                if (!textEl) {
                    return;
                }

                const styles = window.getComputedStyle(textEl);
                if (selectedFont) selectedFont.disabled = false;
                if (selectedWeight) selectedWeight.disabled = false;
                if (selectedSize) selectedSize.disabled = false;
                if (selectedBold) selectedBold.disabled = false;
                if (selectedItalic) selectedItalic.disabled = false;
                if (selectedUnderline) selectedUnderline.disabled = false;
                if (selectedColor) selectedColor.disabled = false;
                if (selectedBg) selectedBg.disabled = false;
                if (selectedAlign) selectedAlign.disabled = false;
                if (selectedOpacity) selectedOpacity.disabled = false;
                if (selectedDelete) selectedDelete.disabled = liveFields.length > 1;

                if (selectedFont) {
                    selectedFont.value = mapFontFamilyToKey(styles.fontFamily);
                }
                if (selectedWeight) {
                    const weightValue = parseInt(styles.fontWeight, 10);
                    const normalizedWeight = Number.isFinite(weightValue) ? String(Math.round(weightValue / 100) * 100) : '400';
                    selectedWeight.value = ['100','200','300','400','500','600','700','800','900'].includes(normalizedWeight) ? normalizedWeight : '400';
                }
                if (selectedSize) selectedSize.value = Math.round(parseFloat(styles.fontSize) || 16);
                if (selectedColor) selectedColor.value = colorToHex(styles.color) || '#000000';
                if (selectedBg) {
                    const bgColor = colorToHex(styles.backgroundColor);
                    selectedBg.value = bgColor && bgColor !== 'transparent' ? bgColor : '#ffffff';
                }
                if (selectedAlign) selectedAlign.value = styles.textAlign || 'left';
                if (selectedOpacity) {
                    const opacityValue = String(parseFloat(styles.opacity || '1'));
                    if ([...selectedOpacity.options].some((option) => option.value === opacityValue)) {
                        selectedOpacity.value = opacityValue;
                    } else {
                        selectedOpacity.value = '1';
                    }
                }
                if (selectedBold) {
                    setToggleButtonPressedState(selectedBold, liveFields.every((field) => {
                        const fieldStyles = window.getComputedStyle(getOverlayTextElement(field));
                        const fieldWeight = parseInt(fieldStyles.fontWeight, 10);
                        return Number.isFinite(fieldWeight) ? fieldWeight >= 600 : fieldStyles.fontWeight === 'bold';
                    }));
                }
                if (selectedItalic) {
                    setToggleButtonPressedState(selectedItalic, liveFields.every((field) => {
                        const fieldStyles = window.getComputedStyle(getOverlayTextElement(field));
                        return fieldStyles.fontStyle === 'italic' || fieldStyles.fontStyle === 'oblique';
                    }));
                }
                if (selectedUnderline) {
                    setToggleButtonPressedState(selectedUnderline, liveFields.every((field) => {
                        const fieldStyles = window.getComputedStyle(getOverlayTextElement(field));
                        return String(fieldStyles.textDecorationLine || '').includes('underline');
                    }));
                }
            }

            function updateSelectionBar() {
                console.log('updateSelectionBar called - selectedAnnotation:', selectedAnnotation, 'selectedOverlayField:', selectedOverlayField);
                const liveOverlayFields = getSelectedOverlayFields();
                const multiOverlaySelection = !selectedAnnotation && liveOverlayFields.length > 1;
                const samePageOverlaySelection = multiOverlaySelection
                    && new Set(liveOverlayFields.map((field) => String(field?.dataset?.pageNumber || ''))).size === 1;
                if (!selectedAnnotation && !selectedOverlayField) {
                    console.log('No selection, disabling toolbar');
                    if (selectionLabel) {
                        selectionLabel.textContent = overlayEditorActive
                            ? (boundingBoxEditMode ? 'Click a text annotation to edit' : 'Click a text block to edit')
                            : 'No text selected';
                    }
                    if (selectionControls) selectionControls.classList.add('disabled');
                    if (selectedFont) {
                        selectedFont.value = 'Helvetica';
                        selectedFont.disabled = true;
                    }
                    if (selectedWeight) {
                        selectedWeight.value = '400';
                        selectedWeight.disabled = true;
                    }
                    if (selectedSize) {
                        selectedSize.value = 16;
                        selectedSize.disabled = true;
                    }
                    if (selectedBold) selectedBold.disabled = true;
                    if (selectedItalic) selectedItalic.disabled = true;
                    if (selectedUnderline) selectedUnderline.disabled = true;
                    if (selectedColor) selectedColor.disabled = true;
                    if (selectedBg) selectedBg.disabled = true;
                    if (selectedAlign) selectedAlign.disabled = true;
                    if (selectedOpacity) selectedOpacity.disabled = true;
                    if (selectedMerge) selectedMerge.disabled = true;
                    if (selectedDelete) selectedDelete.disabled = true;
                    return;
                }

                if (selectionLabel) selectionLabel.textContent = multiOverlaySelection
                    ? `${liveOverlayFields.length} blocks selected`
                    : 'Selected text';
                if (selectionControls) selectionControls.classList.remove('disabled');

                if (multiOverlaySelection) {
                    populateSelectionBarFromOverlayFields(liveOverlayFields);
                    if (selectedMerge) selectedMerge.disabled = !samePageOverlaySelection;
                    return;
                }

                if (selectedMerge) selectedMerge.disabled = true;

                if (selectedAnnotation) {
                    const isText = selectedAnnotation.type === 'text' || !selectedAnnotation.type;
                    if (selectedFont) selectedFont.disabled = !isText;
                    if (selectedWeight) selectedWeight.disabled = !isText;
                    if (selectedSize) selectedSize.disabled = !isText;
                    if (selectedBold) selectedBold.disabled = !isText;
                    if (selectedItalic) selectedItalic.disabled = !isText;
                    if (selectedUnderline) selectedUnderline.disabled = !isText;
                    if (selectedColor) selectedColor.disabled = !isText;
                    if (selectedBg) selectedBg.disabled = !isText;
                    if (selectedAlign) selectedAlign.disabled = !isText;
                    if (selectedValign) selectedValign.disabled = !isText;
                    if (selectedOpacity) selectedOpacity.disabled = !isText;
                    if (selectedDelete) selectedDelete.disabled = false;
                    if (isText) {
                        if (selectedFont) {
                            selectedFont.value = resolveToolbarFontSelection(
                                selectedAnnotation.fontSourceName || selectedAnnotation.fontFamily || 'Helvetica'
                            );
                        }
                        if (selectedWeight) {
                            const annoWeight = String(selectedAnnotation.fontWeight);
                            selectedWeight.value = ['100','200','300','400','500','600','700','800','900'].includes(annoWeight) ? annoWeight : (annoWeight === 'bold' ? '700' : '400');
                        }
                        if (selectedSize) selectedSize.value = getRequestedAnnotationFontSize(selectedAnnotation);
                        if (selectedColor) selectedColor.value = selectedAnnotation.textColor || '#000000';
                        if (selectedBg) {
                            const background = selectedAnnotation.backgroundColor || 'transparent';
                            selectedBg.value = background === 'transparent' ? '#ffffff' : background;
                        }
                        if (selectedAlign) selectedAlign.value = selectedAnnotation.textAlign || 'left';
                        if (selectedValign) selectedValign.value = selectedAnnotation.verticalAlign || 'top';
                        if (selectedOpacity) {
                            const opacityValue = String(selectedAnnotation.opacity ?? 1);
                            if ([...selectedOpacity.options].some((option) => option.value === opacityValue)) {
                                selectedOpacity.value = opacityValue;
                            } else {
                                selectedOpacity.value = '1';
                            }
                        }
                        setToggleButtonPressedState(selectedBold, selectedAnnotation.fontWeight === '700' || selectedAnnotation.fontWeight === 'bold');
                        setToggleButtonPressedState(selectedItalic, selectedAnnotation.fontStyle === 'italic');
                        setToggleButtonPressedState(selectedUnderline, Boolean(selectedAnnotation.underline));
                    } else {
                        if (selectionLabel) selectionLabel.textContent = 'Selected item';
                        if (selectedFont) selectedFont.value = 'Helvetica';
                        if (selectedSize) selectedSize.value = 16;
                        setToggleButtonPressedState(selectedBold, false);
                        setToggleButtonPressedState(selectedItalic, false);
                        setToggleButtonPressedState(selectedUnderline, false);
                    }
                    return;
                }

                if (selectedOverlayField) {
                    console.log('Updating toolbar for overlay field');
                    populateSelectionBarFromOverlayFields([selectedOverlayField]);
                    console.log('Toolbar controls enabled for overlay field');
                }
            }

            function getSelectedOverlayFields() {
                const liveFields = Array.from(selectedOverlayFields).filter((field) => field && document.body.contains(field));
                if (liveFields.length !== selectedOverlayFields.size) {
                    selectedOverlayFields = new Set(liveFields);
                }
                if (selectedOverlayField && !selectedOverlayFields.has(selectedOverlayField)) {
                    selectedOverlayField = liveFields[0] || null;
                }
                return liveFields;
            }

            function getOverlayStyleTargets() {
                const liveFields = getSelectedOverlayFields();
                if (liveFields.length) {
                    return liveFields;
                }
                return selectedOverlayField ? [selectedOverlayField] : [];
            }

            let restoreOverlayFieldSourceGeometry = () => false;

            function syncBoundingBoxFieldMaskState(field) {
                if (!boundingBoxEditMode || !field || field.dataset.layoutMode !== 'bounding_box_edit') {
                    return;
                }
                const editKey = String(field.dataset.wordIndex || '');
                const textSpan = field.querySelector('[contenteditable]');
                const resolvedMaskColor = colorToHex(
                    field.dataset.backgroundColor
                    || textSpan?.style?.backgroundColor
                    || 'transparent'
                );
                field.style.setProperty(
                    '--overlay-field-mask-color',
                    resolvedMaskColor && resolvedMaskColor !== 'transparent' ? resolvedMaskColor : '#ffffff'
                );
                const shouldMaskSourceText = field.classList.contains('editing')
                    || field.dataset.hasPersistedEdit === '1'
                    || field.dataset.persisting === '1'
                    || (!!editKey && overlayEditedFields.has(editKey));
                if (shouldMaskSourceText) {
                    field.dataset.maskSourceText = '1';
                } else {
                    delete field.dataset.maskSourceText;
                }
            }

            function deactivateOverlayField(field, options = {}) {
                if (!field) return;
                const keepSelected = options.keepSelected === true;
                field.classList.remove('active', 'editing', 'editable');
                if (!keepSelected) {
                    field.classList.remove('selected');
                }
                const ce = field.querySelector('[contenteditable]');
                if (ce) {
                    ce.classList.remove('editable');
                    ce.contentEditable = false;
                    const fieldKey = String(field.dataset.wordIndex || '');
                    const preserveBoundingBoxEditContent = boundingBoxEditMode
                        && field.dataset.layoutMode === 'bounding_box_edit'
                        && field.dataset.hasPersistedEdit === '1';
                    if (field.dataset.exactGeometry === '1' && !overlayEditedFields.has(fieldKey) && !preserveBoundingBoxEditContent) {
                        restoreOverlayFieldSourceGeometry(field, ce);
                    }
                }
                if (field.dataset.originalZIndex) {
                    field.style.zIndex = field.dataset.originalZIndex;
                }
                syncBoundingBoxFieldMaskState(field);
            }

            function activateOverlayField(field) {
                if (!field) return;
                field.classList.add('selected', 'active');
                if (!field.dataset.originalZIndex) {
                    field.dataset.originalZIndex = field.style.zIndex || '1';
                }
                field.style.zIndex = '9999';
                syncBoundingBoxFieldMaskState(field);
            }

            function clearOverlaySelection() {
                getSelectedOverlayFields().forEach((field) => deactivateOverlayField(field));
                selectedOverlayFields = new Set();
                selectedOverlayField = null;
                overlaySelectionRange = null;
            }

            function setOverlaySelection(field, options = {}) {
                if (!field) {
                    return;
                }
                const additive = options.additive === true;
                console.log('setOverlaySelection called with field:', field);
                if (selectedAnnotation) {
                    setSelection(null);
                }

                if (!additive && selectedOverlayField === field && selectedOverlayFields.size === 1) {
                    activateOverlayField(field);
                    updateSelectionBar();
                    return;
                }

                const liveFields = getSelectedOverlayFields();
                const currentPageNumber = String(field.dataset.pageNumber || '');
                const selectionSpansMultiplePages = liveFields.length > 0
                    && liveFields.some((candidate) => String(candidate?.dataset?.pageNumber || '') !== currentPageNumber);

                if (!additive || selectionSpansMultiplePages) {
                    clearOverlaySelection();
                }

                const alreadySelected = selectedOverlayFields.has(field);
                if (additive && alreadySelected && selectedOverlayFields.size > 1) {
                    deactivateOverlayField(field);
                    selectedOverlayFields.delete(field);
                    const remaining = getSelectedOverlayFields();
                    selectedOverlayField = remaining[remaining.length - 1] || null;
                    if (selectedOverlayField) {
                        activateOverlayField(selectedOverlayField);
                        remaining.forEach((candidate) => {
                            if (candidate !== selectedOverlayField) {
                                deactivateOverlayField(candidate, { keepSelected: true });
                                candidate.classList.add('selected');
                            }
                        });
                    }
                    updateSelectionBar();
                    return;
                }

                getSelectedOverlayFields().forEach((candidate) => {
                    if (candidate !== field) {
                        deactivateOverlayField(candidate, { keepSelected: additive });
                        if (additive) {
                            candidate.classList.add('selected');
                        }
                    }
                });

                selectedOverlayFields.add(field);
                selectedOverlayField = field;
                activateOverlayField(selectedOverlayField);
                console.log('Calling updateSelectionBar from setOverlaySelection');
                updateSelectionBar();
            }

            function getOverlayCurrentText(field) {
                const textEl = getOverlayTextElement(field);
                if (!textEl) return '';
                const hasPositionedSpans = Array.from(textEl.querySelectorAll('span')).some((span) => span.style.position === 'absolute');
                if (hasPositionedSpans) {
                    return String(field.dataset.stableFlowText || field.dataset.originalText || '').trim();
                }
                return String(getOverlayExplicitText(textEl) || field.dataset.originalText || '').trim();
            }

            function getOverlayFieldSourcePageData(pageNumber) {
                const extractionPages = Array.isArray(overlayExtractionData) ? overlayExtractionData : [];
                return extractionPages.find((page) => Number(page?.page_number) === Number(pageNumber)) || null;
            }

            function getNextSyntheticOverlayBlockNum(pageData) {
                const pageBlocks = Array.isArray(pageData?.blocks) ? pageData.blocks : [];
                const maxBlockNum = pageBlocks.reduce((maxValue, block) => {
                    const blockNum = Number(block?.block_num);
                    return Number.isFinite(blockNum) ? Math.max(maxValue, blockNum) : maxValue;
                }, -1);
                return maxBlockNum + 1;
            }

            function mergeSelectedOverlayFieldsText(records) {
                const sorted = [...records].sort((a, b) =>
                    (a.bbox[1] - b.bbox[1])
                    || (a.bbox[0] - b.bbox[0])
                );
                const rows = [];
                const verticalOverlapRatio = (aTop, aBottom, bTop, bBottom) => {
                    const inter = Math.max(0, Math.min(aBottom, bBottom) - Math.max(aTop, bTop));
                    const minHeight = Math.max(1, Math.min(aBottom - aTop, bBottom - bTop));
                    return inter / minHeight;
                };

                sorted.forEach((record) => {
                    const top = Number(record?.bbox?.[1]) || 0;
                    const bottom = Number(record?.bbox?.[3]) || top;
                    let row = rows.find((candidate) => verticalOverlapRatio(candidate.top, candidate.bottom, top, bottom) >= 0.35);
                    if (!row) {
                        row = { top, bottom, records: [] };
                        rows.push(row);
                    } else {
                        row.top = Math.min(row.top, top);
                        row.bottom = Math.max(row.bottom, bottom);
                    }
                    row.records.push(record);
                });

                return rows
                    .sort((a, b) => a.top - b.top)
                    .map((row) => row.records
                        .sort((a, b) => (a.bbox[0] - b.bbox[0]))
                        .map((record) => String(record.text || '')
                            .split('\n')
                            .map((line) => line.trim())
                            .filter(Boolean)
                            .join(' ')
                            .trim()
                        )
                        .filter(Boolean)
                        .join(' ')
                        .trim()
                    )
                    .filter(Boolean)
                    .join('\n');
            }

            async function mergeSelectedOverlayFields() {
                const fields = getSelectedOverlayFields();
                if (fields.length < 2) {
                    return;
                }

                const pageNumbers = [...new Set(fields.map((field) => Number(field?.dataset?.pageNumber) || 0))];
                if (pageNumbers.length !== 1 || !pageNumbers[0]) {
                    setStatus('Merge only works for overlay blocks on the same page.', 'warn');
                    return;
                }

                const pageNumber = pageNumbers[0];
                const pageData = getOverlayFieldSourcePageData(pageNumber);
                if (!pageData) {
                    setStatus('Could not find overlay source data for the selected page.', 'err');
                    return;
                }

                pushUndoState();

                const primaryField = selectedOverlayField && fields.includes(selectedOverlayField)
                    ? selectedOverlayField
                    : fields[fields.length - 1];
                const builtRecords = fields
                    .map((field) => ({ field, built: buildOverlayEditRecordFromField(field) }))
                    .filter((entry) => entry.built && entry.built.value && Array.isArray(entry.built.value.bbox));

                if (builtRecords.length < 2) {
                    setStatus('Merge requires at least two valid overlay blocks.', 'warn');
                    return;
                }

                const mergedText = mergeSelectedOverlayFieldsText(
                    builtRecords.map(({ field, built }) => ({
                        bbox: built.value.bbox,
                        text: getOverlayCurrentText(field),
                    }))
                ).trim();

                if (!mergedText) {
                    setStatus('Merge failed because the selected blocks do not contain text.', 'warn');
                    return;
                }

                const mergedBbox = builtRecords.reduce((acc, { built }) => {
                    const bbox = built.value.bbox;
                    return [
                        Math.min(acc[0], Number(bbox[0]) || 0),
                        Math.min(acc[1], Number(bbox[1]) || 0),
                        Math.max(acc[2], Number(bbox[2]) || 0),
                        Math.max(acc[3], Number(bbox[3]) || 0),
                    ];
                }, [Infinity, Infinity, -Infinity, -Infinity]);

                const mergedBlockNum = getNextSyntheticOverlayBlockNum(pageData);
                const mergedKey = `block-${pageNumber}-${mergedBlockNum}`;
                const primarySourceBlock = primaryField?._overlaySourceBlock || {};
                const primaryFont = primaryField.dataset.fontFamily || primaryField.dataset.font || primarySourceBlock.font || 'Helvetica';
                const primaryFontSize = parseFloat(primaryField.dataset.fontSize || primarySourceBlock.font_size || '12') || 12;
                const primaryFontWeight = primaryField.dataset.fontWeight || primarySourceBlock.font_weight || '400';
                const primaryFontStyle = primaryField.dataset.fontStyle || (primarySourceBlock.italic ? 'italic' : 'normal');
                const primaryColor = primaryField.dataset.textColor || primarySourceBlock.hex_color || '#000000';
                const mergedTextLines = mergedText.split('\n').map((line) => line.trim()).filter(Boolean);

                builtRecords.forEach(({ built }) => {
                    overlayEditedFields.set(built.key, {
                        ...built.value,
                        new_text: '',
                        rich_html: null,
                        word_styles: null,
                        line_metrics: null,
                        synthetic_textbox: false,
                    });
                });

                overlayEditedFields.set(mergedKey, {
                    page_number: pageNumber,
                    block_num: mergedBlockNum,
                    original_text: '',
                    new_text: mergedText,
                    rich_html: null,
                    word_styles: null,
                    line_metrics: null,
                    bbox: [...mergedBbox],
                    original_bbox: [...mergedBbox],
                    origin_x: mergedBbox[0],
                    origin_y: mergedBbox[3],
                    font_xref: primaryField.dataset.fontXref ? parseInt(primaryField.dataset.fontXref, 10) : null,
                    font: primaryFont,
                    font_size: primaryFontSize,
                    font_weight: String(primaryFontWeight),
                    font_style: primaryFontStyle,
                    underline: primaryField.dataset.underline === 'true',
                    line_height: parseFloat(primaryField.dataset.lineHeight || primarySourceBlock.line_height || '0') || null,
                    color: primaryColor,
                    synthetic_textbox: true,
                    force_reinsert: true,
                });

                pageData.blocks.push({
                    ...primarySourceBlock,
                    block_num: mergedBlockNum,
                    left: mergedBbox[0],
                    top: mergedBbox[1],
                    width: mergedBbox[2] - mergedBbox[0],
                    height: mergedBbox[3] - mergedBbox[1],
                    text: mergedText,
                    text_single_line: mergedTextLines.join(' '),
                    text_lines: mergedTextLines,
                    line_count: mergedTextLines.length || 1,
                    line_bboxes: [],
                    spans: [],
                    has_mixed_styles: false,
                    font: primaryFont,
                    font_size: primaryFontSize,
                    font_weight: String(primaryFontWeight),
                    italic: primaryFontStyle === 'italic',
                    bold: Number(primaryFontWeight) >= 700 || String(primaryFontWeight).toLowerCase() === 'bold',
                    hex_color: primaryColor,
                    _client_multi_merge: true,
                });

                clearOverlaySelection();
                persistOverlayEdits();
                updateOverlaySaveButton();
                await renderPdfWithOverlay(true);

                const mergedField = document.querySelector(`.overlay-field[data-word-index="${mergedKey}"]`);
                if (mergedField) {
                    setOverlaySelection(mergedField);
                } else {
                    updateSelectionBar();
                }

                setStatus(`Merged ${builtRecords.length} overlay blocks into one block.`, 'ok');
            }

            function getOverlayTextElement(field) {
                return field.querySelector('[contenteditable]') || field;
            }

            function collectSplitParagraphCharacterLines(textEl) {
                if (!textEl) {
                    return [];
                }

                const characterSpans = Array.from(
                    textEl.querySelectorAll('span._iceni_text-sel, span[data-line-num][data-xpos], span[data-lineNum][data-xpos]')
                ).filter((span) => {
                    if (!(span instanceof HTMLElement)) {
                        return false;
                    }
                    return span.style.position === 'absolute'
                        || span.dataset.lineNum !== undefined
                        || span.dataset.linenum !== undefined;
                });

                if (!characterSpans.length) {
                    return [];
                }

                const lineMap = new Map();
                characterSpans.forEach((span) => {
                    const rawLineNum = span.dataset.lineNum ?? span.dataset.linenum ?? '';
                    const parsedLineNum = Number(rawLineNum);
                    const lineKey = Number.isFinite(parsedLineNum)
                        ? `line:${parsedLineNum}`
                        : `y:${Number(span.dataset.originY ?? span.style.top ?? 0).toFixed(2)}`;

                    if (!lineMap.has(lineKey)) {
                        lineMap.set(lineKey, {
                            key: lineKey,
                            lineNum: Number.isFinite(parsedLineNum) ? parsedLineNum : null,
                            baseline: Number(span.dataset.originY ?? span.style.top ?? 0) || 0,
                            items: [],
                        });
                    }

                    const entry = lineMap.get(lineKey);
                    entry.items.push(span);
                    entry.baseline = Number.isFinite(parsedLineNum)
                        ? entry.baseline
                        : ((entry.baseline * (entry.items.length - 1)) + (Number(span.dataset.originY ?? span.style.top ?? 0) || 0)) / entry.items.length;
                });

                return Array.from(lineMap.values())
                    .sort((a, b) => {
                        if (Number.isFinite(a.lineNum) && Number.isFinite(b.lineNum)) {
                            return a.lineNum - b.lineNum;
                        }
                        return a.baseline - b.baseline;
                    })
                    .map((line) => ({
                        ...line,
                        items: line.items.slice().sort((a, b) => {
                            const leftA = Number(a.dataset.xpos ?? a.style.left ?? 0) || 0;
                            const leftB = Number(b.dataset.xpos ?? b.style.left ?? 0) || 0;
                            return leftA - leftB;
                        }),
                    }));
            }

            function clusterPositionedSplitParagraphRows(lineNodes) {
                const clusteredRows = [];

                (Array.isArray(lineNodes) ? lineNodes : [])
                    .filter((node) => node instanceof HTMLElement)
                    .slice()
                    .sort((a, b) => (
                        (parseFloat(a.style.top) || 0) - (parseFloat(b.style.top) || 0)
                        || (parseFloat(a.style.left) || 0) - (parseFloat(b.style.left) || 0)
                    ))
                    .forEach((lineNode) => {
                        const lineTop = parseFloat(lineNode.style.top) || 0;
                        const lineLeft = parseFloat(lineNode.style.left) || 0;
                        const lineWidth = parseFloat(lineNode.style.width)
                            || lineNode.getBoundingClientRect().width
                            || 0;
                        const lineHeight = Math.max(
                            1,
                            parseFloat(lineNode.style.height)
                                || parseFloat(lineNode.style.lineHeight)
                                || lineNode.getBoundingClientRect().height
                                || 0
                        );
                        const lineBottom = lineTop + lineHeight;
                        const mergeTolerance = Math.max(2, Math.min(6, lineHeight * 0.45));

                        let row = clusteredRows.find((candidate) => {
                            const rowBottom = candidate.top + candidate.height;
                            const verticalOverlap = Math.max(0, Math.min(lineBottom, rowBottom) - Math.max(lineTop, candidate.top));
                            const minHeight = Math.max(1, Math.min(lineHeight, candidate.height));
                            const overlapRatio = verticalOverlap / minHeight;
                            return overlapRatio >= 0.45 || Math.abs(candidate.top - lineTop) <= Math.max(candidate.mergeTolerance, mergeTolerance);
                        });

                        if (!row) {
                            row = {
                                top: lineTop,
                                height: lineHeight,
                                mergeTolerance,
                                nodes: [],
                            };
                            clusteredRows.push(row);
                        } else {
                            row.top = Math.min(row.top, lineTop);
                            row.height = Math.max(row.height, lineHeight);
                            row.mergeTolerance = Math.max(row.mergeTolerance, mergeTolerance);
                        }

                        row.nodes.push({
                            lineNode,
                            left: lineLeft,
                            top: lineTop,
                            width: lineWidth,
                            height: lineHeight,
                        });
                    });

                return clusteredRows
                    .sort((a, b) => a.top - b.top)
                    .map((row) => ({
                        ...row,
                        nodes: row.nodes.slice().sort((a, b) => a.left - b.left),
                    }));
            }

            function getSplitParagraphExplicitText(textEl) {
                const lines = collectSplitParagraphCharacterLines(textEl);
                if (!lines.length) {
                    return '';
                }

                return lines.map((line) => (
                    line.items
                        .map((span) => (span.textContent || '').replace(/\u00A0/g, ' '))
                        .join('')
                )).join('\n').replace(/\n+$/g, '');
            }

            function buildSplitParagraphRichTextHtml(textEl) {
                const lines = collectSplitParagraphCharacterLines(textEl);
                if (!lines.length) {
                    return '';
                }

                const serializeStyles = (span) => {
                    const styles = [];
                    const rawColor = String(span.style.color || '').trim();
                    const rawBackgroundColor = String(span.style.backgroundColor || '').trim();
                    const color = rawColor ? colorToHex(rawColor) : '';
                    const backgroundColor = rawBackgroundColor ? colorToHex(rawBackgroundColor) : '';
                    const fontSize = String(span.style.fontSize || '').trim();
                    const fontWeight = String(span.style.fontWeight || '').trim();
                    const fontStyle = String(span.style.fontStyle || '').trim();
                    const textDecoration = String(span.style.textDecoration || span.style.textDecorationLine || '').trim();
                    const fontFamily = String(span.style.fontFamily || '').trim();

                    if (color && color !== '#000000' && color !== 'transparent') styles.push(`color:${color}`);
                    if (backgroundColor && backgroundColor !== 'transparent') styles.push(`background-color:${backgroundColor}`);
                    if (fontSize) styles.push(`font-size:${fontSize}`);
                    if (fontWeight && fontWeight !== '400' && fontWeight !== 'normal') styles.push(`font-weight:${fontWeight}`);
                    if (fontStyle && fontStyle !== 'normal') styles.push(`font-style:${fontStyle}`);
                    if (textDecoration && textDecoration !== 'none') styles.push(`text-decoration:${textDecoration}`);
                    if (fontFamily) styles.push(`font-family:${fontFamily}`);

                    return styles.join(';');
                };

                const buildStyledRunHtml = (text, styleText) => {
                    const safeText = escapeAnnotationHtml(text.replace(/\u00A0/g, ' '));
                    if (!styleText) {
                        return safeText;
                    }
                    return `<span style="${escapeAnnotationHtmlAttribute(styleText)}">${safeText}</span>`;
                };

                let html = '';
                lines.forEach((line, lineIndex) => {
                    let currentStyle = null;
                    let currentText = '';

                    const flush = () => {
                        if (!currentText) {
                            return;
                        }
                        html += buildStyledRunHtml(currentText, currentStyle);
                        currentText = '';
                    };

                    line.items.forEach((span) => {
                        const text = (span.textContent || '').replace(/\u00A0/g, ' ');
                        const styleText = serializeStyles(span);
                        if (currentStyle === null) {
                            currentStyle = styleText;
                            currentText = text;
                            return;
                        }
                        if (styleText === currentStyle) {
                            currentText += text;
                            return;
                        }
                        flush();
                        currentStyle = styleText;
                        currentText = text;
                    });

                    flush();
                    currentStyle = null;

                    if (lineIndex < lines.length - 1) {
                        html += '<br>';
                    }
                });

                return html.replace(/(?:<br>)+$/g, '');
            }

            function getOverlayExplicitText(textEl) {
                if (!textEl) return '';
                if (
                    textEl.nodeType === Node.ELEMENT_NODE
                    && textEl.dataset?.annotationExactCharacterEditor === '1'
                    && textEl._nativeInput instanceof HTMLTextAreaElement
                ) {
                    return String(textEl._nativeInput.value || '')
                        .replace(/\r\n/g, '\n')
                        .replace(/\r/g, '\n');
                }
                if (
                    textEl.nodeType === Node.ELEMENT_NODE
                    && (
                        textEl.dataset?.splitParagraphFullyActive === '1'
                        || textEl.dataset?.annotationSplitParagraphFully === '1'
                        || textEl.dataset?.editLayout === 'split-paragraph-fully'
                    )
                ) {
                    const splitText = getSplitParagraphExplicitText(textEl);
                    if (splitText !== '') {
                        return splitText;
                    }
                }
                if (textEl.nodeType === Node.ELEMENT_NODE) {
                    const hasAbsoluteSpans = Array.from(textEl.querySelectorAll?.('span') || [])
                        .some((span) => span.style.position === 'absolute');
                    const hasBlockChildren = !!textEl.querySelector?.('div, p, li, br');
                    if (!hasAbsoluteSpans && hasBlockChildren && typeof textEl.innerText === 'string') {
                        return String(textEl.innerText)
                            .replace(/\r\n/g, '\n')
                            .replace(/\r/g, '\n')
                            .replace(/\n+$/g, '');
                    }
                }
                const isBlockBoundaryTag = (tag) => tag === 'DIV' || tag === 'P' || tag === 'LI';
                const readNode = (node) => {
                    if (!node) return '';
                    if (node.nodeType === Node.TEXT_NODE) {
                        return node.nodeValue || '';
                    }
                    if (node.nodeType !== Node.ELEMENT_NODE) {
                        return '';
                    }
                    const tag = node.tagName;
                    if (tag === 'BR') {
                        return '\n';
                    }
                    let out = '';
                    node.childNodes.forEach((child) => {
                        const childTag = child?.nodeType === Node.ELEMENT_NODE ? child.tagName : '';
                        if (isBlockBoundaryTag(childTag) && out && !out.endsWith('\n')) {
                            out += '\n';
                        }
                        out += readNode(child);
                    });
                    if (isBlockBoundaryTag(tag) && out && !out.endsWith('\n')) {
                        out += '\n';
                    }
                    return out;
                };
                return readNode(textEl).replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/\n+$/g, '');
            }

            function applyOverlayStyle(updateFn) {
                const targetFields = getOverlayStyleTargets();
                if (!targetFields.length) {
                    return;
                }
                targetFields.forEach((field) => {
                    const textEl = getOverlayTextElement(field);
                    if (!textEl) {
                        return;
                    }
                    updateFn(textEl, field);
                    const wordSpans = textEl.querySelectorAll('span');
                    if (wordSpans.length) {
                        wordSpans.forEach((span) => updateFn(span, field));
                    }
                });
                updateSelectionBar();
            }

            function applyOverlayColorToSelection(color) {
                if (!selectedOverlayField) {
                    return false;
                }
                const textEl = getOverlayTextElement(selectedOverlayField);
                const selection = window.getSelection();
                let range = null;
                if (selection && selection.rangeCount > 0) {
                    range = selection.getRangeAt(0);
                }
                if ((!range || range.collapsed) && overlaySelectionRange) {
                    range = overlaySelectionRange;
                }
                if (!range) {
                    return false;
                }
                if (!textEl.contains(range.commonAncestorContainer)) {
                    return false;
                }
                if (range.collapsed) {
                    return false;
                }
                const span = document.createElement('span');
                span.style.color = color;
                try {
                    range.surroundContents(span);
                } catch (err) {
                    // Fallback for complex selections
                    const contents = range.extractContents();
                    span.appendChild(contents);
                    range.insertNode(span);
                }
                if (selection) {
                    selection.removeAllRanges();
                }
                overlaySelectionRange = null;
                return true;
            }

            function applyOverlayBgToSelection(color) {
                if (!selectedOverlayField) {
                    return false;
                }
                const textEl = getOverlayTextElement(selectedOverlayField);
                const selection = window.getSelection();
                let range = null;
                if (selection && selection.rangeCount > 0) {
                    range = selection.getRangeAt(0);
                }
                if ((!range || range.collapsed) && overlaySelectionRange) {
                    range = overlaySelectionRange;
                }
                if (!range) {
                    return false;
                }
                if (!textEl.contains(range.commonAncestorContainer)) {
                    return false;
                }
                if (range.collapsed) {
                    return false;
                }
                const span = document.createElement('span');
                span.style.backgroundColor = color;
                try {
                    range.surroundContents(span);
                } catch (err) {
                    // Fallback for complex selections
                    const contents = range.extractContents();
                    span.appendChild(contents);
                    range.insertNode(span);
                }
                if (selection) {
                    selection.removeAllRanges();
                }
                overlaySelectionRange = null;
                return true;
            }

            function applyOverlayStyleToSelection(styleProperty, styleValue) {
                if (!selectedOverlayField) {
                    return false;
                }
                const textEl = getOverlayTextElement(selectedOverlayField);
                const selection = window.getSelection();
                let range = null;
                if (selection && selection.rangeCount > 0) {
                    range = selection.getRangeAt(0);
                }
                if ((!range || range.collapsed) && overlaySelectionRange) {
                    range = overlaySelectionRange;
                }
                if (!range) {
                    return false;
                }
                if (!textEl.contains(range.commonAncestorContainer)) {
                    return false;
                }
                if (range.collapsed) {
                    return false;
                }
                const span = document.createElement('span');
                span.style[styleProperty] = styleValue;
                try {
                    range.surroundContents(span);
                } catch (err) {
                    // Fallback for complex selections
                    const contents = range.extractContents();
                    span.appendChild(contents);
                    range.insertNode(span);
                }
                if (selection) {
                    selection.removeAllRanges();
                }
                overlaySelectionRange = null;
                return true;
            }

            /**
             * Build rich HTML representation of a text block for saving.
             * Clones the text element's inner HTML and wraps it with font metadata.
             * Hoisted to outer scope so both markOverlayFieldDirty() and
             * renderOverlayFields() can access it.
             */
            function buildBlockRichHtml(textSpan, fontFamily, fontWeight, fontStyle, fontSizePx, lineHeightPx, textColor) {
                const cloned = textSpan.cloneNode(true);
                cloned.removeAttribute('contenteditable');
                const backgroundColor = colorToHex(textSpan?.style?.backgroundColor || 'transparent');
                const backgroundStyle = backgroundColor && backgroundColor !== 'transparent'
                    ? `background-color:${backgroundColor};`
                    : '';
                const wrapperStyle = `position:relative;width:100%;height:100%;font-family:${fontFamily};font-weight:${fontWeight};font-style:${fontStyle};font-size:${fontSizePx};${lineHeightPx ? `line-height:${lineHeightPx};` : ''}color:${textColor};${backgroundStyle}`;
                return `<div style="${wrapperStyle}">${cloned.innerHTML}</div>`;
            }

            function applyStoredOverlayRichHtml(textSpan, field, richHtml) {
                const nextHtml = String(richHtml || '').trim();
                if (!textSpan || !nextHtml) {
                    return false;
                }

                const container = document.createElement('div');
                container.innerHTML = stripPxFontSizesFromRichHtml(nextHtml);
                const wrapper = container.firstElementChild;

                if (wrapper instanceof HTMLElement && container.childElementCount === 1) {
                    if (wrapper.style.fontFamily) {
                        textSpan.style.fontFamily = wrapper.style.fontFamily;
                        field.style.fontFamily = wrapper.style.fontFamily;
                    }
                    if (wrapper.style.fontWeight) {
                        textSpan.style.fontWeight = wrapper.style.fontWeight;
                        field.style.fontWeight = wrapper.style.fontWeight;
                        field.dataset.fontWeight = wrapper.style.fontWeight;
                    }
                    if (wrapper.style.fontStyle) {
                        textSpan.style.fontStyle = wrapper.style.fontStyle;
                        field.style.fontStyle = wrapper.style.fontStyle;
                        field.dataset.fontStyle = wrapper.style.fontStyle;
                    }
                    if (wrapper.style.color) {
                        const wrapperColor = colorToHex(wrapper.style.color || '#000000');
                        if (wrapperColor !== 'transparent') {
                            textSpan.style.color = wrapperColor;
                            field.style.color = wrapperColor;
                            field.dataset.textColor = wrapperColor;
                        }
                    }
                    const wrapperBackground = colorToHex(wrapper.style.backgroundColor || field.dataset.backgroundColor || 'transparent');
                    if (wrapperBackground !== 'transparent') {
                        textSpan.style.backgroundColor = wrapperBackground;
                        field.dataset.backgroundColor = wrapperBackground;
                    }
                    textSpan.innerHTML = wrapper.innerHTML;
                } else {
                    textSpan.innerHTML = container.innerHTML;
                }

                textSpan.style.whiteSpace = 'pre-wrap';
                textSpan.style.wordBreak = 'break-word';
                delete textSpan.dataset.exactGeometry;
                return true;
            }

            function dedupeOverlaySourceContentOps(ops) {
                const deduped = [];
                const seen = new Set();
                (Array.isArray(ops) ? ops : []).forEach((op) => {
                    if (!op || typeof op !== 'object') return;
                    const xref = Number(op.xref);
                    const start = Number(op.start);
                    const end = Number(op.end);
                    if (!Number.isFinite(xref) || !Number.isFinite(start) || !Number.isFinite(end)) return;
                    const matchedText = String(op.matched_text || '');
                    const key = `${xref}:${start}:${end}:${matchedText}`;
                    if (seen.has(key)) return;
                    seen.add(key);
                    deduped.push({
                        xref,
                        start,
                        end,
                        operator: String(op.operator || ''),
                        operator_text: String(op.operator_text || ''),
                        matched_text: matchedText,
                        collapsed_operator_text: String(op.collapsed_operator_text || ''),
                        tm_x: op.tm_x == null ? null : Number(op.tm_x),
                        tm_y: op.tm_y == null ? null : Number(op.tm_y),
                    });
                });
                return deduped;
            }

            function collectOverlaySourceContentOps(field, sourceWords = null, sourceBlock = null) {
                const ops = [];
                const block = sourceBlock || field?._overlaySourceBlock || null;
                if (Array.isArray(block?.source_content_ops)) {
                    ops.push(...block.source_content_ops);
                }
                const words = Array.isArray(sourceWords) ? sourceWords : (Array.isArray(field?._blockWords) ? field._blockWords : []);
                words.forEach((word) => {
                    if (Array.isArray(word?.source_content_ops)) {
                        ops.push(...word.source_content_ops);
                    }
                });
                return dedupeOverlaySourceContentOps(ops);
            }

            function buildOverlayEditRecordFromField(field, options = {}) {
                if (!field) return null;
                const textEl = getOverlayTextElement(field);
                if (!textEl) return null;

                const pageNumber = parseInt(field.dataset.pageNumber || '0', 10);
                const editKey = field.dataset.wordIndex || `${pageNumber}-0`;

                const hasPositionedSpans = textEl.querySelector('span') &&
                    Array.from(textEl.querySelectorAll('span')).some((span) => span.style.position === 'absolute');
                const currentText = hasPositionedSpans
                    ? (field.dataset.originalText || '')
                    : getOverlayExplicitText(textEl);

                const pageWidth = parseFloat(field.dataset.pageWidth || '0');
                const pageHeight = parseFloat(field.dataset.pageHeight || '0');
                const canvasWidth = parseFloat(field.dataset.canvasWidth || '0');
                const canvasHeight = parseFloat(field.dataset.canvasHeight || '0');
                const scaleX = canvasWidth / (pageWidth || 1);
                const scaleY = canvasHeight / (pageHeight || 1);

                const pad = parseFloat(field.dataset.padding || '0');
                const pdfLeft = (parseFloat(field.style.left) / scaleX) + pad;
                const pdfTop = (parseFloat(field.style.top) / scaleY) + pad;
                const pdfWidth = (parseFloat(field.style.width) / scaleX) - (pad * 2);
                const pdfHeight = (parseFloat(field.style.height) / scaleY) - (pad * 2);
                const pdfOriginX = pdfLeft;
                const pdfOriginY = pdfTop + pdfHeight;

                const origLeft = parseFloat(field.dataset.originalLeft || '0');
                const origTop = parseFloat(field.dataset.originalTop || '0');
                const origWidth = parseFloat(field.dataset.originalWidth || '0');
                const origHeight = parseFloat(field.dataset.originalHeight || '0');

                const fontFamily = field.style.fontFamily || 'Helvetica';
                const fontWeight = field.dataset.fontWeight || '400';
                const fontStyle = field.dataset.fontStyle || 'normal';
                const fieldUnderline = field.dataset.underline === 'true';
                const computedStyle = window.getComputedStyle(textEl);
                const fontSizePx = computedStyle.fontSize;
                const lineHeightPx = computedStyle.lineHeight !== 'normal' ? computedStyle.lineHeight : '';
                const fontSizePdf = parseFloat(field.dataset.fontSize || (parseFloat(fontSizePx) / scaleY) || '12');
                const textColor = field.dataset.textColor || computedStyle.color || '#000000';
                const backgroundColor = field.dataset.backgroundColor || colorToHex(computedStyle.backgroundColor || 'transparent');
                const lineHeightValue = parseFloat(field.dataset.lineHeight) || null;
                const resolvedFont = field.dataset.fontFamily || field.dataset.font || 'Helvetica';

                const richHtml = buildBlockRichHtml(textEl, fontFamily, fontWeight, fontStyle, fontSizePx, lineHeightPx, textColor);
                const wordStylesArr = buildOverlayWordStylesForSave(field, resolvedFont, fontWeight, fontStyle);
                const lineMetricsArr = buildOverlayLineMetricsForSave(field, resolvedFont, fontWeight, fontStyle);
                const syntheticTextbox = shouldConvertOverlayWordsToSyntheticTextbox(
                    field,
                    currentText,
                    null,
                    field.dataset.originalText || ''
                );
                const effectiveText = syntheticTextbox
                    ? buildSyntheticTextboxText(field, currentText, null, field.dataset.originalText || '')
                    : currentText;
                const sourceContentOps = collectOverlaySourceContentOps(field);

                return {
                    key: editKey,
                    value: {
                        page_number: pageNumber,
                        block_num: field.dataset.blockNum ? parseInt(field.dataset.blockNum, 10) : undefined,
                        original_text: field.dataset.originalText || '',
                        new_text: effectiveText,
                        rich_html: syntheticTextbox ? null : richHtml,
                        word_styles: syntheticTextbox ? null : wordStylesArr,
                        line_metrics: lineMetricsArr,
                        bbox: [pdfLeft, pdfTop, pdfLeft + pdfWidth, pdfTop + pdfHeight],
                        original_bbox: [origLeft, origTop, origLeft + origWidth, origTop + origHeight],
                        origin_x: pdfOriginX,
                        origin_y: pdfOriginY,
                        font: resolvedFont,
                        font_size: fontSizePdf,
                        font_weight: fontWeight,
                        font_style: fontStyle,
                        underline: fieldUnderline,
                        font_xref: field.dataset.fontXref ? parseInt(field.dataset.fontXref, 10) : null,
                        line_height: lineHeightValue,
                        color: textColor,
                        background_color: backgroundColor && backgroundColor !== 'transparent' ? backgroundColor : null,
                        synthetic_textbox: syntheticTextbox,
                        force_reinsert: !!options.forceReinsert,
                        source_content_ops: sourceContentOps,
                    }
                };
            }

            function buildOverlaySourceSegmentForBlock(block, words = []) {
                if (!block) return null;
                const safeWords = Array.isArray(words) ? words : [];
                const cleanText = (value) => sanitizeOverlayStorageText(value);
                const textLines = Array.isArray(block.text_lines) && block.text_lines.length
                    ? block.text_lines.map((line) => cleanText(String(line || '')))
                    : [];
                const text = textLines.length
                    ? textLines.join('\n')
                    : cleanText(String(block.text || ''));
                const bbox = [
                    Number(block.left) || 0,
                    Number(block.top) || 0,
                    (Number(block.left) || 0) + (Number(block.width) || 0),
                    (Number(block.top) || 0) + (Number(block.height) || 0),
                ];
                return {
                    block_num: block.block_num,
                    bbox,
                    text,
                    text_lines: textLines,
                    line_bboxes: Array.isArray(block.line_bboxes) ? block.line_bboxes.map((lb) => [...lb]) : [],
                    words: safeWords.map((word) => ({ ...word })),
                    source_content_ops: collectOverlaySourceContentOps(null, safeWords, block),
                };
            }

            function buildOverlayCleanupRect(editData) {
                if (!editData) return null;
                const rects = [];
                if (Array.isArray(editData.original_bbox) && editData.original_bbox.length >= 4) {
                    rects.push(editData.original_bbox);
                }
                if (Array.isArray(editData.bbox) && editData.bbox.length >= 4) {
                    rects.push(editData.bbox);
                }
                if (!rects.length) return null;
                const xs = rects.flatMap((rect) => [Number(rect[0]) || 0, Number(rect[2]) || 0]);
                const ys = rects.flatMap((rect) => [Number(rect[1]) || 0, Number(rect[3]) || 0]);
                return {
                    l: Math.min(...xs),
                    t: Math.min(...ys),
                    r: Math.max(...xs),
                    b: Math.max(...ys),
                };
            }

            function overlayCleanupRectsIntersect(a, b, tolerance = 0.5) {
                if (!a || !b) return false;
                const interW = Math.min(a.r, b.r) - Math.max(a.l, b.l);
                const interH = Math.min(a.b, b.b) - Math.max(a.t, b.t);
                return interW > tolerance && interH > tolerance;
            }

            function collectOverlayOverlapGroupEdits() {
                const fieldMetas = Array.from(document.querySelectorAll('.overlay-field[data-word-index]')).map((field) => {
                    const built = buildOverlayEditRecordFromField(field);
                    if (!built) return null;
                    return {
                        field,
                        key: built.key,
                        pageNumber: built.value.page_number,
                        editData: built.value,
                        cleanupRect: buildOverlayCleanupRect(built.value),
                    };
                }).filter(Boolean);

                const metaByKey = new Map(fieldMetas.map((meta) => [meta.key, meta]));
                const expandedEdits = new Map();
                const overlapGroupKeys = new Set();
                const queue = [];

                overlayEditedFields.forEach((editData, key) => {
                    const fallbackMeta = metaByKey.get(key);
                    const mergedEditData = {
                        ...(fallbackMeta?.editData || {}),
                        ...editData,
                    };
                    expandedEdits.set(key, mergedEditData);
                    if (buildOverlayCleanupRect(mergedEditData)) {
                        overlapGroupKeys.add(key);
                        queue.push(key);
                    }
                });

                while (queue.length > 0) {
                    const currentKey = queue.shift();
                    const currentEdit = expandedEdits.get(currentKey) || metaByKey.get(currentKey)?.editData;
                    const currentRect = buildOverlayCleanupRect(currentEdit);
                    if (!currentRect) continue;
                    const currentPage = Number(currentEdit?.page_number) || metaByKey.get(currentKey)?.pageNumber || 0;

                    fieldMetas.forEach((meta) => {
                        if (meta.key === currentKey) return;
                        if (meta.pageNumber !== currentPage) return;
                        if (!overlayCleanupRectsIntersect(currentRect, meta.cleanupRect)) return;
                        if (overlapGroupKeys.has(meta.key)) return;
                        overlapGroupKeys.add(meta.key);
                        queue.push(meta.key);
                    });
                }

                overlapGroupKeys.forEach((key) => {
                    const meta = metaByKey.get(key);
                    if (!meta) return;
                    const existing = expandedEdits.get(key);
                    if (existing) {
                        expandedEdits.set(key, { ...existing, force_reinsert: true });
                        return;
                    }
                    expandedEdits.set(key, {
                        ...meta.editData,
                        force_reinsert: true,
                    });
                });

                return expandedEdits;
            }

            function getCanonicalOverlayEditForKey(key, fallbackEditData = null) {
                const field = document.querySelector(`.overlay-field[data-word-index="${key}"]`);
                const built = field ? buildOverlayEditRecordFromField(field) : null;
                const canonicalEdit = built?.value
                    ? { ...(fallbackEditData || {}), ...built.value }
                    : (fallbackEditData ? { ...fallbackEditData } : null);
                return { field, editData: canonicalEdit };
            }

            function buildAtomicLiveSaveEditsForKey(key, fallbackEditData = null) {
                const { field, editData } = getCanonicalOverlayEditForKey(key, fallbackEditData);
                if (!editData) {
                    return [];
                }

                const originalText = normalizeOverlayComparableText(editData.original_text || '');
                const newText = normalizeOverlayComparableText(editData.new_text || '');
                const moveOnlyEdit = originalText === newText && overlayEditHasMoved(editData);
                if (moveOnlyEdit) {
                    return [{
                        ...editData,
                        force_reinsert: true,
                    }];
                }

                const segmentEdits = field ? buildOverlaySegmentEditsForSave(field, editData) : null;
                if (Array.isArray(segmentEdits) && segmentEdits.length > 0) {
                    return segmentEdits;
                }

                return [editData];
            }

            function buildLiveSavePayloadFromEdit(editData) {
                return {
                    page_number:   editData.page_number,
                    original_text: editData.original_text || '',
                    new_text:      String(editData.new_text ?? ''),
                    original_bbox: editData.original_bbox || editData.bbox || [0,0,0,0],
                    bbox:          editData.bbox || editData.original_bbox || [0,0,0,0],
                    origin_x:      editData.origin_x || 0,
                    origin_y:      editData.origin_y || 0,
                    font:          editData.font || 'Helvetica',
                    font_size:     editData.font_size || 12,
                    font_weight:   editData.font_weight || null,
                    font_style:    editData.font_style || null,
                    font_xref:     editData.font_xref || null,
                    underline:     !!editData.underline,
                    line_height:   editData.line_height || null,
                    color:         editData.color || '#000000',
                    background_color: editData.background_color || null,
                    word_styles:   Array.isArray(editData.word_styles) ? editData.word_styles : null,
                    line_metrics:  Array.isArray(editData.line_metrics) ? editData.line_metrics : null,
                    source_content_ops: Array.isArray(editData.source_content_ops) ? editData.source_content_ops : null,
                    synthetic_textbox: !!editData.synthetic_textbox,
                    paragraph_bbox: Array.isArray(editData.paragraph_bbox) ? editData.paragraph_bbox : null,
                    retry_mode: typeof editData.retry_mode === 'string' ? editData.retry_mode : null,
                    redaction_padding: Number.isFinite(Number(editData.redaction_padding)) ? Number(editData.redaction_padding) : null,
                };
            }

            function buildLiveSaveRetryEdit(editData, attempt = 1) {
                const retryEdit = clonePlainData(editData);
                if (attempt <= 1) {
                    delete retryEdit.retry_mode;
                    delete retryEdit.redaction_padding;
                    return retryEdit;
                }

                const lineCount = Array.isArray(retryEdit.line_metrics) ? retryEdit.line_metrics.length : 0;
                const isMultiline = lineCount > 1
                    || String(retryEdit.original_text ?? '').includes('\n')
                    || String(retryEdit.new_text ?? '').includes('\n');
                const hasSourceOps = Array.isArray(retryEdit.source_content_ops) && retryEdit.source_content_ops.length > 0;

                const retryPlan = isMultiline
                    ? [
                        { mode: 'paragraph_strict', pad: 0.0 },
                        { mode: 'span_search', pad: 0.0 },
                        { mode: 'paragraph_strict', pad: 1.0 },
                        { mode: 'paragraph_strict', pad: 1.75 },
                    ]
                    : [
                        { mode: 'precise_coords_strict', pad: 0.0 },
                        { mode: 'span_search', pad: 0.0 },
                        { mode: hasSourceOps ? 'source_ops_strict' : 'line_range_strict', pad: 0.75 },
                        { mode: 'precise_coords_strict', pad: 1.25 },
                    ];

                const step = retryPlan[Math.min(retryPlan.length - 1, Math.max(0, attempt - 2))];
                retryEdit.retry_mode = step.mode;
                retryEdit.redaction_padding = step.pad;
                return retryEdit;
            }

            function normalizeOverlayComparableText(value) {
                return String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .replace(/\s+/g, ' ')
                    .trim();
            }

            function overlayEditHasMoved(editData, tolerance = 2) {
                if (!Array.isArray(editData?.original_bbox) || !Array.isArray(editData?.bbox)) {
                    return true;
                }
                const originalBbox = editData.original_bbox;
                const currentBbox = editData.bbox;
                return Math.abs((Number(originalBbox[0]) || 0) - (Number(currentBbox[0]) || 0)) > tolerance
                    || Math.abs((Number(originalBbox[1]) || 0) - (Number(currentBbox[1]) || 0)) > tolerance
                    || Math.abs((Number(originalBbox[2]) || 0) - (Number(currentBbox[2]) || 0)) > tolerance
                    || Math.abs((Number(originalBbox[3]) || 0) - (Number(currentBbox[3]) || 0)) > tolerance;
            }

            function overlayEditHasStyleMutation(editData) {
                if (!editData) {
                    return false;
                }
                const fontWeight = String(editData.font_weight || '').trim().toLowerCase();
                const fontStyle = String(editData.font_style || '').trim().toLowerCase();
                const color = String(editData.color || '').trim().toLowerCase();
                const bgColor = String(editData.background_color || '').trim().toLowerCase();
                return Boolean(editData.rich_html)
                    || (Array.isArray(editData.word_styles) && editData.word_styles.length > 0)
                    || Boolean(editData.underline)
                    || (fontWeight && fontWeight !== '400' && fontWeight !== 'normal')
                    || (fontStyle && fontStyle !== 'normal')
                    || (color && color !== '#000000' && color !== '000000' && color !== 'rgb(0, 0, 0)')
                    || (bgColor !== '' && bgColor !== 'transparent');
            }

            function isMaterialOverlaySaveEdit(editData, { honorForceReinsert = true } = {}) {
                if (!editData) {
                    return false;
                }
                if (honorForceReinsert && editData.force_reinsert) {
                    return true;
                }

                const originalText = normalizeOverlayComparableText(editData.original_text || '');
                const newText = normalizeOverlayComparableText(editData.new_text || '');

                if (originalText !== newText) {
                    return true;
                }
                if (overlayEditHasMoved(editData)) {
                    return true;
                }
                return overlayEditHasStyleMutation(editData);
            }

            function clonePlainData(value) {
                return value == null ? value : JSON.parse(JSON.stringify(value));
            }

            function cloneOverlayEditMap(sourceMap) {
                const clone = new Map();
                if (!(sourceMap instanceof Map)) {
                    return clone;
                }
                sourceMap.forEach((value, key) => {
                    clone.set(key, clonePlainData(value));
                });
                return clone;
            }

            function snapshotOverlayEditState() {
                return {
                    edited: cloneOverlayEditMap(overlayEditedFields),
                    persisted: cloneOverlayEditMap(overlayPersistedEdits),
                };
            }

            function serializeOverlayHistorySnapshot(snapshot) {
                const serializeMap = (sourceMap) => Array.from(sourceMap instanceof Map ? sourceMap.entries() : [])
                    .sort((left, right) => String(left[0]).localeCompare(String(right[0])));

                return JSON.stringify({
                    edited: serializeMap(snapshot?.edited),
                    persisted: serializeMap(snapshot?.persisted),
                });
            }

            function overlayHistorySnapshotsEqual(left, right) {
                return serializeOverlayHistorySnapshot(left) === serializeOverlayHistorySnapshot(right);
            }

            function restoreOverlayEditState(snapshot) {
                overlayEditedFields = cloneOverlayEditMap(snapshot?.edited);
                overlayPersistedEdits = cloneOverlayEditMap(snapshot?.persisted || snapshot?.edited);
                _liveSavedKeys.clear();
                document.querySelectorAll('.overlay-field[data-live-save-state]').forEach((field) => {
                    delete field.dataset.liveSaveState;
                });
                persistOverlayEdits();
                updateOverlaySaveButton();
            }

            function getOverlayPageDataByNumber(pageNumber) {
                if (!Array.isArray(overlayExtractionData)) {
                    return null;
                }
                return overlayExtractionData.find((page) => Number(page?.page_number) === Number(pageNumber)) || null;
            }

            function getRenderedPageWrapper(pageNumber) {
                return document.querySelector(`.page-wrapper.overlay-page[data-page-number="${pageNumber}"]`)
                    || document.querySelector(`.page[data-page-index="${Math.max(0, Number(pageNumber) - 1)}"]`)
                    || null;
            }

            function parseCssPx(value, fallback = 0) {
                const parsed = parseFloat(String(value || '').replace('px', ''));
                return Number.isFinite(parsed) ? parsed : fallback;
            }

            function getRectRelativeTo(element, ancestorRect) {
                const rect = element.getBoundingClientRect();
                return {
                    left: rect.left - ancestorRect.left,
                    top: rect.top - ancestorRect.top,
                    width: rect.width,
                    height: rect.height,
                    right: rect.right - ancestorRect.left,
                    bottom: rect.bottom - ancestorRect.top,
                };
            }

            function buildCanvasFont(style) {
                const fontStyle = style.fontStyle || 'normal';
                const fontWeight = style.fontWeight || '400';
                const fontSize = style.fontSize || '16px';
                const fontFamily = style.fontFamily || 'sans-serif';
                return `${fontStyle} ${fontWeight} ${fontSize} ${fontFamily}`;
            }

            function drawTextRun(ctx, text, x, y, letterSpacing = 0) {
                if (!text) {
                    return 0;
                }
                if (!letterSpacing) {
                    ctx.fillText(text, x, y);
                    return ctx.measureText(text).width;
                }

                let cursorX = x;
                for (const char of Array.from(text)) {
                    ctx.fillText(char, cursorX, y);
                    cursorX += ctx.measureText(char).width + letterSpacing;
                }
                return cursorX - x;
            }

            function wrapCanvasText(ctx, text, maxWidth) {
                const normalizedLines = String(text ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .split('\n');
                const lines = [];

                normalizedLines.forEach((rawLine) => {
                    if (!rawLine.length) {
                        lines.push('');
                        return;
                    }

                    const words = rawLine.split(/(\s+)/).filter((token) => token.length > 0);
                    let currentLine = '';

                    words.forEach((token) => {
                        const candidate = currentLine + token;
                        if (!currentLine || ctx.measureText(candidate).width <= maxWidth) {
                            currentLine = candidate;
                            return;
                        }

                        if (currentLine.trim().length) {
                            lines.push(currentLine.trimEnd());
                            currentLine = token.trimStart();
                            if (ctx.measureText(currentLine).width <= maxWidth) {
                                return;
                            }
                        }

                        let partial = '';
                        for (const char of Array.from(token)) {
                            const nextPartial = partial + char;
                            if (partial && ctx.measureText(nextPartial).width > maxWidth) {
                                lines.push(partial);
                                partial = char;
                            } else {
                                partial = nextPartial;
                            }
                        }
                        currentLine = partial;
                    });

                    lines.push(currentLine.trimEnd());
                });

                return lines;
            }

            function drawMultilineTextBox(ctx, textElement, wrapperRect) {
                const style = window.getComputedStyle(textElement);
                const boxRect = getRectRelativeTo(textElement, wrapperRect);
                const fontSize = parseCssPx(style.fontSize, 16);
                const lineHeight = parseCssPx(style.lineHeight, fontSize * 1.2);
                const paddingLeft = parseCssPx(style.paddingLeft);
                const paddingTop = parseCssPx(style.paddingTop);
                const paddingRight = parseCssPx(style.paddingRight);
                const maxWidth = Math.max(1, boxRect.width - paddingLeft - paddingRight);
                const letterSpacing = parseCssPx(style.letterSpacing);
                const drawUnderline = String(style.textDecorationLine || '').includes('underline');

                ctx.save();
                ctx.font = buildCanvasFont(style);
                ctx.fillStyle = style.color || '#000000';
                ctx.textBaseline = 'top';
                ctx.globalAlpha = Math.min(1, Math.max(0, parseFloat(style.opacity || '1')));

                const textAlign = style.textAlign || 'left';
                const lines = wrapCanvasText(ctx, textElement.innerText || textElement.textContent || '', maxWidth);
                lines.forEach((line, lineIndex) => {
                    const lineWidth = ctx.measureText(line).width;
                    let lineX = boxRect.left + paddingLeft;
                    if (textAlign === 'center') {
                        lineX += Math.max(0, (maxWidth - lineWidth) / 2);
                    } else if (textAlign === 'right' || textAlign === 'end') {
                        lineX += Math.max(0, maxWidth - lineWidth);
                    }
                    const lineY = boxRect.top + paddingTop + (lineIndex * lineHeight);
                    drawTextRun(ctx, line, lineX, lineY, letterSpacing);

                    if (drawUnderline && line.trim().length > 0) {
                        ctx.beginPath();
                        ctx.lineWidth = Math.max(1, fontSize * 0.06);
                        ctx.strokeStyle = style.color || '#000000';
                        ctx.moveTo(lineX, lineY + fontSize * 0.96);
                        ctx.lineTo(lineX + lineWidth, lineY + fontSize * 0.96);
                        ctx.stroke();
                    }
                });

                ctx.restore();
            }

            function drawPositionedTextRuns(ctx, textElement, wrapperRect) {
                const positionedSpans = Array.from(textElement.querySelectorAll('span')).filter((span) => {
                    const style = window.getComputedStyle(span);
                    return style.position === 'absolute' && (span.textContent || '').trim().length > 0;
                });

                positionedSpans.forEach((span) => {
                    const style = window.getComputedStyle(span);
                    const spanRect = getRectRelativeTo(span, wrapperRect);
                    const fontSize = parseCssPx(style.fontSize, 16);
                    const letterSpacing = parseCssPx(style.letterSpacing);
                    const drawUnderline = String(style.textDecorationLine || '').includes('underline');

                    ctx.save();
                    ctx.font = buildCanvasFont(style);
                    ctx.fillStyle = style.color || '#000000';
                    ctx.textBaseline = 'top';
                    ctx.globalAlpha = Math.min(1, Math.max(0, parseFloat(style.opacity || '1')));
                    const textWidth = drawTextRun(ctx, span.textContent || '', spanRect.left, spanRect.top, letterSpacing);

                    if (drawUnderline) {
                        ctx.beginPath();
                        ctx.lineWidth = Math.max(1, fontSize * 0.06);
                        ctx.strokeStyle = style.color || '#000000';
                        ctx.moveTo(spanRect.left, spanRect.top + fontSize * 0.96);
                        ctx.lineTo(spanRect.left + textWidth, spanRect.top + fontSize * 0.96);
                        ctx.stroke();
                    }
                    ctx.restore();
                });
            }

            function drawOverlayFieldSnapshot(ctx, field, wrapperRect) {
                if (!(field instanceof Element)) {
                    return;
                }
                const fieldStyle = window.getComputedStyle(field);
                if (fieldStyle.display === 'none' || fieldStyle.visibility === 'hidden' || parseFloat(fieldStyle.opacity || '1') <= 0) {
                    return;
                }

                const textElement = field.querySelector('[contenteditable]') || field;
                const hasAbsoluteRuns = Array.from(textElement.querySelectorAll('span')).some((span) => {
                    const style = window.getComputedStyle(span);
                    return style.position === 'absolute';
                });

                if (hasAbsoluteRuns) {
                    drawPositionedTextRuns(ctx, textElement, wrapperRect);
                } else {
                    drawMultilineTextBox(ctx, textElement, wrapperRect);
                }
            }

            function rectsIntersect(a, b) {
                if (!a || !b) {
                    return false;
                }
                const aRight = Number.isFinite(a.right) ? a.right : (a.left + a.width);
                const aBottom = Number.isFinite(a.bottom) ? a.bottom : (a.top + a.height);
                const bRight = Number.isFinite(b.right) ? b.right : (b.left + b.width);
                const bBottom = Number.isFinite(b.bottom) ? b.bottom : (b.top + b.height);
                return a.left <= bRight
                    && aRight >= b.left
                    && a.top <= bBottom
                    && aBottom >= b.top;
            }

            function normalizeVerificationText(value) {
                return String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .replace(/\s+/g, ' ')
                    .trim();
            }

            function compactVerificationText(value) {
                return normalizeVerificationText(value)
                    .toLowerCase()
                    .replace(/\s+/g, '');
            }

            function verificationTargetIsSingleLine(target) {
                if (!target || !Array.isArray(target.edits) || target.edits.length === 0) {
                    return false;
                }

                return target.edits.every((edit) => {
                    return verificationEditIsSingleLine(edit);
                });
            }

            function verificationEditIsSingleLine(edit) {
                if (!edit) {
                    return false;
                }
                const originalText = String(edit?.original_text ?? '');
                const newText = String(edit?.new_text ?? '');
                const lineMetrics = Array.isArray(edit?.line_metrics) ? edit.line_metrics : [];
                return !originalText.includes('\n')
                    && !newText.includes('\n')
                    && lineMetrics.length <= 1;
            }

            function buildVerificationExpectedTextSignature(pageEdits) {
                if (!Array.isArray(pageEdits) || pageEdits.length === 0) {
                    return '';
                }

                const ordered = [...pageEdits].sort((a, b) => {
                    const aBox = Array.isArray(a?.bbox) ? a.bbox : (Array.isArray(a?.original_bbox) ? a.original_bbox : [0, 0, 0, 0]);
                    const bBox = Array.isArray(b?.bbox) ? b.bbox : (Array.isArray(b?.original_bbox) ? b.original_bbox : [0, 0, 0, 0]);
                    const aTop = Number(aBox[1]) || 0;
                    const bTop = Number(bBox[1]) || 0;
                    if (Math.abs(aTop - bTop) >= 2) {
                        return aTop - bTop;
                    }
                    return (Number(aBox[0]) || 0) - (Number(bBox[0]) || 0);
                });

                return normalizeVerificationText(ordered.map((edit) => String(edit?.new_text ?? '')).join(' '));
            }

            function getLiveSavePreviewEntries(saveResult) {
                if (Array.isArray(saveResult?.liveSavePreviews) && saveResult.liveSavePreviews.length > 0) {
                    return saveResult.liveSavePreviews;
                }
                if (saveResult?.preview) {
                    return [saveResult.preview];
                }
                return [];
            }

            function getLiveSavePreviewAssets(saveResult) {
                if (Array.isArray(saveResult?.liveSavePreviewAssets) && saveResult.liveSavePreviewAssets.length > 0) {
                    return saveResult.liveSavePreviewAssets;
                }
                const entries = getLiveSavePreviewEntries(saveResult);
                if (entries.length === 0) {
                    return [];
                }
                return entries.map((preview) => ({ preview }));
            }

            function collectLiveSavePreviewEntryIds(saveResult) {
                return getLiveSavePreviewEntries(saveResult)
                    .map((preview) => String(preview?.save_id || '').trim())
                    .filter((value) => value.length > 0);
            }

            function previewMatchesVerificationTarget(preview, target) {
                if (!preview || !target) {
                    return false;
                }

                const previewPage = Number(preview?.page_number) || 0;
                if (previewPage !== Number(target.pageNumber || 0)) {
                    return false;
                }

                const previewText = compactVerificationText(preview?.new_text || '');
                const targetText = compactVerificationText(target?.targetTextSignature || '');
                if (!previewText || !targetText) {
                    return false;
                }

                return previewText === targetText
                    || previewText.includes(targetText)
                    || targetText.includes(previewText);
            }

            function buildVerificationClipRectFromPreview(target, preview) {
                if (!target || !preview?.clip_rect) {
                    return null;
                }
                const clipRect = preview.clip_rect;
                const pageData = target.edits?.find((edit) => Number(edit?.page_width) > 0 && Number(edit?.page_height) > 0) || {};
                const pageWidth = Number(pageData.page_width) || Number(getOverlayPageDataByNumber(target.pageNumber)?.width) || 0;
                const pageHeight = Number(pageData.page_height) || Number(getOverlayPageDataByNumber(target.pageNumber)?.height) || 0;
                return pdfRectToCanvasRect(
                    [clipRect.x0, clipRect.y0, clipRect.x1, clipRect.y1],
                    pageWidth,
                    pageHeight,
                    target.fullCanvas.width,
                    target.fullCanvas.height,
                    0,
                    0
                );
            }

            function pdfRectToCanvasRect(rect, pageWidth, pageHeight, canvasWidth, canvasHeight, padX = 0, padY = padX) {
                if (!Array.isArray(rect) || rect.length < 4 || pageWidth <= 0 || pageHeight <= 0 || canvasWidth <= 0 || canvasHeight <= 0) {
                    return null;
                }
                const scaleX = canvasWidth / pageWidth;
                const scaleY = canvasHeight / pageHeight;
                const left = Math.max(0, Math.floor((Math.min(Number(rect[0]) || 0, Number(rect[2]) || 0) * scaleX) - padX));
                const top = Math.max(0, Math.floor((Math.min(Number(rect[1]) || 0, Number(rect[3]) || 0) * scaleY) - padY));
                const right = Math.min(canvasWidth, Math.ceil((Math.max(Number(rect[0]) || 0, Number(rect[2]) || 0) * scaleX) + padX));
                const bottom = Math.min(canvasHeight, Math.ceil((Math.max(Number(rect[1]) || 0, Number(rect[3]) || 0) * scaleY) + padY));
                return {
                    x: left,
                    y: top,
                    width: Math.max(1, right - left),
                    height: Math.max(1, bottom - top),
                };
            }

            function buildVerificationEraseRects(pageEdits, canvasWidth, canvasHeight) {
                if (!Array.isArray(pageEdits) || pageEdits.length === 0) {
                    return [];
                }
                return pageEdits.flatMap((entry) => {
                    const edit = entry?.editData || entry;
                    const originalText = String(edit?.original_text ?? '');
                    const newText = String(edit?.new_text ?? '');
                    const isSingleLine = verificationEditIsSingleLine(edit);
                    const padX = isSingleLine ? 3 : 10;
                    const padY = isSingleLine ? 2 : 8;
                    const pageWidth = Number(edit?.page_width) || 0;
                    const pageHeight = Number(edit?.page_height) || 0;
                    const rects = [edit?.original_bbox, edit?.bbox]
                        .map((rect) => pdfRectToCanvasRect(rect, pageWidth, pageHeight, canvasWidth, canvasHeight, padX, padY))
                        .filter(Boolean);
                    if (originalText === newText && rects.length > 1) {
                        return rects.slice(0, 1);
                    }
                    return rects;
                });
            }

            function buildVerificationCropBounds(cropRect) {
                return {
                    left: Number(cropRect?.x) || 0,
                    top: Number(cropRect?.y) || 0,
                    width: Math.max(1, Number(cropRect?.width) || 0),
                    height: Math.max(1, Number(cropRect?.height) || 0),
                    right: (Number(cropRect?.x) || 0) + Math.max(1, Number(cropRect?.width) || 0),
                    bottom: (Number(cropRect?.y) || 0) + Math.max(1, Number(cropRect?.height) || 0),
                };
            }

            function captureOverlayVerificationTextSignature(pageWrapper, cropRect) {
                if (!(pageWrapper instanceof Element)) {
                    return '';
                }

                const wrapperRect = pageWrapper.getBoundingClientRect();
                const cropBounds = buildVerificationCropBounds(cropRect);
                const entries = Array.from(pageWrapper.querySelectorAll('.overlay-field'))
                    .map((field) => {
                        const style = window.getComputedStyle(field);
                        if (style.display === 'none' || style.visibility === 'hidden' || parseFloat(style.opacity || '1') <= 0) {
                            return null;
                        }
                        const textElement = field.querySelector('[contenteditable]') || field;
                        const fieldRect = getRectRelativeTo(textElement, wrapperRect);
                        const bounds = {
                            left: fieldRect.left,
                            top: fieldRect.top,
                            width: fieldRect.width,
                            height: fieldRect.height,
                            right: fieldRect.left + fieldRect.width,
                            bottom: fieldRect.top + fieldRect.height,
                        };
                        if (!rectsIntersect(bounds, cropBounds)) {
                            return null;
                        }
                        const text = normalizeVerificationText(textElement?.innerText || textElement?.textContent || '');
                        if (!text) {
                            return null;
                        }
                        return {
                            top: bounds.top,
                            left: bounds.left,
                            text,
                        };
                    })
                    .filter(Boolean)
                    .sort((a, b) => (Math.abs(a.top - b.top) < 2 ? a.left - b.left : a.top - b.top));

                return normalizeVerificationText(entries.map((entry) => entry.text).join(' '));
            }

            async function captureRenderedPageSnapshot(pageWrapper, pageEdits = []) {
                const wrapperRect = pageWrapper.getBoundingClientRect();
                const width = Math.max(1, Math.round(wrapperRect.width));
                const height = Math.max(1, Math.round(wrapperRect.height));
                const snapshotCanvas = document.createElement('canvas');
                snapshotCanvas.width = width;
                snapshotCanvas.height = height;
                const context = snapshotCanvas.getContext('2d');
                context.fillStyle = '#ffffff';
                context.fillRect(0, 0, width, height);

                const baseCanvas = pageWrapper.querySelector('canvas');
                if (baseCanvas) {
                    context.drawImage(baseCanvas, 0, 0, width, height);
                }

                buildVerificationEraseRects(pageEdits, width, height).forEach((rect) => {
                    context.fillStyle = '#ffffff';
                    context.fillRect(rect.x, rect.y, rect.width, rect.height);
                });

                pageEdits.forEach((entry) => {
                    const key = String(entry?.key ?? '');
                    if (!key) {
                        return;
                    }
                    const selector = window.CSS && typeof window.CSS.escape === 'function'
                        ? `.overlay-field[data-word-index="${window.CSS.escape(key)}"]`
                        : `.overlay-field[data-word-index="${key.replace(/"/g, '\\"')}"]`;
                    const field = pageWrapper.querySelector(selector);
                    if (field) {
                        drawOverlayFieldSnapshot(context, field, wrapperRect);
                    }
                });

                return snapshotCanvas;
            }

            function buildVerificationCropRect(pageNumber, pageEdits, canvasWidth, canvasHeight) {
                const pageData = getOverlayPageDataByNumber(pageNumber);
                const fallbackDims = pageEdits.find((edit) => Number(edit?.page_width) > 0 && Number(edit?.page_height) > 0) || {};
                const pageWidth = Number(pageData?.width) || Number(fallbackDims.page_width) || 0;
                const pageHeight = Number(pageData?.height) || Number(fallbackDims.page_height) || 0;

                const pdfRects = [];
                pageEdits.forEach((edit) => {
                    [edit?.original_bbox, edit?.bbox].forEach((rect) => {
                        if (!Array.isArray(rect) || rect.length < 4) {
                            return;
                        }
                        pdfRects.push([
                            Number(rect[0]) || 0,
                            Number(rect[1]) || 0,
                            Number(rect[2]) || 0,
                            Number(rect[3]) || 0,
                        ]);
                    });
                });

                if (!pdfRects.length || pageWidth <= 0 || pageHeight <= 0) {
                    return { x: 0, y: 0, width: canvasWidth, height: canvasHeight };
                }

                const left = Math.max(0, Math.min(...pdfRects.map((rect) => Math.min(rect[0], rect[2]))));
                const top = Math.max(0, Math.min(...pdfRects.map((rect) => Math.min(rect[1], rect[3]))));
                const right = Math.max(...pdfRects.map((rect) => Math.max(rect[0], rect[2])));
                const bottom = Math.max(...pdfRects.map((rect) => Math.max(rect[1], rect[3])));
                const scaleX = canvasWidth / pageWidth;
                const scaleY = canvasHeight / pageHeight;

                const singleLine = Array.isArray(pageEdits) && pageEdits.length > 0 && pageEdits.every((edit) => verificationEditIsSingleLine(edit));
                const padX = singleLine ? 10 : liveSaveVerifyPaddingPx;
                const padY = singleLine ? 8 : liveSaveVerifyPaddingPx;

                const cropLeft = Math.max(0, Math.floor(left * scaleX) - padX);
                const cropTop = Math.max(0, Math.floor(top * scaleY) - padY);
                const cropRight = Math.min(canvasWidth, Math.ceil(right * scaleX) + padX);
                const cropBottom = Math.min(canvasHeight, Math.ceil(bottom * scaleY) + padY);

                return {
                    x: cropLeft,
                    y: cropTop,
                    width: Math.max(1, cropRight - cropLeft),
                    height: Math.max(1, cropBottom - cropTop),
                };
            }

            function cropCanvasRegion(sourceCanvas, rect) {
                const canvas = document.createElement('canvas');
                canvas.width = Math.max(1, Math.floor(rect.width));
                canvas.height = Math.max(1, Math.floor(rect.height));
                const context = canvas.getContext('2d');
                context.drawImage(
                    sourceCanvas,
                    rect.x,
                    rect.y,
                    rect.width,
                    rect.height,
                    0,
                    0,
                    canvas.width,
                    canvas.height
                );
                return canvas;
            }

            async function captureLiveSaveVerificationTargets(editSnapshot) {
                const pageEdits = new Map();
                editSnapshot?.edited?.forEach((editData, key) => {
                    if (!isMaterialOverlaySaveEdit(editData, { honorForceReinsert: false })) {
                        return;
                    }
                    const pageNumber = Number(editData?.page_number) || 0;
                    if (!pageNumber) {
                        return;
                    }
                    if (!pageEdits.has(pageNumber)) {
                        pageEdits.set(pageNumber, []);
                    }
                    pageEdits.get(pageNumber).push({
                        key,
                        editData: clonePlainData(editData),
                    });
                });

                const targets = [];
                for (const [pageNumber, editEntries] of pageEdits.entries()) {
                    const pageWrapper = getRenderedPageWrapper(pageNumber);
                    if (!pageWrapper) {
                        throw new Error(`Verification could not find page ${pageNumber} in the viewer.`);
                    }
                    const edits = editEntries.map((entry) => entry.editData);
                    const snapshotCanvas = await captureRenderedPageSnapshot(pageWrapper, editEntries);
                    const cropRect = buildVerificationCropRect(pageNumber, edits, snapshotCanvas.width, snapshotCanvas.height);
                    targets.push({
                        pageNumber,
                        edits,
                        editEntries,
                        fullCanvas: snapshotCanvas,
                        cropRect,
                        targetTextSignature: buildVerificationExpectedTextSignature(edits),
                    });
                }

                return targets;
            }

            async function createWorkingCopySnapshot() {
                const response = await fetch(createWorkingCopySnapshotUrl, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'Accept': 'application/json',
                    },
                });
                const result = await response.json().catch(() => ({}));
                if (!response.ok) {
                    throw new Error(result.error || result.message || `Failed to create working-copy snapshot (${response.status}).`);
                }
                if (!result?.success || !result?.snapshot_token) {
                    throw new Error(result.error || result.message || 'Working-copy snapshot did not return a token.');
                }
                return result;
            }

            async function restorePdfWorkingCopy(snapshotToken, { discardPreviewEntries = [], deleteSnapshot = false } = {}) {
                const response = await fetch(restoreWorkingCopyUrl, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                    },
                    body: JSON.stringify({
                        snapshot_token: snapshotToken,
                        discard_preview_entries: discardPreviewEntries,
                        delete_snapshot: !!deleteSnapshot,
                    }),
                });
                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result.success) {
                    throw new Error(result.error || result.message || `Failed to restore working copy (${response.status}).`);
                }
                pdfVersion = Date.now();
                return result;
            }

            async function discardWorkingCopySnapshot(snapshotToken, { discardPreviewEntries = [] } = {}) {
                if (!snapshotToken) {
                    return { success: true };
                }

                const response = await fetch(discardWorkingCopySnapshotUrl, {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                    },
                    body: JSON.stringify({
                        snapshot_token: snapshotToken,
                        discard_preview_entries: discardPreviewEntries,
                    }),
                });
                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result.success) {
                    throw new Error(result.error || result.message || `Failed to discard working-copy snapshot (${response.status}).`);
                }
                return result;
            }

            async function extractSavedPdfVerificationTextSignature(pdf, pageNumber, cropRect) {
                const page = await pdf.getPage(pageNumber);
                const viewport = page.getViewport({ scale: currentScale });
                const cropBounds = buildVerificationCropBounds(cropRect);
                const textContent = await page.getTextContent();
                const entries = textContent.items
                    .map((item) => {
                        const transform = pdfjsLib.Util.transform(viewport.transform, item.transform);
                        const left = transform[4];
                        const baselineY = transform[5];
                        const height = Math.abs(transform[3]) || Math.abs(item.height || 0);
                        const width = Math.max(
                            0,
                            (Number(item.width) || 0) * viewport.scale
                        );
                        const bounds = {
                            left,
                            top: baselineY - height,
                            width,
                            height,
                            right: left + width,
                            bottom: baselineY,
                        };
                        if (!rectsIntersect(bounds, cropBounds)) {
                            return null;
                        }
                        const text = normalizeVerificationText(item.str);
                        if (!text) {
                            return null;
                        }
                        return {
                            top: bounds.top,
                            left: bounds.left,
                            text,
                        };
                    })
                    .filter(Boolean)
                    .sort((a, b) => (Math.abs(a.top - b.top) < 2 ? a.left - b.left : a.top - b.top));

                return normalizeVerificationText(entries.map((entry) => entry.text).join(' '));
            }

            async function renderSavedPdfVerificationCanvases(targets) {
                const joiner = pdfUrl.includes('?') ? '&' : '?';
                const loadingTask = pdfjsLib.getDocument(`${pdfUrl}${joiner}verify=${Date.now()}`);
                const pdf = await loadingTask.promise;
                try {
                    const rendered = new Map();
                    for (const target of targets) {
                        const page = await pdf.getPage(target.pageNumber);
                        const viewport = page.getViewport({ scale: currentScale });
                        const renderCanvas = document.createElement('canvas');
                        renderCanvas.width = Math.max(1, Math.ceil(viewport.width));
                        renderCanvas.height = Math.max(1, Math.ceil(viewport.height));
                        await page.render({
                            canvasContext: renderCanvas.getContext('2d'),
                            viewport,
                        }).promise;

                        if (renderCanvas.width !== target.fullCanvas.width || renderCanvas.height !== target.fullCanvas.height) {
                            const scaledCanvas = document.createElement('canvas');
                            scaledCanvas.width = target.fullCanvas.width;
                            scaledCanvas.height = target.fullCanvas.height;
                            scaledCanvas.getContext('2d').drawImage(renderCanvas, 0, 0, scaledCanvas.width, scaledCanvas.height);
                            rendered.set(target.pageNumber, {
                                canvas: scaledCanvas,
                                textSignature: await extractSavedPdfVerificationTextSignature(pdf, target.pageNumber, target.cropRect),
                            });
                        } else {
                            rendered.set(target.pageNumber, {
                                canvas: renderCanvas,
                                textSignature: await extractSavedPdfVerificationTextSignature(pdf, target.pageNumber, target.cropRect),
                            });
                        }
                    }
                    return rendered;
                } finally {
                    if (pdf?.destroy) {
                        await pdf.destroy().catch(() => {});
                    }
                }
            }

            async function loadVerificationImageCanvas(imageUrl, targetWidth = null, targetHeight = null) {
                if (!imageUrl) {
                    return null;
                }

                const response = await fetch(`${imageUrl}${imageUrl.includes('?') ? '&' : '?'}verify_image=${Date.now()}`, {
                    credentials: 'same-origin',
                    cache: 'no-store',
                });
                if (!response.ok) {
                    throw new Error(`Failed to load verification image (${response.status}).`);
                }

                const blob = await response.blob();
                const bitmap = await createImageBitmap(blob);
                const width = Math.max(1, Math.round(Number(targetWidth) || bitmap.width || 1));
                const height = Math.max(1, Math.round(Number(targetHeight) || bitmap.height || 1));
                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const context = canvas.getContext('2d');
                context.drawImage(bitmap, 0, 0, width, height);
                bitmap.close?.();
                return canvas;
            }

            function compareVerificationCanvases(targetCanvas, savedCanvas) {
                const width = Math.max(1, Math.min(targetCanvas.width, savedCanvas.width));
                const height = Math.max(1, Math.min(targetCanvas.height, savedCanvas.height));
                const targetData = targetCanvas.getContext('2d').getImageData(0, 0, width, height);
                const savedData = savedCanvas.getContext('2d').getImageData(0, 0, width, height);
                const diffCanvas = document.createElement('canvas');
                diffCanvas.width = width;
                diffCanvas.height = height;
                const diffContext = diffCanvas.getContext('2d');
                const diffData = diffContext.createImageData(width, height);

                let diffPixels = 0;
                for (let offset = 0; offset < targetData.data.length; offset += 4) {
                    const delta = Math.abs(targetData.data[offset] - savedData.data[offset])
                        + Math.abs(targetData.data[offset + 1] - savedData.data[offset + 1])
                        + Math.abs(targetData.data[offset + 2] - savedData.data[offset + 2])
                        + Math.abs(targetData.data[offset + 3] - savedData.data[offset + 3]);
                    if (delta > liveSaveVerifyPixelDelta) {
                        diffPixels += 1;
                        diffData.data[offset] = 220;
                        diffData.data[offset + 1] = 38;
                        diffData.data[offset + 2] = 38;
                        diffData.data[offset + 3] = 255;
                    } else {
                        diffData.data[offset] = savedData.data[offset];
                        diffData.data[offset + 1] = savedData.data[offset + 1];
                        diffData.data[offset + 2] = savedData.data[offset + 2];
                        diffData.data[offset + 3] = Math.max(48, savedData.data[offset + 3]);
                    }
                }
                diffContext.putImageData(diffData, 0, 0);

                return {
                    diffPixels,
                    totalPixels: width * height,
                    mismatchRatio: diffPixels / Math.max(1, width * height),
                    diffCanvas,
                };
            }

            async function verifySavedPdfAgainstTargets(targets, attempt, saveResult = null) {
                if (!Array.isArray(targets) || targets.length === 0) {
                    return { ok: true, pages: [], attempt };
                }

                await new Promise((resolve) => setTimeout(resolve, 300));
                const backendPreviewEntries = getLiveSavePreviewEntries(saveResult);
                const backendPreviewAssets = getLiveSavePreviewAssets(saveResult);
                const renderedPages = await renderSavedPdfVerificationCanvases(targets);
                const pageResults = [];

                for (const target of targets) {
                    const matchingPreviewAssets = backendPreviewAssets.filter((asset) => previewMatchesVerificationTarget(asset?.preview, target));
                    let targetCropRect = target.cropRect;
                    let savedCrop = null;
                    let savedTextSignature = '';
                    let backendPreviewMatched = false;
                    let previewImageMatched = false;
                    let usedBackendPreviewImage = false;

                    if (matchingPreviewAssets.length === 1 && matchingPreviewAssets[0]?.finalImageUrl) {
                        const previewAsset = matchingPreviewAssets[0];
                        const previewCropRect = buildVerificationClipRectFromPreview(target, previewAsset.preview);
                        if (previewCropRect) {
                            targetCropRect = previewCropRect;
                        }
                        usedBackendPreviewImage = true;
                        const targetCrop = cropCanvasRegion(target.fullCanvas, targetCropRect);
                        savedCrop = await loadVerificationImageCanvas(
                            previewAsset.finalImageUrl,
                            targetCrop.width,
                            targetCrop.height
                        );
                        backendPreviewMatched = previewMatchesVerificationTarget(previewAsset?.preview, target);
                        const comparison = compareVerificationCanvases(targetCrop, savedCrop);
                        previewImageMatched = comparison.diffPixels < liveSaveVerifyMinDiffPixels
                            || comparison.mismatchRatio <= liveSaveVerifyMismatchThreshold;
                        const targetTextSignature = normalizeVerificationText(target.targetTextSignature);
                        const compactTargetTextSignature = compactVerificationText(target.targetTextSignature);
                        const compactSavedTextSignature = '';
                        const strictTextMatched = false;
                        const compactTextMatched = false;
                        const textMatched = false;
                        pageResults.push({
                            pageNumber: target.pageNumber,
                            cropRect: targetCropRect,
                            mismatchRatio: comparison.mismatchRatio,
                            diffPixels: comparison.diffPixels,
                            totalPixels: comparison.totalPixels,
                            targetTextSignature,
                            savedTextSignature,
                            compactTargetTextSignature,
                            compactSavedTextSignature,
                            backendPreviewMatched,
                            previewImageMatched,
                            usedBackendPreviewImage,
                            strictTextMatched,
                            compactTextMatched,
                            textMatched,
                            targetCanvas: targetCrop,
                            savedCanvas: savedCrop,
                            diffCanvas: comparison.diffCanvas,
                        });
                        continue;
                    }

                    const savedPage = renderedPages.get(target.pageNumber);
                    if (!savedPage?.canvas) {
                        throw new Error(`Verification render missed page ${target.pageNumber}.`);
                    }
                    const savedCanvas = savedPage.canvas;
                    const targetCrop = cropCanvasRegion(target.fullCanvas, target.cropRect);
                    savedCrop = cropCanvasRegion(savedCanvas, target.cropRect);
                    const comparison = compareVerificationCanvases(targetCrop, savedCrop);
                    backendPreviewMatched = backendPreviewEntries.some((preview) => previewMatchesVerificationTarget(preview, target));
                    const targetTextSignature = normalizeVerificationText(target.targetTextSignature);
                    savedTextSignature = normalizeVerificationText(savedPage.textSignature);
                    const compactTargetTextSignature = compactVerificationText(target.targetTextSignature);
                    const compactSavedTextSignature = compactVerificationText(savedPage.textSignature);
                    const strictTextMatched = targetTextSignature.length > 0
                        && targetTextSignature === savedTextSignature;
                    const compactTextMatched = compactTargetTextSignature.length > 0
                        && (
                            compactTargetTextSignature === compactSavedTextSignature
                            || compactSavedTextSignature.includes(compactTargetTextSignature)
                            || compactTargetTextSignature.includes(compactSavedTextSignature)
                        );
                    const textMatched = backendPreviewMatched
                        || strictTextMatched
                        || (verificationTargetIsSingleLine(target) && compactTextMatched);
                    pageResults.push({
                        pageNumber: target.pageNumber,
                        cropRect: target.cropRect,
                        mismatchRatio: comparison.mismatchRatio,
                        diffPixels: comparison.diffPixels,
                        totalPixels: comparison.totalPixels,
                        targetTextSignature,
                        savedTextSignature,
                        compactTargetTextSignature,
                        compactSavedTextSignature,
                        backendPreviewMatched,
                        previewImageMatched,
                        usedBackendPreviewImage,
                        strictTextMatched,
                        compactTextMatched,
                        textMatched,
                        targetCanvas: targetCrop,
                        savedCanvas: savedCrop,
                        diffCanvas: comparison.diffCanvas,
                    });
                }

                const failingPages = pageResults.filter((result) => {
                    const hasVisualMismatch = result.diffPixels >= liveSaveVerifyMinDiffPixels
                        && result.mismatchRatio > liveSaveVerifyMismatchThreshold;
                    if (!hasVisualMismatch) {
                        return false;
                    }
                    if (result.usedBackendPreviewImage) {
                        return !result.previewImageMatched;
                    }
                    return !result.textMatched;
                });

                window.__lastLiveSaveVerification = {
                    attempt,
                    pages: pageResults.map((result) => ({
                        pageNumber: result.pageNumber,
                        cropRect: result.cropRect,
                        mismatchRatio: result.mismatchRatio,
                        diffPixels: result.diffPixels,
                        totalPixels: result.totalPixels,
                        targetTextSignature: result.targetTextSignature,
                        savedTextSignature: result.savedTextSignature,
                        compactTargetTextSignature: result.compactTargetTextSignature,
                        compactSavedTextSignature: result.compactSavedTextSignature,
                        backendPreviewMatched: result.backendPreviewMatched,
                        strictTextMatched: result.strictTextMatched,
                        compactTextMatched: result.compactTextMatched,
                        textMatched: result.textMatched,
                        targetDataUrl: result.targetCanvas.toDataURL('image/png'),
                        savedDataUrl: result.savedCanvas.toDataURL('image/png'),
                        diffDataUrl: result.diffCanvas.toDataURL('image/png'),
                    })),
                };

                if (failingPages.length === 0) {
                    return { ok: true, attempt, pages: pageResults };
                }

                const worstPage = failingPages.reduce((currentWorst, page) => (
                    !currentWorst || page.mismatchRatio > currentWorst.mismatchRatio ? page : currentWorst
                ), null);

                return {
                    ok: false,
                    attempt,
                    pages: pageResults,
                    message: `Verification mismatch on page ${worstPage.pageNumber} (attempt ${attempt}): ${(worstPage.mismatchRatio * 100).toFixed(2)}% pixel drift in the edited region.`,
                };
            }

            async function saveOverlayEditsWithVerification() {
                const overlayState = snapshotOverlayEditState();
                const targets = await captureLiveSaveVerificationTargets(overlayState);
                if (targets.length === 0) {
                    return saveOverlayEditsIfNeeded(1);
                }
                let lastFailure = null;
                let baseSnapshotToken = null;
                let activeSnapshotToken = null;
                let activeDiscardPreviewEntries = [];

                try {
                    const baseSnapshot = await createWorkingCopySnapshot();
                    baseSnapshotToken = baseSnapshot.snapshot_token;

                    for (let attempt = 1; attempt <= liveSaveVerifyMaxAttempts; attempt += 1) {
                        if (activeSnapshotToken) {
                            await discardWorkingCopySnapshot(activeSnapshotToken, {
                                discardPreviewEntries: activeDiscardPreviewEntries,
                            });
                            activeSnapshotToken = null;
                            activeDiscardPreviewEntries = [];
                        }

                        if (attempt > 1 && baseSnapshotToken) {
                            await restorePdfWorkingCopy(baseSnapshotToken);
                        }

                        const workingCopySnapshot = await createWorkingCopySnapshot();
                        activeSnapshotToken = workingCopySnapshot.snapshot_token;
                        restoreOverlayEditState(overlayState);
                        _liveSavedKeys.clear();

                        setSaveSpinner(true, `Saving PDF... attempt ${attempt}/${liveSaveVerifyMaxAttempts}`);
                        setStatus(`Saving PDF... verifying attempt ${attempt}/${liveSaveVerifyMaxAttempts}`, '');

                        const saveResult = await saveOverlayEditsIfNeeded(attempt, {
                            workingCopyToken: activeSnapshotToken,
                            finalizeLiveSave: false,
                        });
                        if (!saveResult?.saved) {
                            if (activeSnapshotToken) {
                                await discardWorkingCopySnapshot(activeSnapshotToken, {
                                    discardPreviewEntries: activeDiscardPreviewEntries,
                                });
                                activeSnapshotToken = null;
                                activeDiscardPreviewEntries = [];
                            }
                            if (baseSnapshotToken) {
                                await restorePdfWorkingCopy(baseSnapshotToken, {
                                    deleteSnapshot: true,
                                });
                                baseSnapshotToken = null;
                            }
                            return saveResult;
                        }

                        const verification = await verifySavedPdfAgainstTargets(targets, attempt, saveResult);
                        if (verification.ok) {
                            const finalized = await finalizeLiveSaveSession({ workingCopyToken: activeSnapshotToken });
                            try {
                                await discardWorkingCopySnapshot(activeSnapshotToken);
                            } catch (cleanupError) {
                                console.warn('[live-save verify] snapshot cleanup failed', cleanupError);
                            }
                            activeSnapshotToken = null;
                            if (baseSnapshotToken) {
                                try {
                                    await discardWorkingCopySnapshot(baseSnapshotToken);
                                } catch (cleanupError) {
                                    console.warn('[live-save verify] base snapshot cleanup failed', cleanupError);
                                }
                                baseSnapshotToken = null;
                            }
                            return {
                                ...saveResult,
                                ...finalized,
                                verification,
                            };
                        }

                        activeDiscardPreviewEntries.push(...collectLiveSavePreviewEntryIds(saveResult));
                        lastFailure = verification;
                        console.warn('[live-save verify] mismatch', verification);
                    }
                } catch (error) {
                    lastFailure = error;
                }

                if (activeSnapshotToken) {
                    try {
                        await discardWorkingCopySnapshot(activeSnapshotToken, {
                            discardPreviewEntries: activeDiscardPreviewEntries,
                        });
                    } catch (discardError) {
                        console.error('[live-save verify] failed to discard attempt snapshot', discardError);
                    } finally {
                        activeSnapshotToken = null;
                    }
                }
                if (baseSnapshotToken) {
                    try {
                        await restorePdfWorkingCopy(baseSnapshotToken, {
                            deleteSnapshot: true,
                        });
                    } catch (restoreError) {
                        console.error('[live-save verify] failed to restore pre-save PDF snapshot', restoreError);
                    } finally {
                        baseSnapshotToken = null;
                    }
                }
                restoreOverlayEditState(overlayState);
                _liveSavedKeys.clear();
                updateOverlaySaveButton();
                throw new Error(lastFailure?.message || 'Saved PDF did not match the frontend after repeated verification attempts.');
            }

            /**
             * Mark the currently selected overlay field as dirty (changed) so
             * the save button appears.  This is called after style-only changes
             * (bold, italic, underline, color, font, size, etc.) that do NOT
             * move or resize the field.
             */
            function markOverlayFieldDirty(fields = null) {
                const targetFields = Array.isArray(fields) && fields.length
                    ? fields.filter((field) => field && document.body.contains(field))
                    : getOverlayStyleTargets();
                if (!targetFields.length) return;
                const beforeState = snapshotOverlayEditState();

                targetFields.forEach((field) => {
                    const built = buildOverlayEditRecordFromField(field);
                    if (!built) return;
                    overlayEditedFields.set(built.key, built.value);
                });

                persistOverlayEdits();
                updateOverlaySaveButton();
                if (!overlayHistorySnapshotsEqual(beforeState, snapshotOverlayEditState())) {
                    pushUndoState(beforeState);
                }
            }

            function buildOverlayWordStylesForSave(field, fallbackFont, fallbackWeight, fallbackStyle, sourceWords = null, overrideText = null) {
                const blockWords = Array.isArray(sourceWords) ? sourceWords : (Array.isArray(field?._blockWords) ? field._blockWords : []);
                if (!blockWords.length) {
                    return [];
                }

                const normalizeWeightValue = (value, fallback = 400) => {
                    if (value === null || value === undefined || value === '') return fallback;
                    const lower = String(value).toLowerCase().trim();
                    if (lower === 'bold') return 700;
                    if (lower === 'normal') return 400;
                    const parsed = parseInt(lower, 10);
                    return Number.isFinite(parsed) ? parsed : fallback;
                };

                const resolvedFont = field.dataset.fontFamily || field.dataset.font || fallbackFont || 'Helvetica';
                const resolvedStyle = field.dataset.fontStyle || fallbackStyle || 'normal';
                const resolvedWeight = normalizeWeightValue(field.dataset.fontWeight || fallbackWeight, 400);
                const currentColor = (field.dataset.textColor || '').trim();
                const originalColor = (field.dataset.originalTextColor || currentColor || '#000000').trim();
                const hasFontOverride = !!field.dataset.fontFamily && field.dataset.fontFamily !== field.dataset.font;
                const hasWeightOverride = resolvedWeight !== normalizeWeightValue(field.dataset.originalFontWeight || fallbackWeight, 400);
                const hasStyleOverride = resolvedStyle !== (field.dataset.originalFontStyle || fallbackStyle || 'normal');
                const hasColorOverride = currentColor && currentColor.toLowerCase() !== originalColor.toLowerCase();
                const hasUnderlineOverride = field.dataset.underline === 'true';
                const cleanText = (value) => String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                const getWordBounds = (words) => {
                    if (!Array.isArray(words) || !words.length) return null;
                    let minLeft = Infinity;
                    let minTop = Infinity;
                    let maxRight = -Infinity;
                    let maxBottom = -Infinity;
                    let maxOriginY = -Infinity;
                    words.forEach((word) => {
                        const left = Number(word?.left) || 0;
                        const top = Number(word?.top) || 0;
                        const width = Number(word?.width) || 0;
                        const height = Number(word?.height) || 0;
                        minLeft = Math.min(minLeft, left);
                        minTop = Math.min(minTop, top);
                        maxRight = Math.max(maxRight, left + width);
                        maxBottom = Math.max(maxBottom, top + height);
                        maxOriginY = Math.max(maxOriginY, Number(word?.origin_y) || (top + height));
                    });
                    if (!Number.isFinite(minLeft) || !Number.isFinite(minTop) || !Number.isFinite(maxRight) || !Number.isFinite(maxBottom)) {
                        return null;
                    }
                    return {
                        left: minLeft,
                        top: minTop,
                        width: Math.max(1, maxRight - minLeft),
                        height: Math.max(1, maxBottom - minTop),
                        origin_y: Number.isFinite(maxOriginY) ? maxOriginY : maxBottom,
                    };
                };
                const groupWordsByVisualLine = (words) => {
                    const sortedWords = [...words].sort((a, b) => ((Number(a.top) || 0) - (Number(b.top) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)));
                    const groups = [];
                    sortedWords.forEach((word) => {
                        const wordTop = Number(word?.top) || 0;
                        const wordHeight = Number(word?.height) || 0;
                        const wordBottom = wordTop + wordHeight;
                        let targetGroup = groups.find((group) => {
                            const groupTop = group.top;
                            const groupBottom = group.bottom;
                            const inter = Math.max(0, Math.min(groupBottom, wordBottom) - Math.max(groupTop, wordTop));
                            const minHeight = Math.max(1, Math.min(groupBottom - groupTop, wordHeight));
                            return (inter / minHeight) >= 0.35;
                        });
                        if (!targetGroup) {
                            targetGroup = {
                                words: [],
                                top: wordTop,
                                bottom: wordBottom,
                            };
                            groups.push(targetGroup);
                        } else {
                            targetGroup.top = Math.min(targetGroup.top, wordTop);
                            targetGroup.bottom = Math.max(targetGroup.bottom, wordBottom);
                        }
                        targetGroup.words.push(word);
                    });
                    return groups
                        .map((group) => ({
                            words: group.words.sort((a, b) => ((Number(a.left) || 0) - (Number(b.left) || 0))),
                            bounds: getWordBounds(group.words),
                        }))
                        .filter((group) => group.words.length > 0 && group.bounds);
                };
                const currentEditor = field?.querySelector?.('[contenteditable]');
                const currentText = cleanText(
                    overrideText !== null && overrideText !== undefined
                        ? overrideText
                        : (currentEditor ? getOverlayExplicitText(currentEditor) : getOverlayExplicitText(field))
                );
                const currentLines = currentText
                    .split('\n')
                    .map((line) => line.trim())
                    .filter((line) => line.length > 0);
                const visualLineGroups = groupWordsByVisualLine(blockWords);
                const normalizeComparableText = (value) => cleanText(value).replace(/\s+/g, ' ').trim();
                const visualLineTexts = visualLineGroups.map((group) => group.words
                    .map((word) => cleanText(word?.text || '').trim())
                    .filter((text) => text.length > 0)
                    .join(' ')
                    .trim()
                ).filter((line) => line.length > 0);
                const sourceText = visualLineTexts.join('\n');
                const textChanged = normalizeComparableText(currentText) !== normalizeComparableText(sourceText);

                // For multiline text edits, the original per-word geometry is no longer a
                // reliable save primitive. Force the backend onto line-metric replay so the
                // paragraph keeps its original line spacing instead of collapsing into
                // origin-based styled runs.
                if (visualLineGroups.length > 1 && textChanged) {
                    return [];
                }

                if (visualLineGroups.length > 0 && currentLines.length === visualLineGroups.length) {
                    return visualLineGroups.map((group, index) => {
                        const styleWord = [...group.words].sort((a, b) => ((Number(b.font_size) || 0) - (Number(a.font_size) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)))[0];
                        const originalWeight = normalizeWeightValue(styleWord.font_weight, styleWord.bold ? 700 : 400);
                        const originalColorHex = (styleWord.hex_color || currentColor || '#000000').trim();

                        return {
                            text: currentLines[index],
                            font: hasFontOverride ? resolvedFont : (styleWord.font || fallbackFont || 'Helvetica'),
                            font_xref: hasFontOverride ? null : (styleWord.font_xref || null),
                            font_size: styleWord.font_size,
                            font_weight: hasWeightOverride ? resolvedWeight : originalWeight,
                            italic: hasStyleOverride ? (resolvedStyle === 'italic') : !!styleWord.italic,
                            bold: hasWeightOverride ? (resolvedWeight >= 700) : !!styleWord.bold,
                            underline: hasUnderlineOverride ? true : !!styleWord.underline,
                            color: hasColorOverride ? currentColor : (styleWord.color ?? null),
                            hex_color: hasColorOverride ? currentColor : (originalColorHex || '#000000'),
                            left: group.bounds.left,
                            top: group.bounds.top,
                            width: group.bounds.width,
                            height: group.bounds.height,
                            origin_x: group.bounds.left,
                            origin_y: group.bounds.origin_y,
                            ascender: styleWord.ascender,
                            descender: styleWord.descender,
                        };
                    });
                }

                return blockWords.map((w) => {
                    const originalWeight = normalizeWeightValue(w.font_weight, w.bold ? 700 : 400);
                    const originalColorHex = (w.hex_color || currentColor || '#000000').trim();

                    return {
                        text: w.text,
                        font: hasFontOverride ? resolvedFont : (w.font || fallbackFont || 'Helvetica'),
                        font_xref: hasFontOverride ? null : (w.font_xref || null),
                        font_size: w.font_size,
                        font_weight: hasWeightOverride ? resolvedWeight : originalWeight,
                        italic: hasStyleOverride ? (resolvedStyle === 'italic') : !!w.italic,
                        bold: hasWeightOverride ? (resolvedWeight >= 700) : !!w.bold,
                        underline: hasUnderlineOverride ? true : !!w.underline,
                        color: hasColorOverride ? currentColor : (w.color ?? null),
                        hex_color: hasColorOverride ? currentColor : (originalColorHex || '#000000'),
                        left: w.left,
                        top: w.top,
                        width: w.width,
                        height: w.height,
                        origin_x: w.origin_x,
                        origin_y: w.origin_y,
                        ascender: w.ascender,
                        descender: w.descender,
                    };
                });
            }

            function buildOverlayLineMetricsForSave(field, fallbackFont, fallbackWeight, fallbackStyle, sourceWords = null) {
                const blockWords = Array.isArray(sourceWords) ? sourceWords : (Array.isArray(field?._blockWords) ? field._blockWords : []);
                if (!blockWords.length) {
                    return [];
                }
                const sourceBlock = field?._overlaySourceBlock || null;

                const normalizeWeightValue = (value, fallback = 400) => {
                    if (value === null || value === undefined || value === '') return fallback;
                    const lower = String(value).toLowerCase().trim();
                    if (lower === 'bold') return 700;
                    if (lower === 'normal') return 400;
                    const parsed = parseInt(lower, 10);
                    return Number.isFinite(parsed) ? parsed : fallback;
                };

                const resolvedFont = field.dataset.fontFamily || field.dataset.font || fallbackFont || 'Helvetica';
                const resolvedStyle = field.dataset.fontStyle || fallbackStyle || 'normal';
                const resolvedWeight = normalizeWeightValue(field.dataset.fontWeight || fallbackWeight, 400);
                const currentColor = (field.dataset.textColor || '').trim();
                const originalColor = (field.dataset.originalTextColor || currentColor || '#000000').trim();
                const hasFontOverride = !!field.dataset.fontFamily && field.dataset.fontFamily !== field.dataset.font;
                const hasWeightOverride = resolvedWeight !== normalizeWeightValue(field.dataset.originalFontWeight || fallbackWeight, 400);
                const hasStyleOverride = resolvedStyle !== (field.dataset.originalFontStyle || fallbackStyle || 'normal');
                const hasColorOverride = currentColor && currentColor.toLowerCase() !== originalColor.toLowerCase();
                const hasUnderlineOverride = field.dataset.underline === 'true';
                const cleanText = (value) => String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                const currentText = cleanText(getOverlayExplicitText(field?.querySelector?.('[contenteditable]') || field));
                const currentLines = currentText
                    .split('\n')
                    .map((line) => cleanText(line).trim());
                const getWordBounds = (words) => {
                    if (!Array.isArray(words) || !words.length) return null;
                    let minLeft = Infinity;
                    let minTop = Infinity;
                    let maxRight = -Infinity;
                    let maxBottom = -Infinity;
                    let maxOriginY = -Infinity;
                    words.forEach((word) => {
                        const left = Number(word?.left) || 0;
                        const top = Number(word?.top) || 0;
                        const width = Number(word?.width) || 0;
                        const height = Number(word?.height) || 0;
                        minLeft = Math.min(minLeft, left);
                        minTop = Math.min(minTop, top);
                        maxRight = Math.max(maxRight, left + width);
                        maxBottom = Math.max(maxBottom, top + height);
                        maxOriginY = Math.max(maxOriginY, Number(word?.origin_y) || (top + height));
                    });
                    if (!Number.isFinite(minLeft) || !Number.isFinite(minTop) || !Number.isFinite(maxRight) || !Number.isFinite(maxBottom)) {
                        return null;
                    }
                    return {
                        left: minLeft,
                        top: minTop,
                        width: Math.max(1, maxRight - minLeft),
                        height: Math.max(1, maxBottom - minTop),
                        origin_y: Number.isFinite(maxOriginY) ? maxOriginY : maxBottom,
                    };
                };
                const groupWordsByVisualLine = (words) => {
                    const sortedWords = [...words].sort((a, b) => ((Number(a.top) || 0) - (Number(b.top) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)));
                    const groups = [];
                    sortedWords.forEach((word) => {
                        const wordTop = Number(word?.top) || 0;
                        const wordHeight = Number(word?.height) || 0;
                        const wordBottom = wordTop + wordHeight;
                        let targetGroup = groups.find((group) => {
                            const groupTop = group.top;
                            const groupBottom = group.bottom;
                            const inter = Math.max(0, Math.min(groupBottom, wordBottom) - Math.max(groupTop, wordTop));
                            const minHeight = Math.max(1, Math.min(groupBottom - groupTop, wordHeight));
                            return (inter / minHeight) >= 0.35;
                        });
                        if (!targetGroup) {
                            targetGroup = {
                                words: [],
                                top: wordTop,
                                bottom: wordBottom,
                            };
                            groups.push(targetGroup);
                        } else {
                            targetGroup.top = Math.min(targetGroup.top, wordTop);
                            targetGroup.bottom = Math.max(targetGroup.bottom, wordBottom);
                        }
                        targetGroup.words.push(word);
                    });
                    return groups
                        .map((group) => ({
                            words: group.words.sort((a, b) => ((Number(a.left) || 0) - (Number(b.left) || 0))),
                            bounds: getWordBounds(group.words),
                        }))
                        .filter((group) => group.words.length > 0 && group.bounds);
                };
                const sourceLineBBoxes = Array.isArray(sourceBlock?.line_bboxes)
                    ? sourceBlock.line_bboxes
                        .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        .map((bbox) => bbox.map((value) => Number(value) || 0))
                    : [];
                if (sourceLineBBoxes.length > 1 && currentLines.length === sourceLineBBoxes.length) {
                    const verticalOverlapRatio = (topA, bottomA, topB, bottomB) => {
                        const inter = Math.max(0, Math.min(bottomA, bottomB) - Math.max(topA, topB));
                        const minHeight = Math.max(1, Math.min(bottomA - topA, bottomB - topB));
                        return inter / minHeight;
                    };
                    const defaultStyleWord = [...blockWords].sort((a, b) => ((Number(b.font_size) || 0) - (Number(a.font_size) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)))[0];

                    return sourceLineBBoxes.map((bbox, index) => {
                        const [left, top, right, bottom] = bbox;
                        const lineWords = blockWords
                            .filter((word) => {
                                const wordTop = Number(word?.top) || 0;
                                const wordBottom = wordTop + (Number(word?.height) || 0);
                                return verticalOverlapRatio(wordTop, wordBottom, top, bottom) >= 0.35;
                            })
                            .sort((a, b) => ((Number(a.left) || 0) - (Number(b.left) || 0)));
                        const styleWord = lineWords[0] || defaultStyleWord;
                        const originalWeight = normalizeWeightValue(styleWord?.font_weight, styleWord?.bold ? 700 : 400);
                        const originalColorHex = (styleWord?.hex_color || currentColor || '#000000').trim();
                        const originY = lineWords.length > 0
                            ? Math.max(...lineWords.map((word) => Number(word?.origin_y) || (Number(word?.top) || 0) + (Number(word?.height) || 0)))
                            : bottom;

                        return {
                            text: currentLines[index] || '',
                            font: hasFontOverride ? resolvedFont : (styleWord?.font || fallbackFont || 'Helvetica'),
                            font_xref: hasFontOverride ? null : (styleWord?.font_xref || null),
                            font_size: styleWord?.font_size || Number(field.dataset.fontSize) || 12,
                            font_weight: hasWeightOverride ? resolvedWeight : originalWeight,
                            italic: hasStyleOverride ? (resolvedStyle === 'italic') : !!styleWord?.italic,
                            bold: hasWeightOverride ? (resolvedWeight >= 700) : !!styleWord?.bold,
                            underline: hasUnderlineOverride ? true : !!styleWord?.underline,
                            color: hasColorOverride ? currentColor : (styleWord?.color ?? null),
                            hex_color: hasColorOverride ? currentColor : (originalColorHex || '#000000'),
                            left,
                            top,
                            width: Math.max(1, right - left),
                            height: Math.max(1, bottom - top),
                            origin_x: left,
                            origin_y: originY,
                            ascender: styleWord?.ascender,
                            descender: styleWord?.descender,
                        };
                    });
                }

                return groupWordsByVisualLine(blockWords).map((group) => {
                    const styleWord = [...group.words].sort((a, b) => ((Number(b.font_size) || 0) - (Number(a.font_size) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)))[0];
                    const originalWeight = normalizeWeightValue(styleWord.font_weight, styleWord.bold ? 700 : 400);
                    const originalColorHex = (styleWord.hex_color || currentColor || '#000000').trim();
                    const lineText = group.words
                        .map((word) => cleanText(word?.text || '').trim())
                        .filter((text) => text.length > 0)
                        .join(' ')
                        .trim();

                    return {
                        text: lineText,
                        font: hasFontOverride ? resolvedFont : (styleWord.font || fallbackFont || 'Helvetica'),
                        font_xref: hasFontOverride ? null : (styleWord.font_xref || null),
                        font_size: styleWord.font_size,
                        font_weight: hasWeightOverride ? resolvedWeight : originalWeight,
                        italic: hasStyleOverride ? (resolvedStyle === 'italic') : !!styleWord.italic,
                        bold: hasWeightOverride ? (resolvedWeight >= 700) : !!styleWord.bold,
                        underline: hasUnderlineOverride ? true : !!styleWord.underline,
                        color: hasColorOverride ? currentColor : (styleWord.color ?? null),
                        hex_color: hasColorOverride ? currentColor : (originalColorHex || '#000000'),
                        left: group.bounds.left,
                        top: group.bounds.top,
                        width: group.bounds.width,
                        height: group.bounds.height,
                        origin_x: group.bounds.left,
                        origin_y: group.bounds.origin_y,
                        ascender: styleWord.ascender,
                        descender: styleWord.descender,
                    };
                });
            }

            function shouldConvertOverlayWordsToSyntheticTextbox(field, currentText = null, sourceWords = null, originalText = null) {
                const blockWords = Array.isArray(sourceWords) ? sourceWords : (Array.isArray(field?._blockWords) ? field._blockWords : []);
                if (blockWords.length < 2) {
                    return false;
                }

                const normalizeWeightValue = (value, fallback = 400) => {
                    if (value === null || value === undefined || value === '') return fallback;
                    const lower = String(value).toLowerCase().trim();
                    if (lower === 'bold') return 700;
                    if (lower === 'normal') return 400;
                    const parsed = parseInt(lower, 10);
                    return Number.isFinite(parsed) ? parsed : fallback;
                };
                const normalizeComparableText = (value) => String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();

                const currentNorm = normalizeComparableText(
                    currentText !== null && currentText !== undefined
                        ? currentText
                        : getOverlayExplicitText(field?.querySelector?.('[contenteditable]') || field)
                );
                const originalNorm = normalizeComparableText(
                    originalText !== null && originalText !== undefined
                        ? originalText
                        : (field?.dataset?.originalText || '')
                );
                if (!currentNorm || currentNorm === originalNorm) {
                    return false;
                }

                const uniqueLinePositions = new Set(
                    blockWords.map((word) => Math.round((Number(word?.top) || 0) * 2) / 2)
                );
                if (uniqueLinePositions.size < 2) {
                    return false;
                }

                const styleSignatures = new Set(
                    blockWords.map((word) => {
                        const weight = normalizeWeightValue(word?.font_weight, word?.bold ? 700 : 400);
                        return [
                            String(word?.font || ''),
                            Number(word?.font_size || 0).toFixed(2),
                            String(weight),
                            String(!!word?.italic),
                            String(!!word?.bold),
                        ].join('|');
                    })
                );

                return styleSignatures.size > 1;
            }

            function buildSyntheticTextboxText(field, currentText = null, sourceWords = null, originalText = null) {
                const blockWords = Array.isArray(sourceWords) ? sourceWords : (Array.isArray(field?._blockWords) ? field._blockWords : []);
                const block = field?._overlaySourceBlock || null;
                const cleanText = (value) => String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                const normalizeComparableText = (value) => cleanText(value).replace(/\s+/g, ' ').trim();
                const originalLines = Array.isArray(block?.text_lines) && block.text_lines.length
                    ? block.text_lines.map((line) => cleanText(line).trim()).filter((line) => line.length > 0)
                    : [];
                const currentRaw = cleanText(
                    currentText !== null && currentText !== undefined
                        ? currentText
                        : getOverlayExplicitText(field?.querySelector?.('[contenteditable]') || field)
                );
                const originalRaw = cleanText(
                    originalText !== null && originalText !== undefined
                        ? originalText
                        : (field?.dataset?.originalText || '')
                );

                if (!originalLines.length) {
                    return currentRaw;
                }

                const currentNorm = normalizeComparableText(currentRaw);
                const originalNorm = normalizeComparableText(originalRaw || originalLines.join('\n'));
                if (!currentNorm || !originalNorm) {
                    return currentRaw;
                }

                if (currentNorm === originalNorm) {
                    return originalLines.join('\n');
                }

                if (currentNorm.startsWith(originalNorm)) {
                    const suffix = currentNorm.slice(originalNorm.length).trim();
                    if (suffix.length > 0) {
                        const rebuilt = [...originalLines];
                        rebuilt[rebuilt.length - 1] = `${rebuilt[rebuilt.length - 1]} ${suffix}`.trim();
                        return rebuilt.join('\n');
                    }
                }

                return currentRaw;
            }

            function buildOverlaySourceSegmentEditsForSave(field, editData) {
                const sourceSegments = Array.isArray(field?._overlaySaveSegments)
                    ? field._overlaySaveSegments.filter((segment) => segment && Array.isArray(segment.bbox) && segment.bbox.length >= 4)
                    : [];
                if (sourceSegments.length < 2) {
                    return null;
                }

                const cleanText = (value) => String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n');
                const normalizeComparableText = (value) => String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();

                const fullOriginalText = normalizeComparableText(editData?.original_text || field?.dataset?.originalText || '');
                const editedText = String(editData?.new_text || '');
                const editedTextNorm = normalizeComparableText(editedText);
                const editedLinesRaw = cleanText(editedText)
                    .split('\n')
                    .map((line) => cleanText(line));
                const editedNonEmptyLines = editedLinesRaw.filter((line) => line.trim().length > 0);
                const lineMetrics = Array.isArray(editData?.line_metrics) ? editData.line_metrics : [];
                if (!editedTextNorm || editedTextNorm === fullOriginalText) {
                    return null;
                }

                // Distribute the edited text to each source segment proportionally by
                // the original line count of each segment. This ensures the new text for
                // each segment is only the portion that belongs to it, preventing the
                // full merged-field text from being written into a single segment's
                // smaller bbox (which caused text duplication / overflow artifacts).
                const segmentLineCounts = sourceSegments.map(
                    (s) => Math.max(1, Array.isArray(s.text_lines) ? s.text_lines.length : 0)
                );
                const totalOriginalLines = segmentLineCounts.reduce((a, b) => a + b, 0);
                let computedSegmentNewTexts = null;
                const preserveAtomicParagraphEdit = (
                    lineMetrics.length > 1
                    && editedNonEmptyLines.length === totalOriginalLines
                );

                // Keep full multiline paragraph replacements atomic. Splitting these
                // back into source segments causes partial live-save patches such as
                // "first line only" + "remaining lines", which corrupts paragraph
                // spacing and leaves original text fragments behind.
                if (preserveAtomicParagraphEdit) {
                    return null;
                }

                // Prefer paragraph-boundary splits when the editor introduces blank
                // separator lines between vertically merged source segments.
                const editedParagraphs = cleanText(editedText)
                    .split(/\n\s*\n+/)
                    .map((paragraph) => paragraph
                        .split('\n')
                        .map((line) => cleanText(line))
                        .filter((line) => line.trim().length > 0)
                        .join('\n')
                        .trim())
                    .filter((paragraph) => paragraph.length > 0);
                if (editedParagraphs.length === sourceSegments.length) {
                    computedSegmentNewTexts = editedParagraphs;
                }

                if (!computedSegmentNewTexts) {
                    // Only proceed with per-segment line-based splitting when the
                    // effective line count is preserved. Blank separator lines
                    // between source paragraphs are ignored.
                    if (editedNonEmptyLines.length === totalOriginalLines) {
                        let lineOffset = 0;
                        computedSegmentNewTexts = segmentLineCounts.map((count) => {
                            const lines = editedNonEmptyLines.slice(lineOffset, lineOffset + count);
                            lineOffset += count;
                            return lines.join('\n').trim();
                        });
                    }
                }

                if (!computedSegmentNewTexts) {
                    const matchIndexes = sourceSegments
                        .map((segment, index) => {
                            const segmentNorm = normalizeComparableText(String(segment.text || ''));
                            if (!segmentNorm) {
                                return null;
                            }
                            const prefix = segmentNorm.slice(0, Math.min(segmentNorm.length, 96));
                            const suffix = segmentNorm.slice(Math.max(0, segmentNorm.length - 96));
                            const likelyMatch =
                                editedTextNorm === segmentNorm
                                || editedTextNorm.startsWith(segmentNorm)
                                || segmentNorm.startsWith(editedTextNorm)
                                || (prefix.length >= 24 && editedTextNorm.includes(prefix))
                                || (suffix.length >= 24 && editedTextNorm.includes(suffix));
                            return likelyMatch ? index : null;
                        })
                        .filter((index) => index !== null);

                    if (matchIndexes.length === 1) {
                        const matchedIndex = matchIndexes[0];
                        computedSegmentNewTexts = sourceSegments.map((segment, index) => (
                            index === matchedIndex
                                ? editedText.trim()
                                : String(segment.text || '')
                        ));
                    }
                }

                if (!computedSegmentNewTexts) {
                    return null;
                }

                // Bail out without generating any edits when nothing actually changed.
                const anySegmentChanged = sourceSegments.some((segment, index) =>
                    normalizeComparableText(String(segment.text || '')) !==
                    normalizeComparableText(computedSegmentNewTexts[index] || '')
                );
                if (!anySegmentChanged) {
                    return null;
                }

                const resolvedFont = editData.font || field.dataset.fontFamily || field.dataset.font || 'Helvetica';
                const resolvedWeight = editData.font_weight || field.dataset.fontWeight || field.style.fontWeight || '400';
                const resolvedStyle = editData.font_style || field.dataset.fontStyle || field.style.fontStyle || 'normal';

                return sourceSegments.map((segment, index) => {
                    const segmentText = String(segment.text || '');
                    const segmentNewText = computedSegmentNewTexts[index];
                    const isChanged = normalizeComparableText(segmentText) !== normalizeComparableText(segmentNewText);

                    const segmentBbox = [
                        Number(segment.bbox[0]) || 0,
                        Number(segment.bbox[1]) || 0,
                        Number(segment.bbox[2]) || 0,
                        Number(segment.bbox[3]) || 0,
                    ];
                    const segmentWords = Array.isArray(segment.words) ? segment.words : [];
                    const segmentWordStyles = buildOverlayWordStylesForSave(
                        field,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segmentWords,
                        isChanged ? segmentNewText : segmentText
                    );
                    const segmentLineMetrics = buildOverlayLineMetricsForSave(
                        field,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segmentWords
                    );
                    const syntheticTextbox = shouldConvertOverlayWordsToSyntheticTextbox(
                        field,
                        segmentNewText,
                        segmentWords,
                        segmentText
                    );
                    const effectiveSegmentText = isChanged
                        ? (
                            syntheticTextbox
                                ? buildSyntheticTextboxText(field, segmentNewText, segmentWords, segmentText)
                                : segmentNewText
                        )
                        : segmentText;

                    return {
                        ...editData,
                        block_num: segment.block_num ?? editData.block_num,
                        original_text: segmentText,
                        new_text: effectiveSegmentText,
                        bbox: segmentBbox,
                        original_bbox: segmentBbox,
                        origin_x: segmentBbox[0],
                        origin_y: segmentBbox[3],
                        preserve_partial_block: false,
                        force_reinsert: !!editData.force_reinsert || !isChanged,
                        cleanup_group_bbox: Array.isArray(editData.original_bbox) && editData.original_bbox.length >= 4
                            ? [...editData.original_bbox]
                            : null,
                        word_styles: (isChanged && syntheticTextbox) ? null : (segmentWordStyles.length > 0 ? segmentWordStyles : null),
                        line_metrics: segmentLineMetrics.length > 0 ? segmentLineMetrics : null,
                        rich_html: null,
                        synthetic_textbox: !!(isChanged && syntheticTextbox),
                        paragraph_bbox: [...segmentBbox],
                        source_content_ops: dedupeOverlaySourceContentOps(
                            (Array.isArray(segment.source_content_ops) ? segment.source_content_ops : [])
                                .concat(segmentWords.flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : []))
                        ),
                    };
                });
            }

            function buildOverlayTableRowClusterEditsForSave(field, editData) {
                const rowCluster = Array.isArray(field?._overlayTableRowCluster)
                    ? field._overlayTableRowCluster.filter((segment) => segment && Array.isArray(segment.bbox) && segment.bbox.length >= 4)
                    : [];
                if (rowCluster.length < 2) {
                    return null;
                }

                const currentKey = String(field?.dataset?.wordIndex || '');
                if (!currentKey) {
                    return null;
                }

                const normalizeComparableText = (value) => String(value ?? '')
                    .replace(/\r\n/g, '\n')
                    .replace(/\r/g, '\n')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();

                const editedClusterKeys = rowCluster
                    .map((segment) => String(segment.key || ''))
                    .filter((key) => key && overlayEditedFields.has(key))
                    .sort();
                const leaderKey = editedClusterKeys.length > 0 ? editedClusterKeys[0] : currentKey;
                if (leaderKey !== currentKey) {
                    return [];
                }

                return rowCluster.map((segment) => {
                    const segmentKey = String(segment.key || '');
                    const siblingField = segmentKey
                        ? document.querySelector(`.overlay-field[data-word-index="${segmentKey}"]`)
                        : null;
                    const siblingEdit = segmentKey ? overlayEditedFields.get(segmentKey) : null;
                    const segmentText = String(segment.text || '');
                    const segmentNewText = siblingEdit
                        ? String(siblingEdit.new_text || '')
                        : (segmentKey === currentKey
                            ? String(editData?.new_text || '')
                            : segmentText);
                    const isChanged = normalizeComparableText(segmentText) !== normalizeComparableText(segmentNewText);
                    const resolvedFont = segment.font || editData.font || field.dataset.fontFamily || field.dataset.font || 'Helvetica';
                    const resolvedWeight = segment.font_weight || editData.font_weight || field.dataset.fontWeight || field.style.fontWeight || '400';
                    const resolvedStyle = segment.font_style || editData.font_style || field.dataset.fontStyle || field.style.fontStyle || 'normal';
                    const styleField = siblingField || field;
                    const syntheticTextbox = isChanged && shouldConvertOverlayWordsToSyntheticTextbox(
                        styleField,
                        segmentNewText,
                        segment.words,
                        segmentText
                    );
                    const effectiveSegmentText = isChanged
                        ? (
                            syntheticTextbox
                                ? buildSyntheticTextboxText(styleField, segmentNewText, segment.words, segmentText)
                                : segmentNewText
                        )
                        : segmentText;
                    const segmentWordStyles = buildOverlayWordStylesForSave(
                        styleField,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segment.words,
                        effectiveSegmentText
                    );
                    const segmentLineMetrics = buildOverlayLineMetricsForSave(
                        styleField,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segment.words
                    );

                    return {
                        ...editData,
                        page_number: editData.page_number,
                        block_num: segment.block_num ?? editData.block_num,
                        original_text: segmentText,
                        new_text: effectiveSegmentText,
                        bbox: [...segment.bbox],
                        original_bbox: [...segment.bbox],
                        origin_x: Number(segment.bbox[0]) || 0,
                        origin_y: Number(segment.bbox[3]) || 0,
                        font: resolvedFont,
                        font_size: Number(segment.font_size) || Number(editData.font_size) || 12,
                        font_weight: String(resolvedWeight),
                        font_style: resolvedStyle,
                        font_xref: segment.font_xref ?? editData.font_xref ?? null,
                        line_height: segment.line_height || editData.line_height || null,
                        color: segment.color || editData.color || '#000000',
                        preserve_partial_block: false,
                        force_reinsert: true,
                        table_row_cluster_rebuild: true,
                        cleanup_group_bbox: Array.isArray(segment.bbox) ? [...segment.bbox] : null,
                        word_styles: syntheticTextbox ? null : (segmentWordStyles.length > 0 ? segmentWordStyles : null),
                        line_metrics: segmentLineMetrics.length > 0 ? segmentLineMetrics : null,
                        rich_html: null,
                        synthetic_textbox: !!syntheticTextbox,
                        paragraph_bbox: [...segment.bbox],
                        source_content_ops: dedupeOverlaySourceContentOps(
                            (Array.isArray(segment.source_content_ops) ? segment.source_content_ops : [])
                                .concat(Array.isArray(segment.words) ? segment.words.flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : []) : [])
                        ),
                    };
                });
            }

            function buildOverlaySegmentEditsForSave(field, editData) {
                const sourceSegmentEdits = buildOverlaySourceSegmentEditsForSave(field, editData);
                if (Array.isArray(sourceSegmentEdits) && sourceSegmentEdits.length > 0) {
                    return sourceSegmentEdits;
                }

                const block = field?._overlaySourceBlock;
                const blockWords = Array.isArray(field?._blockWords) ? field._blockWords : [];
                const lineBBoxes = Array.isArray(block?.line_bboxes) ? block.line_bboxes : [];
                const textLines = Array.isArray(block?.text_lines) ? block.text_lines : [];
                const cleanText = (value) => String(value ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
                const localVerticalOverlapRatio = (topA, bottomA, topB, bottomB) => {
                    const inter = Math.max(0, Math.min(bottomA, bottomB) - Math.max(topA, topB));
                    const minHeight = Math.max(1, Math.min(bottomA - topA, bottomB - topB));
                    return inter / minHeight;
                };
                const localGetWordBounds = (words) => {
                    if (!Array.isArray(words) || !words.length) return null;
                    let minLeft = Infinity;
                    let minTop = Infinity;
                    let maxRight = -Infinity;
                    let maxBottom = -Infinity;
                    words.forEach((word) => {
                        const left = Number(word?.left) || 0;
                        const top = Number(word?.top) || 0;
                        const width = Number(word?.width) || 0;
                        const height = Number(word?.height) || 0;
                        minLeft = Math.min(minLeft, left);
                        minTop = Math.min(minTop, top);
                        maxRight = Math.max(maxRight, left + width);
                        maxBottom = Math.max(maxBottom, top + height);
                    });
                    if (!Number.isFinite(minLeft) || !Number.isFinite(minTop) || !Number.isFinite(maxRight) || !Number.isFinite(maxBottom)) {
                        return null;
                    }
                    return {
                        left: minLeft,
                        top: minTop,
                        width: Math.max(1, maxRight - minLeft),
                        height: Math.max(1, maxBottom - minTop),
                    };
                };
                if (!block || blockWords.length === 0 || lineBBoxes.length < 2 || textLines.length !== lineBBoxes.length) {
                    return [editData];
                }

                const explicitNewLines = cleanText(editData?.new_text || '')
                    .split('\n')
                    .filter((line) => line.trim().length > 0);
                const lineMetrics = Array.isArray(editData?.line_metrics) ? editData.line_metrics : [];
                if (lineMetrics.length > 1 && explicitNewLines.length === lineBBoxes.length) {
                    return [editData];
                }

                const lineEntries = lineBBoxes.map((lb, idx) => {
                    const left = Number(lb?.[0]) || 0;
                    const top = Number(lb?.[1]) || 0;
                    const right = Number(lb?.[2]) || left;
                    const bottom = Number(lb?.[3]) || top;
                    return {
                        idx,
                        left,
                        top,
                        right,
                        bottom,
                        height: Math.max(1, bottom - top),
                        text: cleanText(textLines[idx] || ''),
                    };
                }).sort((a, b) => a.top - b.top || a.left - b.left);

                const sortedHeights = lineEntries.map((line) => line.height).sort((a, b) => a - b);
                const medianHeight = sortedHeights.length
                    ? sortedHeights[Math.floor(sortedHeights.length / 2)]
                    : 12;
                const segmentGapThreshold = Math.max(6, Math.min(18, medianHeight * 0.6));

                const segments = [];
                let currentSegment = [lineEntries[0]];
                for (let i = 1; i < lineEntries.length; i++) {
                    const prev = lineEntries[i - 1];
                    const line = lineEntries[i];
                    const gap = line.top - prev.bottom;
                    if (gap > segmentGapThreshold) {
                        segments.push(currentSegment);
                        currentSegment = [line];
                    } else {
                        currentSegment.push(line);
                    }
                }
                if (currentSegment.length) {
                    segments.push(currentSegment);
                }

                if (segments.length < 2) {
                    return [editData];
                }

                const newLines = String(editData?.new_text || '').split('\n');
                const originalLineTotal = segments.reduce((sum, segment) => sum + segment.length, 0);
                if (newLines.length !== originalLineTotal) {
                    return [editData];
                }

                const resolvedFont = editData.font || field.dataset.fontFamily || field.dataset.font || block.font || 'Helvetica';
                const resolvedWeight = editData.font_weight || field.dataset.fontWeight || field.style.fontWeight || '400';
                const resolvedStyle = editData.font_style || field.dataset.fontStyle || field.style.fontStyle || 'normal';
                let lineCursor = 0;
                const splitIntoMinimalLineEdits = [];

                const segmentEdits = segments.map((segment, segmentIndex) => {
                    const segmentLines = newLines.slice(lineCursor, lineCursor + segment.length);
                    lineCursor += segment.length;

                    const segTop = Math.min(...segment.map((line) => line.top));
                    const segBottom = Math.max(...segment.map((line) => line.bottom));
                    const segWords = blockWords
                        .filter((word) => {
                            const wTop = Number(word?.top) || 0;
                            const wBottom = wTop + (Number(word?.height) || 0);
                            return segment.some((line) => localVerticalOverlapRatio(wTop, wBottom, line.top, line.bottom) >= 0.35);
                        })
                        .sort((a, b) => ((Number(a.top) || 0) - (Number(b.top) || 0)) || ((Number(a.left) || 0) - (Number(b.left) || 0)));

                    if (!segWords.length) {
                        return null;
                    }

                    const wordBounds = localGetWordBounds(segWords);
                    if (!wordBounds) {
                        return null;
                    }

                    const segmentOriginalText = segment.map((line) => line.text).join('\n').trim();
                    const segmentNewText = segmentLines.join('\n').trim();
                    const lineDescriptors = segment.map((line, lineIndex) => {
                        const lineWords = segWords
                            .filter((word) => {
                                const wTop = Number(word?.top) || 0;
                                const wBottom = wTop + (Number(word?.height) || 0);
                                return localVerticalOverlapRatio(wTop, wBottom, line.top, line.bottom) >= 0.35;
                            })
                            .sort((a, b) => ((Number(a.left) || 0) - (Number(b.left) || 0)));
                        const lineBounds = localGetWordBounds(lineWords);
                        return {
                            lineIndex,
                            originalText: cleanText(line.text || ''),
                            newText: cleanText(segmentLines[lineIndex] || ''),
                            words: lineWords,
                            bounds: lineBounds,
                            top: line.top,
                            bottom: line.bottom,
                        };
                    });
                    const changedLineDescriptors = lineDescriptors.filter((line) => line.originalText !== line.newText);
                    if (lineDescriptors.length > 1 && changedLineDescriptors.length > 0 && changedLineDescriptors.length < lineDescriptors.length) {
                        changedLineDescriptors.forEach((line) => {
                            if (!line.bounds || !line.words.length) return;
                            const lineWordStyles = buildOverlayWordStylesForSave(
                                field,
                                resolvedFont,
                                resolvedWeight,
                                resolvedStyle,
                                line.words,
                                line.newText
                            );
                            splitIntoMinimalLineEdits.push({
                                ...editData,
                                block_num: null,
                                preserve_partial_block: true,
                                original_text: line.originalText,
                                new_text: line.newText,
                                bbox: [line.bounds.left, line.top, line.bounds.left + line.bounds.width, line.bottom],
                                original_bbox: [line.bounds.left, line.top, line.bounds.left + line.bounds.width, line.bottom],
                                origin_x: line.bounds.left,
                                origin_y: line.bottom,
                                word_styles: lineWordStyles.length > 0 ? lineWordStyles : null,
                                rich_html: null,
                                source_content_ops: dedupeOverlaySourceContentOps(
                                    Array.isArray(line.words)
                                        ? line.words.flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : [])
                                        : []
                                ),
                            });
                        });
                        return null;
                    }

                    if (segmentOriginalText === segmentNewText) {
                        return null;
                    }
                    const segWordStyles = buildOverlayWordStylesForSave(
                        field,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segWords,
                        segmentNewText
                    );
                    const segLineMetrics = buildOverlayLineMetricsForSave(
                        field,
                        resolvedFont,
                        resolvedWeight,
                        resolvedStyle,
                        segWords
                    );

                    return {
                        ...editData,
                        block_num: segmentIndex === 0 ? editData.block_num : null,
                        preserve_partial_block: segmentIndex !== 0,
                        original_text: segmentOriginalText,
                        new_text: segmentNewText,
                        bbox: [wordBounds.left, segTop, wordBounds.left + wordBounds.width, segBottom],
                        original_bbox: [wordBounds.left, segTop, wordBounds.left + wordBounds.width, segBottom],
                        origin_x: wordBounds.left,
                        origin_y: segBottom,
                        word_styles: segWordStyles.length > 0 ? segWordStyles : null,
                        line_metrics: segLineMetrics.length > 0 ? segLineMetrics : null,
                        rich_html: null,
                        source_content_ops: dedupeOverlaySourceContentOps(
                            Array.isArray(segWords)
                                ? segWords.flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : [])
                                : []
                        ),
                    };
                }).filter(Boolean);

                if (splitIntoMinimalLineEdits.length > 0) {
                    return splitIntoMinimalLineEdits;
                }

                return segmentEdits.length > 0 ? segmentEdits : [editData];
            }

            function mapFontFamilyToKey(fontFamily) {
                if (!fontFamily) {
                    return 'Helvetica';
                }

                const fontSelect = document.getElementById('selected-font');
                const raw = String(fontFamily || '').trim();
                const lower = raw.toLowerCase().replace(/['"]/g, '').trim();
                const familyCandidates = raw
                    .split(',')
                    .map((part) => String(part || '').replace(/['"]/g, '').trim())
                    .filter(Boolean);
                const candidateValues = [];

                familyCandidates.forEach((candidate) => {
                    const exactCandidate = normalizePdfExactFontName(candidate);
                    const normalizedFamily = normalizePdfEditableFontFamily(candidate);
                    [candidate, exactCandidate, normalizedFamily].forEach((value) => {
                        const trimmed = String(value || '').trim();
                        if (!trimmed) return;
                        if (!candidateValues.some((existing) => existing.toLowerCase() === trimmed.toLowerCase())) {
                            candidateValues.push(trimmed);
                        }
                    });
                });

                if (fontSelect) {
                    for (let option of fontSelect.options) {
                        const optionValue = String(option.value || '').trim();
                        if (!optionValue) continue;
                        if (candidateValues.some((candidate) => optionValue.toLowerCase() === candidate.toLowerCase())) {
                            return optionValue;
                        }
                    }

                    for (let option of fontSelect.options) {
                        const optionValue = String(option.value || '').trim();
                        if (!optionValue || option.disabled) continue;
                        if (candidateValues.some((candidate) => (
                            optionValue.toLowerCase().includes(candidate.toLowerCase())
                            || candidate.toLowerCase().includes(optionValue.toLowerCase())
                        ))) {
                            return optionValue;
                        }
                    }
                }

                if (lower.includes('times')) {
                    return 'TimesRoman';
                }
                if (lower.includes('courier')) {
                    return 'Courier';
                }
                return 'Helvetica';
            }

            function resolveToolbarFontSelection(fontFamily, fallbackFont = 'Helvetica') {
                const raw = String(fontFamily || '').trim();
                if (!raw) {
                    return fallbackFont;
                }

                if (fontMap[raw]) {
                    return raw;
                }

                const exact = normalizePdfExactFontName(raw);
                if (exact && !raw.includes(',') && !fontMap[exact]) {
                    return exact;
                }

                const mapped = mapFontFamilyToKey(raw);
                if (mapped && fontMap[mapped]) {
                    return mapped;
                }

                if (exact) {
                    return exact;
                }

                return fallbackFont;
            }

            function getToolbarCssFontFamily(fontFamily) {
                const resolvedFont = resolveToolbarFontSelection(fontFamily);
                if (fontMap[resolvedFont]) {
                    return fontMap[resolvedFont].css;
                }
                return resolveAnnotationCssFontFamily(resolvedFont, {
                    preferExact: true,
                    exactFontName: resolvedFont,
                });
            }

            function normalizeBuiltinAnnotationFontFamily(fontFamily) {
                if (!fontFamily) {
                    return 'Helvetica';
                }

                const lower = String(fontFamily)
                    .toLowerCase()
                    .replace(/['"]/g, '')
                    .replace(/\s+/g, '')
                    .trim();

                // Explicit Helvetica substitutes — check FIRST so they always win.
                if (lower.includes('annothelvetica') || lower.includes('arimo') || lower.includes('nimbussans')) {
                    return 'Helvetica';
                }
                // TrebuchetMS must come before Verdana: its CSS fallback stack includes
                // Verdana, so processing Verdana first would misidentify TrebuchetMS.
                if (lower.includes('trebuchet')) {
                    return 'TrebuchetMS';
                }
                if (lower.includes('verdana') || lower.includes('geneva')) {
                    return 'Verdana';
                }
                if (lower.includes('gelasio') || lower.includes('georgia')) {
                    return 'Georgia';
                }
                if (lower.includes('annotpalatino') || lower.includes('palatino') || lower.includes('bookantiqua')) {
                    return 'Palatino';
                }
                // 'timesroman'/'times' must come before 'tinos': TimesRoman's CSS fallback
                // stack includes "Tinos", so checking 'tinos' first would return Garamond.
                if (lower.includes('timesroman') || lower.includes('times')) {
                    return 'TimesRoman';
                }
                if (lower.includes('tinos')) {
                    return 'Garamond';
                }
                if (lower.includes('annotgaramond') || lower.includes('garamond') || lower.includes('baskerville')) {
                    return 'Garamond';
                }
                if (lower.includes('courier') || lower.includes('cousine') || lower.includes('mono')) {
                    return 'Courier';
                }
                // Generic sans-serif fallbacks (Arial, Helvetica) are checked LAST so
                // they don't shadow specific fonts whose CSS stacks include Arial.
                if (lower.includes('arial') || lower.includes('helvetica')) {
                    return 'Helvetica';
                }
                return 'Helvetica';
            }

            function resolveBuiltinAnnotationFontFamily(fontFamily, preferredFontFamily = '') {
                const normalizedFontFamily = normalizeBuiltinAnnotationFontFamily(fontFamily);
                const normalizedPreferredFontFamily = preferredFontFamily
                    ? normalizeBuiltinAnnotationFontFamily(preferredFontFamily)
                    : '';

                if (!normalizedPreferredFontFamily) {
                    return normalizedFontFamily;
                }

                const lower = String(fontFamily || '')
                    .toLowerCase()
                    .replace(/['"]/g, '')
                    .replace(/\s+/g, '')
                    .trim();

                if (
                    normalizedPreferredFontFamily === 'Verdana'
                    && normalizedFontFamily === 'Helvetica'
                    && (lower.includes('arimo') || lower.includes('helvetica'))
                ) {
                    return normalizedPreferredFontFamily;
                }

                return normalizedFontFamily || normalizedPreferredFontFamily || 'Helvetica';
            }

            /**
             * Normalize a link span color for overlay display.
             * Some PDFs use bright annotation/link colors that make rebuilt overlay
             * text noisy. This should only be applied to actual link spans.
             */
            function normalizeSpanColorForOverlay(hexColor) {
                if (!hexColor || hexColor === '#000000') return '#000000';
                let h = hexColor.replace('#', '');
                if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
                if (h.length !== 6) return '#000000';
                const r = parseInt(h.slice(0,2), 16) / 255;
                const g = parseInt(h.slice(2,4), 16) / 255;
                const b = parseInt(h.slice(4,6), 16) / 255;
                // Relative luminance (approximate, gamma-compressed linear)
                const lum = 0.2126 * r + 0.7152 * g + 0.0722 * b;
                const maxCh = Math.max(r, g, b);
                if (lum < 0.18 && maxCh < 0.55) return hexColor;
                return '#000000';
            }

            function sourceSpanShouldNormalizeColorForOverlay(sourceSpan) {
                if (!sourceSpan || typeof sourceSpan !== 'object') {
                    return false;
                }
                if (sourceSpan.is_link === true) {
                    return true;
                }
                const linkUri = String(sourceSpan.link_uri || '').trim();
                return linkUri !== '';
            }

            function colorToHex(color) {
                if (!color) {
                    return '#000000';
                }
                if (color === 'transparent') {
                    return 'transparent';
                }
                if (color.startsWith('#')) {
                    return color.length === 4
                        ? `#${color[1]}${color[1]}${color[2]}${color[2]}${color[3]}${color[3]}`
                        : color;
                }
                const match = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/);
                if (!match) {
                    return '#000000';
                }
                if (match[4] !== undefined && parseFloat(match[4]) === 0) {
                    return 'transparent';
                }
                const r = parseInt(match[1], 10).toString(16).padStart(2, '0');
                const g = parseInt(match[2], 10).toString(16).padStart(2, '0');
                const b = parseInt(match[3], 10).toString(16).padStart(2, '0');
                return `#${r}${g}${b}`;
            }

            function rangeInsideNode(range, node) {
                return !!(range && node && node.contains(range.commonAncestorContainer));
            }

            function rangeSelectsEntireNodeContents(range, node) {
                if (!range || !node || range.collapsed || !rangeInsideNode(range, node)) {
                    return false;
                }
                const fullRange = document.createRange();
                fullRange.selectNodeContents(node);
                return range.compareBoundaryPoints(Range.START_TO_START, fullRange) === 0
                    && range.compareBoundaryPoints(Range.END_TO_END, fullRange) === 0;
            }

            function escapeAnnotationHtml(value) {
                return String(value ?? '')
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;')
                    .replace(/'/g, '&#39;');
            }

            function escapeAnnotationHtmlAttribute(value) {
                return escapeAnnotationHtml(value);
            }

            function scaleInlinePxStyleValue(value, factor) {
                const text = String(value || '').trim();
                if (!text || !Number.isFinite(factor) || Math.abs(factor - 1) < 0.0001) {
                    return null;
                }
                const match = text.match(/^(-?\d*\.?\d+)px$/i);
                if (!match) {
                    return null;
                }
                const numericValue = parseFloat(match[1]);
                if (!Number.isFinite(numericValue)) {
                    return null;
                }
                return `${Math.max(0, numericValue * factor)}px`;
            }

            function scaleRichTextInlineStyles(root, factor, { includeRoot = false } = {}) {
                if (!root || !Number.isFinite(factor) || Math.abs(factor - 1) < 0.0001) {
                    return false;
                }

                const nodes = includeRoot
                    ? [root, ...root.querySelectorAll('*')]
                    : Array.from(root.querySelectorAll('*'));
                let changed = false;

                nodes.forEach((node) => {
                    if (!(node instanceof HTMLElement)) {
                        return;
                    }

                    const nextFontSize = scaleInlinePxStyleValue(node.style.fontSize, factor);
                    if (nextFontSize !== null) {
                        node.style.fontSize = nextFontSize;
                        changed = true;
                    }

                    const nextLineHeight = scaleInlinePxStyleValue(node.style.lineHeight, factor);
                    if (nextLineHeight !== null) {
                        node.style.lineHeight = nextLineHeight;
                        changed = true;
                    }
                });

                return changed;
            }

            function serializeAnnotationRichTextNode(node) {
                if (!node) {
                    return '';
                }
                if (node.nodeType === Node.TEXT_NODE) {
                    return escapeAnnotationHtml(node.nodeValue || '');
                }
                if (node.nodeType !== Node.ELEMENT_NODE) {
                    return '';
                }

                const tagName = String(node.tagName || '').toLowerCase();
                if (tagName === 'br') {
                    return '<br>';
                }

                let inner = '';
                node.childNodes.forEach((child) => {
                    inner += serializeAnnotationRichTextNode(child);
                });

                if (tagName === 'div' || tagName === 'p') {
                    return `${inner}<br>`;
                }

                if (tagName !== 'span') {
                    return inner;
                }

                const styles = [];
                const rawColor = String(node.style.color || '').trim();
                const rawBackgroundColor = String(node.style.backgroundColor || '').trim();
                const color = rawColor ? colorToHex(rawColor) : '';
                const backgroundColor = rawBackgroundColor ? colorToHex(rawBackgroundColor) : '';
                const fontSize = String(node.style.fontSize || '').trim();
                const fontWeight = String(node.style.fontWeight || '').trim();
                const fontStyle = String(node.style.fontStyle || '').trim();
                const textDecoration = String(node.style.textDecoration || node.style.textDecorationLine || '').trim();
                const fontFamily = String(node.style.fontFamily || '').trim();

                if (color && color !== '#000000' && color !== 'transparent') styles.push(`color:${color}`);
                if (backgroundColor && backgroundColor !== 'transparent') styles.push(`background-color:${backgroundColor}`);
                if (fontSize) styles.push(`font-size:${fontSize}`);
                if (fontWeight && fontWeight !== '400' && fontWeight !== 'normal') styles.push(`font-weight:${fontWeight}`);
                if (fontStyle && fontStyle !== 'normal') styles.push(`font-style:${fontStyle}`);
                if (textDecoration && textDecoration !== 'none') styles.push(`text-decoration:${textDecoration}`);
                if (fontFamily) styles.push(`font-family:${fontFamily}`);

                if (styles.length === 0) {
                    return inner;
                }

                return `<span style="${escapeAnnotationHtmlAttribute(styles.join(';'))}">${inner}</span>`;
            }

            function extractAnnotationNodePlainText(node) {
                if (!node) {
                    return '';
                }
                if (node.nodeType === Node.TEXT_NODE) {
                    return node.nodeValue || '';
                }
                if (node.nodeType !== Node.ELEMENT_NODE) {
                    return '';
                }
                if (String(node.tagName || '').toLowerCase() === 'br') {
                    return '\n';
                }
                let out = '';
                node.childNodes.forEach((child) => {
                    out += extractAnnotationNodePlainText(child);
                });
                return out;
            }

            function trimTrailingWhitespaceFromRichTextNode(node) {
                if (!node || !node.childNodes || !node.childNodes.length) {
                    return;
                }
                for (let index = node.childNodes.length - 1; index >= 0; index -= 1) {
                    const child = node.childNodes[index];
                    if (!child) {
                        continue;
                    }
                    if (child.nodeType === Node.TEXT_NODE) {
                        const nextValue = String(child.nodeValue || '').replace(/[ \t]+$/g, '');
                        if (nextValue.length) {
                            child.nodeValue = nextValue;
                            return;
                        }
                        child.parentNode?.removeChild(child);
                        continue;
                    }
                    if (child.nodeType === Node.ELEMENT_NODE) {
                        trimTrailingWhitespaceFromRichTextNode(child);
                        const remainingText = extractAnnotationNodePlainText(child).replace(/[ \t]+$/g, '');
                        if (remainingText.length) {
                            return;
                        }
                        child.parentNode?.removeChild(child);
                    }
                }
            }

            function serializeExactPromotedGeometryLineRichText(lineEl) {
                if (!(lineEl instanceof HTMLElement)) {
                    return '';
                }

                let html = '';
                const fullLineText = extractAnnotationNodePlainText(lineEl).replace(/\u00A0/g, ' ');
                let textCursor = 0;
                const childNodes = Array.from(lineEl.childNodes || []);

                childNodes.forEach((child) => {
                    const childHtml = serializeAnnotationRichTextNode(child);
                    if (!childHtml) {
                        return;
                    }

                    const childText = extractAnnotationNodePlainText(child).replace(/\u00A0/g, ' ');
                    if (childText) {
                        const matchIndex = fullLineText.indexOf(childText, textCursor);
                        if (matchIndex > textCursor) {
                            html += escapeAnnotationHtml(fullLineText.slice(textCursor, matchIndex));
                        }
                        if (matchIndex >= 0) {
                            textCursor = matchIndex + childText.length;
                        }
                    }

                    html += childHtml;
                });

                if (textCursor < fullLineText.length) {
                    html += escapeAnnotationHtml(fullLineText.slice(textCursor));
                }

                return html;
            }

            function getExactPromotedGeometryLineElements(textEl) {
                if (!(textEl instanceof HTMLElement) || textEl.dataset?.exactPromotedGeometry !== '1') {
                    return [];
                }
                return Array.from(textEl.children || []).filter((child) => (
                    child instanceof HTMLElement && child.classList.contains('annotation-exact-line')
                ));
            }

            function buildExactPromotedGeometryText(textEl) {
                const lineElements = getExactPromotedGeometryLineElements(textEl);
                if (!lineElements.length) {
                    return '';
                }
                const lines = lineElements.map((lineEl) => (
                    sanitizePromotedExtractionLine(extractAnnotationNodePlainText(lineEl))
                ));
                return sanitizePromotedExtractionText(lines.join('\n'));
            }

            function buildExactPromotedGeometryRichTextHtml(textEl) {
                const lineElements = getExactPromotedGeometryLineElements(textEl);
                if (!lineElements.length) {
                    return '';
                }

                let html = '';
                lineElements.forEach((lineEl, lineIndex) => {
                    const clonedLine = lineEl.cloneNode(true);
                    trimTrailingWhitespaceFromRichTextNode(clonedLine);
                    html += serializeExactPromotedGeometryLineRichText(clonedLine);
                    if (lineIndex < lineElements.length - 1) {
                        html += '<br>';
                    }
                });
                return html.replace(/(?:<br>)+$/g, '');
            }

            function buildAnnotationRichTextHtml(textEl) {
                if (!textEl) {
                    return '';
                }
                if (textEl.dataset?.annotationExactCharacterEditor === '1') {
                    return '';
                }
                if (textEl.dataset?.exactPromotedGeometry === '1') {
                    const exactGeometryHtml = buildExactPromotedGeometryRichTextHtml(textEl);
                    if (exactGeometryHtml !== '') {
                        return exactGeometryHtml;
                    }
                }
                if (
                    textEl.dataset?.splitParagraphFullyActive === '1'
                    || textEl.dataset?.annotationSplitParagraphFully === '1'
                    || textEl.dataset?.editLayout === 'split-paragraph-fully'
                ) {
                    const splitHtml = buildSplitParagraphRichTextHtml(textEl);
                    if (splitHtml !== '') {
                        return splitHtml;
                    }
                }
                let html = '';
                textEl.childNodes.forEach((child) => {
                    html += serializeAnnotationRichTextNode(child);
                });
                return html.replace(/(?:<br>)+$/g, '');
            }

            // Strip font-size:Xpx declarations from inline styles in an HTML string.
            // richTextHtml stores font sizes as browser screen pixels at the current zoom level.
