                const container = document.createElement('div');
                container.innerHTML = stripPxFontSizesFromRichHtml(nextHtml);
                const resolvedExactFontFamily = resolveAnnotationCssFontFamily(
                    annotationLike?.fontFamily || 'Helvetica',
