                        text: textValue,
                        fontFamily: style.fontFamily || baseStyle.fontFamily,
                        fontWeight: style.fontWeight || baseStyle.fontWeight,
                        fontStyle: style.fontStyle || baseStyle.fontStyle,
                        color: style.color || baseStyle.color,
