                        fontWeight: inheritedStyle.fontWeight || baseStyle.fontWeight,
                        fontStyle: inheritedStyle.fontStyle || baseStyle.fontStyle,
                        color: inheritedStyle.color || baseStyle.color,
                        underline: Boolean(inheritedStyle.underline),
