                                });
                                lineEl.style.fontSize = `${annotation.fontSize * currentScale}px`;
                                lineEl.style.fontWeight = annotation.fontWeight || '400';
                                lineEl.style.fontStyle = annotation.fontStyle || 'normal';
                                lineEl.style.color = annotation.textColor || '#000000';
                            }

                            fragment.appendChild(lineEl);
                        });

                        target.appendChild(fragment);
                        target.dataset.exactPromotedGeometry = '1';
                        return true;
                    };
                    const fontFamily = resolveAnnotationCssFontFamily(annotation.fontFamily, {
                        preferExact: Boolean(annotation.promotedFromExtraction),
                        exactFontName: annotation.fontSourceName || annotation.fontFamily,
                    });
                    const fontSizePx = getAnnotationDisplayFontSizePx(annotation, currentScale);
                    const hasBounds = annotationHasBounds(annotation);
                    const promotedExtraction = Boolean(annotation.promotedFromExtraction);
                    const preservePromotedLines = promotedExtraction && !annotation.promotedReflowEnabled;
                    const textWrapper = annotation.textWrapper || annotation.element.querySelector('.text-content-wrapper');
                    // Mask the underlying PDF text if the base PDF has baked-in text (detected
                    // at load time). Applies to any annotation that represents text placed over
                    // the document — both DB-loaded (savedDatabaseAnnotation) and freshly
                    // hydrated from extraction (promotedExtraction) in loadedSavedPdfMode.
                    const shouldMaskUnderlyingPageText = Boolean(
                        hasBounds
                        && (annotation.savedTextOverlay || promotedExtraction || annotation.savedDatabaseAnnotation)
                        && (
                            (loadedSavedPdfMode && basePdfHasBakedAnnotationText)
                            || (
                                promotedExtraction
                                && basePdfUrl === cleanPdfUrl
                            )
                        )
                    );
                    const shouldUseTransparentPromotedMask = promotedAnnotationShouldUseTransparentMask(annotation);
                    const effectiveBackgroundColor = (shouldMaskUnderlyingPageText && !shouldUseTransparentPromotedMask)
                        ? (annotation.backgroundColor && annotation.backgroundColor !== 'transparent'
                            ? annotation.backgroundColor
                            : '#ffffff')
                        : (annotation.backgroundColor || 'transparent');
                    annotation.element.style.fontFamily = fontFamily;
                    annotation.element.style.fontSize = fontSizePx + 'px';
                    annotation.element.style.textAlign = annotation.textAlign || 'left';
                    annotation.element.classList.toggle('has-bounds', hasBounds);
                    annotation.element.classList.toggle('promoted-extraction', promotedExtraction);
                    annotation.element.style.display = hasBounds ? 'block' : 'inline-flex';
                    annotation.element.style.alignItems = hasBounds ? 'stretch' : 'center';
                    annotation.element.style.padding = hasBounds ? '0' : '2px 6px';
                    annotation.element.style.gap = hasBounds ? '0' : '4px';
                    annotation.element.style.overflow = 'visible';
                    annotation.element.style.backgroundColor = hasBounds ? effectiveBackgroundColor : 'transparent';
                    annotation.element.style.wordWrap = '';
                    const storedLineHeightPx = Number(annotation.lineHeight) > 0
                        ? (Number(annotation.lineHeight) * currentScale)
                        : 0;
                    const resolvedLineHeightPx = promotedExtraction
                        ? storedLineHeightPx
                        : Math.max(storedLineHeightPx, fontSizePx * 1.2);
                    annotation.element.style.lineHeight = resolvedLineHeightPx > 0 ? `${resolvedLineHeightPx}px` : '';
                        const span = annotation.element.querySelector('.annotation-text');
                        if (span) {
                            const nextRichHtml = typeof annotation.richTextHtml === 'string' ? annotation.richTextHtml : '';
                            const appliedExactGeometry = renderExactPromotedGeometry(span);
                        if (!appliedExactGeometry && nextRichHtml) {
                                const cleanRichHtml = normalizeAnnotationRichTextHtml(nextRichHtml, annotation);
                                if (span.innerHTML !== cleanRichHtml) {
                                    span.innerHTML = cleanRichHtml;
                                }
                                delete span.dataset.exactPromotedGeometry;
                            } else if (!appliedExactGeometry && span.textContent !== annotation.text) {
                                span.textContent = annotation.text;
                                delete span.dataset.exactPromotedGeometry;
                            }
                        const usesExactPromotedGeometry = span.dataset.exactPromotedGeometry === '1';
                        const normalizedAnnotationBackgroundColor = String(annotation.backgroundColor || '').trim().toLowerCase();
                        const effectiveMaskLooksLikeWhite = String(effectiveBackgroundColor || '').trim().toLowerCase() === '#ffffff';
                        const shouldSampleFallbackMaskColor = Boolean(
                            shouldMaskUnderlyingPageText
                            && usesExactPromotedGeometry
                            && (
                                !normalizedAnnotationBackgroundColor
                                || normalizedAnnotationBackgroundColor === 'transparent'
                                || normalizedAnnotationBackgroundColor === '#fff'
                                || normalizedAnnotationBackgroundColor === '#ffffff'
                                || normalizedAnnotationBackgroundColor === 'rgb(255, 255, 255)'
                                || normalizedAnnotationBackgroundColor === 'rgba(255, 255, 255, 1)'
                                || effectiveMaskLooksLikeWhite
                            )
                        );
                        const annotationContainerBackgroundColor = usesExactPromotedGeometry && promotedExtraction
                            ? 'transparent'
                            : effectiveBackgroundColor;
                        span.style.color = annotation.textColor || '#000000';
                        span.style.backgroundColor = usesExactPromotedGeometry ? 'transparent' : effectiveBackgroundColor;
                        span.style.fontWeight = annotation.fontWeight || 'normal';
                        span.style.fontStyle = annotation.fontStyle || 'normal';
                        span.style.textDecoration = annotation.underline ? 'underline' : 'none';
                        span.style.opacity = annotation.opacity ?? 1;
                        span.style.padding = promotedExtraction ? '0' : '';
                        span.style.lineHeight = span.dataset.exactPromotedGeometry === '1'
                            ? ''
                            : (resolvedLineHeightPx > 0 ? `${resolvedLineHeightPx}px` : '');
                        span.style.whiteSpace = span.dataset.exactPromotedGeometry === '1'
                            ? 'normal'
                            : (promotedExtraction ? (preservePromotedLines ? 'pre' : 'pre-wrap') : '');
                        span.style.overflowWrap = span.dataset.exactPromotedGeometry === '1'
                            ? 'normal'
                            : (promotedExtraction ? (preservePromotedLines ? 'normal' : 'break-word') : '');
                        span.style.wordBreak = span.dataset.exactPromotedGeometry === '1'
                            ? 'normal'
                            : (promotedExtraction ? (preservePromotedLines ? 'normal' : 'break-word') : '');
                        if (usesExactPromotedGeometry) {
                            span.querySelectorAll('.annotation-exact-line').forEach((lineEl) => {
                                if (!(lineEl instanceof HTMLElement)) {
                                    return;
                                }
                                const applyExactLineMaskColor = () => {
                                    const sampledMaskColor = shouldSampleFallbackMaskColor
                                        ? samplePageCanvasDominantColorForElement(annotation, lineEl)
                                        : null;
                                    lineEl.style.backgroundColor = sampledMaskColor || effectiveBackgroundColor;
                                };
                                applyExactLineMaskColor();
                                if (shouldSampleFallbackMaskColor) {
                                    requestAnimationFrame(() => {
                                        requestAnimationFrame(() => {
                                            if (document.body.contains(lineEl)) {
                                                applyExactLineMaskColor();
                                            }
                                        });
                                    });
                                }
                            });
                        }
                        annotation.element.style.backgroundColor = hasBounds ? annotationContainerBackgroundColor : 'transparent';
                    }
                    if (textWrapper) {
                        if (hasBounds && !promotedExtraction) {
                            const vAlign = annotation.verticalAlign || 'top';
                            textWrapper.style.display = 'flex';
                            textWrapper.style.flexDirection = 'column';
                            textWrapper.style.justifyContent = vAlign === 'bottom' ? 'flex-end' : (vAlign === 'middle' ? 'center' : 'flex-start');
                        } else {
                            textWrapper.style.display = hasBounds ? 'block' : 'inline-block';
                            textWrapper.style.flexDirection = '';
                            textWrapper.style.justifyContent = '';
                        }
                        textWrapper.style.width = hasBounds ? '100%' : 'auto';
                        textWrapper.style.height = hasBounds ? '100%' : 'auto';
                        textWrapper.style.padding = hasBounds
                            ? (promotedExtraction ? '0' : '2px 6px')
                            : '0';
                        textWrapper.style.boxSizing = hasBounds ? 'border-box' : '';
                        // Promoted-extraction: keep visible so HTML font metrics slightly
                        // wider than PDF metrics don't clip edge characters.
                        // Standalone text boxes: hide so the user-defined box constrains.
                        textWrapper.style.overflow = (hasBounds && !promotedExtraction) ? 'hidden' : 'visible';
                        textWrapper.style.backgroundColor = hasBounds
                            ? ((span?.dataset?.exactPromotedGeometry === '1' && promotedExtraction) ? 'transparent' : effectiveBackgroundColor)
                            : 'transparent';
                    }
                    // Apply bounding box size if present
                    if (hasBounds) {
                        annotation.element.style.width = (annotation.pdfWidth * currentScale) + 'px';
                        annotation.element.style.height = (annotation.pdfHeight * currentScale) + 'px';
                    } else {
                        annotation.element.style.width = '';
                        annotation.element.style.height = '';
                    }
                    // Alignment translateX on the label (no rotation here — rotation goes on textWrapper)
                    const measuredRichWidth = !hasBounds && span
                        ? Math.ceil(span.getBoundingClientRect().width || span.scrollWidth || 0)
                        : 0;
                    const width = hasBounds
                        ? (annotation.pdfWidth * currentScale)
                        : Math.max(
                            measuredRichWidth,
                            measureAnnotationTextWidth(annotation.text, fontSizePx, fontFamily, annotation.fontWeight, annotation.fontStyle)
                        );
                    let translateX = 0;
                    if (!hasBounds) {
                        if (annotation.textAlign === 'center') {
                            translateX = -width / 2;
                        } else if (annotation.textAlign === 'right') {
                            translateX = -width;
                        }
                    }
                    annotation.element.style.transform = `translateX(${translateX}px)`;
                    // Apply rotation to the text content wrapper only
                    const rot = annotation.rotation || 0;
                    const tw = annotation.textWrapper || annotation.element.querySelector('.text-content-wrapper');
                    if (tw) {
                        tw.style.transform = rot ? `rotate(${rot}deg)` : '';
                        tw.style.transformOrigin = 'center center';
                    }

                    if (selectedAnnotation === annotation) {
                        queueSelectedAnnotationMenuPlacement();
                    }
                }
            }

            function syncTextAnnotationStyleFromDom(annotation) {
                if (!annotation || !annotation.element || (annotation.type && annotation.type !== 'text')) {
                    return;
                }
                if (annotation.promotedFromExtraction && !annotation.promotedDirty) {
                    return;
                }
                const span = annotation.element.querySelector('.annotation-text');
                const spanStyle = span ? window.getComputedStyle(span) : null;
                const elementStyle = window.getComputedStyle(annotation.element);
                const resolvedFontSizePx = parseFloat(spanStyle?.fontSize || elementStyle.fontSize || '0');
                const resolvedFontFamily = spanStyle?.fontFamily || elementStyle.fontFamily || annotation.fontFamily || 'Helvetica';
                const resolvedTextColor = colorToHex(spanStyle?.color || annotation.textColor || '#000000');
                const resolvedBgColor = colorToHex(spanStyle?.backgroundColor || annotation.backgroundColor || 'transparent');
                const resolvedWeight = String(spanStyle?.fontWeight || annotation.fontWeight || '400');
                const resolvedStyle = String(spanStyle?.fontStyle || annotation.fontStyle || 'normal');
                const resolvedLineHeightPx = parseFloat(spanStyle?.lineHeight || elementStyle.lineHeight || '0');
                const resolvedDecoration = String(spanStyle?.textDecorationLine || '').toLowerCase();
                const resolvedAlign = String(spanStyle?.textAlign || elementStyle.textAlign || annotation.textAlign || 'left');
                const resolvedOpacity = parseFloat(spanStyle?.opacity || elementStyle.opacity || annotation.opacity || '1') || 1;
                const explicitText = span ? getOverlayExplicitText(span) : annotation.text;
                const richTextHtml = span ? buildAnnotationRichTextHtml(span) : '';

                if (annotation.promotedFromExtraction) {
                    const existingFontFamily = String(annotation.fontFamily || '').trim();
                    const existingNormalized = normalizePdfEditableFontFamily(existingFontFamily);
                    const resolvedNormalized = normalizePdfEditableFontFamily(resolvedFontFamily);
                    annotation.fontFamily = (
                        existingFontFamily
                        && existingNormalized
                        && resolvedNormalized
                        && existingNormalized.toLowerCase() === resolvedNormalized.toLowerCase()
                    )
                        ? existingFontFamily
                        : (resolvedNormalized || existingFontFamily || normalizeBuiltinAnnotationFontFamily(resolvedFontFamily));
                } else {
                    annotation.fontFamily = resolveBuiltinAnnotationFontFamily(
                        resolvedFontFamily,
                        annotation.fontFamily || 'Helvetica'
                    );
                }
                if (resolvedFontSizePx > 0 && currentScale > 0) {
                    annotation.fontSize = resolvedFontSizePx / currentScale;
                    if (
                        annotation.promotedFromExtraction
                        || annotationRichTextHasFormatting(richTextHtml)
                        || !(Number(annotation.requestedFontSize) > 0)
                    ) {
                        annotation.requestedFontSize = resolvedFontSizePx;
                    }
                }
                annotation.text = explicitText;
                if (annotationRichTextHasFormatting(richTextHtml)) {
                    annotation.richTextHtml = richTextHtml;
                } else {
                    delete annotation.richTextHtml;
                }
                annotation.textColor = resolvedTextColor === 'transparent' ? '#000000' : resolvedTextColor;
                annotation.backgroundColor = resolvedBgColor === '#ffffff' ? 'transparent' : resolvedBgColor;
                annotation.fontWeight = Number.isFinite(parseInt(resolvedWeight, 10))
                    ? String(Math.round(parseInt(resolvedWeight, 10) / 100) * 100)
                    : (resolvedWeight.toLowerCase() === 'bold' ? '700' : '400');
                annotation.fontStyle = resolvedStyle === 'italic' || resolvedStyle === 'oblique' ? 'italic' : 'normal';
                annotation.underline = resolvedDecoration.includes('underline');
                annotation.textAlign = ['left', 'center', 'right'].includes(resolvedAlign) ? resolvedAlign : 'left';
                annotation.opacity = resolvedOpacity;
                if (resolvedLineHeightPx > 0 && currentScale > 0) {
                    annotation.lineHeight = resolvedLineHeightPx / currentScale;
                }
                normalizeTextAnnotation(annotation);

                if (annotation.richTextHtml) {
                    const pageContext = resolveAnnotationPageContext(annotation);
                    const measuredBounds = measureTextAnnotationContentBounds(annotation);
                    if (pageContext && measuredBounds && annotation.element) {
                        annotation.keepBounds = true;
                        setTextAnnotationBounds(
                            annotation,
                            pageContext.pageInfo,
                            annotation.element.offsetLeft,
                            annotation.element.offsetTop,
                            measuredBounds.widthPx,
                            measuredBounds.heightPx
                        );
                    }
                }
            }

            function syncAnnotationsForSave() {
                annotations.forEach((annotation) => {
                    syncTextAnnotationStyleFromDom(annotation);
                });
                persistAnnotations();
            }

            function syncSelectedAnnotationEditState() {
                if (!selectedAnnotation || (selectedAnnotation.type && selectedAnnotation.type !== 'text')) {
                    return;
                }

                if (typeof populateEditTextBanner === 'function') {
                    populateEditTextBanner(selectedAnnotation);
                }

                if (!activeEditor || !activeEditor.classList.contains('text-box-creator')) {
                    return;
                }

                const input = activeEditor._tbcInput || activeEditor.querySelector('.tbc-input');
                if (!input) {
                    return;
                }
                const pageScale = Number(activeEditor._pageScale || input.dataset.pageScale || currentScale || 1) || 1;
                const useRequestedScale = input.dataset.fontSizeScaleMode === 'requested';

                input.style.fontFamily = selectedAnnotation.promotedFromExtraction
                    ? resolveAnnotationCssFontFamily(selectedAnnotation.fontFamily, {
                        preferExact: true,
                        exactFontName: selectedAnnotation.fontSourceName || selectedAnnotation.fontFamily,
                    })
                    : (fontMap[selectedAnnotation.fontFamily]?.css || 'inherit');
                input.dataset.builtinFontFamily = selectedAnnotation.fontFamily || 'Helvetica';
                input.dataset.requestedFontSize = String(getRequestedAnnotationFontSize(selectedAnnotation));
                input.style.fontSize = useRequestedScale
                    ? `${getRequestedAnnotationFontSize(selectedAnnotation) * pageScale}px`
                    : `${getRequestedAnnotationFontSize(selectedAnnotation)}px`;
                input.style.color = selectedAnnotation.textColor || '#000000';
                input.style.backgroundColor = selectedAnnotation.backgroundColor || 'transparent';
                input.style.fontWeight = selectedAnnotation.fontWeight || 'normal';
                input.style.fontStyle = selectedAnnotation.fontStyle || 'normal';
                input.style.textDecoration = selectedAnnotation.underline ? 'underline' : 'none';
                input.style.textAlign = selectedAnnotation.textAlign || 'left';
                input.style.opacity = String(selectedAnnotation.opacity ?? 1);
                const selectedFontSizePx = getRequestedAnnotationFontSize(selectedAnnotation);
                const selectedLineHeightPx = Number(selectedAnnotation.lineHeight) > 0
                    ? Number(selectedAnnotation.lineHeight) * currentScale
                    : 0;
                const defaultEditorLineHeightPx = getEditorDefaultLineHeightPx(input, selectedFontSizePx, pageScale);
                const preservePromotedLineHeightInEditor = Boolean(
                    selectedAnnotation.promotedFromExtraction
                    && !selectedAnnotation.promotedReflowEnabled
                    && selectedLineHeightPx > 0
                );
                if (preservePromotedLineHeightInEditor) {
                    input.style.lineHeight = `${selectedLineHeightPx}px`;
                } else if (selectedAnnotation.promotedFromExtraction) {
                    input.style.lineHeight = `${Math.max(selectedLineHeightPx, defaultEditorLineHeightPx)}px`;
                } else if (selectedLineHeightPx > 0) {
                    input.style.lineHeight = `${selectedLineHeightPx}px`;
                } else {
                    input.style.lineHeight = `${defaultEditorLineHeightPx}px`;
                }
                if (selectedAnnotation.promotedFromExtraction && selectedAnnotation.promotedReflowEnabled) {
                    input.style.whiteSpace = 'pre-wrap';
                    input.style.overflowWrap = 'break-word';
                    input.style.wordBreak = 'break-word';
                    input.style.padding = '';
                }
            }

            function normalizeFieldAnnotation(annotation) {
                if (!annotation || !isFieldAnnotation(annotation)) {
                    return;
                }

                annotation.type = 'field';
                annotation.fieldKind = normalizeFieldKind(annotation.fieldKind);
                annotation.fieldName = String(annotation.fieldName || annotation.id || generateAnnotationId()).trim();
                annotation.placeholder = String(annotation.placeholder || (
                    annotation.fieldKind === 'date'
                        ? 'MM/DD/YYYY'
                        :
                    annotation.fieldKind === 'signature'
                        ? 'Sign here'
                        : (isOptionFieldKind(annotation.fieldKind) ? 'Select option' : 'Type here')
                ));
                annotation.fieldOptions = isOptionFieldKind(annotation.fieldKind)
                    ? getSelectFieldOptions(annotation, getDefaultOptionFieldOptions(annotation.fieldKind))
                    : [];
                if (annotation.fieldKind === 'date') {
                    annotation.fieldValue = formatDateFieldValue(annotation.fieldValue ?? annotation.text ?? '', { finalize: true });
                } else if (annotation.fieldKind === 'text') {
                    annotation.fieldValue = String(annotation.fieldValue ?? annotation.text ?? '');
                } else if (isOptionFieldKind(annotation.fieldKind)) {
                    annotation.fieldValue = getSelectFieldValue(annotation, annotation.fieldOptions);
                } else {
                    annotation.fieldValue = '';
                }
                annotation.checked = Boolean(annotation.checked);
                annotation.textColor = annotation.textColor || (annotation.fieldKind === 'signature' ? '#ffffff' : '#334155');
                const useAutoDetectedCheckboxTint = Boolean(
                    annotation.autoDetectedDrawnCheckbox
                    && annotation.fieldKind === 'checkbox'
                    && (
                        !annotation.backgroundColor
                        || String(annotation.backgroundColor).trim().toLowerCase() === 'transparent'
                    )
                );
                annotation.backgroundColor = useAutoDetectedCheckboxTint
                    ? '#e0e7ff'
                    : (annotation.backgroundColor || (
                        (annotation.fieldKind === 'checkbox' || isOptionFieldKind(annotation.fieldKind))
                            ? '#ffffff'
                            : (annotation.fieldKind === 'signature' ? '#e0e7ff' : '#e0e7ff')
                    ));
                annotation.borderColor = annotation.borderColor || (annotation.fieldKind === 'signature' ? '#818cf8' : '#64748b');
                annotation.accentColor = annotation.accentColor || (annotation.fieldKind === 'signature' ? '#4f46e5' : '#64748b');
                annotation.borderWidth = Number(annotation.borderWidth) > 0 ? Number(annotation.borderWidth) : 1.5;
                annotation.fontSize = Number(annotation.fontSize) > 0 ? Number(annotation.fontSize) : 12;
                annotation.opacity = typeof annotation.opacity === 'number' ? normalizeShapeOpacity(annotation.opacity) : 1;
                annotation.rotation = 0;
                annotation.signedDataUrl = String(annotation.signedDataUrl || '').trim();
                annotation.signedAssetPath = String(annotation.signedAssetPath || annotation.signatureAssetPath || '').trim();
                annotation.signedMimeType = String(annotation.signedMimeType || '').trim();
                annotation.signedFileName = String(annotation.signedFileName || '').trim();
                annotation.pdfWidth = Number(annotation.pdfWidth) > 0
                    ? Number(annotation.pdfWidth)
                    : (annotation.fieldKind === 'checkbox' ? 18 : (annotation.fieldKind === 'signature' ? 220 : (annotation.fieldKind === 'list' ? 180 : (annotation.fieldKind === 'select' ? 180 : 160))));
                annotation.pdfHeight = Number(annotation.pdfHeight) > 0
                    ? Number(annotation.pdfHeight)
                    : (annotation.fieldKind === 'checkbox' ? 18 : (annotation.fieldKind === 'signature' ? 52 : (annotation.fieldKind === 'list' ? 88 : (annotation.fieldKind === 'select' ? 40 : 32))));
                if (annotation.fieldKind === 'checkbox') {
                    const squareSize = Math.max(annotation.pdfWidth, annotation.pdfHeight);
                    annotation.pdfWidth = squareSize;
                    annotation.pdfHeight = squareSize;
                }
            }

            function normalizeTextAnnotation(annotation) {
                if (!annotation || isImageBackedAnnotationType(annotation.type) || annotation.type === 'shape' || annotation.type === 'eraser' || annotation.type === 'table' || isFieldAnnotation(annotation)) {
                    return;
                }
                annotation.type = annotation.type || 'text';
                annotation.fontFamily = resolveToolbarFontSelection(
                    annotation.fontSourceName || annotation.fontFamily || 'Helvetica'
                );
                if (typeof annotation.fontSourceName === 'string') {
                    annotation.fontSourceName = annotation.fontSourceName.trim();
                }
                annotation.textColor = annotation.textColor || '#000000';
                annotation.backgroundColor = annotation.backgroundColor || 'transparent';
                annotation.fontWeight = annotation.fontWeight || 'normal';
                annotation.fontStyle = annotation.fontStyle || 'normal';
                annotation.underline = Boolean(annotation.underline);
                annotation.textAlign = annotation.textAlign || 'left';
                annotation.opacity = typeof annotation.opacity === 'number' ? annotation.opacity : 1;
                annotation.rotation = annotation.rotation || 0;
                annotation.keepBounds = Boolean(annotation.keepBounds);
                if (annotation.promotedFromExtraction) {
                    // Promoted/imported text stores fontSize in PDF-space units. A persisted
                    // requestedFontSize is only a display-pixel cache from a prior zoom level,
                    // and reusing it on load causes font size to be scaled twice.
                    delete annotation.requestedFontSize;
                } else if (annotation.requestedFontSize !== null && annotation.requestedFontSize !== undefined) {
                    const parsedRequestedFontSize = Number(annotation.requestedFontSize);
                    if (parsedRequestedFontSize > 0) {
                        annotation.requestedFontSize = parsedRequestedFontSize;
                    } else {
                        delete annotation.requestedFontSize;
                    }
                }
                if (annotation.lineHeight !== null && annotation.lineHeight !== undefined) {
                    const parsedLineHeight = Number(annotation.lineHeight);
                    if (parsedLineHeight > 0) {
                        annotation.lineHeight = parsedLineHeight;
                    } else {
                        delete annotation.lineHeight;
                    }
                }
                if (typeof annotation.richTextHtml !== 'string' || !annotation.richTextHtml.trim()) {
                    delete annotation.richTextHtml;
                }
            }

            function getRequestedAnnotationFontSize(annotation, fallback = 16) {
                const requestedSize = Number(annotation?.requestedFontSize);
                if (requestedSize > 0) {
                    return requestedSize;
                }
                const normalizedFontSize = Number(annotation?.fontSize);
                if (normalizedFontSize > 0) {
                    return Math.round(normalizedFontSize * currentScale) || fallback;
                }
                return fallback;
            }

            function getAnnotationDisplayFontSizePx(annotation, pageScale = currentScale) {
                const normalizedScale = Math.max(0.0001, Number(pageScale) || currentScale || 1);
                if (annotation && !annotationRichTextHasFormatting(annotation.richTextHtml || '')) {
                    const requestedSize = Number(annotation.requestedFontSize);
                    if (requestedSize > 0) {
                        return requestedSize * normalizedScale;
                    }
                }
                return (Number(annotation?.fontSize) || 0) * normalizedScale;
            }

            function annotationHasBounds(annotation) {
                return Boolean(
                    annotation
                    && Number(annotation.pdfWidth) > 0
                    && Number(annotation.pdfHeight) > 0
                );
            }

            function getRenderedPageCssDimension(overlay, canvas, dimension, fallbackValue = 0) {
                const overlayDimension = dimension === 'width'
                    ? Number(overlay?.clientWidth)
                    : Number(overlay?.clientHeight);
                if (overlayDimension > 0) {
                    return overlayDimension;
                }

                const canvasStyleDimension = parseFloat(
                    dimension === 'width'
                        ? String(canvas?.style?.width || '')
                        : String(canvas?.style?.height || '')
                );
                if (canvasStyleDimension > 0) {
                    return canvasStyleDimension;
                }

                if (canvas instanceof HTMLElement) {
                    const rect = canvas.getBoundingClientRect();
                    const rectDimension = dimension === 'width' ? Number(rect.width) : Number(rect.height);
                    if (rectDimension > 0) {
                        return rectDimension;
                    }
                }

                const backingDimension = dimension === 'width'
                    ? Number(canvas?.width)
                    : Number(canvas?.height);
                if (backingDimension > 0) {
                    return backingDimension / Math.max(1, Number(window.devicePixelRatio) || 1);
                }

                return Math.max(0, Number(fallbackValue) || 0);
            }

            function buildPageInfoForRender(overlay, canvas, { scale = currentScale, fallbackWidth = 0, fallbackHeight = 0 } = {}) {
                return {
                    scale,
                    canvasWidth: getRenderedPageCssDimension(overlay, canvas, 'width', fallbackWidth),
                    canvasHeight: getRenderedPageCssDimension(overlay, canvas, 'height', fallbackHeight),
                };
            }

            function getTextAnnotationTopPx(annotation, pageInfo) {
                if (annotationHasBounds(annotation)) {
                    return pageInfo.canvasHeight - ((annotation.pdfY + annotation.pdfHeight) * pageInfo.scale);
                }
                return pageInfo.canvasHeight - (annotation.pdfY * pageInfo.scale);
            }

            function setTextAnnotationPosition(annotation, pageInfo, leftPx, topPx) {
                annotation.pdfX = leftPx / pageInfo.scale;
                if (annotationHasBounds(annotation)) {
                    annotation.pdfY = (pageInfo.canvasHeight - topPx) / pageInfo.scale - annotation.pdfHeight;
                } else {
                    annotation.pdfY = (pageInfo.canvasHeight - topPx) / pageInfo.scale;
                }
            }

            function setTextAnnotationBounds(annotation, pageInfo, leftPx, topPx, widthPx, heightPx) {
                annotation.pdfWidth = widthPx / pageInfo.scale;
                annotation.pdfHeight = heightPx / pageInfo.scale;
                setTextAnnotationPosition(annotation, pageInfo, leftPx, topPx);
            }

            function clearTextAnnotationBounds(annotation, pageInfo, leftPx, topPx) {
                delete annotation.pdfWidth;
                delete annotation.pdfHeight;
                setTextAnnotationPosition(annotation, pageInfo, leftPx, topPx);
            }

            function countTextBoxEditorLines(input) {
                if (!input) {
                    return 1;
                }

                const computedStyle = window.getComputedStyle(input);
                const fontSizePx = parseFloat(computedStyle.fontSize || '0') || 16;
                const lineHeightPx = parseFloat(computedStyle.lineHeight || '0') || (fontSizePx * 1.2);
                const probe = document.createElement('div');
                probe.style.position = 'absolute';
                probe.style.visibility = 'hidden';
                probe.style.pointerEvents = 'none';
                probe.style.left = '-99999px';
                probe.style.top = '-99999px';
                probe.style.width = `${Math.max(1, input.clientWidth || input.offsetWidth || 1)}px`;
                probe.style.boxSizing = 'border-box';
                probe.style.padding = computedStyle.padding;
                probe.style.fontFamily = computedStyle.fontFamily;
                probe.style.fontSize = computedStyle.fontSize;
                probe.style.fontWeight = computedStyle.fontWeight;
                probe.style.fontStyle = computedStyle.fontStyle;
                probe.style.letterSpacing = computedStyle.letterSpacing;
                probe.style.lineHeight = computedStyle.lineHeight;
                probe.style.textAlign = computedStyle.textAlign;
                probe.style.whiteSpace = 'pre-wrap';
                probe.style.overflowWrap = 'break-word';
                probe.textContent = getOverlayExplicitText(input) || ' ';
                document.body.appendChild(probe);
                const measuredHeight = probe.getBoundingClientRect().height || lineHeightPx;
                probe.remove();
                return Math.max(1, Math.round(measuredHeight / Math.max(lineHeightPx, 1)));
            }

            /**
             * Measures the natural (unconstrained) rendered height of the content inside
             * a tbc-input contenteditable div by cloning its styles and HTML into a
             * probe element with no min-height / height constraints.
             * Used so the annotation bounding box always collapses to fit the text.
             */
            function measureInputContentHeight(input) {
                if (!input) return 0;
                const cs = window.getComputedStyle(input);
                const probe = document.createElement('div');
                probe.style.position = 'absolute';
                probe.style.visibility = 'hidden';
                probe.style.pointerEvents = 'none';
                probe.style.left = '-99999px';
                probe.style.top = '-99999px';
                probe.style.width = `${Math.max(1, input.offsetWidth || 1)}px`;
                probe.style.boxSizing = 'border-box';
                probe.style.padding = cs.padding;
                probe.style.fontFamily = cs.fontFamily;
                probe.style.fontSize = cs.fontSize;
                probe.style.fontWeight = cs.fontWeight;
                probe.style.fontStyle = cs.fontStyle;
                probe.style.letterSpacing = cs.letterSpacing;
                probe.style.lineHeight = cs.lineHeight;
                probe.style.textAlign = cs.textAlign;
                probe.style.whiteSpace = cs.whiteSpace || 'pre-wrap';
                probe.style.overflowWrap = cs.overflowWrap || 'break-word';
                probe.style.wordBreak = cs.wordBreak || 'normal';
                probe.innerHTML = input.innerHTML;
                document.body.appendChild(probe);
                const h = probe.getBoundingClientRect().height;
                probe.remove();
                return Math.max(1, h);
            }

            function shouldKeepTextAnnotationBounds({ text, input, dragW, dragH, editAnnotation }) {
                const hasRequestedBounds = Boolean(dragW || dragH || (editAnnotation && annotationHasBounds(editAnnotation)));
                if (!hasRequestedBounds) {
                    return false;
                }

                if (editAnnotation?.keepBounds) {
                    return true;
                }

                if (/(?:\r\n|\r|\n)/.test(text || '')) {
                    return true;
                }

                return countTextBoxEditorLines(input) > 1;
            }

            function resolveAnnotationPageContext(annotation) {
                if (!annotation) {
                    return null;
                }

                const wrapper = annotation.element?.closest('.page, .page-wrapper')
                    || viewer.querySelector(`.page[data-page-index="${annotation.pageIndex}"], .page-wrapper[data-page-number="${Number(annotation.pageIndex) + 1}"]`);
                if (!wrapper) {
                    return null;
                }

                const overlay = wrapper.querySelector('.overlay');
                const canvas = wrapper.querySelector('canvas');
                const canvasHeight = overlay?.clientHeight || canvas?.height || 0;
                if (!canvasHeight) {
                    return null;
                }

                return {
                    wrapper,
                    overlay,
                    canvas,
                    pageInfo: {
                        scale: currentScale,
                        canvasHeight,
                    },
                };
            }

            function rgbToCssColor(red, green, blue) {
                const clampChannel = (value) => Math.max(0, Math.min(255, Math.round(Number(value) || 0)));
                return `rgb(${clampChannel(red)}, ${clampChannel(green)}, ${clampChannel(blue)})`;
            }

            function sampleCanvasDominantColor(canvas, clientRect) {
                if (!(canvas instanceof HTMLCanvasElement) || !clientRect) {
                    return null;
                }

                const canvasRect = canvas.getBoundingClientRect();
                if (!canvasRect.width || !canvasRect.height || !canvas.width || !canvas.height) {
                    return null;
                }

                const left = Math.max(clientRect.left, canvasRect.left);
                const top = Math.max(clientRect.top, canvasRect.top);
                const right = Math.min(clientRect.right, canvasRect.right);
                const bottom = Math.min(clientRect.bottom, canvasRect.bottom);
                if (!(right > left) || !(bottom > top)) {
                    return null;
                }

                const scaleX = canvas.width / canvasRect.width;
                const scaleY = canvas.height / canvasRect.height;
                const sampleX = Math.max(0, Math.floor((left - canvasRect.left) * scaleX));
                const sampleY = Math.max(0, Math.floor((top - canvasRect.top) * scaleY));
                const sampleWidth = Math.max(1, Math.min(canvas.width - sampleX, Math.ceil((right - left) * scaleX)));
                const sampleHeight = Math.max(1, Math.min(canvas.height - sampleY, Math.ceil((bottom - top) * scaleY)));

                let imageData;
                try {
                    const context = canvas.getContext('2d', { willReadFrequently: true });
                    imageData = context?.getImageData(sampleX, sampleY, sampleWidth, sampleHeight)?.data || null;
                } catch (_error) {
                    return null;
                }
                if (!imageData?.length) {
                    return null;
                }

                const colorCounts = new Map();
                for (let index = 0; index < imageData.length; index += 4) {
                    const alpha = Number(imageData[index + 3]) || 0;
                    if (alpha < 200) {
                        continue;
                    }
                    const key = `${imageData[index]},${imageData[index + 1]},${imageData[index + 2]}`;
                    colorCounts.set(key, (colorCounts.get(key) || 0) + 1);
                }
                if (!colorCounts.size) {
                    return null;
                }

                let dominantKey = null;
                let dominantCount = -1;
                colorCounts.forEach((count, key) => {
                    if (count > dominantCount) {
                        dominantKey = key;
                        dominantCount = count;
                    }
                });
                if (!dominantKey) {
                    return null;
                }

                const [red, green, blue] = dominantKey.split(',').map((value) => Number(value) || 0);
                return rgbToCssColor(red, green, blue);
            }

            function samplePageCanvasDominantColorForElement(annotation, element) {
                if (!annotation || !(element instanceof HTMLElement)) {
                    return null;
                }
                const pageContext = resolveAnnotationPageContext(annotation);
                if (!(pageContext?.canvas instanceof HTMLCanvasElement)) {
                    return null;
                }
                return sampleCanvasDominantColor(pageContext.canvas, element.getBoundingClientRect());
            }

            function measureTextAnnotationContentBounds(annotation) {
                if (!annotation || (annotation.type && annotation.type !== 'text') || !annotation.element) {
                    return null;
                }

                const label = annotation.element;
                const textWrapper = annotation.textWrapper || label.querySelector('.text-content-wrapper');
                const textEl = label.querySelector('.annotation-text');
                if (!textEl) {
                    return null;
                }

                const labelStyle = window.getComputedStyle(label);
                const wrapperStyle = textWrapper ? window.getComputedStyle(textWrapper) : null;
                const textStyle = window.getComputedStyle(textEl);
                const labelPadX = (parseFloat(labelStyle.paddingLeft || '0') || 0) + (parseFloat(labelStyle.paddingRight || '0') || 0);
                const labelPadY = (parseFloat(labelStyle.paddingTop || '0') || 0) + (parseFloat(labelStyle.paddingBottom || '0') || 0);
                const wrapperPadX = (parseFloat(wrapperStyle?.paddingLeft || '0') || 0) + (parseFloat(wrapperStyle?.paddingRight || '0') || 0);
                const wrapperPadY = (parseFloat(wrapperStyle?.paddingTop || '0') || 0) + (parseFloat(wrapperStyle?.paddingBottom || '0') || 0);
                const textPadX = (parseFloat(textStyle.paddingLeft || '0') || 0) + (parseFloat(textStyle.paddingRight || '0') || 0);
                const textPadY = (parseFloat(textStyle.paddingTop || '0') || 0) + (parseFloat(textStyle.paddingBottom || '0') || 0);
                const textRect = textEl.getBoundingClientRect();

                return {
                    widthPx: Math.max(30, Math.ceil(textRect.width + labelPadX + wrapperPadX + textPadX)),
                    heightPx: Math.max(16, Math.ceil(textRect.height + labelPadY + wrapperPadY + textPadY)),
                };
            }

            function fitTextAnnotationBoundsToRenderedContent(annotation, pageInfo) {
                if (!annotationHasBounds(annotation) || !annotation?.element || !pageInfo || (annotation.type && annotation.type !== 'text')) {
                    return false;
                }
                if (
                    canRenderPromotedAnnotationWithExactGeometry(annotation)
                ) {
                    return false;
                }

                const label = annotation.element;
                const textWrapper = annotation.textWrapper || label.querySelector('.text-content-wrapper');
                const textEl = label.querySelector('.annotation-text');
                if (!textEl) {
                    return false;
                }

                const labelStyle = window.getComputedStyle(label);
                const wrapperStyle = textWrapper ? window.getComputedStyle(textWrapper) : null;
                const textStyle = window.getComputedStyle(textEl);
                const labelPadX = (parseFloat(labelStyle.paddingLeft || '0') || 0) + (parseFloat(labelStyle.paddingRight || '0') || 0);
                const labelPadY = (parseFloat(labelStyle.paddingTop || '0') || 0) + (parseFloat(labelStyle.paddingBottom || '0') || 0);
                const wrapperPadX = (parseFloat(wrapperStyle?.paddingLeft || '0') || 0) + (parseFloat(wrapperStyle?.paddingRight || '0') || 0);
                const wrapperPadY = (parseFloat(wrapperStyle?.paddingTop || '0') || 0) + (parseFloat(wrapperStyle?.paddingBottom || '0') || 0);
                const textPadX = (parseFloat(textStyle.paddingLeft || '0') || 0) + (parseFloat(textStyle.paddingRight || '0') || 0);
                const textPadY = (parseFloat(textStyle.paddingTop || '0') || 0) + (parseFloat(textStyle.paddingBottom || '0') || 0);
                const promotedExtraction = Boolean(annotation.promotedFromExtraction);
                const preservePromotedLines = promotedExtraction && !annotation.promotedReflowEnabled;
                const fontFamily = resolveAnnotationCssFontFamily(annotation.fontFamily, {
                    preferExact: promotedExtraction,
                    exactFontName: annotation.fontSourceName || annotation.fontFamily,
                });
                const fontSizePx = getAnnotationDisplayFontSizePx(annotation, currentScale);
                const widthSafety = promotedExtraction ? 4 : 2;
                const heightSafety = promotedExtraction ? 3 : 1;

                const requiredWidth = Math.max(
                    label.offsetWidth || 0,
                    Math.ceil((textEl.scrollWidth || textEl.getBoundingClientRect().width || 0) + labelPadX + wrapperPadX + textPadX + widthSafety)
                );
                const measuredLineWidth = preservePromotedLines
                    ? Math.max(
                        ...String(annotation.text || '')
                            .replace(/\r\n/g, '\n')
                            .replace(/\r/g, '\n')
                            .split('\n')
                            .map((line) => measureAnnotationTextWidth(line || ' ', fontSizePx, fontFamily, annotation.fontWeight, annotation.fontStyle))
                      )
                    : 0;
                const requiredHeight = Math.max(
                    label.offsetHeight || 0,
                    Math.ceil((textEl.scrollHeight || textEl.getBoundingClientRect().height || 0) + labelPadY + wrapperPadY + textPadY + heightSafety)
                );
                const exactRequiredWidth = measuredLineWidth > 0
                    ? Math.ceil(measuredLineWidth + labelPadX + wrapperPadX + textPadX + widthSafety)
                    : 0;

                const currentWidth = label.offsetWidth || 0;
                const currentHeight = label.offsetHeight || 0;
                const nextRequiredWidth = Math.max(requiredWidth, exactRequiredWidth);
                const widthNeedsGrowth = nextRequiredWidth > (currentWidth + 1);
                const heightNeedsGrowth = requiredHeight > (currentHeight + 1);

                if (!widthNeedsGrowth && !heightNeedsGrowth) {
                    return false;
                }

                setTextAnnotationBounds(
                    annotation,
                    pageInfo,
                    label.offsetLeft,
                    label.offsetTop,
                    Math.max(currentWidth, nextRequiredWidth),
                    Math.max(currentHeight, requiredHeight)
                );
                applyAnnotationStyle(annotation);
                return true;
            }

            let promotedAnnotationFontRefitToken = 0;

            function schedulePromotedAnnotationFontRefit() {
                if (!document.fonts || !document.fonts.ready) {
                    return;
                }

                const refitToken = ++promotedAnnotationFontRefitToken;
                const runRefit = () => {
                    if (refitToken !== promotedAnnotationFontRefitToken) {
                        return;
                    }

                    annotations.forEach((annotation) => {
                        if (!annotation?.promotedFromExtraction || !annotation?.element) {
                            return;
                        }
                        const pageContext = resolveAnnotationPageContext(annotation);
                        if (!pageContext?.pageInfo) {
                            return;
                        }
                        applyAnnotationStyle(annotation);
                        fitTextAnnotationBoundsToRenderedContent(annotation, pageContext.pageInfo);
                    });
                };

                window.setTimeout(() => {
                    document.fonts.ready.then(() => {
                        requestAnimationFrame(runRefit);
                        window.setTimeout(runRefit, 180);
                    });
                }, 0);
            }

            function buildCopiedAnnotationSnapshot(annotation) {
                const copied = JSON.parse(JSON.stringify(stripInternalAnnotationFields(annotation)));

                if (annotation.type === 'text' || !annotation.type) {
                    const pageContext = resolveAnnotationPageContext(annotation);
                    const leftPx = annotation.element ? annotation.element.offsetLeft : (annotation.pdfX * currentScale);
                    const topPx = pageContext ? (
                        annotation.element ? annotation.element.offsetTop : getTextAnnotationTopPx(annotation, pageContext.pageInfo)
                    ) : 0;
                    const measuredBounds = measureTextAnnotationContentBounds(annotation);

                    copied.__copyMeta = {
                        leftPx,
                        topPx,
                        widthPx: measuredBounds?.widthPx || null,
                        heightPx: measuredBounds?.heightPx || null,
                    };
                }

                return copied;
            }

            function createAnnotationFromCopiedSnapshot(copiedAnnotation, offsetPx = 10) {
                const newAnnotation = JSON.parse(JSON.stringify(copiedAnnotation));
                const copyMeta = newAnnotation.__copyMeta || null;
                delete newAnnotation.__copyMeta;
                delete newAnnotation.element;
                delete newAnnotation.textWrapper;
                delete newAnnotation.shapeSvg;
                newAnnotation.id = generateAnnotationId();

                if (newAnnotation.type === 'text' || !newAnnotation.type) {
                    const pageContext = resolveAnnotationPageContext(newAnnotation);
                    if (pageContext) {
                        const baseLeftPx = Number(copyMeta?.leftPx) || (Number(newAnnotation.pdfX) || 0) * currentScale;
                        const baseTopPx = Number(copyMeta?.topPx) || getTextAnnotationTopPx(newAnnotation, pageContext.pageInfo);
                        const widthPx = Number(copyMeta?.widthPx) || 0;
                        const heightPx = Number(copyMeta?.heightPx) || 0;

                        if (newAnnotation.keepBounds && widthPx > 0 && heightPx > 0) {
                            setTextAnnotationBounds(newAnnotation, pageContext.pageInfo, baseLeftPx + offsetPx, baseTopPx + offsetPx, widthPx, heightPx);
                        } else {
                            delete newAnnotation.keepBounds;
                            clearTextAnnotationBounds(newAnnotation, pageContext.pageInfo, baseLeftPx + offsetPx, baseTopPx + offsetPx);
                        }
                    } else {
                        newAnnotation.pdfX = (Number(newAnnotation.pdfX) || 0) + (offsetPx / currentScale);
                        newAnnotation.pdfY = (Number(newAnnotation.pdfY) || 0) + (offsetPx / currentScale);
                        delete newAnnotation.keepBounds;
                        delete newAnnotation.pdfWidth;
                        delete newAnnotation.pdfHeight;
                    }

                    normalizeTextAnnotation(newAnnotation);
                    return newAnnotation;
                }

                newAnnotation.pdfX = (Number(newAnnotation.pdfX) || 0) + (offsetPx / currentScale);
                newAnnotation.pdfY = (Number(newAnnotation.pdfY) || 0) + (offsetPx / currentScale);
                return newAnnotation;
            }

            function addPageThumbnail(pageNumber, canvas) {
                if (!pageList) {
                    return;
                }
                const thumb = document.createElement('div');
                thumb.className = 'page-thumb relative p-3 rounded-lg border border-gray-600/50 cursor-pointer transition-all hover:border-emerald-500/50 group';
                thumb.dataset.pageIndex = String(pageNumber - 1);

                const thumbCanvas = document.createElement('canvas');
                thumbCanvas.className = 'w-full h-auto rounded shadow-lg bg-white';
                const thumbWidth = 240; // Increased from 160 for sharper rendering
                const scale = thumbWidth / canvas.width;
                thumbCanvas.width = Math.round(canvas.width * scale);
                thumbCanvas.height = Math.round(canvas.height * scale);
                const thumbCtx = thumbCanvas.getContext('2d');
                // Enable image smoothing for better quality
                thumbCtx.imageSmoothingEnabled = true;
                thumbCtx.imageSmoothingQuality = 'high';
                thumbCtx.drawImage(canvas, 0, 0, thumbCanvas.width, thumbCanvas.height);

                const label = document.createElement('span');
                label.className = 'block text-center text-sm text-gray-400 mt-2';
                label.textContent = String(pageNumber);

                // Create hover menu
                const hoverMenu = document.createElement('div');
                hoverMenu.id = 'page_controller';
                hoverMenu.className = 'absolute top-1 right-1 transition-opacity flex flex-col gap-1 bg-gray-800/95 rounded-lg shadow-xl p-1 backdrop-blur-sm z-10';
                hoverMenu.style.opacity = '0';
                hoverMenu.style.pointerEvents = 'auto';
                hoverMenu.innerHTML = `
                    <button class="add-page-btn btn btn-success btn-sm shadow-sm d-flex align-items-center justify-content-center" style="width: 32px; height: 32px; padding: 0;" title="Add blank page after">
                        <svg class="text-white" style="width: 16px; height: 16px;" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/>
                        </svg>
                    </button>
                    <button class="rotate-page-btn btn btn-primary btn-sm shadow-sm d-flex align-items-center justify-content-center" style="width: 32px; height: 32px; padding: 0;" title="Rotate page 90°">
                        <svg class="text-white" style="width: 16px; height: 16px;" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/>
                        </svg>
                    </button>
                    <div style="height: 8px;"></div>
                    <button class="delete-page-btn btn btn-danger btn-sm shadow-sm d-flex align-items-center justify-content-center" style="width: 32px; height: 32px; padding: 0; border: 2px solid #ff4444;" title="⚠️ Delete page permanently">
                        <svg class="text-white" style="width: 16px; height: 16px;" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/>
                        </svg>
                    </button>
                `;

                // Show menu on hover
                thumb.addEventListener('mouseenter', () => {
                    hoverMenu.style.opacity = '1';
                });
                thumb.addEventListener('mouseleave', () => {
                    hoverMenu.style.opacity = '0';
                });

                // Prevent menu clicks from triggering page selection
                hoverMenu.addEventListener('click', (e) => {
                    e.stopPropagation();
                });

                // Add page button handler - adds to DOM only, saved on save button
                hoverMenu.querySelector('.add-page-btn').addEventListener('click', async () => {
                    try {
                        // Get dimensions from the reference page
                        const refPageIndex = pageNumber - 1;
                        const refPage = await pdfjsDocument.getPage(refPageIndex + 1);
                        const viewport = refPage.getViewport({ scale: 1.0 });
                        
                        // Calculate pending page index
                        const pendingIdx = pendingNewPages.length;
                        const pendingPageId = 'pending-' + pendingIdx;
                        
                        // Track this pending new page (will be added during save)
                        const pendingPageData = {
                            id: pendingPageId,
                            insertAfter: refPageIndex,
                            width: viewport.width,
                            height: viewport.height,
                            annotations: [] // Annotations specific to this pending page
                        };
                        pendingNewPages.push(pendingPageData);
                        
                        // Create a visual placeholder in the thumbnail list
                        const thumbnailContainer = pageList;
                        if (!thumbnailContainer) {
                            throw new Error('Thumbnail container not found');
                        }
                        const existingThumbnails = thumbnailContainer.querySelectorAll('[data-page-index]');
                        const insertAfterElement = existingThumbnails[refPageIndex];
                        
                        // Calculate new page number (for display)
                        const newPageDisplayNumber = refPageIndex + 2; // +1 for 0-based, +1 for "after"
                        
                        // Create blank thumbnail placeholder
                        const wrapper = document.createElement('div');
                        wrapper.className = 'thumbnail-wrapper pending-page';
                        wrapper.dataset.pageIndex = pendingPageId;
                        wrapper.innerHTML = `
                            <div class="thumbnail-label">New Page</div>
                            <div class="thumbnail-canvas-wrapper" style="background: white; display: flex; align-items: center; justify-content: center; min-height: 150px; border: 2px dashed #28a745;">
                                <span style="color: #28a745; font-size: 24px;">📄</span>
                            </div>
                            <div class="thumbnail-hover-menu">
                                <button class="remove-pending-page-btn btn btn-danger btn-sm shadow-sm d-flex align-items-center justify-content-center" style="width: 32px; height: 32px; padding: 0;" title="Remove pending page">
                                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16"><path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5zm2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5zm3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0V6z"/><path fill-rule="evenodd" d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1v1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4H4.118zM2.5 3V2h11v1h-11z"/></svg>
                                </button>
                            </div>
                        `;
                        
                        // Insert after the reference page
                        if (insertAfterElement.nextSibling) {
                            thumbnailContainer.insertBefore(wrapper, insertAfterElement.nextSibling);
                        } else {
                            thumbnailContainer.appendChild(wrapper);
                        }
                        
                        // Add remove handler for pending page
                        wrapper.querySelector('.remove-pending-page-btn').addEventListener('click', (e) => {
                            e.stopPropagation();
                            // Find and remove from pendingNewPages array
                            const idx = pendingNewPages.findIndex(p => p.id === pendingPageId);
                            if (idx !== -1) {
                                // Also remove any annotations for this pending page
                                const pageAnnotations = pendingNewPages[idx].annotations || [];
                                for (const ann of pageAnnotations) {
                                    const annIdx = annotations.findIndex(a => a.id === ann.id);
                                    if (annIdx !== -1) annotations.splice(annIdx, 1);
                                }
                                pendingNewPages.splice(idx, 1);
                            }
                            wrapper.remove();
                            // Also remove from main viewer
                            const mainPageEl = viewer.querySelector(`.page[data-page-index="${pendingPageId}"]`);
                            if (mainPageEl) mainPageEl.remove();
                            updateAnnotationsList();
                            setStatus('Pending page removed.', 'ok');
                        });

                        // Click on pending thumbnail scrolls to it in main viewer
                        wrapper.addEventListener('click', () => {
                            const mainPageEl = viewer.querySelector(`.page[data-page-index="${pendingPageId}"], .page-wrapper[data-pending-id="${pendingPageId}"]`);
                            if (!mainPageEl) {
                                // Also try without the page-wrapper selector
                                const alt = viewer.querySelector(`[data-page-index="${pendingPageId}"]`);
                                if (alt) { alt.scrollIntoView({ behavior: 'smooth', block: 'center' }); return; }
                            }
                            if (mainPageEl) mainPageEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        });
                        wrapper.style.cursor = 'pointer';
                        
                        // Also add blank page to main viewer with interactive canvas
                        const scaledViewport = refPage.getViewport({ scale: currentScale });
                        const mainViewer = viewer;
                        // Fix: Select both standard pages and overlay pages
                        const existingPages = mainViewer.querySelectorAll('.page[data-page-index], .page-wrapper[data-page-number]');
                        const insertAfterMainPage = existingPages[refPageIndex];
                        
                        // Create blank page element for main viewer with proper canvas structure
                        const blankPageEl = document.createElement('div');
                        // Fix: Add page-wrapper class
                        blankPageEl.className = 'page page-wrapper pending-page';
                        blankPageEl.dataset.pageIndex = pendingPageId;
                        // Add pageNumber data attribute
                        blankPageEl.dataset.pageNumber = 'pending'; 
                        blankPageEl.style.cssText = `
                            position: relative;
                            width: ${scaledViewport.width}px;
                            height: ${scaledViewport.height}px;
                            margin: 10px auto;
                            box-shadow: 0 2px 8px rgba(0,0,0,0.3);
                        `;
                        
                        // Create a real canvas for the blank page
                        const blankCanvas = document.createElement('canvas');
                        blankCanvas.width = scaledViewport.width;
                        blankCanvas.height = scaledViewport.height;
                        blankCanvas.style.cssText = 'position: absolute; top: 0; left: 0; z-index: 1;';
                        const ctx = blankCanvas.getContext('2d');
                        ctx.fillStyle = 'white';
                        ctx.fillRect(0, 0, blankCanvas.width, blankCanvas.height);
                        
                        // Draw a subtle indicator that this is a new page
                        ctx.strokeStyle = '#28a745';
                        ctx.lineWidth = 2;
                        ctx.setLineDash([10, 5]);
                        ctx.strokeRect(10, 10, blankCanvas.width - 20, blankCanvas.height - 20);
                        ctx.setLineDash([]);
                        
                        // Add "New Page" watermark
                        ctx.fillStyle = 'rgba(40, 167, 69, 0.15)';
                        ctx.font = 'bold 48px Arial';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText('New Page', blankCanvas.width / 2, blankCanvas.height / 2);

                        // Add generation options (Temporary Overlay)
                        const genOptions = document.createElement('div');
                        genOptions.className = 'new-page-options';
                        genOptions.style.cssText = 'position: absolute; top: 60%; left: 50%; transform: translateX(-50%); display: flex; gap: 10px; z-index: 20; pointer-events: auto;';
                        genOptions.innerHTML = `
                            <a href="{{ route('documents.guided', $document) }}" class="btn btn-sm btn-success text-white shadow-sm" style="text-decoration: none;">Generate from Guided</a>
                            <button class="btn btn-sm btn-primary shadow-sm" onclick="document.querySelector('[data-tab-target=\\'#ai-generator\\']')?.click()">Generate from AI</button>
                        `;
                        blankPageEl.appendChild(genOptions);
                        
                        blankPageEl.appendChild(blankCanvas);
                        
                        // Create annotation layer for the blank page (same as regular pages)
                        const annotationLayer = document.createElement('div');
                        annotationLayer.className = 'annotation-layer';
                        annotationLayer.style.cssText = `
                            position: absolute;
                            top: 0;
                            left: 0;
                            width: 100%;
                            height: 100%;
                            pointer-events: none;
                            z-index: 5;
                        `;
                        blankPageEl.appendChild(annotationLayer);
                        
                        // Create an overlay for interactions (same as regular pages)
                        const overlay = document.createElement('div');
                        overlay.className = 'overlay pdf-overlay';
                        overlay.style.cssText = `
                            position: absolute;
                            top: 0;
                            left: 0;
                            width: 100%;
                            height: 100%;
                            cursor: crosshair;
                            pointer-events: auto;
                            z-index: 10;
                        `;
                        blankPageEl.appendChild(overlay);
                        
                        // Store canvas reference in pending page data
                        pendingPageData.canvas = blankCanvas;
                        pendingPageData.element = blankPageEl;
                        pendingPageData.scale = currentScale;
                        pendingPageData.overlay = overlay;
                        
                        const pageInfo = buildPageInfoForRender(overlay, blankCanvas, {
                            scale: currentScale,
                        });
                        
                        // Click handler for deselect when not in text mode
                        overlay.addEventListener('click', (event) => {
                            if (event.target !== overlay) return;
                            if (consumeSuppressedOverlayBackgroundClick(overlay, event)) return;
                            if (toolMode !== 'text') {
                                setSelection(null);
                                removeActiveEditor();
                            }
                        });
                        
                        // Drag-to-create text box for pending pages
                        (function setupPendingTextDrag(ov, pid, cv, el, pi) {
                            let dragState = null;
                            ov.addEventListener('pointerdown', (e) => {
                                if (toolMode !== 'text') return;
                                if (e.target !== ov) return;
                                e.preventDefault();
                                ov.setPointerCapture(e.pointerId);
                                const rect = ov.getBoundingClientRect();
                                const sx = e.clientX - rect.left;
                                const sy = e.clientY - rect.top;
                                const sel = document.createElement('div');
                                sel.className = 'text-drag-selection';
                                sel.style.left = sx + 'px';
                                sel.style.top = sy + 'px';
                                sel.style.width = '0';
                                sel.style.height = '0';
                                ov.appendChild(sel);
                                dragState = { startX: sx, startY: sy, sel, rect, moved: false };
                            });
                            ov.addEventListener('pointermove', (e) => {
                                if (!dragState) return;
                                const cx = e.clientX - dragState.rect.left;
                                const cy = e.clientY - dragState.rect.top;
                                const lx = Math.min(dragState.startX, cx);
                                const ly = Math.min(dragState.startY, cy);
                                const w = Math.abs(cx - dragState.startX);
                                const h = Math.abs(cy - dragState.startY);
                                dragState.sel.style.left = lx + 'px';
                                dragState.sel.style.top = ly + 'px';
                                dragState.sel.style.width = w + 'px';
                                dragState.sel.style.height = h + 'px';
                                if (w > 5 || h > 5) dragState.moved = true;
                            });
                            ov.addEventListener('pointerup', (e) => {
                                if (!dragState) return;
                                const ds = dragState;
                                dragState = null;
                                const cx = e.clientX - ds.rect.left;
                                const cy = e.clientY - ds.rect.top;
                                const bx = Math.min(ds.startX, cx);
                                const by = Math.min(ds.startY, cy);
                                const bw = Math.abs(cx - ds.startX);
                                const bh = Math.abs(cy - ds.startY);
                                ds.sel.remove();
                                const opts = readBannerOpts();
                                if (ds.moved && bw > 20 && bh > 10) {
                                    createTextBoxCreator(ov, bx, by, pid, cv, el, pi, opts, bw, bh);
                                } else {
                                    createTextBoxCreator(ov, bx, by, pid, cv, el, pi, opts);
                                }
                            });
                        })(overlay, pendingPageId, blankCanvas, blankPageEl, pageInfo);
                        
                        // Add shape drawing handlers for pending page
                        let pendingDrawingShape = null;
                        
                        overlay.addEventListener('pointerdown', (event) => {
                            if (toolMode !== 'shape') return;
                            // Don't start drawing if clicking on an existing annotation
                            if (event.target !== overlay && event.target.closest('.annotation')) {
                                return;
                            }
                            event.preventDefault();
                            overlay.setPointerCapture(event.pointerId);
                            
                            const rect = overlay.getBoundingClientRect();
                            const startX = event.clientX - rect.left;
                            const startY = event.clientY - rect.top;
                            
                            const shapeEl = document.createElement('div');
                            shapeEl.className = 'drawing-shape-preview';
                            shapeEl.style.cssText = `
                                position: absolute;
                                left: ${startX}px;
                                top: ${startY}px;
                                width: 0;
                                height: 0;
                                border: 2px dashed ${shapeStroke};
                                background: ${shapeFillTransparentState ? 'transparent' : shapeFill + '80'};
                                opacity: 0.7;
                                pointer-events: none;
                                z-index: 1000;
                                box-sizing: border-box;
                                ${shapeType === 'circle' || shapeType === 'ellipse' ? 'border-radius: 50%;' : ''}
                            `;
                            overlay.appendChild(shapeEl);
                            
                            pendingDrawingShape = {
                                element: shapeEl,
                                startX,
                                startY
                            };
                        });
                        
                        overlay.addEventListener('pointermove', (event) => {
                            if (!pendingDrawingShape || toolMode !== 'shape') return;
                            
                            const rect = overlay.getBoundingClientRect();
                            const currentX = event.clientX - rect.left;
                            const currentY = event.clientY - rect.top;

                            if (isLineShapeType(shapeType)) {
                                const snappedPoint = snapLineEndpoint(pendingDrawingShape.startX, pendingDrawingShape.startY, currentX, currentY);
                                const geometry = computeLineBoxGeometry(pendingDrawingShape.startX, pendingDrawingShape.startY, snappedPoint.x, snappedPoint.y);
                                pendingDrawingShape.lineStartX = geometry.lineStartX;
                                pendingDrawingShape.lineStartY = geometry.lineStartY;
                                pendingDrawingShape.lineEndX = geometry.lineEndX;
                                pendingDrawingShape.lineEndY = geometry.lineEndY;
                                pendingDrawingShape.element.style.left = geometry.left + 'px';
                                pendingDrawingShape.element.style.top = geometry.top + 'px';
                                pendingDrawingShape.element.style.width = geometry.width + 'px';
                                pendingDrawingShape.element.style.height = geometry.height + 'px';
                                return;
                            }

                            const left = Math.min(currentX, pendingDrawingShape.startX);
                            const top = Math.min(currentY, pendingDrawingShape.startY);
                            const width = Math.max(1, Math.abs(currentX - pendingDrawingShape.startX));
                            const height = Math.max(1, Math.abs(currentY - pendingDrawingShape.startY));

                            pendingDrawingShape.element.style.left = left + 'px';
                            pendingDrawingShape.element.style.top = top + 'px';
                            pendingDrawingShape.element.style.width = width + 'px';
                            pendingDrawingShape.element.style.height = height + 'px';
                        });
                        
                        overlay.addEventListener('pointerup', (event) => {
                            if (!pendingDrawingShape || toolMode !== 'shape') return;
                            const overlayRect = overlay.getBoundingClientRect();
                            const currentX = event.clientX - overlayRect.left;
                            const currentY = event.clientY - overlayRect.top;
                            const finalLineGeometry = isLineShapeType(shapeType)
                                ? (() => {
                                    const snappedPoint = snapLineEndpoint(pendingDrawingShape.startX, pendingDrawingShape.startY, currentX, currentY);
                                    return computeLineBoxGeometry(pendingDrawingShape.startX, pendingDrawingShape.startY, snappedPoint.x, snappedPoint.y);
                                })()
                                : null;
                            const shapeRect = pendingDrawingShape.element.getBoundingClientRect();
                            const width = finalLineGeometry ? finalLineGeometry.width : shapeRect.width;
                            const height = finalLineGeometry ? finalLineGeometry.height : shapeRect.height;
                            const lineLength = Math.hypot(currentX - pendingDrawingShape.startX, currentY - pendingDrawingShape.startY);

                            if ((isLineShapeType(shapeType) && lineLength < 10) || (!isLineShapeType(shapeType) && (width < 6 || height < 6))) {
                                pendingDrawingShape.element.remove();
                                pendingDrawingShape = null;
                                return;
                            }
                            
                            const left = finalLineGeometry ? finalLineGeometry.left : (shapeRect.left - overlayRect.left);
                            const top = finalLineGeometry ? finalLineGeometry.top : (shapeRect.top - overlayRect.top);
                            const pdfX = left / currentScale;
                            const pdfWidth = width / currentScale;
                            const pdfHeight = height / currentScale;
                            const pdfY = (overlay.clientHeight - top) / currentScale - pdfHeight;
                            
                            const annotation = {
                                id: generateAnnotationId(),
                                type: 'shape',
                                shapeType,
                                strokeColor: shapeStroke,
                                strokeWidth: shapeStrokeWidth,
                                strokeTransparent: shapeStrokeTransparentState,
                                fillColor: shapeFill,
                                fillTransparent: shapeFillTransparentState,
                                opacity: shapeOpacityValue,
                                pageIndex: pendingPageId,
                                pdfX,
                                pdfY,
                                pdfWidth,
                                pdfHeight
                            };
                            if (isLineShapeType(shapeType)) {
                                annotation.lineStartX = finalLineGeometry?.lineStartX ?? pendingDrawingShape.lineStartX ?? 0;
                                annotation.lineStartY = finalLineGeometry?.lineStartY ?? pendingDrawingShape.lineStartY ?? 0;
                                annotation.lineEndX = finalLineGeometry?.lineEndX ?? pendingDrawingShape.lineEndX ?? 1;
                                annotation.lineEndY = finalLineGeometry?.lineEndY ?? pendingDrawingShape.lineEndY ?? 0;
                            }
                            
                            annotations.push(annotation);
                            persistAnnotations();
                            updateAnnotationsList();
                            addAnnotationElement(blankPageEl, annotation, pageInfo);
                            pendingDrawingShape.element.remove();
                            pendingDrawingShape = null;
                            toolMode = 'edit-text';
                            setTimeout(() => {
                                updateModeButtons();
                                updateEditTextBanner();
                                setSelection(annotation);
                                setStatus('Shape added to new page. Click Save to keep changes.', 'ok');
                            }, 10);
                        });

                        // ─── Table drawing on pending page ───
                        let pendingDrawingTable = null;

                        overlay.addEventListener('pointerdown', (event) => {
                            if (toolMode !== 'table') return;
                            if (event.target !== overlay && event.target.closest('.annotation')) return;
                            event.preventDefault();
                            overlay.setPointerCapture(event.pointerId);
                            const rect = overlay.getBoundingClientRect();
                            const startX = event.clientX - rect.left;
                            const startY = event.clientY - rect.top;
                            const tableEl = document.createElement('div');
                            tableEl.style.cssText = `position:absolute;left:${startX}px;top:${startY}px;width:0;height:0;border:${tableStrokeWidth}px solid ${tableStroke};background:${tableFillTransparent ? 'transparent' : tableFill};opacity:0.7;pointer-events:none;box-sizing:border-box;z-index:1000;`;
                            overlay.appendChild(tableEl);
                            pendingDrawingTable = { element: tableEl, startX, startY };
                        });

                        overlay.addEventListener('pointermove', (event) => {
                            if (!pendingDrawingTable || toolMode !== 'table') return;
                            const rect = overlay.getBoundingClientRect();
                            const currentX = event.clientX - rect.left;
                            const currentY = event.clientY - rect.top;
                            const left = Math.min(currentX, pendingDrawingTable.startX);
                            const top = Math.min(currentY, pendingDrawingTable.startY);
                            const width = Math.max(1, Math.abs(currentX - pendingDrawingTable.startX));
                            const height = Math.max(1, Math.abs(currentY - pendingDrawingTable.startY));
                            pendingDrawingTable.element.style.left = left + 'px';
                            pendingDrawingTable.element.style.top = top + 'px';
                            pendingDrawingTable.element.style.width = width + 'px';
                            pendingDrawingTable.element.style.height = height + 'px';
                        });

                        overlay.addEventListener('pointerup', (event) => {
                            if (!pendingDrawingTable || toolMode !== 'table') return;
                            const elRect = pendingDrawingTable.element.getBoundingClientRect();
                            const overlayRect = overlay.getBoundingClientRect();
                            const width = elRect.width;
                            const height = elRect.height;
                            if (width < 10 || height < 10) {
                                pendingDrawingTable.element.remove();
                                pendingDrawingTable = null;
                                return;
                            }
                            const left = elRect.left - overlayRect.left;
                            const top = elRect.top - overlayRect.top;
                            const pdfX = left / currentScale;
                            const pdfWidth = width / currentScale;
                            const pdfHeight = height / currentScale;
                            const pdfY = (overlay.clientHeight - top) / currentScale - pdfHeight;
                            const annotation = {
                                id: generateAnnotationId(),
                                type: 'table',
                                rows: tableRows,
                                cols: tableCols,
                                strokeColor: tableStroke,
                                strokeWidth: tableStrokeWidth,
                                fillColor: tableFill,
                                fillTransparent: tableFillTransparent,
                                outerBorder: tableOuterBorder,
                                opacity: 1,
                                pageIndex: pendingPageId,
                                pdfX, pdfY, pdfWidth, pdfHeight,
                            };
                            annotations.push(annotation);
                            persistAnnotations();
                            updateAnnotationsList();
                            addAnnotationElement(blankPageEl, annotation, pageInfo);
                            pendingDrawingTable.element.remove();
                            pendingDrawingTable = null;
                            toolMode = 'edit-text';
                            updateModeButtons();
                            updateEditTextBanner();
                            setSelection(annotation);
                            setStatus('Table added to new page. Click Save to keep changes.', 'ok');
                        });

                        // Insert after the reference page in main viewer
                        if (insertAfterMainPage && insertAfterMainPage.nextSibling) {
                            mainViewer.insertBefore(blankPageEl, insertAfterMainPage.nextSibling);
                        } else if (insertAfterMainPage) {
                            mainViewer.appendChild(blankPageEl);
                        }
                        
                        // Scroll to the new page
                        blankPageEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        
                        setStatus('Blank page added after page ' + pageNumber + '. Click to add annotations, then save.', 'ok');
                    } catch (error) {
                        console.error('Error preparing blank page:', error);
                        setStatus('Error preparing page: ' + error.message, 'err');
                    }
                });

                // Rotate page button handler
                hoverMenu.querySelector('.rotate-page-btn').addEventListener('click', async () => {
                    const pageIndex = pageNumber - 1;
                    console.log(`[ROTATE] Page ${pageNumber} rotation requested`);
                    
                    // Update rotation state (90 degrees clockwise each click)
                    pageRotations[pageIndex] = (pageRotations[pageIndex] || 0) + 90;
                    if (pageRotations[pageIndex] >= 360) {
                        pageRotations[pageIndex] = 0;
                    }
                    
                    // Re-render the page with rotation
                    const pageWrapper = viewer.querySelector(`.page[data-page-index="${pageIndex}"]`);
                    if (pageWrapper && pdfjsDocument) {
                        try {
                            const page = await pdfjsDocument.getPage(pageNumber);
                            // Apply additional rotation on top of PDF's existing rotation
                            const existingRotation = page.rotate || 0;
                            const totalRotation = existingRotation + pageRotations[pageIndex];
                            const viewport = page.getViewport({ scale: currentScale, rotation: totalRotation });
                            
                            // Find the canvas in the page wrapper
                            const canvas = pageWrapper.querySelector('canvas');
                            if (canvas) {
                                const context = canvas.getContext('2d');
                                canvas.width = viewport.width;
                                canvas.height = viewport.height;
                                
                                // Re-render the page with rotation
                                await page.render({ canvasContext: context, viewport }).promise;
                                
                                // Update wrapper dimensions
                                pageWrapper.style.width = viewport.width + 'px';
                                pageWrapper.style.height = viewport.height + 'px';
                                
                                // Re-render the thumbnail with rotation
                                const thumbWidth = 240;
                                const thumbViewport = page.getViewport({ scale: thumbWidth / viewport.width, rotation: totalRotation });
                                thumbCanvas.width = thumbViewport.width;
                                thumbCanvas.height = thumbViewport.height;
                                const thumbCtx = thumbCanvas.getContext('2d');
                                thumbCtx.imageSmoothingEnabled = true;
                                thumbCtx.imageSmoothingQuality = 'high';
                                
                                // Clear any previous CSS transforms
                                thumbCanvas.style.transform = '';
                                
                                // Render the rotated page to the thumbnail
                                await page.render({ 
                                    canvasContext: thumbCtx, 
                                    viewport: thumbViewport 
                                }).promise;
                            }
                        } catch (error) {
                            console.error('Error re-rendering rotated page:', error);
                        }
                    }
                    
                    setStatus(`Page ${pageNumber} rotated ${pageRotations[pageIndex]}°. Click Save PDF to apply.`, 'ok');
                });

                // Delete page button handler
                hoverMenu.querySelector('.delete-page-btn').addEventListener('click', async () => {
                    console.log(`[DELETE] Page ${pageNumber} delete requested`);
                    
                    // Count visible (non-deleted) pages
                    const visiblePageCount = totalPages - pendingDeletedPages.length;
                    
                    if (visiblePageCount <= 1) {
                        alert('Cannot delete the last page of the document.');
                        return;
                    }
                    
                    if (!confirm('⚠️ DELETE PAGE ' + pageNumber + '?\n\nThis page will be removed. Click Save PDF to make the deletion permanent.\n\nAre you sure?')) {
                        console.log(`[DELETE] Page ${pageNumber} delete cancelled by user`);
                        return;
                    }
                    
                    console.log(`[DELETE] Page ${pageNumber} delete confirmed by user`);
                    
                    const pageIndex = pageNumber - 1;
                    
                    // Track this page for deletion on save
                    if (!pendingDeletedPages.includes(pageIndex)) {
                        pendingDeletedPages.push(pageIndex);
                    }
                    
                    // Remove annotations for this page from the local array
                    const annotationsToRemove = annotations.filter(a => a.pageIndex === pageIndex);
                    annotationsToRemove.forEach(ann => {
                        const idx = annotations.indexOf(ann);
                        if (idx >= 0) annotations.splice(idx, 1);
                    });
                    updateAnnotationsList();
                    persistAnnotations();
                    
                    // Remove page from main viewer DOM
                    const pageWrapper = viewer.querySelector(`.page[data-page-index="${pageIndex}"]`);
                    if (pageWrapper) {
                        pageWrapper.remove();
                    }
                    
                    // Remove thumbnail from sidebar
                    thumb.remove();
                    
                    // Update page numbers on remaining thumbnails
                    const remainingThumbs = pageList.querySelectorAll('.page-thumb');
                    remainingThumbs.forEach((t, idx) => {
                        const labelEl = t.querySelector('span');
                        if (labelEl) {
                            // Recalculate visual page number (excluding deleted pages)
                            const originalIndex = parseInt(t.dataset.pageIndex || idx);
                            let visualNum = 1;
                            for (let i = 0; i <= originalIndex; i++) {
                                if (!pendingDeletedPages.includes(i)) {
                                    if (i === originalIndex) break;
                                    visualNum++;
                                }
                            }
                        }
                    });
                    
                    setStatus(`Page ${pageNumber} marked for deletion. Click Save PDF to apply.`, 'ok');
                });

                thumb.appendChild(thumbCanvas);
                thumb.appendChild(label);
                thumb.appendChild(hoverMenu);

                thumb.addEventListener('click', () => {
                    pageList.querySelectorAll('.page-thumb-active').forEach((item) => {
                        item.classList.remove('page-thumb-active', 'border-emerald-500', 'ring-2', 'ring-emerald-500/30');
                        item.classList.add('border-gray-600/50');
                    });
                    thumb.classList.remove('border-gray-600/50');
                    thumb.classList.add('page-thumb-active', 'border-emerald-500', 'ring-2', 'ring-emerald-500/30');
                    const target = viewer.querySelector(
                        `.page[data-page-index="${pageNumber - 1}"], .overlay-page[data-page-number="${pageNumber}"]`
                    );
                    if (target) {
                        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                    // Close sidebar on mobile after selection
                    if (window.innerWidth < 1024) {
                        sidebar.classList.add('-translate-x-full');
                    }
                });

                if (pageNumber === 1) {
                    thumb.classList.remove('border-gray-600/50');
                    thumb.classList.add('page-thumb-active', 'border-emerald-500', 'ring-2', 'ring-emerald-500/30');
                }
                pageList.appendChild(thumb);
            }

            function getVisiblePage() {
                // Use the scroll-tracked current page from pageJumpInput if available
                const trackedPageNum = pageJumpInput ? parseInt(pageJumpInput.value || '1', 10) : NaN;
                if (Number.isFinite(trackedPageNum) && trackedPageNum >= 1) {
                    const byPageNumber = viewer.querySelector(`.overlay-page[data-page-number="${trackedPageNum}"]`);
                    if (byPageNumber) return byPageNumber;
                    const byPageIndex = viewer.querySelector(`.page[data-page-index="${trackedPageNum - 1}"]`);
                    if (byPageIndex) return byPageIndex;
                }

                // Fallback: find the page with the most vertical overlap with the viewer
                const viewerRect = viewer.getBoundingClientRect();
                const pages = viewer.querySelectorAll('.page, .overlay-page');
                let bestPage = pages[0] || null;
                let bestOverlap = -Infinity;
                pages.forEach(page => {
                    const rect = page.getBoundingClientRect();
                    const overlap = Math.min(rect.bottom, viewerRect.bottom) - Math.max(rect.top, viewerRect.top);
                    if (overlap > bestOverlap) {
                        bestOverlap = overlap;
                        bestPage = page;
                    }
                });
                return bestPage;
            }

            function placeImageBackedAnnotationOnVisiblePage({
                type,
                dataUrl,
                intrinsicWidth,
                intrinsicHeight,
                fileName = null,
                mimeType = null,
                preferredWidthPx = 220,
                maxWidthFraction = 0.35,
                maxHeightFraction = 0.25,
                fallbackWidthPx = 180,
                statusMessage = 'Annotation placed. Click Save to keep changes.',
            }) {
                if (!dataUrl) {
                    return;
                }

                const buildAnnotation = (pageIndex, pdfX, pdfY, pdfWidth, pdfHeight) => ({
                    id: generateAnnotationId(),
                    type,
                    dataUrl,
                    src: null,
                    fileName: fileName || undefined,
                    mimeType: mimeType || undefined,
                    pageIndex,
                    pdfX,
                    pdfY,
                    pdfWidth,
                    pdfHeight,
                });

                const safeIntrinsicWidth = Math.max(1, Number(intrinsicWidth) || 1);
                const safeIntrinsicHeight = Math.max(1, Number(intrinsicHeight) || 1);
                const aspectRatio = safeIntrinsicWidth / safeIntrinsicHeight;
                const wrapper = getVisiblePage() || viewer.querySelector('.page') || viewer.querySelector('.overlay-page');
                if (!wrapper) {
                    const fallbackWidth = fallbackWidthPx / currentScale;
                    const fallbackHeight = Math.max(24 / currentScale, fallbackWidth / aspectRatio);
                    const annotation = buildAnnotation(0, 72, 72, fallbackWidth, fallbackHeight);
                    annotations.push(annotation);
                    persistAnnotations();
                    updateAnnotationsList();
                    rerenderPdf();
                    return;
                }

                const canvas = wrapper.querySelector('canvas');
                const overlay = wrapper.querySelector('.overlay');
                if (!canvas || !overlay) {
                    return;
                }

                const pdfPageWidth = canvas.width / currentScale;
                const pdfPageHeight = canvas.height / currentScale;
                const maxWidthPx = Math.max(60, Math.min(preferredWidthPx, canvas.width * maxWidthFraction));
                const maxHeightPx = Math.max(60, canvas.height * maxHeightFraction);
                let targetWidthPx = maxWidthPx;
                let targetHeightPx = targetWidthPx / aspectRatio;
                if (targetHeightPx > maxHeightPx) {
                    targetHeightPx = maxHeightPx;
                    targetWidthPx = targetHeightPx * aspectRatio;
                }

                const pdfWidth = targetWidthPx / currentScale;
                const pdfHeight = targetHeightPx / currentScale;
                const pdfX = Math.max(12 / currentScale, (pdfPageWidth - pdfWidth) / 2);
                const pdfY = Math.max(12 / currentScale, (pdfPageHeight - pdfHeight) / 2);

                const annotation = buildAnnotation(
                    wrapper.dataset.pageIndex.startsWith('pending-')
                        ? wrapper.dataset.pageIndex
                        : (parseInt(wrapper.dataset.pageIndex || '0', 10) || 0),
                    pdfX,
                    pdfY,
                    pdfWidth,
                    pdfHeight,
                );

                annotations.push(annotation);
                persistAnnotations();
                updateAnnotationsList();
                addAnnotationElement(
                    wrapper,
                    annotation,
                    buildPageInfoForRender(overlay, canvas, { scale: currentScale })
                );
                if (annotationInteractionsRequireEditTextMode({ type })) {
                    toolMode = 'edit-text';
                    updateModeButtons();
                    updateEditTextBanner();
                }
                setSelection(annotation);
                saveAnnotationToDatabase(annotation);
                setStatus(statusMessage, 'ok');
            }

            function placeSignatureOnFirstPage() {
                placeImageBackedAnnotationOnVisiblePage({
                    type: 'signature',
                    dataUrl: signatureDataUrl,
                    intrinsicWidth: signatureCanvas?.width || 900,
                    intrinsicHeight: signatureCanvas?.height || 300,
                    preferredWidthPx: 220,
                    maxWidthFraction: 0.35,
                    maxHeightFraction: 0.18,
                    fallbackWidthPx: 180,
                    statusMessage: 'Signature placed. Click Save to keep changes.',
                });
            }

            function placeImportedImageOnVisiblePage(imageAsset) {
                if (!imageAsset?.dataUrl) {
                    return;
                }
                placeImageBackedAnnotationOnVisiblePage({
                    type: 'image',
                    dataUrl: imageAsset.dataUrl,
                    intrinsicWidth: imageAsset.width,
                    intrinsicHeight: imageAsset.height,
                    fileName: imageAsset.fileName,
                    mimeType: imageAsset.mimeType,
                    preferredWidthPx: 260,
                    maxWidthFraction: 0.4,
                    maxHeightFraction: 0.35,
                    fallbackWidthPx: 220,
                    statusMessage: 'Image placed. Click Save to keep changes.',
                });
            }

            function placeImageBackedAnnotationAtPageBox({
                wrapper,
                pageInfo,
                type = 'image',
                dataUrl,
                pageIndex,
                pdfX,
                pdfY,
                pdfWidth,
                pdfHeight,
                fileName = null,
                mimeType = 'image/png',
                statusMessage = 'Annotation placed. Click Save to keep changes.',
            }) {
                if (!wrapper || !pageInfo || !dataUrl) {
                    return null;
                }

                const annotation = {
                    id: generateAnnotationId(),
                    type,
                    dataUrl,
                    src: null,
                    fileName: fileName || undefined,
                    mimeType: mimeType || undefined,
                    pageIndex,
                    pdfX,
                    pdfY,
                    pdfWidth,
                    pdfHeight,
                };

                annotations.push(annotation);
                persistAnnotations();
                updateAnnotationsList();
                addAnnotationElement(wrapper, annotation, pageInfo);
                if (annotationInteractionsRequireEditTextMode(annotation)) {
                    toolMode = 'edit-text';
                    updateModeButtons();
                    updateEditTextBanner();
                }
                setSelection(annotation);
                saveAnnotationToDatabase(annotation);
                setStatus(statusMessage, 'ok');
                return annotation;
            }

            function createFieldAnnotation(pageNumber, pageInfo, leftPx, topPx, widthPx, heightPx) {
                const normalizedFieldKind = normalizeFieldKind(fieldType);
                const minWidthPx = normalizedFieldKind === 'checkbox'
                    ? 28
                    : (normalizedFieldKind === 'signature' ? 220 : (normalizedFieldKind === 'list' ? 180 : (normalizedFieldKind === 'select' ? 180 : 140)));
                const minHeightPx = normalizedFieldKind === 'checkbox'
                    ? 28
                    : (normalizedFieldKind === 'signature' ? 52 : (normalizedFieldKind === 'list' ? 88 : (normalizedFieldKind === 'select' ? 40 : 40)));
                let nextWidthPx = Math.max(minWidthPx, Number(widthPx) || minWidthPx);
                let nextHeightPx = Math.max(minHeightPx, Number(heightPx) || minHeightPx);
                if (normalizedFieldKind === 'checkbox') {
                    const squareSize = Math.max(nextWidthPx, nextHeightPx);
                    nextWidthPx = squareSize;
                    nextHeightPx = squareSize;
                }

                const annotation = {
                    id: generateAnnotationId(),
                    type: 'field',
                    fieldKind: normalizedFieldKind,
                    fieldName: `field_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
                    placeholder: normalizedFieldKind === 'date'
                        ? 'MM/DD/YYYY'
                        : (normalizedFieldKind === 'signature' ? 'Sign here' : (isOptionFieldKind(normalizedFieldKind) ? 'Select option' : 'Type here')),
                    fieldValue: isOptionFieldKind(normalizedFieldKind) ? 'Option 1' : '',
                    fieldOptions: isOptionFieldKind(normalizedFieldKind) ? getDefaultOptionFieldOptions(normalizedFieldKind) : [],
                    checked: false,
                    pageIndex: pageNumber - 1,
                    pdfX: leftPx / pageInfo.scale,
                    pdfY: (pageInfo.canvasHeight - topPx) / pageInfo.scale - (nextHeightPx / pageInfo.scale),
                    pdfWidth: nextWidthPx / pageInfo.scale,
                    pdfHeight: nextHeightPx / pageInfo.scale,
                    fontSize: 12,
                    textColor: normalizedFieldKind === 'signature' ? '#ffffff' : '#334155',
                    backgroundColor: (normalizedFieldKind === 'checkbox' || isOptionFieldKind(normalizedFieldKind)) ? '#ffffff' : '#e0e7ff',
                    borderColor: normalizedFieldKind === 'signature' ? '#818cf8' : '#64748b',
                    accentColor: normalizedFieldKind === 'signature' ? '#4f46e5' : '#64748b',
                    borderWidth: 1.5,
                    opacity: 1,
                };

                normalizeFieldAnnotation(annotation);
                return annotation;
            }

            function createSignatureFieldShell() {
                const shell = document.createElement('div');
                shell.className = 'field-annotation-shell field-annotation-signature-shell';

                const badge = document.createElement('div');
                badge.className = 'field-annotation-signature-badge';
                badge.textContent = 'sign';

                const content = document.createElement('div');
                content.className = 'field-annotation-signature-content';

                const placeholder = document.createElement('div');
                placeholder.className = 'field-annotation-signature-placeholder';
                placeholder.textContent = 'Sign here';

                const image = document.createElement('img');
                image.className = 'field-annotation-signature-image';
                image.alt = 'Signature';

                content.appendChild(placeholder);
                content.appendChild(image);
                shell.appendChild(badge);
                shell.appendChild(content);

                return {
                    shell,
                    badge,
                    content,
                    placeholder,
                    image,
                };
            }

            function createSelectFieldShell() {
                const shell = document.createElement('div');
                shell.className = 'field-annotation-shell field-annotation-select-shell';

                const value = document.createElement('div');
                value.className = 'field-annotation-select-value';
                value.textContent = 'Option 1';

                const caret = document.createElement('div');
                caret.className = 'field-annotation-select-caret';
                caret.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>';

                shell.appendChild(value);
                shell.appendChild(caret);

                return {
                    shell,
                    value,
                    caret,
                };
            }

            function createListFieldShell() {
                const shell = document.createElement('div');
                shell.className = 'field-annotation-shell field-annotation-list-shell';

                const items = document.createElement('div');
                items.className = 'field-annotation-list-items';
                shell.appendChild(items);

                return {
                    shell,
                    items,
                };
            }

            function createFieldPreviewElement(fieldKind) {
                const preview = document.createElement('div');
                preview.className = `annotation field-annotation field-annotation-preview field-annotation-${fieldKind}`;
                preview.style.position = 'absolute';
                preview.style.left = '0';
                preview.style.top = '0';
                preview.style.width = '1px';
                preview.style.height = '1px';

                const shell = document.createElement('div');
                shell.className = `field-annotation-shell ${fieldKind === 'checkbox' ? 'field-annotation-checkbox-shell' : ''}`;
                if (fieldKind === 'checkbox') {
                    const checkboxBox = document.createElement('div');
                    checkboxBox.className = 'field-annotation-checkbox-box';
                    const checkMark = document.createElement('span');
                    checkMark.className = 'field-annotation-checkbox-mark checked';
                    checkMark.textContent = '✓';
                    checkboxBox.appendChild(checkMark);
                    shell.appendChild(checkboxBox);
                } else if (fieldKind === 'signature') {
                    const signatureShell = createSignatureFieldShell();
                    preview.appendChild(signatureShell.shell);
                    return preview;
                } else if (fieldKind === 'select') {
                    const selectShell = createSelectFieldShell();
                    preview.appendChild(selectShell.shell);
                    return preview;
                } else if (fieldKind === 'list') {
                    const listShell = createListFieldShell();
                    ['Option 1', 'Option 2', 'Option 3'].forEach((option, index) => {
                        const item = document.createElement('div');
                        item.className = `field-annotation-list-item${index === 0 ? ' selected' : ''}`;
                        item.textContent = option;
                        listShell.items.appendChild(item);
                    });
                    preview.appendChild(listShell.shell);
                    return preview;
                } else {
                    const input = document.createElement('input');
                    input.type = 'text';
                    input.className = 'field-annotation-input';
                    input.placeholder = fieldKind === 'date' ? 'MM/DD/YYYY' : 'Type here';
                    input.value = '';
                    if (fieldKind === 'date') {
                        input.inputMode = 'numeric';
                        input.maxLength = 10;
                    }
                    shell.appendChild(input);
                }
                preview.appendChild(shell);
                return preview;
            }

            function setupFieldPlacementHandlers(overlay, wrapper, pageNumber, pageInfo) {
                if (!overlay || !wrapper || !pageInfo) {
                    return;
                }

                let pendingFieldPlacement = null;

                overlay.addEventListener('pointerdown', (event) => {
                    if (toolMode !== 'field' || event.target !== overlay) {
                        return;
                    }
                    const rect = overlay.getBoundingClientRect();
                    const startX = event.clientX - rect.left;
                    const startY = event.clientY - rect.top;
                    const preview = createFieldPreviewElement(getActiveFieldToolKind() || 'text');
                    preview.style.left = `${startX}px`;
                    preview.style.top = `${startY}px`;
                    overlay.appendChild(preview);
                    pendingFieldPlacement = {
                        startX,
                        startY,
                        preview,
                    };
                });

                overlay.addEventListener('pointermove', (event) => {
                    if (!pendingFieldPlacement || toolMode !== 'field') {
                        return;
                    }
                    const rect = overlay.getBoundingClientRect();
                    const currentX = Math.max(0, Math.min(overlay.clientWidth, event.clientX - rect.left));
                    const currentY = Math.max(0, Math.min(overlay.clientHeight, event.clientY - rect.top));
                    const fieldKind = getActiveFieldToolKind() || 'text';
                    let left = Math.min(currentX, pendingFieldPlacement.startX);
                    let top = Math.min(currentY, pendingFieldPlacement.startY);
                    let width = Math.max(1, Math.abs(currentX - pendingFieldPlacement.startX));
                    let height = Math.max(1, Math.abs(currentY - pendingFieldPlacement.startY));
                    if (fieldKind === 'checkbox') {
                        const squareSize = Math.max(width, height);
                        width = squareSize;
                        height = squareSize;
                        left = currentX >= pendingFieldPlacement.startX ? pendingFieldPlacement.startX : (pendingFieldPlacement.startX - squareSize);
                        top = currentY >= pendingFieldPlacement.startY ? pendingFieldPlacement.startY : (pendingFieldPlacement.startY - squareSize);
                    }
                    pendingFieldPlacement.preview.style.left = `${Math.max(0, left)}px`;
                    pendingFieldPlacement.preview.style.top = `${Math.max(0, top)}px`;
                    pendingFieldPlacement.preview.style.width = `${Math.max(1, width)}px`;
                    pendingFieldPlacement.preview.style.height = `${Math.max(1, height)}px`;
                });

                overlay.addEventListener('pointerup', (event) => {
                    if (!pendingFieldPlacement || toolMode !== 'field') {
                        return;
                    }
                    const preview = pendingFieldPlacement.preview;
                    const overlayRect = overlay.getBoundingClientRect();
                    const previewRect = preview.getBoundingClientRect();
                    let left = Math.max(0, previewRect.left - overlayRect.left);
                    let top = Math.max(0, previewRect.top - overlayRect.top);
                    let width = previewRect.width;
                    let height = previewRect.height;

                    preview.remove();
                    pendingFieldPlacement = null;

                    if (width < 8 || height < 8) {
                        const fieldKind = getActiveFieldToolKind() || 'text';
                        width = fieldKind === 'checkbox' ? 28 : (fieldKind === 'signature' ? 240 : (fieldKind === 'list' ? 200 : (fieldKind === 'select' ? 200 : 180)));
                        height = fieldKind === 'checkbox' ? 28 : (fieldKind === 'signature' ? 56 : (fieldKind === 'list' ? 96 : (fieldKind === 'select' ? 44 : 44)));
                        if (fieldKind === 'checkbox') {
                            width = height = 28;
                        }
                        const rect = overlay.getBoundingClientRect();
                        left = Math.max(0, Math.min(overlay.clientWidth - width, event.clientX - rect.left - (width / 2)));
                        top = Math.max(0, Math.min(overlay.clientHeight - height, event.clientY - rect.top - (height / 2)));
                    }

                    if (left + width > overlay.clientWidth) {
                        left = Math.max(0, overlay.clientWidth - width);
                    }
                    if (top + height > overlay.clientHeight) {
                        top = Math.max(0, overlay.clientHeight - height);
                    }

                    const annotation = createFieldAnnotation(pageNumber, pageInfo, left, top, width, height);
                    annotations.push(annotation);
                    persistAnnotations();
                    updateAnnotationsList();
                    addAnnotationElement(wrapper, annotation, pageInfo);
                    saveAnnotationToDatabase(annotation);
                    suppressNextOverlayBackgroundClick(overlay);
                    toolMode = 'select';
                    updateModeButtons();
                    updateEditTextBanner();
                    setSelection(annotation);
                    applyAnnotationStyle(annotation);
                    const statusMessage = annotation.fieldKind === 'signature'
                        ? 'Signature field added and selected. Use the Sign button in the floating menu or double click to sign.'
                        : (annotation.fieldKind === 'list'
                            ? 'List field added and selected. Use the floating menu to configure options or click a row to change the default selection.'
                            : (annotation.fieldKind === 'date'
                                ? 'Date field added and selected. Double click or use the floating menu to enter a date in MM/DD/YYYY format.'
                            : (isOptionFieldKind(annotation.fieldKind)
                            ? 'Select field added and selected. Use the floating menu to configure options.'
                            : `${getFieldAnnotationLabel(annotation)} added and selected. Use the floating menu or double click to edit text fields.`)));
                    setStatus(statusMessage, 'ok');
                });
            }

            function sanitizeTextForPdf(text) {
                if (!text) {
                    return text;
                }
                let sanitized = String(text)
                    .replace(/✕/g, 'X')
                    .replace(/×/g, 'x')
                    .replace(/☐/g, '[ ]')
                    .replace(/☑/g, '[x]')
                    .replace(/☒/g, '[x]')
                    .replace(/[‘’‚‛‹›]/g, "'")
                    .replace(/[“”„‟«»]/g, '"')
                    .replace(/[–—―]/g, '-')
                    .replace(/…/g, '...')
                    .replace(/\u00A0/g, ' ');
                try {
                    sanitized = sanitized.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
                } catch (error) {
                    // Ignore environments without Unicode normalization support.
                }
                sanitized = sanitized.replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '');
                return sanitized;
            }

            function sanitizePdfFormFieldName(value, fallback = 'field') {
                const normalized = String(value || fallback)
                    .replace(/[^A-Za-z0-9_.-]+/g, '_')
                    .replace(/^_+|_+$/g, '');
                return normalized || fallback;
            }

            function hexToPdfRgbComponents(hex, fallback = '#000000') {
                const source = String(hex || fallback || '#000000').trim();
                const normalized = /^#?[0-9a-f]{6}$/i.test(source)
                    ? source.replace('#', '')
                    : String(fallback || '#000000').replace('#', '');
                const value = parseInt(normalized, 16);
                return {
                    r: Number((((value >> 16) & 255) / 255).toFixed(4)),
                    g: Number((((value >> 8) & 255) / 255).toFixed(4)),
                    b: Number(((value & 255) / 255).toFixed(4)),
                };
            }

            function hexToPdfLibColor(hex, fallback = '#000000') {
                const { r, g, b } = hexToPdfRgbComponents(hex, fallback);
                return PDFLib.rgb(r, g, b);
            }

            async function applyExistingAcroFormEditorValuesToPdf(pdfDoc) {
                if (!pdfDoc || !hasAcroFormEditorChanges() || typeof pdfDoc.getForm !== 'function') {
                    return false;
                }

                const pdfForm = pdfDoc.getForm();
                if (!pdfForm) {
                    return false;
                }
                const appearanceFont = await pdfDoc.embedFont(PDFLib.StandardFonts.Helvetica);
                let applied = false;
                let needAppearancesEnabled = false;

                const enableNeedAppearances = () => {
                    if (needAppearancesEnabled) {
                        return;
                    }
                    if (pdfForm?.acroForm?.dict && PDFLib?.PDFName && PDFLib?.PDFBool) {
                        pdfForm.acroForm.dict.set(PDFLib.PDFName.of('NeedAppearances'), PDFLib.PDFBool.True);
                    }
                    needAppearancesEnabled = true;
                };

                const normalizeOverlayRect = (rectLike) => {
                    if (Array.isArray(rectLike) && rectLike.length >= 4) {
                        const rect = rectLike.slice(0, 4).map((value) => Number(value));
                        if (rect.every((value) => Number.isFinite(value))) {
                            return rect;
                        }
                    }
                    if (!rectLike || typeof rectLike !== 'object') {
                        return null;
                    }
                    const left = Number(rectLike.x ?? rectLike.left);
                    const bottom = Number(rectLike.y ?? rectLike.bottom);
                    const width = Number(rectLike.width);
                    const height = Number(rectLike.height);
                    if ([left, bottom, width, height].every((value) => Number.isFinite(value))) {
                        return [left, bottom, left + width, bottom + height];
                    }
                    const x1 = Number(rectLike.x1);
                    const y1 = Number(rectLike.y1);
                    const x2 = Number(rectLike.x2);
                    const y2 = Number(rectLike.y2);
                    if ([x1, y1, x2, y2].every((value) => Number.isFinite(value))) {
                        return [x1, y1, x2, y2];
                    }
                    return null;
                };

                const resolveOverlayRect = (entry, field) => {
                    const entryRect = normalizeOverlayRect(entry?.rect);
                    if (entryRect) {
                        return entryRect;
                    }
                    const widgets = typeof field?.acroField?.getWidgets === 'function'
                        ? field.acroField.getWidgets()
                        : [];
                    const widget = Array.isArray(widgets) ? widgets.find(Boolean) : null;
                    if (!widget) {
                        return null;
                    }
                    try {
                        if (typeof widget.getRectangle === 'function') {
                            const widgetRect = normalizeOverlayRect(widget.getRectangle());
                            if (widgetRect) {
                                return widgetRect;
                            }
                        }
                    } catch (_widgetRectError) {
                        // Fall through to other rect accessors below.
                    }
                    return normalizeOverlayRect(widget.rect);
                };

                const drawTextFieldOverlay = (entry, field) => {
                    const pageIndex = Number(entry?.pageIndex);
                    if (!Number.isInteger(pageIndex) || pageIndex < 0 || pageIndex >= pdfDoc.getPageCount()) {
                        return false;
                    }

                    const rect = resolveOverlayRect(entry, field);
                    if (!rect) {
                        return false;
                    }

                    const [x1, y1, x2, y2] = rect;
                    const left = Math.min(x1, x2);
                    const bottom = Math.min(y1, y2);
                    const width = Math.abs(x2 - x1);
                    const height = Math.abs(y2 - y1);
                    if (!(width > 1 && height > 1)) {
                        return false;
                    }

                    const rawValue = Array.isArray(entry?.value)
                        ? entry.value.map((value) => String(value ?? '')).join(', ')
                        : String(entry?.value ?? '');
                    const normalizedText = rawValue.replace(/\r\n?/g, '\n');
                    if (!normalizedText.trim()) {
                        return false;
                    }

                    const textColorHex = normalizeAcroFormFieldTextColor(entry?.textColor) || '#000000';
                    const textColor = hexToPdfLibColor(textColorHex, '#000000');
                    const page = pdfDoc.getPage(pageIndex);
                    const fontSize = Math.max(8, Math.min(12, height - 2));
                    const lineHeight = Math.max(fontSize * 1.15, fontSize + 1);
                    const maxLines = Math.max(1, Math.floor((height - 2) / lineHeight));
                    const lines = (entry?.multiLine ? normalizedText.split('\n') : [normalizedText.replace(/\n+/g, ' ')])
                        .map((line) => String(line ?? ''))
                        .filter((line) => line.length > 0)
                        .slice(0, maxLines);
                    if (!lines.length) {
                        return false;
                    }

                    const x = left + Math.min(6, Math.max(3, width * 0.04));
                    let y = bottom + Math.max(1, Math.floor((height - fontSize) / 2));
                    if (lines.length > 1) {
                        y = bottom + height - fontSize - 1;
                    }

                    lines.forEach((line, index) => {
                        page.drawText(line, {
                            x,
                            y: y - (index * lineHeight),
                            size: fontSize,
                            font: appearanceFont,
                            color: textColor,
                            lineHeight,
                        });
                    });
                    return true;
                };

                for (const entry of acroFormFieldChanges.values()) {
                    const fieldName = String(entry?.fieldName || '').trim();
                    if (!fieldName) {
                        continue;
                    }

                    let field = null;
                    try {
                        field = pdfForm.getField(fieldName);
                    } catch (_fieldLookupError) {
                        field = null;
                    }
                    if (!field) {
                        continue;
                    }

                    try {
                        if (entry.fieldType === 'BTN') {
                            enableNeedAppearances();
                            if (entry.radioButton && typeof field.select === 'function') {
                                const radioValue = String(entry.value || '').trim();
                                if (radioValue) {
                                    field.select(radioValue);
                                    applied = true;
                                }
                            } else if (entry.checkBox) {
                                if (Boolean(entry.value) && typeof field.check === 'function') {
                                    field.check();
                                    applied = true;
                                } else if (!Boolean(entry.value) && typeof field.uncheck === 'function') {
                                    field.uncheck();
                                    applied = true;
                                }
                            }
                            if (typeof field.updateAppearances === 'function') {
                                field.updateAppearances();
                            }
                            continue;
                        }

                        if ((entry.fieldType === 'TX' || entry.fieldType === 'CH') && drawTextFieldOverlay(entry, field)) {
                            applied = true;
                            continue;
                        }

                        if (entry.fieldType === 'CH' && typeof field.select === 'function') {
                            enableNeedAppearances();
                            if (Array.isArray(entry.value) && entry.value.length > 0) {
                                field.select(entry.value.map((value) => String(value ?? '')));
                            } else {
                                field.select(String(entry.value ?? ''));
                            }
                            if (typeof field.updateAppearances === 'function') {
                                field.updateAppearances(appearanceFont);
                            }
                            applied = true;
                            continue;
                        }

                        if (typeof field.setText === 'function') {
                            enableNeedAppearances();
                            field.setText(String(entry.value ?? ''));
                            if (typeof field.updateAppearances === 'function') {
                                field.updateAppearances(appearanceFont);
                            }
                            applied = true;
                        }
                    } catch (error) {
                        console.warn('Failed to apply AcroForm field value:', fieldName, error);
                    }
                }

                return applied;
            }

            async function appendInteractiveFieldAnnotationsToPdf(pdfDoc, fieldAnnotations) {
                if (!pdfDoc || !Array.isArray(fieldAnnotations) || fieldAnnotations.length === 0 || typeof pdfDoc.getForm !== 'function') {
                    return;
                }

                const pdfForm = pdfDoc.getForm();
                if (pdfForm?.acroForm?.dict && PDFLib?.PDFName && PDFLib?.PDFBool) {
                    pdfForm.acroForm.dict.set(PDFLib.PDFName.of('NeedAppearances'), PDFLib.PDFBool.True);
                }
                const formFont = await pdfDoc.embedFont(PDFLib.StandardFonts.Helvetica);
                const formBoldFont = await pdfDoc.embedFont(PDFLib.StandardFonts.HelveticaBold);
                const dataUrlToUint8 = (dataUrl) => {
                    const base64 = String(dataUrl || '').split(',')[1] || '';
                    const binary = atob(base64);
                    const bytes = new Uint8Array(binary.length);
                    for (let i = 0; i < binary.length; i += 1) {
                        bytes[i] = binary.charCodeAt(i);
                    }
                    return bytes;
                };
                const loadFieldSignatureImagePayload = async (annotation) => {
                    const signedDataUrl = String(annotation?.signedDataUrl || '').trim();
                    if (signedDataUrl.startsWith('data:image/')) {
                        const mimeMatch = signedDataUrl.match(/^data:([^;,]+)/i);
                        return {
                            bytes: dataUrlToUint8(signedDataUrl),
                            mimeType: String(mimeMatch?.[1] || annotation?.signedMimeType || 'image/png').toLowerCase(),
                        };
                    }

                    const imageUrl = getFieldSignatureImageUrl(annotation);
                    if (!imageUrl) {
                        return null;
                    }

                    const response = await fetch(imageUrl, {
                        credentials: 'same-origin',
                    });
                    if (!response.ok) {
                        throw new Error(`Failed to load field signature image (${response.status}).`);
                    }
                    return {
                        bytes: new Uint8Array(await response.arrayBuffer()),
                        mimeType: String(response.headers.get('content-type') || annotation?.signedMimeType || 'image/png').toLowerCase(),
                    };
                };
                const embedFieldSignatureImage = async (annotation) => {
                    const imagePayload = await loadFieldSignatureImagePayload(annotation);
                    if (!imagePayload?.bytes?.length) {
                        return null;
                    }
                    if (imagePayload.mimeType.includes('jpeg') || imagePayload.mimeType.includes('jpg')) {
                        return pdfDoc.embedJpg(imagePayload.bytes);
                    }
                    return pdfDoc.embedPng(imagePayload.bytes);
                };
                const drawSignatureField = async (page, annotation) => {
                    const x = Number(annotation.pdfX) || 0;
                    const y = Number(annotation.pdfY) || 0;
                    const width = Math.max(44, Number(annotation.pdfWidth) || 44);
                    const height = Math.max(22, Number(annotation.pdfHeight) || 22);
                    const borderWidth = Math.max(1, Number(annotation.borderWidth) || 1.5);
                    const backgroundColor = hexToPdfLibColor(annotation.backgroundColor || '#e0e7ff', '#e0e7ff');
                    const borderColor = hexToPdfLibColor(annotation.borderColor || '#818cf8', '#818cf8');
                    const accentColor = hexToPdfLibColor(annotation.accentColor || '#4f46e5', '#4f46e5');
                    const badgeWidth = Math.min(width * 0.34, Math.max(48, Math.min(94, width - 28)));
                    const placeholderColor = PDFLib.rgb(0.42, 0.4, 0.82);
                    const badgeLabel = String(annotation.signatureBadgeLabel || 'sign');

                    page.drawRectangle({
                        x,
                        y,
                        width,
                        height,
                        color: backgroundColor,
                        borderColor,
                        borderWidth,
                    });
                    page.drawRectangle({
                        x,
                        y,
                        width: badgeWidth,
                        height,
                        color: accentColor,
                        borderWidth: 0,
                    });

                    const badgeFontSize = Math.max(12, Math.min(height * 0.54, 28));
                    const badgeTextWidth = formBoldFont.widthOfTextAtSize(badgeLabel, badgeFontSize);
                    page.drawText(badgeLabel, {
                        x: x + Math.max(6, (badgeWidth - badgeTextWidth) / 2),
                        y: y + Math.max(4, (height - badgeFontSize) / 2) + (badgeFontSize * 0.1),
                        size: badgeFontSize,
                        font: formBoldFont,
                        color: PDFLib.rgb(1, 1, 1),
                    });

                    const contentX = x + badgeWidth;
                    const contentWidth = Math.max(12, width - badgeWidth);
                    const signedImage = await embedFieldSignatureImage(annotation);
                    if (signedImage) {
                        const imageDims = signedImage.scale(1);
                        const padding = Math.max(4, height * 0.12);
                        const availableWidth = Math.max(1, contentWidth - (padding * 2));
                        const availableHeight = Math.max(1, height - (padding * 2));
                        const scale = Math.min(availableWidth / imageDims.width, availableHeight / imageDims.height, 1);
                        const drawWidth = Math.max(1, imageDims.width * scale);
                        const drawHeight = Math.max(1, imageDims.height * scale);
                        page.drawImage(signedImage, {
                            x: contentX + Math.max(padding, (contentWidth - drawWidth) / 2),
                            y: y + Math.max(padding, (height - drawHeight) / 2),
                            width: drawWidth,
                            height: drawHeight,
                        });
                        return;
                    }

                    const placeholder = String(annotation.placeholder || '').trim();
                    if (placeholder) {
                        const placeholderFontSize = Math.max(8, Math.min(height * 0.24, 14));
                        const placeholderWidth = formFont.widthOfTextAtSize(placeholder, placeholderFontSize);
                        page.drawText(placeholder, {
                            x: contentX + Math.max(8, (contentWidth - placeholderWidth) / 2),
                            y: y + Math.max(4, (height - placeholderFontSize) / 2),
                            size: placeholderFontSize,
                            font: formFont,
                            color: placeholderColor,
                        });
                    }
                };

                for (let index = 0; index < fieldAnnotations.length; index += 1) {
                    const annotation = fieldAnnotations[index];
                    if (!annotation) {
                        continue;
                    }

                    const pageIndex = Number(annotation.pageIndex) || 0;
                    if (pageIndex < 0 || pageIndex >= pdfDoc.getPageCount()) {
                        continue;
                    }
                    const page = pdfDoc.getPage(pageIndex);
                    const fieldKind = normalizeFieldKind(annotation.fieldKind);

                    if (fieldKind === 'signature') {
                        await drawSignatureField(page, annotation);
                        continue;
                    }

                    const fieldNameBase = sanitizePdfFormFieldName(annotation.fieldName || annotation.id || `field_${index}`);
                    const fieldName = `${fieldNameBase}_${index}`;
                    const width = Math.max(12, Number(annotation.pdfWidth) || 12);
                    const height = Math.max(12, Number(annotation.pdfHeight) || 12);
                    const borderWidth = Math.max(1, Number(annotation.borderWidth) || 1.5);
                    const backgroundColor = hexToPdfLibColor(
                        annotation.backgroundColor || ((fieldKind === 'checkbox' || isOptionFieldKind(fieldKind)) ? '#ffffff' : '#e0e7ff'),
                        '#ffffff'
                    );
                    const borderColor = hexToPdfLibColor(annotation.borderColor || '#64748b', '#64748b');
                    const textColorComponents = hexToPdfRgbComponents(annotation.textColor || '#334155', '#334155');
                    const textColor = PDFLib.rgb(textColorComponents.r, textColorComponents.g, textColorComponents.b);

                    if (fieldKind === 'checkbox') {
                        const checkBox = pdfForm.createCheckBox(fieldName);
                        checkBox.addToPage(page, {
                            x: Number(annotation.pdfX) || 0,
                            y: Number(annotation.pdfY) || 0,
                            width,
                            height,
                            borderColor,
                            backgroundColor,
                            borderWidth,
                        });
                        if (annotation.checked) {
                            checkBox.check();
                        } else {
                            checkBox.uncheck();
                        }
                        checkBox.updateAppearances();
                        continue;
                    }

                    const fontSize = Math.max(8, Number(annotation.fontSize) || 12);
                    if (fieldKind === 'select') {
                        const dropdown = pdfForm.createDropdown(fieldName);
                        const selectOptions = getSelectFieldOptions(annotation, getDefaultOptionFieldOptions(fieldKind));
                        const selectedValue = getSelectFieldValue(annotation, selectOptions);
                        if (dropdown?.acroField && typeof dropdown.acroField.setDefaultAppearance === 'function') {
                            dropdown.acroField.setDefaultAppearance(
                                `${textColorComponents.r} ${textColorComponents.g} ${textColorComponents.b} rg\n/${formFont.name} ${fontSize} Tf`
                            );
                        }
                        dropdown.setOptions(selectOptions);
                        dropdown.select(selectedValue);
                        dropdown.disableEditing();
                        dropdown.disableMultiselect();
                        dropdown.enableSelectOnClick();
                        dropdown.addToPage(page, {
                            x: Number(annotation.pdfX) || 0,
                            y: Number(annotation.pdfY) || 0,
                            width,
                            height,
                            font: formFont,
                            textColor,
                            backgroundColor,
                            borderColor,
                            borderWidth,
                        });
                        dropdown.updateAppearances(formFont);
                        continue;
                    }

                    if (fieldKind === 'list') {
                        const optionList = pdfForm.createOptionList(fieldName);
                        const listOptions = getSelectFieldOptions(annotation, getDefaultOptionFieldOptions(fieldKind));
                        const selectedValue = getSelectFieldValue(annotation, listOptions);
                        if (optionList?.acroField && typeof optionList.acroField.setDefaultAppearance === 'function') {
                            optionList.acroField.setDefaultAppearance(
                                `${textColorComponents.r} ${textColorComponents.g} ${textColorComponents.b} rg\n/${formFont.name} ${fontSize} Tf`
                            );
                        }
                        optionList.setOptions(listOptions);
                        optionList.select(selectedValue);
                        optionList.disableMultiselect();
                        optionList.enableSelectOnClick();
                        optionList.addToPage(page, {
                            x: Number(annotation.pdfX) || 0,
                            y: Number(annotation.pdfY) || 0,
                            width,
                            height,
                            font: formFont,
                            textColor,
                            backgroundColor,
                            borderColor,
                            borderWidth,
                        });
                        optionList.updateAppearances(formFont);
                        continue;
                    }

                    const textField = pdfForm.createTextField(fieldName);
                    if (textField?.acroField && typeof textField.acroField.setDefaultAppearance === 'function') {
                        textField.acroField.setDefaultAppearance(
                            `${textColorComponents.r} ${textColorComponents.g} ${textColorComponents.b} rg\n/${formFont.name} ${fontSize} Tf`
                        );
                    }
                    textField.setText(String(annotation.fieldValue || ''));
                    textField.addToPage(page, {
                        x: Number(annotation.pdfX) || 0,
                        y: Number(annotation.pdfY) || 0,
                        width,
                        height,
                        font: formFont,
                        textColor,
                        backgroundColor,
                        borderColor,
                        borderWidth,
                    });
                    textField.updateAppearances(formFont);
                }
            }

            function getDownloadSourcePdfUrl() {
                const useCleanPdf = shouldUseCleanPdfForAnnotationSave();
                const useOriginalPdf = !useCleanPdf && shouldUseOriginalPdfForAnnotationSave();
                const sourceUrl = useOriginalPdf ? originalPdfUrl : (useCleanPdf ? cleanPdfUrl : pdfUrl);
                const joiner = sourceUrl.includes('?') ? '&' : '?';
                return `${sourceUrl}${joiner}v=${pdfVersion}`;
            }

            function generateSessionId() {
                return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            }

            function generateAnnotationId() {
                const id = 'ann_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
                knownAnnotationIds.add(id);
                return id;
            }

            function markPromotedAnnotationDirty(annotation) {
                if (annotation?.promotedFromExtraction) {
                    annotation.promotedDirty = true;
                }
            }

            function shouldEnablePromotedAnnotationReflow(annotationLike) {
                if (!annotationLike?.promotedFromExtraction || !annotationLike?.promotedDirty) {
                    return false;
                }
                if (!(Number(annotationLike?.pdfWidth) > 0) || !(Number(annotationLike?.pdfHeight) > 0)) {
                    return false;
                }

                const originalText = String(annotationLike?.originalText || '');
                if (originalText === '') {
                    return false;
                }

                if (String(annotationLike?.text || '') === originalText) {
                    return false;
                }

                return !canPreservePromotedAnnotationSourceLineLayout(annotationLike, annotationLike?.text, {
                    richTextHtml: annotationLike?.richTextHtml || '',
                });
            }

            function getPromotedAnnotationSourceLineCount(annotationLike) {
                const sourceMeta = getPromotedAnnotationSourceMeta(annotationLike);
                const sourceLineBoxes = Array.isArray(sourceMeta?.sourceLineBBoxes)
                    ? sourceMeta.sourceLineBBoxes.filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                    : [];
                if (sourceLineBoxes.length > 0) {
                    return sourceLineBoxes.length;
                }

                const sourceTextLines = Array.isArray(sourceMeta?.sourceTextLines)
                    ? sourceMeta.sourceTextLines
                        .map((line) => sanitizePromotedExtractionLine(line))
                        .filter((line) => line.length > 0)
                    : [];
                return sourceTextLines.length;
            }

            function getNormalizedPromotedAnnotationTextLines(value) {
                return sanitizePromotedExtractionText(value)
                    .split('\n')
                    .map((line) => sanitizePromotedExtractionLine(line))
                    .filter((line) => line.length > 0);
            }

            function getCanonicalPromotedAnnotationSourceText(annotation) {
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                const sourceTextLines = Array.isArray(sourceMeta?.sourceTextLines)
                    ? sourceMeta.sourceTextLines
                        .map((line) => sanitizePromotedExtractionLine(line))
                        .filter((line) => line.length > 0)
                    : [];
                if (sourceTextLines.length > 0) {
                    return sanitizePromotedExtractionText(sourceTextLines.join('\n'));
                }
                return sanitizePromotedExtractionText(annotation?.originalText || '');
            }

            function canPreservePromotedAnnotationSourceLineLayout(annotationLike, nextText = annotationLike?.text, { richTextHtml = annotationLike?.richTextHtml || '' } = {}) {
                if (!annotationLike?.promotedFromExtraction) {
                    return false;
                }
                if (!annotationHasBounds(annotationLike)) {
                    return false;
                }

                const sourceLineCount = getPromotedAnnotationSourceLineCount(annotationLike);
                if (sourceLineCount <= 0) {
                    return false;
                }

                if (annotationRichTextHasFormatting(richTextHtml)) {
                    const richLines = buildPromotedRichTextLineSegments(annotationLike, richTextHtml, nextText);
                    return richLines.length === sourceLineCount;
                }

                return getNormalizedPromotedAnnotationTextLines(nextText).length === sourceLineCount;
            }

            function syncPromotedAnnotationSourceTextLines(annotationLike, nextText) {
                if (!annotationLike?.promotedFromExtraction) {
                    return;
                }

                const sourceMeta = getPromotedAnnotationSourceMeta(annotationLike);
                if (!sourceMeta) {
                    return;
                }

                const nextLines = getNormalizedPromotedAnnotationTextLines(nextText);
                const sourceLineCount = getPromotedAnnotationSourceLineCount(annotationLike);
                if (!nextLines.length || nextLines.length !== sourceLineCount) {
                    return;
                }

                setPromotedAnnotationSourceMeta(annotationLike, {
                    ...sourceMeta,
                    sourceTextLines: nextLines,
                });
            }

            function normalizeComparableAnnotationNumber(value) {
                const numericValue = Number(value);
                if (!Number.isFinite(numericValue)) {
                    return null;
                }
                return Number(numericValue.toFixed(4));
            }

            function getComparableTextAnnotationState(annotation) {
                if (!annotation || (annotation.type && annotation.type !== 'text')) {
                    return '';
                }

                return JSON.stringify({
                    text: String(annotation.text || ''),
                    richTextHtml: typeof annotation.richTextHtml === 'string' ? annotation.richTextHtml : '',
                    fontSize: normalizeComparableAnnotationNumber(annotation.fontSize),
                    requestedFontSize: normalizeComparableAnnotationNumber(annotation.requestedFontSize),
                    fontFamily: String(annotation.fontFamily || ''),
                    textColor: String(annotation.textColor || ''),
                    backgroundColor: String(annotation.backgroundColor || ''),
                    fontWeight: String(annotation.fontWeight || ''),
                    fontStyle: String(annotation.fontStyle || ''),
                    underline: Boolean(annotation.underline),
                    textAlign: String(annotation.textAlign || ''),
                    opacity: normalizeComparableAnnotationNumber(annotation.opacity),
                    lineHeight: normalizeComparableAnnotationNumber(annotation.lineHeight),
                    keepBounds: Boolean(annotation.keepBounds),
                    pdfX: normalizeComparableAnnotationNumber(annotation.pdfX),
                    pdfY: normalizeComparableAnnotationNumber(annotation.pdfY),
                    pdfWidth: normalizeComparableAnnotationNumber(annotation.pdfWidth),
                    pdfHeight: normalizeComparableAnnotationNumber(annotation.pdfHeight),
                    promotedReflowEnabled: Boolean(annotation.promotedReflowEnabled),
                });
            }

            function matchesPromotedAnnotationExactSourceState(annotation) {
                if (!annotation?.promotedFromExtraction || annotation?.promotedReflowEnabled) {
                    return false;
                }
                if (annotationRichTextHasFormatting(annotation?.richTextHtml || '')) {
                    return false;
                }
                if (sanitizePromotedExtractionText(annotation?.text || '') !== getCanonicalPromotedAnnotationSourceText(annotation)) {
                    return false;
                }
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                if (!Array.isArray(sourceMeta?.sourceLineBBoxes) || sourceMeta.sourceLineBBoxes.length === 0) {
                    return false;
                }
                if (annotationHasBounds(annotation)) {
                    const sourceBlockLeft = Number(sourceMeta?.sourceBlockLeft);
                    const sourceBlockTop = Number(sourceMeta?.sourceBlockTop);
                    const sourceBlockWidth = Number(sourceMeta?.sourceBlockWidth);
                    const sourceBlockHeight = Number(sourceMeta?.sourceBlockHeight);
                    const sourcePageHeight = Number(sourceMeta?.sourcePageHeight);
                    if (
                        Number.isFinite(sourceBlockLeft)
                        && Number.isFinite(sourceBlockTop)
                        && Number.isFinite(sourceBlockWidth)
                        && Number.isFinite(sourceBlockHeight)
                        && sourcePageHeight > 0
                    ) {
                        const currentTop = sourcePageHeight - ((Number(annotation.pdfY) || 0) + (Number(annotation.pdfHeight) || 0));
                        const geometryTolerance = 0.75;
                        if (
                            Math.abs((Number(annotation.pdfX) || 0) - sourceBlockLeft) > geometryTolerance
                            || Math.abs(currentTop - sourceBlockTop) > geometryTolerance
                            || Math.abs((Number(annotation.pdfWidth) || 0) - sourceBlockWidth) > geometryTolerance
                            || Math.abs((Number(annotation.pdfHeight) || 0) - sourceBlockHeight) > geometryTolerance
                        ) {
                            return false;
                        }
                    }
                }
                if (String(annotation.backgroundColor || 'transparent') !== 'transparent') {
                    return false;
                }
                if (String(annotation.textColor || '#000000').toLowerCase() !== '#000000') {
                    return false;
                }
                if (String(annotation.fontStyle || 'normal') !== 'normal') {
                    return false;
                }
                if (Boolean(annotation.underline)) {
                    return false;
                }
                if (String(annotation.textAlign || 'left') !== 'left') {
                    return false;
                }
                if (normalizeComparableAnnotationNumber(annotation.opacity ?? 1) !== 1) {
                    return false;
                }

                const sourceLineHeights = sourceMeta.sourceLineBBoxes
                    .map((bbox) => Array.isArray(bbox) && bbox.length >= 4 ? (Number(bbox[3]) - Number(bbox[1])) : 0)
                    .filter((height) => Number.isFinite(height) && height > 0);
                const savedLineHeight = Number(annotation.lineHeight);
                if (sourceLineHeights.length && savedLineHeight > 0) {
                    const averageSourceLineHeight = sourceLineHeights.reduce((sum, height) => sum + height, 0) / sourceLineHeights.length;
                    if (Math.abs(savedLineHeight - averageSourceLineHeight) > 1.5) {
                        return false;
                    }
                }

                return true;
            }

            function canRestorePromotedAnnotationExactLayout(annotation) {
                if (!annotation?.promotedFromExtraction || !annotation?.promotedDirty) {
                    return false;
                }
                return matchesPromotedAnnotationExactSourceState(annotation);
            }

            function shouldReplayPromotedAnnotationOnPageRedraw(annotation) {
                if (!annotation?.promotedFromExtraction) {
                    return false;
                }
                return true;
            }

            function shouldResetPromotedAnnotationReflow(annotation) {
                if (!annotation?.promotedFromExtraction || !annotation?.promotedReflowEnabled) {
                    return false;
                }
                if (String(annotation.text || '') !== String(annotation.originalText || '')) {
                    return false;
                }
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                return Array.isArray(sourceMeta?.sourceLineBBoxes) && sourceMeta.sourceLineBBoxes.length > 0;
            }

            function canRenderPromotedAnnotationWithExactGeometry(annotation) {
                if (!annotation?.promotedFromExtraction || annotation?.promotedReflowEnabled) {
                    return false;
                }
                // When the annotation text has been changed from the original source text, skip
                // exact geometry rendering entirely — the source span positions no longer match
                // the edited content and would render the original text instead of the edit.
                // Compare against annotation.originalText (not getCanonicalPromotedAnnotationSourceText)
                // because syncPromotedAnnotationSourceTextLines mutates sourceTextLines to the new text
                // after an edit, making the canonical source text equal the edited text — defeating the guard.
                if (
                    annotation.promotedDirty
                    && sanitizePromotedExtractionText(annotation.text || '') !== sanitizePromotedExtractionText(annotation.originalText || '')
                ) {
                    return false;
                }
                if (!annotationHasBounds(annotation)) {
                    return false;
                }
                const sourceMeta = getPromotedAnnotationSourceMeta(annotation);
                if (!Array.isArray(sourceMeta?.sourceLineBBoxes) || sourceMeta.sourceLineBBoxes.length === 0) {
                    return false;
                }
                return canPreservePromotedAnnotationSourceLineLayout(annotation, annotation.text, {
                    richTextHtml: annotation.richTextHtml || '',
                });
            }

            async function saveAnnotationToDatabase(annotation, { markPromotedDirty = true, markAnnotationPageDirty: shouldMarkAnnotationPageDirty = true } = {}) {
                try {
                    clearTrackedPromotedAnnotationDeletion(annotation);
                    if (markPromotedDirty) {
                        markPromotedAnnotationDirty(annotation);
                    }
                    if (shouldMarkAnnotationPageDirty) {
                        markAnnotationPageDirty(annotation);
                    }
                    const sessionId = getStoredPdfSessionId() || generateSessionId();
                    setStoredPdfSessionId(sessionId);
                    const annotationPayload = stripInternalAnnotationFields(annotation);
                    
                    const saveUrl = `{{ route('documents.saveAnnotations', $document) }}`;
                    const response = await fetch(saveUrl, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRF-TOKEN': csrfToken,
                        },
                        body: JSON.stringify({
                            annotations: [annotationPayload],
                            session_id: sessionId,
                            user_email: null,
                            annotation_id: annotation.id,
                        }),
                    });
                    const result = await response.json().catch(() => ({}));
                    
                    if (response.ok) {
                        if (result?.annotation && typeof result.annotation === 'object') {
                            Object.assign(annotation, result.annotation);
                            normalizeTextAnnotation(annotation);
                            const annotationImage = annotation.element?.querySelector?.('img');
                            if (annotationImage) {
                                annotationImage.src = getAnnotationImageDataUrl(annotation);
                            }
                            persistAnnotations();
                            updateAnnotationsList();
                        }
                        console.log('Annotation saved to database:', annotation.id);
                        if (layoutMode === 'new_writer' && annotation.db_id) {
                            renderWithNewWriter(annotation.pageIndex);
                        }
                    } else {
                        console.error('Failed to save annotation to database', result?.message || response.statusText);
                    }
                } catch (error) {
                    console.error('Error saving annotation to database:', error);
                }
            }

            function deleteAnnotationFromDatabase(annotation) {
                const sessionId = getStoredPdfSessionId({
                    includeUrl: true,
                    includeLegacyGlobal: loadedSavedPdfMode,
                });
                if (!sessionId) return;
                const annotationId = String(annotation?.id || '').trim();
                const promotedSourceKey = annotation?.promotedFromExtraction
                    ? String(annotation?.promotedSourceKey || '').trim()
                    : '';
                if (!annotationId && !promotedSourceKey) return;
                fetch(`{{ route('documents.deleteAnnotations', $document) }}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken },
                    body: JSON.stringify({
                        annotation_ids: annotationId ? [annotationId] : [],
                        deleted_promoted_source_keys: promotedSourceKey ? [promotedSourceKey] : [],
                        session_id: sessionId,
                    }),
                }).catch(e => console.warn('Failed to mark annotation deleted in DB:', e));
            }

            function deleteAnnotationIdsFromDatabase(ids) {
                if (!ids || ids.length === 0) return;
                const sessionId = getStoredPdfSessionId({
                    includeUrl: true,
                    includeLegacyGlobal: loadedSavedPdfMode,
                });
                if (!sessionId) return;
                fetch(`{{ route('documents.deleteAnnotations', $document) }}`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken },
                    body: JSON.stringify({ annotation_ids: ids, session_id: sessionId }),
                }).catch(e => console.warn('Failed to bulk-delete annotations from DB:', e));
            }

            // ── new_writer: server-side render a page using the Python annotation writer ──
            // Called after annotations with db_id are saved/loaded. Paints the
            // writer-rendered PNG over the PDF.js canvas so the editor shows
            // pixel-accurate writer output when layoutMode === 'new_writer'.
            let _writerRenderPending = {};
            async function renderWithNewWriter(pageIndex) {
                if (layoutMode !== 'new_writer') return;

                const pi = Number(pageIndex) || 0;
                // Debounce: multiple rapid saves on the same page collapse into one fetch
                if (_writerRenderPending[pi]) return;
                _writerRenderPending[pi] = true;
                await new Promise(r => setTimeout(r, 80));
                _writerRenderPending[pi] = false;

                const ids = annotations
                    .filter(a => (Number(a.pageIndex) || 0) === pi && a.db_id)
                    .map(a => a.db_id);

                if (ids.length === 0) return;

                try {
                    const url = '{{ route('pdfTests.renderAnnotations', $document) }}';
                    const resp = await fetch(url, {
                        method: 'POST',
                        headers: {
                            Accept: 'application/json',
                            'X-CSRF-TOKEN': csrfToken,
                        },
                        credentials: 'same-origin',
                        body: new URLSearchParams({
                            state_ids: ids.join(','),
                            page_index: String(pi),
                            dpi: '150',
                        }),
                    });
                    const data = await resp.json().catch(() => ({}));
                    if (!data.success || !data.image) return;

                    const wrapper = viewer.querySelector(`.page[data-page-index="${pi}"]`);
                    if (!wrapper) return;
                    const canvas = wrapper.querySelector('canvas');
                    if (!canvas) return;

                    const img = new Image();
                    img.onload = () => {
                        // Scale writer PNG to existing canvas size so HTML annotation
                        // overlay positions remain accurate (do not resize the canvas).
                        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
                    };
                    img.src = 'data:image/png;base64,' + data.image;
                } catch (e) {
                    console.warn('renderWithNewWriter failed:', e);
                }
            }

            // Ensures all annotations on a page have db_ids by saving unsaved ones,
            // then fires renderWithNewWriter. Used on initial page load in new_writer mode
            // so the writer renders all annotations, not just those already in DB.
            async function flushPageAnnotationsForNewWriter(pageIndex) {
                if (layoutMode !== 'new_writer') return;
                const pi = Number(pageIndex) || 0;
                const unsaved = annotations.filter(a => (Number(a.pageIndex) || 0) === pi && !a.db_id);
                if (unsaved.length > 0) {
                    await Promise.all(unsaved.map(a => saveAnnotationToDatabase(a, { markPromotedDirty: false, markAnnotationPageDirty: false })));
                }
                renderWithNewWriter(pi);
            }

            async function flushAllAnnotationsForNewWriter() {
                if (layoutMode !== 'new_writer') return;
                const pages = [...new Set(annotations.map(a => Number(a.pageIndex) || 0))];
                await Promise.all(pages.map(pi => flushPageAnnotationsForNewWriter(pi)));
            }

            function isPdfJsRenderingCancelledError(error) {
                if (!error || typeof error !== 'object') {
                    return false;
                }
                const name = String(error.name || '').trim();
                const message = String(error.message || '').trim();
                return name === 'RenderingCancelledException'
                    || /rendering cancelled/i.test(message);
            }

            async function rerenderPdf() {
                closeTextEditPopup();

                try {
                    if (await ensurePassiveAcroFormOverlayReady()) {
                        if (typeof renderGridlines === 'function') renderGridlines();
                        return;
                    }

                    await renderPdf();
                    // Re-apply gridlines after re-render
                    if (typeof renderGridlines === 'function') renderGridlines();
                    if (layoutMode === 'new_writer') {
                        flushAllAnnotationsForNewWriter();
                    }
                } catch (err) {
                    if (isPdfJsRenderingCancelledError(err)) {
                        console.debug('rerenderPdf cancelled by a newer render', err);
                        return;
                    }
                    console.error('rerenderPdf failed', err);
                    setStatus('Failed to load PDF.', 'err');
                }
            }

            function removeActiveEditor() {
                if (!activeEditor) {
                    return;
                }

                inlineEditRequestSequence += 1;

                try {
                    // Check if the element still exists in the DOM
                    if (activeEditor.parentNode && activeEditor.parentNode.contains(activeEditor)) {
                        activeEditor.parentNode.removeChild(activeEditor);
                    } else if (activeEditor.isConnected) {
                        // Element is in DOM but not in expected parent, use remove()
                        activeEditor.remove();
                    }
                } catch (e) {
                    // Element was already removed or doesn't exist, ignore the error
                    console.warn('Editor element already removed:', e);
                }
                
                activeEditor = null;
                activeEditorSelectionRange = null;
                updateEditTextBanner();
            }

            function closeTextEditPopup() {
                // Legacy PDF.js text-layer popup editing was removed.
            }

            async function startInlineEdit(wrapper, annotation, options = {}) {
                if (annotation.type !== 'text') {
                    return;
                }
                if (activeEditor && activeEditor._annotationId && activeEditor._annotationId === annotation.id) {
                    if (typeof activeEditor._focusTextEditor === 'function') {
                        activeEditor._focusTextEditor(options);
                    }
                    return;
                }
                const overlay = wrapper.querySelector('.overlay');
                if (!overlay) return;
                const canvas = wrapper.querySelector('canvas');
                if (!canvas) return;
                const requestSequence = ++inlineEditRequestSequence;
                
                // Build pageInfo from canvas
                const pageInfo = {
                    scale: currentScale,
                    canvasHeight: overlay.clientHeight || canvas.height,
                };
                const pageIndex = annotation.pageIndex;

                // Build opts from the annotation's current style
                const opts = {
                    fontFamily: annotation.fontFamily || defaultTextFont,
                    fontSizePx: getRequestedAnnotationFontSize(annotation),
                    textColor: annotation.textColor || '#000000',
                    bgColor: annotation.backgroundColor || 'transparent',
                    opacityVal: annotation.opacity ?? 1,
                    fontWeight: annotation.fontWeight || 'normal',
                    fontStyle: annotation.fontStyle || 'normal',
                    underline: Boolean(annotation.underline),
                    textAlign: annotation.textAlign || 'left',
                };

                await ensureAnnotationEditorFontsLoaded(annotation, opts.fontSizePx, annotation.text || '');
                if (requestSequence !== inlineEditRequestSequence) {
                    return;
                }

                const x = annotation.pdfX * currentScale;
                const y = getTextAnnotationTopPx(annotation, pageInfo);
                const dw = annotation.pdfWidth ? annotation.pdfWidth * currentScale : 0;
                const dh = annotation.pdfHeight ? annotation.pdfHeight * currentScale : 0;

                createTextBoxCreator(overlay, x, y, pageIndex, canvas, wrapper, pageInfo, opts, dw || undefined, dh || undefined, annotation, options);
            }

            // Helper to read current banner settings into an opts object
            function readBannerOpts() {
                const etbFont = document.getElementById('etb-font');
                const etbSize = document.getElementById('etb-size');
                const etbTextColor = document.getElementById('etb-text-color');
                const etbBgColor = document.getElementById('etb-bg-color');
                const etbOpacity = document.getElementById('etb-opacity');
                const etbBold = document.getElementById('etb-bold');
                const etbItalic = document.getElementById('etb-italic');
                const etbUnderline = document.getElementById('etb-underline');
                const etbAlign = document.getElementById('etb-align');
                const etbValign = document.getElementById('etb-valign');
                return {
                    fontFamily: etbFont ? etbFont.value : defaultTextFont,
                    fontSizePx: etbSize ? bannerSliderValueToFontSizePx(etbSize.value || editTextBannerSliderMid) : defaultTextSize,
                    textColor: etbTextColor ? etbTextColor.value : '#000000',
                    bgColor: etbBgColor ? etbBgColor.value : '#ffffff',
                    opacityVal: etbOpacity ? parseFloat(etbOpacity.value) : 1,
                    fontWeight: (etbBold && etbBold.classList.contains('active')) ? '700' : 'normal',
                    fontStyle: (etbItalic && etbItalic.classList.contains('active')) ? 'italic' : 'normal',
                    underline: etbUnderline ? etbUnderline.classList.contains('active') : false,
                    textAlign: etbAlign ? etbAlign.value : 'left',
                    verticalAlign: etbValign ? etbValign.value : 'top',
                };
            }

            function createTextBoxCreator(overlay, x, y, pageIndex, canvas, wrapper, pageInfo, opts, dragW, dragH, editAnnotation, editorOptions = {}) {
                const { fontFamily, fontSizePx, textColor, bgColor, opacityVal, fontWeight, fontStyle, underline, textAlign } = opts;
                const editingExistingAnnotation = Boolean(editAnnotation);
                const editingPromotedExtraction = Boolean(editAnnotation?.promotedFromExtraction);
                const editingRichTextAnnotation = Boolean(annotationRichTextHasFormatting(editAnnotation?.richTextHtml || ''));
                const preservePromotedLinesInEditor = Boolean(editingPromotedExtraction && !editAnnotation?.promotedReflowEnabled);
                const preservePromotedEntryLayout = Boolean(editingPromotedExtraction && annotationHasBounds(editAnnotation));
                const editorPageScale = Math.max(0.0001, Number(pageInfo?.scale || currentScale || 1) || 1);
                const editLineHeightPx = Number(editAnnotation?.lineHeight) > 0
                    ? Number(editAnnotation.lineHeight) * currentScale
                    : 0;
                const editorLineHeightPx = editingPromotedExtraction
                    ? (preservePromotedLinesInEditor && editLineHeightPx > 0
                        ? editLineHeightPx
                        : Math.max(editLineHeightPx, fontSizePx * 1.2))
                    : editLineHeightPx;
                const initialCaretClientX = Number(editorOptions?.caretClientX);
                const initialCaretClientY = Number(editorOptions?.caretClientY);
                const hasInitialCaretPoint = Number.isFinite(initialCaretClientX) && Number.isFinite(initialCaretClientY);
                let nativeInput = null;
                let exactCharacterEditorState = null;
                const editorMeasurementCanvas = document.createElement('canvas');
                const editorMeasurementContext = editorMeasurementCanvas.getContext('2d');
                const measureInlineTextWidth = (text, fontSizePx, fontFamilyValue, fontWeightValue, fontStyleValue) => {
                    if (!editorMeasurementContext) {
                        return Math.max(1, (Number(fontSizePx) || 12) * 0.6);
                    }
                    const safeFontSizePx = Math.max(1, Number(fontSizePx) || 12);
                    editorMeasurementContext.font = `${fontStyleValue || 'normal'} ${fontWeightValue || '400'} ${safeFontSizePx}px ${fontFamilyValue || 'sans-serif'}`;
                    return editorMeasurementContext.measureText(text || ' ').width;
                };
                
                // Remove any existing text-box-creator
                document.querySelectorAll('.text-box-creator').forEach(el => el.remove());
                removeActiveEditor();
                if (!editAnnotation) {
                    setSelection(null);
                }
                
                const box = document.createElement('div');
                box.className = 'text-box-creator';
                box.style.zIndex = '200000';
                if (editingExistingAnnotation) {
                    box.classList.add('inline-annotation-editor');
                }
                if (preservePromotedEntryLayout) {
                    box.classList.add('promoted-inline-editor');
                    box.style.border = 'none';
                    box.style.background = 'rgba(255,255,255,0.98)';
                    box.style.borderRadius = '0';
                    box.style.minWidth = '0';
                    box.style.minHeight = '0';
                    box.style.boxSizing = 'border-box';
                }
                box.style.left = x + 'px';
                box.style.top = y + 'px';
                if (dragW && dragH) {
                    box.style.width = Math.max(60, dragW) + 'px';
                    box.style.height = Math.max(28, dragH) + 'px';
                    box.style.minWidth = '0';
                    if (editingPromotedExtraction) {
                        box.style.minHeight = '0';
                    }
                }
                
                // Input area – contenteditable for partial word styling
                const input = document.createElement('div');
