                const buildStyledWordSpans = (container, words, scaleX, scaleY, blockLeft, blockTop, sourceBlock, sourceBlockText) => {
                    container.style.position = 'relative';
                    const parentBlockText = sanitizeOverlayText(sourceBlockText || '');
                    const alignToUnderlineRow = isLabelUnderlineValueBlock(sourceBlock || {}, words, parentBlockText);
                    let underlineTop = null;
                    let underlineLeft = null;
                    let underlineRight = null;
                    const valueShiftByLine = new Map();

                    // ── Word-level deduplication ──────────────────────────────
                    // Extraction can produce duplicate/overlapping word entries
                    // (OCR layers, font re-encoding, ligature splitting). Remove
                    // near-identical words so we don't render stacked glyphs.
                    const WORD_POS_EPS = 1.5; // PDF-unit tolerance
                    const dedupedWords = [];
                    const seenWordKeys = new Set();
                    const sortedInput = [...words].sort((a, b) =>
                        ((a.top || 0) - (b.top || 0)) || ((a.left || 0) - (b.left || 0))
                    );
                    sortedInput.forEach((word) => {
                        // Fast path: exact signature match
                        const sig = [
                            sanitizeOverlayText(word.text || ''),
                            Math.round((word.left || 0) / WORD_POS_EPS),
                            Math.round((word.top || 0) / WORD_POS_EPS),
                        ].join('|');
                        if (seenWordKeys.has(sig)) return;
                        seenWordKeys.add(sig);

                        // Slow path: check for near-overlap with already-kept words
                        const isDup = dedupedWords.some((kept) => {
                            if (Math.abs((kept.left || 0) - (word.left || 0)) > WORD_POS_EPS) return false;
                            if (Math.abs((kept.top || 0) - (word.top || 0)) > WORD_POS_EPS) return false;
                            const keptText = sanitizeOverlayText(kept.text || '');
                            const wordText = sanitizeOverlayText(word.text || '');
                            return keptText === wordText
                                || keptText.includes(wordText)
                                || wordText.includes(keptText);
                        });
                        if (!isDup) dedupedWords.push(word);
                    });

                    const lines = new Map();
                    dedupedWords.forEach((word) => {
                        const lineKey = word.line_num ?? 0;
                        if (!lines.has(lineKey)) {
                            lines.set(lineKey, []);
                        }
                        lines.get(lineKey).push(word);
                    });

                    const sortedLineKeys = Array.from(lines.keys()).sort((a, b) => a - b);
                    if (alignToUnderlineRow) {
                        // Derive underline anchor from actual underscore glyph run.
                        // If underscores are embedded in a mixed token like
                        // "Label: ________", use measured prefix/run widths so
                        // value text can center over the underline region only.
                        sortedLineKeys.forEach((lineKey) => {
                            const lineWords = (lines.get(lineKey) || []).slice().sort((a, b) => (a.left || 0) - (b.left || 0));
                            lineWords.forEach((w) => {
                                const src = sanitizeOverlayText(w.text || '');
                                if (!/_{3,}/.test(src)) return;

                                let candLeft = Number(w.left) || 0;
                                let candRight = candLeft + (Number(w.width) || 0);
                                const candTop = Number(w.top) || 0;

                                if (!/^_+$/.test(src)) {
                                    const firstUs = src.indexOf('_');
                                    const lastUs = src.lastIndexOf('_');
                                    if (firstUs >= 0 && lastUs >= firstUs) {
                                        const prefix = src.slice(0, firstUs);
                                        const run = src.slice(firstUs, lastUs + 1);
                                        const wFamily = getCssFontFamily(w.font, w.embedded_font_name || w.font);
                                        let wWeight;
                                        if (w.font_weight) wWeight = String(w.font_weight);
                                        else if (w.bold) wWeight = '700';
                                        else wWeight = '400';
                                        const wStyle = w.italic ? 'italic' : 'normal';
                                        const wSizePx = (Number(w.font_size) || 10) * scaleY;
                                        const totalPx = Math.max(1, measureTextWidth(src, wSizePx, wFamily, wWeight, wStyle));
                                        const prePx = Math.max(0, measureTextWidth(prefix, wSizePx, wFamily, wWeight, wStyle));
                                        const runPx = Math.max(0, measureTextWidth(run, wSizePx, wFamily, wWeight, wStyle));
                                        const pdfW = Math.max(1, Number(w.width) || 1);
                                        candLeft = (Number(w.left) || 0) + ((prePx / totalPx) * pdfW);
                                        candRight = candLeft + ((runPx / totalPx) * pdfW);
                                    }
                                }

                                underlineTop = (underlineTop === null) ? candTop : Math.min(underlineTop, candTop);
                                underlineLeft = (underlineLeft === null) ? candLeft : Math.min(underlineLeft, candLeft);
                                underlineRight = (underlineRight === null) ? candRight : Math.max(underlineRight, candRight);
                            });
                        });
                    }
                    // Coordinate-based mapping for label+underline+value rows:
                    // use underscore bbox as anchor and center the value group within it.
                    if (alignToUnderlineRow && underlineTop !== null && underlineLeft !== null && underlineRight !== null) {
                        sortedLineKeys.forEach((lineKey) => {
                            const lineWords = lines.get(lineKey) || [];
                            const hasUnderline = lineWords.some((w) => /_{3,}/.test(sanitizeOverlayText(w.text || '')));
                            if (hasUnderline) return;
                            const valueWords = lineWords.filter((w) => {
                                const src = sanitizeOverlayText(w.text || '');
                                return src && !src.includes(':') && !/_{3,}/.test(src);
                            });
                            if (!valueWords.length) return;
                            const vMinL = Math.min(...valueWords.map((w) => Number(w.left) || 0));
                            const vMaxR = Math.max(...valueWords.map((w) => (Number(w.left) || 0) + (Number(w.width) || 0)));
                            const valueCenter = (vMinL + vMaxR) / 2;
                            const underlineCenter = (underlineLeft + underlineRight) / 2;
                            const shift = underlineCenter - valueCenter;
                            valueShiftByLine.set(String(lineKey), shift);
                        });
                    }

                    // Only strip template underscores for option-choice rows where
                    // duplicate lines are common. For normal label/value fields
                    // (e.g. "... marriage: ____" + "2"), keep underscores visible.
                    const shouldStripTemplateUnderscores = isOptionChoiceBlock(
                        sourceBlock || {},
                        dedupedWords,
                        parentBlockText
                    );
                    const renderAnchoredUnderscoreSegments = (word, wordFontFamily, wordWeight, wordStyle, lineKey) => {
                        const sourceText = sanitizeOverlayText(word.text || '');
                        if (!/_{3,}/.test(sourceText)) return false;
                        const chunks = sourceText.split(/(_{3,})/);
                        if (chunks.length < 2) return false;
                        const fontSizePx = (Number(word.font_size) || 10) * scaleY;
                        const measuredTotal = Math.max(1, measureTextWidth(sourceText, fontSizePx, wordFontFamily, wordWeight, wordStyle));
                        const targetPx = Math.max(1, (Number(word.width) || 1) * scaleX);
                        const widthScale = targetPx / measuredTotal;
                        let cursorPx = 0;
                        let renderedAny = false;

                        chunks.forEach((chunk) => {
                            const chunkPx = measureTextWidth(chunk, fontSizePx, wordFontFamily, wordWeight, wordStyle) * widthScale;
                            const isUnderlineRun = /^_{3,}$/.test(chunk);
                            if (!isUnderlineRun && chunk.length > 0) {
                                const seg = document.createElement('span');
                                const segFontSizePx = (Number(word.font_size) || 10) * scaleY;
                                const segLineHeightPx = Math.max(
                                    segFontSizePx,
                                    (Number(word.height) || 0) * scaleY,
                                    1
                                );
                                seg.textContent = chunk;
                                seg.style.fontFamily = wordFontFamily;
                                seg.style.fontSize = fontSizePx + 'px';
                                seg.style.lineHeight = segLineHeightPx + 'px';
                                seg.style.fontWeight = wordWeight;
                                seg.style.fontStyle = wordStyle;
                                seg.style.color = getWordColor(word, '#000000');
                                seg.style.position = 'absolute';
                                let renderLeft = (Number(word.left) || 0) + (cursorPx / Math.max(1e-6, scaleX));
                                let renderTop = Number(word.top) || 0;
                                if (alignToUnderlineRow && underlineTop !== null) {
                                    const src = sanitizeOverlayText(word.text || '');
                                    const isUnderlineWord = /_{3,}/.test(src);
                                    const isLabelWord = src.includes(':');
                                    if (!isUnderlineWord && !isLabelWord) {
                                        renderTop = underlineTop;
                                        const lineShift = valueShiftByLine.get(String(lineKey));
                                        if (Number.isFinite(lineShift)) renderLeft = renderLeft + lineShift;
                                    }
                                }
                                seg.style.left = ((renderLeft - blockLeft) * scaleX) + 'px';
                                seg.style.top = ((renderTop - blockTop) * scaleY) + 'px';
                                seg.dataset.lineNum = String(word.line_num ?? 0);
                                seg.dataset.originY = String(
                                    (word.origin_y !== undefined && word.origin_y !== null)
                                        ? word.origin_y
                                        : ((word.top || 0) + (word.height || 0))
                                );
                                seg.style.whiteSpace = 'pre';
                                container.appendChild(seg);
                                renderedAny = true;
                            }
                            cursorPx += chunkPx;
                        });

                        return renderedAny;
                    };

                    sortedLineKeys.forEach((lineKey) => {
                        const lineWords = lines.get(lineKey)
                            .sort((a, b) => a.left - b.left)
                            .map((w) => {
                                let displayText = getOverlayWordDisplayText(w);
                                const srcText = sanitizeOverlayText(w.text || '');
                                if (/_{3,}/.test(srcText)) {
                                    const hasFlag = !!(w.has_drawn_underline || w.suppress_drawn_underline);
                                    const hasVisual = hasVisualUnderlineInWordBBox(w, scaleX, scaleY);
                                    if (hasFlag || hasVisual) {
                                        displayText = displayText
                                            .replace(/_{3,}/g, (m) => ' '.repeat(m.length))
                                            .replace(/[ \t]+$/g, '');
                                    }
                                }
                                // If a fill value exists in this block, strip underscores
                                // from template words (they are just form placeholders).
                                // Keep underscores only when no value is present.
                                if (shouldStripTemplateUnderscores && /_{3,}/.test(sanitizeOverlayText(w.text || ''))) {
                                    displayText = displayText
                                        .replace(/_{3,}/g, (m) => ' '.repeat(m.length))
                                        .replace(/[ \t]+$/g, '');
                                }
                                return { ...w, _displayText: displayText };
                            })
                            .filter((w) => w._displayText.length > 0);
                        if (!lineWords.length) return;
                        lineWords.forEach((word, wordIndex) => {
                            const wordFontFamily = getCssFontFamily(word.font, word.embedded_font_name || word.font);
                            
                            // Use explicit font_weight from extraction if available, otherwise infer
                            let wordWeight;
                            if (word.font_weight) {
                                wordWeight = String(word.font_weight);
                            } else {
                                const inferredWeight = inferFontWeightFromName(word.font);
                                if (inferredWeight) {
                                    wordWeight = inferredWeight;
                                } else if (word.bold) {
                                    wordWeight = '700';
                                } else {
                                    wordWeight = '400';
                                }
                            }
                            
                            const wordStyle = word.italic ? 'italic' : 'normal';
                            const sourceText = sanitizeOverlayText(word.text || '');
                            const displayText = sanitizeOverlayText(word._displayText || '');
                            const shouldRenderAnchoredSegments =
                                /_{3,}/.test(sourceText) &&
                                displayText.length > 0 &&
                                !displayText.includes('_') &&
                                displayText !== sourceText;
                            if (shouldRenderAnchoredSegments) {
                                const rendered = renderAnchoredUnderscoreSegments(
                                    word, wordFontFamily, wordWeight, wordStyle, lineKey
                                );
                                if (rendered) {
                                    return;
                                }
                            }

                            const wordSpan = document.createElement('span');
                            const wordFontSizePx = (Number(word.font_size) || 10) * scaleY;
                            const wordLineHeightPx = Math.max(
                                wordFontSizePx,
                                (Number(word.height) || 0) * scaleY,
                                1
                            );
                            wordSpan.textContent = word._displayText;
                            wordSpan.style.fontFamily = wordFontFamily;
                            wordSpan.style.fontSize = wordFontSizePx + 'px';
                            wordSpan.style.lineHeight = wordLineHeightPx + 'px';
                            wordSpan.style.fontWeight = wordWeight;
                            wordSpan.style.fontStyle = wordStyle;
                            wordSpan.style.color = getWordColor(word, '#000000');
                            wordSpan.style.position = 'absolute';
                            let renderLeft = Number(word.left) || 0;
                            let renderTop = Number(word.top) || 0;
                            if (alignToUnderlineRow && underlineTop !== null) {
                                const src = sanitizeOverlayText(word.text || '');
                                const isUnderlineWord = /_{3,}/.test(src);
                                const isLabelWord = src.includes(':');
                                if (!isUnderlineWord && !isLabelWord) {
                                    // Place filled values onto the underline row.
                                    renderTop = underlineTop;
                                    const lineShift = valueShiftByLine.get(String(lineKey));
                                    if (Number.isFinite(lineShift)) {
                                        renderLeft = renderLeft + lineShift;
                                    }
                                }
                            }
                            wordSpan.style.left = ((renderLeft - blockLeft) * scaleX) + 'px';
                            wordSpan.style.top = ((renderTop - blockTop) * scaleY) + 'px';
                            wordSpan.dataset.lineNum = String(word.line_num ?? 0);
                            wordSpan.dataset.originY = String(
                                (word.origin_y !== undefined && word.origin_y !== null)
                                    ? word.origin_y
                                    : ((word.top || 0) + (word.height || 0))
                            );
                            wordSpan.style.whiteSpace = 'pre';
                            // Do not apply width-fit letter spacing when render_text differs
                            // from source text (e.g. underscore suppression over drawn lines).
                            // Using original extraction width in that case causes extreme
                            // character spreading like "A d d r e s s :".
                            const sourceUnderscoreRuns = (sourceText.match(/_{3,}/g) || []).length;
                            const sourceAlphaTokens = sourceText.replace(/_{3,}/g, ' ')
                                .split(/\s+/)
                                .filter((tok) => /[A-Za-z]/.test(tok))
                                .length;
                            const isOptionChoiceToken = sourceUnderscoreRuns >= 2 && sourceAlphaTokens >= 3;
                            const isUnderscoreAnchorToken = sourceUnderscoreRuns >= 1 &&
                                !/_{3,}/.test(displayText) &&
                                /\s/.test(displayText);
                            const canFitSpacing = displayText && sourceText &&
                                ((displayText === sourceText) || isOptionChoiceToken);
                            if (canFitSpacing) {
                                const spacing = computeLetterSpacing(
                                    { ...word, text: displayText },
                                    scaleX, scaleY, wordFontFamily, wordWeight, wordStyle,
                                    isUnderscoreAnchorToken ? { maxSpacing: 24 } : undefined
                                );
                                if (spacing !== null) {
                                    wordSpan.style.letterSpacing = spacing + 'px';
                                }
                            }
                            container.appendChild(wordSpan);
                            if (wordIndex < lineWords.length - 1) {
                                const space = document.createElement('span');
                                space.textContent = ' ';
                                space.style.position = 'absolute';
                                space.style.left = ((word.left - blockLeft + word.width) * scaleX) + 'px';
                                space.style.top = ((word.top - blockTop) * scaleY) + 'px';
                                space.style.fontSize = (word.font_size * scaleY) + 'px';
                                space.style.fontFamily = wordFontFamily;
                                space.style.fontWeight = wordWeight;
                                space.style.fontStyle = wordStyle;
                                container.appendChild(space);
                            }
                        });
                    });
                };

                const buildExactBlockLineSpans = (container, block, scaleX, scaleY, blockLeft, blockTop) => {
                    const lineBBoxes = Array.isArray(block?.line_bboxes)
                        ? block.line_bboxes.filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                        : [];
                    const spans = Array.isArray(block?.spans)
                        ? block.spans.filter((span) => span && Array.isArray(span.bbox) && span.bbox.length >= 4)
                        : [];
                    const textLines = Array.isArray(block?.text_lines)
                        ? block.text_lines.map((line) => sanitizeOverlayText(line))
                        : [];
                    if (lineBBoxes.length === 0 || spans.length === 0) {
                        return false;
                    }

                    const lineEntries = lineBBoxes.map((bbox, index) => ({
                        index,
                        bbox: bbox.map((value) => Number(value) || 0),
                        text: textLines[index] || '',
                        spans: [],
                    }));
                    assignPromotedSpansToLineEntries(lineEntries, spans);

                    container.innerHTML = '';
                    container.style.position = 'relative';
                    container.style.display = 'block';
                    container.style.width = '100%';
                    container.style.height = '100%';
                    container.style.padding = '0';
                    container.style.margin = '0';
                    container.style.whiteSpace = 'normal';
                    container.style.overflow = 'visible';

                    const getSpanColor = (span) => {
                        if (span?.hex_color) return span.hex_color;
                        if (span?.color !== undefined && span?.color !== null) {
                            return typeof span.color === 'number'
                                ? '#' + span.color.toString(16).padStart(6, '0')
                                : span.color;
                        }
                        if (block?.hex_color) return block.hex_color;
                        if (block?.color !== undefined && block?.color !== null) {
                            return typeof block.color === 'number'
                                ? '#' + block.color.toString(16).padStart(6, '0')
                                : block.color;
                        }
                        return '#000000';
                    };

                    const fragment = document.createDocumentFragment();
                    lineEntries.forEach((entry) => {
                        const [lineLeft, lineTop, lineRight, lineBottom] = entry.bbox;
                        const lineEl = document.createElement('span');
                        lineEl.style.position = 'absolute';
                        lineEl.style.display = 'block';
                        lineEl.style.left = `${(lineLeft - blockLeft) * scaleX}px`;
                        lineEl.style.width = `${Math.max(1, (lineRight - lineLeft) * scaleX)}px`;
                        lineEl.style.overflow = 'visible';
                        lineEl.style.whiteSpace = 'pre';
                        lineEl.style.padding = '0';
                        lineEl.style.margin = '0';

                        // Compute proper line-box height and top using font metrics.
                        // PyMuPDF reports glyph bboxes, not full em-boxes. For small
                        // characters like periods, the glyph bbox height is much smaller
                        // than the font's actual line height (ascender+descender). Without
                        // this correction, CSS renders the text above the line element and
                        // the character gets clipped by the overlay-field's overflow:hidden.
                        {
                            const entrySpans = entry.spans.filter(Boolean);
                            const avgAsc = entrySpans.length > 0
                                ? entrySpans.reduce((s, sp) => s + (Number(sp.ascender) || 0.8), 0) / entrySpans.length
                                : (Number(block?.spans?.[0]?.ascender) || 0.8);
                            const avgDesc = entrySpans.length > 0
                                ? entrySpans.reduce((s, sp) => s + (Number(sp.descender) || -0.2), 0) / entrySpans.length
                                : (Number(block?.spans?.[0]?.descender) || -0.2);
                            const avgFsPdf = entrySpans.length > 0
                                ? entrySpans.reduce((s, sp) => s + (Number(sp.font_size || block?.font_size || 10) || 10), 0) / entrySpans.length
                                : (Number(block?.font_size) || 10);
                            const fontMetricHeightPdf = avgFsPdf * (avgAsc - avgDesc);
                            const rawHeightPdf = Math.max(0, lineBottom - lineTop);
                            if (rawHeightPdf < fontMetricHeightPdf * 0.6) {
                                // Glyph bbox much smaller than em-height (e.g. period/dot).
                                // Compute the correct top so the text baseline aligns with
                                // the PDF character origin (span's origin[1]).
                                const avgFsPx = avgFsPdf * scaleY;
                                const lineHeightFontPx = fontMetricHeightPdf * scaleY;
                                const firstOriginY = entrySpans.length > 0
                                    ? (Number(entrySpans[0]?.origin?.[1]) || lineBottom)
                                    : lineBottom;
                                const baselineFromBlockTopPx = (firstOriginY - blockTop) * scaleY;
                                // CSS: baseline offset from lineEl top = half-leading + fontSize * ascentRatio
                                const halfLeading = (lineHeightFontPx - avgFsPx) / 2;
                                const cssBaselineOffset = halfLeading + avgFsPx * avgAsc / (avgAsc - avgDesc);
                                lineEl.style.top = `${baselineFromBlockTopPx - cssBaselineOffset}px`;
                                lineEl.style.height = `${Math.max(1, lineHeightFontPx)}px`;
                                lineEl.style.lineHeight = `${Math.max(1, lineHeightFontPx)}px`;
                            } else {
                                lineEl.style.top = `${(lineTop - blockTop) * scaleY}px`;
                                lineEl.style.height = `${Math.max(1, rawHeightPdf * scaleY)}px`;
                                lineEl.style.lineHeight = `${Math.max(1, rawHeightPdf * scaleY)}px`;
                            }
                        }

                        const sortedSpans = entry.spans.slice().sort((a, b) => (
                            (Number(a.bbox?.[0]) || 0) - (Number(b.bbox?.[0]) || 0)
                        ));
                        if (sortedSpans.length > 0) {
                            sortedSpans.forEach((sourceSpan) => {
                                const spanEl = document.createElement('span');
                                const spanBBox = Array.isArray(sourceSpan?.bbox) && sourceSpan.bbox.length >= 4
                                    ? sourceSpan.bbox
                                    : [lineLeft, lineTop, lineRight, lineBottom];
                                const spanLeft = Number(spanBBox[0]) || lineLeft;
                                const spanTop = Number(spanBBox[1]) || lineTop;
                                const spanRight = Number(spanBBox[2]) || spanLeft;
                                const spanBottom = Number(spanBBox[3]) || spanTop;
                                const resolvedFontFamily = getCssFontFamily(
                                    sourceSpan.font || block?.font,
                                    sourceSpan.embedded_font_name || block?.embedded_font_name || sourceSpan.font || block?.font
                                );
                                const resolvedFontSizePx = (Number(sourceSpan.font_size || block?.font_size || 10) || 10) * scaleY;
                                const resolvedFontWeight = String(sourceSpan.font_weight || (sourceSpan.bold ? 700 : (block?.font_weight || 400)));
                                const resolvedFontStyle = sourceSpan.italic ? 'italic' : 'normal';
                                const resolvedFontStretch = extractFontStretchFromPdfFontName(
                                    sourceSpan.embedded_font_name || sourceSpan.font || block?.embedded_font_name || block?.font
                                );
                                spanEl.textContent = String(sourceSpan.render_text ?? sourceSpan.text ?? '');
                                spanEl.style.position = 'absolute';
                                spanEl.style.display = 'block';
                                spanEl.style.left = `${(spanLeft - lineLeft) * scaleX}px`;
                                spanEl.style.top = `${(spanTop - lineTop) * scaleY}px`;
                                spanEl.style.lineHeight = `${Math.max(1, (spanBottom - spanTop) * scaleY)}px`;
                                spanEl.style.whiteSpace = 'pre';
                                spanEl.style.padding = '0';
                                spanEl.style.margin = '0';
                                if (shouldRenderFilledCircleSymbolAsShape(sourceSpan, sortedSpans)) {
                                    applyFilledCircleSymbolSpanStyles(spanEl, sourceSpan, {
                                        scale: scaleY,
                                        absolute: true,
                                        lineLeft,
                                        lineTop,
                                        fallbackColor: getSpanColor(sourceSpan),
                                    });
                                } else if (isAdobePiRightTriangleSourceSpan(sourceSpan)) {
                                    applyAdobePiRightTriangleSpanStyles(spanEl, sourceSpan, {
                                        scaleX,
                                        scaleY,
                                        absolute: true,
                                        lineLeft,
                                        lineTop,
                                        fallbackColor: getSpanColor(sourceSpan),
                                    });
                                } else {
                                    const sourceSpanRotation = normalizeSourceSpanRotation(sourceSpan);
                                    const sourceSpanWidthPx = Math.max(1, (spanRight - spanLeft) * scaleX);
                                    const sourceSpanHeightPx = Math.max(1, (spanBottom - spanTop) * scaleY);
                                    const isQuarterTurn = Math.abs(Math.abs(sourceSpanRotation) - 90) <= 0.5;
                                    spanEl.style.fontFamily = resolvedFontFamily;
                                    spanEl.style.fontSize = `${resolvedFontSizePx}px`;
                                    spanEl.style.fontWeight = resolvedFontWeight;
                                    spanEl.style.fontStyle = resolvedFontStyle;
                                    spanEl.style.fontStretch = resolvedFontStretch;
                                    spanEl.style.color = getSpanColor(sourceSpan);
                                    spanEl.style.textDecoration = sourceSpan.underline ? 'underline' : 'none';
                                    if (isQuarterTurn) {
                                        spanEl.style.width = `${sourceSpanHeightPx}px`;
                                        spanEl.style.height = `${sourceSpanWidthPx}px`;
                                        spanEl.style.lineHeight = `${sourceSpanWidthPx}px`;
                                    }
                                    applyExactTextWidthFit(spanEl, {
                                        text: spanEl.textContent || '',
                                        targetWidthPx: isQuarterTurn ? sourceSpanHeightPx : sourceSpanWidthPx,
                                        fontSizePx: resolvedFontSizePx,
                                        fontFamily: resolvedFontFamily,
                                        fontWeight: resolvedFontWeight,
                                        fontStyle: resolvedFontStyle,
                                        fontStretch: resolvedFontStretch,
                                    });
                                    const widthFitTransform = spanEl.style.transform || '';
                                    const rotatedTransform = buildRotatedSourceSpanTransform(
                                        sourceSpanRotation,
                                        sourceSpanWidthPx,
                                        sourceSpanHeightPx,
                                        widthFitTransform
                                    );
                                    if (rotatedTransform) {
                                        spanEl.style.transformOrigin = 'top left';
                                        spanEl.style.transform = rotatedTransform;
                                    }
                                }
                                lineEl.appendChild(spanEl);
                            });
                        } else {
                            lineEl.textContent = entry.originalText ?? entry.text;
                            lineEl.style.fontFamily = getCssFontFamily(block?.font, block?.embedded_font_name || block?.font);
                            lineEl.style.fontSize = `${(Number(block?.font_size) || 10) * scaleY}px`;
                            lineEl.style.fontWeight = String(block?.font_weight || (block?.bold ? 700 : 400));
                            lineEl.style.fontStyle = block?.italic ? 'italic' : 'normal';
                            lineEl.style.color = getSpanColor(block);
                        }

                        fragment.appendChild(lineEl);
                    });

                    container.appendChild(fragment);
                    container.dataset.exactGeometry = '1';
                    return true;
                };

                // Convert absolutely-positioned word spans back to flowing text while
                // preserving meaningful horizontal gaps (e.g. "1.      Information...").
                const positionedSpansToFlowText = (container) => {
                    const allSpans = Array.from(container.querySelectorAll('span'))
                        .filter((s) => s.style.position === 'absolute');
                    if (!allSpans.length) return '';

                    const contentSpans = allSpans.filter((s) => {
                        const text = s.textContent || '';
                        return !(text === ' ' && !text.trim());
                    });
                    const declaredLineNums = new Set(
                        contentSpans
                            .map((s) => s.dataset.lineNum)
                            .filter((v) => v !== undefined && v !== null && v !== '')
                    );

                    // If extraction declared a single logical line, keep it as one line
                    // during edit normalization to avoid artificial line flips.
                    if (declaredLineNums.size === 1) {
                        const lineSpans = contentSpans.sort((a, b) =>
                            (parseFloat(a.style.left) || 0) - (parseFloat(b.style.left) || 0)
                        );
                        let out = '';
                        let prevRight = null;
                        lineSpans.forEach((s) => {
                            const txt = s.textContent || '';
                            const left = parseFloat(s.style.left) || 0;
                            const width = s.getBoundingClientRect().width || 0;
                            if (prevRight !== null) {
                                const gapPx = left - prevRight;
                                if (gapPx > 0.5) {
                                    const fontSizePx = parseFloat(s.style.fontSize)
                                        || parseFloat(window.getComputedStyle(container).fontSize)
                                        || 12;
                                    const approxSpacePx = Math.max(2, fontSizePx * 0.33);
                                    const spaces = Math.max(1, Math.min(24, Math.round(gapPx / approxSpacePx)));
                                    out += ' '.repeat(spaces);
                                }
                            }
                            out += txt;
                            prevRight = left + width;
                        });
                        return out.replace(/[ \t]+$/g, '');
                    }

                    const lineTolPx = 2.5;
                    const lines = [];
                    const candidates = contentSpans
                        .map((s) => {
                            const left = parseFloat(s.style.left) || 0;
                            const top = parseFloat(s.style.top) || 0;
                            const baseline = Number.isFinite(parseFloat(s.dataset.originY))
                                ? parseFloat(s.dataset.originY)
                                : top;
                            return { s, left, baseline };
                        })
                        .sort((a, b) => (a.baseline - b.baseline) || (a.left - b.left));

                    candidates.forEach((item) => {
                        let line = lines.find((ln) => Math.abs(ln.baseline - item.baseline) <= lineTolPx);
                        if (!line) {
                            line = { baseline: item.baseline, items: [] };
                            lines.push(line);
                        }
                        line.items.push(item);
                        line.baseline = (line.baseline * (line.items.length - 1) + item.baseline) / line.items.length;
                    });

                    lines.sort((a, b) => a.baseline - b.baseline);
                    const outLines = lines.map((line) => {
                        const lineSpans = line.items
                            .sort((a, b) => a.left - b.left)
                            .map((it) => it.s);

                        let out = '';
                        let prevRight = null;
                        lineSpans.forEach((s) => {
                            const txt = s.textContent || '';
                            const left = parseFloat(s.style.left) || 0;
                            const width = s.getBoundingClientRect().width || 0;

                            if (prevRight !== null) {
                                const gapPx = left - prevRight;
                                if (gapPx > 0.5) {
                                    const fontSizePx = parseFloat(s.style.fontSize)
                                        || parseFloat(window.getComputedStyle(container).fontSize)
                                        || 12;
                                    const approxSpacePx = Math.max(2, fontSizePx * 0.33);
                                    const spaces = Math.max(1, Math.min(24, Math.round(gapPx / approxSpacePx)));
                                    out += ' '.repeat(spaces);
                                }
                            }

                            out += txt;
                            prevRight = left + width;
                        });

                        return out.replace(/[ \t]+$/g, '');
                    });

                    return outLines.join('\n').replace(/\n+$/g, '');
                };

                const getPrimaryCssFontFamily = (fontFamilyValue) => {
                    const raw = String(fontFamilyValue || '').trim();
                    if (!raw) return '';
                    const first = raw.split(',')[0] || '';
                    return first.replace(/^['"]|['"]$/g, '').trim();
                };

                const getFallbackCssFontFamily = (fontFamilyValue, fallbackCssFamily) => {
                    const raw = String(fontFamilyValue || '').trim();
                    if (!raw) return fallbackCssFamily || 'sans-serif';
                    const parts = raw.split(',').map((part) => part.trim()).filter(Boolean);
                    if (parts.length > 1) {
                        return parts.slice(1).join(', ');
                    }
                    return fallbackCssFamily || 'sans-serif';
                };

                const isExactEditableFontAvailable = (fontFamilyValue, fontWeight, fontStyle, sampleText) => {
                    if (!document.fonts || typeof document.fonts.check !== 'function') return true;
                    const primaryFamily = getPrimaryCssFontFamily(fontFamilyValue);
                    if (!primaryFamily) return true;
                    const style = fontStyle || 'normal';
                    const weight = fontWeight || '400';
                    const sample = sanitizeOverlayText(sampleText || 'Hamburgefonstiv');
                    try {
                        return document.fonts.check(`${style} ${weight} 16px "${primaryFamily}"`, sample || 'Hamburgefonstiv');
                    } catch (err) {
                        return true;
                    }
                };

                const getEditableFallbackCssFamily = (field) => {
                    if (field?.dataset?.font) {
                        return getCssFontFamily(field.dataset.font, field.dataset.embeddedFontName || field.dataset.font);
                    }
                    const blockWords = Array.isArray(field?._blockWords) ? field._blockWords : [];
                    if (blockWords.length > 0) {
                        const styleWeights = new Map();
                        blockWords.forEach((word) => {
                            const family = getCssFontFamily(word.font, word.embedded_font_name || word.font);
                            const textWeight = Math.max(
                                1,
                                sanitizeOverlayText(String(word.render_text ?? word.text ?? '')).replace(/\s+/g, '').length
                            );
                            styleWeights.set(family, (styleWeights.get(family) || 0) + textWeight);
                        });
                        let bestFamily = '';
                        let bestScore = -1;
                        styleWeights.forEach((score, family) => {
                            if (score > bestScore) {
                                bestScore = score;
                                bestFamily = family;
                            }
                        });
                        if (bestFamily) return bestFamily;
                    }
                    return field?.style?.fontFamily || 'sans-serif';
                };

                const fieldHasMultipleExtractedStyles = (field) => {
                    const blockWords = Array.isArray(field?._blockWords) ? field._blockWords : [];
                    if (blockWords.length < 2) return false;
                    const styleKeys = new Set();
                    blockWords.forEach((word) => {
                        styleKeys.add(JSON.stringify({
                            font: normalizePdfFontName(word.font || ''),
                            font_weight: String(word.font_weight || (word.bold ? 700 : 400)),
                            font_style: word.italic ? 'italic' : 'normal',
                            font_size: Math.round((Number(word.font_size) || 0) * 10) / 10,
                            color: getWordColor(word, '#000000'),
                        }));
                    });
                    return styleKeys.size > 1;
                };

                const convertPositionedSpansToStyledFlow = (field, textSpan) => {
                    if (!field || !textSpan) return false;
                    const allSpans = Array.from(textSpan.querySelectorAll('span'))
                        .filter((span) => span.style.position === 'absolute');
                    if (!allSpans.length) return false;

                    const fallbackCssFamily = getEditableFallbackCssFamily(field);
                    const lineTolerance = 2;
                    const lines = [];

                    allSpans.forEach((span) => {
                        const top = parseFloat(span.style.top) || 0;
                        const left = parseFloat(span.style.left) || 0;
                        const rect = span.getBoundingClientRect();
                        const height = rect.height || parseFloat(span.style.lineHeight) || parseFloat(span.style.fontSize) || 0;
                        const fontSize = parseFloat(span.style.fontSize) || 0;
                        const lineNumRaw = span.dataset.lineNum;
                        const lineNum = lineNumRaw !== undefined && lineNumRaw !== null && lineNumRaw !== ''
                            ? Number(lineNumRaw)
                            : null;
                        const lineMatchTolerance = Math.max(lineTolerance, fontSize * 0.9);
                        let line = lines.find((candidate) => {
                            const candidateLineNum = candidate.lineNum;
                            if (Number.isFinite(lineNum) && Number.isFinite(candidateLineNum)) {
                                return lineNum === candidateLineNum &&
                                    Math.abs(candidate.referenceTop - top) <= lineMatchTolerance;
                            }
                            return Math.abs(candidate.top - top) <= lineTolerance;
                        });
                        if (!line) {
                            line = { top, referenceTop: top, lineNum, items: [] };
                            lines.push(line);
                        }
                        line.referenceTop = (line.referenceTop * line.items.length + top) / (line.items.length + 1);
                        line.items.push({ span, top, left, height, width: rect.width || 0, fontSize });
                    });

                    if (!lines.length) return false;

                    lines.sort((a, b) => a.top - b.top);
                    const fragment = document.createDocumentFragment();

                    lines.forEach((line, lineIndex) => {
                        const lineEl = document.createElement('div');
                        const sortedItems = line.items.sort((a, b) => a.left - b.left);
                        const lineLeft = Math.min(...sortedItems.map((item) => item.left));
                        const lineFontSize = Math.max(...sortedItems.map((item) => parseFloat(item.span.style.fontSize) || 0), 0);
                        const nextLineTop = lines[lineIndex + 1]?.top;
                        const lineStep = Number.isFinite(nextLineTop)
                            ? Math.max(1, nextLineTop - line.top)
                            : Math.max(1, lineFontSize * 1.15);

                        lineEl.style.display = 'block';
                        lineEl.style.paddingLeft = `${Math.max(0, lineLeft)}px`;
                        lineEl.style.whiteSpace = 'pre';
                        lineEl.style.lineHeight = `${lineStep}px`;

                        sortedItems.forEach(({ span }) => {
                            const clone = span.cloneNode(true);
                            clone.style.position = 'static';
                            clone.style.left = '';
                            clone.style.top = '';
                            clone.style.display = 'inline';
                            clone.style.verticalAlign = 'baseline';
                            clone.style.whiteSpace = 'pre';
                            const fontFamilyValue = clone.style.fontFamily || window.getComputedStyle(span).fontFamily;
                            if (!isExactEditableFontAvailable(
                                fontFamilyValue,
                                clone.style.fontWeight || window.getComputedStyle(span).fontWeight,
                                clone.style.fontStyle || window.getComputedStyle(span).fontStyle,
                                clone.textContent || ''
                            )) {
                                clone.style.fontFamily = getFallbackCssFontFamily(fontFamilyValue, fallbackCssFamily);
                            }
                            lineEl.appendChild(clone);
                        });

                        fragment.appendChild(lineEl);
                        if (lineIndex === lines.length - 1) return;
                    });

                    textSpan.innerHTML = '';
                    textSpan.appendChild(fragment);
                    textSpan.style.whiteSpace = 'pre-wrap';
                    textSpan.style.wordBreak = 'normal';
                    textSpan.style.overflow = 'hidden';
                    return true;
                };

                const formatSplitParagraphMetric = (value) => {
                    const numericValue = Math.round((Number(value) || 0) * 100) / 100;
                    if (!Number.isFinite(numericValue)) {
                        return '0';
                    }
                    return String(numericValue)
                        .replace(/\.0+$/g, '')
                        .replace(/(\.\d*?[1-9])0+$/g, '$1');
                };

                const splitPositionedSpansToAbsolutelyPositionedCharacters = (field, textSpan) => {
                    if (!field || !textSpan) return false;

                    const lineNodes = Array.from(textSpan.children)
                        .filter((node) => node instanceof HTMLElement && node.style.position === 'absolute');
                    if (!lineNodes.length) {
                        return false;
                    }

                    const fallbackCssFamily = getEditableFallbackCssFamily(field);
                    const fragment = document.createDocumentFragment();
                    let previousLineBottom = 0;
                    let maxBottom = 0;
                    let builtCharacterCount = 0;

                    const collectLineSegments = (lineNode) => {
                        const segments = Array.from(lineNode.childNodes)
                            .map((node) => {
                                if (node.nodeType === Node.TEXT_NODE) {
                                    return {
                                        text: String(node.textContent || ''),
                                        styleSource: lineNode,
                                    };
                                }
                                if (node.nodeType === Node.ELEMENT_NODE) {
                                    return {
                                        text: String(node.textContent || ''),
                                        styleSource: node,
                                    };
                                }
                                return null;
                            })
                            .filter((segment) => segment && segment.text.length > 0);

                        if (!segments.length) {
                            segments.push({
                                text: String(lineNode.textContent || ''),
                                styleSource: lineNode,
                            });
                        }

                        return segments;
                    };

                    clusterPositionedSplitParagraphRows(lineNodes)
                        .forEach((row, lineIndex) => {
                            const rowNodes = row.nodes;
                            const rowLeft = rowNodes.reduce((minLeft, node) => Math.min(minLeft, node.left), Infinity);
                            const rowRight = rowNodes.reduce((maxRight, node) => Math.max(maxRight, node.left + node.width), 0);
                            const lineTop = row.top;
                            const lineHeight = Math.max(1, row.height);
                            const marginTop = Math.max(0, lineIndex === 0 ? lineTop : (lineTop - previousLineBottom));
                            const paraEl = document.createElement('p');
                            paraEl.className = 'para-sel';
                            paraEl.dataset.ypos = formatSplitParagraphMetric(lineTop);
                            paraEl.style.margin = `${formatSplitParagraphMetric(marginTop)}px 0 0`;
                            paraEl.style.padding = '0';
                            paraEl.style.width = `${Math.max(1, rowRight - rowLeft)}px`;
                            paraEl.style.minHeight = `${lineHeight}px`;
                            paraEl.style.lineHeight = `${lineHeight}px`;
                            paraEl.style.position = 'static';
                            paraEl.style.whiteSpace = 'pre';

                            rowNodes.forEach(({ lineNode, left: nodeLeft }) => {
                                const segments = collectLineSegments(lineNode);
                                let currentLeft = Math.max(0, nodeLeft - rowLeft);
                                segments.forEach(({ text, styleSource }) => {
                                    const computedStyle = window.getComputedStyle(styleSource);
                                    let fontFamilyValue = styleSource.style.fontFamily || computedStyle.fontFamily || fallbackCssFamily;
                                    const fontWeightValue = styleSource.style.fontWeight || computedStyle.fontWeight || '400';
                                    const fontStyleValue = styleSource.style.fontStyle || computedStyle.fontStyle || 'normal';
                                    const fontSizePx = parseFloat(styleSource.style.fontSize)
                                        || parseFloat(computedStyle.fontSize)
                                        || parseFloat(lineNode.style.fontSize)
                                        || parseFloat(window.getComputedStyle(lineNode).fontSize)
                                        || 12;
                                    const colorValue = styleSource.style.color || computedStyle.color || '#000000';
                                    const textDecorationValue = styleSource.style.textDecoration || computedStyle.textDecoration || 'none';

                                    if (!isExactEditableFontAvailable(fontFamilyValue, fontWeightValue, fontStyleValue, text)) {
                                        fontFamilyValue = getFallbackCssFontFamily(fontFamilyValue, fallbackCssFamily);
                                    }

                                    Array.from(text).forEach((character) => {
                                        const measuredCharacter = character === '\u00A0' ? ' ' : character;
                                        const measuredWidth = Math.max(
                                            measureTextWidth(measuredCharacter, fontSizePx, fontFamilyValue, fontWeightValue, fontStyleValue),
                                            /\S/.test(measuredCharacter) ? fontSizePx * 0.08 : fontSizePx * 0.22
                                        );
                                        const charEl = document.createElement('span');
                                        charEl.className = '_iceni_text-sel';
                                        charEl.textContent = character === ' ' ? '\u00A0' : character;
                                        charEl.dataset.lineNum = String(lineIndex);
                                        charEl.dataset.originY = formatSplitParagraphMetric(lineTop);
                                        charEl.dataset.xpos = formatSplitParagraphMetric(rowLeft + currentLeft);
                                        charEl.dataset.width = formatSplitParagraphMetric(measuredWidth);
                                        charEl.style.position = 'absolute';
                                        charEl.style.left = `${rowLeft + currentLeft}px`;
                                        charEl.style.top = `${lineTop}px`;
                                        charEl.style.padding = '0';
                                        charEl.style.margin = '0';
                                        charEl.style.whiteSpace = 'pre';
                                        charEl.style.fontFamily = fontFamilyValue;
                                        charEl.style.fontSize = `${fontSizePx}px`;
                                        charEl.style.fontWeight = String(fontWeightValue);
                                        charEl.style.fontStyle = fontStyleValue;
                                        charEl.style.color = colorValue;
                                        charEl.style.textDecoration = textDecorationValue;
                                        charEl.style.lineHeight = `${lineHeight}px`;
                                        charEl.style.verticalAlign = 'middle';
                                        paraEl.appendChild(charEl);
                                        currentLeft += measuredWidth;
                                        builtCharacterCount += 1;
                                    });
                                });
                            });

                            previousLineBottom = lineTop + lineHeight;
                            maxBottom = Math.max(maxBottom, previousLineBottom);
                            fragment.appendChild(paraEl);
                        });

                    if (!builtCharacterCount) {
                        return false;
                    }

                    textSpan.innerHTML = '';
                    textSpan.appendChild(fragment);
                    textSpan.style.position = 'relative';
                    textSpan.style.display = 'block';
                    textSpan.style.width = '100%';
                    textSpan.style.whiteSpace = 'normal';
                    textSpan.style.wordBreak = 'normal';
                    textSpan.style.overflow = 'visible';
                    if (maxBottom > 0) {
                        textSpan.style.minHeight = `${maxBottom}px`;
                    }
                    field.dataset.splitParagraphFullyActive = '1';
                    textSpan.dataset.editLayout = 'split-paragraph-fully';
                    return true;
                };

                const buildSplitParagraphCharactersFromSource = (field, textSpan) => {
                    if (!field || !textSpan) return false;

                    const sourceBlock = field._overlaySourceBlock || null;
                    const sourceWords = Array.isArray(field?._blockWords) ? field._blockWords : [];
                    if (!sourceBlock && sourceWords.length === 0) {
                        return false;
                    }

                    const pageWidth = parseFloat(field.dataset.pageWidth || '0');
                    const pageHeight = parseFloat(field.dataset.pageHeight || '0');
                    const canvasWidth = parseFloat(field.dataset.canvasWidth || '0');
                    const canvasHeight = parseFloat(field.dataset.canvasHeight || '0');
                    const scaleX = pageWidth > 0 ? (canvasWidth / pageWidth) : 1;
                    const scaleY = pageHeight > 0 ? (canvasHeight / pageHeight) : 1;
                    const blockLeft = parseFloat(field.dataset.originalLeft || '0') || Number(sourceBlock?.left) || 0;
                    const blockTop = parseFloat(field.dataset.originalTop || '0') || Number(sourceBlock?.top) || 0;
                    const sourceContainer = document.createElement('div');
                    sourceContainer.style.fontFamily = textSpan.style.fontFamily || field.style.fontFamily || '';
                    sourceContainer.style.fontWeight = textSpan.style.fontWeight || field.style.fontWeight || '';
                    sourceContainer.style.fontStyle = textSpan.style.fontStyle || field.style.fontStyle || '';
                    sourceContainer.style.fontSize = textSpan.style.fontSize || field.style.fontSize || '';
                    sourceContainer.style.color = textSpan.style.color || field.style.color || '';

                    let builtPositionedSource = false;
                    if (
                        Array.isArray(sourceBlock?.line_bboxes)
                        && sourceBlock.line_bboxes.length > 1
                        && Array.isArray(sourceBlock?.spans)
                        && sourceBlock.spans.length > 0
                    ) {
                        builtPositionedSource = buildExactBlockLineSpans(
                            sourceContainer,
                            sourceBlock,
                            scaleX,
                            scaleY,
                            blockLeft,
                            blockTop
                        );
                    }

                    if (!builtPositionedSource && sourceWords.length > 0) {
                        buildStyledWordSpans(
                            sourceContainer,
                            sourceWords,
                            scaleX,
                            scaleY,
                            blockLeft,
                            blockTop,
                            sourceBlock,
                            field.dataset.originalText || ''
                        );
                        builtPositionedSource = Array.from(sourceContainer.querySelectorAll('span'))
                            .some((span) => span.style.position === 'absolute');
                    }

                    if (!builtPositionedSource) {
                        return false;
                    }

                    const splitBuiltSource = splitPositionedSpansToAbsolutelyPositionedCharacters(field, sourceContainer);
                    if (!splitBuiltSource) {
                        return false;
                    }

                    textSpan.innerHTML = sourceContainer.innerHTML;
                    textSpan.style.position = sourceContainer.style.position;
                    textSpan.style.display = sourceContainer.style.display;
                    textSpan.style.width = sourceContainer.style.width;
                    textSpan.style.whiteSpace = sourceContainer.style.whiteSpace;
                    textSpan.style.wordBreak = sourceContainer.style.wordBreak;
                    textSpan.style.overflow = sourceContainer.style.overflow;
                    textSpan.style.minHeight = sourceContainer.style.minHeight;
                    textSpan.dataset.editLayout = sourceContainer.dataset.editLayout || 'split-paragraph-fully';
                    return true;
                };

                const normalizePositionedSpansForEditing = (field, textSpan) => {
                    if (!field || !textSpan) return;
                    if (field.dataset.flowNormalized === '1') return;
                    const forceFlowText = field.dataset.forceFlowText === '1';
                    const preserveUnderscores = field.dataset.preserveUnderscores === '1';
                    if (preserveUnderscores) {
                        // Keep absolute word-span layout for underscore form fields.
                        // Converting to plain flowing text causes value drift to the right.
                        delete field.dataset.splitParagraphFullyActive;
                        field.dataset.flowNormalized = '1';
                        return;
                    }
                    const stableFlowText = preserveUnderscores
                        ? normalizeStableFlowText(field.dataset.stableFlowText || '')
                        : collapseLabelValueLines(field.dataset.stableFlowText || '');
                    const lockFormLayout = field.dataset.lockFormLayout === '1';
                    const hasPositionedSpans = textSpan.querySelector('span') &&
                        Array.from(textSpan.querySelectorAll('span')).some(s => s.style.position === 'absolute');
                    const sourceLineBBoxes = Array.isArray(field?._overlaySourceBlock?.line_bboxes)
                        ? field._overlaySourceBlock.line_bboxes
                            .filter((bbox) => Array.isArray(bbox) && bbox.length >= 4)
                            .map((bbox) => bbox.map((value) => Number(value) || 0))
                        : [];
                    const sourceLineCount = sourceLineBBoxes.length > 0
                        ? sourceLineBBoxes.length
                        : (() => {
                            const sourceTextLines = Array.isArray(field?._overlaySourceBlock?.text_lines)
                                ? field._overlaySourceBlock.text_lines
                                    .map((line) => sanitizeOverlayText(line))
                                    .filter((line) => line.length > 0)
                                : [];
                            if (sourceTextLines.length > 0) {
                                return sourceTextLines.length;
                            }
                            const blockWords = Array.isArray(field?._blockWords) ? field._blockWords : [];
                            const lineNums = new Set(
                                blockWords
                                    .map((word) => word?.line_num)
                                    .filter((lineNum) => lineNum !== undefined && lineNum !== null)
                            );
                            return lineNums.size;
                        })();
                    const lineStepCandidates = [];
                    for (let index = 1; index < sourceLineBBoxes.length; index += 1) {
                        const previousTop = Number(sourceLineBBoxes[index - 1]?.[1]) || 0;
                        const currentTop = Number(sourceLineBBoxes[index]?.[1]) || 0;
                        const step = currentTop - previousTop;
                        if (step > 0.5) {
                            lineStepCandidates.push(step);
                        }
                    }
                    const flowedLineHeightPx = lineStepCandidates.length > 0
                        ? `${(lineStepCandidates.reduce((sum, step) => sum + step, 0) / lineStepCandidates.length) * scaleY}px`
                        : '';
                    if (stableFlowText.length > 0 && lockFormLayout) {
                        // Force deterministic edit text for form rows (Name/Address/etc),
                        // even when content already became plain text from prior edits.
                        textSpan.textContent = stableFlowText;
                        textSpan.style.whiteSpace = 'pre';
                        textSpan.style.wordBreak = 'normal';
                        textSpan.style.overflow = 'hidden';
                        if (flowedLineHeightPx) {
                            textSpan.style.lineHeight = flowedLineHeightPx;
                        }
                        delete field.dataset.splitParagraphFullyActive;
                        field.dataset.flowNormalized = '1';
                        return;
                    }
                    if (splitParagraphFullyEnabled && !forceFlowText && sourceLineCount > 1) {
                        const splitFully = hasPositionedSpans
                            ? splitPositionedSpansToAbsolutelyPositionedCharacters(field, textSpan)
                            : buildSplitParagraphCharactersFromSource(field, textSpan);
                        if (splitFully) {
                            if (flowedLineHeightPx) {
                                textSpan.style.lineHeight = flowedLineHeightPx;
                            }
                            field.dataset.flowNormalized = '1';
                            return;
                        }
                    }
                    if (!hasPositionedSpans) {
                        delete field.dataset.splitParagraphFullyActive;
                        field.dataset.flowNormalized = '1';
                        return;
                    }
                    delete field.dataset.splitParagraphFullyActive;
                    delete textSpan.dataset.editLayout;
                    if (fieldHasMultipleExtractedStyles(field) || sourceLineCount > 1) {
                        const converted = convertPositionedSpansToStyledFlow(field, textSpan);
                        if (converted) {
                            if (flowedLineHeightPx) {
                                textSpan.style.lineHeight = flowedLineHeightPx;
                            }
                            field.dataset.flowNormalized = '1';
                            return;
                        }
                    }
                    const plainText = stableFlowText.length > 0
                        ? stableFlowText
                        : positionedSpansToFlowText(textSpan);
                    textSpan.textContent = plainText;
                    // Keep layout locked while editing: preserve explicit spacing/newlines
                    // and prevent automatic reflow from moving tokens across lines.
                    textSpan.style.whiteSpace = 'pre';
                    textSpan.style.wordBreak = 'normal';
                    textSpan.style.overflow = 'hidden';
                    if (flowedLineHeightPx) {
                        textSpan.style.lineHeight = flowedLineHeightPx;
                    }
                    field.dataset.flowNormalized = '1';
                };

                restoreOverlayFieldSourceGeometry = function(field, textSpan) {
                    if (!field || !textSpan || field.dataset.exactGeometry !== '1') {
                        return false;
                    }

                    const pageWidth = parseFloat(field.dataset.pageWidth || '0');
                    const pageHeight = parseFloat(field.dataset.pageHeight || '0');
                    const canvasWidth = parseFloat(field.dataset.canvasWidth || '0');
                    const canvasHeight = parseFloat(field.dataset.canvasHeight || '0');
                    const scaleX = pageWidth > 0 ? (canvasWidth / pageWidth) : 1;
                    const scaleY = pageHeight > 0 ? (canvasHeight / pageHeight) : 1;
                    const blockLeft = parseFloat(field.dataset.originalLeft || '0') || 0;
                    const blockTop = parseFloat(field.dataset.originalTop || '0') || 0;
                    const sourceBlock = field._overlaySourceBlock || null;
                    const sourceWords = Array.isArray(field._blockWords) ? field._blockWords : [];

                    const restoredExactGeometry = buildExactBlockLineSpans(
                        textSpan,
                        sourceBlock,
                        scaleX,
                        scaleY,
                        blockLeft,
                        blockTop
                    );

                    if (!restoredExactGeometry) {
                        textSpan.innerHTML = '';
                        textSpan.textContent = '';
                        buildStyledWordSpans(
                            textSpan,
                            sourceWords,
                            scaleX,
                            scaleY,
                            blockLeft,
                            blockTop,
                            sourceBlock,
                            field.dataset.originalText || ''
                        );
                    }

                    delete field.dataset.flowNormalized;
                    delete field.dataset.splitParagraphFullyActive;
                    delete field.dataset.forceFlowText;
                    delete textSpan.dataset.editLayout;
                    return true;
                };

                const convertSplitParagraphLayoutToFlowText = (field, textSpan) => {
                    if (!field || !textSpan || field.dataset.splitParagraphFullyActive !== '1') {
                        return;
                    }
                    field.dataset.forceFlowText = '1';
                    field.dataset.flowNormalized = '0';
                    normalizePositionedSpansForEditing(field, textSpan);
                    delete field.dataset.forceFlowText;
                };

                // buildBlockRichHtml is defined in the outer scope so
                // markOverlayFieldDirty() can also use it.

                const getWordBounds = (words) => {
                    let minLeft = Infinity;
                    let minTop = Infinity;
                    let maxRight = -Infinity;
                    let maxBottom = -Infinity;
                    words.forEach((word) => {
                        minLeft = Math.min(minLeft, word.left);
                        minTop = Math.min(minTop, word.top);
                        maxRight = Math.max(maxRight, word.left + word.width);
                        maxBottom = Math.max(maxBottom, word.top + word.height);
                    });
                    if (!Number.isFinite(minLeft) || !Number.isFinite(minTop) || !Number.isFinite(maxRight) || !Number.isFinite(maxBottom)) {
                        return null;
                    }
                    return {
                        left: minLeft,
                        top: minTop,
                        width: Math.max(1, maxRight - minLeft),
                        height: Math.max(1, maxBottom - minTop)
                    };
                };

                const computeOverlayPaddingPdf = (block) => {
                    const fontSize = Number(block?.font_size) || 12;
                    if (fontSize >= 40) {
                        // Large display headings need a more generous click/selection
                        // target; their visual boxes are intentionally looser.
                        return Math.max(4, Math.min(fontSize * 0.18, 18));
                    }
                    const basePad = fontSize * 0.15;
                    // Tight padding — just enough for click-targeting
                    return Math.max(1, Math.min(basePad, 5));
                };
                const shouldTrimUnderlinedTailLine = (block) => {
                    if (!block || block._client_line_split) return false;
                    const textLines = Array.isArray(block.text_lines)
                        ? block.text_lines.map((line) => sanitizeOverlayText(line)).filter((line) => line.length > 0)
                        : [];
                    const spans = Array.isArray(block.spans) ? block.spans : [];
                    if (textLines.length < 3 || textLines.length > 4) return false;
                    if (spans.length !== textLines.length) return false;
                    const blockHeight = Number(block.height) || 0;
                    if (blockHeight <= 70) return false;

                    const tailSpan = spans[spans.length - 1];
                    const tailUnderlined = !!(tailSpan?.has_drawn_underline || tailSpan?.suppress_drawn_underline);
                    if (!tailUnderlined) return false;

                    const headSpans = spans.slice(0, -1);
                    const headAllPlain = headSpans.every((span) => !(span?.has_drawn_underline || span?.suppress_drawn_underline));
                    if (!headAllPlain) return false;

                    const headLines = textLines.slice(0, -1);
                    const tailLine = textLines[textLines.length - 1] || '';
                    const headLooksCompact = headLines.every((line) => line.length > 0 && line.length <= 70);
                    const tailLooksTemplateLike = /^[A-Z0-9 .,&()'/-]+$/.test(tailLine) && tailLine.length >= 18;
                    return headLooksCompact && tailLooksTemplateLike;
                };
                const getTrimmedBlockDisplayData = (block) => {
                    const rawTextLines = Array.isArray(block?.text_lines)
                        ? block.text_lines.map((line) => sanitizeOverlayText(line)).filter((line) => line.length > 0)
                        : [];
                    if (!shouldTrimUnderlinedTailLine(block) || rawTextLines.length < 2) {
                        return {
                            trimmed: false,
                            textLines: rawTextLines,
                            bounds: null,
                        };
                    }

                    const keptTextLines = rawTextLines.slice(0, -1);
                    const lineBBoxes = Array.isArray(block?.line_bboxes) ? block.line_bboxes : [];
                    const keptLineBoxes = lineBBoxes.slice(0, keptTextLines.length).filter((lb) => Array.isArray(lb) && lb.length >= 4);
                    let bounds = null;
                    if (keptLineBoxes.length) {
                        const minL = Math.min(...keptLineBoxes.map((lb) => Number(lb[0]) || 0));
                        const minT = Math.min(...keptLineBoxes.map((lb) => Number(lb[1]) || 0));
                        const maxR = Math.max(...keptLineBoxes.map((lb) => Number(lb[2]) || 0));
                        const maxB = Math.max(...keptLineBoxes.map((lb) => Number(lb[3]) || 0));
                        bounds = {
                            left: minL,
                            top: minT,
                            width: Math.max(1, maxR - minL),
                            height: Math.max(1, maxB - minT),
                        };
                    }

                    return {
                        trimmed: true,
                        textLines: keptTextLines,
                        bounds,
                    };
                };
                const renderOverlayUnderlineMasks = () => {
                    // Keep the PDF's original underline strokes visible. Masking them
                    // makes form blanks disappear in overlay mode.
                    return;
                };

                const renderOverlayBlocks = () => {
                    if (!pageData.blocks || pageData.blocks.length === 0) {
                        console.warn('No block data available for block mode');
                        return;
                    }
                    // Use CSS pixel dimensions for overlay coordinate math.
                    // Canvas backing size may be DPR-scaled.
                    const effectiveWidth = viewport.width || overlay.clientWidth || 1;
                    const effectiveHeight = viewport.height || overlay.clientHeight || 1;

                    renderOverlayUnderlineMasks();
                    const scaleX = pageData.width ? effectiveWidth / pageData.width : 1;
                    const scaleY = pageData.height ? effectiveHeight / pageData.height : 1;
                    const literalBoundingBoxBlocks = boundingBoxEditMode && pageData?._overlayLiteralBlocks === true;
                    const overlayWidthPx = Math.max(1, overlay.clientWidth || effectiveWidth);
                    const overlayHeightPx = Math.max(1, overlay.clientHeight || effectiveHeight);
                    const clampRectToOverlay = (left, top, width, height) => {
                        let l = Number.isFinite(left) ? left : 0;
                        let t = Number.isFinite(top) ? top : 0;
                        let w = Number.isFinite(width) ? width : 1;
                        let h = Number.isFinite(height) ? height : 1;

                        w = Math.max(1, Math.min(w, overlayWidthPx));
                        h = Math.max(1, Math.min(h, overlayHeightPx));
                        l = Math.max(0, Math.min(l, overlayWidthPx - w));
                        t = Math.max(0, Math.min(t, overlayHeightPx - h));
                        return { left: l, top: t, width: w, height: h };
                    };
                    const applyClampedRect = (field, left, top, width, height) => {
                        const rect = clampRectToOverlay(left, top, width, height);
                        field.style.left = rect.left + 'px';
                        field.style.top = rect.top + 'px';
                        field.style.width = rect.width + 'px';
                        field.style.height = rect.height + 'px';
                    };
                    const fitOverlayFieldToRenderedContent = (field, textSpan) => {
                        if (!field || !textSpan) return false;
                        if (field.dataset.exactGeometry === '1') {
                            return false;
                        }

                        const fieldLeft = parseFloat(field.style.left) || 0;
                        const fieldTop = parseFloat(field.style.top) || 0;
                        const fieldWidth = parseFloat(field.style.width) || field.offsetWidth || 0;
                        const fieldHeight = parseFloat(field.style.height) || field.offsetHeight || 0;
                        if (fieldWidth <= 0 || fieldHeight <= 0) {
                            return false;
                        }

                        const fieldStyle = window.getComputedStyle(field);
                        const borderX = (parseFloat(fieldStyle.borderLeftWidth || '0') || 0)
                            + (parseFloat(fieldStyle.borderRightWidth || '0') || 0);
                        const borderY = (parseFloat(fieldStyle.borderTopWidth || '0') || 0)
                            + (parseFloat(fieldStyle.borderBottomWidth || '0') || 0);
                        const padX = (parseFloat(fieldStyle.paddingLeft || '0') || 0)
                            + (parseFloat(fieldStyle.paddingRight || '0') || 0);
                        const padY = (parseFloat(fieldStyle.paddingTop || '0') || 0)
                            + (parseFloat(fieldStyle.paddingBottom || '0') || 0);

                        let contentWidth = Math.max(
                            textSpan.scrollWidth || 0,
                            textSpan.getBoundingClientRect().width || 0
                        );
                        let contentHeight = Math.max(
                            textSpan.scrollHeight || 0,
                            textSpan.getBoundingClientRect().height || 0
                        );

                        const positionedChildren = Array.from(textSpan.querySelectorAll('span')).filter((span) => {
                            const style = span.style || {};
                            return style.position === 'absolute';
                        });
                        if (positionedChildren.length > 0) {
                            let maxRight = 0;
                            let maxBottom = 0;
                            positionedChildren.forEach((span) => {
                                const left = parseFloat(span.style.left || '0') || 0;
                                const top = parseFloat(span.style.top || '0') || 0;
                                const rect = span.getBoundingClientRect();
                                const width = rect.width || span.offsetWidth || 0;
                                const height = rect.height || span.offsetHeight || 0;
                                maxRight = Math.max(maxRight, left + width);
                                maxBottom = Math.max(maxBottom, top + height);
                            });
                            contentWidth = Math.max(contentWidth, maxRight);
                            contentHeight = Math.max(contentHeight, maxBottom);
                        }

                        const desiredWidth = Math.ceil(contentWidth + padX + borderX);
                        const desiredHeight = Math.ceil(contentHeight + padY + borderY);
                        const maxWidthPx = parseFloat(field.dataset.maxWidthPx || '');
                        const unclampedNextWidth = Math.max(fieldWidth, desiredWidth);
                        const nextWidth = Number.isFinite(maxWidthPx) && maxWidthPx > 0
                            ? Math.min(unclampedNextWidth, maxWidthPx)
                            : unclampedNextWidth;
                        const nextHeight = Math.max(fieldHeight, desiredHeight);

                        if ((nextWidth - fieldWidth) < 1 && (nextHeight - fieldHeight) < 1) {
                            return false;
                        }

                        applyClampedRect(field, fieldLeft, fieldTop, nextWidth, nextHeight);
                        return true;
                    };

                    // ── Gap-based block splitting ──────────────────────────────
                    // PyMuPDF merges entire table rows into one block. We detect
                    // large horizontal gaps between words on the same line and
                    // split them into separate visual blocks so each table cell
                    // gets its own bounding box.
                    const GAP_FACTOR = 3; // gap > GAP_FACTOR × avg font size = column break
                    const SPLIT_ALIGN_TOLERANCE_PX = 6;
                    const blockHasSplittableInternalGap = (words) => {
                        if (!Array.isArray(words) || words.length < 2) return false;
                        const lineMap = new Map();
                        words.forEach((word) => {
                            const lineNum = word.line_num ?? 0;
                            if (!lineMap.has(lineNum)) lineMap.set(lineNum, []);
                            lineMap.get(lineNum).push(word);
                        });

                        for (const lineWords of lineMap.values()) {
                            const sorted = lineWords.slice().sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0));
                            if (sorted.length < 2) continue;
                            const avgFontSize = sorted.reduce((sum, word) => sum + (Number(word.font_size) || 10), 0) / sorted.length;
                            const gapThreshold = avgFontSize * GAP_FACTOR;
                            for (let i = 1; i < sorted.length; i++) {
                                const prevRight = (Number(sorted[i - 1].left) || 0) + (Number(sorted[i - 1].width) || 0);
                                const currLeft = Number(sorted[i].left) || 0;
                                if ((currLeft - prevRight) > gapThreshold) {
                                    return true;
                                }
                            }
                        }

                        return false;
                    };

                    // Prepare block data only once per extracted page payload. Repeating
                    // the split+retag pass on every re-render can create drifting block
                    // assignments and visual duplicates over time.
                    let expandedBlocks;
                    if (pageData._overlayBlocksPrepared) {
                        expandedBlocks = pageData.blocks || [];
                    } else {
                        pageData.blocks = (pageData.blocks || []).map((block) => ({
                            ...block,
                            _overlayOriginalLeft: Number.isFinite(Number(block?._overlayOriginalLeft))
                                ? Number(block._overlayOriginalLeft)
                                : (Number(block?.left) || 0),
                            _overlayOriginalTop: Number.isFinite(Number(block?._overlayOriginalTop))
                                ? Number(block._overlayOriginalTop)
                                : (Number(block?.top) || 0),
                            _overlayOriginalWidth: Number.isFinite(Number(block?._overlayOriginalWidth))
                                ? Number(block._overlayOriginalWidth)
                                : Math.max(1, Number(block?.width) || 0),
                            _overlayOriginalHeight: Number.isFinite(Number(block?._overlayOriginalHeight))
                                ? Number(block._overlayOriginalHeight)
                                : Math.max(1, Number(block?.height) || 0),
                        }));
                        if (literalBoundingBoxBlocks) {
                            expandedBlocks = pageData.blocks.slice();
                            pageData._overlayBlocksPrepared = true;
                        } else {
                        let nextSyntheticBlockNum = pageData.blocks.reduce((m, b) => Math.max(m, b.block_num), 0) + 1;
                        expandedBlocks = [];
                        const consumedByFormMerge = new Set();

                        pageData.blocks.forEach(block => {
                        if (consumedByFormMerge.has(block.block_num)) {
                            return;
                        }
                        const blockWords = pageData.words
                            ? pageData.words.filter(w => w.block_num === block.block_num)
                            : [];

                        // Avoid double-splitting blocks that were already split upstream
                        // or by this client-side renderer on a prior pass. Some PDFs
                        // still arrive with a surviving large internal word gap even
                        // when `_from_xgap_split` is set, so allow one more pass for
                        // those blocks.
                        if ((block._from_xgap_split || block._client_split) && !blockHasSplittableInternalGap(blockWords)) {
                            expandedBlocks.push(block);
                            return;
                        }

                        // Form-row helper: merge multi-line underscore blocks with their
                        // sibling value blocks (e.g. Address + 1810..., Wife, 1980) into
                        // one composite block.
                        const lineBBoxes = Array.isArray(block.line_bboxes) ? block.line_bboxes : [];
                        const blockTextRaw = sanitizeOverlayText(String(block.text || ''));
                        const hasInlineChoiceLine = (Array.isArray(block.text_lines) ? block.text_lines : [])
                            .some((line) => /_{3,}\s+\S+.*_{3,}\s+\S+/.test(String(line || '')));
                        const looksLikeFormRows = lineBBoxes.length > 1 && blockTextRaw.includes('_') && !hasInlineChoiceLine;
                        if (looksLikeFormRows) {
                            const overlapsVertically = (aTop, aBottom, bTop, bBottom) => {
                                const inter = Math.max(0, Math.min(aBottom, bBottom) - Math.max(aTop, bTop));
                                const minH = Math.max(1, Math.min(aBottom - aTop, bBottom - bTop));
                                return (inter / minH) >= 0.35;
                            };

                            const compositeWords = [...blockWords];
                            const compositeLineTexts = [];
                            const compositeLineBBoxes = [];
                            const valueBlockNums = new Set();

                            lineBBoxes.forEach((lb, idx) => {
                                const lineLeft = lb[0];
                                const lineTop = lb[1];
                                const lineRightRaw = lb[2];
                                const lineBottom = lb[3];

                                const sibling = (pageData.blocks || [])
                                    .filter((ob) => ob && ob.block_num !== block.block_num)
                                    .filter((ob) => overlapsVertically(lineTop, lineBottom, ob.top || 0, (ob.top || 0) + (ob.height || 0)))
                                    .filter((ob) => (Number(ob.left) || 0) > (lineLeft + 4))
                                    .sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0))[0];

                                if (sibling) {
                                    valueBlockNums.add(sibling.block_num);
                                    const sibWords = (pageData.words || []).filter((w) => w.block_num === sibling.block_num);
                                    compositeWords.push(...sibWords);
                                }

                                const rowWords = compositeWords
                                    .filter((w) => overlapsVertically(
                                        lineTop, lineBottom,
                                        (Number(w.top) || 0), (Number(w.top) || 0) + (Number(w.height) || 0)
                                    ))
                                    .sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0));

                                const lineText = rowWords
                                    .map((w) => getOverlayWordDisplayText(w))
                                    .filter((t) => t.length > 0)
                                    .join(' ')
                                    .replace(/[ \t]+/g, ' ')
                                    .trim();
                                compositeLineTexts.push(lineText);
                                compositeLineBBoxes.push([lineLeft, lineTop, lineRightRaw, lineBottom]);
                            });

                            const uniqByGeom = new Map();
                            compositeWords.forEach((w) => {
                                const key = [
                                    Math.round((Number(w.left) || 0) * 100),
                                    Math.round((Number(w.top) || 0) * 100),
                                    Math.round((Number(w.width) || 0) * 100),
                                    Math.round((Number(w.height) || 0) * 100),
                                    sanitizeOverlayText(String(w.text || ''))
                                ].join('|');
                                if (!uniqByGeom.has(key)) uniqByGeom.set(key, w);
                            });
                            const mergedWords = Array.from(uniqByGeom.values());
                            const subNum = nextSyntheticBlockNum++;
                            mergedWords.forEach((w) => { w.block_num = subNum; });
                            valueBlockNums.forEach((bn) => consumedByFormMerge.add(bn));

                            let minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
                            mergedWords.forEach((w) => {
                                minL = Math.min(minL, Number(w.left) || 0);
                                minT = Math.min(minT, Number(w.top) || 0);
                                maxR = Math.max(maxR, (Number(w.left) || 0) + (Number(w.width) || 0));
                                maxB = Math.max(maxB, (Number(w.top) || 0) + (Number(w.height) || 0));
                            });
                            if (!Number.isFinite(minL) || !Number.isFinite(minT) || !Number.isFinite(maxR) || !Number.isFinite(maxB)) {
                                minL = block.left; minT = block.top; maxR = block.left + block.width; maxB = block.top + block.height;
                            }

                            expandedBlocks.push({
                                ...block,
                                _client_split: true,
                                _client_form_merge: true,
                                block_num: subNum,
                                left: minL,
                                top: minT,
                                width: Math.max(1, maxR - minL),
                                height: Math.max(1, maxB - minT),
                                line_count: compositeLineTexts.length || (block.line_count || 1),
                                text: compositeLineTexts.join('\n'),
                                text_lines: compositeLineTexts.length ? compositeLineTexts : (block.text_lines || []),
                                line_bboxes: compositeLineBBoxes.length ? compositeLineBBoxes : lineBBoxes,
                            });
                            return;
                        }

                        if (blockWords.length < 2) {
                            expandedBlocks.push(block);
                            return;
                        }

                        // Group words by line
                        const lineMap = new Map();
                        blockWords.forEach(w => {
                            const ln = w.line_num ?? 0;
                            if (!lineMap.has(ln)) lineMap.set(ln, []);
                            lineMap.get(ln).push(w);
                        });

                        // For single-line blocks: check for column gaps
                        // For multi-line blocks: only split if ALL lines have matching column structure
                        const lineKeys = Array.from(lineMap.keys()).sort((a, b) => a - b);

                        const sortedLineWords = lineKeys.map(k =>
                            [...lineMap.get(k)].sort((a, b) => a.left - b.left)
                        );

                        // Determine candidate split positions per line.
                        const lineSplitPositions = sortedLineWords.map(words => {
                            if (words.length < 2) return [];
                            const avgFontSize = words.reduce((s, w) => s + (w.font_size || 10), 0) / words.length;
                            const gapThreshold = avgFontSize * GAP_FACTOR;
                            const positions = [];
                            for (let i = 1; i < words.length; i++) {
                                const prevRight = words[i - 1].left + words[i - 1].width;
                                const curLeft = words[i].left;
                                const gap = curLeft - prevRight;
                                if (gap > gapThreshold) {
                                    positions.push((prevRight + curLeft) / 2);
                                }
                            }
                            return positions;
                        });

                        // Use the longest line as reference for expected split positions.
                        let refLineIndex = 0;
                        for (let i = 1; i < sortedLineWords.length; i++) {
                            if (sortedLineWords[i].length > sortedLineWords[refLineIndex].length) {
                                refLineIndex = i;
                            }
                        }
                        const splitPositions = lineSplitPositions[refLineIndex];

                        if (splitPositions.length === 0) {
                            // No column gaps found — keep block as-is
                            expandedBlocks.push(block);
                            return;
                        }

                        // Require all lines to have matching column structure.
                        const allLinesMatchColumns = lineSplitPositions.every(positions => {
                            if (positions.length !== splitPositions.length) return false;
                            for (let i = 0; i < positions.length; i++) {
                                if (Math.abs(positions[i] - splitPositions[i]) > SPLIT_ALIGN_TOLERANCE_PX) {
                                    return false;
                                }
                            }
                            return true;
                        });
                        if (!allLinesMatchColumns) {
                            expandedBlocks.push(block);
                            return;
                        }

                        // Split all words into column groups based on gap positions
                        const numCols = splitPositions.length + 1;
                        const columnWords = Array.from({ length: numCols }, () => []);
                        const rowClusterId = `table-row-${pageData.page_number}-${block.block_num}`;
                        const rowClusterBbox = [
                            Number(block.left) || 0,
                            Number(block.top) || 0,
                            (Number(block.left) || 0) + (Number(block.width) || 0),
                            (Number(block.top) || 0) + (Number(block.height) || 0),
                        ];
                        blockWords.forEach(w => {
                            const wCenter = w.left + w.width / 2;
                            let col = 0;
                            for (let s = 0; s < splitPositions.length; s++) {
                                if (wCenter > splitPositions[s]) col = s + 1;
                            }
                            columnWords[col].push(w);
                        });

                        // Create a sub-block for each non-empty column
                        columnWords.forEach(words => {
                            if (words.length === 0) return;
                            let minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
                            words.forEach(w => {
                                minL = Math.min(minL, w.left);
                                minT = Math.min(minT, w.top);
                                maxR = Math.max(maxR, w.left + w.width);
                                maxB = Math.max(maxB, w.top + w.height);
                            });
                            const subNum = nextSyntheticBlockNum++;
                            // Re-tag words so they belong to the new sub-block
                            words.forEach(w => { w.block_num = subNum; });

                            // Build text_lines grouped by line_num
                            const subLineMap = new Map();
                            words.forEach(w => {
                                const ln = w.line_num ?? 0;
                                if (!subLineMap.has(ln)) subLineMap.set(ln, []);
                                subLineMap.get(ln).push(w);
                            });
                            const textLines = [];
                            Array.from(subLineMap.keys()).sort((a, b) => a - b).forEach(ln => {
                                const lineWords = subLineMap.get(ln).sort((a, b) => a.left - b.left);
                                textLines.push(lineWords.map(w => sanitizeOverlayText(w.text)).join(' '));
                            });

                            expandedBlocks.push({
                                ...block,
                                _client_split: true,
                                _client_table_cell: true,
                                _client_table_row_cluster_id: rowClusterId,
                                _client_table_row_cluster_bbox: rowClusterBbox,
                                block_num: subNum,
                                left: minL,
                                top: minT,
                                width: maxR - minL,
                                height: maxB - minT,
                                text: textLines.join('\n'),
                                text_lines: textLines,
                            });
                        });
                        });

                        // ── Drawn-underline trailing-word split ───────────────────────────
                        // When a form-blank line has filler words (has_drawn_underline /
                        // suppress_drawn_underline) followed by template context words that
                        // have no drawn underline (e.g. "and"), split those trailing context
                        // words into their own synthetic block.  This prevents "and" from
                        // appearing inside the editable blank field so the user only edits
                        // the fill-in value, not the surrounding boilerplate.
                        const afterUnderlineSplit = [];
                        expandedBlocks.forEach((block) => {
                            const bWords = (pageData.words || []).filter(
                                (w) => w.block_num === block.block_num
                            );
                            const blockTextLines = Array.isArray(block?.text_lines)
                                ? block.text_lines.map((line) => sanitizeOverlayText(String(line || '')).trim()).filter((line) => line.length > 0)
                                : [];
                            const compactUnderlineRowCandidate = blockTextLines.length > 0
                                && blockTextLines.length <= 2
                                && (Number(block?.width) || 0) <= 360;
                            if (!compactUnderlineRowCandidate) {
                                afterUnderlineSplit.push(block);
                                return;
                            }
                            if (bWords.length < 2) {
                                afterUnderlineSplit.push(block);
                                return;
                            }
                            // Group words by line_num into visual rows.
                            const lnMap = new Map();
                            bWords.forEach((w) => {
                                const ln = w.line_num ?? 0;
                                if (!lnMap.has(ln)) lnMap.set(ln, []);
                                lnMap.get(ln).push(w);
                            });

                            // Collect trailing non-underline words (per-line, after last underline word).
                            const trailingSet = new Set();
                            lnMap.forEach((lineWords) => {
                                const sorted = lineWords.slice().sort(
                                    (a, b) => (Number(a.left) || 0) - (Number(b.left) || 0)
                                );
                                let lastUlIdx = -1;
                                sorted.forEach((w, i) => {
                                    if (w.has_drawn_underline || w.suppress_drawn_underline) lastUlIdx = i;
                                });
                                // No underline words on this line, or underline is the last word → nothing to split.
                                if (lastUlIdx < 0 || lastUlIdx === sorted.length - 1) return;
                                const trailing = sorted.slice(lastUlIdx + 1);
                                // Only split if the trailing words carry real text (not punctuation-only slivers).
                                const meaningful = trailing.filter((w) => {
                                    const t = sanitizeOverlayText(w.text || '').trim();
                                    return t.length > 0 && /[A-Za-z0-9]/.test(t);
                                });
                                if (meaningful.length === 0) return;
                                trailing.forEach((w) => trailingSet.add(w));
                            });

                            if (trailingSet.size === 0) {
                                afterUnderlineSplit.push(block);
                                return;
                            }

                            // Re-tag trailing words to a new synthetic block number.
                            const trailNum = nextSyntheticBlockNum++;
                            const trailingWords = Array.from(trailingSet);
                            trailingWords.forEach((w) => { w.block_num = trailNum; });

                            // Shrink main block bbox to the words that remain.
                            const remainWords = bWords.filter((w) => !trailingSet.has(w));
                            let mL = Infinity, mT = Infinity, mR = -Infinity, mB = -Infinity;
                            remainWords.forEach((w) => {
                                mL = Math.min(mL, Number(w.left) || 0);
                                mT = Math.min(mT, Number(w.top) || 0);
                                mR = Math.max(mR, (Number(w.left) || 0) + (Number(w.width) || 0));
                                mB = Math.max(mB, (Number(w.top) || 0) + (Number(w.height) || 0));
                            });
                            if (!Number.isFinite(mL)) {
                                mL = block.left; mT = block.top;
                                mR = block.left + block.width; mB = block.top + block.height;
                            }
                            afterUnderlineSplit.push({
                                ...block,
                                _client_split: true,
                                left: mL, top: mT,
                                width: Math.max(1, mR - mL),
                                height: Math.max(1, mB - mT),
                            });

                            // Create synthetic block for the trailing context words.
                            let tL = Infinity, tT = Infinity, tR = -Infinity, tB = -Infinity;
                            trailingWords.forEach((w) => {
                                tL = Math.min(tL, Number(w.left) || 0);
                                tT = Math.min(tT, Number(w.top) || 0);
                                tR = Math.max(tR, (Number(w.left) || 0) + (Number(w.width) || 0));
                                tB = Math.max(tB, (Number(w.top) || 0) + (Number(w.height) || 0));
                            });
                            const trailText = trailingWords
                                .slice().sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0))
                                .map((w) => sanitizeOverlayText(w.text || ''))
                                .filter((t) => t.length > 0)
                                .join(' ');
                            afterUnderlineSplit.push({
                                ...block,
                                _client_split: true,
                                _client_underline_trail: true,
                                block_num: trailNum,
                                left: tL, top: tT,
                                width: Math.max(1, tR - tL),
                                height: Math.max(1, tB - tT),
                                text: trailText,
                                text_lines: [trailText],
                            });
                        });
                        expandedBlocks = afterUnderlineSplit;

                        // Split narrow stacked value cells (e.g. "no" + stray "1")
                        // into per-line fields so editing one line does not rewrite
                        // the whole stacked block.
                        const afterNarrowLineSplit = [];
                        const overlapsVertically = (aTop, aBottom, bTop, bBottom) => {
                            const inter = Math.max(0, Math.min(aBottom, bBottom) - Math.max(aTop, bTop));
                            const minH = Math.max(1, Math.min(aBottom - aTop, bBottom - bTop));
                            return (inter / minH) >= 0.35;
                        };
                        const normalizeLineText = (value) => sanitizeOverlayText(String(value || ''))
                            .replace(/\s+/g, ' ')
                            .trim();
                        const shouldSplitNarrowStackedBlock = (block, blockWords) => {
                            if (!block || !Array.isArray(blockWords) || blockWords.length < 2) return false;
                            if (block._client_form_merge || block._client_line_split) return false;
                            const textLines = Array.isArray(block.text_lines)
                                ? block.text_lines.map((line) => normalizeLineText(line)).filter((line) => line.length > 0)
                                : [];
                            const lineBBoxes = Array.isArray(block.line_bboxes) ? block.line_bboxes : [];
                            if (textLines.length !== 2 || lineBBoxes.length !== textLines.length) return false;
                            const blockWidth = Number(block.width) || 0;
                            if (blockWidth <= 0 || blockWidth > 36) return false;
                            if (textLines.some((line) => line.length === 0 || line.length > 8)) return false;

                            const lineWordCounts = lineBBoxes.map((lb) => {
                                const lTop = Number(lb?.[1]) || 0;
                                const lBottom = Number(lb?.[3]) || lTop;
                                return blockWords.filter((word) => {
                                    const wTop = Number(word?.top) || 0;
                                    const wBottom = wTop + (Number(word?.height) || 0);
                                    return overlapsVertically(lTop, lBottom, wTop, wBottom);
                                }).length;
                            });

                            return lineWordCounts.every((count) => count >= 1 && count <= 2);
                        };

                        expandedBlocks.forEach((block) => {
                            const blockWords = (pageData.words || []).filter((w) => w.block_num === block.block_num);
                            if (!shouldSplitNarrowStackedBlock(block, blockWords)) {
                                afterNarrowLineSplit.push(block);
                                return;
                            }

                            const textLines = Array.isArray(block.text_lines) ? block.text_lines : [];
                            const lineBBoxes = Array.isArray(block.line_bboxes) ? block.line_bboxes : [];
                            const sourceOpsByKey = new Set(
                                (Array.isArray(block.source_content_ops) ? block.source_content_ops : []).map((op) => (
                                    `${Number(op?.xref) || 0}:${Number(op?.start) || 0}:${Number(op?.end) || 0}:${String(op?.matched_text || '')}`
                                ))
                            );

                            lineBBoxes.forEach((lb, lineIndex) => {
                                const lTop = Number(lb?.[1]) || 0;
                                const lBottom = Number(lb?.[3]) || lTop;
                                const lineWords = blockWords
                                    .filter((word) => {
                                        const wTop = Number(word?.top) || 0;
                                        const wBottom = wTop + (Number(word?.height) || 0);
                                        return overlapsVertically(lTop, lBottom, wTop, wBottom);
                                    })
                                    .sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0));
                                if (!lineWords.length) return;

                                const subNum = nextSyntheticBlockNum++;
                                lineWords.forEach((word) => { word.block_num = subNum; });

                                const text = normalizeLineText(textLines[lineIndex] || lineWords.map((word) => getOverlayWordDisplayText(word)).join(' '));
                                const minL = Math.min(...lineWords.map((word) => Number(word.left) || 0));
                                const minT = Math.min(...lineWords.map((word) => Number(word.top) || 0));
                                const maxR = Math.max(...lineWords.map((word) => (Number(word.left) || 0) + (Number(word.width) || 0)));
                                const maxB = Math.max(...lineWords.map((word) => (Number(word.top) || 0) + (Number(word.height) || 0)));
                                const seenLineOpKeys = new Set();
                                const lineSourceOps = lineWords
                                    .flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : [])
                                    .filter((op) => {
                                        const key = `${Number(op?.xref) || 0}:${Number(op?.start) || 0}:${Number(op?.end) || 0}:${String(op?.matched_text || '')}`;
                                        if (seenLineOpKeys.has(key)) return false;
                                        seenLineOpKeys.add(key);
                                        return sourceOpsByKey.size === 0 || sourceOpsByKey.has(key);
                                    });

                                afterNarrowLineSplit.push({
                                    ...block,
                                    _client_split: true,
                                    _client_line_split: true,
                                    block_num: subNum,
                                    left: minL,
                                    top: minT,
                                    width: Math.max(1, maxR - minL),
                                    height: Math.max(1, maxB - minT),
                                    line_count: 1,
                                    text,
                                    text_lines: [text],
                                    line_bboxes: [[minL, minT, maxR, maxB]],
                                    source_content_ops: lineSourceOps,
                                });
                            });
                        });
                        expandedBlocks = afterNarrowLineSplit;

                        // Persist the expanded blocks back into pageData so subsequent
                        // re-renders (toggle off/on, zoom, etc.) see the already-split
                        // blocks with matching word block_num values.
                        pageData.blocks = expandedBlocks;
                        pageData._overlayBlocksPrepared = true;
                        }
                    }

                    if (!literalBoundingBoxBlocks) {
                    // Final pass: split tiny stacked value blocks after all client-side
                    // merges so each short line becomes its own editable field.
                    const finalSplitNarrowStackedBlocks = [];
                    const finalNextSyntheticBlockNumStart = (expandedBlocks || []).reduce((m, b) => Math.max(m, Number(b.block_num) || 0), 0) + 1;
                    let finalNextSyntheticBlockNum = finalNextSyntheticBlockNumStart;
                    const finalOverlapsVertically = (aTop, aBottom, bTop, bBottom) => {
                        const inter = Math.max(0, Math.min(aBottom, bBottom) - Math.max(aTop, bTop));
                        const minH = Math.max(1, Math.min(aBottom - aTop, bBottom - bTop));
                        return (inter / minH) >= 0.3;
                    };
                    const finalNormalizeLineText = (value) => sanitizeOverlayText(String(value || ''))
                        .replace(/\s+/g, ' ')
                        .trim();
                    const looksLikeStandaloneCodeLine = (value) => {
                        const text = finalNormalizeLineText(value);
                        if (!text || text.length < 6 || text.length > 24) return false;
                        return /^[A-Z]{3,}-\d{4,}$/i.test(text);
                    };

                    (expandedBlocks || []).forEach((block) => {
                        const blockWords = (pageData.words || []).filter((w) => w.block_num === block.block_num);
                        const rawTextLines = Array.isArray(block?.text_lines)
                            ? block.text_lines.map((line) => finalNormalizeLineText(line))
                            : [];
                        const rawLineBBoxes = Array.isArray(block?.line_bboxes) ? block.line_bboxes : [];
                        const meaningfulLineEntries = rawTextLines
                            .map((line, index) => ({
                                text: line,
                                bbox: rawLineBBoxes[index],
                            }))
                            .filter((entry) => entry.text.length > 0 && Array.isArray(entry.bbox) && entry.bbox.length >= 4);
                        const textLines = meaningfulLineEntries.map((entry) => entry.text);
                        const lineBBoxes = meaningfulLineEntries.map((entry) => entry.bbox);
                        const blockWidth = Number(block?.width) || 0;
                        const shouldSplitNarrowValues = !!block
                            && blockWords.length >= 2
                            && textLines.length >= 2
                            && textLines.length <= 3
                            && lineBBoxes.length === textLines.length
                            && blockWidth > 0
                            && blockWidth <= 24
                            && textLines.every((line) => line.length > 0 && line.length <= 8);
                        const shouldSplitStandaloneCodeColumn = !!block
                            && blockWords.length >= 2
                            && textLines.length >= 2
                            && lineBBoxes.length === textLines.length
                            && blockWidth > 0
                            && blockWidth <= 140
                            && textLines.every((line) => looksLikeStandaloneCodeLine(line));
                        const shouldSplitFinal = shouldSplitNarrowValues || shouldSplitStandaloneCodeColumn;

                        if (!shouldSplitFinal) {
                            finalSplitNarrowStackedBlocks.push(block);
                            return;
                        }

                        const groupedLineWords = lineBBoxes.map((lb) => {
                            const lTop = Number(lb?.[1]) || 0;
                            const lBottom = Number(lb?.[3]) || lTop;
                            return blockWords
                                .filter((word) => {
                                    const wTop = Number(word?.top) || 0;
                                    const wBottom = wTop + (Number(word?.height) || 0);
                                    return finalOverlapsVertically(lTop, lBottom, wTop, wBottom);
                                })
                                .sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0));
                        });

                        const validLineWordGroups = shouldSplitStandaloneCodeColumn
                            ? groupedLineWords.every((lineWords) => lineWords.length >= 1)
                            : groupedLineWords.every((lineWords) => lineWords.length >= 1 && lineWords.length <= 2);
                        if (!validLineWordGroups) {
                            finalSplitNarrowStackedBlocks.push(block);
                            return;
                        }

                        groupedLineWords.forEach((lineWords, lineIndex) => {
                            const subNum = finalNextSyntheticBlockNum++;
                            lineWords.forEach((word) => { word.block_num = subNum; });

                            const minL = Math.min(...lineWords.map((word) => Number(word.left) || 0));
                            const minT = Math.min(...lineWords.map((word) => Number(word.top) || 0));
                            const maxR = Math.max(...lineWords.map((word) => (Number(word.left) || 0) + (Number(word.width) || 0)));
                            const maxB = Math.max(...lineWords.map((word) => (Number(word.top) || 0) + (Number(word.height) || 0)));
                            const text = finalNormalizeLineText(
                                textLines[lineIndex] || lineWords.map((word) => getOverlayWordDisplayText(word)).join(' ')
                            );
                            const seenOpKeys = new Set();
                            const sourceOps = lineWords
                                .flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : [])
                                .filter((op) => {
                                    const key = `${Number(op?.xref) || 0}:${Number(op?.start) || 0}:${Number(op?.end) || 0}:${String(op?.matched_text || '')}`;
                                    if (seenOpKeys.has(key)) return false;
                                    seenOpKeys.add(key);
                                    return true;
                                });

                            finalSplitNarrowStackedBlocks.push({
                                ...block,
                                _client_split: true,
                                _client_line_split: true,
                                block_num: subNum,
                                left: minL,
                                top: minT,
                                width: Math.max(1, maxR - minL),
                                height: Math.max(1, maxB - minT),
                                line_count: 1,
                                text,
                                text_lines: [text],
                                line_bboxes: [[minL, minT, maxR, maxB]],
                                source_content_ops: sourceOps,
                            });
                        });
                    });
                    expandedBlocks = finalSplitNarrowStackedBlocks;

                    // Split a tracked underlined tail line (e.g. "TO CONTRACT
                    // CONCERNING THE PROPERTY AT") out of a taller centered
                    // heading block so it renders as its own field instead of
                    // being swallowed by the header.
                    const separatedUnderlineTailBlocks = [];
                    (expandedBlocks || []).forEach((block) => {
                        const blockWords = (pageData.words || []).filter((word) => word.block_num === block.block_num);
                        if (!shouldTrimUnderlinedTailLine(block) || blockWords.length === 0) {
                            separatedUnderlineTailBlocks.push(block);
                            return;
                        }

                        const textLines = Array.isArray(block.text_lines)
                            ? block.text_lines.map((line) => finalNormalizeLineText(line)).filter((line) => line.length > 0)
                            : [];
                        const spans = Array.isArray(block.spans) ? block.spans : [];
                        const tailLine = textLines[textLines.length - 1] || '';
                        const tailSpan = spans[spans.length - 1] || null;
                        const normalizedTailLine = finalNormalizeLineText(tailLine);
                        const tailWords = blockWords.filter((word) => {
                            const rendered = finalNormalizeLineText(getOverlayWordDisplayText(word));
                            const source = finalNormalizeLineText(word?.text || '');
                            return rendered === normalizedTailLine
                                || source === normalizedTailLine
                                || (rendered.length > 0 && normalizedTailLine.includes(rendered))
                                || (source.length > 0 && normalizedTailLine.includes(source));
                        });

                        if (!tailWords.length) {
                            separatedUnderlineTailBlocks.push(block);
                            return;
                        }

                        const tailNum = finalNextSyntheticBlockNum++;
                        tailWords.forEach((word) => { word.block_num = tailNum; });

                        const minL = Math.min(...tailWords.map((word) => Number(word.left) || 0));
                        const minT = Math.min(...tailWords.map((word) => Number(word.top) || 0));
                        const maxR = Math.max(...tailWords.map((word) => (Number(word.left) || 0) + (Number(word.width) || 0)));
                        const maxB = Math.max(...tailWords.map((word) => (Number(word.top) || 0) + (Number(word.height) || 0)));
                        const seenOpKeys = new Set();
                        const tailSourceOps = tailWords
                            .flatMap((word) => Array.isArray(word?.source_content_ops) ? word.source_content_ops : [])
                            .filter((op) => {
                                const key = `${Number(op?.xref) || 0}:${Number(op?.start) || 0}:${Number(op?.end) || 0}:${String(op?.matched_text || '')}`;
                                if (seenOpKeys.has(key)) return false;
                                seenOpKeys.add(key);
                                return true;
                            });

                        separatedUnderlineTailBlocks.push(block);
                        separatedUnderlineTailBlocks.push({
                            ...block,
                            _client_split: true,
                            _client_trimmed_tail_line: true,
                            block_num: tailNum,
                            left: minL,
                            top: minT,
                            width: Math.max(1, maxR - minL),
                            height: Math.max(1, maxB - minT),
                            line_count: 1,
                            text: tailLine,
                            text_lines: [tailLine],
                            line_bboxes: [[minL, minT, maxR, maxB]],
                            spans: tailSpan ? [tailSpan] : [],
                            source_content_ops: tailSourceOps,
                        });
                    });
                    expandedBlocks = separatedUnderlineTailBlocks;
                    pageData.blocks = expandedBlocks;
                    }

                    // Sort blocks by vertical position (top to bottom) then horizontal (left to right)
                    const sortedBlocks = [...expandedBlocks].sort((a, b) => {
                        const topDiff = a.top - b.top;
                        if (Math.abs(topDiff) > 5) return topDiff;
                        return a.left - b.left;
                    });

                    // Defensive dedupe: extraction can occasionally contain duplicate
                    // or near-duplicate blocks (same text, slightly different bbox).
                    const BLOCK_GEOM_EPS = 0.75;
                    const getBlockTextSig = (blk) => sanitizeOverlayText(
                        (blk.text_single_line || blk.text || (blk.text_lines || []).join(' '))
                    ).replace(/\s+/g, ' ').trim();
                    const getRect = (blk) => ({
                        l: Number(blk.left) || 0,
                        t: Number(blk.top) || 0,
                        r: (Number(blk.left) || 0) + (Number(blk.width) || 0),
                        b: (Number(blk.top) || 0) + (Number(blk.height) || 0)
                    });
                    const rectIou = (a, b) => {
                        const interW = Math.max(0, Math.min(a.r, b.r) - Math.max(a.l, b.l));
                        const interH = Math.max(0, Math.min(a.b, b.b) - Math.max(a.t, b.t));
                        const inter = interW * interH;
                        if (inter <= 0) return 0;
                        const areaA = Math.max(0, a.r - a.l) * Math.max(0, a.b - a.t);
                        const areaB = Math.max(0, b.r - b.l) * Math.max(0, b.b - b.t);
                        const denom = areaA + areaB - inter;
                        return denom > 0 ? (inter / denom) : 0;
                    };
                    // Compute overlap ratio of the SMALLER rect with the larger.
                    // Returns intersection_area / smaller_area (0..1).
                    const rectOverlapSmaller = (a, b) => {
                        const interW = Math.max(0, Math.min(a.r, b.r) - Math.max(a.l, b.l));
                        const interH = Math.max(0, Math.min(a.b, b.b) - Math.max(a.t, b.t));
                        const inter = interW * interH;
                        if (inter <= 0) return 0;
                        const areaA = Math.max(0, a.r - a.l) * Math.max(0, a.b - a.t);
                        const areaB = Math.max(0, b.r - b.l) * Math.max(0, b.b - b.t);
                        const smaller = Math.min(areaA, areaB);
                        return smaller > 0 ? (inter / smaller) : 0;
                    };
                    const looksLikeFormCompositeText = (text) => {
                        const normalized = sanitizeOverlayText(String(text || ''))
                            .replace(/\s+/g, ' ')
                            .trim();
                        return /_{3,}/.test(normalized) && /[A-Za-z][^:\n]{0,120}:/.test(normalized);
                    };
                    const looksLikeFilledValueText = (text) => {
                        const normalized = sanitizeOverlayText(String(text || ''))
                            .replace(/\s+/g, ' ')
                            .trim();
                        return !!normalized
                            && !/_{3,}/.test(normalized)
                            && /[A-Za-z0-9]/.test(normalized)
                            && normalized.length <= 120;
                    };
                    const isLikelyDuplicateBlock = (a, b) => {
                        const textA = a._textSig;
                        const textB = b._textSig;
                        if (!textA || !textB) return false;
                        const iou = rectIou(a._rect, b._rect);
                        const topClose = Math.abs((a.top || 0) - (b.top || 0)) <= 2;
                        const leftClose = Math.abs((a.left || 0) - (b.left || 0)) <= 2;
                        const sameRow = verticalOverlapRatio(a._rect.t, a._rect.b, b._rect.t, b._rect.b) >= 0.6;
                        if (textA === textB) {
                            return iou >= 0.7 || (topClose && leftClose);
                        }
                        const aContainsB = textA.includes(textB);
                        const bContainsA = textB.includes(textA);
                        if ((aContainsB || bContainsA) && iou >= 0.9) {
                            return true;
                        }
                        const shortFrag = Math.min(textA.length, textB.length) <= 4;
                        if (shortFrag && iou >= 0.85 && topClose) {
                            return true;
                        }
                        const overlapSmaller = rectOverlapSmaller(a._rect, b._rect);
                        const preferFormCompositeBlock = sameRow && overlapSmaller >= 0.25 && (
                            (textA.includes(textB) && looksLikeFormCompositeText(textA) && looksLikeFilledValueText(textB))
                            || (textB.includes(textA) && looksLikeFormCompositeText(textB) && looksLikeFilledValueText(textA))
                        );
                        if (preferFormCompositeBlock) {
                            return true;
                        }
                        const textALower = textA.toLowerCase();
                        const textBLower = textB.toLowerCase();
                        const isPrefixSuffixPair =
                            textALower.startsWith(textBLower) ||
                            textBLower.startsWith(textALower) ||
                            textALower.endsWith(textBLower) ||
                            textBLower.endsWith(textALower);
                        const leftNear = Math.abs((a._rect.l || 0) - (b._rect.l || 0)) <= Math.max(
                            8,
                            Math.min(
                                Math.max(1, (a._rect.r || 0) - (a._rect.l || 0)),
                                Math.max(1, (b._rect.r || 0) - (b._rect.l || 0))
                            ) * 0.25
                        );
                        // Catch clipped/truncated extraction fragments like
                        // "create PDF/A-conforming docume" that share the same
                        // row/origin as the full block text.
                        if (isPrefixSuffixPair && sameRow && leftNear && overlapSmaller >= 0.45) {
                            return true;
                        }
                        // Catch overlapping text layers at the same position but with
                        // different text (e.g., prior edit remnants like "violate" vs
                        // "violated").  If the smaller block is mostly inside the
                        // larger one AND they share the same vertical position, they
                        // are overlapping text layers — deduplicate.
                        if (topClose && leftClose) {
                            if (overlapSmaller >= 0.5) {
                                return true;
                            }
                        }
                        return false;
                    };

                    const dedupedBlocks = literalBoundingBoxBlocks ? sortedBlocks.slice() : [];
                    if (!literalBoundingBoxBlocks) {
                        const seenBlockSigs = new Set();
                        sortedBlocks.forEach((blk) => {
                            blk._textSig = getBlockTextSig(blk);
                            blk._rect = getRect(blk);

                            const sig = [
                                blk._textSig,
                                Math.round((blk.left || 0) / BLOCK_GEOM_EPS),
                                Math.round((blk.top || 0) / BLOCK_GEOM_EPS),
                                Math.round((blk.width || 0) / BLOCK_GEOM_EPS),
                                Math.round((blk.height || 0) / BLOCK_GEOM_EPS),
                            ].join('|');
                            if (seenBlockSigs.has(sig)) {
                                return;
                            }

                            let duplicateIndex = -1;
                            for (let i = 0; i < dedupedBlocks.length; i++) {
                                if (isLikelyDuplicateBlock(blk, dedupedBlocks[i])) {
                                    duplicateIndex = i;
                                    break;
                                }
                            }
                            if (duplicateIndex >= 0) {
                                // Keep the richer candidate when two blocks look duplicated.
                                const existing = dedupedBlocks[duplicateIndex];
                                const existingScore = ((existing._textSig || '').length * 1000) + ((existing.width || 0) * (existing.height || 0));
                                const candidateScore = ((blk._textSig || '').length * 1000) + ((blk.width || 0) * (blk.height || 0));
                                if (candidateScore > existingScore) {
                                    dedupedBlocks[duplicateIndex] = blk;
                                }
                                return;
                            }

                            seenBlockSigs.add(sig);
                            dedupedBlocks.push(blk);
                        });
                    }

                    const mergeVerticallyAdjacentBlocks = (blocks) => {
                        if (!Array.isArray(blocks) || blocks.length < 2) return Array.isArray(blocks) ? blocks : [];

                        const sorted = [...blocks].sort((a, b) => {
                            const topDiff = (Number(a.top) || 0) - (Number(b.top) || 0);
                            if (Math.abs(topDiff) > 3) return topDiff;
                            return (Number(a.left) || 0) - (Number(b.left) || 0);
                        });
                        let nextMergedBlockNum = sorted.reduce((maxNum, block) => {
                            return Math.max(maxNum, Number(block?.block_num) || 0);
                        }, 0) + 1;
                        const consumed = new Set();
                        const out = [];
                        const blockWordsCache = new Map();
                        const getCachedBlockWords = (blockNum) => {
                            if (!blockWordsCache.has(blockNum)) {
                                blockWordsCache.set(
                                    blockNum,
                                    (pageData.words || []).filter((w) => String(w.block_num) === String(blockNum))
                                );
                            }
                            return blockWordsCache.get(blockNum);
                        };
                        const overlapsRowBand = (block, rowTop, rowBottom, minRatio = 0.45) => {
                            const bTop = Number(block?.top) || 0;
                            const bBottom = bTop + (Number(block?.height) || 0);
                            return verticalOverlapRatio(bTop, bBottom, rowTop, rowBottom) >= minRatio;
                        };
                        const horizontalOverlapRatio = (leftA, rightA, leftB, rightB) => {
                            const inter = Math.max(0, Math.min(rightA, rightB) - Math.max(leftA, leftB));
                            const minW = Math.max(1, Math.min(rightA - leftA, rightB - leftB));
                            return inter / minW;
                        };
                        const looksLikeStandaloneStackedCode = (textValue, widthValue) => {
                            const text = sanitizeOverlayText(String(textValue || ''))
                                .replace(/\s+/g, '')
                                .trim();
                            const width = Number(widthValue) || 0;
                            if (!text || text.length < 6 || text.length > 24) return false;
                            if (width <= 0 || width > 140) return false;
                            if (!/[A-Za-z]/.test(text) || !/\d/.test(text)) return false;
                            if (!/^[A-Za-z0-9-]+$/.test(text)) return false;
                            return text.includes('-') || /^[A-Za-z]{3,}\d{2,}$/.test(text);
                        };
                        const getMeaningfulBlockLines = (block) => (
                            Array.isArray(block?.text_lines)
                                ? block.text_lines
                                    .map((line) => sanitizeOverlayText(String(line || '')).replace(/\s+/g, ' ').trim())
                                    .filter((line) => line.length > 0)
                                : []
                        );
                        const isStandaloneListMarkerBlock = (block) => {
                            const lines = getMeaningfulBlockLines(block);
                            if (lines.length !== 1) return false;
                            return /^(?:\(?\d{1,3}[A-Za-z]?\)|\d{1,3}[.)]|[A-Za-z][.)]|[•◦▪■▶▲])$/.test(lines[0]);
                        };
                        const isCalloutParagraphBlock = (block) => {
                            const lines = getMeaningfulBlockLines(block);
                            if (!lines.length) return false;
                            return /^(?:NOTE|NOTES|IMPORTANT|WARNING|CAUTION|NOTICE|ATTENTION)\s*:/.test(lines[0]);
                        };
                        const isDifferentColumn = (block, colLeft, colRight) => {
                            const bLeft = Number(block?.left) || 0;
                            const bRight = bLeft + (Number(block?.width) || 0);
                            const overlap = horizontalOverlapRatio(colLeft, colRight, bLeft, bRight);
                            const colCenter = colLeft + ((colRight - colLeft) / 2);
                            const bCenter = bLeft + ((bRight - bLeft) / 2);
                            return overlap < 0.45 && Math.abs(bCenter - colCenter) > Math.max(18, Math.min(colRight - colLeft, bRight - bLeft) * 0.35);
                        };
                        const hasSharedRowStartPeers = (bottomBlock, colLeft, colRight, allBlocks) => {
                            const blockList = Array.isArray(allBlocks) ? allBlocks : [];
                            const bottomTop = Number(bottomBlock?.top) || 0;
                            const distinctPeerColumns = [];

                            blockList.forEach((other) => {
                                if (!other || other === bottomBlock) return;
                                if (!isDifferentColumn(other, colLeft, colRight)) return;
                                const otherTop = Number(other.top) || 0;
                                const otherLeft = Number(other.left) || 0;
                                const otherRight = otherLeft + (Number(other.width) || 0);
                                const otherCenter = otherLeft + ((otherRight - otherLeft) / 2);
                                const rowStartTol = Math.max(4, Math.min(10, (Number(other.height) || 0) * 0.35));
                                if (Math.abs(otherTop - bottomTop) > rowStartTol) return;

                                const sameColumnIdx = distinctPeerColumns.findIndex((entry) =>
                                    horizontalOverlapRatio(entry.left, entry.right, otherLeft, otherRight) >= 0.35 &&
                                    Math.abs(entry.center - otherCenter) <= Math.max(20, Math.min(entry.right - entry.left, otherRight - otherLeft) * 0.45)
                                );
                                if (sameColumnIdx === -1) {
                                    distinctPeerColumns.push({ left: otherLeft, right: otherRight, center: otherCenter });
                                }
                            });

                            return distinctPeerColumns.length >= 2;
                        };
                        const hasParallelRowPeers = (topBlock, bottomBlock, allBlocks) => {
                            const blockList = Array.isArray(allBlocks) ? allBlocks : [];
                            if (blockList.length < 4) return false;

                            const aL = Number(topBlock.left) || 0;
                            const aT = Number(topBlock.top) || 0;
                            const aW = Math.max(1, Number(topBlock.width) || 0);
                            const aH = Math.max(1, Number(topBlock.height) || 0);
                            const aR = aL + aW;
                            const aB = aT + aH;
                            const bL = Number(bottomBlock.left) || 0;
                            const bT = Number(bottomBlock.top) || 0;
                            const bW = Math.max(1, Number(bottomBlock.width) || 0);
                            const bH = Math.max(1, Number(bottomBlock.height) || 0);
                            const bR = bL + bW;
                            const bB = bT + bH;

                            const colLeft = Math.min(aL, bL);
                            const colRight = Math.max(aR, bR);

                            const peerTopBlocks = blockList.filter((other) => {
                                if (!other || other === topBlock || other === bottomBlock) return false;
                                if (!isDifferentColumn(other, colLeft, colRight)) return false;
                                return overlapsRowBand(other, aT, aB);
                            });
                            if (!peerTopBlocks.length) return false;

                            const peerBottomBlocks = blockList.filter((other) => {
                                if (!other || other === topBlock || other === bottomBlock) return false;
                                if (!isDifferentColumn(other, colLeft, colRight)) return false;
                                return overlapsRowBand(other, bT, bB);
                            });
                            if (!peerBottomBlocks.length) return false;

                            return peerTopBlocks.some((topPeer) => {
                                const tpL = Number(topPeer.left) || 0;
                                const tpR = tpL + (Number(topPeer.width) || 0);
                                const tpCenter = tpL + ((tpR - tpL) / 2);
                                const tpTop = Number(topPeer.top) || 0;
                                const tpBottom = tpTop + (Number(topPeer.height) || 0);

                                return peerBottomBlocks.some((bottomPeer) => {
                                    if (bottomPeer === topPeer) return false;
                                    const bpL = Number(bottomPeer.left) || 0;
                                    const bpR = bpL + (Number(bottomPeer.width) || 0);
                                    const bpCenter = bpL + ((bpR - bpL) / 2);
                                    const samePeerColumn = horizontalOverlapRatio(tpL, tpR, bpL, bpR) >= 0.35 &&
                                        Math.abs(tpCenter - bpCenter) <= Math.max(20, Math.min(tpR - tpL, bpR - bpL) * 0.45);
                                    if (!samePeerColumn) return false;

                                    const bpTop = Number(bottomPeer.top) || 0;
                                    if (bpTop < tpTop) return false;
                                    if (overlapsRowBand(topPeer, bT, bB, 0.25)) return false;
                                    if (overlapsRowBand(bottomPeer, aT, aB, 0.25)) return false;

                                    return true;
                                });
                            });
                        };
                        const shouldMergeStackedBlocks = (topBlock, bottomBlock, allBlocks) => {
                            if (!topBlock || !bottomBlock) return false;
                            if (topBlock._client_form_merge || bottomBlock._client_form_merge) return false;
                            if (topBlock._client_line_split || bottomBlock._client_line_split) return false;
                            if (isStandaloneListMarkerBlock(topBlock) || isStandaloneListMarkerBlock(bottomBlock)) return false;
                            if (isCalloutParagraphBlock(topBlock) || isCalloutParagraphBlock(bottomBlock)) return false;

                            const aL = Number(topBlock.left) || 0;
                            const aT = Number(topBlock.top) || 0;
                            const aW = Math.max(1, Number(topBlock.width) || 0);
                            const aH = Math.max(1, Number(topBlock.height) || 0);
                            const aR = aL + aW;
                            const aB = aT + aH;
                            const bL = Number(bottomBlock.left) || 0;
                            const bT = Number(bottomBlock.top) || 0;
                            const bW = Math.max(1, Number(bottomBlock.width) || 0);
                            const bH = Math.max(1, Number(bottomBlock.height) || 0);
                            const bR = bL + bW;
                            const bB = bT + bH;

                            if (bT < aT) return false;

                            const colLeft = Math.min(aL, bL);
                            const colRight = Math.max(aR, bR);

                            const interW = Math.max(0, Math.min(aR, bR) - Math.max(aL, bL));
                            const xOverlapRatio = interW / Math.max(1, Math.min(aW, bW));
                            if (xOverlapRatio < 0.55) return false;

                            const centerA = aL + (aW / 2);
                            const centerB = bL + (bW / 2);
                            if (Math.abs(centerA - centerB) > Math.max(16, Math.min(aW, bW) * 0.18)) return false;

                            const verticalGap = bT - aB;
                            const verticalOverlap = Math.max(0, aB - bT);
                            const minHeight = Math.max(1, Math.min(aH, bH));
                            const maxGap = Math.max(8, Math.min(18, minHeight * 0.9));
                            if (verticalGap > maxGap) return false;
                            if ((verticalOverlap / minHeight) > 0.22) return false;

                            const textA = getBlockTextSig(topBlock);
                            const textB = getBlockTextSig(bottomBlock);
                            if (!textA || !textB) return false;
                            const lowerStartsStructuredItem = /^\s*(?:\d+[.)]|[A-Za-z][.)]|[ivxlcdm]+[.)])\s/.test(textB);
                            const upperEndsSectionLeadIn = /(?:[:;]\s*|follows:\s*)$/i.test(textA);
                            if (lowerStartsStructuredItem && (upperEndsSectionLeadIn || verticalGap >= 6)) {
                                return false;
                            }
                            const shortStackedValues = Math.max(textA.length, textB.length) <= 8
                                && Math.max(aW, bW) <= 24
                                && /^[A-Za-z0-9 ]+$/.test(textA)
                                && /^[A-Za-z0-9 ]+$/.test(textB);
                            if (shortStackedValues) return false;
                            if (looksLikeStandaloneStackedCode(textA, aW) && looksLikeStandaloneStackedCode(textB, bW)) {
                                return false;
                            }

                            const hasIntervening = (allBlocks || []).some((other) => {
                                if (!other || other === topBlock || other === bottomBlock) return false;
                                const oL = Number(other.left) || 0;
                                const oT = Number(other.top) || 0;
                                const oW = Math.max(1, Number(other.width) || 0);
                                const oH = Math.max(1, Number(other.height) || 0);
                                const oR = oL + oW;
                                const oB = oT + oH;
                                if (oT < (aT - 2) || oB > (bB + 2)) return false;
                                const interW2 = Math.max(0, Math.min(Math.max(aR, bR), oR) - Math.max(Math.min(aL, bL), oL));
                                const columnW = Math.max(1, Math.min(Math.max(aR, bR) - Math.min(aL, bL), oW));
                                return (interW2 / columnW) >= 0.55 && oT > aT && oB < bB;
                            });
                            if (hasIntervening) return false;
                            if (hasSharedRowStartPeers(bottomBlock, colLeft, colRight, allBlocks)) return false;
                            if (hasParallelRowPeers(topBlock, bottomBlock, allBlocks)) return false;

                            return true;
                        };
                        const buildMergedBlock = (cluster) => {
                            const clusterEntries = cluster.map((block) => ({
                                block,
                                words: getCachedBlockWords(block.block_num),
                            }));
                            const mergedWords = clusterEntries.flatMap((entry) => entry.words);
                            if (!mergedWords.length) return null;

                            const newBlockNum = nextMergedBlockNum++;
                            mergedWords.forEach((w) => { w.block_num = newBlockNum; });

                            let minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
                            mergedWords.forEach((w) => {
                                const wL = Number(w.left) || 0;
                                const wT = Number(w.top) || 0;
                                const wR = wL + (Number(w.width) || 0);
                                const wB = wT + (Number(w.height) || 0);
                                minL = Math.min(minL, wL);
                                minT = Math.min(minT, wT);
                                maxR = Math.max(maxR, wR);
                                maxB = Math.max(maxB, wB);
                            });

                            const mergedLineBoxes = [];
                            const mergedTextLines = [];
                            clusterEntries.forEach(({ block, words }) => {
                                const lineBBoxes = Array.isArray(block.line_bboxes) && block.line_bboxes.length
                                    ? block.line_bboxes
                                    : [[
                                        Number(block.left) || 0,
                                        Number(block.top) || 0,
                                        (Number(block.left) || 0) + (Number(block.width) || 0),
                                        (Number(block.top) || 0) + (Number(block.height) || 0),
                                    ]];
                                lineBBoxes.forEach((lb) => {
                                    mergedLineBoxes.push([lb[0], lb[1], lb[2], lb[3]]);
                                    const lineWords = words
                                        .filter((w) => verticalOverlapRatio(
                                            Number(w.top) || 0,
                                            (Number(w.top) || 0) + (Number(w.height) || 0),
                                            Number(lb[1]) || 0,
                                            Number(lb[3]) || (Number(lb[1]) || 0)
                                        ) >= 0.35)
                                        .sort((a, b) => (Number(a.left) || 0) - (Number(b.left) || 0));
                                    const lineText = lineWords
                                        .map((w) => getOverlayWordDisplayText(w))
                                        .filter((t) => t.length > 0)
                                        .join(' ')
                                        .replace(/[ \t]+/g, ' ')
                                        .trim();
                                    if (lineText) mergedTextLines.push(lineText);
                                });
                            });

                            if (!Number.isFinite(minL) || !Number.isFinite(minT) || !Number.isFinite(maxR) || !Number.isFinite(maxB)) {
                                return null;
                            }

                            const modelBase = cluster[0];
                            const sourceSegments = clusterEntries
                                .map(({ block, words }) => buildOverlaySourceSegmentForBlock(block, words))
                                .filter(Boolean);
                            const mergedFontSizes = mergedWords
                                .map((w) => Number(w.font_size) || 0)
                                .filter((v) => v > 0)
                                .sort((a, b) => a - b);
                            const representativeFontSize = mergedFontSizes.length
                                ? mergedFontSizes[Math.floor((mergedFontSizes.length - 1) / 2)]
                                : (Number(modelBase.font_size) || 12);
                            const minMergedFontSize = mergedFontSizes.length ? mergedFontSizes[0] : representativeFontSize;
                            const maxMergedFontSize = mergedFontSizes.length ? mergedFontSizes[mergedFontSizes.length - 1] : representativeFontSize;
                            const mergedLineHeights = clusterEntries
                                .flatMap(({ block }) => {
                                    const values = [];
                                    if (Number(block.line_height) > 0) values.push(Number(block.line_height));
                                    if (Number(block.avg_line_height) > 0) values.push(Number(block.avg_line_height));
                                    if (Array.isArray(block.line_bboxes)) {
                                        block.line_bboxes.forEach((lb) => {
                                            const h = (Number(lb?.[3]) || 0) - (Number(lb?.[1]) || 0);
                                            if (h > 0) values.push(h);
                                        });
                                    }
                                    return values;
                                })
                                .filter((v) => v > 0)
                                .sort((a, b) => a - b);
                            const representativeLineHeight = mergedLineHeights.length
                                ? mergedLineHeights[Math.floor((mergedLineHeights.length - 1) / 2)]
                                : (Number(modelBase.avg_line_height) || Number(modelBase.line_height) || (representativeFontSize * 1.2));
                            const styleWeights = new Map();
                            mergedWords.forEach((w) => {
                                const textWeight = Math.max(
                                    1,
                                    sanitizeOverlayText(String(
                                        (w.render_text !== undefined && w.render_text !== null) ? w.render_text : (w.text || '')
                                    )).replace(/\s+/g, '').length
                                );
                                const styleKey = JSON.stringify({
                                    font: w.font || modelBase.font || '',
                                    font_size: Number(w.font_size) || representativeFontSize,
                                    font_weight: Number(w.font_weight) || (w.bold ? 700 : 400),
                                    italic: !!w.italic,
                                    bold: !!w.bold,
                                    color: w.color,
                                    hex_color: w.hex_color || null,
                                    font_xref: w.font_xref ?? null,
                                });
                                styleWeights.set(styleKey, (styleWeights.get(styleKey) || 0) + textWeight);
                            });
                            let dominantStyle = null;
                            let dominantScore = -1;
                            styleWeights.forEach((score, styleKey) => {
                                if (score > dominantScore) {
                                    dominantScore = score;
                                    dominantStyle = JSON.parse(styleKey);
                                }
                            });
                            return {
                                ...modelBase,
                                _client_split: true,
                                _client_vertical_merge: true,
                                _client_mixed_font_merge: (maxMergedFontSize - minMergedFontSize) >= 8,
                                font: dominantStyle?.font || modelBase.font,
                                block_num: newBlockNum,
                                left: minL,
                                top: minT,
                                width: Math.max(1, maxR - minL),
                                height: Math.max(1, maxB - minT),
                                line_count: mergedLineBoxes.length || mergedTextLines.length,
                                text: mergedTextLines.join('\n'),
                                text_lines: mergedTextLines,
                                line_bboxes: mergedLineBoxes,
                                font_size: Number(dominantStyle?.font_size) || representativeFontSize,
                                line_height: representativeLineHeight,
                                avg_line_height: representativeLineHeight,
                                font_weight: String(dominantStyle?.font_weight || modelBase.font_weight || (modelBase.bold ? 700 : 400)),
                                bold: dominantStyle?.bold ?? modelBase.bold,
                                italic: dominantStyle?.italic ?? modelBase.italic,
                                color: dominantStyle?.color ?? modelBase.color,
                                hex_color: dominantStyle?.hex_color || modelBase.hex_color,
                                font_xref: dominantStyle?.font_xref ?? modelBase.font_xref,
                                _overlay_source_segments: sourceSegments,
                            };
                        };
                        for (let i = 0; i < sorted.length; i++) {
                            const base = sorted[i];
                            if (!base || consumed.has(base.block_num)) continue;

                            const cluster = [base];
                            let current = base;
                            for (let j = i + 1; j < sorted.length; j++) {
                                const candidate = sorted[j];
                                if (!candidate || consumed.has(candidate.block_num)) continue;
                                if (!shouldMergeStackedBlocks(current, candidate, sorted)) continue;
                                cluster.push(candidate);
                                current = candidate;
                            }

                            if (cluster.length > 1) {
                                cluster.forEach((blk) => consumed.add(blk.block_num));
                                const merged = buildMergedBlock(cluster);
                                if (merged) {
                                    out.push(merged);
                                    continue;
                                }
                                cluster.forEach((blk) => out.push(blk));
                                continue;
                            }

                            consumed.add(base.block_num);
                            out.push(base);
                        }

                        return out.sort((a, b) => {
                            const topDiff = (Number(a.top) || 0) - (Number(b.top) || 0);
                            if (Math.abs(topDiff) > 3) return topDiff;
                            return (Number(a.left) || 0) - (Number(b.left) || 0);
                        });
                    };
                    const mergedAdjacentBlocks = literalBoundingBoxBlocks
                        ? dedupedBlocks
                        : mergeVerticallyAdjacentBlocks(dedupedBlocks);
                    pageData.blocks = mergedAdjacentBlocks;

                    const isLikelyOrphanTinyBlock = (block, textValue, allBlocks) => {
                        if (block?._client_line_split) return false;
                        const t = sanitizeOverlayText(String(textValue || '')).trim();
                        if (!t || t.length > 2 || !/[A-Za-z0-9]/.test(t)) return false;
                        const bL = Number(block.left) || 0;
                        const bT = Number(block.top) || 0;
                        const bW = Math.max(0.1, Number(block.width) || 0);
                        const bH = Math.max(0.1, Number(block.height) || 0);
                        const bR = bL + bW;
                        const bB = bT + bH;
                        const bCx = bL + (bW / 2);
                        const bArea = bW * bH;

                        return (allBlocks || []).some((other) => {
                            if (!other || other === block) return false;
                            const oText = sanitizeOverlayText(String(other.text_single_line || other.text || '')).replace(/\s+/g, ' ').trim();
                            if (oText.length < 8) return false;
                            const oL = Number(other.left) || 0;
                            const oT = Number(other.top) || 0;
                            const oW = Math.max(0.1, Number(other.width) || 0);
                            const oH = Math.max(0.1, Number(other.height) || 0);
                            const oR = oL + oW;
                            const oB = oT + oH;
                            const oArea = oW * oH;
                            if (oArea <= bArea * 3) return false;
                            const yOverlap = verticalOverlapRatio(bT, bB, oT, oB);
                            if (yOverlap < 0.6) return false;
                            const centerInsideX = bCx >= (oL - 1) && bCx <= (oR + 1);
                            const nestedHoriz = bL >= (oL - 1) && bR <= (oR + 1);
                            return centerInsideX || nestedHoriz;
                        });
                    };
                    const isValueShadowOfCompositeField = (block, textValue, allBlocks) => {
                        if (block?._client_line_split) return false;
                        const candidateText = sanitizeOverlayText(String(textValue || '')).replace(/\s+/g, ' ').trim();
                        if (!candidateText || !looksLikeFilledValueText(candidateText)) return false;
                        const candidateRect = getRect(block);
                        return (allBlocks || []).some((other) => {
                            if (!other || other === block) return false;
                            const otherText = sanitizeOverlayText(
                                (Array.isArray(other.text_lines) && other.text_lines.length)
                                    ? other.text_lines.join('\n')
                                    : (other.text || '')
                            ).replace(/\s+/g, ' ').trim();
                            const looksLikeCompositeOwner = looksLikeFormCompositeText(otherText)
                                || (otherText.includes(':') && otherText.length > (candidateText.length + 4));
                            if (!otherText || !looksLikeCompositeOwner) return false;
                            if (!otherText.includes(candidateText)) return false;
                            const otherRect = getRect(other);
                            const overlapSmaller = rectOverlapSmaller(candidateRect, otherRect);
                            const sameRow = verticalOverlapRatio(candidateRect.t, candidateRect.b, otherRect.t, otherRect.b) >= 0.2;
                            return sameRow && overlapSmaller >= 0.15;
                        });
                    };

                    // Pre-compute base rectangles for all blocks so we can clamp padding to prevent overlaps
                    const blockBaseRects = mergedAdjacentBlocks.map((blk) => {
                        const blkKey = `block-${pageData.page_number}-${blk.block_num}`;
                        const blkEdit = getOverlayStoredEdit(blkKey);
                        const blkWords = pageData.words
                            ? pageData.words.filter((w) => w.block_num === blk.block_num)
                            : [];

                        let bL = blk.left, bT = blk.top, bW = blk.width, bH = blk.height;
                        if (!literalBoundingBoxBlocks && !blkEdit && blkWords.length > 0) {
                            const bounds = getWordBounds(blkWords);
                            if (bounds) { bL = bounds.left; bT = bounds.top; bW = bounds.width; bH = Math.max(bH, bounds.height); }
                        }

                        const baseL = blkEdit ? blkEdit.bbox[0] : bL;
                        const baseT = blkEdit ? blkEdit.bbox[1] : bT;
                        const baseW = blkEdit ? (blkEdit.bbox[2] - blkEdit.bbox[0]) : bW;
                        const baseH = blkEdit ? (blkEdit.bbox[3] - blkEdit.bbox[1]) : bH;
                        const desired = (literalBoundingBoxBlocks || blkEdit) ? 0 : computeOverlayPaddingPdf(blk);
                        return { baseL, baseT, baseW, baseH, desired };
                    });

                    // For each block, clamp its padding so padded boxes never overlap neighbours
                    const blockClampedPad = blockBaseRects.map((rect, i) => {
                        let maxPad = rect.desired;
                        for (let j = 0; j < blockBaseRects.length; j++) {
                            if (j === i) continue;
                            const o = blockBaseRects[j];
                            const rectRight = rect.baseL + rect.baseW;
                            const rectBottom = rect.baseT + rect.baseH;
                            const otherRight = o.baseL + o.baseW;
                            const otherBottom = o.baseT + o.baseH;
                            const rectArea = Math.max(1, rect.baseW * rect.baseH);
                            const otherArea = Math.max(1, o.baseW * o.baseH);
                            const rectContainsOther =
                                rect.baseL <= (o.baseL + 2) &&
                                rectRight >= (otherRight - 2) &&
                                rect.baseT <= (o.baseT + 2) &&
                                rectBottom >= (otherBottom - 2);
                            const otherContainsRect =
                                o.baseL <= (rect.baseL + 2) &&
                                otherRight >= (rectRight - 2) &&
                                o.baseT <= (rect.baseT + 2) &&
                                otherBottom >= (rectBottom - 2);
                            const nestedAreaRatio = rectContainsOther
                                ? (rectArea / otherArea)
                                : (otherContainsRect ? (otherArea / rectArea) : 0);
                            const isLargeNestedPair = nestedAreaRatio >= 3;
                            // Check if blocks share horizontal span (potential vertical overlap)
                            const hOverlap = rect.baseL < o.baseL + o.baseW && rect.baseL + rect.baseW > o.baseL;
                            // Check if blocks share vertical span (potential horizontal overlap)
                            const vOverlap = rect.baseT < o.baseT + o.baseH && rect.baseT + rect.baseH > o.baseT;

                            if (hOverlap) {
                                if (isLargeNestedPair) {
                                    continue;
                                }
                                let gap;
                                if (o.baseT >= rect.baseT + rect.baseH) {
                                    gap = o.baseT - (rect.baseT + rect.baseH);
                                } else if (rect.baseT >= o.baseT + o.baseH) {
                                    gap = rect.baseT - (o.baseT + o.baseH);
                                } else {
                                    gap = 0;
                                }
                                maxPad = Math.min(maxPad, gap / 2);
                            }
                            if (vOverlap) {
                                if (isLargeNestedPair) {
                                    continue;
                                }
                                let gap;
                                if (o.baseL >= rect.baseL + rect.baseW) {
                                    gap = o.baseL - (rect.baseL + rect.baseW);
                                } else if (rect.baseL >= o.baseL + o.baseW) {
                                    gap = rect.baseL - (o.baseL + o.baseW);
                                } else {
                                    gap = 0;
                                }
                                maxPad = Math.min(maxPad, gap / 2);
                            }
                        }
                        return Math.max(0, maxPad);
                    });
                    const blockRightGapLimit = blockBaseRects.map((rect, i) => {
                        let maxRightExpansion = Infinity;
                        const rectTop = rect.baseT;
                        const rectBottom = rect.baseT + rect.baseH;
                        const rectRight = rect.baseL + rect.baseW;
                        for (let j = 0; j < blockBaseRects.length; j++) {
                            if (j === i) continue;
                            const other = blockBaseRects[j];
                            const otherTop = other.baseT;
                            const otherBottom = other.baseT + other.baseH;
                            const verticalOverlap = Math.max(0, Math.min(rectBottom, otherBottom) - Math.max(rectTop, otherTop));
                            const minHeight = Math.max(1, Math.min(rect.baseH, other.baseH));
                            if ((verticalOverlap / minHeight) < 0.3) {
                                continue;
                            }
                            const otherLeft = other.baseL;
                            if (otherLeft < rectRight) {
                                continue;
                            }
                            const gap = otherLeft - rectRight;
                            maxRightExpansion = Math.min(maxRightExpansion, gap / 2);
                        }
                        return Number.isFinite(maxRightExpansion)
                            ? Math.max(0, maxRightExpansion)
                            : null;
                    });

                    const renderedBlockKeys = new Set();
                    const renderedFieldFingerprints = [];
                    const normalizeSavedOverlayText = (value) => sanitizeOverlayText(String(value || ''))
                        .replace(/\s+/g, ' ')
                        .trim()
                        .toLowerCase();
                    const hasEquivalentPromotedAnnotation = (block, blockTextValue, blockLeftValue, blockTopValue, blockWidthValue, blockHeightValue, blockFontSizeValue) => {
                        const blockPageIndex = (Number(pageData.page_number) || 1) - 1;
                        const pageHeightPdf = Number(pageData.height || pageData.page_height || 0);
                        const promotedAnnotationsOnPage = annotations.filter((annotation) => (
                            annotation
                            && annotation.type === 'text'
                            && annotation.promotedFromExtraction
                            && (Number(annotation.pageIndex) || 0) === blockPageIndex
                        ));
                        const matchesPromotedAnnotation = ({
                            textValue,
                            leftValue,
                            topValue,
                            widthValue,
                            heightValue,
                            fontSizeValue,
                            expectedSourceKey,
                        }) => {
                            const comparableText = normalizeSavedOverlayText(textValue);
                            if (!comparableText) {
                                return false;
                            }

                            const samePagePromotedTextMatches = promotedAnnotationsOnPage.filter((annotation) => (
                                normalizeSavedOverlayText(annotation.text) === comparableText
                            ));

                            return promotedAnnotationsOnPage.some((annotation) => {
                                const annotationSourceKey = String(annotation.promotedSourceKey || '').trim();
                                if (expectedSourceKey && annotationSourceKey && annotationSourceKey === expectedSourceKey) {
                                    return true;
                                }

                                const annotationText = normalizeSavedOverlayText(annotation.text);
                                if (annotationText !== comparableText) {
                                    return false;
                                }
                                if (samePagePromotedTextMatches.length === 1) {
                                    return true;
                                }

                                const blockLeftNumber = Number(leftValue) || 0;
                                const blockTopNumber = Number(topValue) || 0;
                                const blockWidthNumber = Number(widthValue) || 0;
                                const blockHeightNumber = Number(heightValue) || 0;
                                const annotationX = Number(annotation.pdfX) || 0;
                                const annotationY = Number(annotation.pdfY) || 0;
                                const annotationHeight = Number(annotation.pdfHeight) || 0;
                                const annotationTopPdf = pageHeightPdf > 0
                                    ? (pageHeightPdf - annotationY - annotationHeight)
                                    : null;

                                if (
                                    annotationTopPdf !== null
                                    && Math.abs(annotationTopPdf - blockTopNumber) <= Math.max(8, blockHeightNumber * 0.6)
                                ) {
                                    return true;
                                }

                                if (Math.abs(annotationX - blockLeftNumber) > Math.max(3, blockWidthNumber * 0.08)) {
                                    return false;
                                }

                                const blockFontSizeNumber = Number(fontSizeValue) || 0;
                                const annotationFontSize = Number(annotation.fontSize) || 0;
                                if (
                                    annotationFontSize > 0
                                    && blockFontSizeNumber > 0
                                    && Math.abs(annotationFontSize - blockFontSizeNumber) > Math.max(0.75, blockFontSizeNumber * 0.08)
                                ) {
                                    return false;
                                }

                                let annotationWidthPdf = Number(annotation.pdfWidth) || 0;
                                if (!(annotationWidthPdf > 0)) {
                                    const annotationFontFamily = fontMap[annotation.fontFamily]?.css
                                        || annotation.fontFamily
                                        || 'Arial, sans-serif';
                                    const annotationWidthPx = measureTextWidth(
                                        annotation.text || '',
                                        Math.max(1, annotationFontSize * scaleY),
                                        annotationFontFamily,
                                        annotation.fontWeight,
                                        annotation.fontStyle
                                    );
                                    annotationWidthPdf = annotationWidthPx / Math.max(scaleX, 0.0001);
                                }

                                if (annotationWidthPdf > 0 && blockWidthNumber > 0) {
                                    const widthDelta = Math.abs(annotationWidthPdf - blockWidthNumber);
                                    if (widthDelta > Math.max(12, blockWidthNumber * 0.2)) {
                                        return false;
                                    }
                                }

                                return true;
                            });
                        };

                        const mergedSourceSegments = Array.isArray(block?._overlay_source_segments)
                            ? block._overlay_source_segments.filter((segment) => segment && Array.isArray(segment.bbox) && segment.bbox.length >= 4)
                            : [];
                        if (mergedSourceSegments.length > 1) {
                            const allSegmentsCovered = mergedSourceSegments.every((segment) => {
                                const segmentText = String(segment.text || (
                                    Array.isArray(segment.text_lines) ? segment.text_lines.join('\n') : ''
                                ));
                                const segmentBbox = segment.bbox;
                                return matchesPromotedAnnotation({
                                    textValue: segmentText,
                                    leftValue: segmentBbox[0],
                                    topValue: segmentBbox[1],
                                    widthValue: (Number(segmentBbox[2]) || 0) - (Number(segmentBbox[0]) || 0),
                                    heightValue: (Number(segmentBbox[3]) || 0) - (Number(segmentBbox[1]) || 0),
                                    fontSizeValue: segment.font_size ?? blockFontSizeValue,
                                    expectedSourceKey: segment.block_num !== undefined && segment.block_num !== null
                                        ? `block-${pageData.page_number}-${segment.block_num}`
                                        : '',
                                });
                            });
                            if (allSegmentsCovered) {
                                return true;
                            }
                        }

                        return matchesPromotedAnnotation({
                            textValue: blockTextValue,
                            leftValue: blockLeftValue,
                            topValue: blockTopValue,
                            widthValue: blockWidthValue,
                            heightValue: blockHeightValue,
                            fontSizeValue: blockFontSizeValue,
                            expectedSourceKey: `block-${pageData.page_number}-${block.block_num}`,
                        });
                    };

                    const hasEquivalentSavedStandaloneTextAnnotation = (blockTextValue, blockLeftValue, blockWidthValue, blockFontSizeValue) => {
                        const comparableText = normalizeSavedOverlayText(blockTextValue);
                        if (!comparableText) {
                            return false;
                        }

                        return annotations.some((annotation) => {
                            if (!annotation || annotation.type !== 'text' || annotation.promotedFromExtraction || !annotation.savedTextOverlay) {
                                return false;
                            }
                            if ((Number(annotation.pageIndex) || 0) !== ((Number(pageData.page_number) || 1) - 1)) {
                                return false;
                            }

                            const annotationText = normalizeSavedOverlayText(annotation.text);
                            if (annotationText !== comparableText) {
                                return false;
                            }

                            const blockLeftNumber = Number(blockLeftValue) || 0;
                            const blockWidthNumber = Number(blockWidthValue) || 0;
                            const annotationX = Number(annotation.pdfX) || 0;
                            if (Math.abs(annotationX - blockLeftNumber) > Math.max(3, blockWidthNumber * 0.08)) {
                                return false;
                            }

                            const blockFontSizeNumber = Number(blockFontSizeValue) || 0;
                            const annotationFontSize = Number(annotation.fontSize) || 0;
                            if (
                                annotationFontSize > 0
                                && blockFontSizeNumber > 0
                                && Math.abs(annotationFontSize - blockFontSizeNumber) > Math.max(0.75, blockFontSizeNumber * 0.08)
                            ) {
                                return false;
                            }

                            let annotationWidthPdf = Number(annotation.pdfWidth) || 0;
                            if (!(annotationWidthPdf > 0)) {
                                const annotationFontFamily = fontMap[annotation.fontFamily]?.css
                                    || annotation.fontFamily
                                    || 'Arial, sans-serif';
                                const annotationWidthPx = measureTextWidth(
                                    annotation.text || '',
                                    Math.max(1, annotationFontSize * scaleY),
                                    annotationFontFamily,
                                    annotation.fontWeight,
                                    annotation.fontStyle
                                );
                                annotationWidthPdf = annotationWidthPx / Math.max(scaleX, 0.0001);
                            }

                            if (annotationWidthPdf > 0 && blockWidthNumber > 0) {
                                const widthDelta = Math.abs(annotationWidthPdf - blockWidthNumber);
                                if (widthDelta > Math.max(12, blockWidthNumber * 0.2)) {
                                    return false;
                                }
                            }

                            return true;
                        });
                    };

                    // Pre-process blocks to detect duplicated text layers that should
                    // share the same Y anchor. Keep this conservative: never collapse
                    // distinct wrapped lines into one row.
                    const Y_ALIGNMENT_THRESHOLD = 15; // max Y difference in PDF units for alignment
                    const blockYAdjustments = new Map(); // block_num -> adjusted Y position

                    mergedAdjacentBlocks.forEach((blockA, idxA) => {
                        if (blockYAdjustments.has(blockA.block_num)) return;
                        
                        const aLeft = blockA.left || 0;
                        const aRight = aLeft + (blockA.width || 0);
                        const aTop = blockA.top || 0;
                        
                        // Look for other blocks that horizontally overlap with this one
                        mergedAdjacentBlocks.forEach((blockB, idxB) => {
                            if (idxA === idxB) return;
                            if (blockYAdjustments.has(blockB.block_num)) return;
                            
                            const bLeft = blockB.left || 0;
                            const bRight = bLeft + (blockB.width || 0);
                            const bTop = blockB.top || 0;
                            const aBottom = aTop + (blockA.height || 0);
                            const bBottom = bTop + (blockB.height || 0);
                            
                            // Check Y proximity
                            const yDiff = Math.abs(aTop - bTop);
                            if (yDiff > Y_ALIGNMENT_THRESHOLD) return;

                            // CRITICAL: require real vertical overlap. Nearby wrapped lines
                            // can have small yDiff but should remain separate rows.
                            const verticalIntersection = Math.max(0, Math.min(aBottom, bBottom) - Math.max(aTop, bTop));
                            const minHeight = Math.max(1, Math.min((blockA.height || 0), (blockB.height || 0)));
                            const verticalOverlapRatio = verticalIntersection / minHeight;
                            if (verticalOverlapRatio < 0.35) return;
                            
                            // Check horizontal overlap: does one contain the other?
                            const aContainsB = (bLeft >= aLeft && bRight <= aRight);
                            const bContainsA = (aLeft >= bLeft && aRight <= bRight);
                            const hasHorizontalOverlap = aContainsB || bContainsA;
                            
                            if (!hasHorizontalOverlap) return;
                            
                            // Align both blocks to the minimum Y (topmost position)
                            const alignedY = Math.min(aTop, bTop);
                            blockYAdjustments.set(blockA.block_num, alignedY);
                            blockYAdjustments.set(blockB.block_num, alignedY);
                        });
                    });

                    mergedAdjacentBlocks.forEach((block, blockIndex) => {
                        const key = `block-${pageData.page_number}-${block.block_num}`;
                        if (renderedBlockKeys.has(key)) return;
                        renderedBlockKeys.add(key);
                        const storedEdit = getOverlayStoredEdit(key);

                        const trimmedBlockDisplay = getTrimmedBlockDisplayData(block);
                        const blockText = trimmedBlockDisplay.textLines.length
                            ? trimmedBlockDisplay.textLines.join('\n')
                            : ((block.text_lines && block.text_lines.length)
                                ? block.text_lines.map(line => sanitizeOverlayText(line)).join('\n')
                                : sanitizeOverlayText(block.text || ''));
                        // Ensure blockText is always a string, never undefined
                        const safeBlockText = sanitizeOverlayText(String(blockText || ''));
                        if (storedEdit && storedEdit.new_text === '') {
                            return;
                        }

                        let blockLeft = block.left;
                        let blockTop = block.top;
                        let blockWidth = block.width;
                        let blockHeight = block.height;
                        if (!literalBoundingBoxBlocks && !storedEdit && trimmedBlockDisplay.bounds) {
                            blockLeft = trimmedBlockDisplay.bounds.left;
                            blockTop = trimmedBlockDisplay.bounds.top;
                            blockWidth = trimmedBlockDisplay.bounds.width;
                            blockHeight = trimmedBlockDisplay.bounds.height;
                        }

                        // Apply Y-axis alignment adjustment if this block overlaps horizontally with another
                        const sourceGeometryLockedBlock = Array.isArray(block?.line_bboxes)
                            && block.line_bboxes.length > 1
                            && Array.isArray(block?.spans)
                            && block.spans.length > 0;
                        if (!literalBoundingBoxBlocks && !sourceGeometryLockedBlock && blockYAdjustments.has(block.block_num)) {
                            const originalTop = blockTop;
                            blockTop = blockYAdjustments.get(block.block_num);
                            // Keep the height adjustment so bottom edge doesn't shift
                            const topDiff = originalTop - blockTop;
                            blockHeight = blockHeight + topDiff;
                        }

                        const field = document.createElement('div');
                        field.className = 'overlay-field';
                        field.dataset.layoutMode = layoutMode;
                        field.style.position = 'absolute';
                        field.style.background = 'transparent';
                        field.style.pointerEvents = 'auto';
                        field.style.padding = '0';
                        field.style.minWidth = '20px';
                        field.style.minHeight = '10px';
                        field.style.boxSizing = 'border-box';
                        field.style.setProperty('--overlay-field-mask-color', '#ffffff');

                        // Render the text content
                        const textSpan = document.createElement('div');
                        textSpan.contentEditable = false;
                        const hasStoredEdit = storedEdit && storedEdit.new_text != null;
                        const stripWs = (v) => sanitizeOverlayText(String(v || '')).replace(/\s+/g, '');
                        const hasMeaningfulTextEdit = hasStoredEdit
                            ? (stripWs(storedEdit.new_text) !== stripWs(safeBlockText))
                            : false;
                        textSpan.textContent = '';
                        textSpan.style.display = 'block';
                        textSpan.style.whiteSpace = 'pre';
                        textSpan.style.wordBreak = 'normal';
                        textSpan.style.width = '100%';
                        textSpan.style.minHeight = '100%';
                        textSpan.style.outline = 'none';
                        textSpan.style.cursor = 'text';
                        textSpan.style.userSelect = 'text';
                        textSpan.style.webkitUserSelect = 'text';
                        textSpan.style.padding = '0';
                        textSpan.style.margin = '0';
                        textSpan.style.overflow = 'hidden';
                        textSpan.style.boxSizing = 'border-box';
                        
                        // Apply font styling from block data directly to the field for inheritance
                        const resolvedBlockFont = storedEdit?.font || block.font;
                        const fontFamily = getCssFontFamily(
                            resolvedBlockFont,
                            storedEdit?.embedded_font_name || block.embedded_font_name || resolvedBlockFont
                        );
                        
                        // Use explicit font_weight from extraction if available, otherwise infer
                        let fontWeight;
                        if (storedEdit?.font_weight) {
                            fontWeight = String(storedEdit.font_weight);
                        } else if (block.font_weight) {
                            fontWeight = String(block.font_weight);
                        } else {
                            const inferredWeight = inferFontWeightFromName(resolvedBlockFont);
                            if (inferredWeight) {
                                fontWeight = inferredWeight;
                            } else if (block.bold) {
                                fontWeight = '700';
                            } else {
                                fontWeight = '400';
                            }
                        }
                        
                        const fontStyle = storedEdit?.font_style || (block.italic ? 'italic' : 'normal');
                        const resolvedFontSizePdf = Number(storedEdit?.font_size) > 0 ? Number(storedEdit.font_size) : Number(block.font_size) || 12;
                        const fontSize = (resolvedFontSizePdf * scaleY) + 'px';
                        const lineHeightValue = block.avg_line_height || block.line_height;
                        const lineHeightPx = lineHeightValue ? (lineHeightValue * scaleY) + 'px' : '';
                        
                        // Debug logging for first block
                        if (blockIndex === 0) {
                            console.log('Block font info:', {
                                original_font: block.font,
                                css_family: fontFamily,
                                weight: fontWeight,
                                style: fontStyle,
                                size_pdf: block.font_size,
                                size_scaled: fontSize,
                                scaleY: scaleY,
                                bold: block.bold,
                                italic: block.italic
                            });
                        }
                        
                        // Apply to both field and textSpan for proper inheritance
                        field.style.fontFamily = fontFamily;
                        field.style.fontWeight = fontWeight;
                        field.style.fontStyle = fontStyle;
                        field.style.fontSize = fontSize;
                        
                        textSpan.style.fontFamily = fontFamily;
                        textSpan.style.fontWeight = fontWeight;
                        textSpan.style.fontStyle = fontStyle;
                        textSpan.style.fontSize = fontSize;
                        
                        // Apply text color
                        let textColor = storedEdit?.color || '#000000';
                        if (!storedEdit?.color && block.hex_color) {
                            textColor = block.hex_color;
                        } else if (!storedEdit?.color && block.color !== undefined && block.color !== null) {
                            textColor = typeof block.color === 'number'
                                ? '#' + block.color.toString(16).padStart(6, '0')
                                : block.color;
                        }
                        const storedBackgroundColor = colorToHex(storedEdit?.background_color || 'transparent');
                        field.style.color = textColor;
                        textSpan.style.color = textColor;
                        field.dataset.textColor = textColor;
                        field.dataset.originalTextColor = textColor;
                        field.dataset.fontWeight = fontWeight;
                        field.dataset.fontStyle = fontStyle;
                        field.dataset.originalFontWeight = fontWeight;
                        field.dataset.originalFontStyle = fontStyle;
                        field.dataset.underline = storedEdit?.underline ? 'true' : 'false';
                        field.dataset.hasPersistedEdit = hasStoredEdit ? '1' : '0';
                        if (storedBackgroundColor !== 'transparent') {
                            textSpan.style.backgroundColor = storedBackgroundColor;
                            field.dataset.backgroundColor = storedBackgroundColor;
                        } else {
                            delete field.dataset.backgroundColor;
                            textSpan.style.backgroundColor = 'transparent';
                        }
                        syncBoundingBoxFieldMaskState(field);

                        const rawBlockWords = pageData.words
                            ? pageData.words.filter((word) => word.block_num === block.block_num)
                            : [];
                        const blockWords = collapseOverlayDuplicateWords(filterOverlayArtifactWords(rawBlockWords)).filter((word) => {
                            const display = getOverlayWordDisplayText(word);
                            return !isIgnorableOverlayToken(display);
                        });
                        const preferredFlowText = trimmedBlockDisplay.trimmed
                            ? safeBlockText
                            : getPreferredFlowTextForBlock(block, blockWords, safeBlockText);
                        const forceFlowRender = trimmedBlockDisplay.trimmed
                            ? true
                            : shouldUseFlowRenderForBlock(block, blockWords, safeBlockText);
                        const exactGeometryEligible = !storedEdit
                            && !hasMeaningfulTextEdit
                            && Array.isArray(block?.line_bboxes)
                            && block.line_bboxes.length > 0
                            && Array.isArray(block?.spans)
                            && block.spans.length > 0;
                        if (exactGeometryEligible) {
                            blockLeft = Number(block?._overlayOriginalLeft);
                            blockTop = Number(block?._overlayOriginalTop);
                            blockWidth = Number(block?._overlayOriginalWidth);
                            blockHeight = Number(block?._overlayOriginalHeight);
                            if (!Number.isFinite(blockLeft)) blockLeft = Number(block?.left) || 0;
                            if (!Number.isFinite(blockTop)) blockTop = Number(block?.top) || 0;
                            if (!Number.isFinite(blockWidth) || blockWidth <= 0) blockWidth = Number(block?.width) || 1;
                            if (!Number.isFinite(blockHeight) || blockHeight <= 0) blockHeight = Number(block?.height) || 1;
                        }
                        const wordDerivedFlowText = normalizeStableFlowText(buildStableFlowTextFromWords(block, blockWords) || '', {
                            collapseRepeatedNonEmptyLines: true,
                        });
                        const flowNeedsBlockBounds = trimmedBlockDisplay.trimmed || (forceFlowRender
                            && preferredFlowText.length > 0
                            && preferredFlowText.length > (wordDerivedFlowText.length + 3));

                        if (!literalBoundingBoxBlocks && !storedEdit && isLikelyOrphanTinyBlock(block, safeBlockText, mergedAdjacentBlocks)) {
                            return;
                        }
                        if (!literalBoundingBoxBlocks && !storedEdit && isValueShadowOfCompositeField(block, safeBlockText, mergedAdjacentBlocks)) {
                            return;
                        }

                        if (!literalBoundingBoxBlocks && !storedEdit && blockWords.length === 0 && !hasMeaningfulOverlayText(safeBlockText)) {
                            return;
                        }

                        if (!literalBoundingBoxBlocks && !storedEdit && blockWords.length > 0 && !flowNeedsBlockBounds && !exactGeometryEligible) {
                            const bounds = getWordBounds(blockWords);
                            if (bounds) {
                                blockLeft = bounds.left;
                                blockTop = bounds.top;
                                blockWidth = bounds.width;
                                blockHeight = Math.max(blockHeight, bounds.height);
                            }
                        }

                        if (!literalBoundingBoxBlocks && !storedEdit && hasEquivalentSavedStandaloneTextAnnotation(safeBlockText, blockLeft, blockWidth, block.font_size)) {
                            return;
                        }
                        if (!literalBoundingBoxBlocks && !storedEdit && hasEquivalentPromotedAnnotation(block, safeBlockText, blockLeft, blockTop, blockWidth, blockHeight, block.font_size)) {
                            return;
                        }

                        // Skip synthetic/duplicate blocks that don't map to any words and
                        // also don't have a user edit record. These are a common source of
                        // stray duplicated glyph fragments in overlay mode.
                        if (!literalBoundingBoxBlocks && !storedEdit && blockWords.length === 0 && !exactGeometryEligible && !hasMeaningfulOverlayText(safeBlockText)) {
                            return;
                        }

                        // Final safety net: skip near-identical field renderings that
                        // can appear with duplicated extraction fragments.
                        const candidateTextSig = sanitizeOverlayText(
                            String((storedEdit && storedEdit.new_text != null ? storedEdit.new_text : safeBlockText) || '')
                        ).replace(/\s+/g, ' ').trim();
                        const candidateWordSig = blockWords
                            .slice()
                            .sort((a, b) => ((a.top || 0) - (b.top || 0)) || ((a.left || 0) - (b.left || 0)))
