                            if (field.dataset.splitParagraphFullyActive !== '1') {
                                return;
                            }
                            const inputType = String(e.inputType || '');
                            if (
                                inputType.startsWith('insert')
                                || inputType.startsWith('delete')
                                || inputType === 'historyUndo'
                                || inputType === 'historyRedo'
                            ) {
                                pushUndoState();
                                convertSplitParagraphLayoutToFlowText(field, textSpan);
                            }
                        });
                        textSpan.addEventListener('keydown', function(e) {
                            if (field.classList.contains('editing') && field.dataset.splitParagraphFullyActive === '1') {
                                if (
                                    e.key === 'Enter'
                                    || (
                                        !e.metaKey
                                        && !e.ctrlKey
                                        && !e.altKey
                                        && (e.key.length === 1 || e.key === 'Backspace' || e.key === 'Delete')
                                    )
                                ) {
                                    convertSplitParagraphLayoutToFlowText(field, textSpan);
                                }
                            }
                            if (field.classList.contains('editing')) {
                                // Keyboard edits should operate on flowing text, not
                                // absolutely-positioned span fragments.
                                normalizePositionedSpansForEditing(field, textSpan);
                            }
                            if (e.key === 'Enter' && field.classList.contains('editing')) {
                                e.preventDefault();
                                const selection = window.getSelection();
                                if (selection && selection.rangeCount > 0) {
                                    const range = selection.getRangeAt(0);
                                    range.deleteContents();
                                    const newlineNode = document.createTextNode('\n');
                                    range.insertNode(newlineNode);
                                    range.setStartAfter(newlineNode);
                                    range.collapse(true);
                                    selection.removeAllRanges();
                                    selection.addRange(range);
                                    textSpan.dispatchEvent(new Event('input', { bubbles: true }));
                                }
                            }
                            // Escape exits edit mode back to selected mode
                            if (e.key === 'Escape' && field.classList.contains('editing')) {
                                e.preventDefault();
                                field.classList.remove('editing', 'editable');
                                textSpan.classList.remove('editable');
                                textSpan.contentEditable = false;
                                textSpan.blur();
                                window.getSelection()?.removeAllRanges();
                            }
                        });
                        textSpan.addEventListener('keyup', function() {
                            if (field.classList.contains('editing')) {
                                setOverlaySelection(field);
                            }
                        });

                        const enterOverlayFieldEditing = () => {
                            if (!overlayEditorActive) return;
                            if (!boundingBoxEditMode && !ensureEditTextModeEnabled()) return;
                            if (getSelectedOverlayFields().length > 1) {
                                setOverlaySelection(field);
                            }
                            field.classList.add('active', 'editing', 'editable');
                            textSpan.classList.add('editable');
                            syncBoundingBoxFieldMaskState(field);

                            const preserveUnderscores = field.dataset.preserveUnderscores === '1';
                            field.dataset.flowNormalized = '0';
                            if (!preserveUnderscores) {
                                field.dataset.forceFlowText = '1';
                            }
                            normalizePositionedSpansForEditing(field, textSpan);
                            if (!preserveUnderscores) {
                                delete field.dataset.forceFlowText;
                            }

                            if (preserveUnderscores) {
                                textSpan.contentEditable = true;
                                textSpan.focus();
                                selectAllEditableContents(textSpan);
                                setOverlaySelection(field);
                                return;
                            }

                            textSpan.contentEditable = true;
                            textSpan.focus();
                            selectAllEditableContents(textSpan);
                            setOverlaySelection(field);
                        };

                        // ── ilovepdf-style interaction ──
                        // Single click = SELECT (show handles, enable drag, no text editing)
                        field.addEventListener('mousedown', function(e) {
                            if (e.target.closest('.box-menu') || e.target.classList.contains('resize-handle')) return;
                            if (field.classList.contains('editing') && textSpan.contains(e.target)) {
                                return;
                            }
                            field.dataset.overlayWasSelectedBeforeMouseDown = selectedOverlayFields.has(field) ? '1' : '0';
                            setOverlaySelection(field, { additive: e.shiftKey });
                            e.stopPropagation();
                        });

                        field.addEventListener('click', function(e) {
                            if (!boundingBoxEditMode) return;
                            if (!overlayEditorActive) return;
                            if (e.target.closest('.box-menu') || e.target.classList.contains('resize-handle')) return;
                            if (field.classList.contains('editing')) return;
                            setOverlaySelection(field);
                            enterOverlayFieldEditing();
                            e.stopPropagation();
                        });

                        // Double click = EDIT (enable text cursor)
                        field.addEventListener('dblclick', function(e) {
                            if (boundingBoxEditMode) return;
                            if (!overlayEditorActive) return;
                            if (!ensureEditTextModeEnabled()) return;
                            if (e.target.closest('.box-menu') || e.target.classList.contains('resize-handle')) return;
                            enterOverlayFieldEditing();
                        });

                        textSpan.addEventListener('dblclick', function(e) {
                            if (!field.classList.contains('editing')) {
                                return;
                            }
                            e.preventDefault();
                            e.stopPropagation();
                            selectAllEditableContents(textSpan);
                            setOverlaySelection(field);
                        });

                        textSpan.addEventListener('blur', function(e) {
                            // Delay to allow button clicks to register
                            setTimeout(async () => {
                                if (!field.contains(document.activeElement) && !field.matches(':hover')) {
                                    field.classList.remove('editing', 'editable');
                                    textSpan.classList.remove('editable');
                                    textSpan.contentEditable = false;
                                    syncBoundingBoxFieldMaskState(field);
                                    if (boundingBoxEditMode) {
                                        await persistBoundingBoxFieldIfNeeded(field);
                                    }
                                    const fieldKey = String(field.dataset.wordIndex || '');
                                    const preserveBoundingBoxEditContent = boundingBoxEditMode
                                        && field.dataset.layoutMode === 'bounding_box_edit'
                                        && field.dataset.hasPersistedEdit === '1';
                                    if (selectedOverlayField === field && field.dataset.exactGeometry === '1' && !overlayEditedFields.has(fieldKey) && !preserveBoundingBoxEditContent) {
                                        restoreOverlayFieldSourceGeometry(field, textSpan);
                                    }
                                    if (selectedOverlayField !== field) {
                                        deactivateOverlayField(field, { keepSelected: selectedOverlayFields.has(field) });
                                    }
                                }
                            }, 250);
                        });
                        
                        // Add drag-to-move functionality
                        (function() {
                            let isDragging = false;
                            let dragPending = false;
                            let dragMoved = false;
                            let dragStart = { x: 0, y: 0 };

                            // Create box menu toolbar at top-right
                            const boxMenu = document.createElement('div');
                            boxMenu.className = 'box-menu';
                            
                            const dragBtn = document.createElement('button');
                            dragBtn.className = 'menu-drag';
                            dragBtn.innerHTML = '✥ Move';
                            dragBtn.title = 'Drag to move this block';
                            
                            const divider1 = document.createElement('div');
                            divider1.className = 'menu-divider';
                            
                            const splitBtn = document.createElement('button');
                            splitBtn.className = 'menu-split';
                            splitBtn.innerHTML = '✂ Split';
                            splitBtn.title = 'Split this block into two halves';
                            
                            const divider2 = document.createElement('div');
                            divider2.className = 'menu-divider';
                            
                            const deleteBtn = document.createElement('button');
                            deleteBtn.className = 'menu-delete';
                            deleteBtn.innerHTML = '🗑 Delete';
                            deleteBtn.title = 'Delete this text block';
                            
                            boxMenu.appendChild(dragBtn);
                            boxMenu.appendChild(divider1);
                            boxMenu.appendChild(splitBtn);
                            boxMenu.appendChild(divider2);
                            boxMenu.appendChild(deleteBtn);
                            field.appendChild(boxMenu);
                            
                            // ── Split handler ─────────────────────────────────
                            splitBtn.addEventListener('click', function(e) {
                                e.preventDefault();
                                e.stopPropagation();
                                pushUndoState();

                                // Get current field bbox in PDF coords
                                const pad = parseFloat(field.dataset.padding) || 0;
                                const fLeft  = (parseFloat(field.style.left) / scaleX) + pad;
                                const fTop   = (parseFloat(field.style.top) / scaleY) + pad;
                                const fWidth = (parseFloat(field.style.width) / scaleX) - (pad * 2);
                                const fHeight = (parseFloat(field.style.height) / scaleY) - (pad * 2);
                                const midX   = fLeft + fWidth / 2;

                                // Partition words into left/right by each word's center-x
                                const bWords = pageData.words
                                    ? pageData.words.filter(w => w.block_num === block.block_num)
                                    : [];
                                let leftWords = [];
                                let rightWords = [];
                                if (bWords.length > 0) {
                                    bWords.forEach(w => {
                                        const wCenterX = w.left + w.width / 2;
                                        if (wCenterX < midX) leftWords.push(w);
                                        else rightWords.push(w);
                                    });
                                } else {
                                    // No word data — split text string in half
                                    const mid = Math.ceil(blockText.length / 2);
                                    leftWords = [{ text: blockText.substring(0, mid), left: fLeft, top: fTop, width: fWidth / 2, height: fHeight }];
                                    rightWords = [{ text: blockText.substring(mid), left: midX, top: fTop, width: fWidth / 2, height: fHeight }];
                                }

                                // Compute tight bboxes from actual word positions
                                const wordBbox = (words) => {
                                    if (!words.length) return null;
                                    let l = Infinity, t = Infinity, r = -Infinity, b = -Infinity;
                                    words.forEach(w => {
                                        l = Math.min(l, w.left);
                                        t = Math.min(t, w.top);
                                        r = Math.max(r, w.left + w.width);
                                        b = Math.max(b, w.top + w.height);
                                    });
                                    return [l, t, r, b];
                                };

                                const leftBbox  = wordBbox(leftWords) || [fLeft, fTop, midX, fTop + fHeight];
                                const rightBbox = wordBbox(rightWords) || [midX, fTop, fLeft + fWidth, fTop + fHeight];

                                const leftText  = leftWords.map(w => sanitizeOverlayText(w.text)).join(' ');
                                const rightText = rightWords.map(w => sanitizeOverlayText(w.text)).join(' ');

                                // Keys for the two halves
                                const maxBlk = pageData.blocks.reduce((m, b) => Math.max(m, b.block_num), 0);
                                const leftBlockNum  = maxBlk + 1;
                                const rightBlockNum = maxBlk + 2;
                                const leftKey  = `block-${pageData.page_number}-${leftBlockNum}`;
                                const rightKey = `block-${pageData.page_number}-${rightBlockNum}`;

                                // Build edit entries
                                const makeEdit = (text, bbox, bNum) => ({
                                    page_number: pageData.page_number,
                                    block_num: bNum,
                                    original_text: safeBlockText,
                                    new_text: text,
                                    rich_html: null,
                                    bbox: bbox,
                                    original_bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                    origin_x: bbox[0],
                                    origin_y: bbox[3],
                                    font: block.font,
                                    font_size: block.font_size,
                                    font_weight: fontWeight,
                                    font_style: fontStyle,
                                    font_xref: block.font_xref,
                                    line_height: lineHeightValue || null,
                                    color: field.dataset.textColor || '#000000'
                                });

                                // Delete original block
                                overlayEditedFields.set(key, {
                                    page_number: pageData.page_number,
                                    block_num: block.block_num,
                                    original_text: safeBlockText,
                                    new_text: '',
                                    rich_html: null,
                                    bbox: [fLeft, fTop, fLeft + fWidth, fTop + fHeight],
                                    original_bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                    font_xref: block.font_xref,
                                    font: block.font,
                                    font_size: block.font_size,
                                    font_weight: fontWeight,
                                    font_style: fontStyle,
                                    line_height: lineHeightValue || null,
                                    color: field.dataset.textColor || '#000000'
                                });

                                // Add two new edit entries
                                overlayEditedFields.set(leftKey, makeEdit(leftText, leftBbox, leftBlockNum));
                                overlayEditedFields.set(rightKey, makeEdit(rightText, rightBbox, rightBlockNum));

                                // Inject synthetic blocks into extraction data so re-render sees them
                                const synBase = { ...block, text: '', text_lines: [] };
                                pageData.blocks.push({
                                    ...synBase,
                                    block_num: leftBlockNum,
                                    left: leftBbox[0], top: leftBbox[1],
                                    width: leftBbox[2] - leftBbox[0],
                                    height: leftBbox[3] - leftBbox[1],
                                    text: leftText,
                                    text_lines: [leftText],
                                });
                                pageData.blocks.push({
                                    ...synBase,
                                    block_num: rightBlockNum,
                                    left: rightBbox[0], top: rightBbox[1],
                                    width: rightBbox[2] - rightBbox[0],
                                    height: rightBbox[3] - rightBbox[1],
                                    text: rightText,
                                    text_lines: [rightText],
                                });

                                // Remove original field and re-render
                                selectedOverlayField = null;
                                if (field.parentNode) field.parentNode.removeChild(field);

                                persistOverlayEdits();
                                updateOverlaySaveButton();
                                renderPdfWithOverlay(true);
                                setStatus('Block split into two halves', 'ok');
                            });
                            
                            deleteBtn.addEventListener('click', function(e) {
                                e.preventDefault();
                                e.stopPropagation();
                                
                                try {
                                    // Save state before deletion
                                    pushUndoState();
                                    
                                    // Mark as edited by storing empty text
                                    const deleteKey = field.dataset.wordIndex || key;
                                    if (deleteKey) {
                                        const currentFontSizePdf = parseFloat(field.dataset.fontSize || block.font_size || 12);
                                        overlayEditedFields.set(deleteKey, {
                                            page_number: pageData.page_number,
                                            block_num: block.block_num,
                                            original_text: safeBlockText,
                                            new_text: '',
                                            rich_html: null,
                                            original_bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                            bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                            font_xref: field.dataset.fontXref ? parseInt(field.dataset.fontXref, 10) : null,
                                            font: block.font,
                                            font_size: currentFontSizePdf,
                                            font_weight: fontWeight,
                                            font_style: fontStyle,
                                            line_height: lineHeightValue || null,
                                            color: field.dataset.textColor || '#000000'
                                        });
                                    }
                                    
                                    // Remove field from DOM
                                    field.classList.remove('active');
                                    if (field.parentNode) {
                                        field.parentNode.removeChild(field);
                                    }
                                    
                                    // Clear selection and update UI
                                    clearOverlaySelection();
                                    updateSelectionBar();
                                    updateOverlaySaveButton();
                                    persistOverlayEdits();
                                    setStatus('Text block deleted', 'ok');
                                } catch (err) {
                                    console.error('Delete handler error:', err);
                                    // Still try to remove the field even if something failed
                                    if (field.parentNode) field.parentNode.removeChild(field);
                                    clearOverlaySelection();
                                    updateSelectionBar();
                                    setStatus('Delete failed: ' + err.message, 'err');
                                }
                            });
                            
                            const activateDragUi = () => {
                                if (isDragging) {
                                    return;
                                }
                                pushUndoState();
                                overlayInteractionActive = true;
                                isDragging = true;
                                dragBtn.style.cursor = 'grabbing';
                                boxMenu.style.display = 'none';
                            };

                            const resetDragState = () => {
                                isDragging = false;
                                dragPending = false;
                                dragMoved = false;
                                dragBtn.style.cursor = 'grab';
                                boxMenu.style.display = '';
                                overlayInteractionActive = false;
                            };

                            const startDrag = (e, options = {}) => {
                                dragPending = true;
                                dragMoved = false;
                                dragStart = { x: e.clientX, y: e.clientY };
                                if (options.immediate === true) {
                                    activateDragUi();
                                }
                                if (options.preventDefault !== false) {
                                    e.preventDefault();
                                }
                                if (options.stopPropagation !== false) {
                                    e.stopPropagation();
                                }
                            };
                            
                            dragBtn.addEventListener('mousedown', (e) => {
                                if (!ensureEditTextModeEnabled('Turn on Edit Text to move existing text boxes.')) {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    return;
                                }
                                startDrag(e, { immediate: true });
                            });
                            
                            // Allow dragging the whole box when in selected (not editing) mode.
                            field.addEventListener('mousedown', (e) => {
                                if (e.target.closest('.box-menu') || e.target.classList.contains('resize-handle')) {
                                    return;
                                }
                                const wasSelectedBeforeMouseDown = field.dataset.overlayWasSelectedBeforeMouseDown === '1';
                                // Only drag if selected but not in text-editing mode.
                                // Skip on multi-clicks (e.detail >= 2) so double-click word
                                // selection works — otherwise startDrag's preventDefault()
                                // kills the browser's native selection.
                                if (wasSelectedBeforeMouseDown && field.classList.contains('active') && !field.classList.contains('editing') && e.detail < 2) {
                                    if (toolMode !== 'edit-text') {
                                        return;
                                    }
                                    startDrag(e, { preventDefault: false, stopPropagation: false });
                                }
                            });
                            
                            const moveHandler = function(e) {
                                if (!dragPending && !isDragging) return;
                                
                                const dx = e.clientX - dragStart.x;
                                const dy = e.clientY - dragStart.y;
                                if (!isDragging) {
                                    if (Math.abs(dx) < 2 && Math.abs(dy) < 2) {
                                        return;
                                    }
                                    activateDragUi();
                                }
                                if (dx === 0 && dy === 0) {
                                    return;
                                }
                                dragMoved = true;
                                
                                const currentLeft = parseFloat(field.style.left);
                                const currentTop = parseFloat(field.style.top);
                                const fieldWidth = parseFloat(field.style.width) || field.offsetWidth;
                                const fieldHeight = parseFloat(field.style.height) || field.offsetHeight;
                                const maxW = parseFloat(field.dataset.canvasWidth || '0') || (field.parentElement ? field.parentElement.clientWidth : Infinity);
                                const maxH = parseFloat(field.dataset.canvasHeight || '0') || (field.parentElement ? field.parentElement.clientHeight : Infinity);
                                
                                let newLeft = currentLeft + dx;
                                let newTop = currentTop + dy;
                                // Clamp to page boundaries
                                newLeft = Math.max(0, Math.min(newLeft, maxW - fieldWidth));
                                newTop = Math.max(0, Math.min(newTop, maxH - fieldHeight));
                                
                                field.style.left = newLeft + 'px';
                                field.style.top = newTop + 'px';
                                
                                dragStart = { x: e.clientX, y: e.clientY };
                            };
                            
                            const upHandler = function() {
                                field.dataset.overlayWasSelectedBeforeMouseDown = '0';
                                const commitDrag = isDragging && dragMoved;
                                if (dragPending || isDragging) {
                                    resetDragState();
                                }
                                if (commitDrag) {
                                    
                                    // Save the new position
                                    // Account for CSS padding: field position includes padding offset
                                    const pad = parseFloat(field.dataset.padding) || 0;
                                    let newLeft = (parseFloat(field.style.left) / scaleX) + pad;
                                    let newTop = (parseFloat(field.style.top) / scaleY) + pad;
                                    let width = (parseFloat(field.style.width) / scaleX) - (pad * 2);
                                    let height = (parseFloat(field.style.height) / scaleY) - (pad * 2);
                                    
                                    // Clamp bbox to PDF page boundaries — text must NEVER go off-page
                                    const pdfPageW = parseFloat(field.dataset.pageWidth || '0');
                                    const pdfPageH = parseFloat(field.dataset.pageHeight || '0');
                                    if (pdfPageW > 0 && pdfPageH > 0) {
                                        if (newLeft < 0) { width += newLeft; newLeft = 0; }
                                        if (newTop < 0) { height += newTop; newTop = 0; }
                                        if (newLeft + width > pdfPageW) width = pdfPageW - newLeft;
                                        if (newTop + height > pdfPageH) height = pdfPageH - newTop;
                                        if (width < 1) width = 1;
                                        if (height < 1) height = 1;
                                    }
                                    
                                    // Calculate NEW origin based on the NEW position (not original!)
                                    // origin_x is the left edge, origin_y is the bottom edge (baseline area)
                                    const newOriginX = newLeft;
                                    const newOriginY = newTop + height;
                                    
                                    // Get current text — if the user hasn't typed anything
                                    // the spans are still absolutely-positioned so innerText
                                    // would mangle the spacing. Use the original blockText.
                                    const hasPositionedSpans = textSpan.querySelector('span[style*="position: absolute"]') ||
                                        textSpan.querySelector('span[style*="position:absolute"]');
                                    let currentText;
                                    if (hasPositionedSpans) {
                                        // Words are still in positioned spans — text is unedited
                                        currentText = blockText;
                                    } else {
                                        currentText = getOverlayExplicitText(textSpan);
                                        const originalClean = blockText.replace(/\s+/g, '');
                                        const currentClean = currentText.replace(/\s+/g, '');
                                        if (originalClean === currentClean) {
                                            currentText = blockText;
                                        }
                                    }
                                    const computedStyle = window.getComputedStyle(textSpan);
                                    const currentFontSizePx = computedStyle.fontSize;
                                    const currentLineHeightPx = computedStyle.lineHeight !== 'normal' ? computedStyle.lineHeight : '';
                                    const currentFontSizePdf = parseFloat(field.dataset.fontSize || (parseFloat(currentFontSizePx) / scaleY) || block.font_size);
                                    const currentTextColor = field.dataset.textColor || computedStyle.color || '#000000';
                                    const currentBackgroundColor = field.dataset.backgroundColor || colorToHex(computedStyle.backgroundColor || 'transparent');
                                    const richHtml = buildBlockRichHtml(textSpan, fontFamily, fontWeight, fontStyle, currentFontSizePx, currentLineHeightPx, currentTextColor);
                                    
                                    // Build per-word style data for preserving formatting on save
                                    // Read current toolbar overrides from the field's dataset
                                    const moveResolvedFont = field.dataset.fontFamily || field.dataset.font || block.font;
                                    const moveFieldWeight = parseInt(field.dataset.fontWeight || fontWeight) || 400;
                                    const moveFieldIsBold = moveFieldWeight >= 700;
                                    const moveFieldIsItalic = (field.dataset.fontStyle || fontStyle) === 'italic';
                                    const moveFieldUnderline = field.dataset.underline === 'true';

                                    const moveWordStylesArr = buildOverlayWordStylesForSave(field, moveResolvedFont, moveFieldWeight, field.dataset.fontStyle || fontStyle);

                                    overlayEditedFields.set(key, {
                                        page_number: pageData.page_number,
                                        block_num: block.block_num,
                                        original_text: safeBlockText,          // ORIGINAL PDF TEXT
                                        new_text: currentText,                 // TEXT WITH PRESERVED NEWLINES
                                        rich_html: richHtml,
                                        word_styles: moveWordStylesArr.length > 0 ? moveWordStylesArr : null,  // PER-WORD FORMATTING
                                        bbox: [newLeft, newTop, newLeft + width, newTop + height],
                                        original_bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                        origin_x: newOriginX,                  // NEW POSITION X
                                        origin_y: newOriginY,                  // NEW POSITION Y (bottom of box)
                                        font: moveResolvedFont,                // FONT NAME (user-selected or original)
                                        font_size: currentFontSizePdf,         // FONT SIZE
                                        font_weight: String(moveFieldWeight),  // FONT WEIGHT (400, 700, etc.)
                                        font_style: field.dataset.fontStyle || fontStyle, // FONT STYLE
                                        underline: moveFieldUnderline,         // TEXT DECORATION UNDERLINE
                                        font_xref: block.font_xref,            // FONT REFERENCE
                                        line_height: lineHeightValue || null,
                                        color: field.dataset.textColor || '#000000',  // TEXT COLOR
                                        background_color: currentBackgroundColor && currentBackgroundColor !== 'transparent' ? currentBackgroundColor : null
                                    });
                                    
                                    persistOverlayEdits();
                                    updateOverlaySaveButton();
                                }
                            };
                            
                            document.addEventListener('mousemove', moveHandler);
                            document.addEventListener('mouseup', upHandler);
                        })();
                        
                        // Add resize handles
                        const resizePositions = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'];
                        resizePositions.forEach(pos => {
                            const handle = document.createElement('div');
                            handle.className = `resize-handle ${pos} ${['n','s','e','w'].includes(pos) ? 'edge' : 'corner'}`;
                            field.appendChild(handle);
                        });
                        
                        // Resize functionality
                        field.addEventListener('mousedown', (e) => {
                            if (!e.target.classList.contains('resize-handle')) return;
                            
                            e.preventDefault();
                            e.stopPropagation();
                            
                            overlayInteractionActive = true;
                            pushUndoState();
                            
                            const handle = e.target;
                            const position = handle.classList[1]; // nw, n, ne, e, se, s, sw, w
                            
                            const startX = e.clientX;
                            const startY = e.clientY;
                            const startLeft = parseFloat(field.style.left);
                            const startTop = parseFloat(field.style.top);
                            const startWidth = parseFloat(field.style.width);
                            const startHeight = parseFloat(field.style.height);

                            // Page dimension limits (in pixels)
                            const maxPageWidth = parseFloat(field.dataset.canvasWidth || '0') || (field.parentElement ? field.parentElement.clientWidth : Infinity);
                            const maxPageHeight = parseFloat(field.dataset.canvasHeight || '0') || (field.parentElement ? field.parentElement.clientHeight : Infinity);

                            // Convert absolutely-positioned word spans to flowing text once at
                            // the start of the resize so that text wraps naturally with the box.
                            // Font size is NEVER changed — only the box dimensions change.
                            let normalizedOnce = false;
                            const normalizeOnce = () => {
                                if (normalizedOnce) return;
                                const hasPositionedSpans = textSpan.querySelector('span') &&
                                    Array.from(textSpan.querySelectorAll('span')).some(s => s.style.position === 'absolute');
                                if (!hasPositionedSpans) return;
                                // Preserve extracted line boundaries while normalizing spans.
                                // This keeps save payload geometry aligned with the original block.
                                const plainText = positionedSpansToFlowText(textSpan);
                                textSpan.textContent = plainText;
                                textSpan.style.whiteSpace = 'pre-wrap';
                                textSpan.style.wordBreak = 'break-word';
                                textSpan.style.width = '100%';
                                textSpan.style.height = 'auto';
                                normalizedOnce = true;
                            };

                            const onMouseMove = (moveEvent) => {
                                const dx = moveEvent.clientX - startX;
                                const dy = moveEvent.clientY - startY;
                                
                                let newLeft = startLeft;
                                let newTop = startTop;
                                let newWidth = startWidth;
                                let newHeight = startHeight;
                                
                                // Handle horizontal resize
                                if (position.includes('w')) {
                                    newLeft = startLeft + dx;
                                    newWidth = startWidth - dx;
                                } else if (position.includes('e')) {
                                    newWidth = startWidth + dx;
                                }
                                
                                // Handle vertical resize
                                if (position.includes('n')) {
                                    newTop = startTop + dy;
                                    newHeight = startHeight - dy;
                                } else if (position.includes('s')) {
                                    newHeight = startHeight + dy;
                                }
                                
                                // Enforce minimum width
                                if (newWidth < 40) {
                                    if (position.includes('w')) {
                                        newLeft = startLeft + startWidth - 40;
                                    }
                                    newWidth = 40;
                                }

                                // Clamp to page dimensions — box must stay within the page
                                if (newLeft < 0) { newWidth += newLeft; newLeft = 0; }
                                if (newTop < 0) { newHeight += newTop; newTop = 0; }
                                if (newWidth > maxPageWidth) newWidth = maxPageWidth;
                                if (newHeight > maxPageHeight) newHeight = maxPageHeight;
                                if (newLeft + newWidth > maxPageWidth) newLeft = maxPageWidth - newWidth;
                                if (newTop + newHeight > maxPageHeight) newTop = maxPageHeight - newHeight;

                                // If width changed, normalize positioned spans to flowing text
                                // so text wraps naturally (only happens once)
                                if (newWidth !== startWidth) {
                                    normalizeOnce();
                                }
                                
                                // Apply dimensions (width first so scrollHeight reflects wrap)
                                field.style.left = newLeft + 'px';
                                field.style.top = newTop + 'px';
                                field.style.width = newWidth + 'px';
                                field.style.height = newHeight + 'px';

                                // NO font-size changes — font stays constant during resize

                                // Enforce minimum height: box can never be shorter than its text content
                                const contentHeight = Math.ceil(textSpan.scrollHeight || 0);
                                const minHeight = Math.max(20, contentHeight);
                                if (newHeight < minHeight) {
                                    if (position.includes('n')) {
                                        newTop = startTop + startHeight - minHeight;
                                        field.style.top = newTop + 'px';
                                    }
                                    newHeight = minHeight;
                                    field.style.height = newHeight + 'px';
                                }
                            };
                            
                            const onMouseUp = () => {
                                document.removeEventListener('mousemove', onMouseMove);
                                document.removeEventListener('mouseup', onMouseUp);
                                
                                // Save the new dimensions
                                // Account for CSS padding: field position includes padding offset
                                const pad = parseFloat(field.dataset.padding) || 0;
                                let newLeft = (parseFloat(field.style.left) / scaleX) + pad;
                                let newTop = (parseFloat(field.style.top) / scaleY) + pad;
                                let newWidth = (parseFloat(field.style.width) / scaleX) - (pad * 2);
                                let newHeight = (parseFloat(field.style.height) / scaleY) - (pad * 2);
                                
                                // Clamp bbox to PDF page boundaries — text must NEVER go off-page
                                const rsPageW = parseFloat(field.dataset.pageWidth || '0');
                                const rsPageH = parseFloat(field.dataset.pageHeight || '0');
                                if (rsPageW > 0 && rsPageH > 0) {
                                    if (newLeft < 0) { newWidth += newLeft; newLeft = 0; }
                                    if (newTop < 0) { newHeight += newTop; newTop = 0; }
                                    if (newLeft + newWidth > rsPageW) newWidth = rsPageW - newLeft;
                                    if (newTop + newHeight > rsPageH) newHeight = rsPageH - newTop;
                                    if (newWidth < 1) newWidth = 1;
                                    if (newHeight < 1) newHeight = 1;
                                }
                                
                                // Use CURRENT position for origin (where text should be inserted)
                                const newOriginX = newLeft;
                                const newOriginY = newTop + newHeight;
                                
                                // Get current text — if normalizeOnce() ran, spans are now
                                // flowing text and innerText works. If not (pure move via
                                // corner handle without width change), spans are still
                                // absolutely-positioned and innerText would mangle spacing.
                                const hasPositionedSpans2 = textSpan.querySelector('span[style*="position: absolute"]') ||
                                    textSpan.querySelector('span[style*="position:absolute"]');
                                let currentText;
                                if (hasPositionedSpans2) {
                                    currentText = blockText;
                                } else {
                                    currentText = getOverlayExplicitText(textSpan);
                                    const originalClean = blockText.replace(/\s+/g, '');
                                    const currentClean = currentText.replace(/\s+/g, '');
                                    if (originalClean === currentClean) {
                                        currentText = blockText;
                                    }
                                }
                                const computedStyle = window.getComputedStyle(textSpan);
                                const currentFontSizePx = computedStyle.fontSize;
                                const currentLineHeightPx = computedStyle.lineHeight !== 'normal' ? computedStyle.lineHeight : '';
                                const currentFontSizePdf = parseFloat(field.dataset.fontSize || (parseFloat(currentFontSizePx) / scaleY) || block.font_size);
                                const currentTextColor = field.dataset.textColor || computedStyle.color || '#000000';
                                const currentBackgroundColor = field.dataset.backgroundColor || colorToHex(computedStyle.backgroundColor || 'transparent');
                                const richHtml = buildBlockRichHtml(textSpan, fontFamily, fontWeight, fontStyle, currentFontSizePx, currentLineHeightPx, currentTextColor);
                                
                                // Read current toolbar overrides from the field's dataset
                                const resizeResolvedFont = field.dataset.fontFamily || field.dataset.font || block.font;
                                const resizeFieldWeight = parseInt(field.dataset.fontWeight || fontWeight) || 400;
                                const resizeWordStylesArr = buildOverlayWordStylesForSave(field, resizeResolvedFont, resizeFieldWeight, field.dataset.fontStyle || fontStyle);
                                const resizeFieldUnderline = field.dataset.underline === 'true';

                                overlayEditedFields.set(key, {
                                    page_number: pageData.page_number,
                                    block_num: block.block_num,
                                    original_text: safeBlockText,               // ORIGINAL PDF TEXT
                                    new_text: currentText,                      // TEXT WITH PRESERVED NEWLINES
                                    rich_html: richHtml,
                                    word_styles: resizeWordStylesArr.length > 0 ? resizeWordStylesArr : null,
                                    bbox: [newLeft, newTop, newLeft + newWidth, newTop + newHeight],
                                    original_bbox: [blockLeft, blockTop, blockLeft + blockWidth, blockTop + blockHeight],
                                    origin_x: newOriginX,                       // NEW POSITION X
                                    origin_y: newOriginY,                       // NEW POSITION Y (bottom)
                                    font: resizeResolvedFont,                   // FONT NAME (user-selected or original)
                                    font_size: currentFontSizePdf,              // FONT SIZE
                                    font_weight: String(resizeFieldWeight),      // FONT WEIGHT
                                    font_style: field.dataset.fontStyle || fontStyle, // FONT STYLE
                                    underline: resizeFieldUnderline,            // TEXT DECORATION UNDERLINE
                                    font_xref: block.font_xref,                 // FONT REFERENCE
                                    line_height: lineHeightValue || null,
                                    color: field.dataset.textColor || '#000000', // TEXT COLOR
                                    background_color: currentBackgroundColor && currentBackgroundColor !== 'transparent' ? currentBackgroundColor : null
                                });
                                
                                persistOverlayEdits();
                                updateOverlaySaveButton();
                                overlayInteractionActive = false;
                            };
                            
                            document.addEventListener('mousemove', onMouseMove);
                            document.addEventListener('mouseup', onMouseUp);
                        });

                        overlay.appendChild(field);
                        fitOverlayFieldToRenderedContent(field, textSpan);
                    });
                };

                // Calculate scale factors based on the actual rendered canvas vs PDF page dimensions
                // pageData dimensions are from PyMuPDF (in PDF points)
                // canvas dimensions are from PDF.js rendering (in pixels at currentScale)
                const scaleX = canvas.width / pageData.width;
                const scaleY = canvas.height / pageData.height;
                
                // Once promoted extraction has been hydrated into live annotations,
                // do not also render the raw Fitz overlay blocks. Keeping both layers
                // alive reintroduces split-layout artifacts like
                // "meetingsmeetings" / "NY · SFNY · SF" on top of the cleaned
                // promoted annotation layer. AcroForm widgets are handled separately
                // by the passive widget preview path.
                const shouldRenderOverlayBlocks = !boundingBoxEditMode && !promotedExtractionHydrated;
                if (shouldRenderOverlayBlocks) {
                    renderOverlayBlocks();
                }

                // ── Font-ready re-render ──────────────────────────────────
                // Google Fonts are loaded asynchronously via <link> tags.
                // If measureTextWidth runs before the real font is available,
                // the canvas context falls back to a system font, computing
                // incorrect letter-spacing. Once fonts finish loading, we
                // rebuild the word spans so letter-spacing matches reality.
                if (document.fonts && document.fonts.ready) {
                    document.fonts.ready.then(() => {
                        overlay.querySelectorAll('.overlay-field').forEach((field) => {
                            if (!field._blockWords || field._blockWords.length === 0) return;
                            // Only re-render fields that still use absolutely-positioned
                            // word spans (not user-edited plain text).
                            const textSpan = field.querySelector('[contenteditable]');
                            if (!textSpan) return;
                            const blockLeft = parseFloat(field.dataset.originalLeft) || 0;
                            const blockTop = parseFloat(field.dataset.originalTop) || 0;
                            if (field.dataset.exactGeometry === '1') {
                                const renderedExactGeometry = buildExactBlockLineSpans(
                                    textSpan,
                                    field._overlaySourceBlock || null,
                                    scaleX,
                                    scaleY,
                                    blockLeft,
                                    blockTop
                                );
                                if (!renderedExactGeometry) {
                                    textSpan.innerHTML = '';
                                    textSpan.textContent = '';
                                    buildStyledWordSpans(
                                        textSpan,
                                        field._blockWords,
                                        scaleX,
                                        scaleY,
                                        blockLeft,
                                        blockTop,
                                        field._overlaySourceBlock || null,
                                        field.dataset.originalText || ''
                                    );
                                }
                                return;
                            }
                            const hasAbsoluteSpans = textSpan.querySelector('span[style*="position: absolute"]') ||
                                textSpan.querySelector('span[style*="position:absolute"]');
                            if (textSpan.textContent !== '') {
                                // Flow-text blocks are already rendered; just refit them after
                                // the real font metrics become available.
                                if (!hasAbsoluteSpans) {
                                    fitOverlayFieldToRenderedContent(field, textSpan);
                                    return;
                                }
                            }
                            textSpan.innerHTML = '';
                            textSpan.textContent = '';
                            buildStyledWordSpans(
                                textSpan,
                                field._blockWords,
                                scaleX,
                                scaleY,
                                blockLeft,
                                blockTop,
                                field._overlaySourceBlock || null,
                                field.dataset.originalText || ''
                            );
                            fitOverlayFieldToRenderedContent(field, textSpan);
                        });
                    });
                }

                return;

                pageData.words.forEach((word, index) => {
                    const storedEdit = overlayEditedFields.get(`${pageData.page_number}-${index}`);
                    if (storedEdit && storedEdit.new_text === '') {
                        return;
                    }
                    const field = document.createElement('div');
                    field.className = 'overlay-field';
                    field.style.position = 'absolute';
                    field.style.background = 'rgba(77, 208, 168, 0.1)';
                    field.style.pointerEvents = 'auto';
                    field.style.cursor = 'text';
                    field.style.padding = '2px';
                    field.style.minWidth = '20px';
                    field.style.minHeight = '15px';
                    field.style.display = 'flex';
                    field.style.alignItems = 'center';
                    
                    const textSpan = document.createElement('span');
                    textSpan.contentEditable = false;
                    textSpan.textContent = sanitizeOverlayText(storedEdit && storedEdit.new_text != null ? storedEdit.new_text : word.text);
                    
                    // Use the color from the PDF extraction (convert from integer to hex)
                    let textColor = '#000000';
                    console.log(`Word "${word.text}": color value=${word.color}, type=${typeof word.color}`);
                    if (word.color !== undefined && word.color !== null) {
                        if (typeof word.color === 'number') {
                            // Color is stored as an integer (RGB packed)
                            textColor = '#' + word.color.toString(16).padStart(6, '0');
                        } else if (typeof word.color === 'string') {
                            textColor = word.color;
                        }
                    }
                    // Debug: log non-black colors
                    if (textColor !== '#000000') {
                        console.log(`Color for "${word.text}": raw=${word.color}, converted=${textColor}`);
                    }
                    textSpan.style.color = textColor;
                    field.dataset.textColor = textColor;
                    
                    textSpan.style.outline = 'none';
                    textSpan.style.width = '100%';
                    textSpan.style.cursor = 'text';
                    textSpan.style.whiteSpace = 'pre-wrap';
                    textSpan.style.padding = '0';
                    textSpan.style.margin = '0';
                    textSpan.style.verticalAlign = 'baseline';
                    
                    // Map PDF fonts to web-safe fonts for preview (exact fonts used on save)
                    let fontFamily = 'Arial, sans-serif';
                    let fontWeight = 'normal';
                    let fontStyle = 'normal';
                    
                    if (word.font) {
                        const fontName = word.font.toLowerCase();
                        
                        // Detect weight
                        if (fontName.includes('bold') || fontName.includes('700') || fontName.includes('black') || fontName.includes('-b')) {
                            fontWeight = 'bold';
                        } else if (fontName.includes('semibold') || fontName.includes('600')) {
                            fontWeight = '600';
                        } else if (fontName.includes('medium') || fontName.includes('500')) {
                            fontWeight = '500';
                        }
                        
                        // Detect style
                        if (fontName.includes('italic') || fontName.includes('oblique') || fontName.includes('-i')) {
                            fontStyle = 'italic';
                        }
                        
                        // Map to web-safe font families
                        if (fontName.includes('gelasio') || fontName.includes('georgia')) {
                            fontFamily = '"Georgia", "Liberation Serif", serif';
                        } else if (fontName.includes('garamond') || fontName.includes('baskerville')) {
                            fontFamily = '"AnnotGaramond", "EB Garamond", Baskerville, serif';
                        } else if (fontName.includes('times') || fontName.includes('serif')) {
                            fontFamily = '"Times New Roman", Times, serif';
                        } else if (fontName.includes('courier') || fontName.includes('mono')) {
                            fontFamily = '"Cousine", "Courier New", Courier, monospace';
                        } else if (fontName.includes('arimo') || fontName.includes('arial') || fontName.includes('helvetica')) {
                            fontFamily = 'Arial, Helvetica, sans-serif';
                        } else if (fontName.includes('roboto') || fontName.includes('sans')) {
                            fontFamily = 'Arial, sans-serif';
                        } else {
                            // Default to sans-serif for unknown fonts
                            fontFamily = 'Arial, sans-serif';
                        }
                    }
                    
                    textSpan.style.fontFamily = fontFamily;
                    textSpan.style.fontWeight = fontWeight;
                    textSpan.style.fontStyle = fontStyle;
                    
                    field.appendChild(textSpan);
                    
                    // Apply scaling to PDF coordinates to get canvas pixel positions
                    const padding = 4;
                    const baseLeft = storedEdit ? storedEdit.bbox[0] : word.left;
                    const baseTop = storedEdit ? storedEdit.bbox[1] : word.top;
                    const baseWidth = storedEdit ? (storedEdit.bbox[2] - storedEdit.bbox[0]) : word.width;
                    const baseHeight = storedEdit ? (storedEdit.bbox[3] - storedEdit.bbox[1]) : word.height;

                    const left = (baseLeft * scaleX) - padding;
                    const top = (baseTop * scaleY) - padding;
                    const width = (baseWidth * scaleX) + (padding * 2);
                    const height = (baseHeight * scaleY) + (padding * 2);
                    
                    field.style.left = left + 'px';
                    field.style.top = top + 'px';
                    field.style.width = width + 'px';
                    field.style.height = height + 'px';
                    field.style.boxSizing = 'border-box';
                    textSpan.style.fontSize = (word.font_size * scaleY) + 'px';
                    textSpan.style.fontFamily = getCssFontFamily(word.font, word.embedded_font_name || word.font);
                    textSpan.style.fontWeight = word.bold ? '700' : '400';
                    textSpan.style.fontStyle = word.italic ? 'italic' : 'normal';
                    textSpan.style.display = 'inline-block';
                    textSpan.style.transformOrigin = 'left baseline';
                    textSpan.style.lineHeight = '1';
                    textSpan.style.height = '100%';

                    const targetWidth = baseWidth * scaleX;
                    const measuredWidth = measureTextWidth(
                        word.text,
                        word.font_size * scaleY,
                        textSpan.style.fontFamily,
                        textSpan.style.fontWeight,
                        textSpan.style.fontStyle
                    );
                    if (measuredWidth > 0 && targetWidth > 0) {
                        const ratio = Math.max(0.7, Math.min(1.3, targetWidth / measuredWidth));
                        textSpan.style.transform = `scaleX(${ratio})`;
                    }
                    
                    if (index === 0) {
                        console.log('First field positioning:', {
                            wordLeft: word.left,
                            wordTop: word.top,
                            wordHeight: word.height,
                            scaledLeft: left,
                            scaledTop: top,
                            width,
                            height
                        });
                    }
                    
                    // Store original data
                    field.dataset.originalText = word.text;
                    field.dataset.originalLeft = word.left;
                    field.dataset.originalTop = word.top;
                    field.dataset.originalWidth = word.width;
                    field.dataset.originalHeight = word.height;
                    field.dataset.originalOriginX = word.origin_x ?? word.left;
                    field.dataset.originalOriginY = word.origin_y ?? (word.top + word.height);
                    field.dataset.pageNumber = pageData.page_number;
                    field.dataset.wordIndex = index;
                    field.dataset.font = word.font;
                    if (word.embedded_font_name) {
                        field.dataset.embeddedFontName = word.embedded_font_name;
                    }
                    field.dataset.fontSize = word.font_size;
                    if (word.font_xref !== undefined && word.font_xref !== null) {
                        field.dataset.fontXref = word.font_xref;
                    }
                    field.dataset.canvasWidth = canvas.width;
                    field.dataset.canvasHeight = canvas.height;
                    field.dataset.pageWidth = pageData.width;
                    field.dataset.pageHeight = pageData.height;
                    field.dataset.padding = padding;
                    
                    // Allow Enter key to insert line breaks
                    textSpan.addEventListener('keydown', function(e) {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            document.execCommand('insertLineBreak');
                        }
                    });

                    textSpan.addEventListener('beforeinput', function(e) {
                        const inputType = String(e.inputType || '');
                        if (
                            inputType.startsWith('insert')
                            || inputType.startsWith('delete')
                            || inputType === 'historyUndo'
                            || inputType === 'historyRedo'
                        ) {
                            pushUndoState();
                        }
                    });
                    
                    // Track changes and auto-expand width as user types
                    textSpan.addEventListener('input', () => {
                        // Auto-expand field width to fit text content
                        const currentText = textSpan.textContent;
                        const currentFontSize = parseFloat(textSpan.style.fontSize) || 12;
                        const currentFontFamily = textSpan.style.fontFamily || 'sans-serif';
                        const currentFontWeight = textSpan.style.fontWeight || 'normal';
                        const currentFontStyle = textSpan.style.fontStyle || 'normal';
                        
                        const measuredWidth = measureTextWidth(
                            currentText,
                            currentFontSize,
                            currentFontFamily,
                            currentFontWeight,
                            currentFontStyle
                        );
                        
                        const currentPadding = parseFloat(field.dataset.padding || '4');
                        const minWidth = measuredWidth + (currentPadding * 2) + 10; // Add 10px buffer
                        const currentWidth = parseFloat(field.style.width);
                        
                        // Only expand width if needed (don't shrink)
                        if (minWidth > currentWidth) {
                            field.style.width = minWidth + 'px';
                        }
                        
                        trackOverlayFieldChange(field, textSpan, pageData, word, index);
                    });
                    
                    // Save undo state when user starts editing (before changes)
                    textSpan.addEventListener('focus', function() {
                        pushUndoState();
                    });
                    
                    // Add drag-to-move functionality
                    (function() {
                        let isDragging = false;
                        let dragStart = { x: 0, y: 0 };
                        
                    field.addEventListener('mousedown', function(e) {
                        // Don't drag if clicking on delete button, resize handles, or text input
                        if (e.target.classList.contains('overlay-resize-handle')) return;
                        if (e.target === textSpan || textSpan.contains?.(e.target)) return;
                            
                            // Save state before drag starts
                            pushUndoState();
                            
                            isDragging = true;
                            dragStart = { x: e.clientX, y: e.clientY };
                            field.style.cursor = 'move';
                            e.preventDefault();
                            e.stopPropagation();
                        });
                        
                        const moveHandler = function(e) {
                            if (!isDragging) return;
                            
                            const dx = e.clientX - dragStart.x;
                            const dy = e.clientY - dragStart.y;
                            
                            const currentLeft = parseFloat(field.style.left);
                            const currentTop = parseFloat(field.style.top);
                            const fieldWidth = parseFloat(field.style.width) || field.offsetWidth;
                            const fieldHeight = parseFloat(field.style.height) || field.offsetHeight;
                            const maxW = parseFloat(field.dataset.canvasWidth || '0') || (field.parentElement ? field.parentElement.clientWidth : Infinity);
                            const maxH = parseFloat(field.dataset.canvasHeight || '0') || (field.parentElement ? field.parentElement.clientHeight : Infinity);
                            
                            let newLeft = currentLeft + dx;
                            let newTop = currentTop + dy;
                            // Clamp to page boundaries
                            newLeft = Math.max(0, Math.min(newLeft, maxW - fieldWidth));
                            newTop = Math.max(0, Math.min(newTop, maxH - fieldHeight));
                            
                            field.style.left = newLeft + 'px';
                            field.style.top = newTop + 'px';
                            
                            dragStart = { x: e.clientX, y: e.clientY };
                        };
                        
                        const upHandler = function() {
                            if (isDragging) {
                                isDragging = false;
                                field.style.cursor = 'default';
                                // Track the position change
                                trackOverlayFieldChange(field, textSpan, pageData, word, index);
                            }
                        };
                        
                        document.addEventListener('mousemove', moveHandler);
                        document.addEventListener('mouseup', upHandler);
                    })();
                    
                    
                    // Add resize handles
                    const handles = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'];
                    handles.forEach((pos) => {
                        const handle = document.createElement('div');
                        handle.className = `resize-handle ${pos} ${['n','s','e','w'].includes(pos) ? 'edge' : 'corner'}`;
                        handle.dataset.position = pos;
                        handle.addEventListener('mousedown', startOverlayResize);
                        field.appendChild(handle);
                    });

                    // Drag to reposition
                    let isDragging = false;
                    let dragStart = { x: 0, y: 0 };

                    field.addEventListener('mousedown', (e) => {
                        if (e.target.classList.contains('resize-handle')) return;
                        if (e.target !== field && e.target !== textSpan) return;
                        if (toolMode !== 'edit-text') return;
                        if (textSpan.isContentEditable && textSpan.contains?.(e.target)) return;

                        isDragging = true;
                        dragStart = { x: e.clientX, y: e.clientY };
                        field.style.cursor = 'move';
                        textSpan.style.cursor = 'move';
                        e.preventDefault();
                        e.stopPropagation();
                    });

                    field.addEventListener('click', (e) => {
                        if (e.target.classList.contains('resize-handle')) return;
                        setOverlaySelection(field);
                    });

                    document.addEventListener('mousemove', (e) => {
                        if (!isDragging) return;
                        const dx = e.clientX - dragStart.x;
                        const dy = e.clientY - dragStart.y;
                        const currentLeft = parseFloat(field.style.left);
                        const currentTop = parseFloat(field.style.top);
                        const fieldWidth = parseFloat(field.style.width) || field.offsetWidth;
                        const fieldHeight = parseFloat(field.style.height) || field.offsetHeight;
                        const maxW = parseFloat(field.dataset.canvasWidth || '0') || (field.parentElement ? field.parentElement.clientWidth : Infinity);
                        const maxH = parseFloat(field.dataset.canvasHeight || '0') || (field.parentElement ? field.parentElement.clientHeight : Infinity);
                        
                        let newLeft = currentLeft + dx;
                        let newTop = currentTop + dy;
                        // Clamp to page boundaries
                        newLeft = Math.max(0, Math.min(newLeft, maxW - fieldWidth));
                        newTop = Math.max(0, Math.min(newTop, maxH - fieldHeight));
                        
                        field.style.left = newLeft + 'px';
                        field.style.top = newTop + 'px';
                        dragStart = { x: e.clientX, y: e.clientY };
                    });

                    document.addEventListener('mouseup', () => {
                        if (!isDragging) return;
                        isDragging = false;
                        field.style.cursor = 'text';
                        textSpan.style.cursor = 'text';
                        const originalWord = buildOriginalWordFromField(field, word.text);
                        trackOverlayFieldChange(field, textSpan, pageData, originalWord, index);
                    });

                    textSpan.addEventListener('dblclick', (e) => {
                        if (!overlayEditorActive) return;
                        if (!ensureEditTextModeEnabled()) return;
                        if (textSpan.isContentEditable) {
                            e.preventDefault();
                            selectAllEditableContents(textSpan);
                        }
                        e.stopPropagation();
                        textSpan.style.cursor = 'text';
                        textSpan.focus();
                    });

                    overlay.appendChild(field);
                });
            }

            function buildOriginalWordFromField(field, fallbackText) {
                return {
                    text: field.dataset.originalText || fallbackText || '',
                    left: parseFloat(field.dataset.originalLeft || '0'),
                    top: parseFloat(field.dataset.originalTop || '0'),
                    width: parseFloat(field.dataset.originalWidth || '0'),
                    height: parseFloat(field.dataset.originalHeight || '0'),
                    origin_x: parseFloat(field.dataset.originalOriginX || field.dataset.originalLeft || '0'),
                    origin_y: parseFloat(field.dataset.originalOriginY || (parseFloat(field.dataset.originalTop || '0') + parseFloat(field.dataset.originalHeight || '0'))),
                    font: field.dataset.font || 'helv',
                    font_size: parseFloat(field.dataset.fontSize || '12')
                };
            }

            function startOverlayResize(e) {
                e.preventDefault();
                e.stopPropagation();

                overlayResizingField = e.target.closest('.overlay-field');
                overlayResizePosition = e.target.dataset.position;
                if (!overlayResizingField) return;

                const rect = overlayResizingField.getBoundingClientRect();
                const containerRect = overlayResizingField.parentElement.getBoundingClientRect();
                const textSpan = overlayResizingField.querySelector('[contenteditable]');
                const computedStyle = textSpan ? window.getComputedStyle(textSpan) : null;
                overlayResizeStart = {
                    x: e.clientX,
                    y: e.clientY,
                    width: rect.width,
                    height: rect.height,
                    left: rect.left - containerRect.left,
                    top: rect.top - containerRect.top,
                    fontSizePx: computedStyle ? parseFloat(computedStyle.fontSize) : null,
                    lineHeightPx: computedStyle && computedStyle.lineHeight !== 'normal'
                        ? parseFloat(computedStyle.lineHeight)
                        : null,
                    textSpan
                };

                if (textSpan) {
                    textSpan.contentEditable = false;
                }
                document.addEventListener('mousemove', doOverlayResize);
                document.addEventListener('mouseup', stopOverlayResize);
            }

            function doOverlayResize(e) {
                if (!overlayResizingField) return;

                const dx = e.clientX - overlayResizeStart.x;
                const dy = e.clientY - overlayResizeStart.y;

                let newLeft = overlayResizeStart.left;
                let newTop = overlayResizeStart.top;
                let newWidth = overlayResizeStart.width;
                let newHeight = overlayResizeStart.height;

                if (overlayResizePosition.includes('w')) {
                    newLeft = overlayResizeStart.left + dx;
                    newWidth = overlayResizeStart.width - dx;
                }
                if (overlayResizePosition.includes('e')) {
                    newWidth = overlayResizeStart.width + dx;
                }
                if (overlayResizePosition.includes('n')) {
                    newTop = overlayResizeStart.top + dy;
                    newHeight = overlayResizeStart.height - dy;
                }
                if (overlayResizePosition.includes('s')) {
                    newHeight = overlayResizeStart.height + dy;
                }

                // --- Page dimension clamping ---
                const maxPageWidth = parseFloat(overlayResizingField.dataset.canvasWidth || '0');
                const maxPageHeight = parseFloat(overlayResizingField.dataset.canvasHeight || '0');

                if (newWidth < 20) newWidth = 20;
                if (newLeft < 0) { newWidth += newLeft; newLeft = 0; }
                if (maxPageWidth > 0 && newLeft + newWidth > maxPageWidth) {
                    newWidth = maxPageWidth - newLeft;
                }
                if (newTop < 0) { newHeight += newTop; newTop = 0; }
                if (maxPageHeight > 0 && newTop + newHeight > maxPageHeight) {
                    newHeight = maxPageHeight - newTop;
                }

                // --- Enable text wrapping (no font changes) ---
                if (overlayResizeStart.textSpan) {
                    overlayResizeStart.textSpan.style.whiteSpace = 'pre-wrap';
                    overlayResizeStart.textSpan.style.wordBreak = 'break-word';
                    overlayResizeStart.textSpan.style.width = '100%';
                    overlayResizeStart.textSpan.style.height = 'auto';
                }

                // Apply width first so text can reflow
                overlayResizingField.style.left = newLeft + 'px';
                overlayResizingField.style.top = newTop + 'px';
                overlayResizingField.style.width = newWidth + 'px';

                // --- Min-height from text content ---
                if (overlayResizeStart.textSpan) {
                    const contentHeight = Math.ceil(overlayResizeStart.textSpan.scrollHeight);
                    const minHeight = Math.max(15, contentHeight);
                    if (newHeight < minHeight) newHeight = minHeight;
                }

                overlayResizingField.style.height = newHeight + 'px';

                // NO font scaling - font size never changes during resize
            }

            function stopOverlayResize() {
                if (overlayResizingField) {
                    const textSpan = overlayResizingField.querySelector('[contenteditable]');
                    if (textSpan) {
                        // Only re-enable editing if field was in editing mode before resize
                        textSpan.contentEditable = overlayResizingField.classList.contains('editing');
                    }
                    const pageNumber = parseInt(overlayResizingField.dataset.pageNumber, 10);
                    const index = overlayResizingField.dataset.wordIndex;
                    const originalWord = buildOriginalWordFromField(overlayResizingField, textSpan ? textSpan.textContent : '');
                    trackOverlayFieldChange(overlayResizingField, textSpan, { page_number: pageNumber }, originalWord, index);
                    overlayResizingField = null;
                }
                document.removeEventListener('mousemove', doOverlayResize);
                document.removeEventListener('mouseup', stopOverlayResize);
            }
            
            
            
            function trackOverlayFieldChange(field, textSpan, pageData, originalWord, index) {
                const key = typeof index === 'string' ? index : `${pageData.page_number}-${index}`;
                const currentText = textSpan.textContent.trim();

                // Get current position and size in browser pixels
                const currentLeft = parseFloat(field.style.left);
                const currentTop = parseFloat(field.style.top);
                const currentWidth = parseFloat(field.style.width);
                const currentHeight = parseFloat(field.style.height);

                // Get PDF dimensions and canvas dimensions for scale calculation
                const pageWidth = parseFloat(field.dataset.pageWidth || '0');
                const pageHeight = parseFloat(field.dataset.pageHeight || '0');
                const canvasWidth = parseFloat(field.dataset.canvasWidth || '0');
                const canvasHeight = parseFloat(field.dataset.canvasHeight || '0');
                const padding = parseFloat(field.dataset.padding || '0');

                const overlayEl = field.parentElement;
                const overlayWidth = overlayEl ? overlayEl.clientWidth : 0;
                const overlayHeight = overlayEl ? overlayEl.clientHeight : 0;
                const effectiveWidth = canvasWidth || overlayWidth || 1;
                const effectiveHeight = canvasHeight || overlayHeight || 1;

                // Calculate scale factors (pixels per PDF point)
                const scaleX = effectiveWidth / pageWidth;
                const scaleY = effectiveHeight / pageHeight;

                // Convert browser pixels to PDF points
                // Account for CSS padding: field position includes padding offset,
                // and dimensions include 2*padding. Subtract padding to get content bbox.
                const padPx = padding;  // padding is in pixels for word-level fields
                let pdfLeft = (currentLeft + padPx) / scaleX;
                let pdfTop = (currentTop + padPx) / scaleY;
                let pdfWidth = (currentWidth - padPx * 2) / scaleX;
                let pdfHeight = (currentHeight - padPx * 2) / scaleY;

                // Clamp bbox to PDF page boundaries — text must NEVER go off-page
                if (pageWidth > 0 && pageHeight > 0) {
                    if (pdfLeft < 0) { pdfWidth += pdfLeft; pdfLeft = 0; }
                    if (pdfTop < 0) { pdfHeight += pdfTop; pdfTop = 0; }
                    if (pdfLeft + pdfWidth > pageWidth) pdfWidth = pageWidth - pdfLeft;
                    if (pdfTop + pdfHeight > pageHeight) pdfHeight = pageHeight - pdfTop;
                    if (pdfWidth < 1) pdfWidth = 1;
                    if (pdfHeight < 1) pdfHeight = 1;
                }
                
                // Calculate baseline origin for text insertion
                const originDx = originalWord.origin_x - originalWord.left;
                const originDy = originalWord.origin_y - (originalWord.top + originalWord.height);
                const pdfOriginX = pdfLeft + originDx;
                const pdfOriginY = (pdfTop + pdfHeight) + originDy;

                const hasTextChanged = currentText !== originalWord.text;
                const hasPositionChanged = Math.abs(pdfLeft - originalWord.left) > 1 || Math.abs(pdfTop - originalWord.top) > 1;
                const hasSizeChanged = Math.abs(pdfWidth - originalWord.width) > 1 || Math.abs(pdfHeight - originalWord.height) > 1;

                // Detect style changes (font weight, font style, color, font size)
                const currentFontWeight = field.dataset.fontWeight || '400';
                const originalFontWeight = field.dataset.originalFontWeight || '400';
                const currentFontStyle = field.dataset.fontStyle || 'normal';
                const originalFontStyle = field.dataset.originalFontStyle || 'normal';
                const currentColor = field.dataset.textColor || '#000000';
                const originalColor = field.dataset.originalTextColor || '#000000';
                const currentFontSizePdf = parseFloat(field.dataset.fontSize || String(originalWord.font_size || 12));
                const originalFontSize = originalWord.font_size || 12;
                // Check if the text element's innerHTML contains styled <span> elements (per-word styling)
                const textEl = getOverlayTextElement(field);
                const hasRichStyling = textEl && textEl.querySelector('span[style]') !== null;

                const hasStyleChanged = currentFontWeight !== originalFontWeight
                    || currentFontStyle !== originalFontStyle
                    || currentColor !== originalColor
                    || Math.abs(currentFontSizePdf - originalFontSize) > 0.5
                    || hasRichStyling
                    || field.dataset.underline === 'true';

                if (hasTextChanged || hasPositionChanged || hasSizeChanged || hasStyleChanged) {
                    const colorValue = field.dataset.textColor || '#000000';
                    const colorHex = colorValue.startsWith('#') ? colorValue : '#' + colorValue;
                    
                    const editData = {
                        page_index: pageData.page_number - 1, // 0-based for Python
                        page_number: pageData.page_number,    // 1-based for display
                        original_text: originalWord.text,
                        new_text: currentText,
                        
                        // Browser coordinates (for debugging)
                        pixel_left: currentLeft,
                        pixel_top: currentTop,
                        pixel_width: currentWidth,
                        pixel_height: currentHeight,
                        
                        // PDF coordinates (converted from pixels)
                        pdf_x: pdfLeft,
                        pdf_y: pdfTop,
                        pdf_width: pdfWidth,
                        pdf_height: pdfHeight,
                        
                        // Scale factors
                        scale_x: scaleX,
                        scale_y: scaleY,
                        viewport_width: effectiveWidth,
                        viewport_height: effectiveHeight,
                        
                        // Bounding boxes for compatibility
                        original_bbox: [originalWord.left, originalWord.top, originalWord.left + originalWord.width, originalWord.top + originalWord.height],
                        bbox: [pdfLeft, pdfTop, pdfLeft + pdfWidth, pdfTop + pdfHeight],
                        
                        // Text baseline anchor point
                        origin_x: pdfOriginX,
                        origin_y: pdfOriginY,
                        
                        // Font information
                        font_xref: field.dataset.fontXref ? parseInt(field.dataset.fontXref, 10) : null,
                        font: field.dataset.fontFamily || field.dataset.font || originalWord.font,
                        font_size: currentFontSizePdf,
                        font_weight: currentFontWeight,
                        font_style: currentFontStyle,
                        underline: field.dataset.underline === 'true',
                        color: colorHex,
                        
                        // Page dimensions
                        page_width: pageWidth,
                        page_height: pageHeight
                    };
                    
                    overlayEditedFields.set(key, editData);
                } else {
                    overlayEditedFields.delete(key);
                }
                updateOverlaySaveButton();
                persistOverlayEdits();
            }
            
            // ── Live-save state ──────────────────────────────────────────────────
            // _liveSavedKeys  : keys successfully written to disk
            // _lsPendingData  : keys debounced but not yet sent (timer still running)
            // _lsInflight     : keys currently in-flight (fetch in progress)
            const _liveSavedKeys  = new Set();
            const _lsPendingData  = new Map(); // editKey → { editData, timerId }
            const _lsInflight     = new Map(); // editKey → Promise<void>

            async function _executeLiveSave(editKey, editData) {
                _lsPendingData.delete(editKey);
                _liveSavedKeys.delete(editKey);
                const field = document.querySelector(`.overlay-field[data-word-index="${editKey}"]`);
                if (field) field.dataset.liveSaveState = 'saving';
                updateOverlaySaveButton();

                try {
                    const atomicEdits = buildAtomicLiveSaveEditsForKey(editKey, editData)
                        .filter((atomicEdit) => isMaterialOverlaySaveEdit(atomicEdit, { honorForceReinsert: false }));
                    if (atomicEdits.length === 0) {
                        _liveSavedKeys.add(editKey);
                        if (field) field.dataset.liveSaveState = 'saved';
                        return { success: true, skipped_noop: true };
                    }
                    let lastResult = null;

                    for (const atomicEdit of atomicEdits) {
                        const payload = buildLiveSavePayloadFromEdit(atomicEdit);
                        payload.paragraph_bbox = Array.isArray(atomicEdit.paragraph_bbox) ? atomicEdit.paragraph_bbox : null;

                        const resp = await fetch(liveSaveUrl, {
                            method: 'POST',
                            credentials: 'same-origin',
                            headers: {
                                'X-CSRF-TOKEN': csrfToken,
                                'Content-Type': 'application/json',
                                'Accept': 'application/json',
                            },
                            body: JSON.stringify(payload),
                        });

                        const result = await resp.json().catch(() => ({}));
                        if (!resp.ok || !result.success) {
                            if (field) field.dataset.liveSaveState = 'error';
                            console.warn(`[live-save] ✗ key=${editKey}`, result.error || resp.status);
                            return {
                                success: false,
                                message: result.error || result.message || `Live save failed (${resp.status})`,
                            };
                        }
                        lastResult = result;
                    }

                    _liveSavedKeys.add(editKey);
                    if (field) field.dataset.liveSaveState = 'saved';
                    updateSavedEditPreviewLink(lastResult?.saved_preview_url || savedEditPreviewUrl);
                    console.log(`[live-save] ✓ key=${editKey}`);
                    return {
                        success: true,
                        saved_preview_url: lastResult?.saved_preview_url || savedEditPreviewUrl,
                    };
                } catch (err) {
                    if (field) field.dataset.liveSaveState = 'error';
                    console.warn('[live-save] network error', err);
                    return {
                        success: false,
                        message: err?.message || 'Live save failed.',
                    };
                } finally {
                    _lsInflight.delete(editKey);
                    updateOverlaySaveButton();
                }
            }

            /**
             * Schedule a live-save for a single field with a short debounce.
             * Called every time a field is committed.
             */
            function triggerLiveSave(editKey, editData) {
                // Cancel any pending debounce for this key
                const existing = _lsPendingData.get(editKey);
                if (existing) clearTimeout(existing.timerId);

                _lsPendingData.delete(editKey);
                _liveSavedKeys.delete(editKey);
                const field = document.querySelector(`.overlay-field[data-word-index="${editKey}"]`);
                if (field) delete field.dataset.liveSaveState;
                updateOverlaySaveButton();

                // Schedule the debounced save
                const timerId = setTimeout(() => {
                    _lsPendingData.delete(editKey);
                    if (!_lsInflight.has(editKey)) {
                        const promise = _executeLiveSave(editKey, editData);
                        _lsInflight.set(editKey, promise);
                    }
                }, 800);
                _lsPendingData.set(editKey, { editData, timerId });
            }

            /**
             * Called by the Save button handler.
             * Fires all pending debounced saves immediately, then waits for every
             * in-flight request to settle — so the "all saved" check is reliable.
             */
            async function flushLiveSaves() {
                // Fire any pending (debounced) saves immediately
                for (const [key, { editData, timerId }] of _lsPendingData.entries()) {
                    clearTimeout(timerId);
                    if (!_lsInflight.has(key)) {
                        const promise = _executeLiveSave(key, editData);
                        _lsInflight.set(key, promise);
                    }
                }
                _lsPendingData.clear();
                // Await everything in-flight
                if (_lsInflight.size > 0) {
                    await Promise.allSettled([..._lsInflight.values()]);
                }
            }

            /** True when every pending overlay edit has been live-saved to disk. */
            function allOverlayEditsLiveSaved() {
                return false;
            }

            async function finalizeLiveSaveSession({ workingCopyToken = null } = {}) {
                if (overlaySaveMode !== 'live_save') {
                    return { success: true };
                }

                const response = await fetch('{{ route("documents.saveEdits", $document) }}', {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'X-Requested-With': 'XMLHttpRequest',
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({
                        edits: [],
                        finalize_live_save: true,
                        working_copy_token: workingCopyToken || null,
                    })
                });

                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result.success) {
                    throw new Error(result.error || result.message || `Live-save finalize failed (${response.status})`);
                }

                updateSavedEditPreviewLink(result.saved_preview_url || savedEditPreviewUrl);
                return result;
            }

            async function runOverlayEditsThroughLiveSave(edits, { workingCopyToken = null, finalize = true } = {}) {
                let lastResult = null;
                const liveSavePreviews = [];
                const liveSavePreviewAssets = [];
                const materialEdits = edits.filter((edit) => isMaterialOverlaySaveEdit(edit, { honorForceReinsert: false }));

                if (materialEdits.length === 0) {
                    return { success: true, skipped_noop: true, saved_preview_url: savedEditPreviewUrl, liveSavePreviews, liveSavePreviewAssets };
                }

                for (const edit of materialEdits) {
                    const resp = await fetch(liveSaveUrl, {
                        method: 'POST',
                        credentials: 'same-origin',
                        headers: {
                            'X-CSRF-TOKEN': csrfToken,
                            'Content-Type': 'application/json',
                            'Accept': 'application/json',
                        },
                        body: JSON.stringify({
                            ...buildLiveSavePayloadFromEdit(edit),
                            working_copy_token: workingCopyToken || null,
                        }),
                    });

                    const result = await resp.json().catch(() => ({}));
                    if (result.skipped_noop) {
                        continue;
                    }
                    if (!resp.ok || !result.success) {
                        throw new Error(result.error || result.message || `Live save failed (${resp.status})`);
                    }

                    lastResult = result;
                    if (result?.preview) {
                        liveSavePreviews.push(clonePlainData(result.preview));
                        liveSavePreviewAssets.push({
                            preview: clonePlainData(result.preview),
                            beforeImageUrl: result.before_image_url || null,
                            redactedImageUrl: result.redacted_image_url || null,
                            finalImageUrl: result.final_image_url || null,
                        });
                    }
                    updateSavedEditPreviewLink(result.saved_preview_url || savedEditPreviewUrl);
                }

                if (finalize) {
                    await finalizeLiveSaveSession({ workingCopyToken });
                }
                return {
                    ...(lastResult || { success: true, saved_preview_url: savedEditPreviewUrl }),
                    liveSavePreviews,
                    liveSavePreviewAssets,
                };
            }

            function updateOverlaySaveButton() {
                // Unified save button — update label to indicate pending overlay changes
                const unifiedBtn = document.getElementById('save-btn');
                if (!unifiedBtn) return;
                const desktopSpan = unifiedBtn.querySelector('span.hidden.sm\\:inline');
                const mobileSpan = unifiedBtn.querySelector('span.sm\\:hidden');
                if (overlayEditedFields.size > 0) {
                    const savedCount = Array.from(overlayEditedFields.keys()).filter(k => _liveSavedKeys.has(k)).length;
                    const total = overlayEditedFields.size;
                    const label = savedCount === total ? `Save PDF ✓ (${total})` : `Save PDF (${savedCount}/${total})`;
                    if (desktopSpan) desktopSpan.textContent = label;
                    if (mobileSpan) mobileSpan.textContent = savedCount === total ? `Save ✓` : `Save (${savedCount}/${total})`;
                } else {
                    if (desktopSpan) desktopSpan.textContent = 'Save PDF';
                    if (mobileSpan) mobileSpan.textContent = 'Save';
                }
            }

            function updateUndoRedoButtons() {
                if (overlayUndoBtn) {
                    overlayUndoBtn.disabled = overlayUndoStack.length === 0;
                }
                if (overlayRedoBtn) {
                    overlayRedoBtn.disabled = overlayRedoStack.length === 0;
                }
            }

            function resetOverlayHistory() {
                overlayUndoStack = [];
                overlayRedoStack = [];
                updateUndoRedoButtons();
            }

            function pushUndoState(snapshot = null) {
                const state = snapshot || snapshotOverlayEditState();
                const lastState = overlayUndoStack.length > 0 ? overlayUndoStack[overlayUndoStack.length - 1] : null;
                if (overlayHistorySnapshotsEqual(lastState, state)) {
                    updateUndoRedoButtons();
                    return false;
                }

                overlayUndoStack.push(state);
                if (overlayUndoStack.length > overlayUndoLimit) {
                    overlayUndoStack.shift();
                }
                overlayRedoStack = [];
                updateUndoRedoButtons();
                return true;
            }

            function overlayUndo() {
                if (overlayUndoStack.length === 0) return;
                
                const currentState = snapshotOverlayEditState();
                overlayRedoStack.push(currentState);
                
                const previousState = overlayUndoStack.pop();
                restoreOverlayEditState(previousState);
                
                updateUndoRedoButtons();
                updateOverlaySaveButton();
                renderPdfWithOverlay();
            }

            function overlayRedo() {
                if (overlayRedoStack.length === 0) return;
                
                const currentState = snapshotOverlayEditState();
                overlayUndoStack.push(currentState);
                if (overlayUndoStack.length > overlayUndoLimit) {
                    overlayUndoStack.shift();
                }
                
                const nextState = overlayRedoStack.pop();
                restoreOverlayEditState(nextState);
                
                updateUndoRedoButtons();
                updateOverlaySaveButton();
                renderPdfWithOverlay();
            }
            
            function persistOverlayEdits() {
                try {
                    const editsArray = Array.from(overlayEditedFields.entries()).map(([key, value]) => ({
                        key,
                        value,
                    }));
                    sessionStorage.setItem(overlayEditsStorageKey, JSON.stringify(editsArray));
                } catch (err) {
                    console.warn('Failed to persist overlay edits', err);
                }
            }

            function buildOverlayEditRecordFromSavedPromotedAnnotation(annotationData) {
                const annotation = buildTextAnnotationFromSavedState(annotationData);
                if (!annotation?.promotedFromExtraction || !annotation?.promotedSourceKey) {
                    return null;
                }

                const sourceMeta = getPromotedAnnotationSourceMeta(annotation) || {};
                const pageNumber = Number(annotation.promotedSourcePage) || ((Number(annotation.pageIndex) || 0) + 1);
                const sourcePageHeight = Number(sourceMeta.sourcePageHeight)
                    || (Array.isArray(overlayExtractionData)
                        ? (overlayExtractionData.find((page) => Number(page?.page_number) === pageNumber)?.height || 0)
                        : 0);
                const pdfWidth = Math.max(0, Number(annotation.pdfWidth) || 0);
                const pdfHeight = Math.max(0, Number(annotation.pdfHeight) || 0);
                const pdfX = Number(annotation.pdfX) || 0;
                const pdfY = Number(annotation.pdfY) || 0;
                const pdfTop = sourcePageHeight > 0
                    ? Math.max(0, sourcePageHeight - (pdfY + pdfHeight))
                    : Math.max(0, Number(sourceMeta.sourceBlockTop) || 0);
                const bbox = [pdfX, pdfTop, pdfX + pdfWidth, pdfTop + pdfHeight];

                const sourceLeft = Number(sourceMeta.sourceBlockLeft);
                const sourceTop = Number(sourceMeta.sourceBlockTop);
                const sourceWidth = Number(sourceMeta.sourceBlockWidth);
                const sourceHeight = Number(sourceMeta.sourceBlockHeight);
                const originalBbox = [
                    Number.isFinite(sourceLeft) ? sourceLeft : bbox[0],
                    Number.isFinite(sourceTop) ? sourceTop : bbox[1],
                    Number.isFinite(sourceLeft) && Number.isFinite(sourceWidth) ? (sourceLeft + sourceWidth) : bbox[2],
                    Number.isFinite(sourceTop) && Number.isFinite(sourceHeight) ? (sourceTop + sourceHeight) : bbox[3],
                ];

                return {
                    key: String(annotation.promotedSourceKey),
                    value: {
                        page_number: pageNumber,
                        block_num: Number(annotation.promotedSourceBlockNum) || undefined,
                        original_text: String(annotation.originalText || annotation.text || ''),
                        new_text: String(annotation.text || ''),
                        rich_html: typeof annotation.richTextHtml === 'string' ? annotation.richTextHtml : null,
                        bbox,
                        original_bbox: originalBbox,
                        origin_x: bbox[0],
                        origin_y: bbox[3],
                        font: String(annotation.fontSourceName || annotation.fontFamily || 'Helvetica'),
                        font_size: Number(annotation.fontSize) || 12,
                        font_weight: String(annotation.fontWeight || '400'),
                        font_style: String(annotation.fontStyle || 'normal'),
                        underline: Boolean(annotation.underline),
                        line_height: Number(annotation.lineHeight) || null,
                        color: annotation.textColor || '#000000',
                        background_color: annotation.backgroundColor && annotation.backgroundColor !== 'transparent'
                            ? annotation.backgroundColor
                            : null,
                        annotation_id: String(annotation.id || ''),
                        promoted_source_key: String(annotation.promotedSourceKey || ''),
                    },
                };
            }

            async function mergeBoundingBoxAnnotationStateIntoOverlayEdits() {
                if (!boundingBoxEditMode) {
                    return;
                }

                try {
                    const { promotedSavedAnnotations } = await loadSavedTextAnnotationsFromDatabase();
                    (Array.isArray(promotedSavedAnnotations) ? promotedSavedAnnotations : []).forEach((annotationData) => {
                        const built = buildOverlayEditRecordFromSavedPromotedAnnotation(annotationData);
                        if (!built?.key || !built?.value) {
                            return;
                        }
                        if (overlayEditedFields.has(built.key)) {
                            return;
                        }
                        const existing = overlayPersistedEdits.get(built.key) || {};
                        overlayPersistedEdits.set(built.key, {
                            ...clonePlainData(built.value),
                            ...clonePlainData(existing),
                            annotation_id: existing.annotation_id || built.value.annotation_id || '',
                            promoted_source_key: existing.promoted_source_key || built.value.promoted_source_key || built.key,
                        });
                    });
                } catch (error) {
                    console.warn('Failed to load bounding-box annotation state', error);
                }
            }

            async function loadOverlayEdits() {
                overlayEditedFields.clear();
                overlayPersistedEdits.clear();
                clearStaleOverlayEditStorage();
                try {
                    const stored = sessionStorage.getItem(overlayEditsStorageKey);
                    if (!stored) {
                        await mergeBoundingBoxAnnotationStateIntoOverlayEdits();
                        updateUndoRedoButtons();
                        return;
                    }
                    const parsed = JSON.parse(stored);
                    const edits = Array.isArray(parsed)
                        ? parsed
                        : (Array.isArray(parsed?.edits) ? parsed.edits : []);
                    if (!Array.isArray(edits)) {
                        await mergeBoundingBoxAnnotationStateIntoOverlayEdits();
                        updateUndoRedoButtons();
                        return;
                    }
                    edits.forEach((item) => {
                        if (item && item.key && item.value) {
                            overlayEditedFields.set(item.key, item.value);
                            overlayPersistedEdits.set(item.key, clonePlainData(item.value));
                        }
                    });
                    pruneOverlayEditsAgainstExtraction();
                } catch (err) {
                    console.warn('Failed to load overlay edits', err);
                }
                await mergeBoundingBoxAnnotationStateIntoOverlayEdits();
                updateUndoRedoButtons();
            }

            async function persistSingleOverlayEdit(editKey, editData) {
                if (!editKey || !editData) {
                    return { success: false, message: 'Missing overlay edit payload.' };
                }

                if (overlaySaveMode === 'live_save') {
                    return await _executeLiveSave(editKey, editData);
                }

                const edits = [editData].filter((candidate) => isMaterialOverlaySaveEdit(candidate, { honorForceReinsert: true }));
                if (edits.length === 0) {
                    return { success: true, skipped_noop: true };
                }

                const response = await fetch('{{ route("documents.saveEdits", $document) }}', {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'X-Requested-With': 'XMLHttpRequest',
                        'Content-Type': 'application/json',
                        'Accept': 'application/json'
                    },
                    body: JSON.stringify({ edits })
                });

                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result.success) {
                    return {
                        success: false,
                        message: result.error || result.message || `Overlay save failed (${response.status})`,
                    };
                }

                updateSavedEditPreviewLink(result.saved_preview_url || savedEditPreviewUrl);
                return {
                    success: true,
                    saved_preview_url: result.saved_preview_url || savedEditPreviewUrl,
                };
            }

            function buildBoundingBoxAnnotationPayload(field, editKey, editData) {
                if (!field || !editKey || !editData) {
                    return null;
                }

                const bbox = Array.isArray(editData.bbox) && editData.bbox.length >= 4
                    ? editData.bbox.map((value) => Number(value) || 0)
                    : null;
                if (!bbox) {
                    return null;
                }

                const pageNumber = Number(editData.page_number || field.dataset.pageNumber || 0);
                const pageIndex = Math.max(0, pageNumber - 1);
                const pageHeight = Number(field.dataset.pageHeight || 0)
                    || (Array.isArray(overlayExtractionData)
                        ? (overlayExtractionData.find((page) => Number(page?.page_number) === pageNumber)?.height || 0)
                        : 0);
                const left = Number(bbox[0]) || 0;
                const top = Number(bbox[1]) || 0;
                const right = Number(bbox[2]) || left;
                const bottom = Number(bbox[3]) || top;
                const width = Math.max(0, right - left);
                const height = Math.max(0, bottom - top);
                const sourceOriginalText = String(
                    field.dataset.sourceOriginalText
                    || editData.original_text
                    || field.dataset.originalText
                    || ''
                );
                const sourceLeft = Number(field.dataset.sourceOriginalLeft || field.dataset.originalLeft || editData.original_bbox?.[0] || left);
                const sourceTop = Number(field.dataset.sourceOriginalTop || field.dataset.originalTop || editData.original_bbox?.[1] || top);
                const sourceWidth = Number(field.dataset.sourceOriginalWidth || field.dataset.originalWidth || ((editData.original_bbox?.[2] ?? left) - (editData.original_bbox?.[0] ?? left)) || width);
                const sourceHeight = Number(field.dataset.sourceOriginalHeight || field.dataset.originalHeight || ((editData.original_bbox?.[3] ?? top) - (editData.original_bbox?.[1] ?? top)) || height);
                const sourceBlock = field._overlaySourceBlock || null;
                const backgroundColor = colorToHex(
                    editData.background_color
                    || field.dataset.backgroundColor
                    || '#ffffff'
                );
                const annotation = {
                    id: String(field.dataset.annotationId || editData.annotation_id || `bbox_${String(editKey).replace(/[^a-z0-9_-]+/gi, '_')}`),
                    type: 'text',
                    text: String(editData.new_text ?? ''),
                    originalText: sourceOriginalText,
                    pageIndex,
                    pdfX: left,
                    pdfY: pageHeight > 0 ? Math.max(0, pageHeight - bottom) : Math.max(0, Number(editData.origin_y || bottom) - height),
                    pdfWidth: width,
                    pdfHeight: height,
                    keepBounds: true,
                    fontSize: Number(editData.font_size) || 12,
                    fontFamily: normalizePdfEditableFontFamily(editData.font || field.dataset.font || 'Helvetica')
                        || normalizeBuiltinAnnotationFontFamily(editData.font || field.dataset.font || 'Helvetica'),
                    fontSourceName: String(field.dataset.embeddedFontName || editData.font || field.dataset.font || ''),
                    lineHeight: Number(editData.line_height) || null,
                    textColor: editData.color || field.dataset.textColor || '#000000',
                    backgroundColor: backgroundColor && backgroundColor !== 'transparent' ? backgroundColor : '#ffffff',
                    fontWeight: String(editData.font_weight || field.dataset.fontWeight || '400'),
                    fontStyle: String(editData.font_style || field.dataset.fontStyle || 'normal'),
                    underline: Boolean(editData.underline),
                    textAlign: 'left',
                    opacity: 1,
                    rotation: 0,
                    promotedFromExtraction: true,
                    promotedDirty: true,
                    promotedSourceKey: String(editKey),
                    promotedSourceBlockNum: Number(editData.block_num || field.dataset.blockNum || 0),
                    promotedSourcePage: pageNumber,
                    richTextHtml: typeof editData.rich_html === 'string' ? editData.rich_html : '',
                };

                setPromotedAnnotationSourceMeta(annotation, {
                    sourceBlockLeft: sourceLeft,
                    sourceBlockTop: sourceTop,
                    sourceBlockWidth: sourceWidth,
                    sourceBlockHeight: sourceHeight,
                    sourcePageHeight: pageHeight,
                    sourceTextLines: Array.isArray(sourceBlock?.text_lines) && sourceBlock.text_lines.length
                        ? sourceBlock.text_lines.map((line) => sanitizePromotedExtractionLine(line))
                        : sourceOriginalText.split('\n').map((line) => sanitizePromotedExtractionLine(line)).filter((line) => line.length > 0),
                    sourceLineBBoxes: Array.isArray(sourceBlock?.line_bboxes)
                        ? sourceBlock.line_bboxes
                            .filter((bboxEntry) => Array.isArray(bboxEntry) && bboxEntry.length >= 4)
                            .map((bboxEntry) => bboxEntry.map((value) => Number(value) || 0))
                        : (Array.isArray(editData.original_bbox) && editData.original_bbox.length >= 4
                            ? [editData.original_bbox.map((value) => Number(value) || 0)]
                            : []),
                    sourceSpans: Array.isArray(sourceBlock?.spans)
                        ? sourceBlock.spans
                            .filter((span) => span && Array.isArray(span.bbox) && span.bbox.length >= 4)
                            .map((span) => ({
                                ...span,
                                bbox: span.bbox.map((value) => Number(value) || 0),
                            }))
                        : [],
                });

                return stripInternalAnnotationFields(annotation);
            }

            async function persistSingleBoundingBoxAnnotation(field, editKey, editData) {
                const annotationPayload = buildBoundingBoxAnnotationPayload(field, editKey, editData);
                if (!annotationPayload) {
                    return { success: false, message: 'Failed to build bounding-box annotation payload.' };
                }

                const sessionId = getStoredPdfSessionId() || generateSessionId();
                setStoredPdfSessionId(sessionId);

                const response = await fetch('{{ route("documents.saveAnnotations", $document) }}', {
                    method: 'POST',
                    credentials: 'same-origin',
                    headers: {
                        'X-CSRF-TOKEN': csrfToken,
                        'X-Requested-With': 'XMLHttpRequest',
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                    },
                    body: JSON.stringify({
                        annotations: [annotationPayload],
                        session_id: sessionId,
                        user_email: null,
                        annotation_id: annotationPayload.id,
                    }),
                });

                const result = await response.json().catch(() => ({}));
                if (!response.ok || !result.success) {
                    return {
                        success: false,
                        message: result.error || result.message || `Bounding-box annotation save failed (${response.status})`,
                    };
                }

                const savedAnnotation = result.annotation && typeof result.annotation === 'object'
                    ? result.annotation
                    : annotationPayload;
                const overlayRecord = buildOverlayEditRecordFromSavedPromotedAnnotation(savedAnnotation);

                return {
                    success: true,
                    annotation: savedAnnotation,
                    overlayEdit: overlayRecord?.value || {
                        ...clonePlainData(editData),
                        annotation_id: annotationPayload.id,
                        promoted_source_key: editKey,
                    },
                };
            }

            function updateOverlayFieldOriginalStateFromEdit(field, editData) {
                if (!field || !editData) {
                    return;
                }

                const nextText = String(editData.new_text ?? '');
                field.dataset.originalText = nextText;
                field.dataset.hasPersistedEdit = nextText.trim() !== '' ? '1' : '0';
                if (boundingBoxEditMode && field.dataset.layoutMode === 'bounding_box_edit' && field.dataset.hasPersistedEdit === '1') {
                    delete field.dataset.exactGeometry;
                }

                const nextBBox = Array.isArray(editData.bbox) && editData.bbox.length >= 4
                    ? editData.bbox.map((value) => Number(value))
                    : null;
                const nextPdfX = Number(editData.pdf_x ?? nextBBox?.[0]);
                const nextPdfY = Number(editData.pdf_y ?? nextBBox?.[1]);
                const nextPdfWidth = Number(editData.pdf_width ?? ((nextBBox?.[2] ?? 0) - (nextBBox?.[0] ?? 0)));
                const nextPdfHeight = Number(editData.pdf_height ?? ((nextBBox?.[3] ?? 0) - (nextBBox?.[1] ?? 0)));
                if (Number.isFinite(nextPdfX)) field.dataset.originalLeft = String(nextPdfX);
                if (Number.isFinite(nextPdfY)) field.dataset.originalTop = String(nextPdfY);
                if (Number.isFinite(nextPdfWidth)) field.dataset.originalWidth = String(nextPdfWidth);
                if (Number.isFinite(nextPdfHeight)) field.dataset.originalHeight = String(nextPdfHeight);
                if (Number.isFinite(Number(editData.origin_x))) field.dataset.originalOriginX = String(editData.origin_x);
                if (Number.isFinite(Number(editData.origin_y))) field.dataset.originalOriginY = String(editData.origin_y);
                if (editData.annotation_id) field.dataset.annotationId = String(editData.annotation_id);
                const nextBackgroundColor = colorToHex(editData.background_color || 'transparent');
                if (nextBackgroundColor && nextBackgroundColor !== 'transparent') {
                    field.dataset.backgroundColor = nextBackgroundColor;
                } else {
                    delete field.dataset.backgroundColor;
                }
                syncBoundingBoxFieldMaskState(field);
            }

            function upsertBoundingBoxAnnotationIntoLocalState(annotationData) {
                const annotation = buildTextAnnotationFromSavedState(annotationData);
                if (!annotation?.promotedFromExtraction || !annotation?.promotedSourceKey) {
                    return;
                }

                annotation.promotedDirty = true;
                const sourceKey = String(annotation.promotedSourceKey || '');
                const existingIndex = annotations.findIndex((candidate) => (
                    candidate?.promotedFromExtraction
                    && String(candidate?.promotedSourceKey || '') === sourceKey
                ));

                if (existingIndex >= 0) {
                    const existingAnnotation = annotations[existingIndex];
                    if (existingAnnotation?.element?.parentNode) {
                        existingAnnotation.element.parentNode.removeChild(existingAnnotation.element);
                    }
                    annotations.splice(existingIndex, 1, annotation);
                } else {
                    registerAnnotationId(annotation);
                    annotations.push(annotation);
                }

                persistAnnotations();
                updateAnnotationsList();
            }

            async function persistBoundingBoxFieldIfNeeded(field) {
                if (!boundingBoxEditMode || !field) {
                    return;
                }

                const editKey = String(field.dataset.wordIndex || '');
                if (!editKey || field.dataset.persisting === '1') {
                    return;
                }

                const editData = overlayEditedFields.get(editKey);
                if (!editData) {
                    field.dataset.hasPersistedEdit = overlayPersistedEdits.has(editKey) ? '1' : '0';
                    syncBoundingBoxFieldMaskState(field);
                    return;
                }

                field.dataset.persisting = '1';
                field.dataset.liveSaveState = 'saving';
                syncBoundingBoxFieldMaskState(field);
                updateOverlaySaveButton();

                try {
                    const result = await persistSingleBoundingBoxAnnotation(field, editKey, editData);
                    if (!result?.success) {
                        field.dataset.liveSaveState = 'error';
                        syncBoundingBoxFieldMaskState(field);
                        setStatus(result?.message || 'Failed to persist text box.', 'err');
                        return;
                    }

                    const persistedEdit = result?.overlayEdit
                        ? clonePlainData(result.overlayEdit)
                        : clonePlainData(editData);
                    overlayPersistedEdits.set(editKey, persistedEdit);
                    overlayEditedFields.delete(editKey);
                    _liveSavedKeys.add(editKey);
                    field.dataset.liveSaveState = 'saved';
                    updateOverlayFieldOriginalStateFromEdit(field, persistedEdit);
                    upsertBoundingBoxAnnotationIntoLocalState(result.annotation || buildBoundingBoxAnnotationPayload(field, editKey, persistedEdit));
                    persistOverlayEdits();
                    updateOverlaySaveButton();
                    setStatus('Text box saved.', 'ok');
                } catch (error) {
                    field.dataset.liveSaveState = 'error';
                    syncBoundingBoxFieldMaskState(field);
                    setStatus(error?.message || 'Failed to persist text box.', 'err');
                } finally {
                    delete field.dataset.persisting;
                    syncBoundingBoxFieldMaskState(field);
                }
            }
            const ZOOM_MIN_PERCENT = 50;
            const ZOOM_MAX_PERCENT = 400;
            const ZOOM_STEP_PERCENT = 30;

            const updateZoom = (value) => {
                const zoomValue = Math.max(ZOOM_MIN_PERCENT, Math.min(ZOOM_MAX_PERCENT, parseInt(value, 10)));
                zoomLabel.textContent = zoomValue + '%';
                currentScale = baseScale * (zoomValue / 100);

                // Check if AI tab is active — zoom generated pages in #ai-viewer
                const aiTab = document.getElementById('extracted-text');
                if (aiTab && aiTab.style.display !== 'none') {
                    const aiViewer = document.getElementById('ai-viewer');
                    if (aiViewer) {
                        const scaleFactor = zoomValue / 100;
                        aiViewer.querySelectorAll('.generated-page').forEach(page => {
                            page.style.transform = `scale(${scaleFactor})`;
                            page.style.transformOrigin = 'top center';
                        });
                    }
                    return;
                }

                if (overlayEditorActive && overlayExtractionData) {
                    renderPdfWithOverlay(true);
                } else {
                    rerenderPdf();
                }
                updateSelectionBar();
            };

            const scrollToPage = (pageNumber) => {
                const clamped = Math.max(1, Math.min(totalPages || 1, pageNumber));
                if (pageJumpInput) {
                    pageJumpInput.value = clamped;
                }
                const target = viewer.querySelector(
                    `.page[data-page-index="${clamped - 1}"], .overlay-page[data-page-number="${clamped}"]`
                );
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            };

            const updatePageControls = () => {
                if (pageTotalLabel) {
                    pageTotalLabel.textContent = String(totalPages || 1);
                }
                if (pageJumpInput) {
                    pageJumpInput.max = String(totalPages || 1);
                    if (!pageJumpInput.value || parseInt(pageJumpInput.value, 10) > (totalPages || 1)) {
                        pageJumpInput.value = '1';
                    }
                }
            };

            const syncCurrentPageFromScroll = () => {
                if (!viewer || !pageJumpInput) return;
                const pages = viewer.querySelectorAll('.page[data-page-index], .overlay-page[data-page-number]');
                if (!pages.length) return;
                const viewerRect = viewer.getBoundingClientRect();
                let bestPage = null;
                let bestOverlap = -Infinity;
                for (const page of pages) {
                    const rect = page.getBoundingClientRect();
                    const overlapTop = Math.max(rect.top, viewerRect.top);
                    const overlapBottom = Math.min(rect.bottom, viewerRect.bottom);
                    const overlap = overlapBottom - overlapTop;
                    if (overlap > bestOverlap) {
                        bestOverlap = overlap;
                        bestPage = page;
                    }
                }
                if (bestPage) {
                    const pageNum = bestPage.dataset.pageNumber
                        ? parseInt(bestPage.dataset.pageNumber, 10)
                        : parseInt(bestPage.dataset.pageIndex, 10) + 1;
                    if (Number.isFinite(pageNum) && String(pageNum) !== pageJumpInput.value) {
                        pageJumpInput.value = String(pageNum);
                    }
                }
            };

            if (zoomOutBtn) {
                zoomOutBtn.addEventListener('click', () => updateZoom(Math.round((currentScale / baseScale) * 100) - ZOOM_STEP_PERCENT));
            }
            if (zoomInBtn) {
                zoomInBtn.addEventListener('click', () => updateZoom(Math.round((currentScale / baseScale) * 100) + ZOOM_STEP_PERCENT));
            }
            if (pageJumpInput) {
                pageJumpInput.addEventListener('change', () => {
                    const value = parseInt(pageJumpInput.value || '1', 10);
                    if (Number.isFinite(value)) {
                        scrollToPage(value);
                    }
                });
                pageJumpInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') {
                        const value = parseInt(pageJumpInput.value || '1', 10);
                        if (Number.isFinite(value)) {
                            scrollToPage(value);
                        }
                    }
                });
            }
            if (pagePrevBtn) {
                pagePrevBtn.addEventListener('click', () => {
                    const current = parseInt(pageJumpInput?.value || '1', 10) || 1;
                    scrollToPage(current - 1);
                });
            }
            if (pageNextBtn) {
                pageNextBtn.addEventListener('click', () => {
                    const current = parseInt(pageJumpInput?.value || '1', 10) || 1;
                    scrollToPage(current + 1);
                });
            }

            (async () => {
                showDocumentLoadingScreen('Loading document...');
                updateDocumentLoadingProgress(8, 'Loading document...');
                // If we have a session ID from the URL but haven't entered loadedSavedPdfMode
                // yet, redirect there. This covers old ?savedSession=...&savedSessionMaterialized=1
                // URLs and any other entry point. We never stamp annotations into document.path.
                if (savedSessionFromUrl && !loadedSavedPdfMode) {
                    try {
                        sessionStorage.removeItem(annotationsStorageKey);
                        sessionStorage.removeItem(overlayEditsStorageKey);
                    } catch (_) {}
                    const dest = new URL(window.location.pathname, window.location.origin);
                    dest.searchParams.set('loadedSavedPdf', '1');
                    dest.searchParams.set('savedSession', savedSessionFromUrl);
                    window.location.replace(dest.toString());
                    return;
                }
                // In loadedSavedPdfMode, bootstrapPromotedTextAnnotations loads all
                // annotations (shapes + text) from DB — skip sessionStorage load.
                if (!loadedSavedPdfMode) {
                    loadAnnotationsFromStorage();
                }
                updateDocumentLoadingProgress(18, 'Restoring editor state...');
                const overlayChipEl = document.getElementById('mode-overlay-chip');
                if (overlayChipEl && (!overlayEditorEnabled || promotedTextAnnotationsEnabled)) {
                    overlayChipEl.style.display = 'none';
                }
                if (!overlayEditorEnabled) {
                    overlayEditedFields.clear();
                    overlayPersistedEdits.clear();
                    try {
                        sessionStorage.removeItem(overlayEditsStorageKey);
                    } catch (storageError) {
                        console.warn('Failed to clear disabled overlay editor state', storageError);
                    }
                }
                if (!isImageDocument && promotedTextAnnotationsEnabled) {
                    try {
                        setStatus('Preparing editable text boxes...', 'loading');
                        updateDocumentLoadingProgress(34, 'Preparing editable text...');
                        await bootstrapPromotedTextAnnotations();
                        await restoreUnhydratedStoredLocalAnnotations({ rehydratePromoted: true });
                        updateDocumentLoadingProgress(58, 'Applying annotations...');
                    } catch (error) {
                        console.warn('Failed to promote extracted text into annotations', error);
                        basePdfUrl = loadedSavedPdfMode ? cleanPdfUrl : pdfUrl;
                        pdfVersion = Date.now();
                    }
                }
                updateAnnotationsList(); // Populate annotations panel with loaded annotations
                if (!isImageDocument) {
                    loadOriginalPdfBytes().catch((err) => {
                        console.warn('Failed to cache original PDF bytes', err);
                    });
                }
                updateOverlayShowOriginalToggle();
                updateModeButtons();
                updateSelectionBar();
                updateDocumentLoadingProgress(72, 'Rendering document pages...');

                if (boundingBoxEditMode && !isImageDocument) {
                    overlayToggleHandler(true)
                        .then(() => resumePendingDownloadAfterSaveIfNeeded())
                        .catch((error) => {
                            if (isPdfJsRenderingCancelledError(error)) {
                                console.debug('Initial bounding-box render cancelled by a newer render', error);
                                return;
                            }
                            hideDocumentLoadingScreen({ immediate: true });
                            console.error('Initial bounding-box render failed', error);
                            setStatus('Failed to load positioned annotation editor.', 'err');
                        });
                    return;
                }

                renderPdf()
                    .then(async () => {
                        if (layoutMode === 'new_writer') {
                            await flushAllAnnotationsForNewWriter();
                        }
                        return resumePendingDownloadAfterSaveIfNeeded();
                    })
                    .catch((error) => {
                        if (isPdfJsRenderingCancelledError(error)) {
                            console.debug('Initial renderPdf cancelled by a newer render', error);
                            return;
                        }
                        hideDocumentLoadingScreen({ immediate: true });
                        console.error('Initial renderPdf failed', error);
                        setStatus(isImageDocument ? 'Failed to load image.' : 'Failed to load PDF.', 'err');
                    });
            })();

            // Page navigation (separate pages instead of tabs)
            let aiViewerRendered = false;
            
            const pdfModeBar = document.getElementById('pdf-mode-bar');
            const selectionToolbar = document.getElementById('selection-toolbar');
            const guidedWaitingOverlay = document.getElementById('guided-waiting-overlay');
            const floatingZoomBar = document.getElementById('floating-zoom-bar');
            const pdfEditorContent = document.querySelector('#pdf-editor > .flex');
            const sidebarEl = document.getElementById('sidebar');
            const editTextBanner = document.getElementById('edit-text-banner');
            const pageHeader = document.querySelector('header');

            // Track whether guided mode is engaged (hides the PDF viewer)
            let guidedModeActive = false;

            function syncPdfStickyTopOffset() {
                const headerRect = pageHeader?.getBoundingClientRect?.();
                if (!headerRect || headerRect.height <= 0) {
                    return;
                }
                const nextTop = Math.max(0, Math.round(headerRect.bottom));
                document.documentElement.style.setProperty('--pdf-sticky-top', `${nextTop}px`);
            }

            syncPdfStickyTopOffset();
            window.addEventListener('resize', syncPdfStickyTopOffset, { passive: true });
            window.addEventListener('load', syncPdfStickyTopOffset);
            if (window.ResizeObserver && pageHeader) {
                const stickyHeaderObserver = new ResizeObserver(() => {
                    syncPdfStickyTopOffset();
                });
                stickyHeaderObserver.observe(pageHeader);
            }

            function setGuidedOverlay(show) {
                guidedModeActive = show;
                if (guidedWaitingOverlay) {
                    guidedWaitingOverlay.style.display = show ? 'flex' : 'none';
                }
                if (pdfEditorContent) {
                    pdfEditorContent.style.display = show ? 'none' : '';
                }
                if (floatingZoomBar) {
                    floatingZoomBar.style.display = show ? 'none' : '';
                }
            }

            // Auto-init: if on AI page, load sections
            const _currentTab = @json($activeTab ?? 'pdf-editor');
            if (_currentTab === 'extracted-text') {
                aiViewerRendered = true;
                loadSectionsFromDatabase();
            }
            // Auto-init: hide editor toolbars on non-editor pages
            if (_currentTab !== 'pdf-editor') {
                if (pdfModeBar) pdfModeBar.style.display = 'none';
                if (selectionToolbar) selectionToolbar.style.display = 'none';
            }

            if (editTextBanner) {
                window.addEventListener('scroll', syncEditTextBannerStickyOffset, { passive: true });
                window.addEventListener('resize', syncEditTextBannerStickyOffset);
                if (viewer) {
                    viewer.addEventListener('scroll', syncEditTextBannerStickyOffset, { passive: true });
                }
                requestAnimationFrame(syncEditTextBannerStickyOffset);
            }

            window.addEventListener('scroll', queueSelectedAnnotationMenuPlacement, { passive: true });
            window.addEventListener('resize', queueSelectedAnnotationMenuPlacement);
            if (viewer) {
                viewer.addEventListener('scroll', queueSelectedAnnotationMenuPlacement, { passive: true });
                viewer.addEventListener('scroll', syncCurrentPageFromScroll, { passive: true });
            }
            
            async function renderAIViewer() {
                // Function disabled - AI Generator tab doesn't show PDF pages
                return;
            }
            
            // Generate from Template Modal
            const generateFromTemplateBtn = document.getElementById('generate-from-template');
            const templateModal = document.getElementById('generate-from-template-modal');
            const templateModalClose = document.getElementById('template-modal-close');
            const templateModalCancel = document.getElementById('template-modal-cancel');
            const templateModalGenerate = document.getElementById('template-modal-generate');
            const templatePrefabs = document.querySelectorAll('.template-prefab');
            const templateSectionsContainer = document.getElementById('template-sections-container');
            const templateSectionsList = document.getElementById('template-sections-list');
            
            let selectedLayout = null;
            let templateSections = [];
            let builderSections = []; // For custom builder
            
            // Tab switching in modal
            const templateTabs = document.querySelectorAll('[data-template-tab]');
            const templatePanels = document.querySelectorAll('[data-template-panel]');
            
            console.log('Template tabs found:', templateTabs.length);
            console.log('Template panels found:', templatePanels.length);
            
            templateTabs.forEach(tab => {
                tab.addEventListener('click', () => {
                    const targetPanel = tab.dataset.templateTab;
                    
                    console.log('Tab clicked:', targetPanel);
                    
                    // Update tabs
                    templateTabs.forEach(t => t.classList.remove('active'));
                    tab.classList.add('active');
                    
                    // Update panels
                    templatePanels.forEach(p => {
                        p.classList.remove('active');
                        console.log('Removed active from panel:', p.dataset.templatePanel);
                    });
                    const targetPanelEl = document.querySelector(`[data-template-panel="${targetPanel}"]`);
                    if (targetPanelEl) {
                        targetPanelEl.classList.add('active');
                        console.log('Added active to panel:', targetPanel);
                    } else {
                        console.error('Could not find panel:', targetPanel);
                    }
                    
                    // Update generate button state after a brief delay to ensure DOM is updated
                    setTimeout(() => {
                        updateGenerateButton();
                    }, 10);
                });
            });
            
            if (generateFromTemplateBtn) {
                generateFromTemplateBtn.addEventListener('click', () => {
                    templateModal.style.display = 'flex';
                    document.body.style.overflow = 'hidden';
                });
            }
            
            const closeTemplateModal = () => {
                templateModal.style.display = 'none';
                document.body.style.overflow = '';
                selectedLayout = null;
                templateSections = [];
                builderSections = [];
                templatePrefabs.forEach(p => p.classList.remove('selected'));
                templateSectionsContainer.style.display = 'none';
                templateSectionsList.innerHTML = '';
                clearBuilderCanvas();
                templateModalGenerate.disabled = true;
                
                // Reset to prefabs tab
                templateTabs.forEach(t => t.classList.remove('active'));
                templateTabs[0].classList.add('active');
                templatePanels.forEach(p => p.classList.remove('active'));
                templatePanels[0].classList.add('active');
            };
            
            if (templateModalClose) {
                templateModalClose.addEventListener('click', closeTemplateModal);
            }
            if (templateModalCancel) {
                templateModalCancel.addEventListener('click', closeTemplateModal);
            }
            
            // Handle prefab selection
            templatePrefabs.forEach(prefab => {
                prefab.addEventListener('click', () => {
                    const layout = prefab.dataset.layout;
                    templatePrefabs.forEach(p => p.classList.remove('selected'));
                    prefab.classList.add('selected');
                    selectedLayout = layout;
                    
                    templateSections = getLayoutSections(layout);
                    renderTemplateSections();
                    templateSectionsContainer.style.display = 'block';
                    templateModalGenerate.disabled = false;
                });
            });
            
            function getLayoutSections(layout) {
                const sectionTypes = {
                    title: { name: 'Title', icon: '📄', defaultHeight: 10, defaultWidth: 100, defaultX: 0, defaultY: 0 },
                    paragraph: { name: 'Paragraph', icon: '📝', defaultHeight: 20, defaultWidth: 100, defaultX: 0, defaultY: 0 },
                    chart: { name: 'Chart', icon: '📊', defaultHeight: 30, defaultWidth: 50, defaultX: 0, defaultY: 0 },
                    graphic: { name: 'Graphic', icon: '🖼️', defaultHeight: 30, defaultWidth: 50, defaultX: 0, defaultY: 0 }
                };
                
                const layouts = {
                    'title-abstract-body': [
                        { type: 'title', height: 10, ...sectionTypes.title },
                        { type: 'paragraph', height: 20, ...sectionTypes.paragraph, name: 'Abstract' },
                        { type: 'paragraph', height: 70, ...sectionTypes.paragraph, name: 'Body' }
                    ],
                    'intro-body-conclusion': [
                        { type: 'paragraph', height: 20, ...sectionTypes.paragraph, name: 'Introduction' },
                        { type: 'paragraph', height: 60, ...sectionTypes.paragraph, name: 'Body' },
                        { type: 'paragraph', height: 20, ...sectionTypes.paragraph, name: 'Conclusion' }
                    ],
                    'full-body-references': [
                        { type: 'paragraph', height: 80, ...sectionTypes.paragraph, name: 'Body Content' },
                        { type: 'paragraph', height: 20, ...sectionTypes.paragraph, name: 'References' }
                    ],
                    'methods-results': [
                        { type: 'chart', height: 50, ...sectionTypes.chart, name: 'Methods' },
                        { type: 'chart', height: 50, ...sectionTypes.chart, name: 'Results' }
                    ],
                    'full-document': [
                        { type: 'title', height: 8, ...sectionTypes.title },
                        { type: 'paragraph', height: 12, ...sectionTypes.paragraph, name: 'Abstract' },
                        { type: 'paragraph', height: 15, ...sectionTypes.paragraph, name: 'Introduction' },
                        { type: 'paragraph', height: 40, ...sectionTypes.paragraph, name: 'Body' },
                        { type: 'paragraph', height: 15, ...sectionTypes.paragraph, name: 'Conclusion' },
                        { type: 'graphic', height: 10, ...sectionTypes.graphic, name: 'References' }
                    ],
                    // Multi-column layouts
                    'two-column': [
                        { type: 'title', height: 10, ...sectionTypes.title, defaultWidth: 100, defaultX: 0 },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 48, defaultX: 1, name: 'Left Column' },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 48, defaultX: 51, name: 'Right Column' }
                    ],
                    'two-column-image': [
                        { type: 'title', height: 10, ...sectionTypes.title, defaultWidth: 100, defaultX: 0 },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 55, defaultX: 1, name: 'Text Column' },
                        { type: 'graphic', height: 90, ...sectionTypes.graphic, defaultWidth: 42, defaultX: 57, name: 'Image' }
                    ],
                    'three-column': [
                        { type: 'title', height: 10, ...sectionTypes.title, defaultWidth: 100, defaultX: 0 },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 31, defaultX: 1, name: 'Column 1' },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 31, defaultX: 34, name: 'Column 2' },
                        { type: 'paragraph', height: 90, ...sectionTypes.paragraph, defaultWidth: 31, defaultX: 67, name: 'Column 3' }
                    ],
                    'image-gallery': [
                        { type: 'title', height: 10, ...sectionTypes.title, defaultWidth: 100, defaultX: 0 },
                        { type: 'graphic', height: 43, ...sectionTypes.graphic, defaultWidth: 48, defaultX: 1, name: 'Image 1' },
                        { type: 'graphic', height: 43, ...sectionTypes.graphic, defaultWidth: 48, defaultX: 51, name: 'Image 2' },
                        { type: 'graphic', height: 43, ...sectionTypes.graphic, defaultWidth: 48, defaultX: 1, name: 'Image 3' },
                        { type: 'graphic', height: 43, ...sectionTypes.graphic, defaultWidth: 48, defaultX: 51, name: 'Image 4' }
                    ],
                    'hero-image': [
                        { type: 'graphic', height: 50, ...sectionTypes.graphic, defaultWidth: 100, defaultX: 0, name: 'Hero Image' },
                        { type: 'title', height: 10, ...sectionTypes.title, defaultWidth: 100, defaultX: 0 },
                        { type: 'paragraph', height: 40, ...sectionTypes.paragraph, defaultWidth: 100, defaultX: 0, name: 'Description' }
                    ],
                    'sidebar-layout': [
                        { type: 'paragraph', height: 100, ...sectionTypes.paragraph, defaultWidth: 68, defaultX: 0, name: 'Main Content' },
                        { type: 'graphic', height: 40, ...sectionTypes.graphic, defaultWidth: 28, defaultX: 71, name: 'Sidebar Image' },
                        { type: 'paragraph', height: 55, ...sectionTypes.paragraph, defaultWidth: 28, defaultX: 71, name: 'Sidebar Text' }
                    ]
                };
                
                const sections = layouts[layout] || [];
                
                // Compute cumulative Y positions for stacked sections
                // Sections sharing same row (overlapping X ranges at same Y) are side-by-side (columns)
                return computeSectionPositions(sections);
            }
            
            // Compute proper Y positions for sections - stacked sections get cumulative Y
            function computeSectionPositions(sections) {
                if (sections.length === 0) return sections;
                
                // Check if this is a multi-column layout (sections have explicit non-zero defaultX)
                const hasExplicitPositions = sections.some(s => s.defaultX > 0);
                
                if (hasExplicitPositions) {
                    // For multi-column layouts, compute Y positions for stacked groups
                    // Group sections by their column (X range)
                    const processed = [];
                    const columnTracker = {}; // Track Y offset per column
                    
                    sections.forEach(section => {
                        const x = section.defaultX || 0;
                        const w = section.defaultWidth || 100;
                        const colKey = `${x}-${w}`;
                        
                        if (columnTracker[colKey] === undefined) {
                            // First section in this column - find existing Y from previous full-width row
                            const fullWidthY = processed
                                .filter(s => (s.defaultWidth || 100) >= 95 && s.defaultX <= 2)
                                .reduce((acc, s) => acc + s.height, 0);
                            columnTracker[colKey] = fullWidthY;
                        }
                        
                        const computedSection = { ...section, defaultY: columnTracker[colKey] };
                        columnTracker[colKey] += section.height;
                        processed.push(computedSection);
                    });
                    
                    return processed;
                } else {
                    // Simple stacked layout - accumulate Y positions
                    let cumulativeY = 0;
                    return sections.map(section => {
                        const result = { ...section, defaultY: cumulativeY };
                        cumulativeY += section.height;
                        return result;
                    });
                }
            }
            
            function renderTemplateSections() {
                templateSectionsList.innerHTML = '';
                templateSections.forEach((section, index) => {
                    const sectionEl = document.createElement('div');
                    sectionEl.className = 'template-section';
                    sectionEl.style.cssText = 'display: flex; align-items: center; gap: 12px; padding: 12px; background: rgba(255,255,255,0.08); border-radius: 8px; margin-bottom: 8px;';
                    sectionEl.innerHTML = `
                        <span style="font-size: 20px;">${section.icon}</span>
                        <span style="font-weight: 600; min-width: 100px; color: #f3f4f6;">${section.name}</span>
                        <input type="number" value="${section.height}" min="5" max="100" 
                               onchange="templateSections[${index}].height = parseInt(this.value)" 
                               style="width: 80px; padding: 6px 10px; border: 1px solid rgba(255,255,255,0.2); border-radius: 6px; background: rgba(255,255,255,0.05); color: #111827;"
                               placeholder="Height %">
                        <span style="font-size: 12px; color: #9ca3af;">%</span>
                    `;
                    templateSectionsList.appendChild(sectionEl);
                });
            }
            
            // Custom Builder - Visual Page Preview with Column Drop Zones
            const sectionBlocksPalette = document.getElementById('section-blocks-palette');
            const pageBuilderCanvas = document.getElementById('page-builder-canvas');
            const builderEmptyState = document.getElementById('builder-empty-state');
            const builderClearBtn = document.getElementById('builder-clear-btn');
            
            let draggedBlock = null;
            let draggedCanvasSection = null;
            let builderColumnLayout = null; // Track current column layout: null, '1col', '2col', '3col'
            let builderColumnZones = []; // Column zone definitions
            
            // Section type colors for visual distinction
            const sectionColors = {
                title: { bg: 'rgba(59,130,246,0.12)', border: 'rgba(59,130,246,0.5)', accent: '#3b82f6' },
                paragraph: { bg: 'rgba(16,185,129,0.12)', border: 'rgba(16,185,129,0.5)', accent: '#10b981' },
                chart: { bg: 'rgba(139,92,246,0.12)', border: 'rgba(139,92,246,0.5)', accent: '#8b5cf6' },
                graphic: { bg: 'rgba(245,158,11,0.12)', border: 'rgba(245,158,11,0.5)', accent: '#f59e0b' }
            };
            
            // Column zone definitions for each layout
            function getColumnZones(layout) {
                if (layout === '1col') {
                    return [
                        { id: 'col-0', label: 'Content', x: 0, y: 10, width: 100, height: 90 }
                    ];
                } else if (layout === '2col') {
                    return [
                        { id: 'col-0', label: 'Left', x: 1, y: 10, width: 48, height: 90 },
                        { id: 'col-1', label: 'Right', x: 51, y: 10, width: 48, height: 90 }
                    ];
                } else if (layout === '3col') {
                    return [
                        { id: 'col-0', label: 'Column 1', x: 1, y: 10, width: 31, height: 90 },
                        { id: 'col-1', label: 'Column 2', x: 34, y: 10, width: 31, height: 90 },
                        { id: 'col-2', label: 'Column 3', x: 67, y: 10, width: 31, height: 90 }
                    ];
                }
                return [];
            }
            
            // Render column drop zones on the canvas (visual guides only)
            function renderColumnZones() {
                // Remove existing zones
                pageBuilderCanvas.querySelectorAll('.column-drop-zone').forEach(z => z.remove());
                
                if (!builderColumnLayout) return;
                
                builderColumnZones = getColumnZones(builderColumnLayout);
                
                builderColumnZones.forEach((zone, i) => {
                    const zoneEl = document.createElement('div');
                    zoneEl.className = 'column-drop-zone';
                    zoneEl.dataset.colIndex = i;
                    zoneEl.style.cssText = `
                        position: absolute;
                        left: ${zone.x}%;
                        top: ${zone.y}%;
                        width: ${zone.width}%;
                        height: ${zone.height}%;
                        border: 2px dashed rgba(148, 163, 184, 0.35);
                        border-radius: 6px;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        transition: all 0.2s;
                        pointer-events: auto;
                    `;
                    // Small subtle label
                    zoneEl.innerHTML = `<span style="color: rgba(148,163,184,0.5); font-size: 11px; font-weight: 500; pointer-events: none; user-select: none;">Drop here</span>`;
                    
                    // Drop zone events
                    zoneEl.addEventListener('dragover', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        e.dataTransfer.dropEffect = 'copy';
                        zoneEl.style.borderColor = 'rgba(59,130,246,0.8)';
                        zoneEl.style.background = 'rgba(59,130,246,0.06)';
                    });
                    zoneEl.addEventListener('dragleave', () => {
                        zoneEl.style.borderColor = 'rgba(148, 163, 184, 0.35)';
                        zoneEl.style.background = 'transparent';
                    });
                    zoneEl.addEventListener('drop', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        zoneEl.style.borderColor = 'rgba(148, 163, 184, 0.35)';
                        zoneEl.style.background = 'transparent';
                        
                        if (draggedBlock) {
                            addSectionToColumn(draggedBlock, i);
                        }
                    });
                    
                    pageBuilderCanvas.appendChild(zoneEl);
                });
            }
            
            // Add a section snapped to a specific column zone
            function addSectionToColumn(sectionType, colIndex) {
                const zone = builderColumnZones[colIndex];
                if (!zone) return;
                
                const sectionTypes = {
                    title: { name: 'Title', icon: '📄', defaultHeight: 10 },
                    paragraph: { name: 'Paragraph', icon: '📝', defaultHeight: 20 },
                    chart: { name: 'Chart', icon: '📊', defaultHeight: 25 },
                    graphic: { name: 'Graphic', icon: '🖼️', defaultHeight: 25 }
                };
                
                const sType = sectionTypes[sectionType] || sectionTypes.paragraph;
                
                // Calculate Y position: stack below existing items in this column
                const existingInCol = builderSections.filter(s => s._colIndex === colIndex);
                let nextY = zone.y;
                existingInCol.forEach(s => {
                    nextY = Math.max(nextY, (s.defaultY || 0) + s.defaultHeight);
                });
                if (nextY + sType.defaultHeight > zone.y + zone.height) {
                    nextY = zone.y + zone.height - sType.defaultHeight;
                }
                
                const section = {
                    type: sectionType,
                    name: sType.name,
                    icon: sType.icon,
                    defaultHeight: sType.defaultHeight,
                    defaultWidth: zone.width,
                    defaultX: zone.x,
                    defaultY: nextY,
                    _colIndex: colIndex
                };
                
                builderSections.push(section);
                renderBuilderCanvas();
                updateGenerateButton();
            }
            
            // Make palette blocks draggable
            const sectionBlocks = sectionBlocksPalette.querySelectorAll('.section-block');
            sectionBlocks.forEach(block => {
                block.addEventListener('dragstart', (e) => {
                    draggedBlock = block.dataset.sectionType;
                    e.dataTransfer.effectAllowed = 'copy';
                });
                block.addEventListener('dragend', () => { draggedBlock = null; });
            });
            
            // Canvas-level drop (fallback if not dropped on a specific column zone)
            pageBuilderCanvas.addEventListener('dragover', (e) => {
                e.preventDefault();
                e.dataTransfer.dropEffect = 'copy';
            });
            
            pageBuilderCanvas.addEventListener('drop', (e) => {
                e.preventDefault();
                if (draggedBlock && builderColumnLayout) {
                    // Find closest column zone
                    const rect = pageBuilderCanvas.getBoundingClientRect();
                    const dropXPct = ((e.clientX - rect.left) / rect.width) * 100;
                    let closestCol = 0;
                    let closestDist = Infinity;
                    builderColumnZones.forEach((zone, i) => {
                        const zoneMidX = zone.x + zone.width / 2;
                        const dist = Math.abs(dropXPct - zoneMidX);
                        if (dist < closestDist) { closestDist = dist; closestCol = i; }
                    });
                    addSectionToColumn(draggedBlock, closestCol);
                } else if (draggedBlock) {
                    // No layout selected - add as free-form
                    addSectionToCanvas(draggedBlock);
                }
            });
            
            function addSectionToCanvas(sectionType, dropX, dropY) {
                const sectionTypes = {
                    title: { name: 'Title', icon: '📄', defaultHeight: 10, defaultWidth: 100, defaultX: 0, defaultY: 0 },
                    paragraph: { name: 'Paragraph', icon: '📝', defaultHeight: 20, defaultWidth: 100, defaultX: 0, defaultY: 0 },
                    chart: { name: 'Chart', icon: '📊', defaultHeight: 30, defaultWidth: 50, defaultX: 0, defaultY: 0 },
                    graphic: { name: 'Graphic', icon: '🖼️', defaultHeight: 30, defaultWidth: 50, defaultX: 0, defaultY: 0 }
                };
                
                const section = { type: sectionType, ...sectionTypes[sectionType] };
                
                if (dropX !== undefined && dropY !== undefined) {
                    section.defaultX = Math.max(0, Math.min(dropX - section.defaultWidth / 2, 100 - section.defaultWidth));
                    section.defaultY = Math.max(0, Math.min(dropY - section.defaultHeight / 2, 100 - section.defaultHeight));
                } else {
                    const totalH = builderSections.reduce((sum, s) => Math.max(sum, (s.defaultY || 0) + s.defaultHeight), 0);
                    section.defaultY = Math.min(totalH, 100 - section.defaultHeight);
                }
                
                builderSections.push(section);
                renderBuilderCanvas();
                updateGenerateButton();
            }
            
            function renderBuilderCanvas() {
                // Clear existing sections (keep column zones)
                pageBuilderCanvas.querySelectorAll('.canvas-section').forEach(s => s.remove());
                
                if (builderSections.length === 0 && !builderColumnLayout) {
                    builderEmptyState.style.display = 'flex';
                    return;
                }
                
                builderEmptyState.style.display = 'none';
                
                // Render sections as modern styled blocks
                builderSections.forEach((section, index) => {
                    const colors = sectionColors[section.type] || sectionColors.paragraph;
                    
                    const sectionEl = document.createElement('div');
                    sectionEl.className = 'canvas-section';
                    sectionEl.dataset.index = index;
                    sectionEl.style.cssText = `
                        left: ${section.defaultX || 0}%;
                        top: ${section.defaultY || 0}%;
                        width: ${section.defaultWidth || 100}%;
                        height: ${section.defaultHeight || 20}%;
                        background: ${colors.bg};
                        border-color: ${colors.border};
                        border-width: 2px;
                        border-style: solid;
                    `;
                    
                    sectionEl.innerHTML = `
                        <div class="canvas-section-label" style="display: flex; align-items: center; gap: 6px;">
                            <span class="icon" style="font-size: 14px; opacity: 0.8;">${section.icon}</span>
                            <span class="name" style="font-size: 11px; font-weight: 600; color: ${colors.accent}; opacity: 0.9;">${section.name}</span>
                        </div>
                        <button class="remove-btn" title="Remove" style="font-size: 14px;">×</button>
                    `;
                    
                    // Remove button handler
                    sectionEl.querySelector('.remove-btn').addEventListener('click', (e) => {
                        e.stopPropagation();
                        builderSections.splice(index, 1);
                        renderBuilderCanvas();
                        updateGenerateButton();
                    });
                    
                    // Drag to move within canvas (snap to columns)
                    let isDragMoving = false;
                    let dragStartX, dragStartY, dragStartLeft, dragStartTop;
                    
                    sectionEl.addEventListener('mousedown', (e) => {
                        if (e.target.classList.contains('remove-btn')) return;
                        isDragMoving = true;
                        dragStartX = e.clientX;
                        dragStartY = e.clientY;
                        dragStartLeft = section.defaultX || 0;
                        dragStartTop = section.defaultY || 0;
                        sectionEl.style.zIndex = '50';
                        sectionEl.classList.add('dragging');
                        e.preventDefault();
                    });
                    
                    document.addEventListener('mousemove', (e) => {
                        if (!isDragMoving) return;
                        const rect = pageBuilderCanvas.getBoundingClientRect();
                        const dxPct = ((e.clientX - dragStartX) / rect.width) * 100;
                        const dyPct = ((e.clientY - dragStartY) / rect.height) * 100;
                        
                        let newX = dragStartLeft + dxPct;
                        let newY = dragStartTop + dyPct;
                        
                        const w = section.defaultWidth || 100;
                        const h = section.defaultHeight || 20;
                        newX = Math.max(0, Math.min(newX, 100 - w));
                        newY = Math.max(0, Math.min(newY, 100 - h));
                        
                        // Snap to column zones
                        if (builderColumnZones.length > 0) {
                            const midX = newX + w / 2;
                            let bestZone = null;
                            let bestDist = 15; // snap threshold in %
                            builderColumnZones.forEach(zone => {
                                const zoneMidX = zone.x + zone.width / 2;
                                const dist = Math.abs(midX - zoneMidX);
                                if (dist < bestDist) { bestDist = dist; bestZone = zone; }
                            });
                            if (bestZone) {
                                newX = bestZone.x;
                                sectionEl.style.width = bestZone.width + '%';
                            }
                        }
                        
                        sectionEl.style.left = newX + '%';
                        sectionEl.style.top = newY + '%';
                    });
                    
                    document.addEventListener('mouseup', () => {
                        if (isDragMoving) {
                            isDragMoving = false;
                            sectionEl.style.zIndex = '';
                            sectionEl.classList.remove('dragging');
                            
                            section.defaultX = Math.round(parseFloat(sectionEl.style.left));
                            section.defaultY = Math.round(parseFloat(sectionEl.style.top));
                            section.defaultWidth = Math.round(parseFloat(sectionEl.style.width));
                            
                            // Update column index based on snapped position
                            if (builderColumnZones.length > 0) {
                                const midX = section.defaultX + section.defaultWidth / 2;
                                builderColumnZones.forEach((zone, zi) => {
                                    if (midX >= zone.x && midX <= zone.x + zone.width) {
                                        section._colIndex = zi;
                                    }
                                });
                            }
                            
                            renderBuilderCanvas();
                        }
                    });
                    
                    pageBuilderCanvas.appendChild(sectionEl);
                });
            }
            
            function clearBuilderCanvas() {
                builderSections = [];
                builderColumnLayout = null;
                builderColumnZones = [];
                pageBuilderCanvas.querySelectorAll('.canvas-section, .column-drop-zone').forEach(s => s.remove());
                builderEmptyState.style.display = 'flex';
                // Deselect preset buttons
                document.querySelectorAll('.builder-preset-btn').forEach(b => {
                    b.style.outline = 'none';
                    b.style.boxShadow = 'none';
                });
            }
            
            // Clear button handler
            if (builderClearBtn) {
                builderClearBtn.addEventListener('click', () => {
                    clearBuilderCanvas();
                    updateGenerateButton();
                });
            }
            
            // Column preset buttons — set layout + show column zones
            const presetBtns = document.querySelectorAll('.builder-preset-btn');
            presetBtns.forEach(btn => {
                btn.addEventListener('click', () => {
                    const preset = btn.dataset.preset;
                    builderSections = [];
                    builderColumnLayout = preset;
                    
                    // Title is always full-width at top
                    builderSections.push({ type: 'title', name: 'Title', icon: '📄', defaultHeight: 10, defaultWidth: 100, defaultX: 0, defaultY: 0, _colIndex: -1 });
                    
                    // Highlight active preset
                    document.querySelectorAll('.builder-preset-btn').forEach(b => {
                        b.style.outline = 'none';
                        b.style.boxShadow = 'none';
                    });
                    btn.style.outline = '2px solid rgba(59,130,246,0.6)';
                    btn.style.boxShadow = '0 0 0 4px rgba(59,130,246,0.15)';
                    
                    renderColumnZones();
                    renderBuilderCanvas();
                    updateGenerateButton();
                });
                
                btn.addEventListener('mouseenter', () => { btn.style.transform = 'translateY(-1px)'; });
                btn.addEventListener('mouseleave', () => { btn.style.transform = ''; });
            });
            
            // Keep old functions for compatibility
            function getDropIndex(clientY) { return builderSections.length; }
            function reorderCanvasSection(fromIndex, toIndex) {
                if (fromIndex === toIndex) return;
                
                const section = builderSections.splice(fromIndex, 1)[0];
                builderSections.splice(toIndex, 0, section);
                renderBuilderCanvas();
            }
            
            function updateGenerateButton() {
                if (!templateModalGenerate) {
                    console.error('templateModalGenerate button not found!');
                    return;
                }
                
                const activePanel = templateModal.querySelector('.signature-panel.active');
                console.log('Active panel element:', activePanel);
                console.log('Active panel classList:', activePanel ? activePanel.classList.toString() : 'null');
                console.log('Active panel dataset:', activePanel ? activePanel.dataset : 'null');
                
                const isPrefabsTab = activePanel && activePanel.dataset.templatePanel === 'prefabs';
                const isBuilderTab = activePanel && activePanel.dataset.templatePanel === 'builder';
                
                console.log('updateGenerateButton:', { 
                    isPrefabsTab, 
                    isBuilderTab, 
                    builderSectionsCount: builderSections.length, 
                    selectedLayout,
                    activePanelDataset: activePanel ? activePanel.dataset.templatePanel : 'none'
                });
                
                let shouldEnable = false;
                
                if (isPrefabsTab) {
                    shouldEnable = !!selectedLayout;
                } else if (isBuilderTab) {
                    shouldEnable = builderSections.length > 0;
                }
                
                templateModalGenerate.disabled = !shouldEnable;
                
                console.log('Button state:', shouldEnable ? 'ENABLED' : 'DISABLED', 'disabled attr:', templateModalGenerate.disabled);
            }
            
            // Generate page from template
            if (templateModalGenerate) {
                templateModalGenerate.addEventListener('click', async () => {
                    console.log('Generate button clicked!');
                    
                    const activePanel = templateModal.querySelector('.signature-panel.active');
                    const isPrefabsTab = activePanel && activePanel.dataset.templatePanel === 'prefabs';
                    const isBuilderTab = activePanel && activePanel.dataset.templatePanel === 'builder';
                    
                    console.log('Generate click - Active tab:', { isPrefabsTab, isBuilderTab });
                    
                    // Determine which sections to use
                    let sectionsToRender = [];
                    if (isPrefabsTab) {
                        sectionsToRender = templateSections;
                        console.log('Using prefab sections:', sectionsToRender.length);
                    } else if (isBuilderTab) {
                        sectionsToRender = computeSectionPositions(builderSections.map(s => ({
                            ...s,
                            height: s.defaultHeight
                        })));
                        console.log('Using builder sections:', sectionsToRender.length);
                    }
                    
                    if (sectionsToRender.length === 0) {
                        setStatus('Please add sections to generate a page', 'err');
                        return;
                    }
                    
                    console.log('Generating page from sections:', sectionsToRender);
                    
                    // Get the dimensions from the first page of the PDF
                    if (!pdfjsDocument) {
                        await loadPdf();
                    }
                    const firstPage = await pdfjsDocument.getPage(1);
                    const viewport = firstPage.getViewport({ scale: currentScale });
                    const pageWidth = viewport.width;
                    const pageHeight = viewport.height;
                    
                    // Create a new page canvas with sections
                    const canvas = document.createElement('canvas');
                    canvas.width = pageWidth;
                    canvas.height = pageHeight;
                    const ctx = canvas.getContext('2d');
                    
                    // White background
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, pageWidth, pageHeight);
                    
                    // Draw sections using their computed positions
                    sectionsToRender.forEach((section, i) => {
                        const sectionHeight = pageHeight * (section.height / 100);
                        const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                        const sectionX = pageWidth * ((section.defaultX || 0) / 100);
                        const sectionY = pageHeight * ((section.defaultY || 0) / 100);
                        
                        // Draw subtle section border (structure only, no labels)
                        const colors = ['#3b82f6', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];
                        ctx.strokeStyle = colors[i % colors.length] + '40'; // semi-transparent
                        ctx.lineWidth = 1;
                        ctx.setLineDash([6, 4]);
                        ctx.strokeRect(sectionX + 10, sectionY + 10, sectionWidth - 20, sectionHeight - 20);
                        ctx.setLineDash([]);
                    });
                    
                    // Add the generated page to the AI viewer
                    const aiViewer = document.getElementById('ai-viewer');
                    const wrapper = document.createElement('div');
                    wrapper.className = 'page generated-page';
                    wrapper.style.border = '3px solid #10b981';
                    wrapper.style.position = 'relative';
                    wrapper.appendChild(canvas);
                    
                    // Store sections data for regeneration
                    wrapper.sectionsData = sectionsToRender;
                    wrapper.pageWidth = pageWidth;
                    wrapper.pageHeight = pageHeight;
                    
                    // Function to create section overlay with full functionality
                    function createSectionOverlay(wrapper, section, i, sectionsToRender, pageWidth, pageHeight) {
                        const sectionHeight = pageHeight * (section.height / 100);
                        const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                        const sectionX = pageWidth * ((section.defaultX || 0) / 100);
                        const sectionY = pageHeight * ((section.defaultY || 0) / 100);
                        const MIN_SIZE = 30; // minimum px for width/height
                        
                        const sectionOverlay = document.createElement('div');
                        sectionOverlay.className = 'section-overlay';
                        sectionOverlay.style.cssText = 'position: absolute; left: ' + sectionX + 'px; top: ' + sectionY + 'px; width: ' + sectionWidth + 'px; height: ' + sectionHeight + 'px; cursor: move; border: 2px solid transparent; transition: border-color 0.2s;';
                        sectionOverlay.dataset.sectionIndex = i;
                        
                        // Add controls panel with delete button
                        const controlsPanel = document.createElement('div');
                        controlsPanel.className = 'section-overlay-controls';
                        controlsPanel.style.cssText = 'position: absolute; top: 5px; right: 5px; background: rgba(17, 24, 39, 0.95); border: 1px solid rgba(255,255,255,0.2); border-radius: 6px; padding: 8px; display: none; gap: 6px; align-items: center; z-index: 10; pointer-events: auto;';
                        
                        const deleteBtnHtml = '<button class="delete-section-btn" style="background: rgba(239, 68, 68, 0.9); border: none; color: white; border-radius: 4px; padding: 4px 8px; cursor: pointer; font-size: 11px; font-weight: 600; transition: all 0.2s;" title="Delete section">&#128465;&#65039;</button>';
                        const xInputHtml = '<span style="color: #9ca3af; font-size: 11px; font-weight: 600;">X:</span><input type="number" class="overlay-x-input" value="' + Math.round(section.defaultX || 0) + '" min="0" max="100" style="width: 50px; padding: 3px 5px; border: 1px solid rgba(255,255,255,0.2); border-radius: 4px; background: rgba(255,255,255,0.1); color: white; font-size: 11px;">';
                        const yInputHtml = '<span style="color: #9ca3af; font-size: 11px; font-weight: 600;">Y:</span><input type="number" class="overlay-y-input" value="' + Math.round(section.defaultY || 0) + '" min="0" max="100" style="width: 50px; padding: 3px 5px; border: 1px solid rgba(255,255,255,0.2); border-radius: 4px; background: rgba(255,255,255,0.1); color: white; font-size: 11px;">';
                        const percentHtml = '<span style="color: #9ca3af; font-size: 11px;">%</span>';
                        controlsPanel.innerHTML = deleteBtnHtml + xInputHtml + yInputHtml + percentHtml;
                        
                        sectionOverlay.appendChild(controlsPanel);
                        
                        // Delete button handler
                        const deleteBtn = controlsPanel.querySelector('.delete-section-btn');
                        deleteBtn.addEventListener('click', (e) => {
                            e.stopPropagation();
                            if (confirm('Delete this section?')) {
                                sectionsToRender.splice(i, 1);
                                wrapper.sectionsData = sectionsToRender;
                                sectionOverlay.remove();
                                regenerateCanvas(wrapper);
                                
                                const allOverlays = wrapper.querySelectorAll('.section-overlay');
                                allOverlays.forEach(o => o.remove());
                                sectionsToRender.forEach((sec, idx) => {
                                    const newOverlay = createSectionOverlay(wrapper, sec, idx, sectionsToRender, pageWidth, pageHeight);
                                    wrapper.appendChild(newOverlay);
                                });
                                
                                setStatus('Section deleted', 'ok');
                            }
                        });
                        deleteBtn.addEventListener('mouseenter', () => { deleteBtn.style.background = '#ef4444'; });
                        deleteBtn.addEventListener('mouseleave', () => { deleteBtn.style.background = 'rgba(239, 68, 68, 0.9)'; });
                        
                        // ===== ALL 8 RESIZE HANDLES =====
                        const handleDefs = [
                            { name: 'n',  css: 'position:absolute; top:-4px; left:10px; right:10px; height:8px; cursor:ns-resize; z-index:11;' },
                            { name: 's',  css: 'position:absolute; bottom:-4px; left:10px; right:10px; height:8px; cursor:ns-resize; z-index:11;' },
                            { name: 'e',  css: 'position:absolute; right:-4px; top:10px; bottom:10px; width:8px; cursor:ew-resize; z-index:11;' },
                            { name: 'w',  css: 'position:absolute; left:-4px; top:10px; bottom:10px; width:8px; cursor:ew-resize; z-index:11;' },
                            { name: 'ne', css: 'position:absolute; top:-5px; right:-5px; width:12px; height:12px; cursor:nesw-resize; z-index:12; border-radius:50%;' },
                            { name: 'nw', css: 'position:absolute; top:-5px; left:-5px; width:12px; height:12px; cursor:nwse-resize; z-index:12; border-radius:50%;' },
                            { name: 'se', css: 'position:absolute; bottom:-5px; right:-5px; width:12px; height:12px; cursor:nwse-resize; z-index:12; border-radius:50%;' },
                            { name: 'sw', css: 'position:absolute; bottom:-5px; left:-5px; width:12px; height:12px; cursor:nesw-resize; z-index:12; border-radius:50%;' }
                        ];
                        
                        const handles = {};
                        handleDefs.forEach(def => {
                            const h = document.createElement('div');
                            h.className = 'resize-handle ' + def.name;
                            h.style.cssText = def.css + ' background: rgba(59,130,246,0); transition: background 0.2s;';
                            h.addEventListener('mouseenter', () => { h.style.background = 'rgba(59,130,246,0.5)'; });
                            h.addEventListener('mouseleave', () => { h.style.background = 'rgba(59,130,246,0)'; });
                            sectionOverlay.appendChild(h);
                            handles[def.name] = h;
                        });
                        
                        // ===== UNIFIED RESIZE STATE =====
                        let activeResize = null; // { handle, startMouseX, startMouseY, startLeft, startTop, startW, startH }
                        
                        Object.keys(handles).forEach(name => {
                            handles[name].addEventListener('mousedown', (e) => {
                                activeResize = {
                                    handle: name,
                                    startMouseX: e.clientX,
                                    startMouseY: e.clientY,
                                    startLeft: sectionOverlay.offsetLeft,
                                    startTop: sectionOverlay.offsetTop,
                                    startW: sectionOverlay.offsetWidth,
                                    startH: sectionOverlay.offsetHeight
                                };
                                e.stopPropagation();
                                e.preventDefault();
                            });
                        });
                        
                        document.addEventListener('mousemove', (e) => {
                            if (!activeResize) return;
                            const dx = e.clientX - activeResize.startMouseX;
                            const dy = e.clientY - activeResize.startMouseY;
                            const h = activeResize.handle;
                            
                            let newLeft = activeResize.startLeft;
                            let newTop = activeResize.startTop;
                            let newW = activeResize.startW;
                            let newH = activeResize.startH;
                            
                            // East: expand width rightward
                            if (h === 'e' || h === 'ne' || h === 'se') {
                                newW = Math.max(MIN_SIZE, activeResize.startW + dx);
                            }
                            // West: move left edge, adjust width
                            if (h === 'w' || h === 'nw' || h === 'sw') {
                                const maxDx = activeResize.startW - MIN_SIZE;
                                const clampedDx = Math.min(dx, maxDx);
                                newLeft = activeResize.startLeft + clampedDx;
                                newW = activeResize.startW - clampedDx;
                            }
                            // South: expand height downward
                            if (h === 's' || h === 'se' || h === 'sw') {
                                newH = Math.max(MIN_SIZE, activeResize.startH + dy);
                            }
                            // North: move top edge, adjust height
                            if (h === 'n' || h === 'ne' || h === 'nw') {
                                const maxDy = activeResize.startH - MIN_SIZE;
                                const clampedDy = Math.min(dy, maxDy);
                                newTop = activeResize.startTop + clampedDy;
                                newH = activeResize.startH - clampedDy;
                            }
                            
                            // Clamp to page boundaries
                            if (newLeft < 0) { newW += newLeft; newLeft = 0; }
                            if (newTop < 0) { newH += newTop; newTop = 0; }
                            if (newLeft + newW > pageWidth) newW = pageWidth - newLeft;
                            if (newTop + newH > pageHeight) newH = pageHeight - newTop;
                            newW = Math.max(MIN_SIZE, newW);
                            newH = Math.max(MIN_SIZE, newH);
                            
                            sectionOverlay.style.left = newLeft + 'px';
                            sectionOverlay.style.top = newTop + 'px';
                            sectionOverlay.style.width = newW + 'px';
                            sectionOverlay.style.height = newH + 'px';
                        });
                        
                        document.addEventListener('mouseup', () => {
                            if (activeResize) {
                                // Update section data from final overlay position/size
                                const finalLeft = parseFloat(sectionOverlay.style.left);
                                const finalTop = parseFloat(sectionOverlay.style.top);
                                const finalW = parseFloat(sectionOverlay.style.width);
                                const finalH = parseFloat(sectionOverlay.style.height);
                                
                                sectionsToRender[i].defaultX = Math.round((finalLeft / pageWidth) * 100);
                                sectionsToRender[i].defaultY = Math.round((finalTop / pageHeight) * 100);
                                sectionsToRender[i].defaultWidth = Math.round((finalW / pageWidth) * 100);
                                sectionsToRender[i].height = Math.round((finalH / pageHeight) * 100);
                                
                                // Update inputs
                                xInput.value = sectionsToRender[i].defaultX;
                                yInput.value = sectionsToRender[i].defaultY;
                                
                                activeResize = null;
                                regenerateCanvas(wrapper);
                                saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                            }
                        });
                        
                        // Show/hide controls on hover
                        sectionOverlay.addEventListener('mouseenter', () => {
                            sectionOverlay.style.borderColor = 'rgba(59, 130, 246, 0.8)';
                            controlsPanel.style.display = 'flex';
                        });
                        sectionOverlay.addEventListener('mouseleave', () => {
                            if (!activeResize) {
                                sectionOverlay.style.borderColor = 'transparent';
                                controlsPanel.style.display = 'none';
                            }
                        });
                        
                        // Handle input changes
                        const xInput = controlsPanel.querySelector('.overlay-x-input');
                        const yInput = controlsPanel.querySelector('.overlay-y-input');
                        
                        xInput.addEventListener('input', (e) => {
                            const newX = Math.max(0, Math.min(100, parseInt(e.target.value) || 0));
                            const newLeft = (newX / 100) * pageWidth;
                            // Clamp so section stays on page
                            const clampedLeft = Math.min(newLeft, pageWidth - parseFloat(sectionOverlay.style.width));
                            sectionOverlay.style.left = Math.max(0, clampedLeft) + 'px';
                            sectionsToRender[i].defaultX = Math.round((Math.max(0, clampedLeft) / pageWidth) * 100);
                            regenerateCanvas(wrapper);
                            saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                        });
                        
                        yInput.addEventListener('input', (e) => {
                            const newY = Math.max(0, Math.min(100, parseInt(e.target.value) || 0));
                            const newTop = (newY / 100) * pageHeight;
                            const clampedTop = Math.min(newTop, pageHeight - parseFloat(sectionOverlay.style.height));
                            sectionOverlay.style.top = Math.max(0, clampedTop) + 'px';
                            sectionsToRender[i].defaultY = Math.round((Math.max(0, clampedTop) / pageHeight) * 100);
                            regenerateCanvas(wrapper);
                            saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                        });
                        
                        // ===== DRAG FUNCTIONALITY WITH PAGE CLAMPING =====
                        let isDragging = false;
                        let startX, startY, offsetX, offsetY;
                        
                        sectionOverlay.addEventListener('mousedown', (e) => {
                            if (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON') return;
                            if (e.target.classList.contains('resize-handle')) return;
                            
                            isDragging = true;
                            startX = e.clientX;
                            startY = e.clientY;
                            offsetX = sectionOverlay.offsetLeft;
                            offsetY = sectionOverlay.offsetTop;
                            sectionOverlay.style.zIndex = '1000';
                            sectionOverlay.style.borderColor = 'rgba(59, 130, 246, 1)';
                            e.preventDefault();
                        });
                        
                        document.addEventListener('mousemove', (e) => {
                            if (!isDragging) return;
                            const deltaX = e.clientX - startX;
                            const deltaY = e.clientY - startY;
                            let newLeft = offsetX + deltaX;
                            let newTop = offsetY + deltaY;
                            
                            // Clamp to page boundaries
                            const w = sectionOverlay.offsetWidth;
                            const h = sectionOverlay.offsetHeight;
                            newLeft = Math.max(0, Math.min(newLeft, pageWidth - w));
                            newTop = Math.max(0, Math.min(newTop, pageHeight - h));
                            
                            sectionOverlay.style.left = newLeft + 'px';
                            sectionOverlay.style.top = newTop + 'px';
                            
                            const newXPct = Math.round((newLeft / pageWidth) * 100);
                            const newYPct = Math.round((newTop / pageHeight) * 100);
                            xInput.value = newXPct;
                            yInput.value = newYPct;
                        });
                        
                        document.addEventListener('mouseup', () => {
                            if (isDragging) {
                                isDragging = false;
                                sectionOverlay.style.zIndex = '';
                                sectionOverlay.style.borderColor = 'transparent';
                                
                                const newX = (parseFloat(sectionOverlay.style.left) / pageWidth) * 100;
                                const newY = (parseFloat(sectionOverlay.style.top) / pageHeight) * 100;
                                sectionsToRender[i].defaultX = Math.round(newX);
                                sectionsToRender[i].defaultY = Math.round(newY);
                                
                                regenerateCanvas(wrapper);
                                saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                            }
                        });
                        
                        return sectionOverlay;
                    }
                    
                    // Create draggable section overlays
                    sectionsToRender.forEach((section, i) => {
                        const overlay = createSectionOverlay(wrapper, section, i, sectionsToRender, pageWidth, pageHeight);
                        wrapper.appendChild(overlay);
                    });
                    
                    // Add menu bar to the right of the page
                    const menu = document.createElement('div');
                    menu.className = 'generated-page-menu';
                    const unlockIcon = String.fromCodePoint(0x1F513);
                    const plusIcon = String.fromCodePoint(0x2795);
                    const trashIcon = String.fromCodePoint(0x1F5D1, 0xFE0F);
                    menu.innerHTML = `
                        <button class="lock-sections-btn" title="Lock/Unlock sections">
                            <span>${unlockIcon}</span> Unlock
                        </button>
                        <button class="add-section-btn" title="Add section to page">
                            <span>${plusIcon}</span> Section
                        </button>
                        <button class="delete-page-btn" title="Delete this page">
                            <span>${trashIcon}</span> Delete
                        </button>
                    `;
                    wrapper.appendChild(menu);
                    
                    // Track locked state
                    let sectionsLocked = false;
                    
                    // Add lock handler
                    const lockBtn = menu.querySelector('.lock-sections-btn');
                    lockBtn.addEventListener('click', () => {
                        sectionsLocked = !sectionsLocked;
                        const overlays = wrapper.querySelectorAll('.section-overlay');
                        
                        overlays.forEach(overlay => {
                            if (sectionsLocked) {
                                overlay.style.pointerEvents = 'none';
                                overlay.style.opacity = '0.5';
                            } else {
                                overlay.style.pointerEvents = 'auto';
                                overlay.style.opacity = '1';
                            }
                        });
                        
                        if (sectionsLocked) {
                            lockBtn.innerHTML = '<span>🔒</span> Locked';
                            lockBtn.classList.add('locked');
                            setStatus('Sections locked', 'ok');
                        } else {
                            lockBtn.innerHTML = '<span>🔓</span> Unlock';
                            lockBtn.classList.remove('locked');
                            setStatus('Sections unlocked', 'ok');
                        }
                    });
                    
                    // Add section handler
                    const addSectionBtn = menu.querySelector('.add-section-btn');
                    addSectionBtn.addEventListener('click', () => {
                        // Create and show modal
                        const addSectionModal = document.createElement('div');
                        addSectionModal.className = 'modal';
                        addSectionModal.style.display = 'flex';
                        addSectionModal.innerHTML = `
                            <div class="modal-content" style="max-width: 400px;">
                                <div class="modal-header">
                                    <span>Add Section</span>
                                    <button class="modal-close" type="button">×</button>
                                </div>
                                <div class="modal-body" style="padding: 20px;">
                                    <label style="display: block; font-weight: 600; margin-bottom: 12px;">Section Type</label>
                                    <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                                        <button class="section-type-btn" data-type="paragraph" style="padding: 20px; background: rgba(59, 130, 246, 0.1); border: 2px solid rgba(59, 130, 246, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                            <div style="font-size: 32px; margin-bottom: 8px;">📄</div>
                                            <div style="font-weight: 600;">Paragraph</div>
                                        </button>
                                        <button class="section-type-btn" data-type="title" style="padding: 20px; background: rgba(139, 92, 246, 0.1); border: 2px solid rgba(139, 92, 246, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                            <div style="font-size: 32px; margin-bottom: 8px;">📌</div>
                                            <div style="font-weight: 600;">Title</div>
                                        </button>
                                        <button class="section-type-btn" data-type="chart" style="padding: 20px; background: rgba(236, 72, 153, 0.1); border: 2px solid rgba(236, 72, 153, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                            <div style="font-size: 32px; margin-bottom: 8px;">📊</div>
                                            <div style="font-weight: 600;">Chart</div>
                                        </button>
                                        <button class="section-type-btn" data-type="graphic" style="padding: 20px; background: rgba(245, 158, 11, 0.1); border: 2px solid rgba(245, 158, 11, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                            <div style="font-size: 32px; margin-bottom: 8px;">🖼️</div>
                                            <div style="font-weight: 600;">Image</div>
                                        </button>
                                    </div>
                                </div>
                            </div>
                        `;
                        document.body.appendChild(addSectionModal);
                        
                        // Add hover effects
                        const sectionTypeBtns = addSectionModal.querySelectorAll('.section-type-btn');
                        sectionTypeBtns.forEach(btn => {
                            btn.addEventListener('mouseenter', () => {
                                btn.style.transform = 'translateY(-2px)';
                                btn.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
                            });
                            btn.addEventListener('mouseleave', () => {
                                btn.style.transform = '';
                                btn.style.boxShadow = '';
                            });
                            btn.addEventListener('click', () => {
                                const sectionType = btn.dataset.type;
                                
                                // Add new section to the page
                                const newSection = {
                                    type: sectionType,
                                    height: 20,
                                    defaultX: 10,
                                    defaultY: sectionsToRender.length * 20,
                                    defaultWidth: 80
                                };
                                
                                sectionsToRender.push(newSection);
                                wrapper.sectionsData = sectionsToRender;
                                
                                // Close modal
                                addSectionModal.remove();
                                setStatus(`Added ${sectionType} section`, 'ok');
                                
                                // Regenerate the canvas with new section
                                regenerateCanvas(wrapper);
                                
                                // Remove existing overlays
                                const existingOverlays = wrapper.querySelectorAll('.section-overlay');
                                existingOverlays.forEach(o => o.remove());
                                
                                // Recreate overlays for all sections using the helper function
                                sectionsToRender.forEach((sec, idx) => {
                                    const newOverlay = createSectionOverlay(wrapper, sec, idx, sectionsToRender, pageWidth, pageHeight);
                                    wrapper.appendChild(newOverlay);
                                });
                            });
                        });
                        
                        // Close modal handler
                        const closeBtn = addSectionModal.querySelector('.modal-close');
                        closeBtn.addEventListener('click', () => addSectionModal.remove());
                        addSectionModal.addEventListener('click', (e) => {
                            if (e.target === addSectionModal) addSectionModal.remove();
                        });
                    });
                    
                    // Add delete handler
                    const deleteBtn = menu.querySelector('.delete-page-btn');
                    deleteBtn.addEventListener('click', () => {
                        if (confirm('Delete this generated page?')) {
                            wrapper.remove();
                            setStatus('Page deleted', 'ok');
                        }
                    });
                    
                    aiViewer.insertBefore(wrapper, aiViewer.firstChild);
                    
                    // Save template structure to localStorage
                    saveTemplateToLocalStorage(sectionsToRender, pageWidth, pageHeight);
                    
                    // Save sections to database
                    saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                    
                    // Scroll to the new page
                    wrapper.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    
                    setStatus('Template page generated successfully!', 'ok');
                    closeTemplateModal();
                });
            }
            
            // Function to regenerate canvas when sections are moved
            function regenerateCanvas(wrapper) {
                const sectionsData = wrapper.sectionsData;
                const pageWidth = wrapper.pageWidth;
                const pageHeight = wrapper.pageHeight;
                const generatedContent = wrapper.generatedContent; // Get stored content
                const generatedImages = wrapper.generatedImages || []; // Get stored images
                const renderVersion = (wrapper.canvasRenderVersion || 0) + 1;
                wrapper.canvasRenderVersion = renderVersion;
                
                // Get the canvas element
                const canvas = wrapper.querySelector('canvas');
                if (!canvas) return;
                const ctx = canvas.getContext('2d');
                
                // Clear and redraw
                ctx.setTransform(1, 0, 0, 1, 0, 0);
                ctx.clearRect(0, 0, pageWidth, pageHeight);
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(0, 0, pageWidth, pageHeight);
                
                // Draw sections with updated positions
                sectionsData.forEach((section, i) => {
                    const sectionHeight = pageHeight * (section.height / 100);
                    const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                    const sectionX = pageWidth * ((section.defaultX || 0) / 100);
                    const sectionY = pageHeight * ((section.defaultY || 0) / 100);
                    
                    // Draw subtle section border (structure only, no labels)
                    const colors = ['#3b82f6', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];
                    ctx.strokeStyle = colors[i % colors.length] + '40';
                    ctx.lineWidth = 1;
                    ctx.setLineDash([6, 4]);
                    ctx.strokeRect(sectionX + 10, sectionY + 10, sectionWidth - 20, sectionHeight - 20);
                    ctx.setLineDash([]);
                    
                    // Check if this is an image section
                    const isImageSection = ['image', 'graphic', 'chart'].includes(section.type?.toLowerCase());
                    const generatedImage = generatedImages.find(img => img.section_number === i);
                    
                    // Check if there's generated content for this section
                    if (isImageSection && generatedImage && generatedImage.image_id) {
                        // Fetch and render image from database
                        fetch(`/api/ai-images/${generatedImage.image_id}`)
                            .then(response => response.json())
                            .then(imageData => {
                                if (wrapper.canvasRenderVersion !== renderVersion) return;
                                if (imageData.image_data && imageData.storage_type === 'base64') {
                                    const img = new Image();
                                    img.onload = function() {
                                        if (wrapper.canvasRenderVersion !== renderVersion) return;
                                        const padding = 20;
                                        const maxWidth = sectionWidth - padding * 2;
                                        const maxHeight = sectionHeight - padding * 2;
                                        
                                        let drawWidth = img.width;
                                        let drawHeight = img.height;
                                        
                                        const scale = Math.min(maxWidth / drawWidth, maxHeight / drawHeight, 1);
                                        drawWidth *= scale;
                                        drawHeight *= scale;
                                        
                                        const x = sectionX + (sectionWidth - drawWidth) / 2;
                                        const y = sectionY + (sectionHeight - drawHeight) / 2;
                                        
                                        ctx.drawImage(img, x, y, drawWidth, drawHeight);
                                    };
                                    img.src = `data:image/png;base64,${imageData.image_data}`;
                                }
                            })
                            .catch(error => console.error('Failed to load image:', error));
                    } else if (generatedContent) {
                        // Handle both array and object formats
                        const contentArray = Array.isArray(generatedContent) ? generatedContent : 
                            (generatedContent.sections || []);
                        
                        const generatedSection = contentArray.find(gs => 
                            gs.section_number === (i + 1) || 
                            gs.type === section.type
                        );
                        
                        if (generatedSection && generatedSection.content) {
                            // Render the generated content
                            ctx.fillStyle = '#000000';
                            
                            // Adjust font size based on section type and height
                            let fontSize = 16;
                            if (section.type === 'title') {
                                fontSize = Math.min(32, sectionHeight / 3);
                            } else if (section.type === 'paragraph') {
                                fontSize = Math.min(16, sectionHeight / 10);
                            }
                            
                            ctx.font = `${fontSize}px sans-serif`;
                            ctx.textAlign = 'left';
                            
                            // Word wrap and render text within section bounds
                            const maxWidth = sectionWidth - 60; // Padding
                            const lineHeight = fontSize * 1.4;
                            const maxLines = Math.floor((sectionHeight - 40) / lineHeight);
                            
                            const words = generatedSection.content.split(' ');
                            let lines = [];
                            let currentLine = '';
                            
                            for (let word of words) {
                                const testLine = currentLine + (currentLine ? ' ' : '') + word;
                                const metrics = ctx.measureText(testLine);
                                
                                if (metrics.width > maxWidth && currentLine) {
                                    lines.push(currentLine);
                                    currentLine = word;
                                } else {
                                    currentLine = testLine;
                                }
                                
                                if (lines.length >= maxLines) break;
                            }
                            if (currentLine && lines.length < maxLines) {
                                lines.push(currentLine);
                            }
                            
                            // Draw the text lines
                            let textY = sectionY + 30 + fontSize;
                            lines.forEach((line, lineIndex) => {
                                if (textY + lineHeight <= sectionY + sectionHeight - 20) {
                                    ctx.fillText(line, sectionX + 30, textY);
                                    textY += lineHeight;
                                }
                            });
                            
                            return; // Skip drawing placeholder elements
                        }
                    }
                    
                    // Draw section icon and name (only if no generated content)
                    ctx.fillStyle = '#000000';
                    ctx.font = 'bold 24px sans-serif';
                    ctx.textAlign = 'left';
                    ctx.fillText(section.icon || '', sectionX + 30, sectionY + 50);
                    
                    ctx.font = 'bold 18px sans-serif';
                    ctx.fillText(section.name || section.type, sectionX + 70, sectionY + 50);
                    
                    // Draw section dimensions
                    ctx.font = '14px sans-serif';
                    ctx.fillStyle = '#000000';
                    ctx.fillText(`H: ${section.height}% W: ${section.defaultWidth || 100}%`, sectionX + 30, sectionY + 80);
                });
            }
            
            // AI mode bar buttons - connect to same save/clear functionality
            const aiSaveBtn = document.getElementById('ai-save-btn');
            const aiClearBtn = document.getElementById('ai-clear-btn');
            const savePdfBtn = document.getElementById('save-btn');
            const clearAllBtn = document.getElementById('clear-btn');
            
            if (aiSaveBtn && savePdfBtn) {
                aiSaveBtn.addEventListener('click', () => savePdfBtn.click());
            }
            if (aiClearBtn && clearAllBtn) {
                aiClearBtn.addEventListener('click', () => clearAllBtn.click());
            }
            
            // Initialize zoom on page load (without re-rendering, just update the label)
            // Mobile gets 100% of base scale (50%), desktop gets 130% of base scale (169%)
            const initialZoomMultiplier = isMobile ? 1.0 : 1.3;
            currentScale = baseScale * initialZoomMultiplier;
            zoomLabel.textContent = Math.round(initialZoomMultiplier * 100) + '%';
            
            // ===== CUSTOMIZE PROMPT MODAL =====
            const customizePromptBtn = document.getElementById('customize-prompt-btn');
            const promptModal = document.getElementById('customize-prompt-modal');
            const promptModalClose = document.getElementById('prompt-modal-close');
            const promptModalCancel = document.getElementById('prompt-modal-cancel');
            const promptModalSave = document.getElementById('prompt-modal-save');
            const promptModalReset = document.getElementById('prompt-modal-reset');
            
            const promptStyleInput = document.getElementById('prompt-style');
            const promptQualityInput = document.getElementById('prompt-quality');
            const promptAdditionalInput = document.getElementById('prompt-additional');
            const promptPreview = document.getElementById('prompt-preview');
            
            // Default prompt settings
            const defaultPromptSettings = {
                style: 'modern and professional',
                quality: 'high-quality, photorealistic',
                additional: ''
            };
            
            // Load saved settings from localStorage or use defaults
            let promptSettings = JSON.parse(localStorage.getItem('aiPromptSettings')) || { ...defaultPromptSettings };
            
            // Function to update the preview
            function updatePromptPreview() {
                const style = promptStyleInput.value.trim() || defaultPromptSettings.style;
                const quality = promptQualityInput.value.trim() || defaultPromptSettings.quality;
                const additional = promptAdditionalInput.value.trim();
                
                let preview = `Generate a professional [type] for a document about: [user prompt]. Section name: [section name]. Image dimensions: [width]px × [height]px. The image should be ${quality}, and directly relevant to the content. Style: ${style}.`;
                
                if (additional) {
                    preview += ` ${additional}`;
                }
                
                promptPreview.textContent = preview;
            }
            
            // Load settings into form
            function loadPromptSettings() {
                promptStyleInput.value = promptSettings.style;
                promptQualityInput.value = promptSettings.quality;
                promptAdditionalInput.value = promptSettings.additional || '';
                updatePromptPreview();
            }
            
            // Open customize prompt modal
            if (customizePromptBtn) {
                customizePromptBtn.addEventListener('click', () => {
                    loadPromptSettings();
                    promptModal.style.display = 'flex';
                    document.body.style.overflow = 'hidden';
                });
            }
            
            // Close modal
            const closePromptModal = () => {
                promptModal.style.display = 'none';
                document.body.style.overflow = '';
            };
            
            if (promptModalClose) {
                promptModalClose.addEventListener('click', closePromptModal);
            }
            if (promptModalCancel) {
                promptModalCancel.addEventListener('click', closePromptModal);
            }
            
            // Update preview on input
            promptStyleInput.addEventListener('input', updatePromptPreview);
            promptQualityInput.addEventListener('input', updatePromptPreview);
            promptAdditionalInput.addEventListener('input', updatePromptPreview);
            
            // Reset to defaults
            if (promptModalReset) {
                promptModalReset.addEventListener('click', () => {
                    promptStyleInput.value = defaultPromptSettings.style;
                    promptQualityInput.value = defaultPromptSettings.quality;
                    promptAdditionalInput.value = '';
                    updatePromptPreview();
                });
            }
            
            // Save settings
            if (promptModalSave) {
                promptModalSave.addEventListener('click', () => {
                    promptSettings = {
                        style: promptStyleInput.value.trim() || defaultPromptSettings.style,
                        quality: promptQualityInput.value.trim() || defaultPromptSettings.quality,
                        additional: promptAdditionalInput.value.trim()
                    };
                    
                    // Save to localStorage
                    localStorage.setItem('aiPromptSettings', JSON.stringify(promptSettings));
                    
                    setStatus('Prompt settings saved successfully!', 'ok');
                    closePromptModal();
                });
            }
            
            // ===== END CUSTOMIZE PROMPT MODAL =====
            
            // AI Chat Functionality
            const aiChatInput = document.getElementById('ai-chat-input');
            const aiSendBtn = document.getElementById('ai-send-btn');
            const aiChatMessages = document.getElementById('ai-chat-messages');
            const aiAttachBtn = document.getElementById('ai-attach-btn');
            
            // Auto-resize textarea
            if (aiChatInput) {
                aiChatInput.addEventListener('input', function() {
                    this.style.height = 'auto';
                    this.style.height = Math.min(this.scrollHeight, 120) + 'px';
                });
            }
            
            // Add message to chat
            function addChatMessage(text, isUser = true) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `ai-chat-message ${isUser ? 'user' : 'bot'}`;
                
                const bubble = document.createElement('div');
                bubble.className = 'ai-message-bubble';
                bubble.textContent = text;
                
                messageDiv.appendChild(bubble);
                
                // Add copy button for bot messages
                if (!isUser) {
                    const copyBtn = document.createElement('div');
                    copyBtn.className = 'ai-message-copy';
                    copyBtn.innerHTML = `
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                        </svg>
                        Copy
                    `;
                    copyBtn.addEventListener('click', () => {
                        navigator.clipboard.writeText(text);
                        copyBtn.innerHTML = `
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                <polyline points="20 6 9 17 4 12"></polyline>
                            </svg>
                            Copied!
                        `;
                        setTimeout(() => {
                            copyBtn.innerHTML = `
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                                    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                                </svg>
                                Copy
                            `;
                        }, 2000);
                    });
                    messageDiv.appendChild(copyBtn);
                }
                
                aiChatMessages.appendChild(messageDiv);
                aiChatMessages.scrollTop = aiChatMessages.scrollHeight;
            }
            
            // Render AI-generated content into sections
            function renderContentIntoSections(generatedSections, originalSections, generatedImages = []) {
                console.log('Rendering sections:', {generatedSections, originalSections, generatedImages});
                
                const aiViewer = document.getElementById('ai-viewer');
                const generatedPages = aiViewer ? aiViewer.querySelectorAll('.generated-page') : [];
                
                if (generatedPages.length === 0) return;
                
                // For each generated page, re-render with content
                generatedPages.forEach((page, pageIndex) => {
                    if (!page.sectionsData || !page.pageWidth || !page.pageHeight) return;
                    
                    // Store generated content on the page element
                    page.generatedContent = generatedSections;
                    page.generatedImages = generatedImages;
                    
                    const canvas = page.querySelector('canvas');
                    if (!canvas) return;
                    
                    const ctx = canvas.getContext('2d');
                    const pageWidth = page.pageWidth;
                    const pageHeight = page.pageHeight;
                    
                    // Clear and redraw white background
                    ctx.fillStyle = '#ffffff';
                    ctx.fillRect(0, 0, pageWidth, pageHeight);
                    
                    // Draw each section with generated content
                    page.sectionsData.forEach((section, sectionIndex) => {
                        const sectionHeight = pageHeight * (section.height / 100);
                        const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                        const sectionX = pageWidth * ((section.defaultX || 0) / 100);
                        const sectionY = pageHeight * ((section.defaultY || 0) / 100);
                        
                        // Find the order number for this section from originalSections
                        const sectionOrder = originalSections[sectionIndex]?.order || sectionIndex;
                        
                        // Find matching generated content - match by section_number only
                        const generatedSection = generatedSections.find(gs => 
                            gs.section_number === (sectionIndex + 1)
                        );
                        
                        // Find matching generated image by order
                        const generatedImage = generatedImages.find(img => 
                            img.section_number === sectionOrder
                        );
                        
                        console.log(`Section ${sectionIndex}:`, {section, sectionOrder, generatedSection, generatedImage});
                        
                        // Draw subtle section border (hidden structure)
                        const colors = ['#3b82f6', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];
                        ctx.strokeStyle = colors[sectionIndex % colors.length] + '30';
                        ctx.lineWidth = 1;
                        ctx.setLineDash([6, 4]);
                        ctx.strokeRect(sectionX + 10, sectionY + 10, sectionWidth - 20, sectionHeight - 20);
                        ctx.setLineDash([]);
                        
                        // Check if this is an image section
                        const isImageSection = ['image', 'graphic', 'chart'].includes(section.type?.toLowerCase());
                        
                        if (isImageSection && generatedImage && generatedImage.image_data && generatedImage.storage_type === 'base64') {
                            // Render image
                            const img = new Image();
                            img.onload = function() {
                                // Calculate dimensions to fit within section
                                const padding = 20;
                                const maxWidth = sectionWidth - padding * 2;
                                const maxHeight = sectionHeight - padding * 2;
                                
                                let drawWidth = img.width;
                                let drawHeight = img.height;
                                
                                // Scale to fit
                                const scale = Math.min(maxWidth / drawWidth, maxHeight / drawHeight, 1);
                                drawWidth *= scale;
                                drawHeight *= scale;
                                
                                // Center the image
                                const x = sectionX + (sectionWidth - drawWidth) / 2;
                                const y = sectionY + (sectionHeight - drawHeight) / 2;
                                
                                ctx.drawImage(img, x, y, drawWidth, drawHeight);
                            };
                            img.src = `data:image/png;base64,${generatedImage.image_data}`;
                        } else if (generatedSection && generatedSection.content) {
                            // Render the generated text content
                            ctx.fillStyle = '#000000';
                            
                            // Adjust font size based on section type and height
                            let fontSize = 16;
                            if (section.type === 'title') {
                                fontSize = Math.min(32, sectionHeight / 3);
                            } else if (section.type === 'paragraph') {
                                fontSize = Math.min(16, sectionHeight / 10);
                            }
                            
                            ctx.font = `${fontSize}px sans-serif`;
                            ctx.textAlign = 'left';
                            
                            // Word wrap and render text within section bounds
                            const maxWidth = sectionWidth - 60; // Padding
                            const lineHeight = fontSize * 1.4;
                            const maxLines = Math.floor((sectionHeight - 40) / lineHeight);
                            
                            const words = generatedSection.content.split(' ');
                            let lines = [];
                            let currentLine = '';
                            
                            for (let word of words) {
                                const testLine = currentLine + (currentLine ? ' ' : '') + word;
                                const metrics = ctx.measureText(testLine);
                                
                                if (metrics.width > maxWidth && currentLine) {
                                    lines.push(currentLine);
                                    currentLine = word;
                                } else {
                                    currentLine = testLine;
                                }
                                
                                if (lines.length >= maxLines) break;
                            }
                            if (currentLine && lines.length < maxLines) {
                                lines.push(currentLine);
                            }
                            
                            // Draw the text lines
                            let textY = sectionY + 30 + fontSize;
                            lines.forEach((line, lineIndex) => {
                                if (textY + lineHeight <= sectionY + sectionHeight - 20) {
                                    ctx.fillText(line, sectionX + 30, textY);
                                    textY += lineHeight;
                                }
                            });
                        } else {
                            // No content generated, show placeholder
                            ctx.fillStyle = '#9ca3af';
                            ctx.font = 'italic 14px sans-serif';
                            ctx.textAlign = 'center';
                            ctx.fillText('No content generated', sectionX + sectionWidth / 2, sectionY + sectionHeight / 2);
                        }
                    });
                });
                
                // Save to localStorage
                saveAIContentToLocalStorage(generatedSections);
            }
            
            // Save AI generated content to localStorage
            function saveAIContentToLocalStorage(generatedSections) {
                const storageKey = `ai-generated-content-${documentId}`;
                try {
                    localStorage.setItem(storageKey, JSON.stringify(generatedSections));
                } catch (e) {
                    console.error('Failed to save AI content to localStorage:', e);
                }
            }
            
            // Save template structure to localStorage
            function saveTemplateToLocalStorage(sectionsData, pageWidth, pageHeight) {
                const storageKey = `ai-template-${documentId}`;
                try {
                    localStorage.setItem(storageKey, JSON.stringify({
                        sections: sectionsData,
                        pageWidth: pageWidth,
                        pageHeight: pageHeight,
                        timestamp: Date.now()
                    }));
                } catch (e) {
                    console.error('Failed to save template to localStorage:', e);
                }
            }
            
            // Save sections to database
            async function saveSectionsToDatabase(sectionsData, pageWidth, pageHeight) {
                try {
                    const response = await fetch('/ai/sections', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Accept': 'application/json',
                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
                        },
                        body: JSON.stringify({
                            document_id: documentId,
                            sections: sectionsData,
                            page_width: pageWidth,
                            page_height: pageHeight
                        })
                    });
                    
                    const data = await response.json();
                    if (data.success) {
                        console.log('Sections saved to database:', data.section_id);
                    } else {
                        console.error('Failed to save sections:', data.message);
                    }
                } catch (e) {
                    console.error('Error saving sections to database:', e);
                }
            }
            
            // Delete sections from database
            async function deleteSectionsFromDatabase() {
                try {
                    const response = await fetch(`/ai/sections/${documentId}`, {
                        method: 'DELETE',
                        headers: {
                            'Accept': 'application/json',
                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').getAttribute('content')
                        }
                    });
                    
                    const data = await response.json();
                    if (data.success) {
                        console.log('Sections deleted from database');
                    } else {
                        console.error('Failed to delete sections:', data.message);
                    }
                } catch (e) {
                    console.error('Error deleting sections from database:', e);
                }
            }
            
            // Load sections from database and recreate template
            async function loadSectionsFromDatabase() {
                try {
                    const response = await fetch(`/ai/sections/${documentId}`, {
                        headers: {
                            'Accept': 'application/json',
                        }
                    });
                    
                    const data = await response.json();
                    if (data.success && data.sections) {
                        console.log('Loaded sections from database:', data.sections.length);
                        console.log('Generated content:', data.generated_content);
                        console.log('Generated images:', data.generated_images);
                        
                        // Recreate the template with saved sections and content
                        await recreateTemplateFromSections(
                            data.sections, 
                            data.page_width, 
                            data.page_height,
                            data.generated_content,
                            data.generated_images
                        );
                    }
                } catch (e) {
                    console.error('Error loading sections from database:', e);
                }
            }
            
            // Recreate template page from saved sections
            async function recreateTemplateFromSections(sectionsData, pageWidth, pageHeight, generatedContent, generatedImages) {
                // Get PDF dimensions if not provided
                if (!pageWidth || !pageHeight) {
                    if (!pdfjsDocument) {
                        await loadPdf();
                    }
                    const firstPage = await pdfjsDocument.getPage(1);
                    const viewport = firstPage.getViewport({ scale: currentScale });
                    pageWidth = viewport.width;
                    pageHeight = viewport.height;
                }
                
                // Create canvas
                const canvas = document.createElement('canvas');
                canvas.width = pageWidth;
                canvas.height = pageHeight;
                const ctx = canvas.getContext('2d');
                
                // White background
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(0, 0, pageWidth, pageHeight);
                
                // Draw sections with content if available
                let currentY = 0;
                sectionsData.forEach((section, i) => {
                    const sectionHeight = pageHeight * (section.height / 100);
                    const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                    const sectionX = (pageWidth - sectionWidth) / 2;
                    
                    const colors = ['#3b82f6', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981'];
                    ctx.strokeStyle = colors[i % colors.length];
                    ctx.lineWidth = 2;
                    ctx.strokeRect(sectionX + 10, currentY + 10, sectionWidth - 20, sectionHeight - 20);
                    
                    // Check if there's generated content for this section
                    const contentSection = generatedContent?.sections?.[i];
                    const imageData = generatedImages?.find(img => img.section_number === i);
                    const isImageSection = ['image', 'graphic', 'chart'].includes(section.type?.toLowerCase());
                    
                    if (isImageSection && imageData && imageData.image_data && imageData.storage_type === 'base64') {
                        // Render image asynchronously
                        const img = new Image();
                        img.onload = function() {
                            const padding = 20;
                            const maxWidth = sectionWidth - padding * 2;
                            const maxHeight = sectionHeight - padding * 2;
                            
                            let drawWidth = img.width;
                            let drawHeight = img.height;
                            const aspectRatio = drawWidth / drawHeight;
                            
                            if (drawWidth > maxWidth) {
                                drawWidth = maxWidth;
                                drawHeight = drawWidth / aspectRatio;
                            }
                            if (drawHeight > maxHeight) {
                                drawHeight = maxHeight;
                                drawWidth = drawHeight * aspectRatio;
                            }
                            
                            const imgX = sectionX + (sectionWidth - drawWidth) / 2;
                            const imgY = currentY + (sectionHeight - drawHeight) / 2;
                            
                            ctx.drawImage(img, imgX, imgY, drawWidth, drawHeight);
                        };
                        img.src = `data:${imageData.mime_type || 'image/png'};base64,${imageData.image_data}`;
                    } else if (contentSection && contentSection.content) {
                        // Render text content
                        ctx.fillStyle = '#1f2937';
                        ctx.font = '16px sans-serif';
                        ctx.textAlign = 'left';
                        
                        const content = contentSection.content;
                        const maxWidth = sectionWidth - 60;
                        const words = content.split(' ');
                        const lines = [];
                        let currentLine = '';
                        
                        words.forEach(word => {
                            const testLine = currentLine + (currentLine ? ' ' : '') + word;
                            const metrics = ctx.measureText(testLine);
                            if (metrics.width > maxWidth && currentLine) {
                                lines.push(currentLine);
                                currentLine = word;
                            } else {
                                currentLine = testLine;
                            }
                        });
                        if (currentLine) lines.push(currentLine);
                        
                        const lineHeight = 22;
                        const fontSize = 16;
                        let textY = currentY + 30 + fontSize;
                        lines.forEach((line) => {
                            if (textY + lineHeight <= currentY + sectionHeight - 20) {
                                ctx.fillText(line, sectionX + 30, textY);
                                textY += lineHeight;
                            }
                        });
                    } else {
                        // No content - show section info
                        ctx.fillStyle = '#000000';
                        ctx.font = 'bold 24px sans-serif';
                        ctx.textAlign = 'left';
                        ctx.fillText(section.icon || '', sectionX + 30, currentY + 50);
                        
                        ctx.font = 'bold 18px sans-serif';
                        ctx.fillText(section.name || section.type, sectionX + 70, currentY + 50);
                        
                        ctx.font = '14px sans-serif';
                        ctx.fillStyle = '#000000';
                        ctx.fillText(`H: ${section.height}% W: ${section.defaultWidth || 100}%`, sectionX + 30, currentY + 80);
                    }
                    
                    currentY += sectionHeight;
                });
                
                // Add to AI viewer
                const aiViewer = document.getElementById('ai-viewer');
                const wrapper = document.createElement('div');
                wrapper.className = 'page generated-page';
                wrapper.style.border = '3px solid #10b981';
                wrapper.style.position = 'relative';
                wrapper.appendChild(canvas);
                
                wrapper.sectionsData = sectionsData;
                wrapper.pageWidth = pageWidth;
                wrapper.pageHeight = pageHeight;
                wrapper.generatedContent = generatedContent;
                wrapper.generatedImages = generatedImages || [];
                
                // Create section overlays (same function as in template generation)
                sectionsData.forEach((section, i) => {
                    createSectionOverlayForRecreated(wrapper, section, i, sectionsData, pageWidth, pageHeight);
                });
                
                // Add page menu
                const menu = document.createElement('div');
                menu.className = 'generated-page-menu';
                menu.innerHTML = `
                    <button class="lock-sections-btn" title="Lock/Unlock sections">🔓</button>
                    <button class="add-section-btn" title="Add section">➕</button>
                    <button class="delete-page-btn" title="Delete page">🗑️</button>
                `;
                wrapper.appendChild(menu);
                
                const lockBtn = menu.querySelector('.lock-sections-btn');
                const addBtn = menu.querySelector('.add-section-btn');
                const deleteBtn = menu.querySelector('.delete-page-btn');
                
                let sectionsLocked = false;
                lockBtn.addEventListener('click', () => {
                    sectionsLocked = !sectionsLocked;
                    lockBtn.textContent = sectionsLocked ? '🔒' : '🔓';
                    const overlays = wrapper.querySelectorAll('.section-overlay');
                    overlays.forEach(overlay => {
                        overlay.style.pointerEvents = sectionsLocked ? 'none' : 'auto';
                    });
                });
                
                deleteBtn.addEventListener('click', () => {
                    if (confirm('Delete this generated page?')) {
                        wrapper.remove();
                        // Delete from database
                        deleteSectionsFromDatabase();
                        setStatus('Page deleted', 'ok');
                    }
                });
                
                // Add section handler
                addBtn.addEventListener('click', () => {
                    // Create and show modal
                    const addSectionModal = document.createElement('div');
                    addSectionModal.className = 'modal';
                    addSectionModal.style.display = 'flex';
                    addSectionModal.innerHTML = `
                        <div class="modal-content" style="max-width: 400px;">
                            <div class="modal-header">
                                <span>Add Section</span>
                                <button class="modal-close" type="button">×</button>
                            </div>
                            <div class="modal-body" style="padding: 20px;">
                                <label style="display: block; font-weight: 600; margin-bottom: 12px;">Section Type</label>
                                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
                                    <button class="section-type-btn" data-type="paragraph" style="padding: 20px; background: rgba(59, 130, 246, 0.1); border: 2px solid rgba(59, 130, 246, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                        <div style="font-size: 32px; margin-bottom: 8px;">📄</div>
                                        <div style="font-weight: 600;">Paragraph</div>
                                    </button>
                                    <button class="section-type-btn" data-type="title" style="padding: 20px; background: rgba(139, 92, 246, 0.1); border: 2px solid rgba(139, 92, 246, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                        <div style="font-size: 32px; margin-bottom: 8px;">📌</div>
                                        <div style="font-weight: 600;">Title</div>
                                    </button>
                                    <button class="section-type-btn" data-type="chart" style="padding: 20px; background: rgba(236, 72, 153, 0.1); border: 2px solid rgba(236, 72, 153, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                        <div style="font-size: 32px; margin-bottom: 8px;">📊</div>
                                        <div style="font-weight: 600;">Chart</div>
                                    </button>
                                    <button class="section-type-btn" data-type="graphic" style="padding: 20px; background: rgba(245, 158, 11, 0.1); border: 2px solid rgba(245, 158, 11, 0.3); border-radius: 8px; cursor: pointer; transition: all 0.2s;">
                                        <div style="font-size: 32px; margin-bottom: 8px;">🖼️</div>
                                        <div style="font-weight: 600;">Image</div>
                                    </button>
                                </div>
                            </div>
                        </div>
                    `;
                    document.body.appendChild(addSectionModal);
                    
                    // Add hover effects
                    const sectionTypeBtns = addSectionModal.querySelectorAll('.section-type-btn');
                    sectionTypeBtns.forEach(btn => {
                        btn.addEventListener('mouseenter', () => {
                            btn.style.transform = 'translateY(-2px)';
                            btn.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
                        });
                        btn.addEventListener('mouseleave', () => {
                            btn.style.transform = '';
                            btn.style.boxShadow = '';
                        });
                        btn.addEventListener('click', () => {
                            const sectionType = btn.dataset.type;
                            
                            // Add new section to the page
                            const newSection = {
                                type: sectionType,
                                height: 20,
                                defaultX: 10,
                                defaultY: sectionsData.length * 20,
                                defaultWidth: 80,
                                name: sectionType.charAt(0).toUpperCase() + sectionType.slice(1)
                            };
                            
                            sectionsData.push(newSection);
                            wrapper.sectionsData = sectionsData;
                            
                            // Recreate overlays
                            const allOverlays = wrapper.querySelectorAll('.section-overlay');
                            allOverlays.forEach(o => o.remove());
                            sectionsData.forEach((s, idx) => createSectionOverlayForRecreated(wrapper, s, idx, sectionsData, pageWidth, pageHeight));
                            
                            // Regenerate canvas
                            regenerateCanvas(wrapper);
                            
                            // Save to database
                            saveSectionsToDatabase(sectionsData, pageWidth, pageHeight);
                            
                            addSectionModal.remove();
                            setStatus('Section added', 'ok');
                        });
                    });
                    
                    // Close modal
                    const closeBtn = addSectionModal.querySelector('.modal-close');
                    closeBtn.addEventListener('click', () => addSectionModal.remove());
                    addSectionModal.addEventListener('click', (e) => {
                        if (e.target === addSectionModal) addSectionModal.remove();
                    });
                });
                
                aiViewer.insertBefore(wrapper, aiViewer.firstChild);
                console.log('Template recreated from database');
            }
            
            // Create section overlay for recreated template (helper function)
            function createSectionOverlayForRecreated(wrapper, section, i, sectionsToRender, pageWidth, pageHeight) {
                const sectionHeight = pageHeight * (section.height / 100);
                const sectionWidth = pageWidth * ((section.defaultWidth || 100) / 100);
                const sectionX = pageWidth * ((section.defaultX || 0) / 100);
                const sectionY = pageHeight * ((section.defaultY || 0) / 100);
                
                const sectionOverlay = document.createElement('div');
                sectionOverlay.className = 'section-overlay';
                sectionOverlay.style.cssText = `position: absolute; left: ${sectionX}px; top: ${sectionY}px; width: ${sectionWidth}px; height: ${sectionHeight}px; cursor: move; border: 2px solid transparent; transition: border-color 0.2s;`;
                sectionOverlay.dataset.sectionIndex = i;
                
                // Add controls panel
                const controlsPanel = document.createElement('div');
                controlsPanel.className = 'section-overlay-controls';
                controlsPanel.style.cssText = 'position: absolute; top: 5px; right: 5px; background: rgba(17, 24, 39, 0.95); border: 1px solid rgba(255,255,255,0.2); border-radius: 6px; padding: 8px; display: none; gap: 6px; align-items: center; z-index: 10; pointer-events: auto;';
                
                controlsPanel.innerHTML = `
                    <button class="delete-section-btn" style="background: rgba(239, 68, 68, 0.9); border: none; color: white; border-radius: 4px; padding: 4px 8px; cursor: pointer; font-size: 11px; font-weight: 600; transition: all 0.2s;" title="Delete section">🗑️</button>
                    <span style="color: #9ca3af; font-size: 11px; font-weight: 600;">X:</span>
                    <input type="number" class="overlay-x-input" value="${section.defaultX || 0}" min="-100" max="200" style="width: 50px; padding: 3px 5px; border: 1px solid rgba(255,255,255,0.2); border-radius: 4px; background: rgba(255,255,255,0.1); color: white; font-size: 11px;">
                    <span style="color: #9ca3af; font-size: 11px; font-weight: 600;">Y:</span>
                    <input type="number" class="overlay-y-input" value="${section.defaultY || 0}" min="-100" max="200" style="width: 50px; padding: 3px 5px; border: 1px solid rgba(255,255,255,0.2); border-radius: 4px; background: rgba(255,255,255,0.1); color: white; font-size: 11px;">
                    <span style="color: #9ca3af; font-size: 11px;">%</span>
                `;
                
                sectionOverlay.appendChild(controlsPanel);
                
                // Add resize handles
                const resizeHandles = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw'];
                resizeHandles.forEach(dir => {
                    const handle = document.createElement('div');
                    handle.className = `resize-handle ${dir} ${['ne', 'nw', 'se', 'sw'].includes(dir) ? 'corner' : 'edge'}`;
                    handle.dataset.direction = dir;
                    sectionOverlay.appendChild(handle);
                });
                
                // Resize functionality
                let isResizing = false;
                let resizeDir = null;
                let resizeStartX, resizeStartY, resizeStartWidth, resizeStartHeight, resizeStartLeft, resizeStartTop;
                
                sectionOverlay.querySelectorAll('.resize-handle').forEach(handle => {
                    handle.addEventListener('mousedown', (e) => {
                        e.stopPropagation();
                        isResizing = true;
                        resizeDir = handle.dataset.direction;
                        resizeStartX = e.clientX;
                        resizeStartY = e.clientY;
                        resizeStartWidth = parseFloat(sectionOverlay.style.width);
                        resizeStartHeight = parseFloat(sectionOverlay.style.height);
                        resizeStartLeft = parseFloat(sectionOverlay.style.left);
                        resizeStartTop = parseFloat(sectionOverlay.style.top);
                        sectionOverlay.style.zIndex = '1000';
                        e.preventDefault();
                    });
                });
                
                document.addEventListener('mousemove', (e) => {
                    if (!isResizing) return;
                    const dx = e.clientX - resizeStartX;
                    const dy = e.clientY - resizeStartY;
                    
                    let newWidth = resizeStartWidth;
                    let newHeight = resizeStartHeight;
                    let newLeft = resizeStartLeft;
                    let newTop = resizeStartTop;
                    
                    // Handle resize based on direction
                    if (resizeDir.includes('e')) {
                        newWidth = Math.max(50, Math.min(resizeStartWidth + dx, pageWidth - resizeStartLeft));
                    }
                    if (resizeDir.includes('w')) {
                        const maxDx = resizeStartLeft;
                        const constrainedDx = Math.min(dx, maxDx);
                        newWidth = Math.max(50, resizeStartWidth - constrainedDx);
                        newLeft = resizeStartLeft + (resizeStartWidth - newWidth);
                    }
                    if (resizeDir.includes('s')) {
                        newHeight = Math.max(30, Math.min(resizeStartHeight + dy, pageHeight - resizeStartTop));
                    }
                    if (resizeDir.includes('n')) {
                        const maxDy = resizeStartTop;
                        const constrainedDy = Math.min(dy, maxDy);
                        newHeight = Math.max(30, resizeStartHeight - constrainedDy);
                        newTop = resizeStartTop + (resizeStartHeight - newHeight);
                    }
                    
                    sectionOverlay.style.width = newWidth + 'px';
                    sectionOverlay.style.height = newHeight + 'px';
                    sectionOverlay.style.left = newLeft + 'px';
                    sectionOverlay.style.top = newTop + 'px';
                });
                
                document.addEventListener('mouseup', () => {
                    if (isResizing) {
                        isResizing = false;
                        sectionOverlay.style.zIndex = '';
                        
                        // Update section data
                        const newWidth = parseFloat(sectionOverlay.style.width);
                        const newHeight = parseFloat(sectionOverlay.style.height);
                        const newLeft = parseFloat(sectionOverlay.style.left);
                        const newTop = parseFloat(sectionOverlay.style.top);
                        
                        sectionsToRender[i].defaultWidth = Math.round((newWidth / pageWidth) * 100);
                        sectionsToRender[i].height = Math.round((newHeight / pageHeight) * 100);
                        sectionsToRender[i].defaultX = Math.round((newLeft / pageWidth) * 100);
                        sectionsToRender[i].defaultY = Math.round((newTop / pageHeight) * 100);
                        
                        // Update input fields
                        xInput.value = sectionsToRender[i].defaultX;
                        yInput.value = sectionsToRender[i].defaultY;
                        
                        regenerateCanvas(wrapper);
                        saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                    }
                });
                
                // Show/hide controls on hover
                sectionOverlay.addEventListener('mouseenter', () => {
                    controlsPanel.style.display = 'flex';
                    sectionOverlay.style.borderColor = '#3b82f6';
                });
                sectionOverlay.addEventListener('mouseleave', () => {
                    controlsPanel.style.display = 'none';
                    sectionOverlay.style.borderColor = 'transparent';
                });
                
                // Delete button
                const deleteBtn = controlsPanel.querySelector('.delete-section-btn');
                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    if (confirm('Delete this section?')) {
                        sectionsToRender.splice(i, 1);
                        wrapper.sectionsData = sectionsToRender;
                        sectionOverlay.remove();
                        regenerateCanvas(wrapper);
                        const allOverlays = wrapper.querySelectorAll('.section-overlay');
                        allOverlays.forEach(o => o.remove());
                        sectionsToRender.forEach((s, idx) => createSectionOverlayForRecreated(wrapper, s, idx, sectionsToRender, pageWidth, pageHeight));
                        saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                    }
                });
                
                // X/Y input handlers
                const xInput = controlsPanel.querySelector('.overlay-x-input');
                const yInput = controlsPanel.querySelector('.overlay-y-input');
                
                xInput.addEventListener('input', (e) => {
                    const newX = parseInt(e.target.value) || 0;
                    const newLeft = (newX / 100) * pageWidth;
                    sectionOverlay.style.left = newLeft + 'px';
                    sectionsToRender[i].defaultX = newX;
                    regenerateCanvas(wrapper);
                    saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                });
                
                yInput.addEventListener('input', (e) => {
                    const newY = parseInt(e.target.value) || 0;
                    const newTop = (newY / 100) * pageHeight;
                    sectionOverlay.style.top = newTop + 'px';
                    sectionsToRender[i].defaultY = newY;
                    regenerateCanvas(wrapper);
                    saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                });
                
                // Drag functionality
                let isDragging = false;
                let startX, startY, offsetX, offsetY;
                
                sectionOverlay.addEventListener('mousedown', (e) => {
                    isDragging = true;
                    startX = e.clientX;
                    startY = e.clientY;
                    offsetX = parseFloat(sectionOverlay.style.left) || 0;
                    offsetY = parseFloat(sectionOverlay.style.top) || 0;
                    sectionOverlay.style.zIndex = '1000';
                    sectionOverlay.style.borderColor = '#3b82f6';
                    e.preventDefault();
                });
                
                document.addEventListener('mousemove', (e) => {
                    if (!isDragging) return;
                    const dx = e.clientX - startX;
                    const dy = e.clientY - startY;
                    let newLeft = offsetX + dx;
                    let newTop = offsetY + dy;
                    
                    // Constrain to page boundaries
                    const sectionWidth = parseFloat(sectionOverlay.style.width);
                    const sectionHeight = parseFloat(sectionOverlay.style.height);
                    newLeft = Math.max(0, Math.min(newLeft, pageWidth - sectionWidth));
                    newTop = Math.max(0, Math.min(newTop, pageHeight - sectionHeight));
                    
                    sectionOverlay.style.left = newLeft + 'px';
                    sectionOverlay.style.top = newTop + 'px';
                    const newX = Math.round((newLeft / pageWidth) * 100);
                    const newY = Math.round((newTop / pageHeight) * 100);
                    xInput.value = newX;
                    yInput.value = newY;
                });
                
                document.addEventListener('mouseup', () => {
                    if (isDragging) {
                        isDragging = false;
                        sectionOverlay.style.zIndex = '';
                        sectionOverlay.style.borderColor = 'transparent';
                        const newX = (parseFloat(sectionOverlay.style.left) / pageWidth) * 100;
                        const newY = (parseFloat(sectionOverlay.style.top) / pageHeight) * 100;
                        sectionsToRender[i].defaultX = Math.round(newX);
                        sectionsToRender[i].defaultY = Math.round(newY);
                        regenerateCanvas(wrapper);
                        saveSectionsToDatabase(sectionsToRender, pageWidth, pageHeight);
                    }
                });
                
                wrapper.appendChild(sectionOverlay);
            }
            
            // Load AI generated content from localStorage
            function loadAIContentFromLocalStorage() {
                const storageKey = `ai-generated-content-${documentId}`;
                try {
                    const stored = localStorage.getItem(storageKey);
                    if (stored) {
                        const generatedSections = JSON.parse(stored);
                        
                        // Apply content to any existing generated pages
                        const aiViewer = document.getElementById('ai-viewer');
                        const generatedPages = aiViewer ? aiViewer.querySelectorAll('.generated-page') : [];
                        
                        if (generatedPages.length > 0) {
                            renderContentIntoSections(generatedSections, []);
                        }
                    }
                } catch (e) {
                    console.error('Failed to load AI content from localStorage:', e);
                }
            }
            
            // Send message
            function sendChatMessage(confirmed = false, costPayload = null) {
                if (!confirmed && (!aiChatInput || !aiChatInput.value.trim())) return;
                
                const userMessage = confirmed && costPayload ? costPayload.prompt : (aiChatInput ? aiChatInput.value.trim() : '');
                
                if (!confirmed) {
                    addChatMessage(userMessage, true);
                    
                    // Clear input
                    aiChatInput.value = '';
                    aiChatInput.style.height = 'auto';
                }
                
                // Collect sections data from generated pages in AI viewer
                const aiViewer = document.getElementById('ai-viewer');
                const generatedPages = aiViewer ? aiViewer.querySelectorAll('.generated-page') : [];
                
                let allSections = [];
                let templateType = selectedLayout || 'custom';
                
                generatedPages.forEach((page, pageIndex) => {
                    if (page.sectionsData) {
                        const pageWidth = page.pageWidth;
                        const pageHeight = page.pageHeight;
                        
                        page.sectionsData.forEach((section, sectionIndex) => {
                            allSections.push({
                                type: section.type || 'text',
                                name: section.name || section.type || 'Section',
                                height: section.height || 0,
                                width: section.defaultWidth || 100,
                                x: section.defaultX || 0,
                                y: section.defaultY || 0,
                                order: pageIndex * 100 + sectionIndex,
                                page: pageIndex + 1,
                                dimensions: {
                                    pageWidth: pageWidth,
                                    pageHeight: pageHeight,
                                    sectionWidthPx: pageWidth * ((section.defaultWidth || 100) / 100),
                                    sectionHeightPx: pageHeight * (section.height / 100),
                                    sectionXPx: pageWidth * ((section.defaultX || 0) / 100),
                                    sectionYPx: pageHeight * ((section.defaultY || 0) / 100)
                                }
                            });
                        });
                    }
                });
                
                // Prepare payload with custom prompt settings
                const payload = costPayload || {
                    prompt: userMessage,
                    template: templateType,
                    document_id: documentId,
                    sections: allSections,
                    model: 'gpt-4',
                    prompt_settings: promptSettings, // Include custom prompt settings
                    confirmed: confirmed
                };
                
                // Send to backend
                fetch('/ai/chat', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Accept': 'application/json',
                        'X-CSRF-TOKEN': csrfToken
                    },
                    body: JSON.stringify(payload)
                })
                .then(response => {
                    if (!response.ok) {
                        return response.json().then(err => {
                            throw new Error(err.message || 'Request failed');
                        });
                    }
                    return response.json();
                })
                .then(data => {
                    // Check if cost confirmation is required
                    if (data.requires_confirmation) {
                        showCostConfirmationModal(data.cost_estimate, payload);
                        return;
                    }
                    
                    if (data.success) {
                        // Use the parsed sections from the backend
                        const parsedSections = data.data.parsed_sections;
                        const generatedImages = data.data.generated_images || [];
                        
                        if (parsedSections && parsedSections.sections && Array.isArray(parsedSections.sections)) {
                            // Display formatted sections
                            const sectionsSummary = parsedSections.sections.map((s, i) => 
                                `\n${i + 1}. ${s.type}: ${s.content.substring(0, 100)}...`
                            ).join('');
                            
                            let message = `Generated content for ${parsedSections.sections.length} sections:${sectionsSummary}`;
                            if (generatedImages.length > 0) {
                                message += `\n\n🖼️ Generated ${generatedImages.length} images`;
                            }
                            addChatMessage(message, false);
                            
                            // Render the content into the generated page sections
                            renderContentIntoSections(parsedSections.sections, allSections, generatedImages);
                        } else if (parsedSections && parsedSections.raw_response) {
                            // Fallback to raw response if parsing failed
                            addChatMessage(parsedSections.raw_response, false);
                        } else {
                            // Fallback to generated content
                            addChatMessage(data.data.generated_content || 'Content generated successfully', false);
                        }
                    } else {
                        addChatMessage('Error processing your request', false);
                    }
                })
                .catch(error => {
                    console.error('Error:', error);
                    addChatMessage(`Error: ${error.message || 'Could not connect to AI service'}`, false);
                });
            }
            
            // Show cost confirmation modal
            function showCostConfirmationModal(costEstimate, originalPayload) {
                const modal = document.getElementById('cost-confirmation-modal');
                
                // Populate cost data
                document.getElementById('cost-total').textContent = costEstimate.total_cost_usd.toFixed(4);
                document.getElementById('cost-text').textContent = costEstimate.text_generation.cost_usd.toFixed(6);
                document.getElementById('cost-images').textContent = costEstimate.image_generation.cost_usd.toFixed(4);
                document.getElementById('cost-image-count').textContent = costEstimate.image_generation.count;
                document.getElementById('cost-input-tokens').textContent = costEstimate.text_generation.input_tokens.toLocaleString();
                document.getElementById('cost-output-tokens').textContent = costEstimate.text_generation.output_tokens.toLocaleString();
                document.getElementById('cost-total-tokens').textContent = costEstimate.text_generation.total_tokens.toLocaleString();
                
                // Show modal
                modal.style.display = 'flex';
                
                // Set up confirm button
                const confirmBtn = document.getElementById('cost-modal-confirm');
                const cancelBtn = document.getElementById('cost-modal-cancel');
                const closeBtn = document.getElementById('cost-modal-close');
                
                const confirmHandler = () => {
                    modal.style.display = 'none';
                    originalPayload.confirmed = true;
                    sendChatMessage(true, originalPayload);
                    cleanup();
                };
                
                const cancelHandler = () => {
                    modal.style.display = 'none';
                    addChatMessage('Request cancelled', false);
                    cleanup();
                };
                
                const cleanup = () => {
                    confirmBtn.removeEventListener('click', confirmHandler);
                    cancelBtn.removeEventListener('click', cancelHandler);
                    closeBtn.removeEventListener('click', cancelHandler);
                };
                
                confirmBtn.addEventListener('click', confirmHandler);
                cancelBtn.addEventListener('click', cancelHandler);
                closeBtn.addEventListener('click', cancelHandler);
            }
            
            // Event listeners
            if (aiSendBtn) {
                aiSendBtn.addEventListener('click', sendChatMessage);
            }
            
            if (aiChatInput) {
                aiChatInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        sendChatMessage();
                    }
                });
            }
            
            if (aiAttachBtn) {
                aiAttachBtn.addEventListener('click', () => {
                    // Placeholder for attach functionality
                    console.log('Attach button clicked');
                });
            }
            
            // Request History functionality
            const historyToggle = document.getElementById('history-toggle');
            const historyContent = document.getElementById('history-content');
            const historyHeader = document.getElementById('history-header');
            const historyList = document.getElementById('history-list');
            
            if (historyToggle && historyHeader) {
                historyHeader.addEventListener('click', () => {
                    const isOpen = historyContent.style.display === 'block';
                    historyContent.style.display = isOpen ? 'none' : 'block';
                    historyToggle.classList.toggle('open', !isOpen);
                    
                    // Load history when opening
                    if (!isOpen) {
                        loadRequestHistory();
                    }
                });
            }
            
            async function loadRequestHistory() {
                try {
                    const response = await fetch(`/ai/price-log?document_id=${documentId}`, {
                        headers: {
                            'Accept': 'application/json',
                            'X-CSRF-TOKEN': csrfToken
                        }
                    });
                    
                    const data = await response.json();
                    
                    if (data.success && data.logs) {
                        displayRequestHistory(data.logs);
                    }
                } catch (error) {
                    console.error('Error loading request history:', error);
                }
            }
            
            function displayRequestHistory(logs) {
                if (!historyList) return;
                
                if (logs.length === 0) {
                    historyList.innerHTML = '<div style="padding: 16px; text-align: center; color: #9ca3af; font-size: 13px;">No requests yet</div>';
                    return;
                }
                
                historyList.innerHTML = logs.map(log => {
                    const date = new Date(log.created_at);
                    const cost = parseFloat(log.cost_usd || log.estimated_cost_usd || 0);
                    
                    return `
                        <div class="history-item">
                            <div class="history-item-header">
                                <div class="history-item-cost">$${cost.toFixed(4)}</div>
                                <div class="history-item-date">${date.toLocaleDateString()} ${date.toLocaleTimeString()}</div>
                            </div>
                            <div class="history-item-prompt">${log.prompt_preview || 'No prompt'}</div>
                            <div class="history-item-stats">
                                <div class="history-item-stat">
                                    <span>📝</span>
                                    <span>${(log.total_tokens || 0).toLocaleString()} tokens</span>
                                </div>
                                ${log.image_count > 0 ? `
                                <div class="history-item-stat">
                                    <span>🖼️</span>
                                    <span>${log.image_count} images</span>
                                </div>
                                ` : ''}
                            </div>
                        </div>
                    `;
                }).join('');
            }
            
            // Add to PDF functionality
            const addToPdfBtn = document.getElementById('ai-add-to-pdf-btn');
            
            if (addToPdfBtn) {
                addToPdfBtn.addEventListener('click', async () => {
                    const aiViewer = document.getElementById('ai-viewer');
                    const generatedPages = aiViewer ? aiViewer.querySelectorAll('.generated-page') : [];
                    
                    if (generatedPages.length === 0) {
                        alert('No pages to add. Generate content first.');
                        return;
                    }
                    
                    // Collect canvas data from all generated pages
                    const images = [];
                    for (const page of generatedPages) {
                        const canvas = page.querySelector('canvas');
                        if (canvas) {
                            images.push(canvas.toDataURL('image/png').split(',')[1]); // Get base64 without prefix
                        }
                    }
                    
                    if (images.length === 0) {
                        alert('No content to add.');
                        return;
                    }
                    
                    try {
                        addToPdfBtn.disabled = true;
                        addToPdfBtn.textContent = 'Adding...';
                        
                        const response = await fetch('/ai/add-to-pdf', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'Accept': 'application/json',
                                'X-CSRF-TOKEN': csrfToken
                            },
                            body: JSON.stringify({
                                document_id: documentId,
                                images: images
                            })
                        });
                        
                        const data = await response.json();
                        
                        if (data.success) {
                            alert(`Successfully added ${data.pages_added} pages to PDF! Reloading document...`);
                            // Reload the page to show the updated PDF
                            window.location.reload();
                        } else {
                            alert('Error: ' + (data.message || 'Failed to add pages to PDF'));
                            console.error('Add to PDF error:', data);
                        }
                    } catch (error) {
                        console.error('Error adding to PDF:', error);
                        alert('Error adding pages to PDF: ' + error.message);
                    } finally {
                        addToPdfBtn.disabled = false;
                        addToPdfBtn.innerHTML = `
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="margin-right: 8px;">
                                <path d="M12 5v14M5 12h14"/>
                            </svg>
                            Add to PDF
                        `;
                    }
                });
            }

            // ─── Shared: Capture guided card as clean HTML for PDF ─────
            function captureCardHtml(cardId) {
                const original = document.getElementById(cardId);
                if (!original) return '<body><p>Card not found</p></body>';

                // Sync ALL input/textarea values into attributes BEFORE cloning
                // (cloneNode does not capture user-typed values)
                original.querySelectorAll('input').forEach(inp => {
                    if (inp.type === 'checkbox' || inp.type === 'radio') {
                        if (inp.checked) inp.setAttribute('checked', '');
                        else inp.removeAttribute('checked');
                    } else {
                        inp.setAttribute('value', inp.value);
                    }
                });
                original.querySelectorAll('textarea').forEach(ta => {
                    ta.textContent = ta.value;
                });
                original.querySelectorAll('select').forEach(sel => {
                    [...sel.options].forEach(opt => {
                        if (opt.selected) opt.setAttribute('selected', '');
                        else opt.removeAttribute('selected');
                    });
                });

                // Deep clone so we don't touch the live DOM
                const clone = original.cloneNode(true);

                // 1. Replace every <input> with a <span> showing its value
                clone.querySelectorAll('input').forEach(inp => {
                    if (inp.type === 'hidden' || inp.type === 'file') {
                        inp.remove();
                        return;
                    }
                    const val = inp.getAttribute('value') || '';

                    const span = document.createElement('div'); // Use div to behave like a block/width:100% input
                    span.textContent = val;
                    // Carry over the inline styles that matter for appearance
                    span.style.cssText = inp.style.cssText;
                    // Remove input-specific styles
                    span.style.border = 'none';
                    span.style.outline = 'none';
                    span.style.background = 'transparent';
                    span.style.padding = '0';
                    span.style.minHeight = '1.2em'; // Ensure empty inputs don't collapse
                    
                    // Essential for alignment: keep width 100% so text-align works
                    if (inp.style.width === '100%') {
                        span.style.width = '100%';
                        span.style.display = 'block';
                    } else {
                        span.style.display = 'inline-block';
                    }
                    
                    inp.replaceWith(span);
                });

                // 2. Replace every <textarea> with a <div> showing its value
                clone.querySelectorAll('textarea').forEach(ta => {
                    const val = ta.textContent || '';

                    const div = document.createElement('div');
                    // Pre-wrap to preserve newlines
                    div.style.whiteSpace = 'pre-wrap';
                    div.textContent = val;
                    div.style.cssText = ta.style.cssText;
                    div.style.border = 'none';
                    div.style.outline = 'none';
                    div.style.resize = 'none';
                    div.style.overflow = 'visible';
                    div.style.height = 'auto';
                    div.style.minHeight = '1.2em';
                    ta.replaceWith(div);
                });

                // 3. Remove all <button> elements (Add Line Item, Save, etc.)
                clone.querySelectorAll('button').forEach(btn => btn.remove());

                // 4. Remove elements that are display:none (hidden sections)
                clone.querySelectorAll('[style]').forEach(el => {
                    if (el.style.display === 'none') el.remove();
                });

                // 5. Remove file input areas / logo placeholders if no image
                clone.querySelectorAll('input[type="file"]').forEach(f => f.remove());
                const logoArea = clone.querySelector('#gi-logo-area');
                if (logoArea) {
                    const preview = logoArea.querySelector('#gi-logo-preview');
                    if (!preview || preview.style.display === 'none' || !preview.src) {
                        logoArea.remove();
                    } else {
                        // Keep just the image
                        const placeholder = logoArea.querySelector('#gi-logo-placeholder');
                        if (placeholder) placeholder.remove();
                    }
                }

                // 6. Remove the last × (remove row) column cells
                clone.querySelectorAll('.gi-remove-row, .gpo-remove-row, .gn-remove-row, .gnda-remove-row').forEach(el => {
                    const td = el.closest('td');
                    if (td) td.remove();
                    else el.remove();
                });
                // Also remove empty trailing <th> cells used for the × column
                clone.querySelectorAll('th').forEach(th => {
                    if (th.style.background === 'transparent' && th.textContent.trim() === '') th.remove();
                });

                // 7. Remove action button containers (the flex row with Save/Open in Editor)
                // They are the last div children that contained our buttons (now empty)
                clone.querySelectorAll('div').forEach(div => {
                    if (div.children.length === 0 && div.textContent.trim() === '' && div.style.display === 'flex' && div.style.justifyContent) {
                        div.remove();
                    }
                });

                // 8. Remove the discount row add buttons area and paid toggle if still there
                const paidSection = clone.querySelector('#gi-paid-section');
                if (paidSection) paidSection.remove();

                // 9. Second pass: remove remaining empty containers left after button removal
                clone.querySelectorAll('div').forEach(div => {
                    if (div.children.length === 0 && div.textContent.trim() === '') {
                        const bg = div.style.background || div.style.backgroundColor;
                        const hasBorder = div.style.borderBottom || div.style.borderTop;
                        if ((!bg || bg === 'transparent') && !hasBorder) {
                            div.remove();
                        }
                    }
                });

                // 10. Replace <select> elements with their selected value
                clone.querySelectorAll('select').forEach(sel => {
                    const span = document.createElement('span');
                    const selectedOpt = sel.querySelector('option[selected]') || sel.options?.[0];
                    span.textContent = selectedOpt ? selectedOpt.textContent : '';
                    span.style.cssText = sel.style.cssText;
                    span.style.border = 'none';
                    span.style.background = 'transparent';
                    sel.replaceWith(span);
                });

                // 11. Strip IDs from the clone (not needed in PDF)
                clone.querySelectorAll('[id]').forEach(el => el.removeAttribute('id'));

                // Get the computed font family from the card to preserve toolbar changes
                const computedFont = getComputedStyle(original).fontFamily;

                // Build the final HTML with the card's own styles, minus screen-only decoration
                let cardStyle = original.getAttribute('style') || '';
                // Remove screen-only props
                cardStyle = cardStyle
                    .replace(/box-shadow:[^;]+;?/gi, '')
                    .replace(/border-radius:[^;]+;?/gi, '')
                    .replace(/overflow:[^;]+;?/gi, '')
                    .replace(/max-width:[^;]+;?/gi, '');

                return '<body style="' + cardStyle.replace(/"/g, "'") + 'font-family:' + computedFont + ';">'
                     + clone.innerHTML
                     + '</body>';
            }

            function collectFormData(cardId) {
                // Collect the current state of all inputs in the card to save to DB
                const card = document.getElementById(cardId);
                if (!card) return {};
                
                const data = {};
                
                // Collect standard inputs
                card.querySelectorAll('input, textarea, select').forEach(el => {
                    if (el.type === 'file') return; // Skip files
                    if (el.type === 'button' || el.type === 'submit') return;
                    
                    const name = el.id || el.name;
                    if (!name) return;
                    
                    if (el.type === 'checkbox' || el.type === 'radio') {
                        data[name] = el.checked;
                    } else {
                        data[name] = el.value;
                    }
                });

                // Special handling for dynamic line items which might not have unique global IDs
                // Maybe store them as an array if needed, but for now our IDs (gi_desc_1 etc) are not fully reliable 
                // unless we add them. 
                // For simplicity, let's just make sure we capture everything with an ID.
                // If line items are recreated dynamically, they need unique IDs to be restored correctly.
                
                return data;
            }

            function restoreFormData(cardId, data) {
                if (!data) return;
                const card = document.getElementById(cardId);
                if (!card) return;

                Object.keys(data).forEach(key => {
                    const el = document.getElementById(key);
                    if (el) {
                        if (el.type === 'checkbox' || el.type === 'radio') {
                            el.checked = data[key];
                            // Trigger change events if needed (e.g. for paid toggle)
                            el.dispatchEvent(new Event('change'));
                            el.dispatchEvent(new Event('click')); // Some toggles use click
                        } else {
                            el.value = data[key];
                            // Trigger input events for recalc
                            el.dispatchEvent(new Event('input'));
                        }
                    }
                });
            }

            // ─── Guided Templates ──────────────────────────────────────────
            (function guidedInvoiceInit() {
                const lineItemsBody = document.getElementById('gi-line-items-body');
                const addLineBtn = document.getElementById('gi-add-line-item');
                const addDiscountBtn = document.getElementById('gi-add-discount');
                const discountRow = document.getElementById('gi-discount-row');
                const discountAmountInput = document.getElementById('gi-discount-amount');
                const totalDisplay = document.getElementById('gi-total-display');
                const saveBtn = document.getElementById('gi-save-btn');
                const logoArea = document.getElementById('gi-logo-area');
                const logoInput = document.getElementById('gi-logo-input');
                const logoPreview = document.getElementById('gi-logo-preview');
                const logoPlaceholder = document.getElementById('gi-logo-placeholder');

                if (!lineItemsBody) return; // Safety

                const _urlParams = new URLSearchParams(window.location.search);
                const _guidedStyle = _urlParams.get('style') || @json($templateSlug ?? 'default');
                const _isBoldRed = _guidedStyle === 'bold_red';

                let lineItemIndex = 0;

                function createLineItemRow(qty, desc, price) {
                    const tr = document.createElement('tr');
                    tr.style.borderBottom = '1px solid #f3f4f6';
                    tr.dataset.lineItem = 'true';
                    const idx = lineItemIndex++;
                    tr.innerHTML = `
                        <td style="padding:10px 14px;">
                            <input type="number" class="gi-qty" value="${qty}" min="0" step="1"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; text-align:center; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px;">
                            <input type="text" class="gi-desc" value="${desc}" placeholder="Item description"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px;">
                            <input type="number" class="gi-unit-price" value="${price}" min="0" step="0.01"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; text-align:right; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px; text-align:right; font-size:14px; font-weight:500; color:#1f2937;" class="gi-amount">
                            $0.00
                        </td>
                        <td style="padding:6px 4px; vertical-align:middle;">
                            <button type="button" class="gi-remove-row" style="background:none; border:none; cursor:pointer; color:#9ca3af; font-size:18px; padding:4px;" title="Remove">
                                &times;
                            </button>
                        </td>
                    `;
                    // Events
                    tr.querySelector('.gi-qty').addEventListener('input', recalcAll);
                    tr.querySelector('.gi-unit-price').addEventListener('input', recalcAll);
                    tr.querySelector('.gi-remove-row').addEventListener('click', () => {
                        tr.remove();
                        recalcAll();
                    });
                    return tr;
                }

                function recalcAll() {
                    let subtotal = 0;
                    lineItemsBody.querySelectorAll('tr[data-line-item]').forEach(tr => {
                        const qty = parseFloat(tr.querySelector('.gi-qty').value) || 0;
                        const price = parseFloat(tr.querySelector('.gi-unit-price').value) || 0;
                        const amount = qty * price;
                        tr.querySelector('.gi-amount').textContent = '$' + amount.toFixed(2);
                        subtotal += amount;
                    });
                    const discount = parseFloat(discountAmountInput.value) || 0;
                    const total = Math.max(subtotal - discount, 0);
                    totalDisplay.textContent = '$' + total.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
                }

                // Add first row
                lineItemsBody.appendChild(createLineItemRow(1, '', 0));
                recalcAll();

                addLineBtn.addEventListener('click', () => {
                    lineItemsBody.appendChild(createLineItemRow(1, '', 0));
                });

                addDiscountBtn.addEventListener('click', () => {
                    discountRow.style.display = discountRow.style.display === 'none' ? '' : 'none';
                });
                discountAmountInput.addEventListener('input', recalcAll);

                // Mark as Paid toggle
                const paidToggle = document.getElementById('gi-paid-toggle');
                const paidCheck = document.getElementById('gi-paid-check');
                const paidCheckIcon = document.getElementById('gi-paid-check-icon');
                const paidStamp = document.getElementById('gi-paid-stamp');
                if (paidToggle) {
                    paidToggle.addEventListener('click', () => {
                        const isActive = !paidToggle.dataset.active;
                        if (isActive) {
                            paidToggle.dataset.active = '1';
                            paidToggle.style.borderColor = '#dc2626';
                            paidToggle.style.background = '#fef2f2';
                            paidCheck.style.background = '#dc2626';
                            paidCheck.style.borderColor = '#dc2626';
                            paidCheckIcon.style.display = '';
                            paidStamp.style.display = '';
                        } else {
                            delete paidToggle.dataset.active;
                            paidToggle.style.borderColor = '#d1d5db';
                            paidToggle.style.background = 'transparent';
                            paidCheck.style.background = 'transparent';
                            paidCheck.style.borderColor = '#d1d5db';
                            paidCheckIcon.style.display = 'none';
                            paidStamp.style.display = 'none';
                        }
                    });
                }

                // Logo upload
                logoInput.addEventListener('change', (e) => {
                    const file = e.target.files[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = (ev) => {
                        logoPreview.src = ev.target.result;
                        logoPreview.style.display = '';
                        logoPlaceholder.style.display = 'none';
                    };
                    reader.readAsDataURL(file);
                });

                // Collect invoice payload
                async function generateInvoice(btn, openInEditor) {
                    const html = captureCardHtml('guided-invoice-card');
                    const formData = collectFormData('guided-invoice-card');
                    const origHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin-icon"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg> Generating…`;

                    try {
                        const docId = @json($document->id);
                        const resp = await fetch(`/documents/${docId}/convert-html-to-pdf`, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                                'Accept': 'application/json',
                            },
                            body: JSON.stringify({ html: html, form_data: formData }),
                        });

                        if (!resp.ok) {
                            const err = await resp.json().catch(() => ({}));
                            throw new Error(err.error || 'Generation failed');
                        }

                        if (openInEditor) {
                            window.location.href = @json(route('documents.edit', $document));
                        } else {
                            window.open(`/documents/${docId}/file`, '_blank');
                        }
                        return;
                    } catch (err) {
                        console.error('Invoice generation error:', err);
                        alert('Error: ' + err.message);
                    } finally {
                        btn.disabled = false;
                        btn.innerHTML = origHtml;
                    }
                }

                // Save & Generate PDF → open in new tab
                saveBtn.addEventListener('click', () => generateInvoice(saveBtn, false));

                // Open in Editor → generate then navigate to editor
                const giOpenEditorBtn = document.getElementById('gi-open-editor-btn');
                if (giOpenEditorBtn) {
                    giOpenEditorBtn.addEventListener('click', () => generateInvoice(giOpenEditorBtn, true));
                }

                // Style-aware theming (read style from URL query param or saved slug)
                const urlParams = new URLSearchParams(window.location.search);
                const guidedStyle = urlParams.get('style') || @json($templateSlug ?? 'default');

                if (guidedStyle === 'bold_red') {
                    const RED = '#cc3333';
                    const RED_DARK = '#a82828';

                    // Show bold red header, hide default header + title
                    const boldHeader = document.getElementById('gi-bold-header');
                    const defaultHeader = document.getElementById('gi-default-header');
                    const defaultTitle = document.getElementById('gi-default-title');
                    if (boldHeader) boldHeader.style.display = '';
                    if (defaultHeader) defaultHeader.style.display = 'none';
                    if (defaultTitle) defaultTitle.style.display = 'none';

                    // Sync bold-red header inputs with the default ones (so save still works)
                    const brName = document.getElementById('gi-company-name-br');
                    const brAddr1 = document.getElementById('gi-company-addr1-br');
                    const brAddr2 = document.getElementById('gi-company-addr2-br');
                    const defName = document.getElementById('gi-company-name');
                    const defAddr1 = document.getElementById('gi-company-addr1');
                    const defAddr2 = document.getElementById('gi-company-addr2');
                    if (brName && defName) {
                        brName.addEventListener('input', () => defName.value = brName.value);
                        brAddr1.addEventListener('input', () => defAddr1.value = brAddr1.value);
                        brAddr2.addEventListener('input', () => defAddr2.value = brAddr2.value);
                        // Init sync
                        defName.value = brName.value;
                        defAddr1.value = brAddr1.value;
                        defAddr2.value = brAddr2.value;
                    }

                    // Bill To label → red
                    const billToLabel = document.getElementById('gi-bill-to-label');
                    if (billToLabel) billToLabel.style.color = RED;

                    // Invoice meta labels → red
                    document.querySelectorAll('.gi-meta-label').forEach(el => {
                        el.style.color = RED;
                    });

                    // Table header → red background
                    const tableHeader = document.getElementById('gi-table-header');
                    if (tableHeader) tableHeader.style.background = RED;

                    // Add Line Item button → red
                    const addLineBtn2 = document.getElementById('gi-add-line-item');
                    if (addLineBtn2) {
                        addLineBtn2.style.background = RED;
                        addLineBtn2.style.color = '#fff';
                    }

                    // Add Discount button → red outline
                    const addDiscBtn = document.getElementById('gi-add-discount');
                    if (addDiscBtn) {
                        addDiscBtn.style.color = RED;
                        addDiscBtn.style.borderColor = RED;
                    }

                    // Totals bar → red border, red total row with white text on red bg
                    const totalsBar = document.getElementById('gi-totals-bar');
                    if (totalsBar) {
                        totalsBar.style.borderTopColor = RED;
                    }
                    const totalRow = document.getElementById('gi-total-row');
                    if (totalRow) {
                        totalRow.style.background = RED;
                        totalRow.style.color = '#fff';
                        totalRow.style.padding = '10px 14px';
                        totalRow.style.borderRadius = '6px';
                        totalRow.style.marginTop = '4px';
                    }

                    // Terms label → red
                    const termsLabel = document.getElementById('gi-terms-label');
                    if (termsLabel) termsLabel.style.color = RED;

                    // Save button → red
                    if (saveBtn) {
                        saveBtn.style.background = RED;
                    }

                    // Card top border-radius flush with header
                    const card = document.getElementById('guided-invoice-card');
                    if (card) {
                        card.style.paddingTop = '0';
                        card.style.overflow = 'hidden';
                    }

                    // Update the bold header padding to account for card padding removal
                    if (boldHeader) {
                        boldHeader.style.margin = '0 -48px 24px -48px';
                        boldHeader.style.borderRadius = '12px 12px 0 0';
                    }
                }
            })();

            // ─── Guided Toolbar Wiring ──────────────────────────────────────
            (function guidedToolbarInit() {
                const toolbar = document.getElementById('guided-toolbar');
                if (!toolbar) return;

                const fontFamilySel = document.getElementById('gt-font-family');
                const fontSizeSel = document.getElementById('gt-font-size');
                const textColorInput = document.getElementById('gt-text-color');
                const colorIndicator = document.getElementById('gt-color-indicator');
                const signBtn = document.getElementById('gt-sign-btn');

                // Track the last focused input/textarea in a guided card
                let lastFocusedEl = null;
                const guidedContainer = document.getElementById('guided-invoice');
                if (guidedContainer) {
                    guidedContainer.addEventListener('focusin', (e) => {
                        const tag = e.target.tagName;
                        if (tag === 'INPUT' || tag === 'TEXTAREA') {
                            lastFocusedEl = e.target;
                            // Sync toolbar state from element
                            if (fontFamilySel && e.target.style.fontFamily) {
                                fontFamilySel.value = e.target.style.fontFamily || fontFamilySel.value;
                            }
                            if (fontSizeSel && e.target.style.fontSize) {
                                fontSizeSel.value = parseInt(e.target.style.fontSize) || fontSizeSel.value;
                            }
                        }
                    });
                }

                // Apply font family to focused element only
                if (fontFamilySel) {
                    fontFamilySel.addEventListener('change', () => {
                        if (lastFocusedEl) {
                            lastFocusedEl.style.fontFamily = fontFamilySel.value;
                            lastFocusedEl.focus();
                        }
                    });
                }

                // Apply font size to focused element only
                if (fontSizeSel) {
                    fontSizeSel.addEventListener('change', () => {
                        if (lastFocusedEl) {
                            lastFocusedEl.style.fontSize = fontSizeSel.value + 'px';
                            lastFocusedEl.focus();
                        }
                    });
                }

                // Text color → focused element only
                if (textColorInput && colorIndicator) {
                    textColorInput.addEventListener('input', () => {
                        colorIndicator.style.background = textColorInput.value;
                        if (lastFocusedEl) {
                            lastFocusedEl.style.color = textColorInput.value;
                            lastFocusedEl.focus();
                        }
                    });
                }

                // Bold toggle → focused element
                const boldBtn = document.getElementById('gt-bold');
                if (boldBtn) {
                    boldBtn.addEventListener('click', () => {
                        if (!lastFocusedEl) return;
                        const isBold = lastFocusedEl.style.fontWeight === '700' || lastFocusedEl.style.fontWeight === 'bold';
                        lastFocusedEl.style.fontWeight = isBold ? 'normal' : '700';
                        boldBtn.style.background = isBold ? 'transparent' : 'rgba(255,255,255,0.15)';
                        lastFocusedEl.focus();
                    });
                }

                // Italic toggle → focused element
                const italicBtn = document.getElementById('gt-italic');
                if (italicBtn) {
                    italicBtn.addEventListener('click', () => {
                        if (!lastFocusedEl) return;
                        const isItalic = lastFocusedEl.style.fontStyle === 'italic';
                        lastFocusedEl.style.fontStyle = isItalic ? 'normal' : 'italic';
                        italicBtn.style.background = isItalic ? 'transparent' : 'rgba(255,255,255,0.15)';
                        lastFocusedEl.focus();
                    });
                }

                // Underline toggle → focused element
                const underlineBtn = document.getElementById('gt-underline');
                if (underlineBtn) {
                    underlineBtn.addEventListener('click', () => {
                        if (!lastFocusedEl) return;
                        const isUnder = lastFocusedEl.style.textDecoration === 'underline';
                        lastFocusedEl.style.textDecoration = isUnder ? 'none' : 'underline';
                        underlineBtn.style.background = isUnder ? 'transparent' : 'rgba(255,255,255,0.15)';
                        lastFocusedEl.focus();
                    });
                }

                // Sign button → open signature modal
                if (signBtn) {
                    signBtn.addEventListener('click', () => {
                        if (typeof openSignatureModal === 'function') {
                            openSignatureModal();
                        } else {
                            const modal = document.getElementById('signature-modal');
                            if (modal) modal.style.display = 'flex';
                        }
                    });
                }

                // Save button → save form data only (no PDF generation)
                const saveFormBtn = document.getElementById('gt-save-form-btn');
                if (saveFormBtn) {
                    saveFormBtn.addEventListener('click', async () => {
                        // Determine which card is active
                        const cardIds = ['guided-invoice-card', 'guided-newsletter-card', 'guided-nda-card', 'guided-po-card'];
                        let activeCardId = null;
                        let formData = {};
                        for (const cid of cardIds) {
                            const card = document.getElementById(cid);
                            if (card) {
                                activeCardId = cid;
                                formData = collectFormData(cid);
                                break;
                            }
                        }

                        if (!activeCardId || !formData || Object.keys(formData).length === 0) {
                            alert('No form data to save.');
                            return;
                        }

                        const origHtml = saveFormBtn.innerHTML;
                        saveFormBtn.disabled = true;
                        saveFormBtn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin-icon"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg> Saving…`;

                        try {
                            const docId = @json($document->id);
                            const html = captureCardHtml(activeCardId);

                            // Save form data AND generate PDF in one request
                            const resp = await fetch(`/documents/${docId}/convert-html-to-pdf`, {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                                    'Accept': 'application/json',
                                },
                                body: JSON.stringify({ html: html, form_data: formData }),
                            });

                            if (!resp.ok) {
                                const err = await resp.json().catch(() => ({}));
                                throw new Error(err.error || 'Save failed');
                            }

                            // Brief success flash
                            saveFormBtn.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Saved!`;
                            saveFormBtn.style.background = 'linear-gradient(135deg, #047857, #059669)';
                            setTimeout(() => {
                                saveFormBtn.innerHTML = origHtml;
                                saveFormBtn.style.background = 'linear-gradient(135deg, #059669, #10b981)';
                                saveFormBtn.disabled = false;
                            }, 1500);
                        } catch (err) {
                            console.error('Form save error:', err);
                            alert('Error saving: ' + err.message);
                            saveFormBtn.innerHTML = origHtml;
                            saveFormBtn.disabled = false;
                        }
                    });
                }
            })();

            // ─── Guided Newsletter Builder ──────────────────────────────────
            (function guidedNewsletterInit() {
                const saveBtn = document.getElementById('gn-save-btn');
                if (!saveBtn) return;

                const banner = document.getElementById('gn-header-banner');
                const slug = document.getElementById('gn-template-slug')?.value || 'newsletter_classic';

                // Apply Modern Digest style
                if (slug === 'newsletter_modern') {
                    if (banner) {
                        banner.style.background = 'linear-gradient(90deg, #7c3aed, #2563eb)';
                    }
                    const s1Title = document.getElementById('gn-s1-title');
                    const s2Title = document.getElementById('gn-s2-title');
                    if (s1Title) s1Title.style.color = '#7c3aed';
                    if (s2Title) s2Title.style.color = '#2563eb';
                }

                async function generateNewsletter(btn, openInEditor) {
                    const html = captureCardHtml('guided-newsletter-card');
                    const formData = collectFormData('guided-newsletter-card');
                    const origHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin-icon"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg> Generating…`;

                    try {
                        const docId = @json($document->id);
                        const resp = await fetch(`/documents/${docId}/convert-html-to-pdf`, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                                'Accept': 'application/json',
                            },
                            body: JSON.stringify({ html: html, form_data: formData }),
                        });
                        if (!resp.ok) {
                            const err = await resp.json().catch(() => ({}));
                            throw new Error(err.error || 'Generation failed');
                        }
                        if (openInEditor) {
                            window.location.href = @json(route('documents.edit', $document));
                        } else {
                            window.open(`/documents/${docId}/file`, '_blank');
                        }
                        return;
                    } catch (err) {
                        console.error('Newsletter generation error:', err);
                        alert('Error: ' + err.message);
                    } finally {
                        btn.disabled = false;
                        btn.innerHTML = origHtml;
                    }
                }

                saveBtn.addEventListener('click', () => generateNewsletter(saveBtn, false));

                const gnOpenEditorBtn = document.getElementById('gn-open-editor-btn');
                if (gnOpenEditorBtn) {
                    gnOpenEditorBtn.addEventListener('click', () => generateNewsletter(gnOpenEditorBtn, true));
                }
            })();

            // ─── Guided NDA Builder ─────────────────────────────────────────
            (function guidedNdaInit() {
                const saveBtn = document.getElementById('gnda-save-btn');
                if (!saveBtn) return;

                async function generateNda(btn, openInEditor) {
                    const html = captureCardHtml('guided-nda-card');
                    const formData = collectFormData('guided-nda-card');
                    const origHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin-icon"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg> Generating…`;

                    try {
                        const docId = @json($document->id);
                        const resp = await fetch(`/documents/${docId}/convert-html-to-pdf`, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                                'Accept': 'application/json',
                            },
                            body: JSON.stringify({ html: html, form_data: formData }),
                        });
                        if (!resp.ok) {
                            const err = await resp.json().catch(() => ({}));
                            throw new Error(err.error || 'Generation failed');
                        }
                        if (openInEditor) {
                            window.location.href = @json(route('documents.edit', $document));
                        } else {
                            window.open(`/documents/${docId}/file`, '_blank');
                        }
                        return;
                    } catch (err) {
                        console.error('NDA generation error:', err);
                        alert('Error: ' + err.message);
                    } finally {
                        btn.disabled = false;
                        btn.innerHTML = origHtml;
                    }
                }

                saveBtn.addEventListener('click', () => generateNda(saveBtn, false));

                const gndaOpenEditorBtn = document.getElementById('gnda-open-editor-btn');
                if (gndaOpenEditorBtn) {
                    gndaOpenEditorBtn.addEventListener('click', () => generateNda(gndaOpenEditorBtn, true));
                }
            })();

            // ─── Guided Purchase Order Builder ──────────────────────────────
            (function guidedPoInit() {
                const lineItemsBody = document.getElementById('gpo-line-items-body');
                const addLineBtn = document.getElementById('gpo-add-line-item');
                const totalDisplay = document.getElementById('gpo-total-display');
                const saveBtn = document.getElementById('gpo-save-btn');

                if (!lineItemsBody || !saveBtn) return;

                let lineItemIndex = 0;

                function createPoLineRow(qty, desc, price) {
                    const tr = document.createElement('tr');
                    tr.style.borderBottom = '1px solid #f3f4f6';
                    tr.dataset.lineItem = 'true';
                    lineItemIndex++;
                    tr.innerHTML = `
                        <td style="padding:10px 14px;">
                            <input type="text" class="gpo-desc" value="${desc}" placeholder="Item description"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px;">
                            <input type="number" class="gpo-qty" value="${qty}" min="0" step="1"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; text-align:center; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px;">
                            <input type="number" class="gpo-unit-price" value="${price}" min="0" step="0.01"
                                   style="width:100%; border:1px solid #e5e7eb; border-radius:5px; padding:6px 8px; font-size:13px; text-align:right; outline:none; background:#fff; color:#1f2937;">
                        </td>
                        <td style="padding:10px 14px; text-align:right; font-size:14px; font-weight:500; color:#1f2937;" class="gpo-amount">
                            $0.00
                        </td>
                        <td style="padding:6px 4px; vertical-align:middle;">
                            <button type="button" class="gpo-remove-row" style="background:none; border:none; cursor:pointer; color:#9ca3af; font-size:18px; padding:4px;" title="Remove">
                                &times;
                            </button>
                        </td>
                    `;
                    tr.querySelector('.gpo-qty').addEventListener('input', recalcPoTotal);
                    tr.querySelector('.gpo-unit-price').addEventListener('input', recalcPoTotal);
                    tr.querySelector('.gpo-remove-row').addEventListener('click', () => { tr.remove(); recalcPoTotal(); });
                    return tr;
                }

                function recalcPoTotal() {
                    let total = 0;
                    lineItemsBody.querySelectorAll('tr[data-line-item]').forEach(tr => {
                        const qty = parseFloat(tr.querySelector('.gpo-qty').value) || 0;
                        const price = parseFloat(tr.querySelector('.gpo-unit-price').value) || 0;
                        const amount = qty * price;
                        tr.querySelector('.gpo-amount').textContent = '$' + amount.toFixed(2);
                        total += amount;
                    });
                    totalDisplay.textContent = '$' + total.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                }

                lineItemsBody.appendChild(createPoLineRow(1, 'Sample Item', 0));
                recalcPoTotal();

                addLineBtn.addEventListener('click', () => {
                    lineItemsBody.appendChild(createPoLineRow(1, '', 0));
                });

                async function generatePo(btn, openInEditor) {
                    const html = captureCardHtml('guided-po-card');
                    const formData = collectFormData('guided-po-card');
                    const origHtml = btn.innerHTML;
                    btn.disabled = true;
                    btn.innerHTML = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="spin-icon"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83"/></svg> Generating…`;

                    try {
                        const docId = @json($document->id);
                        const resp = await fetch(`/documents/${docId}/convert-html-to-pdf`, {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content,
                                'Accept': 'application/json',
                            },
                            body: JSON.stringify({ html: html, form_data: formData }),
                        });
                        if (!resp.ok) {
                            const err = await resp.json().catch(() => ({}));
                            throw new Error(err.error || 'Generation failed');
                        }
                        if (openInEditor) {
                            window.location.href = @json(route('documents.edit', $document));
                        } else {
                            window.open(`/documents/${docId}/file`, '_blank');
                        }
                        return;
                    } catch (err) {
                        console.error('Purchase Order generation error:', err);
                        alert('Error: ' + err.message);
                    } finally {
                        btn.disabled = false;
                        btn.innerHTML = origHtml;
                    }
                }

                saveBtn.addEventListener('click', () => generatePo(saveBtn, false));

                const gpoOpenEditorBtn = document.getElementById('gpo-open-editor-btn');
                if (gpoOpenEditorBtn) {
                    gpoOpenEditorBtn.addEventListener('click', () => generatePo(gpoOpenEditorBtn, true));
                }
            })();

            // ─── Restore Guided Template Data ──────────────────────────────
            (function() {
                const savedFormData = @json($formData ?? null);
                if (savedFormData && (typeof savedFormData === 'object') && Object.keys(savedFormData).length > 0) {
                    // Try to restore for all possible guided cards
                    ['guided-invoice-card', 'guided-newsletter-card', 'guided-nda-card', 'guided-po-card'].forEach(cardId => {
                        restoreFormData(cardId, savedFormData);
                    });
                }
            })();

            // ─── Flatpickr Datepickers ──────────────────────────────────────
            (function() {
                if (typeof flatpickr === 'undefined') return;

                const dateFields = [
                    { id: 'gi-invoice-date', format: 'm-d-Y' },
                    { id: 'gi-due-date',     format: 'm-d-Y' },
                    { id: 'gn-date',         format: 'F Y', noDay: true },
                    { id: 'gnda-date',        format: 'F j, Y' },
                    { id: 'gpo-date',         format: 'm-d-Y' },
                    { id: 'gpo-delivery-date', format: 'm-d-Y' },
                ];

                dateFields.forEach(({ id, format, noDay }) => {
                    const el = document.getElementById(id);
                    if (!el) return;

                    const opts = {
                        dateFormat: format,
                        allowInput: true,
                        disableMobile: true,
                        theme: 'dark',
                    };

                    // For month-year only pickers (newsletter)
                    if (noDay) {
                        opts.plugins = [];
                        // Use monthly view: show only months
                        opts.dateFormat = 'F Y';
                        opts.disableMobile = true;
                    }

                    flatpickr(el, opts);
                });
            })();

        </script>

        <!-- Rotation Warning Modal -->
        <div class="modal" id="rotation-warning-modal" aria-hidden="true" style="display: none; z-index: 10000; position: fixed; top: 0; left: 0; width: 100%; height: 100%; align-items: center; justify-content: center; background: rgba(0,0,0,0.5);">
            <div class="modal-card" style="position: relative; background: var(--panel); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; width: 100%; max-width: 400px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); display: flex; flex-direction: column;">
                <div class="modal-header" style="display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; border-bottom: 1px solid rgba(255,255,255,0.08);">
                    <h3 class="modal-title" style="margin: 0; font-size: 18px; font-weight: 600;">Page Rotated</h3>
                    <button class="modal-close" type="button" id="rotation-warning-close" style="background: none; border: none; color: var(--muted); font-size: 24px; cursor: pointer; line-height: 1;">×</button>
                </div>
                <div class="modal-body" style="padding: 20px;">
                    <p style="margin: 0 0 10px;">The overlay editor cannot be activated while the page is rotated.</p>
                    <p style="margin: 0; font-size: 0.9em; color: var(--muted);">Please rotate the page back to 0° (orientation) or save the document to apply rotation permanently.</p>
                </div>
                <div class="modal-footer" style="padding: 16px 20px; border-top: 1px solid rgba(255,255,255,0.08); display: flex; justify-content: flex-end;">
                    <button class="btn btn-secondary" type="button" id="rotation-warning-ok" style="background: #4b5563; color: white; border: none; padding: 8px 16px; border-radius: 4px; cursor: pointer;">Okay</button>
                </div>
            </div>
        </div>

        <script>
            // Modal Logic for Rotation Warning
            const rotationModal = document.getElementById('rotation-warning-modal');
            const rotationCloseBtn = document.getElementById('rotation-warning-close');
            const rotationOkBtn = document.getElementById('rotation-warning-ok');

            function showRotationModal() {
                if (rotationModal) {
                    rotationModal.style.display = 'flex';
                }
            }

            function hideRotationModal() {
                if (rotationModal) {
                    rotationModal.style.display = 'none';
                }
            }

            if (rotationCloseBtn) rotationCloseBtn.addEventListener('click', hideRotationModal);
            if (rotationOkBtn) rotationOkBtn.addEventListener('click', hideRotationModal);
            // Close on outside click
            if (rotationModal) {
                rotationModal.addEventListener('click', (e) => {
                    if (e.target === rotationModal) hideRotationModal();
                });
            }
        </script>
        
        <!-- Bootstrap 5.3.3 JS Bundle -->
        <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" integrity="sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz" crossorigin="anonymous"></script>

    </body>
</html>
